import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum UserRole {
  ADMIN = 'ADMIN',
  SALES = 'SALES',
  OPERATIONS = 'OPERATIONS'
}

export enum TripStatus {
  LEAD = 'Lead',
  QUOTED = 'Quoted',
  BOOKED = 'Booked',
  COMPLETED = 'Completed',
  CANCELLED = 'Cancelled'
}

export enum TripType {
  HONEYMOON = 'Honeymoon',
  FAMILY = 'Family',
  GROUP = 'Group',
  CORPORATE = 'Corporate'
}

export enum HotelCategory {
  BUDGET = 'Budget',
  DELUXE = 'Deluxe',
  LUXURY = 'Luxury',
  HOUSEBOAT = 'Houseboat'
}

export interface Hotel {
  id: string;
  name: string;
  location: string;
  category: HotelCategory;
  ratePerNight: number;
  contact: string;
}

export interface Vehicle {
  id: string;
  type: string;
  capacity: number;
  ratePerDay: number;
}

export interface Activity {
  id: string;
  name: string;
  costPerPax: number;
  description: string;
}

export interface AddOn {
  id: string;
  name: string;
  cost: number;
  isPerPax: boolean;
}

export interface ItineraryDay {
  id: string;
  dayNumber: number;
  title: string;
  hotelId?: string;
  vehicleId?: string;
  activityIds: string[];
  clientNotes: string;
  internalNotes: string;
}

export interface Client {
  name: string;
  phone: string;
  email: string;
  source: string;
}

export interface Trip {
  id: string;
  client: Client;
  tripName: string;
  tripType: TripType;
  startDate: string;
  endDate: string;
  pax: number;
  budgetRange: string;
  assignedSalesperson: string;
  status: TripStatus;
  itinerary: ItineraryDay[];
  marginPercentage: number;
  addOnIds: string[];
}

export interface DashboardStats {
  activeLeads: number;
  totalRevenue: number;
  bookedTrips: number;
  conversionRate: number;
}

import { GoogleGenAI } from "@google/genai";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export async function generateDayDescription(title: string, activities: string[]): Promise<string> {
  try {
    const prompt = `Act as a luxury travel consultant for Escape Theory, a travel agency in Kashmir.
    Write a 3-4 sentence poetic and inviting itinerary description for a day titled "${title}".
    The activities planned are: ${activities.join(', ')}.
    Keep the tone professional yet enchanting, suitable for a high-end client.`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });

    return response.text || "No description generated.";
  } catch (error) {
    console.error("Gemini Error:", error);
    return "Error generating AI description. Please write manually.";
  }
}

export async function suggestKashmirItinerary(tripType: string, days: number): Promise<string> {
  try {
    const prompt = `Create a brief bullet-point summary for a ${days}-day ${tripType} trip to Kashmir.
    Include must-visit spots in Srinagar, Gulmarg, and Pahalgam. Focus on unique experiences.`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });

    return response.text || "No suggestions available.";
  } catch (error) {
    console.error("Gemini Error:", error);
    return "Failed to fetch suggestions.";
  }
}

import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Plus, Search, Filter, MoreVertical, Calendar, User, ArrowRight } from 'lucide-react';
import { MOCK_TRIPS } from '../constants';
import { TripStatus, TripType } from '../types';

const TripList: React.FC = () => {
  const navigate = useNavigate();
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState('All');

  const filteredTrips = MOCK_TRIPS.filter(trip => {
    const matchesSearch = trip.client.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                         trip.tripName.toLowerCase().includes(searchTerm.toLowerCase());
    const matchesStatus = statusFilter === 'All' || trip.status === statusFilter;
    return matchesSearch && matchesStatus;
  });

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div className="flex-1 max-w-md relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
          <input 
            type="text" 
            placeholder="Search clients or trips..." 
            className="w-full pl-10 pr-4 py-2 bg-white border border-slate-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent transition-all"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>

        <div className="flex items-center gap-3">
          <div className="flex items-center gap-2 bg-white px-3 py-2 border border-slate-200 rounded-lg">
            <Filter size={16} className="text-slate-400" />
            <select 
              className="bg-transparent border-none text-sm font-medium text-slate-700 focus:outline-none"
              value={statusFilter}
              onChange={(e) => setStatusFilter(e.target.value)}
            >
              <option value="All">All Statuses</option>
              {Object.values(TripStatus).map(status => (
                <option key={status} value={status}>{status}</option>
              ))}
            </select>
          </div>
          <button 
            onClick={() => navigate('/trips/new')}
            className="flex items-center gap-2 bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-lg font-bold transition-all shadow-sm"
          >
            <Plus size={18} />
            Create Trip
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
        {filteredTrips.map(trip => (
          <div 
            key={trip.id} 
            className="bg-white border border-slate-200 rounded-xl overflow-hidden hover:shadow-lg transition-all cursor-pointer flex flex-col group"
            onClick={() => navigate(`/trips/${trip.id}`)}
          >
            <div className="p-5 flex-1">
              <div className="flex justify-between items-start mb-4">
                <span className={`px-2.5 py-1 rounded text-[10px] font-black uppercase tracking-widest ${
                  trip.tripType === TripType.HONEYMOON ? 'bg-pink-100 text-pink-700' :
                  trip.tripType === TripType.FAMILY ? 'bg-emerald-100 text-emerald-700' :
                  'bg-slate-100 text-slate-700'
                }`}>
                  {trip.tripType}
                </span>
                <span className={`px-2.5 py-1 rounded text-[10px] font-black uppercase tracking-widest ${
                  trip.status === TripStatus.BOOKED ? 'bg-green-100 text-green-700' :
                  trip.status === TripStatus.QUOTED ? 'bg-blue-100 text-blue-700' :
                  'bg-orange-100 text-orange-700'
                }`}>
                  {trip.status}
                </span>
              </div>

              <h3 className="text-xl font-bold text-slate-800 mb-1 group-hover:text-blue-600 transition-colors">
                {trip.tripName}
              </h3>
              <p className="text-slate-500 text-sm mb-4">Client: {trip.client.name}</p>

              <div className="space-y-3">
                <div className="flex items-center gap-3 text-slate-600">
                  <Calendar size={16} className="text-slate-400" />
                  <span className="text-sm font-medium">{trip.startDate} - {trip.endDate}</span>
                </div>
                <div className="flex items-center gap-3 text-slate-600">
                  <User size={16} className="text-slate-400" />
                  <span className="text-sm font-medium">{trip.pax} Passengers • {trip.budgetRange}</span>
                </div>
              </div>
            </div>

            <div className="px-5 py-4 bg-slate-50 border-t border-slate-100 flex items-center justify-between">
              <div className="flex -space-x-2">
                <img src={`https://picsum.photos/seed/${trip.id}/32/32`} className="w-8 h-8 rounded-full border-2 border-white shadow-sm" alt="agent" />
                <div className="w-8 h-8 rounded-full bg-blue-100 border-2 border-white flex items-center justify-center text-[10px] font-bold text-blue-600">
                  {trip.assignedSalesperson.split(' ').map(n => n[0]).join('')}
                </div>
              </div>
              <div className="flex items-center gap-1 text-blue-600 font-bold text-sm">
                Build Itinerary
                <ArrowRight size={14} />
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default TripList;

import React, { useState, useMemo, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { 
  Plus, 
  Trash2, 
  Save, 
  ChevronDown, 
  ChevronUp, 
  Copy, 
  Share2, 
  Calculator,
  Sparkles,
  ArrowLeft,
  CalendarDays,
  Hotel as HotelIcon,
  Car as CarIcon,
  Activity as ActivityIcon
} from 'lucide-react';
import { MOCK_TRIPS, HOTELS, VEHICLES, ACTIVITIES, ADD_ONS } from '../constants';
import { Trip, ItineraryDay, HotelCategory } from '../types';
import { generateDayDescription } from '../services/geminiService';

const TripBuilder: React.FC = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const [trip, setTrip] = useState<Trip | null>(null);
  const [activeDayIndex, setActiveDayIndex] = useState(0);
  const [isAiGenerating, setIsAiGenerating] = useState(false);

  useEffect(() => {
    const foundTrip = MOCK_TRIPS.find(t => t.id === id);
    if (foundTrip) setTrip({ ...foundTrip });
  }, [id]);

  const costs = useMemo(() => {
    if (!trip) return { total: 0, hotel: 0, vehicle: 0, activity: 0, addOns: 0, margin: 0, sellingPrice: 0 };

    let hotelCost = 0;
    let vehicleCost = 0;
    let activityCost = 0;
    let addOnsCost = 0;

    trip.itinerary.forEach(day => {
      if (day.hotelId) {
        const hotel = HOTELS.find(h => h.id === day.hotelId);
        if (hotel) hotelCost += hotel.ratePerNight;
      }
      if (day.vehicleId) {
        const vehicle = VEHICLES.find(v => v.id === day.vehicleId);
        if (vehicle) vehicleCost += vehicle.ratePerDay;
      }
      day.activityIds.forEach(aid => {
        const act = ACTIVITIES.find(a => a.id === aid);
        if (act) activityCost += act.costPerPax * trip.pax;
      });
    });

    trip.addOnIds.forEach(aoId => {
      const ao = ADD_ONS.find(a => a.id === aoId);
      if (ao) {
        addOnsCost += ao.isPerPax ? ao.cost * trip.pax : ao.cost;
      }
    });

    const subtotal = hotelCost + vehicleCost + activityCost + addOnsCost;
    const margin = subtotal * (trip.marginPercentage / 100);
    const sellingPrice = subtotal + margin;

    return { 
      total: subtotal, 
      hotel: hotelCost, 
      vehicle: vehicleCost, 
      activity: activityCost, 
      addOns: addOnsCost, 
      margin, 
      sellingPrice 
    };
  }, [trip]);

  if (!trip) return <div>Loading...</div>;

  const handleAddDay = () => {
    const newDay: ItineraryDay = {
      id: `d-${Date.now()}`,
      dayNumber: trip.itinerary.length + 1,
      title: 'New Day Plan',
      hotelId: '',
      vehicleId: '',
      activityIds: [],
      clientNotes: '',
      internalNotes: ''
    };
    setTrip({ ...trip, itinerary: [...trip.itinerary, newDay] });
    setActiveDayIndex(trip.itinerary.length);
  };

  const updateDay = (index: number, updates: Partial<ItineraryDay>) => {
    const newItinerary = [...trip.itinerary];
    newItinerary[index] = { ...newItinerary[index], ...updates };
    setTrip({ ...trip, itinerary: newItinerary });
  };

  const handleAiDescription = async (index: number) => {
    const day = trip.itinerary[index];
    if (!day.title) return;

    setIsAiGenerating(true);
    const activities = day.activityIds.map(aid => ACTIVITIES.find(a => a.id === aid)?.name || '');
    const description = await generateDayDescription(day.title, activities);
    updateDay(index, { clientNotes: description });
    setIsAiGenerating(false);
  };

  return (
    <div className="flex flex-col h-full space-y-6">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-4">
          <button onClick={() => navigate('/trips')} className="p-2 hover:bg-white rounded-lg transition-colors border border-transparent hover:border-slate-200">
            <ArrowLeft size={20} className="text-slate-600" />
          </button>
          <div>
            <h1 className="text-2xl font-bold text-slate-900">{trip.tripName}</h1>
            <p className="text-slate-500 text-sm">Building itinerary for {trip.client.name} • {trip.pax} Pax</p>
          </div>
        </div>
        <div className="flex items-center gap-3">
          <button className="flex items-center gap-2 px-4 py-2 border border-slate-200 rounded-lg bg-white text-slate-700 font-bold hover:bg-slate-50 transition-all">
            <Share2 size={18} />
            Share with Client
          </button>
          <button className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg font-bold hover:bg-blue-700 transition-all shadow-md">
            <Save size={18} />
            Save Trip
          </button>
        </div>
      </div>

      <div className="flex flex-1 gap-6 overflow-hidden">
        {/* Days List Side Panel */}
        <div className="w-80 bg-white border border-slate-200 rounded-xl flex flex-col overflow-hidden">
          <div className="p-4 border-b border-slate-100 flex items-center justify-between">
            <h3 className="font-bold text-slate-800 flex items-center gap-2">
              <CalendarDays size={18} className="text-blue-600" />
              Trip Days
            </h3>
            <span className="text-xs font-bold text-slate-400">{trip.itinerary.length} Days</span>
          </div>
          <div className="flex-1 overflow-y-auto p-4 space-y-3">
            {trip.itinerary.map((day, idx) => (
              <button
                key={day.id}
                onClick={() => setActiveDayIndex(idx)}
                className={`w-full text-left p-3 rounded-lg border transition-all ${
                  activeDayIndex === idx 
                    ? 'border-blue-600 bg-blue-50 shadow-sm' 
                    : 'border-slate-100 hover:border-slate-300'
                }`}
              >
                <div className="flex justify-between items-center">
                  <span className="text-[10px] font-black uppercase text-blue-600">Day {day.dayNumber}</span>
                  <div className="flex gap-2 opacity-0 group-hover:opacity-100">
                    <Copy size={12} className="text-slate-400 hover:text-blue-600" />
                    <Trash2 size={12} className="text-slate-400 hover:text-red-600" />
                  </div>
                </div>
                <h4 className={`font-semibold truncate ${activeDayIndex === idx ? 'text-blue-900' : 'text-slate-700'}`}>
                  {day.title || 'Untitled Day'}
                </h4>
              </button>
            ))}
            <button 
              onClick={handleAddDay}
              className="w-full py-3 border-2 border-dashed border-slate-200 rounded-lg text-slate-400 font-bold hover:border-blue-400 hover:text-blue-500 transition-all flex items-center justify-center gap-2"
            >
              <Plus size={18} />
              Add Next Day
            </button>
          </div>
        </div>

        {/* Day Editor Content */}
        <div className="flex-1 overflow-y-auto space-y-6 pb-20 pr-2">
          {trip.itinerary[activeDayIndex] ? (
            <div className="bg-white border border-slate-200 rounded-xl shadow-sm p-8 space-y-8 animate-in fade-in slide-in-from-right-4 duration-200">
              <div className="flex flex-col gap-2">
                <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">Day Title</label>
                <input 
                  type="text" 
                  value={trip.itinerary[activeDayIndex].title}
                  onChange={(e) => updateDay(activeDayIndex, { title: e.target.value })}
                  className="text-3xl font-bold text-slate-800 border-none p-0 focus:ring-0 placeholder:text-slate-200 w-full"
                  placeholder="e.g., Arrival in Srinagar & Shikara Ride"
                />
              </div>

              <div className="grid grid-cols-2 gap-8">
                <div className="space-y-4">
                  <div className="flex items-center justify-between">
                    <label className="text-sm font-bold text-slate-700 flex items-center gap-2">
                      <HotelIcon size={16} className="text-blue-500" />
                      Accommodation
                    </label>
                  </div>
                  <select 
                    value={trip.itinerary[activeDayIndex].hotelId}
                    onChange={(e) => updateDay(activeDayIndex, { hotelId: e.target.value })}
                    className="w-full p-3 bg-slate-50 border border-slate-200 rounded-lg text-sm font-medium focus:ring-2 focus:ring-blue-500"
                  >
                    <option value="">Select a Hotel</option>
                    {HOTELS.map(h => <option key={h.id} value={h.id}>{h.name} ({h.location})</option>)}
                  </select>
                </div>

                <div className="space-y-4">
                  <label className="text-sm font-bold text-slate-700 flex items-center gap-2">
                    <CarIcon size={16} className="text-blue-500" />
                    Transport
                  </label>
                  <select 
                    value={trip.itinerary[activeDayIndex].vehicleId}
                    onChange={(e) => updateDay(activeDayIndex, { vehicleId: e.target.value })}
                    className="w-full p-3 bg-slate-50 border border-slate-200 rounded-lg text-sm font-medium focus:ring-2 focus:ring-blue-500"
                  >
                    <option value="">Select Vehicle</option>
                    {VEHICLES.map(v => <option key={v.id} value={v.id}>{v.type}</option>)}
                  </select>
                </div>
              </div>

              <div className="space-y-4">
                <label className="text-sm font-bold text-slate-700 flex items-center gap-2">
                  <ActivityIcon size={16} className="text-blue-500" />
                  Activities
                </label>
                <div className="grid grid-cols-2 md:grid-cols-3 gap-3">
                  {ACTIVITIES.map(act => (
                    <button
                      key={act.id}
                      onClick={() => {
                        const current = trip.itinerary[activeDayIndex].activityIds;
                        const next = current.includes(act.id) 
                          ? current.filter(id => id !== act.id) 
                          : [...current, act.id];
                        updateDay(activeDayIndex, { activityIds: next });
                      }}
                      className={`p-3 rounded-lg border text-xs font-bold transition-all text-left ${
                        trip.itinerary[activeDayIndex].activityIds.includes(act.id)
                          ? 'bg-blue-600 text-white border-blue-600'
                          : 'bg-white text-slate-600 border-slate-200 hover:bg-slate-50'
                      }`}
                    >
                      {act.name}
                    </button>
                  ))}
                </div>
              </div>

              <div className="space-y-4">
                <div className="flex items-center justify-between">
                  <label className="text-sm font-bold text-slate-700">Client Facing Description</label>
                  <button 
                    onClick={() => handleAiDescription(activeDayIndex)}
                    disabled={isAiGenerating}
                    className="flex items-center gap-2 text-xs font-black uppercase text-blue-600 bg-blue-50 px-3 py-1.5 rounded-full hover:bg-blue-100 transition-all disabled:opacity-50"
                  >
                    <Sparkles size={12} />
                    {isAiGenerating ? 'Generating...' : 'AI Enhance'}
                  </button>
                </div>
                <textarea 
                  rows={4}
                  value={trip.itinerary[activeDayIndex].clientNotes}
                  onChange={(e) => updateDay(activeDayIndex, { clientNotes: e.target.value })}
                  placeholder="Describe the day for the client..."
                  className="w-full p-4 bg-slate-50 border border-slate-200 rounded-xl text-sm leading-relaxed focus:ring-2 focus:ring-blue-500"
                />
              </div>

              <div className="space-y-4">
                <label className="text-sm font-bold text-slate-500">Internal Operational Notes (Hidden from Client)</label>
                <textarea 
                  rows={2}
                  value={trip.itinerary[activeDayIndex].internalNotes}
                  onChange={(e) => updateDay(activeDayIndex, { internalNotes: e.target.value })}
                  placeholder="Add notes for operations team..."
                  className="w-full p-4 bg-amber-50/30 border border-amber-100 rounded-xl text-sm italic text-slate-600 focus:ring-1 focus:ring-amber-200"
                />
              </div>
            </div>
          ) : (
            <div className="flex items-center justify-center h-64 bg-slate-100 border-2 border-dashed border-slate-200 rounded-xl">
              <p className="text-slate-400 font-bold">Select a day or create one to start building.</p>
            </div>
          )}
        </div>

        {/* Costing Engine Sticky Panel */}
        <div className="w-80 bg-slate-900 text-white rounded-xl shadow-2xl p-6 flex flex-col h-fit sticky top-0">
          <div className="flex items-center gap-2 mb-6 border-b border-slate-800 pb-4">
            <Calculator className="text-blue-400" size={20} />
            <h3 className="font-bold text-lg">Costing Engine</h3>
          </div>

          <div className="space-y-4 flex-1">
            <div className="flex justify-between items-center text-sm">
              <span className="text-slate-400">Hotel Cost</span>
              <span className="font-bold">₹ {costs.hotel.toLocaleString()}</span>
            </div>
            <div className="flex justify-between items-center text-sm">
              <span className="text-slate-400">Vehicle Cost</span>
              <span className="font-bold">₹ {costs.vehicle.toLocaleString()}</span>
            </div>
            <div className="flex justify-between items-center text-sm">
              <span className="text-slate-400">Activity Cost ({trip.pax} Pax)</span>
              <span className="font-bold">₹ {costs.activity.toLocaleString()}</span>
            </div>
            <div className="flex justify-between items-center text-sm">
              <span className="text-slate-400">Add-ons</span>
              <span className="font-bold">₹ {costs.addOns.toLocaleString()}</span>
            </div>
            <div className="pt-4 border-t border-slate-800">
              <div className="flex justify-between items-center text-xs uppercase font-black text-slate-500 tracking-widest mb-2">
                <span>Profit Margin</span>
                <input 
                  type="number" 
                  value={trip.marginPercentage}
                  onChange={(e) => setTrip({ ...trip, marginPercentage: Number(e.target.value) })}
                  className="w-12 bg-transparent border-none p-0 text-right text-blue-400 focus:ring-0 font-black"
                />
              </div>
              <div className="flex justify-between items-center font-bold text-emerald-400">
                <span>Total Margin ({trip.marginPercentage}%)</span>
                <span>₹ {costs.margin.toLocaleString()}</span>
              </div>
            </div>
          </div>

          <div className="mt-10 pt-6 border-t border-slate-800">
            <p className="text-[10px] uppercase font-black tracking-widest text-slate-500 mb-1">Final Selling Price</p>
            <h2 className="text-4xl font-black text-white">₹ {Math.round(costs.sellingPrice).toLocaleString()}</h2>
            <div className="mt-6 space-y-3">
              <button className="w-full bg-blue-600 py-3 rounded-lg font-bold hover:bg-blue-700 transition-all flex items-center justify-center gap-2">
                <Save size={18} />
                Save & Book
              </button>
              <button className="w-full border border-slate-700 py-3 rounded-lg font-bold text-slate-300 hover:text-white hover:bg-slate-800 transition-all">
                Download PDF Quotation
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default TripBuilder;

import React from 'react';
import { HashRouter as Router, Routes, Route } from 'react-router-dom';
import Layout from './components/Layout';
import Dashboard from './pages/Dashboard';
import TripList from './pages/TripList';
import TripBuilder from './pages/TripBuilder';

// Simple placeholder for other pages
