  Calculator,
  Sparkles,
  ArrowLeft,
  CalendarDays,
  Hotel as HotelIcon,
  Car as CarIcon,
  Activity as ActivityIcon,
  History,
  RotateCcw,
  Clock,
  FileText
} from 'lucide-react';
import { MOCK_TRIPS, HOTELS, VEHICLES, ACTIVITIES, ADD_ONS } from '../constants';
import { Trip, ItineraryDay, TripVersion } from '../types';
import { generateDayDescription, suggestNextDayTitle } from '../services/geminiService';

const TripBuilder: React.FC = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const [trip, setTrip] = useState<Trip | null>(null);
  const [activeDayIndex, setActiveDayIndex] = useState(0);
  const [isAiGenerating, setIsAiGenerating] = useState(false);
  const [showHistory, setShowHistory] = useState(false);

  useEffect(() => {
    const foundTrip = MOCK_TRIPS.find(t => t.id === id);
    if (foundTrip) setTrip({ ...foundTrip });
  }, [id]);

  const costs = useMemo(() => {
    if (!trip) return { total: 0, hotel: 0, vehicle: 0, activity: 0, addOns: 0, margin: 0, sellingPrice: 0 };

    let hotelCost = 0;
    let vehicleCost = 0;
    let activityCost = 0;
    let addOnsCost = 0;

    trip.itinerary.forEach(day => {
      if (day.hotelId) {
        const hotel = HOTELS.find(h => h.id === day.hotelId);
        if (hotel) hotelCost += hotel.ratePerNight;
      }
      if (day.vehicleId) {
        const vehicle = VEHICLES.find(v => v.id === day.vehicleId);
        if (vehicle) vehicleCost += vehicle.ratePerDay;
      }
      day.activityIds.forEach(aid => {
        const act = ACTIVITIES.find(a => a.id === aid);
        if (act) activityCost += act.costPerPax * trip.pax;
      });
    });

    trip.addOnIds.forEach(aoId => {
      const ao = ADD_ONS.find(a => a.id === aoId);
      if (ao) {
        addOnsCost += ao.isPerPax ? ao.cost * trip.pax : ao.cost;
      }
    });

    const subtotal = hotelCost + vehicleCost + activityCost + addOnsCost;
    const margin = subtotal * (trip.marginPercentage / 100);
    const sellingPrice = subtotal + margin;

    return { 
      total: subtotal, 
      hotel: hotelCost, 
      vehicle: vehicleCost, 
      activity: activityCost, 
      addOns: addOnsCost, 
      margin, 
      sellingPrice 
    };
  }, [trip]);

  if (!trip) return <div className="p-10 text-center font-bold text-slate-400">Loading Trip Details...</div>;

  const handleSaveTrip = () => {
    if (!trip) return;
    const newVersion: TripVersion = {
      id: `v-${Date.now()}`,
      timestamp: new Date().toISOString(),
      itinerary: JSON.parse(JSON.stringify(trip.itinerary)),
      marginPercentage: trip.marginPercentage,
      addOnIds: [...trip.addOnIds],
      label: `Update ${new Date().toLocaleTimeString()}`
    };
    setTrip({ ...trip, versions: [newVersion, ...(trip.versions || [])] });
    alert("Trip saved and new version created!");
  };

  const handleRestoreVersion = (version: TripVersion) => {
    if (window.confirm(`Restore to version from ${new Date(version.timestamp).toLocaleString()}?`)) {
      setTrip({
        ...trip,
        itinerary: JSON.parse(JSON.stringify(version.itinerary)),
        marginPercentage: version.marginPercentage,
        addOnIds: [...version.addOnIds]
      });
      setShowHistory(false);
      setActiveDayIndex(0);
    }
  };

  const handleAddDay = async () => {
    if (!trip) return;
    const nextDayNum = trip.itinerary.length + 1;
    const lastDay = trip.itinerary[trip.itinerary.length - 1];

    const newDay: ItineraryDay = {
      id: `d-${Date.now()}`,
      dayNumber: nextDayNum,
      title: `Day ${nextDayNum}: Suggesting Title...`,
      hotelId: lastDay?.hotelId || '', 
      vehicleId: lastDay?.vehicleId || '', 
      activityIds: [],
      clientNotes: '',
      internalNotes: ''
    };

    const newItinerary = [...trip.itinerary, newDay];
    setTrip({ ...trip, itinerary: newItinerary });
    setActiveDayIndex(newItinerary.length - 1);

    const suggestedTitle = await suggestNextDayTitle(
      lastDay?.title || 'Start of Trip', 
      trip.tripType, 
      nextDayNum
    );

    setTrip(prev => {
      if (!prev) return null;
      const updatedItinerary = [...prev.itinerary];
      const targetDay = updatedItinerary[updatedItinerary.length - 1];
      if (targetDay && targetDay.title.includes('Suggesting Title...')) {
        updatedItinerary[updatedItinerary.length - 1] = { ...targetDay, title: suggestedTitle };
      }
      return { ...prev, itinerary: updatedItinerary };
    });
  };

  const updateDay = (index: number, updates: Partial<ItineraryDay>) => {
    const newItinerary = [...trip.itinerary];
    newItinerary[index] = { ...newItinerary[index], ...updates };
    setTrip({ ...trip, itinerary: newItinerary });
  };

  const handleAiDescription = async (index: number) => {
    const day = trip.itinerary[index];
    if (!day.title) return;

    setIsAiGenerating(true);
    const activities = day.activityIds.map(aid => ACTIVITIES.find(a => a.id === aid)?.name || '');
    const description = await generateDayDescription(day.title, activities);
    updateDay(index, { clientNotes: description });
    setIsAiGenerating(false);
  };

  const printUrl = `#/trips/${trip.id}/print`;

  return (
    <div className="flex flex-col h-full space-y-6 relative">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-4">
          <button onClick={() => navigate('/trips')} className="p-2 hover:bg-white rounded-lg transition-colors border border-transparent hover:border-slate-200">
            <ArrowLeft size={20} className="text-slate-600" />
          </button>
          <div>
            <h1 className="text-2xl font-bold text-slate-900">{trip.tripName}</h1>
            <p className="text-slate-500 text-sm">Building itinerary for {trip.client.name} • {trip.pax} Pax</p>
          </div>
        </div>
        <div className="flex items-center gap-3">
          <button 
            onClick={() => setShowHistory(!showHistory)}
            className={`flex items-center gap-2 px-4 py-2 border rounded-lg font-bold transition-all ${showHistory ? 'bg-slate-800 text-white border-slate-800' : 'bg-white border-slate-200 text-slate-700 hover:bg-slate-50'}`}
          >
            <History size={18} />
            History
          </button>
          <a 
            href={printUrl}
            target="_blank"
            rel="noopener noreferrer"
            className="flex items-center gap-2 px-4 py-2 border border-slate-200 rounded-lg bg-white text-slate-700 font-bold hover:bg-slate-50 transition-all shadow-sm"
          >
            <FileText size={18} />
            Client PDF
          </a>
          <button 
            onClick={handleSaveTrip}
            className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg font-bold hover:bg-blue-700 transition-all shadow-md"
          >
            <Save size={18} />
            Save Changes
          </button>
        </div>
      </div>

      <div className="flex flex-1 gap-6 overflow-hidden relative">
        {/* Version History Sidebar Overlay */}
        {showHistory && (
          <div className="absolute inset-y-0 right-0 w-80 bg-white border-l border-slate-200 shadow-2xl z-20 flex flex-col animate-in slide-in-from-right duration-300">
            <div className="p-6 border-b border-slate-100 flex items-center justify-between">
              <h3 className="font-black text-slate-800 uppercase tracking-widest flex items-center gap-2">
                <Clock size={18} className="text-blue-600" />
                Trip Versions
              </h3>
              <button onClick={() => setShowHistory(false)} className="text-slate-400 hover:text-slate-600">
                <Plus size={20} className="rotate-45" />
              </button>
            </div>
            <div className="flex-1 overflow-y-auto p-4 space-y-4">
              {trip.versions?.length ? trip.versions.map((v) => (
                <div key={v.id} className="p-4 border border-slate-100 rounded-xl hover:bg-slate-50 transition-all group">
                  <div className="flex justify-between items-start mb-2">
                    <span className="text-xs font-bold text-blue-600">{v.label}</span>
                    <button 
                      onClick={() => handleRestoreVersion(v)}
                      className="text-xs bg-slate-200 px-2 py-1 rounded font-bold opacity-0 group-hover:opacity-100 transition-all hover:bg-blue-600 hover:text-white flex items-center gap-1"
                    >
                      <RotateCcw size={10} /> Restore
                    </button>
                  </div>
                  <p className="text-[10px] text-slate-400 font-medium mb-2">{new Date(v.timestamp).toLocaleString()}</p>
                  <div className="flex gap-4 text-[10px] font-black uppercase text-slate-500">
                    <span>{v.itinerary.length} Days</span>
                    <span>{v.marginPercentage}% Margin</span>
                  </div>
                </div>
              )) : (
                <div className="text-center py-10">
                  <p className="text-slate-400 text-sm italic">No past versions found.</p>
                </div>
              )}
            </div>
          </div>
        )}

        {/* Days List Side Panel */}
        <div className="w-80 bg-white border border-slate-200 rounded-xl flex flex-col overflow-hidden">
          <div className="p-4 border-b border-slate-100 flex items-center justify-between">
            <h3 className="font-bold text-slate-800 flex items-center gap-2">
              <CalendarDays size={18} className="text-blue-600" />
              Trip Days
            </h3>
            <span className="text-xs font-bold text-slate-400">{trip.itinerary.length} Days</span>
          </div>
          <div className="flex-1 overflow-y-auto p-4 space-y-3">
            {trip.itinerary.map((day, idx) => (
              <button
                key={day.id}
                onClick={() => setActiveDayIndex(idx)}
                className={`w-full text-left p-3 rounded-lg border transition-all ${
                  activeDayIndex === idx 
                    ? 'border-blue-600 bg-blue-50 shadow-sm' 
                    : 'border-slate-100 hover:border-slate-300'
                }`}
              >
                <div className="flex justify-between items-center">
                  <span className="text-[10px] font-black uppercase text-blue-600">Day {day.dayNumber}</span>
                  <div className="flex gap-2 opacity-0 group-hover:opacity-100">
                    <Copy size={12} className="text-slate-400 hover:text-blue-600" />
                    <Trash2 size={12} className="text-slate-400 hover:text-red-600" />
                  </div>
                </div>
                <h4 className={`font-semibold truncate ${activeDayIndex === idx ? 'text-blue-900' : 'text-slate-700'}`}>
                  {day.title || 'Untitled Day'}
                </h4>
              </button>
            ))}
            <button 
              onClick={handleAddDay}
              className="w-full py-3 border-2 border-dashed border-slate-200 rounded-lg text-slate-400 font-bold hover:border-blue-400 hover:text-blue-500 transition-all flex items-center justify-center gap-2"
            >
              <Plus size={18} />
              Add Next Day
            </button>
          </div>
        </div>

        {/* Day Editor Content */}
        <div className="flex-1 overflow-y-auto space-y-6 pb-20 pr-2">
          {trip.itinerary[activeDayIndex] ? (
            <div className="bg-white border border-slate-200 rounded-xl shadow-sm p-8 space-y-8 animate-in fade-in slide-in-from-right-4 duration-200">
              <div className="flex flex-col gap-2">
                <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">Day Title</label>
                <input 
                  type="text" 
                  value={trip.itinerary[activeDayIndex].title}
                  onChange={(e) => updateDay(activeDayIndex, { title: e.target.value })}
                  className="text-3xl font-bold text-slate-900 border-none p-0 focus:ring-0 placeholder:text-slate-300 w-full bg-transparent"
                  placeholder="e.g., Arrival in Srinagar & Shikara Ride"
                />
              </div>

              <div className="grid grid-cols-2 gap-8">
                <div className="space-y-4">
                  <div className="flex items-center justify-between">
                    <label className="text-sm font-bold text-slate-700 flex items-center gap-2">
                      <HotelIcon size={16} className="text-blue-500" />
                      Accommodation
                    </label>
                  </div>
                  <select 
                    value={trip.itinerary[activeDayIndex].hotelId}
                    onChange={(e) => updateDay(activeDayIndex, { hotelId: e.target.value })}
                    className="w-full p-3 bg-slate-50 border border-slate-200 rounded-lg text-sm font-medium focus:ring-2 focus:ring-blue-500 text-slate-900"
                  >
                    <option value="">Select a Hotel</option>
                    {HOTELS.map(h => <option key={h.id} value={h.id}>{h.name} ({h.location})</option>)}
                  </select>
                </div>

                <div className="space-y-4">
                  <label className="text-sm font-bold text-slate-700 flex items-center gap-2">
                    <CarIcon size={16} className="text-blue-500" />
                    Transport
                  </label>
                  <select 
                    value={trip.itinerary[activeDayIndex].vehicleId}
                    onChange={(e) => updateDay(activeDayIndex, { vehicleId: e.target.value })}
                    className="w-full p-3 bg-slate-50 border border-slate-200 rounded-lg text-sm font-medium focus:ring-2 focus:ring-blue-500 text-slate-900"
                  >
                    <option value="">Select Vehicle</option>
                    {VEHICLES.map(v => <option key={v.id} value={v.id}>{v.type}</option>)}
                  </select>
                </div>
              </div>

              <div className="space-y-4">
                <label className="text-sm font-bold text-slate-700 flex items-center gap-2">
                  <ActivityIcon size={16} className="text-blue-500" />
                  Activities
                </label>
                <div className="grid grid-cols-2 md:grid-cols-3 gap-3">
                  {ACTIVITIES.map(act => (
                    <button
                      key={act.id}
                      onClick={() => {
                        const current = trip.itinerary[activeDayIndex].activityIds;
                        const next = current.includes(act.id) 
                          ? current.filter(id => id !== act.id) 
                          : [...current, act.id];
                        updateDay(activeDayIndex, { activityIds: next });
                      }}
                      className={`p-3 rounded-lg border text-xs font-bold transition-all text-left ${
                        trip.itinerary[activeDayIndex].activityIds.includes(act.id)
                          ? 'bg-blue-600 text-white border-blue-600'
                          : 'bg-white text-slate-600 border-slate-200 hover:bg-slate-50'
                      }`}
                    >
                      {act.name}
                    </button>
                  ))}
                </div>
              </div>

              <div className="space-y-4">
                <div className="flex items-center justify-between">
                  <label className="text-sm font-bold text-slate-700">Client Facing Description</label>
                  <button 
                    onClick={() => handleAiDescription(activeDayIndex)}
                    disabled={isAiGenerating}
                    className="flex items-center gap-2 text-xs font-black uppercase text-blue-600 bg-blue-50 px-3 py-1.5 rounded-full hover:bg-blue-100 transition-all disabled:opacity-50"
                  >
                    <Sparkles size={12} />
                    {isAiGenerating ? 'Generating...' : 'AI Enhance'}
                  </button>
                </div>
                <textarea 
                  rows={4}
                  value={trip.itinerary[activeDayIndex].clientNotes}
                  onChange={(e) => updateDay(activeDayIndex, { clientNotes: e.target.value })}
                  placeholder="Describe the day for the client..."
                  className="w-full p-4 bg-slate-50 border border-slate-200 rounded-xl text-sm leading-relaxed focus:ring-2 focus:ring-blue-500 text-slate-900 placeholder:text-slate-400"
                />
              </div>

              <div className="space-y-4">
                <label className="text-sm font-bold text-slate-500">Internal Operational Notes</label>
                <textarea 
                  rows={2}
                  value={trip.itinerary[activeDayIndex].internalNotes}
                  onChange={(e) => updateDay(activeDayIndex, { internalNotes: e.target.value })}
                  placeholder="Add notes for operations team..."
                  className="w-full p-4 bg-amber-50/30 border border-amber-100 rounded-xl text-sm italic text-slate-800 focus:ring-1 focus:ring-amber-200 placeholder:text-slate-400"
                />
              </div>
            </div>
          ) : (
            <div className="flex items-center justify-center h-64 bg-slate-100 border-2 border-dashed border-slate-200 rounded-xl">
              <p className="text-slate-400 font-bold">Select a day or create one to start building.</p>
            </div>
          )}
        </div>

        {/* Costing Engine Sticky Panel */}
        <div className="w-80 bg-slate-900 text-white rounded-xl shadow-2xl p-6 flex flex-col h-fit sticky top-0">
          <div className="flex items-center gap-2 mb-6 border-b border-slate-800 pb-4">
            <Calculator className="text-blue-400" size={20} />
            <h3 className="font-bold text-lg">Costing Engine</h3>
          </div>

          <div className="space-y-4 flex-1">
            <div className="flex justify-between items-center text-sm">
              <span className="text-slate-400">Hotel Cost</span>
              <span className="font-bold">₹ {costs.hotel.toLocaleString()}</span>
            </div>
            <div className="flex justify-between items-center text-sm">
              <span className="text-slate-400">Vehicle Cost</span>
              <span className="font-bold">₹ {costs.vehicle.toLocaleString()}</span>
            </div>
            <div className="flex justify-between items-center text-sm">
              <span className="text-slate-400">Activity Cost ({trip.pax} Pax)</span>
              <span className="font-bold">₹ {costs.activity.toLocaleString()}</span>
            </div>
            <div className="flex justify-between items-center text-sm">
              <span className="text-slate-400">Add-ons</span>
              <span className="font-bold">₹ {costs.addOns.toLocaleString()}</span>
            </div>
            <div className="pt-4 border-t border-slate-800">
              <div className="flex justify-between items-center text-xs uppercase font-black text-slate-500 tracking-widest mb-2">
                <span>Profit Margin</span>
                <input 
                  type="number" 
                  value={trip.marginPercentage}
                  onChange={(e) => setTrip({ ...trip, marginPercentage: Number(e.target.value) })}
                  className="w-12 bg-transparent border-none p-0 text-right text-blue-400 focus:ring-0 font-black"
                />
              </div>
              <div className="flex justify-between items-center font-bold text-emerald-400">
                <span>Total Margin ({trip.marginPercentage}%)</span>
                <span>₹ {costs.margin.toLocaleString()}</span>
              </div>
            </div>
          </div>

          <div className="mt-10 pt-6 border-t border-slate-800">
            <p className="text-[10px] uppercase font-black tracking-widest text-slate-500 mb-1">Final Selling Price</p>
            <h2 className="text-4xl font-black text-white">₹ {Math.round(costs.sellingPrice).toLocaleString()}</h2>
            <div className="mt-6 space-y-3">
              <button onClick={handleSaveTrip} className="w-full bg-blue-600 py-3 rounded-lg font-bold hover:bg-blue-700 transition-all flex items-center justify-center gap-2">
                <Save size={18} />
                Save & Book
              </button>
              <a 
                href={printUrl}
                target="_blank"
                rel="noopener noreferrer"
                className="w-full border border-slate-700 py-3 rounded-lg font-bold text-slate-300 hover:text-white hover:bg-slate-800 transition-all flex items-center justify-center gap-2"
              >
                <FileText size={18} />
                Generate Client PDF
              </a>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default TripBuilder;

import React from 'react';
import { HashRouter as Router, Routes, Route, useLocation } from 'react-router-dom';
import Layout from './components/Layout';
import Dashboard from './pages/Dashboard';
import TripList from './pages/TripList';
import TripBuilder from './pages/TripBuilder';
import Hotels from './pages/Hotels';
import Vehicles from './pages/Vehicles';
import Activities from './pages/Activities';
import Templates from './pages/Templates';
import Settings from './pages/Settings';
import NewTrip from './pages/NewTrip';
import ClientItinerary from './pages/ClientItinerary';

const AppContent: React.FC = () => {
  const location = useLocation();
  // Using include to be more robust against different path representations in preview
  const isPrintView = location.pathname.includes('/print');

  if (isPrintView) {
    return (
      <Routes>
        <Route path="/trips/:id/print" element={<ClientItinerary />} />
        {/* Fallback for print routes that might miss the exact pattern */}
        <Route path="*" element={<ClientItinerary />} />
      </Routes>
    );
  }

  return (
    <Layout>
      <Routes>
        <Route path="/" element={<Dashboard />} />
        <Route path="/trips" element={<TripList />} />
        <Route path="/trips/new" element={<NewTrip />} />
        <Route path="/trips/:id" element={<TripBuilder />} />
        <Route path="/trips/:id/print" element={<ClientItinerary />} />
        <Route path="/hotels" element={<Hotels />} />
        <Route path="/vehicles" element={<Vehicles />} />
        <Route path="/activities" element={<Activities />} />
        <Route path="/templates" element={<Templates />} />
        <Route path="/settings" element={<Settings />} />
      </Routes>
    </Layout>
  );
};

const App: React.FC = () => {
  return (
    <Router>
      <AppContent />
    </Router>
  );
};

export default App;

import React, { useEffect, useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { Mail, Phone, MapPin, Calendar, Users, CheckCircle2, XCircle, Info, X } from 'lucide-react';
import { MOCK_TRIPS, BRAND_CONFIG, HOTELS, VEHICLES, ACTIVITIES } from '../constants';
import { Trip, HotelCategory } from '../types';

const ClientItinerary: React.FC = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const [trip, setTrip] = useState<Trip | null>(null);

  useEffect(() => {
    const foundTrip = MOCK_TRIPS.find(t => t.id === id);
    if (foundTrip) setTrip(foundTrip);

    // Auto-trigger print dialog after a delay to ensure styles and images load
    const timer = setTimeout(() => {
      window.print();
    }, 1200);

    return () => clearTimeout(timer);
  }, [id]);

  if (!trip) return (
    <div className="p-20 text-center font-bold text-slate-400">
      <p className="mb-4">Itinerary data is being synchronized...</p>
      <button 
        onClick={() => navigate('/')} 
        className="px-4 py-2 bg-blue-600 text-white rounded-lg text-sm"
      >
        Return to Dashboard
      </button>
    </div>
  );

  return (
    <div className="bg-white min-h-screen max-w-[210mm] mx-auto p-[15mm] text-slate-900 print:p-0 relative">
      {/* Non-print controls */}
      <div className="no-print fixed top-4 right-4 flex gap-2">
        <button 
          onClick={() => window.print()}
          className="bg-blue-600 text-white px-4 py-2 rounded-lg font-bold shadow-lg hover:bg-blue-700 transition-all text-sm"
        >
          Print Again
        </button>
        <button 
          onClick={() => window.close()}
          className="bg-slate-800 text-white p-2 rounded-lg font-bold shadow-lg hover:bg-slate-900 transition-all text-sm"
          title="Close Tab"
        >
          <X size={20} />
        </button>
      </div>

      {/* Branded Header */}
      <header className="flex justify-between items-start border-b-2 border-slate-100 pb-8 mb-10">
        <div className="flex items-center gap-4">
          <img src={BRAND_CONFIG.logo} alt="Logo" className="w-16 h-16" />
          <div>
            <h1 className="text-3xl font-black text-blue-600 tracking-tight">{BRAND_CONFIG.name}</h1>
            <p className="text-slate-500 font-bold text-xs uppercase tracking-widest">{BRAND_CONFIG.tagline}</p>
          </div>
        </div>
        <div className="text-right text-xs space-y-1 text-slate-500 font-medium">
          <div className="flex items-center justify-end gap-2">
            {BRAND_CONFIG.email} <Mail size={12} />
          </div>
          <div className="flex items-center justify-end gap-2">
            {BRAND_CONFIG.phone} <Phone size={12} />
          </div>
          <div className="flex items-center justify-end gap-2">
            {BRAND_CONFIG.address} <MapPin size={12} />
          </div>
        </div>
      </header>

      {/* Trip Overview Card */}
      <section className="bg-slate-50 rounded-3xl p-8 mb-12 border border-slate-100">
        <div className="flex justify-between items-end">
          <div>
