            ${trip.itinerary.map((day, idx) => `
              <div style="position: relative; padding-left: 45px; margin-bottom: 40px; page-break-inside: avoid;">
                <div style="position: absolute; left: 0; top: 0; width: 32px; height: 32px; background: #2563eb; color: white; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 12px; font-weight: 900; box-shadow: 0 4px 6px rgba(37,99,235,0.2);">${day.dayNumber}</div>
                <h4 style="font-size: 18px; font-weight: 700; color: #1e293b; margin: 0 0 10px 0;">${day.title}</h4>
                <p style="font-size: 13px; color: #475569; line-height: 1.6; white-space: pre-line;">${day.clientNotes || "Enjoy your day at leisure."}</p>
                <div style="display: flex; flex-wrap: wrap; gap: 10px; margin-top: 15px;">
                  ${day.hotelId ? `<span style="background: #f1f5f9; padding: 4px 10px; border-radius: 8px; font-size: 11px; font-weight: 700; color: #334155;">Stay: ${HOTELS.find(h => h.id === day.hotelId)?.name}</span>` : ''}
                  ${day.vehicleId ? `<span style="background: #f1f5f9; padding: 4px 10px; border-radius: 8px; font-size: 11px; font-weight: 700; color: #334155;">Transport: ${VEHICLES.find(v => v.id === day.vehicleId)?.type}</span>` : ''}
                </div>
              </div>
            `).join('')}
          </div>

          <div style="display: flex; gap: 40px; padding-top: 30px; border-top: 1px solid #f1f5f9; page-break-inside: avoid;">
            <div style="flex: 1;">
              <h4 style="font-size: 12px; font-weight: 900; text-transform: uppercase; color: #10b981; margin-bottom: 15px;">Inclusions</h4>
              <ul style="font-size: 11px; color: #64748b; padding-left: 15px; margin: 0; line-height: 1.8;">
                <li>Accommodation in base category rooms</li>
                <li>Daily Breakfast and Dinner at all hotels</li>
                <li>Private vehicle for all transfers</li>
                <li>Shikara Ride for 1 hour on Dal Lake</li>
                <li>All Toll Taxes and Parking Fees</li>
              </ul>
            </div>
            <div style="flex: 1;">
              <h4 style="font-size: 12px; font-weight: 900; text-transform: uppercase; color: #ef4444; margin-bottom: 15px;">Exclusions</h4>
              <ul style="font-size: 11px; color: #64748b; padding-left: 15px; margin: 0; line-height: 1.8;">
                <li>Airfare / Train Tickets</li>
                <li>Lunch and personal expenses</li>
                <li>Entrance fees to monuments or gardens</li>
                <li>Tips and laundry</li>
              </ul>
            </div>
          </div>

          <footer style="margin-top: 50px; text-align: center; border-top: 1px solid #f1f5f9; padding-top: 20px;">
            <p style="font-size: 10px; font-weight: 700; color: #94a3b8; text-transform: uppercase; letter-spacing: 2px;">Thank you for choosing Escape Theory</p>
          </footer>
        </div>
      `;

      element.innerHTML = itineraryHtml;
      document.body.appendChild(element);

      const opt = {
