import React, { useState, useMemo, useEffect } from 'react';
import { useParams, useNavigate, Link } from 'react-router-dom';
import { 
  Plus, 
  Trash2, 
  Save, 
  ChevronDown, 
  ChevronUp, 
  Copy, 
  Share2, 
  Calculator,
  Sparkles,
  ArrowLeft,
  CalendarDays,
  Hotel as HotelIcon,
  Car as CarIcon,
  Activity as ActivityIcon,
  History,
  RotateCcw,
  Clock,
  FileText,
  Download,
  ExternalLink,
  Check,
  AlertCircle
} from 'lucide-react';
import { MOCK_TRIPS, HOTELS, VEHICLES, ACTIVITIES, ADD_ONS, BRAND_CONFIG } from '../constants';
import { Trip, ItineraryDay, TripVersion } from '../types';
import { generateDayDescription, suggestNextDayTitle } from '../services/geminiService';

const TripBuilder: React.FC = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const [trip, setTrip] = useState<Trip | null>(null);
  const [activeDayIndex, setActiveDayIndex] = useState(0);
  const [isAiGenerating, setIsAiGenerating] = useState(false);
  const [isDownloading, setIsDownloading] = useState(false);
  const [downloadSuccess, setDownloadSuccess] = useState(false);
  const [showHistory, setShowHistory] = useState(false);

  useEffect(() => {
    const foundTrip = MOCK_TRIPS.find(t => t.id === id);
    if (foundTrip) setTrip({ ...foundTrip });
  }, [id]);

  const costs = useMemo(() => {
    if (!trip) return { total: 0, hotel: 0, vehicle: 0, activity: 0, addOns: 0, margin: 0, sellingPrice: 0 };

    let hotelCost = 0;
    let vehicleCost = 0;
    let activityCost = 0;
    let addOnsCost = 0;

    trip.itinerary.forEach(day => {
      if (day.hotelId) {
        const hotel = HOTELS.find(h => h.id === day.hotelId);
        if (hotel) hotelCost += hotel.ratePerNight;
      }
      if (day.vehicleId) {
        const vehicle = VEHICLES.find(v => v.id === day.vehicleId);
        if (vehicle) vehicleCost += vehicle.ratePerDay;
      }
      day.activityIds.forEach(aid => {
        const act = ACTIVITIES.find(a => a.id === aid);
        if (act) activityCost += act.costPerPax * trip.pax;
      });
    });

    trip.addOnIds.forEach(aoId => {
      const ao = ADD_ONS.find(a => a.id === aoId);
      if (ao) {
        addOnsCost += ao.isPerPax ? ao.cost * trip.pax : ao.cost;
      }
    });

    const subtotal = hotelCost + vehicleCost + activityCost + addOnsCost;
    const margin = subtotal * (trip.marginPercentage / 100);
    const sellingPrice = subtotal + margin;

    return { 
      total: subtotal, 
      hotel: hotelCost, 
      vehicle: vehicleCost, 
      activity: activityCost, 
      addOns: addOnsCost, 
      margin, 
      sellingPrice 
    };
  }, [trip]);

  if (!trip) return <div className="p-10 text-center font-bold text-slate-400">Loading Trip Details...</div>;

  const handleSaveTrip = () => {
    if (!trip) return;
    const newVersion: TripVersion = {
      id: `v-${Date.now()}`,
      timestamp: new Date().toISOString(),
      itinerary: JSON.parse(JSON.stringify(trip.itinerary)),
      marginPercentage: trip.marginPercentage,
      addOnIds: [...trip.addOnIds],
      label: `Update ${new Date().toLocaleTimeString()}`
    };
    setTrip({ ...trip, versions: [newVersion, ...(trip.versions || [])] });
    alert("Trip saved and new version created!");
  };

  const handleRestoreVersion = (version: TripVersion) => {
    if (window.confirm(`Restore to version from ${new Date(version.timestamp).toLocaleString()}?`)) {
      setTrip({
        ...trip,
        itinerary: JSON.parse(JSON.stringify(version.itinerary)),
        marginPercentage: version.marginPercentage,
        addOnIds: [...version.addOnIds]
      });
      setShowHistory(false);
      setActiveDayIndex(0);
    }
  };

  const handleAddDay = async () => {
    if (!trip) return;
    const nextDayNum = trip.itinerary.length + 1;
    const lastDay = trip.itinerary[trip.itinerary.length - 1];

    const newDay: ItineraryDay = {
      id: `d-${Date.now()}`,
      dayNumber: nextDayNum,
      title: `Day ${nextDayNum}: Suggesting Title...`,
      hotelId: lastDay?.hotelId || '', 
      vehicleId: lastDay?.vehicleId || '', 
      activityIds: [],
      clientNotes: '',
      internalNotes: ''
    };

    const newItinerary = [...trip.itinerary, newDay];
    setTrip({ ...trip, itinerary: newItinerary });
    setActiveDayIndex(newItinerary.length - 1);

    const suggestedTitle = await suggestNextDayTitle(
      lastDay?.title || 'Start of Trip', 
      trip.tripType, 
      nextDayNum
    );

    setTrip(prev => {
      if (!prev) return null;
      const updatedItinerary = [...prev.itinerary];
      const targetDay = updatedItinerary[updatedItinerary.length - 1];
      if (targetDay && targetDay.title.includes('Suggesting Title...')) {
        updatedItinerary[updatedItinerary.length - 1] = { ...targetDay, title: suggestedTitle };
      }
      return { ...prev, itinerary: updatedItinerary };
    });
  };

  const updateDay = (index: number, updates: Partial<ItineraryDay>) => {
    const newItinerary = [...trip.itinerary];
    newItinerary[index] = { ...newItinerary[index], ...updates };
    setTrip({ ...trip, itinerary: newItinerary });
  };

  const handleAiDescription = async (index: number) => {
    const day = trip.itinerary[index];
    if (!day.title) return;

    setIsAiGenerating(true);
    const activities = day.activityIds.map(aid => ACTIVITIES.find(a => a.id === aid)?.name || '');
    const description = await generateDayDescription(day.title, activities);
    updateDay(index, { clientNotes: description });
    setIsAiGenerating(false);
  };

  const handleDownloadPdf = async () => {
    if (!trip || isDownloading) return;
    setIsDownloading(true);

    try {
      const h2p = (window as any).html2pdf;
      if (!h2p) throw new Error("PDF library not ready.");

      const renderZone = document.getElementById('pdf-render-zone');
      if (!renderZone) return;

      // Force absolute background white and clear any previous content
      renderZone.style.backgroundColor = 'white';
      renderZone.innerHTML = `
        <div style="padding: 60px; background-color: white; min-height: 1000px; color: #1e293b; font-family: 'Helvetica', 'Arial', sans-serif;">
          <div style="display: flex; justify-content: space-between; border-bottom: 2px solid #e2e8f0; padding-bottom: 30px; margin-bottom: 40px;">
            <div>
              <h1 style="color: #2563eb; margin: 0; font-size: 32px; font-weight: bold;">${BRAND_CONFIG.name}</h1>
              <p style="color: #64748b; margin: 8px 0; font-size: 14px; font-weight: 600;">${BRAND_CONFIG.tagline}</p>
            </div>
            <div style="text-align: right; font-size: 12px; color: #64748b; line-height: 1.5;">
              <p style="margin:0;">${BRAND_CONFIG.email}</p>
              <p style="margin:0;">${BRAND_CONFIG.phone}</p>
              <p style="margin:0;">${BRAND_CONFIG.address}</p>
            </div>
          </div>

          <div style="margin-bottom: 40px; background: #f1f5f9; padding: 30px; border-radius: 12px;">
             <h2 style="margin: 0; font-size: 26px; color: #0f172a;">${trip.tripName}</h2>
             <p style="margin: 12px 0 0 0; font-size: 16px; color: #475569;">Guest: <strong style="color: #0f172a;">${trip.client.name}</strong> &nbsp; | &nbsp; Travelers: <strong>${trip.pax}</strong></p>
          </div>

          <div>
            ${trip.itinerary.map(day => `
              <div style="margin-bottom: 40px; page-break-inside: avoid; border-bottom: 1px solid #f1f5f9; padding-bottom: 20px;">
                <h3 style="margin: 0 0 15px 0; font-size: 20px; color: #2563eb;">Day ${day.dayNumber}: ${day.title}</h3>
                <p style="font-size: 15px; line-height: 1.7; color: #334155; margin-bottom: 15px;">${day.clientNotes || 'Scheduled exploration and leisure.'}</p>
                <div style="display: flex; gap: 15px;">
                  ${day.hotelId ? `<div style="font-size: 12px; font-weight: bold; color: #2563eb; background: #eff6ff; padding: 6px 12px; border-radius: 6px;">Stay: ${HOTELS.find(h => h.id === day.hotelId)?.name}</div>` : ''}
                  ${day.vehicleId ? `<div style="font-size: 12px; font-weight: bold; color: #475569; background: #f8fafc; padding: 6px 12px; border-radius: 6px;">Transport: ${VEHICLES.find(v => v.id === day.vehicleId)?.type}</div>` : ''}
                </div>
              </div>
            `).join('')}
          </div>

          <div style="margin-top: 60px; text-align: center; border-top: 2px solid #f1f5f9; padding-top: 30px;">
            <p style="font-size: 11px; color: #94a3b8; text-transform: uppercase; letter-spacing: 3px; font-weight: bold;">Escape Theory Kashmir</p>
            <p style="font-size: 10px; color: #cbd5e1; margin-top: 5px;">Created on ${new Date().toLocaleDateString()}</p>
          </div>
        </div>
      `;

      // Wait a bit for images/fonts if any
      await new Promise(resolve => setTimeout(resolve, 500));

      const opt = {
        margin: [0, 0, 0, 0],
        filename: `${trip.client.name.replace(/[^a-z0-9]/gi, '_')}_Itinerary.pdf`,
        image: { type: 'jpeg', quality: 0.98 },
        html2canvas: { 
          scale: 2, 
          useCORS: true, 
          backgroundColor: '#ffffff',
          logging: false,
          scrollY: 0,
          scrollX: 0
        },
        jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' }
      };

      await h2p().from(renderZone).set(opt).save();
      setDownloadSuccess(true);
      setTimeout(() => setDownloadSuccess(false), 3000);
    } catch (err) {
      console.error("PDF generation error:", err);
      alert("Direct download failed. Please use 'Print Preview' instead.");
    } finally {
      setIsDownloading(false);
    }
  };

  return (
    <div className="flex flex-col h-full space-y-6 relative">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-4">
          <button onClick={() => navigate('/trips')} className="p-2 hover:bg-white rounded-lg transition-colors border border-transparent hover:border-slate-200">
            <ArrowLeft size={20} className="text-slate-600" />
          </button>
          <div>
            <h1 className="text-2xl font-bold text-slate-900">{trip.tripName}</h1>
            <p className="text-slate-500 text-sm">Itinerary Builder • {trip.client.name}</p>
          </div>
        </div>
        <div className="flex items-center gap-3">
          <button 
            onClick={() => setShowHistory(!showHistory)}
            className={`flex items-center gap-2 px-4 py-2 border rounded-lg font-bold transition-all ${showHistory ? 'bg-slate-800 text-white border-slate-800' : 'bg-white border-slate-200 text-slate-700 hover:bg-slate-50'}`}
          >
            <History size={18} />
            History
          </button>

          <Link 
            to={`/trips/${trip.id}/print`}
            target="_blank"
            className="flex items-center gap-2 px-4 py-2 border border-slate-200 rounded-lg bg-white text-blue-600 font-bold hover:bg-blue-50 transition-all shadow-sm"
          >
            <ExternalLink size={18} />
            Print Preview
          </Link>

          <button 
            onClick={handleSaveTrip}
            className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg font-bold hover:bg-blue-700 transition-all shadow-md"
          >
            <Save size={18} />
            Save Changes
          </button>
        </div>
      </div>

      <div className="flex flex-1 gap-6 overflow-hidden relative">
        {/* Version History Sidebar */}
        {showHistory && (
          <div className="absolute inset-y-0 right-0 w-80 bg-white border-l border-slate-200 shadow-2xl z-20 flex flex-col animate-in slide-in-from-right duration-300">
            <div className="p-6 border-b border-slate-100 flex items-center justify-between">
              <h3 className="font-black text-slate-800 uppercase tracking-widest flex items-center gap-2">
                <Clock size={18} className="text-blue-600" />
                Versions
              </h3>
              <button onClick={() => setShowHistory(false)} className="text-slate-400 hover:text-slate-600">
                <Plus size={20} className="rotate-45" />
              </button>
            </div>
            <div className="flex-1 overflow-y-auto p-4 space-y-4 text-slate-900">
              {trip.versions?.length ? trip.versions.map((v) => (
                <div key={v.id} className="p-4 border border-slate-100 rounded-xl hover:bg-slate-50 transition-all group">
                  <div className="flex justify-between items-start mb-2">
                    <span className="text-xs font-bold text-blue-600">{v.label}</span>
                    <button 
                      onClick={() => handleRestoreVersion(v)}
                      className="text-xs bg-slate-200 px-2 py-1 rounded font-bold opacity-0 group-hover:opacity-100 transition-all hover:bg-blue-600 hover:text-white"
                    >
                      Restore
                    </button>
                  </div>
                  <p className="text-[10px] text-slate-400 font-medium">{new Date(v.timestamp).toLocaleString()}</p>
                </div>
              )) : (
                <div className="text-center py-10 text-slate-400 text-xs italic">No saved versions found.</div>
              )}
            </div>
          </div>
        )}

        {/* Days List */}
        <div className="w-80 bg-white border border-slate-200 rounded-xl flex flex-col overflow-hidden">
          <div className="p-4 border-b border-slate-100 flex items-center justify-between">
            <h3 className="font-bold text-slate-800 flex items-center gap-2">
              <CalendarDays size={18} className="text-blue-600" />
              Itinerary
            </h3>
            <span className="text-xs font-bold text-slate-400">{trip.itinerary.length} Days</span>
          </div>
          <div className="flex-1 overflow-y-auto p-4 space-y-3">
            {trip.itinerary.map((day, idx) => (
              <button
                key={day.id}
                onClick={() => setActiveDayIndex(idx)}
                className={`w-full text-left p-3 rounded-lg border transition-all ${
                  activeDayIndex === idx 
                    ? 'border-blue-600 bg-blue-50 shadow-sm' 
                    : 'border-slate-100 hover:border-slate-300'
                }`}
              >
                <div className="flex justify-between items-center">
                  <span className="text-[10px] font-black uppercase text-blue-600">Day {day.dayNumber}</span>
                </div>
                <h4 className={`font-semibold truncate ${activeDayIndex === idx ? 'text-blue-900' : 'text-slate-700'}`}>
                  {day.title || 'Untitled Day'}
                </h4>
              </button>
            ))}
            <button 
              onClick={handleAddDay}
              className="w-full py-3 border-2 border-dashed border-slate-200 rounded-lg text-slate-400 font-bold hover:border-blue-400 hover:text-blue-500 transition-all flex items-center justify-center gap-2"
            >
              <Plus size={18} />
              Add Next Day
            </button>
          </div>
        </div>

        {/* Editor Content */}
        <div className="flex-1 overflow-y-auto space-y-6 pb-20 pr-2">
          {trip.itinerary[activeDayIndex] ? (
            <div className="bg-white border border-slate-200 rounded-xl shadow-sm p-8 space-y-8 animate-in fade-in slide-in-from-right-4 duration-200 text-slate-900">
              <div className="flex flex-col gap-2">
                <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">Day Title</label>
                <input 
                  type="text" 
                  value={trip.itinerary[activeDayIndex].title}
                  onChange={(e) => updateDay(activeDayIndex, { title: e.target.value })}
                  className="text-3xl font-bold text-slate-900 border-none p-0 focus:ring-0 placeholder:text-slate-300 w-full bg-transparent"
                />
              </div>

              <div className="grid grid-cols-2 gap-8">
                <div className="space-y-4">
                  <label className="text-sm font-bold text-slate-700 flex items-center gap-2">
                    <HotelIcon size={16} className="text-blue-500" />
                    Accommodation
                  </label>
                  <select 
                    value={trip.itinerary[activeDayIndex].hotelId}
                    onChange={(e) => updateDay(activeDayIndex, { hotelId: e.target.value })}
                    className="w-full p-3 bg-slate-50 border border-slate-200 rounded-lg text-sm font-medium text-slate-900"
                  >
                    <option value="">Select Hotel</option>
                    {HOTELS.map(h => <option key={h.id} value={h.id}>{h.name}</option>)}
                  </select>
                </div>

                <div className="space-y-4">
                  <label className="text-sm font-bold text-slate-700 flex items-center gap-2">
                    <CarIcon size={16} className="text-blue-500" />
                    Transport
                  </label>
                  <select 
                    value={trip.itinerary[activeDayIndex].vehicleId}
                    onChange={(e) => updateDay(activeDayIndex, { vehicleId: e.target.value })}
                    className="w-full p-3 bg-slate-50 border border-slate-200 rounded-lg text-sm font-medium text-slate-900"
                  >
                    <option value="">Select Vehicle</option>
                    {VEHICLES.map(v => <option key={v.id} value={v.id}>{v.type}</option>)}
                  </select>
                </div>
              </div>

              <div className="space-y-4">
                <div className="flex items-center justify-between">
                  <label className="text-sm font-bold text-slate-700">Client Description</label>
                  <button 
                    onClick={() => handleAiDescription(activeDayIndex)}
                    disabled={isAiGenerating}
                    className="flex items-center gap-2 text-xs font-black uppercase text-blue-600 bg-blue-50 px-3 py-1.5 rounded-full disabled:opacity-50"
                  >
                    <Sparkles size={12} />
                    {isAiGenerating ? 'AI Magic...' : 'AI Enhance'}
                  </button>
                </div>
                <textarea 
                  rows={4}
                  value={trip.itinerary[activeDayIndex].clientNotes}
                  onChange={(e) => updateDay(activeDayIndex, { clientNotes: e.target.value })}
                  className="w-full p-4 bg-slate-50 border border-slate-200 rounded-xl text-sm leading-relaxed text-slate-900 focus:ring-2 focus:ring-blue-500 outline-none"
                />
              </div>

              <div className="space-y-4">
                <label className="text-sm font-bold text-slate-500">Internal Operational Notes</label>
                <textarea 
                  rows={2}
                  value={trip.itinerary[activeDayIndex].internalNotes}
                  onChange={(e) => updateDay(activeDayIndex, { internalNotes: e.target.value })}
                  className="w-full p-4 bg-amber-50/30 border border-amber-100 rounded-xl text-sm italic text-slate-800 outline-none"
                />
              </div>
            </div>
          ) : (
            <div className="flex flex-col items-center justify-center h-64 bg-white border-2 border-dashed border-slate-200 rounded-xl text-slate-400">
              <CalendarDays size={48} className="mb-4 opacity-20" />
              <p className="font-bold">Select a day to start building the itinerary.</p>
            </div>
          )}
        </div>

        {/* Costing Engine */}
        <div className="w-80 bg-slate-900 text-white rounded-xl shadow-2xl p-6 flex flex-col h-fit sticky top-0">
          <div className="flex items-center gap-2 mb-6 border-b border-slate-800 pb-4">
            <Calculator className="text-blue-400" size={20} />
            <h3 className="font-bold text-lg">Financial Summary</h3>
          </div>

          <div className="space-y-4 flex-1">
            <div className="flex justify-between items-center text-sm">
              <span className="text-slate-400">Hotels Total</span>
              <span className="font-bold">₹ {costs.hotel.toLocaleString()}</span>
            </div>
            <div className="flex justify-between items-center text-sm">
              <span className="text-slate-400">Vehicle Total</span>
              <span className="font-bold">₹ {costs.vehicle.toLocaleString()}</span>
            </div>
            <div className="flex justify-between items-center text-sm">
              <span className="text-slate-400">Activities Total</span>
              <span className="font-bold">₹ {costs.activity.toLocaleString()}</span>
            </div>
            <div className="pt-4 border-t border-slate-800">
              <div className="flex justify-between items-center text-xs uppercase font-black text-slate-500 mb-2">
                <span>Margin %</span>
                <input 
                  type="number" 
                  value={trip.marginPercentage}
                  onChange={(e) => setTrip({ ...trip, marginPercentage: Number(e.target.value) })}
                  className="w-12 bg-transparent border-none p-0 text-right text-blue-400 font-black focus:ring-0"
                />
              </div>
              <div className="flex justify-between items-center text-emerald-400 font-bold">
                <span>Profit</span>
                <span>₹ {Math.round(costs.margin).toLocaleString()}</span>
              </div>
            </div>
          </div>

          <div className="mt-10 pt-6 border-t border-slate-800">
            <p className="text-[10px] uppercase font-black tracking-widest text-slate-500 mb-1">Total Quote</p>
            <h2 className="text-4xl font-black text-white">₹ {Math.round(costs.sellingPrice).toLocaleString()}</h2>

            <div className="mt-6 space-y-3">
              <button 
                onClick={handleDownloadPdf}
                disabled={isDownloading}
                className={`w-full py-4 rounded-xl font-black uppercase tracking-widest text-xs flex items-center justify-center gap-3 transition-all ${
                  downloadSuccess 
                    ? 'bg-emerald-600 text-white shadow-lg shadow-emerald-900/40' 
                    : 'bg-blue-600 text-white hover:bg-blue-700 shadow-lg shadow-blue-900/40'
                } disabled:opacity-50 disabled:cursor-not-allowed`}
              >
                {isDownloading ? (
                  <Clock className="animate-spin" size={16} />
                ) : downloadSuccess ? (
                  <Check size={16} />
                ) : (
                  <Download size={16} />
                )}
                {isDownloading ? 'Generating...' : downloadSuccess ? 'Success' : 'Direct PDF'}
              </button>

              {!isDownloading && !downloadSuccess && (
                <p className="text-[10px] text-slate-500 text-center italic">Branded itinerary directly to downloads.</p>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default TripBuilder;

