import React, { useEffect, useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { Mail, Phone, MapPin, Calendar, Users, CheckCircle2, XCircle, Info, X, Printer } from 'lucide-react';
import { MOCK_TRIPS, BRAND_CONFIG, HOTELS, VEHICLES, ACTIVITIES } from '../constants';
import { Trip, HotelCategory } from '../types';

const ClientItinerary: React.FC = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const [trip, setTrip] = useState<Trip | null>(null);
  const [isReady, setIsReady] = useState(false);

  useEffect(() => {
    const foundTrip = MOCK_TRIPS.find(t => t.id === id);
    if (foundTrip) {
      setTrip(foundTrip);
      // Wait for rendering lifecycle to settle
      const timer = setTimeout(() => setIsReady(true), 1200);
      return () => clearTimeout(timer);
    }
  }, [id]);

  useEffect(() => {
    if (isReady) {
      // Small delay for images/fonts to finalize paint
      const timer = setTimeout(() => {
        try {
          window.print();
        } catch (e) {
          console.error("Print dialog blocked or failed", e);
        }
      }, 300);
      return () => clearTimeout(timer);
    }
  }, [isReady]);

  if (!trip) return (
    <div className="p-20 text-center font-bold text-slate-400">
      <p className="mb-4">Loading itinerary details...</p>
      <button onClick={() => navigate('/')} className="px-4 py-2 bg-blue-600 text-white rounded-lg">Return to Dashboard</button>
    </div>
  );

  return (
    <div className="bg-white min-h-screen text-slate-900 print:bg-white">
      {/* Interactive Controls (Hidden during print) */}
      <div className="no-print sticky top-0 bg-white/90 backdrop-blur-md border-b border-slate-200 z-50 p-4 flex justify-between items-center px-8 shadow-sm">
        <div className="flex items-center gap-4">
          <button onClick={() => window.close() || navigate(-1)} className="text-slate-500 font-bold hover:text-slate-800 flex items-center gap-2 transition-colors">
            <X size={18} /> Exit Preview
          </button>
          <div className="h-6 w-px bg-slate-200" />
          <h2 className="font-bold text-slate-800">Print View: {trip.tripName}</h2>
        </div>
        <div className="flex gap-3">
          <button 
            onClick={() => window.print()} 
            className="bg-blue-600 text-white px-6 py-2 rounded-xl font-bold flex items-center gap-2 shadow-lg hover:shadow-blue-200 hover:bg-blue-700 transition-all"
          >
            <Printer size={18} /> Print or Save as PDF
          </button>
        </div>
      </div>

      <div className="max-w-[210mm] mx-auto p-[15mm] print:p-0">
        {/* Branded Header */}
        <header className="flex justify-between items-start border-b-2 border-slate-100 pb-8 mb-10">
          <div className="flex items-center gap-4">
            <img src={BRAND_CONFIG.logo} alt="Logo" className="w-16 h-16" />
            <div>
              <h1 className="text-3xl font-black text-blue-600 tracking-tight">{BRAND_CONFIG.name}</h1>
              <p className="text-slate-500 font-bold text-xs uppercase tracking-widest">{BRAND_CONFIG.tagline}</p>
            </div>
          </div>
          <div className="text-right text-[10px] space-y-1 text-slate-500 font-medium leading-tight">
            <p>{BRAND_CONFIG.email}</p>
            <p>{BRAND_CONFIG.phone}</p>
            <p className="max-w-[150px]">{BRAND_CONFIG.address}</p>
          </div>
        </header>

        {/* Hero Section */}
        <section className="bg-slate-50 rounded-3xl p-8 mb-12 border border-slate-100">
          <div className="flex justify-between items-end">
            <div>
              <span className="text-[10px] font-black uppercase text-blue-600 tracking-widest bg-blue-50 px-3 py-1 rounded-full mb-3 inline-block">
                {trip.tripType} Experience
              </span>
              <h2 className="text-4xl font-black text-slate-900 mb-2">{trip.tripName}</h2>
              <p className="text-slate-500 font-medium">Prepared for <span className="text-slate-900 font-bold">{trip.client.name}</span></p>
            </div>
            <div className="flex gap-8 text-sm">
              <div className="text-center">
                <p className="font-bold text-slate-800 text-lg">{trip.itinerary.length} Days</p>
                <p className="text-[10px] text-slate-400 font-bold uppercase">Duration</p>
              </div>
              <div className="text-center">
                <p className="font-bold text-slate-800 text-lg">{trip.pax} Guests</p>
                <p className="text-[10px] text-slate-400 font-bold uppercase">Travelers</p>
              </div>
            </div>
          </div>
        </section>

        {/* Itinerary Timeline */}
        <section className="space-y-12 mb-16">
          {trip.itinerary.map((day, idx) => {
            const hotel = HOTELS.find(h => h.id === day.hotelId);
            const vehicle = VEHICLES.find(v => v.id === day.vehicleId);

            return (
              <div key={day.id} className="relative pl-12 break-inside-avoid">
                {idx !== trip.itinerary.length - 1 && (
                  <div className="absolute left-[15px] top-8 bottom-[-48px] w-0.5 bg-slate-100" />
                )}
                <div className="absolute left-0 top-0 w-8 h-8 rounded-full bg-blue-600 text-white flex items-center justify-center font-black text-xs">
                  {day.dayNumber}
                </div>

                <div className="space-y-4">
                  <h4 className="text-2xl font-bold text-slate-800">{day.title}</h4>
                  <p className="text-slate-600 leading-relaxed text-sm whitespace-pre-line">
                    {day.clientNotes || "Personal leisure and exploration time."}
                  </p>

                  <div className="flex flex-wrap gap-3 pt-2">
                    {hotel && (
                      <div className="bg-slate-50 border border-slate-100 px-3 py-1.5 rounded-lg text-xs font-bold text-slate-700">
                        Accommodation: <span className="text-blue-600">{hotel.name}</span>
                      </div>
                    )}
                    {vehicle && (
                      <div className="bg-slate-50 border border-slate-100 px-3 py-1.5 rounded-lg text-xs font-bold text-slate-700">
                        Transport: <span className="text-blue-600">{vehicle.type}</span>
                      </div>
                    )}
                  </div>
                </div>
              </div>
            );
          })}
        </section>

        {/* T&C Section */}
        <section className="grid grid-cols-2 gap-10 pt-10 border-t border-slate-100 break-inside-avoid">
          <div className="space-y-4">
            <h4 className="text-xs font-black uppercase tracking-widest text-emerald-600 flex items-center gap-2">
               <CheckCircle2 size={16} /> Inclusions
            </h4>
            <ul className="text-[10px] space-y-2 text-slate-500 font-medium">
              <li>• Breakfast & Dinner at all accommodations</li>
              <li>• Private vehicle for all listed transfers</li>
              <li>• Shikara ride for 1 hour on Dal Lake</li>
              <li>• All state taxes and driver allowances</li>
            </ul>
          </div>
          <div className="space-y-4">
            <h4 className="text-xs font-black uppercase tracking-widest text-red-500 flex items-center gap-2">
               <XCircle size={16} /> Exclusions
            </h4>
            <ul className="text-[10px] space-y-2 text-slate-500 font-medium">
              <li>• Any flight or train travel</li>
              <li>• Entry tickets to gardens or monuments</li>
              <li>• Personal items and gratuities</li>
              <li>• Anything not mentioned in inclusions</li>
            </ul>
          </div>
        </section>

        <footer className="mt-24 pt-10 border-t border-slate-100 text-center">
          <p className="text-[10px] font-black text-slate-300 uppercase tracking-[0.3em] mb-2">Escape Theory Kashmir</p>
          <p className="text-[9px] text-slate-400">This itinerary is valid as of ${new Date().toLocaleDateString()}. Subject to availability at time of booking.</p>
        </footer>
      </div>

      <style>{`
        @media print {
          .no-print { display: none !important; }
          body { background: white !important; margin: 0 !important; padding: 0 !important; }
          @page { margin: 15mm; size: A4 portrait; }
        }
      `}</style>
    </div>
  );
};

