import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { Plus, Search, Filter, Calendar, User, ArrowRight, X } from 'lucide-react';
import { MOCK_TRIPS } from '../constants';
import { Trip, TripStatus, TripType } from '../types';

const TripList: React.FC = () => {
  const navigate = useNavigate();
  const [trips, setTrips] = useState<Trip[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState('All');
  const [tripTypeFilter, setTripTypeFilter] = useState('All');
  const [startDateFilter, setStartDateFilter] = useState('');
  const [salespersonFilter, setSalespersonFilter] = useState('All');
  const [showFilters, setShowFilters] = useState(false);

  useEffect(() => {
    const savedTrips = localStorage.getItem('et_trips');
    if (savedTrips) {
      setTrips(JSON.parse(savedTrips));
    } else {
      setTrips(MOCK_TRIPS);
    }
  }, []);

  const salespeople = Array.from(new Set(trips.map(t => t.assignedSalesperson)));

  const filteredTrips = trips.filter(trip => {
    const searchLower = searchTerm.toLowerCase();
    const matchesSearch = 
      trip.client.name.toLowerCase().includes(searchLower) || 
      trip.tripName.toLowerCase().includes(searchLower) ||
      trip.client.phone.includes(searchTerm) ||
      trip.client.email.toLowerCase().includes(searchLower);

    const matchesStatus = statusFilter === 'All' || trip.status === statusFilter;
    const matchesType = tripTypeFilter === 'All' || trip.tripType === tripTypeFilter;
    const matchesSales = salespersonFilter === 'All' || trip.assignedSalesperson === salespersonFilter;
    const matchesDate = !startDateFilter || trip.startDate >= startDateFilter;

    return matchesSearch && matchesStatus && matchesType && matchesSales && matchesDate;
  });

  const resetFilters = () => {
    setSearchTerm('');
    setStatusFilter('All');
    setTripTypeFilter('All');
    setStartDateFilter('');
    setSalespersonFilter('All');
  };

  return (
    <div className="space-y-6">
      <div className="bg-white p-6 rounded-xl border border-slate-200 shadow-sm space-y-4">
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
          <div className="flex-1 relative">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
            <input 
              type="text" 
              placeholder="Search by client, phone, email, or trip name..." 
              className="w-full pl-10 pr-4 py-2 bg-slate-50 border border-slate-200 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 transition-all text-slate-900"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>

          <div className="flex items-center gap-3">
            <button 
              onClick={() => setShowFilters(!showFilters)}
              className={`flex items-center gap-2 px-4 py-2 border rounded-lg font-medium transition-all ${showFilters ? 'bg-blue-50 border-blue-200 text-blue-600' : 'bg-white border-slate-200 text-slate-700'}`}
            >
              <Filter size={18} />
              {showFilters ? 'Hide Filters' : 'Advanced Filters'}
            </button>
            <button 
              onClick={() => navigate('/trips/new')}
              className="flex items-center gap-2 bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded-lg font-bold transition-all shadow-sm"
            >
              <Plus size={18} />
              New Trip
            </button>
          </div>
        </div>

        {showFilters && (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4 pt-4 border-t border-slate-100 animate-in fade-in slide-in-from-top-2">
            <div className="space-y-1">
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Status</label>
              <select 
                className="w-full bg-slate-50 border border-slate-200 rounded-lg py-2 px-3 text-sm text-slate-900"
                value={statusFilter}
                onChange={(e) => setStatusFilter(e.target.value)}
              >
                <option value="All">All Statuses</option>
                {Object.values(TripStatus).map(s => <option key={s} value={s}>{s}</option>)}
              </select>
            </div>
            <div className="space-y-1">
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Trip Type</label>
              <select 
                className="w-full bg-slate-50 border border-slate-200 rounded-lg py-2 px-3 text-sm text-slate-900"
                value={tripTypeFilter}
                onChange={(e) => setTripTypeFilter(e.target.value)}
              >
                <option value="All">All Types</option>
                {Object.values(TripType).map(t => <option key={t} value={t}>{t}</option>)}
              </select>
            </div>
            <div className="space-y-1">
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Salesperson</label>
              <select 
                className="w-full bg-slate-50 border border-slate-200 rounded-lg py-2 px-3 text-sm text-slate-900"
                value={salespersonFilter}
                onChange={(e) => setSalespersonFilter(e.target.value)}
              >
                <option value="All">All Salespeople</option>
                {salespeople.map(s => <option key={s} value={s}>{s}</option>)}
              </select>
            </div>
            <div className="space-y-1">
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Starts After</label>
              <input 
                type="date" 
                className="w-full bg-slate-50 border border-slate-200 rounded-lg py-2 px-3 text-sm text-slate-900"
                value={startDateFilter}
                onChange={(e) => setStartDateFilter(e.target.value)}
              />
            </div>
            <div className="lg:col-span-4 flex justify-end">
              <button onClick={resetFilters} className="text-xs font-bold text-slate-400 hover:text-red-500 flex items-center gap-1">
                <X size={14} /> Clear All Filters
              </button>
            </div>
          </div>
        )}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
        {filteredTrips.map(trip => (
          <div 
            key={trip.id} 
            className="bg-white border border-slate-200 rounded-xl overflow-hidden hover:shadow-lg transition-all cursor-pointer flex flex-col group"
            onClick={() => navigate(`/trips/${trip.id}`)}
          >
            <div className="p-5 flex-1">
              <div className="flex justify-between items-start mb-4">
                <span className={`px-2.5 py-1 rounded text-[10px] font-black uppercase tracking-widest ${
                  trip.tripType === TripType.HONEYMOON ? 'bg-pink-100 text-pink-700' :
                  trip.tripType === TripType.FAMILY ? 'bg-emerald-100 text-emerald-700' :
                  'bg-slate-100 text-slate-700'
                }`}>
                  {trip.tripType}
                </span>
                <span className={`px-2.5 py-1 rounded text-[10px] font-black uppercase tracking-widest ${
                  trip.status === TripStatus.BOOKED ? 'bg-green-100 text-green-700' :
                  trip.status === TripStatus.QUOTED ? 'bg-blue-100 text-blue-700' :
                  'bg-orange-100 text-orange-700'
                }`}>
                  {trip.status}
                </span>
              </div>

              <h3 className="text-xl font-bold text-slate-800 mb-1 group-hover:text-blue-600 transition-colors">
                {trip.tripName}
              </h3>
              <p className="text-slate-500 text-sm mb-4">Client: {trip.client.name}</p>

              <div className="space-y-3">
                <div className="flex items-center gap-3 text-slate-600">
                  <Calendar size={16} className="text-slate-400" />
                  <span className="text-sm font-medium">{trip.startDate || 'No date'} - {trip.endDate || 'No date'}</span>
                </div>
                <div className="flex items-center gap-3 text-slate-600">
                  <User size={16} className="text-slate-400" />
                  <span className="text-sm font-medium">{trip.pax} Passengers • {trip.budgetRange}</span>
                </div>
              </div>
            </div>

            <div className="px-5 py-4 bg-slate-50 border-t border-slate-100 flex items-center justify-between">
              <div className="flex -space-x-2">
                <div className="w-8 h-8 rounded-full bg-blue-100 border-2 border-white flex items-center justify-center text-[10px] font-bold text-blue-600" title={trip.assignedSalesperson}>
                  {trip.assignedSalesperson.split(' ').map(n => n[0]).join('')}
                </div>
              </div>
              <div className="flex items-center gap-1 text-blue-600 font-bold text-sm">
                Open Builder
                <ArrowRight size={14} />
              </div>
            </div>
          </div>
        ))}
      </div>

      {filteredTrips.length === 0 && (
        <div className="bg-white p-20 rounded-xl border-2 border-dashed border-slate-200 text-center">
          <p className="text-slate-400 font-bold">No trips found matching your criteria.</p>
          <button onClick={resetFilters} className="mt-4 text-blue-600 font-bold hover:underline">Reset Filters</button>
        </div>
      )}
    </div>
  );
};

export default TripList;

import React, { useState, useMemo, useEffect } from 'react';
import { useParams, useNavigate, Link } from 'react-router-dom';
import { 
  Plus, 
  Trash2, 
  Save, 
  ChevronDown, 
  ChevronUp, 
  Copy, 
  Share2, 
  Calculator,
  Sparkles,
  ArrowLeft,
  CalendarDays,
  Hotel as HotelIcon,
  Car as CarIcon,
  Activity as ActivityIcon,
  History,
  RotateCcw,
  Clock,
  FileText,
  Download,
  ExternalLink,
  Check,
  AlertCircle
} from 'lucide-react';
import { MOCK_TRIPS, HOTELS, VEHICLES, ACTIVITIES, ADD_ONS, BRAND_CONFIG } from '../constants';
import { Trip, ItineraryDay, TripVersion } from '../types';
import { generateDayDescription, suggestNextDayTitle } from '../services/geminiService';

const TripBuilder: React.FC = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const [trip, setTrip] = useState<Trip | null>(null);
  const [activeDayIndex, setActiveDayIndex] = useState(0);
  const [isAiGenerating, setIsAiGenerating] = useState(false);
  const [isDownloading, setIsDownloading] = useState(false);
  const [downloadSuccess, setDownloadSuccess] = useState(false);
  const [showHistory, setShowHistory] = useState(false);

  // Load trip data and check localStorage for edits
  useEffect(() => {
    const savedTrips = localStorage.getItem('et_trips');
    let foundTrip: Trip | undefined;

    if (savedTrips) {
      const parsed = JSON.parse(savedTrips);
      foundTrip = parsed.find((t: Trip) => t.id === id);
    }

    if (!foundTrip) {
      foundTrip = MOCK_TRIPS.find(t => t.id === id);
    }

    if (foundTrip) {
      setTrip({ ...foundTrip });
    }
  }, [id]);

  // Persist trip to localStorage whenever it changes
  useEffect(() => {
    if (trip) {
      const savedTrips = localStorage.getItem('et_trips');
      let allTrips: Trip[] = savedTrips ? JSON.parse(savedTrips) : [...MOCK_TRIPS];

      const index = allTrips.findIndex(t => t.id === trip.id);
      if (index > -1) {
        allTrips[index] = trip;
      } else {
        allTrips.push(trip);
      }
      localStorage.setItem('et_trips', JSON.stringify(allTrips));
    }
  }, [trip]);

  const costs = useMemo(() => {
    if (!trip) return { total: 0, hotel: 0, vehicle: 0, activity: 0, addOns: 0, margin: 0, sellingPrice: 0 };

    let hotelCost = 0;
    let vehicleCost = 0;
    let activityCost = 0;
    let addOnsCost = 0;

    trip.itinerary.forEach(day => {
      if (day.hotelId) {
        const hotel = HOTELS.find(h => h.id === day.hotelId);
        if (hotel) hotelCost += hotel.ratePerNight;
      }
      if (day.vehicleId) {
        const vehicle = VEHICLES.find(v => v.id === day.vehicleId);
        if (vehicle) vehicleCost += vehicle.ratePerDay;
      }
      day.activityIds.forEach(aid => {
        const act = ACTIVITIES.find(a => a.id === aid);
        if (act) activityCost += act.costPerPax * trip.pax;
      });
    });

    trip.addOnIds.forEach(aoId => {
      const ao = ADD_ONS.find(a => a.id === aoId);
      if (ao) {
        addOnsCost += ao.isPerPax ? ao.cost * trip.pax : ao.cost;
      }
    });

    const subtotal = hotelCost + vehicleCost + activityCost + addOnsCost;
    const margin = subtotal * (trip.marginPercentage / 100);
    const sellingPrice = subtotal + margin;

    return { 
      total: subtotal, 
      hotel: hotelCost, 
      vehicle: vehicleCost, 
      activity: activityCost, 
      addOns: addOnsCost, 
      margin, 
      sellingPrice 
    };
  }, [trip]);

  if (!trip) return <div className="p-10 text-center font-bold text-slate-400">Loading Trip Details...</div>;

  const handleSaveTrip = () => {
    if (!trip) return;
    const newVersion: TripVersion = {
      id: `v-${Date.now()}`,
      timestamp: new Date().toISOString(),
      itinerary: JSON.parse(JSON.stringify(trip.itinerary)),
      marginPercentage: trip.marginPercentage,
      addOnIds: [...trip.addOnIds],
      label: `Update ${new Date().toLocaleTimeString()}`
    };

    const updatedTrip = { ...trip, versions: [newVersion, ...(trip.versions || [])] };
    setTrip(updatedTrip);

    // Force immediate save for peace of mind
    const savedTrips = localStorage.getItem('et_trips');
    let allTrips: Trip[] = savedTrips ? JSON.parse(savedTrips) : [...MOCK_TRIPS];
    const index = allTrips.findIndex(t => t.id === updatedTrip.id);
    if (index > -1) allTrips[index] = updatedTrip;
    else allTrips.push(updatedTrip);
    localStorage.setItem('et_trips', JSON.stringify(allTrips));

    alert("Changes saved successfully!");
  };

  const handleRestoreVersion = (version: TripVersion) => {
    if (window.confirm(`Restore to version from ${new Date(version.timestamp).toLocaleString()}?`)) {
      setTrip({
        ...trip,
        itinerary: JSON.parse(JSON.stringify(version.itinerary)),
        marginPercentage: version.marginPercentage,
        addOnIds: [...version.addOnIds]
      });
      setShowHistory(false);
      setActiveDayIndex(0);
    }
  };

  const handleAddDay = async () => {
    if (!trip) return;
    const nextDayNum = trip.itinerary.length + 1;
    const lastDay = trip.itinerary[trip.itinerary.length - 1];

    const newDay: ItineraryDay = {
      id: `d-${Date.now()}`,
      dayNumber: nextDayNum,
      title: `Day ${nextDayNum}: Suggesting Title...`,
      hotelId: lastDay?.hotelId || '', 
      vehicleId: lastDay?.vehicleId || '', 
      activityIds: [],
      clientNotes: '',
      internalNotes: ''
    };

    const newItinerary = [...trip.itinerary, newDay];
    setTrip({ ...trip, itinerary: newItinerary });
    setActiveDayIndex(newItinerary.length - 1);

    const suggestedTitle = await suggestNextDayTitle(
      lastDay?.title || 'Start of Trip', 
      trip.tripType, 
      nextDayNum
    );

    setTrip(prev => {
      if (!prev) return null;
      const updatedItinerary = [...prev.itinerary];
      const targetDay = updatedItinerary[updatedItinerary.length - 1];
      if (targetDay && targetDay.title.includes('Suggesting Title...')) {
        updatedItinerary[updatedItinerary.length - 1] = { ...targetDay, title: suggestedTitle };
      }
      return { ...prev, itinerary: updatedItinerary };
    });
  };

  const updateDay = (index: number, updates: Partial<ItineraryDay>) => {
    const newItinerary = [...trip.itinerary];
    newItinerary[index] = { ...newItinerary[index], ...updates };
    setTrip({ ...trip, itinerary: newItinerary });
  };

  const handleAiDescription = async (index: number) => {
    const day = trip.itinerary[index];
    if (!day.title) return;

    setIsAiGenerating(true);
    const activities = day.activityIds.map(aid => ACTIVITIES.find(a => a.id === aid)?.name || '');
    const description = await generateDayDescription(day.title, activities);
    updateDay(index, { clientNotes: description });
    setIsAiGenerating(false);
  };

  const handleDownloadPdf = async () => {
    if (!trip || isDownloading) return;
    setIsDownloading(true);

    try {
      const h2p = (window as any).html2pdf;
      if (!h2p) throw new Error("PDF library not ready.");

      const renderZone = document.getElementById('pdf-render-zone');
      if (!renderZone) return;

      renderZone.style.visibility = 'visible';
      renderZone.style.backgroundColor = 'white';

      renderZone.innerHTML = `
