  // Load custom hotels from localStorage
  useEffect(() => {
    const saved = localStorage.getItem('et_hotels');
    if (saved) {
      setCustomHotels(JSON.parse(saved));
    }
  }, []);

  // Combine static and custom hotels
  const allHotels = useMemo(() => [...HOTELS, ...customHotels], [customHotels]);

  const filteredHotels = useMemo(() => {
    return allHotels.filter(hotel => {
      const matchesSearch = hotel.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                           hotel.location.toLowerCase().includes(searchTerm.toLowerCase());
      const matchesCategory = categoryFilter === 'All' || hotel.category === categoryFilter;
      return matchesSearch && matchesCategory;
    });
  }, [allHotels, searchTerm, categoryFilter]);

  // Group hotels by Location (Destination)
  const groupedHotels = useMemo(() => {
    const groups: Record<string, Hotel[]> = {};

    filteredHotels.forEach(hotel => {
      if (!groups[hotel.location]) {
        groups[hotel.location] = [];
      }
      groups[hotel.location].push(hotel);
    });

    return groups;
  }, [filteredHotels]);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setFormData({
          ...formData,
          attachmentName: file.name,
          attachmentType: file.type,
          attachmentData: reader.result as string
        });
      };
      reader.readAsDataURL(file);
    }
  };

  const handleAddHotel = (e: React.FormEvent) => {
    e.preventDefault();
    const newHotel: Hotel = {
      id: `h-custom-${Date.now()}`,
      name: formData.name || '',
      location: formData.location || '',
      category: formData.category || HotelCategory.DELUXE,
      ratePerNight: formData.ratePerNight || 0,
      contact: formData.contact || '',
      ...formData
    } as Hotel;

    const updated = [...customHotels, newHotel];
    setCustomHotels(updated);
    localStorage.setItem('et_hotels', JSON.stringify(updated));

    // Reset and close
    setFormData({
      name: '',
      location: '',
      category: HotelCategory.DELUXE,
      ratePerNight: 5000,
      contact: '',
      extraBedRate: undefined,
      epRate: undefined,
      cpRate: undefined,
      mapRate: undefined,
      apRate: undefined,
      internalNotes: '',
      hotelLink: '',
      attachmentName: '',
      attachmentData: ''
    });
    setIsModalOpen(false);
  };

  const destinations = Object.keys(groupedHotels).sort();

  return (
    <div className="space-y-8 pb-20">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-slate-900">Hotel Inventory</h1>
          <p className="text-slate-500 text-sm">Organized by destination with detailed meal plan pricing.</p>
        </div>
        <button 
          onClick={() => setIsModalOpen(true)}
          className="bg-blue-600 text-white px-5 py-2.5 rounded-xl font-bold flex items-center gap-2 hover:bg-blue-700 shadow-lg shadow-blue-100 transition-all active:scale-95"
        >
          <Plus size={18} /> Add New Hotel
        </button>
      </div>

      {/* Destination Stats Quick View */}
      <div className="flex gap-4 overflow-x-auto pb-2 no-scrollbar">
        {destinations.map(dest => (
          <div key={dest} className="bg-white px-4 py-2 rounded-xl border border-slate-200 flex items-center gap-3 shrink-0 shadow-sm">
            <div className="w-2 h-2 rounded-full bg-blue-500" />
            <span className="text-xs font-bold text-slate-700">{dest}</span>
            <span className="text-[10px] font-black bg-slate-100 text-slate-500 px-1.5 py-0.5 rounded">
              {groupedHotels[dest].length}
            </span>
          </div>
        ))}
      </div>

      {/* Filters Bar */}
      <div className="bg-white p-4 rounded-2xl border border-slate-200 shadow-sm flex flex-wrap items-center gap-4">
        <div className="flex-1 min-w-[300px] relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
          <input 
            type="text" 
            placeholder="Search hotel name or location..." 
            className="w-full pl-10 pr-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm text-slate-900 focus:ring-2 focus:ring-blue-500 outline-none transition-all"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
        <div className="flex items-center gap-2 bg-slate-50 border border-slate-200 rounded-xl px-3 py-1">
          <Layers size={16} className="text-slate-400" />
          <select 
            className="bg-transparent py-2 text-sm text-slate-900 font-bold outline-none"
            value={categoryFilter}
            onChange={(e) => setCategoryFilter(e.target.value)}
          >
            <option value="All">All Categories</option>
            {Object.values(HotelCategory).map(c => <option key={c} value={c}>{c}</option>)}
          </select>
        </div>
      </div>

      {/* Destination Grouped View */}
      <div className="space-y-12">
        {destinations.length > 0 ? (
          destinations.map((location) => (
            <section key={location} className="space-y-6">
              <div className="flex items-center gap-4">
                <div className="bg-slate-900 text-white p-2 rounded-xl">
                  <MapPin size={20} />
                </div>
                <h2 className="text-xl font-black text-slate-800 uppercase tracking-widest flex items-center gap-3">
                  {location}
                  <span className="text-slate-300 font-normal">/</span>
                  <span className="text-slate-400 text-sm font-bold">{groupedHotels[location].length} Hotels</span>
                </h2>
                <div className="flex-1 h-px bg-slate-200"></div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
                {groupedHotels[location].map(hotel => (
                  <div key={hotel.id} className="bg-white border border-slate-200 rounded-2xl overflow-hidden hover:shadow-xl hover:border-blue-200 transition-all group flex flex-col h-full shadow-sm">
                    <div className="relative h-32 bg-slate-100 overflow-hidden">
                      <img 
                        src={`https://picsum.photos/seed/${hotel.id}/400/200`} 
                        className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700 opacity-80" 
                        alt={hotel.name}
                      />
                      <div className="absolute top-3 left-3">
                        <span className="flex items-center gap-1.5 px-2 py-1 bg-white/90 backdrop-blur border border-slate-200 rounded-lg text-[9px] font-black uppercase tracking-widest text-slate-700 shadow-sm">
                          <CategoryIcon category={hotel.category} />
                          {hotel.category}
                        </span>
                      </div>
                    </div>

                    <div className="p-5 flex flex-col flex-1">
                      <div className="flex justify-between items-start mb-2">
                        <h3 className="font-bold text-slate-800 text-base group-hover:text-blue-600 transition-colors leading-tight">
                          {hotel.name}
                        </h3>
                        {hotel.hotelLink && (
                          <a href={hotel.hotelLink} target="_blank" rel="noopener noreferrer" className="text-slate-400 hover:text-blue-600">
                            <ExternalLink size={14} />
                          </a>
                        )}
                      </div>

                      {/* Summary Rates */}
                      <div className="grid grid-cols-2 gap-2 mt-2">
                        {hotel.cpRate && <div className="text-[10px] bg-emerald-50 text-emerald-700 px-2 py-1 rounded font-bold">CP: ₹{hotel.cpRate.toLocaleString()}</div>}
                        {hotel.mapRate && <div className="text-[10px] bg-blue-50 text-blue-700 px-2 py-1 rounded font-bold">MAP: ₹{hotel.mapRate.toLocaleString()}</div>}
                        {hotel.extraBedRate && <div className="text-[10px] bg-amber-50 text-amber-700 px-2 py-1 rounded font-bold">Ex-Bed: ₹{hotel.extraBedRate.toLocaleString()}</div>}
                      </div>

                      <div className="mt-auto space-y-3 pt-4 border-t border-slate-50">
                        <div className="flex items-center justify-between">
                          <span className="text-[10px] font-black uppercase text-slate-400">Base Rate</span>
                          <span className="text-lg font-black text-slate-900">₹{hotel.ratePerNight.toLocaleString()}</span>
                        </div>
                        <div className="flex items-center gap-2 text-xs font-semibold text-slate-500 bg-slate-50 p-2 rounded-lg truncate">
                          <Phone size={14} className="text-slate-400 shrink-0" />
                          {hotel.contact}
                        </div>
                        {hotel.attachmentName && (
                          <div className="flex items-center gap-2 text-[10px] font-bold text-blue-600 bg-blue-50 p-1.5 rounded-md truncate">
                            <Paperclip size={10} className="shrink-0" />
                            {hotel.attachmentName}
                          </div>
                        )}
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            </section>
          ))
        ) : (
          <div className="text-center py-20 bg-white border-2 border-dashed border-slate-200 rounded-3xl">
            <HotelIcon size={48} className="mx-auto text-slate-200 mb-4" />
            <h3 className="text-lg font-bold text-slate-400">No hotels found matching filters</h3>
            <button 
              onClick={() => { setSearchTerm(''); setCategoryFilter('All'); }}
              className="mt-4 text-blue-600 font-bold hover:underline"
            >
              Reset Search
            </button>
          </div>
        )}
      </div>

      {/* Add Hotel Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-50 flex items-center justify-center p-4 overflow-y-auto">
          <div className="bg-white rounded-3xl shadow-2xl w-full max-w-2xl my-8 overflow-hidden animate-in zoom-in-95 duration-200">
            <div className="bg-slate-50 p-6 border-b border-slate-100 flex items-center justify-between sticky top-0 z-10">
              <div className="flex items-center gap-3">
                <div className="bg-blue-600 p-2 rounded-xl text-white">
                  <HotelIcon size={20} />
                </div>
                <div>
                  <h3 className="font-bold text-slate-900">Add Detailed Hotel Entry</h3>
                  <p className="text-xs text-slate-500">Fill operational details and meal plan rates.</p>
                </div>
              </div>
              <button 
                onClick={() => setIsModalOpen(false)}
                className="p-2 hover:bg-slate-200 rounded-full transition-colors"
              >
                <X size={20} className="text-slate-400" />
              </button>
            </div>

            <form onSubmit={handleAddHotel} className="p-8 space-y-8">
              {/* Basic Details */}
              <div className="space-y-4">
                <h4 className="text-xs font-black uppercase tracking-widest text-blue-600 border-b border-blue-50 pb-2">Basic Information</h4>
                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-2 col-span-2">
                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">Hotel Name</label>
                    <input 
                      required
                      type="text"
                      placeholder="e.g. Grand Palace Resort"
                      className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm focus:ring-2 focus:ring-blue-500 outline-none"
                      value={formData.name}
                      onChange={e => setFormData({...formData, name: e.target.value})}
                    />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">Location (City/Destination)</label>
                    <input 
                      required
                      type="text"
                      placeholder="e.g. Srinagar"
                      className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm focus:ring-2 focus:ring-blue-500 outline-none"
                      value={formData.location}
                      onChange={e => setFormData({...formData, location: e.target.value})}
                    />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">Inventory Category</label>
                    <select 
                      className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm focus:ring-2 focus:ring-blue-500 outline-none font-medium"
                      value={formData.category}
                      onChange={e => setFormData({...formData, category: e.target.value as HotelCategory})}
                    >
                      {Object.values(HotelCategory).map(c => <option key={c} value={c}>{c}</option>)}
                    </select>
                  </div>
                </div>
              </div>

              {/* Rates Section */}
              <div className="space-y-4">
                <h4 className="text-xs font-black uppercase tracking-widest text-blue-600 border-b border-blue-50 pb-2">Meal Plans & Extra Bed Rates</h4>
                <div className="grid grid-cols-3 gap-4">
                  <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">EP Rate (Room Only)</label>
                    <input 
                      type="number"
                      placeholder="Optional"
                      className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none"
                      value={formData.epRate || ''}
                      onChange={e => setFormData({...formData, epRate: parseInt(e.target.value) || undefined})}
                    />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">CP Rate (Room+Bf)</label>
                    <input 
                      type="number"
                      placeholder="Optional"
                      className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none"
                      value={formData.cpRate || ''}
                      onChange={e => setFormData({...formData, cpRate: parseInt(e.target.value) || undefined})}
                    />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">MAP Rate (Room+Bf+Meal)</label>
                    <input 
                      type="number"
                      placeholder="Optional"
                      className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none"
                      value={formData.mapRate || ''}
                      onChange={e => setFormData({...formData, mapRate: parseInt(e.target.value) || undefined})}
                    />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">AP Rate (All Meals)</label>
                    <input 
                      type="number"
                      placeholder="Optional"
                      className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none"
                      value={formData.apRate || ''}
                      onChange={e => setFormData({...formData, apRate: parseInt(e.target.value) || undefined})}
                    />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">Extra Bed Rate</label>
                    <input 
                      type="number"
                      placeholder="Optional"
                      className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none"
                      value={formData.extraBedRate || ''}
                      onChange={e => setFormData({...formData, extraBedRate: parseInt(e.target.value) || undefined})}
                    />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">Base/Standard Rate</label>
                    <input 
                      required
                      type="number"
                      className="w-full px-4 py-2 bg-blue-50 border border-blue-100 rounded-xl text-sm font-bold text-blue-900 outline-none"
                      value={formData.ratePerNight}
                      onChange={e => setFormData({...formData, ratePerNight: parseInt(e.target.value) || 0})}
                    />
                  </div>
                </div>
              </div>

              {/* Operational details */}
              <div className="space-y-4">
                <h4 className="text-xs font-black uppercase tracking-widest text-blue-600 border-b border-blue-50 pb-2">Operational & Files</h4>
                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">Contact/Front Desk</label>
                    <input 
                      required
                      type="text"
                      placeholder="+91..."
                      className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none"
                      value={formData.contact}
                      onChange={e => setFormData({...formData, contact: e.target.value})}
                    />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">Website/Portal Link</label>
                    <div className="relative">
                      <LinkIcon className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-300" size={14} />
                      <input 
                        type="url"
                        placeholder="https://..."
                        className="w-full pl-9 pr-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none"
                        value={formData.hotelLink}
                        onChange={e => setFormData({...formData, hotelLink: e.target.value})}
                      />
                    </div>
                  </div>
                  <div className="space-y-2 col-span-2">
                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">Internal Operational Notes</label>
                    <textarea 
                      placeholder="e.g. Free room upgrades for Honeymooners, Check-in at 12 PM..."
                      rows={3}
                      className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none resize-none"
                      value={formData.internalNotes}
                      onChange={e => setFormData({...formData, internalNotes: e.target.value})}
                    />
                  </div>
                  <div className="space-y-2 col-span-2">
                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">Attachments (PDF, JPG, XLS)</label>
                    <div className="flex items-center gap-3 p-4 border-2 border-dashed border-slate-200 rounded-2xl bg-slate-50 hover:bg-slate-100 transition-colors cursor-pointer relative">
                      <input 
                        type="file" 
                        ref={fileInputRef}
                        className="absolute inset-0 opacity-0 cursor-pointer"
                        onChange={handleFileChange}
                        accept=".pdf,.jpg,.jpeg,.png,.xls,.xlsx"
                      />
                      <div className="bg-white p-2 rounded-lg shadow-sm">
                        <Paperclip size={20} className="text-blue-500" />
                      </div>
                      <div className="flex-1">
                        <p className="text-xs font-bold text-slate-700">
                          {formData.attachmentName || 'Click to upload rate sheet or contract'}
                        </p>
                        <p className="text-[10px] text-slate-400 uppercase tracking-widest font-black">Max 5MB • PDF / JPG / Excel</p>
                      </div>
                      {formData.attachmentName && (
                        <button 
                          type="button" 
                          onClick={(e) => { e.stopPropagation(); setFormData({...formData, attachmentName: '', attachmentData: ''}); }}
                          className="p-1.5 hover:bg-red-50 text-red-400 rounded-md"
                        >
                          <X size={14} />
                        </button>
                      )}
                    </div>
                  </div>
                </div>
              </div>

              <div className="pt-6 flex gap-3 sticky bottom-0 bg-white pb-2">
                <button 
                  type="button"
                  onClick={() => setIsModalOpen(false)}
                  className="flex-1 py-3 text-slate-500 font-bold hover:bg-slate-50 rounded-xl transition-colors"
                >
                  Cancel
                </button>
                <button 
                  type="submit"
                  className="flex-1 py-3 bg-blue-600 text-white font-bold rounded-xl shadow-lg shadow-blue-100 hover:bg-blue-700 transition-all flex items-center justify-center gap-2"
                >
                  <Check size={18} />
                  Save Hotel to Inventory
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default Hotels;

export enum UserRole {
  ADMIN = 'ADMIN',
  SALES = 'SALES',
  OPERATIONS = 'OPERATIONS'
}

export enum TripStatus {
  LEAD = 'Lead',
  QUOTED = 'Quoted',
  BOOKED = 'Booked',
  COMPLETED = 'Completed',
  CANCELLED = 'Cancelled'
}

export enum TripType {
  HONEYMOON = 'Honeymoon',
  FAMILY = 'Family',
  GROUP = 'Group',
  CORPORATE = 'Corporate'
}

export enum HotelCategory {
  BUDGET = 'Budget',
  DELUXE = 'Deluxe',
  LUXURY = 'Luxury',
  HOUSEBOAT = 'Houseboat'
}

export interface Hotel {
  id: string;
  name: string;
  location: string;
  category: HotelCategory;
  ratePerNight: number;
  contact: string;
  // Rate Validity
  rateValidityDate?: string;
  // Optional detailed rates
  extraBedRate?: number;
  epRate?: number;
  cpRate?: number;
  mapRate?: number;
  apRate?: number;
  // Metadata
  internalNotes?: string;
  hotelLink?: string;
  attachmentName?: string;
  attachmentType?: string;
  attachmentData?: string; // base64 string
}

export interface Vehicle {
  id: string;
  type: string;
  capacity: number;
  ratePerDay: number;
}

export interface Activity {
  id: string;
  name: string;
  costPerPax: number;
  description: string;
}

export interface AddOn {
  id: string;
  name: string;
  cost: number;
  isPerPax: boolean;
}

export interface ItineraryDay {
  id: string;
  dayNumber: number;
  title: string;
  hotelId?: string;
  vehicleId?: string;
  activityIds: string[];
  clientNotes: string;
  internalNotes: string;
}

export interface TripVersion {
  id: string;
  timestamp: string;
  itinerary: ItineraryDay[];
  marginPercentage: number;
  addOnIds: string[];
  label: string;
}

export interface Client {
  name: string;
  phone: string;
  email: string;
  source: string;
}

export interface Trip {
  id: string;
  client: Client;
  tripName: string;
  tripType: TripType;
  startDate: string;
  endDate: string;
  pax: number;
  budgetRange: string;
  assignedSalesperson: string;
  status: TripStatus;
  itinerary: ItineraryDay[];
  marginPercentage: number;
  addOnIds: string[];
  versions: TripVersion[];
}

export interface DashboardStats {
  activeLeads: number;
  totalRevenue: number;
  bookedTrips: number;
  conversionRate: number;
}

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { 
  Search, 
  Hotel as HotelIcon, 
  MapPin, 
  Phone, 
  Plus, 
  Layers, 
  Anchor, 
  Stars, 
  Wallet, 
  X, 
  Check, 
  Link as LinkIcon, 
  FileText, 
  Info, 
  Paperclip, 
  ExternalLink,
  Edit2,
  AlertTriangle,
  Calendar
} from 'lucide-react';
import { HOTELS } from '../constants';
import { HotelCategory, Hotel } from '../types';

const CategoryIcon = ({ category }: { category: HotelCategory }) => {
  switch (category) {
    case HotelCategory.LUXURY: return <Stars size={14} className="text-amber-500" />;
    case HotelCategory.DELUXE: return <Layers size={14} className="text-blue-500" />;
    case HotelCategory.HOUSEBOAT: return <Anchor size={14} className="text-cyan-500" />;
    case HotelCategory.BUDGET: return <Wallet size={14} className="text-slate-500" />;
    default: return <HotelIcon size={14} />;
  }
};

const Hotels: React.FC = () => {
  const [searchTerm, setSearchTerm] = useState('');
  const [categoryFilter, setCategoryFilter] = useState('All');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingHotelId, setEditingHotelId] = useState<string | null>(null);
  const [customHotels, setCustomHotels] = useState<Hotel[]>([]);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Form State
  const initialFormState: Partial<Hotel> = {
    name: '',
    location: '',
    category: HotelCategory.DELUXE,
    ratePerNight: 5000,
    contact: '',
    rateValidityDate: '',
    extraBedRate: undefined,
    epRate: undefined,
    cpRate: undefined,
    mapRate: undefined,
    apRate: undefined,
    internalNotes: '',
    hotelLink: '',
    attachmentName: '',
    attachmentData: ''
  };

  const [formData, setFormData] = useState<Partial<Hotel>>(initialFormState);

  // Load custom hotels from localStorage
  useEffect(() => {
    const saved = localStorage.getItem('et_hotels');
    if (saved) {
      setCustomHotels(JSON.parse(saved));
    }
  }, []);

  // Combine static and custom hotels
  const allHotels = useMemo(() => {
    // We filter out any static hotels that have been "replaced" by a custom one with the same ID
    const customIds = new Set(customHotels.map(h => h.id));
    return [...HOTELS.filter(h => !customIds.has(h.id)), ...customHotels];
  }, [customHotels]);

  const filteredHotels = useMemo(() => {
    return allHotels.filter(hotel => {
      const matchesSearch = hotel.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                           hotel.location.toLowerCase().includes(searchTerm.toLowerCase());
      const matchesCategory = categoryFilter === 'All' || hotel.category === categoryFilter;
      return matchesSearch && matchesCategory;
    });
  }, [allHotels, searchTerm, categoryFilter]);

  // Group hotels by Location (Destination)
  const groupedHotels = useMemo(() => {
    const groups: Record<string, Hotel[]> = {};

    filteredHotels.forEach(hotel => {
      if (!groups[hotel.location]) {
        groups[hotel.location] = [];
      }
      groups[hotel.location].push(hotel);
    });

    return groups;
  }, [filteredHotels]);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setFormData({
          ...formData,
          attachmentName: file.name,
          attachmentType: file.type,
          attachmentData: reader.result as string
        });
      };
      reader.readAsDataURL(file);
    }
  };

  const openAddModal = () => {
    setEditingHotelId(null);
    setFormData(initialFormState);
    setIsModalOpen(true);
  };

  const openEditModal = (hotel: Hotel) => {
    setEditingHotelId(hotel.id);
    setFormData({ ...hotel });
    setIsModalOpen(true);
  };

  const handleSaveHotel = (e: React.FormEvent) => {
    e.preventDefault();

    const hotelData: Hotel = {
      id: editingHotelId || `h-custom-${Date.now()}`,
      name: formData.name || '',
      location: formData.location || '',
      category: formData.category || HotelCategory.DELUXE,
      ratePerNight: formData.ratePerNight || 0,
      contact: formData.contact || '',
      ...formData
    } as Hotel;

    let updated: Hotel[];
    if (editingHotelId) {
      const index = customHotels.findIndex(h => h.id === editingHotelId);
      if (index > -1) {
        updated = [...customHotels];
        updated[index] = hotelData;
      } else {
        // This was a static hotel being edited for the first time
        updated = [...customHotels, hotelData];
      }
    } else {
      updated = [...customHotels, hotelData];
    }

    setCustomHotels(updated);
    localStorage.setItem('et_hotels', JSON.stringify(updated));

    setFormData(initialFormState);
    setIsModalOpen(false);
  };

  const checkRateValidity = (dateStr?: string) => {
    if (!dateStr) return { status: 'none', label: '' };
    const expiry = new Date(dateStr);
    const today = new Date();
    const diffTime = expiry.getTime() - today.getTime();
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

    if (diffDays < 0) return { status: 'expired', label: 'Rate Expired' };
    if (diffDays <= 15) return { status: 'warning', label: `Expires in ${diffDays}d` };
    return { status: 'valid', label: `Valid until ${new Date(dateStr).toLocaleDateString('en-IN', { day: 'numeric', month: 'short' })}` };
  };

  const destinations = Object.keys(groupedHotels).sort();

  return (
    <div className="space-y-8 pb-20">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-slate-900">Hotel Inventory</h1>
          <p className="text-slate-500 text-sm">Manage seasonal rates and operational data across destinations.</p>
        </div>
        <button 
          onClick={openAddModal}
          className="bg-blue-600 text-white px-5 py-2.5 rounded-xl font-bold flex items-center gap-2 hover:bg-blue-700 shadow-lg shadow-blue-100 transition-all active:scale-95"
        >
          <Plus size={18} /> Add New Hotel
        </button>
      </div>

      {/* Destination Stats Quick View */}
      <div className="flex gap-4 overflow-x-auto pb-2 no-scrollbar">
        {destinations.map(dest => (
          <div key={dest} className="bg-white px-4 py-2 rounded-xl border border-slate-200 flex items-center gap-3 shrink-0 shadow-sm">
            <div className="w-2 h-2 rounded-full bg-blue-500" />
            <span className="text-xs font-bold text-slate-700">{dest}</span>
            <span className="text-[10px] font-black bg-slate-100 text-slate-500 px-1.5 py-0.5 rounded">
              {groupedHotels[dest].length}
            </span>
          </div>
        ))}
      </div>

      {/* Filters Bar */}
      <div className="bg-white p-4 rounded-2xl border border-slate-200 shadow-sm flex flex-wrap items-center gap-4">
        <div className="flex-1 min-w-[300px] relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
          <input 
            type="text" 
            placeholder="Search hotel name or location..." 
            className="w-full pl-10 pr-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm text-slate-900 focus:ring-2 focus:ring-blue-500 outline-none transition-all"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
        <div className="flex items-center gap-2 bg-slate-50 border border-slate-200 rounded-xl px-3 py-1">
          <Layers size={16} className="text-slate-400" />
          <select 
            className="bg-transparent py-2 text-sm text-slate-900 font-bold outline-none"
            value={categoryFilter}
            onChange={(e) => setCategoryFilter(e.target.value)}
          >
            <option value="All">All Categories</option>
            {Object.values(HotelCategory).map(c => <option key={c} value={c}>{c}</option>)}
          </select>
        </div>
      </div>

      {/* Destination Grouped View */}
      <div className="space-y-12">
        {destinations.length > 0 ? (
          destinations.map((location) => (
            <section key={location} className="space-y-6">
              <div className="flex items-center gap-4">
                <div className="bg-slate-900 text-white p-2 rounded-xl">
                  <MapPin size={20} />
                </div>
                <h2 className="text-xl font-black text-slate-800 uppercase tracking-widest flex items-center gap-3">
                  {location}
                  <span className="text-slate-300 font-normal">/</span>
                  <span className="text-slate-400 text-sm font-bold">{groupedHotels[location].length} Hotels</span>
                </h2>
                <div className="flex-1 h-px bg-slate-200"></div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
                {groupedHotels[location].map(hotel => {
                  const validity = checkRateValidity(hotel.rateValidityDate);
                  return (
                    <div key={hotel.id} className="bg-white border border-slate-200 rounded-2xl overflow-hidden hover:shadow-xl hover:border-blue-200 transition-all group flex flex-col h-full shadow-sm relative">
                      <div className="relative h-32 bg-slate-100 overflow-hidden">
                        <img 
                          src={`https://picsum.photos/seed/${hotel.id}/400/200`} 
                          className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700 opacity-80" 
                          alt={hotel.name}
                        />
                        <div className="absolute top-3 left-3 flex flex-col gap-2">
                          <span className="flex items-center gap-1.5 px-2 py-1 bg-white/90 backdrop-blur border border-slate-200 rounded-lg text-[9px] font-black uppercase tracking-widest text-slate-700 shadow-sm">
                            <CategoryIcon category={hotel.category} />
                            {hotel.category}
                          </span>
                          {validity.status !== 'none' && (
                            <span className={`flex items-center gap-1 px-2 py-1 rounded-lg text-[9px] font-black uppercase tracking-widest shadow-sm ${
                              validity.status === 'expired' ? 'bg-red-500 text-white' : 
                              validity.status === 'warning' ? 'bg-amber-500 text-white' : 'bg-emerald-500 text-white'
                            }`}>
                              {validity.status === 'expired' ? <AlertTriangle size={10} /> : <Calendar size={10} />}
                              {validity.label}
                            </span>
                          )}
                        </div>
                        <button 
                          onClick={() => openEditModal(hotel)}
                          className="absolute top-3 right-3 p-2 bg-white/90 backdrop-blur rounded-full text-slate-400 hover:text-blue-600 hover:bg-white transition-all shadow-sm opacity-0 group-hover:opacity-100"
                        >
                          <Edit2 size={14} />
                        </button>
                      </div>

                      <div className="p-5 flex flex-col flex-1">
                        <div className="flex justify-between items-start mb-2">
                          <h3 className="font-bold text-slate-800 text-base group-hover:text-blue-600 transition-colors leading-tight">
                            {hotel.name}
                          </h3>
                          {hotel.hotelLink && (
                            <a href={hotel.hotelLink} target="_blank" rel="noopener noreferrer" className="text-slate-400 hover:text-blue-600">
                              <ExternalLink size={14} />
                            </a>
                          )}
                        </div>

                        {/* Summary Rates */}
                        <div className="grid grid-cols-2 gap-2 mt-2">
                          {hotel.cpRate && <div className="text-[10px] bg-emerald-50 text-emerald-700 px-2 py-1 rounded font-bold">CP: ₹{hotel.cpRate.toLocaleString()}</div>}
                          {hotel.mapRate && <div className="text-[10px] bg-blue-50 text-blue-700 px-2 py-1 rounded font-bold">MAP: ₹{hotel.mapRate.toLocaleString()}</div>}
                          {hotel.extraBedRate && <div className="text-[10px] bg-amber-50 text-amber-700 px-2 py-1 rounded font-bold">Ex-Bed: ₹{hotel.extraBedRate.toLocaleString()}</div>}
                        </div>

                        <div className="mt-auto space-y-3 pt-4 border-t border-slate-50">
                          <div className="flex items-center justify-between">
                            <span className="text-[10px] font-black uppercase text-slate-400">Base Rate</span>
                            <span className="text-lg font-black text-slate-900">₹{hotel.ratePerNight.toLocaleString()}</span>
                          </div>
                          <div className="flex items-center gap-2 text-xs font-semibold text-slate-500 bg-slate-50 p-2 rounded-lg truncate">
                            <Phone size={14} className="text-slate-400 shrink-0" />
                            {hotel.contact}
                          </div>
                          {hotel.attachmentName && (
                            <div className="flex items-center gap-2 text-[10px] font-bold text-blue-600 bg-blue-50 p-1.5 rounded-md truncate">
                              <Paperclip size={10} className="shrink-0" />
                              {hotel.attachmentName}
                            </div>
                          )}
                        </div>
                      </div>
                    </div>
                  );
                })}
              </div>
            </section>
          ))
        ) : (
          <div className="text-center py-20 bg-white border-2 border-dashed border-slate-200 rounded-3xl">
            <HotelIcon size={48} className="mx-auto text-slate-200 mb-4" />
            <h3 className="text-lg font-bold text-slate-400">No hotels found matching filters</h3>
            <button 
              onClick={() => { setSearchTerm(''); setCategoryFilter('All'); }}
              className="mt-4 text-blue-600 font-bold hover:underline"
            >
              Reset Search
            </button>
          </div>
        )}
      </div>

      {/* Add/Edit Hotel Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-50 flex items-center justify-center p-4 overflow-y-auto">
          <div className="bg-white rounded-3xl shadow-2xl w-full max-w-2xl my-8 overflow-hidden animate-in zoom-in-95 duration-200">
            <div className="bg-slate-50 p-6 border-b border-slate-100 flex items-center justify-between sticky top-0 z-10">
              <div className="flex items-center gap-3">
                <div className="bg-blue-600 p-2 rounded-xl text-white">
                  {editingHotelId ? <Edit2 size={20} /> : <HotelIcon size={20} />}
                </div>
                <div>
                  <h3 className="font-bold text-slate-900">{editingHotelId ? 'Edit Hotel Details' : 'Add Detailed Hotel Entry'}</h3>
                  <p className="text-xs text-slate-500">Fill operational details and meal plan rates.</p>
                </div>
              </div>
              <button 
                onClick={() => setIsModalOpen(false)}
                className="p-2 hover:bg-slate-200 rounded-full transition-colors"
              >
                <X size={20} className="text-slate-400" />
              </button>
            </div>

            <form onSubmit={handleSaveHotel} className="p-8 space-y-8">
              {/* Basic Details */}
              <div className="space-y-4">
                <h4 className="text-xs font-black uppercase tracking-widest text-blue-600 border-b border-blue-50 pb-2">Basic Information</h4>
                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-2 col-span-2">
                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">Hotel Name</label>
                    <input 
                      required
                      type="text"
                      placeholder="e.g. Grand Palace Resort"
                      className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm focus:ring-2 focus:ring-blue-500 outline-none"
                      value={formData.name}
                      onChange={e => setFormData({...formData, name: e.target.value})}
                    />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">Location (City/Destination)</label>
                    <input 
                      required
                      type="text"
                      placeholder="e.g. Srinagar"
                      className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm focus:ring-2 focus:ring-blue-500 outline-none"
                      value={formData.location}
                      onChange={e => setFormData({...formData, location: e.target.value})}
                    />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">Inventory Category</label>
                    <select 
                      className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm focus:ring-2 focus:ring-blue-500 outline-none font-medium"
                      value={formData.category}
                      onChange={e => setFormData({...formData, category: e.target.value as HotelCategory})}
                    >
                      {Object.values(HotelCategory).map(c => <option key={c} value={c}>{c}</option>)}
                    </select>
                  </div>
                </div>
              </div>

              {/* Rates Section */}
              <div className="space-y-4">
                <h4 className="text-xs font-black uppercase tracking-widest text-blue-600 border-b border-blue-50 pb-2">Meal Plans & Extra Bed Rates</h4>
                <div className="grid grid-cols-3 gap-4">
                  <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">EP Rate (Room Only)</label>
                    <input 
                      type="number"
                      placeholder="Optional"
                      className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none"
                      value={formData.epRate || ''}
                      onChange={e => setFormData({...formData, epRate: parseInt(e.target.value) || undefined})}
                    />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">CP Rate (Room+Bf)</label>
                    <input 
                      type="number"
                      placeholder="Optional"
                      className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none"
                      value={formData.cpRate || ''}
                      onChange={e => setFormData({...formData, cpRate: parseInt(e.target.value) || undefined})}
                    />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">MAP Rate (Room+Bf+Meal)</label>
                    <input 
                      type="number"
                      placeholder="Optional"
                      className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none"
                      value={formData.mapRate || ''}
                      onChange={e => setFormData({...formData, mapRate: parseInt(e.target.value) || undefined})}
                    />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">AP Rate (All Meals)</label>
                    <input 
                      type="number"
                      placeholder="Optional"
                      className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none"
                      value={formData.apRate || ''}
                      onChange={e => setFormData({...formData, apRate: parseInt(e.target.value) || undefined})}
                    />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">Extra Bed Rate</label>
                    <input 
                      type="number"
                      placeholder="Optional"
                      className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none"
                      value={formData.extraBedRate || ''}
                      onChange={e => setFormData({...formData, extraBedRate: parseInt(e.target.value) || undefined})}
                    />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">Base/Standard Rate</label>
                    <input 
                      required
                      type="number"
                      className="w-full px-4 py-2 bg-blue-50 border border-blue-100 rounded-xl text-sm font-bold text-blue-900 outline-none"
                      value={formData.ratePerNight}
                      onChange={e => setFormData({...formData, ratePerNight: parseInt(e.target.value) || 0})}
                    />
                  </div>
                </div>
              </div>

              {/* Validity Section */}
              <div className="space-y-4">
                <h4 className="text-xs font-black uppercase tracking-widest text-blue-600 border-b border-blue-50 pb-2">Rate Validity (Till Date)</h4>
                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">Rates Valid Until</label>
                    <div className="relative">
                      <Calendar className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-300" size={14} />
                      <input 
                        type="date"
                        className="w-full pl-9 pr-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none font-medium"
                        value={formData.rateValidityDate}
                        onChange={e => setFormData({...formData, rateValidityDate: e.target.value})}
                      />
                    </div>
                    <p className="text-[9px] text-slate-400 italic">Operational alert will trigger 15 days before this date.</p>
                  </div>
                </div>
              </div>

              {/* Operational details */}
              <div className="space-y-4">
                <h4 className="text-xs font-black uppercase tracking-widest text-blue-600 border-b border-blue-50 pb-2">Operational & Files</h4>
                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">Contact/Front Desk</label>
                    <input 
                      required
                      type="text"
                      placeholder="+91..."
                      className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none"
                      value={formData.contact}
                      onChange={e => setFormData({...formData, contact: e.target.value})}
                    />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">Website/Portal Link</label>
                    <div className="relative">
                      <LinkIcon className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-300" size={14} />
                      <input 
                        type="url"
                        placeholder="https://..."
                        className="w-full pl-9 pr-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none"
                        value={formData.hotelLink}
                        onChange={e => setFormData({...formData, hotelLink: e.target.value})}
                      />
                    </div>
                  </div>
                  <div className="space-y-2 col-span-2">
                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">Internal Operational Notes</label>
                    <textarea 
                      placeholder="e.g. Free room upgrades for Honeymooners, Check-in at 12 PM..."
                      rows={3}
                      className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none resize-none"
                      value={formData.internalNotes}
                      onChange={e => setFormData({...formData, internalNotes: e.target.value})}
                    />
                  </div>
                  <div className="space-y-2 col-span-2">
                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">Attachments (PDF, JPG, XLS)</label>
                    <div className="flex items-center gap-3 p-4 border-2 border-dashed border-slate-200 rounded-2xl bg-slate-50 hover:bg-slate-100 transition-colors cursor-pointer relative">
                      <input 
                        type="file" 
                        ref={fileInputRef}
                        className="absolute inset-0 opacity-0 cursor-pointer"
                        onChange={handleFileChange}
                        accept=".pdf,.jpg,.jpeg,.png,.xls,.xlsx"
                      />
                      <div className="bg-white p-2 rounded-lg shadow-sm">
                        <Paperclip size={20} className="text-blue-500" />
                      </div>
                      <div className="flex-1">
                        <p className="text-xs font-bold text-slate-700">
                          {formData.attachmentName || 'Click to upload rate sheet or contract'}
                        </p>
                        <p className="text-[10px] text-slate-400 uppercase tracking-widest font-black">Max 5MB • PDF / JPG / Excel</p>
                      </div>
                      {formData.attachmentName && (
                        <button 
                          type="button" 
                          onClick={(e) => { e.stopPropagation(); setFormData({...formData, attachmentName: '', attachmentData: ''}); }}
                          className="p-1.5 hover:bg-red-50 text-red-400 rounded-md"
                        >
                          <X size={14} />
                        </button>
                      )}
                    </div>
                  </div>
                </div>
              </div>

              <div className="pt-6 flex gap-3 sticky bottom-0 bg-white pb-2">
                <button 
                  type="button"
                  onClick={() => setIsModalOpen(false)}
                  className="flex-1 py-3 text-slate-500 font-bold hover:bg-slate-50 rounded-xl transition-colors"
                >
                  Cancel
                </button>
                <button 
                  type="submit"
                  className="flex-1 py-3 bg-blue-600 text-white font-bold rounded-xl shadow-lg shadow-blue-100 hover:bg-blue-700 transition-all flex items-center justify-center gap-2"
                >
                  <Check size={18} />
                  {editingHotelId ? 'Update Inventory' : 'Save Hotel to Inventory'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default Hotels;

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { 
  Search, 
  Hotel as HotelIcon, 
  MapPin, 
  Phone, 
  Plus, 
  Layers, 
  Anchor, 
  Stars, 
  Wallet, 
  X, 
  Check, 
  Link as LinkIcon, 
  FileText, 
  Info, 
  Paperclip, 
  ExternalLink,
  Edit2,
  AlertTriangle,
  Calendar,
  Eye,
  Globe,
  Tag,
  Clock
} from 'lucide-react';
import { HOTELS } from '../constants';
import { HotelCategory, Hotel } from '../types';

const CategoryIcon = ({ category }: { category: HotelCategory }) => {
  switch (category) {
    case HotelCategory.LUXURY: return <Stars size={14} className="text-amber-500" />;
    case HotelCategory.DELUXE: return <Layers size={14} className="text-blue-500" />;
    case HotelCategory.HOUSEBOAT: return <Anchor size={14} className="text-cyan-500" />;
    case HotelCategory.BUDGET: return <Wallet size={14} className="text-slate-500" />;
    default: return <HotelIcon size={14} />;
  }
};

const Hotels: React.FC = () => {
  const [searchTerm, setSearchTerm] = useState('');
  const [categoryFilter, setCategoryFilter] = useState('All');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [viewingHotel, setViewingHotel] = useState<Hotel | null>(null);
  const [editingHotelId, setEditingHotelId] = useState<string | null>(null);
  const [customHotels, setCustomHotels] = useState<Hotel[]>([]);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Form State
  const initialFormState: Partial<Hotel> = {
    name: '',
    location: '',
    category: HotelCategory.DELUXE,
    ratePerNight: 5000,
    contact: '',
    rateValidityDate: '',
    extraBedRate: undefined,
    epRate: undefined,
    cpRate: undefined,
    mapRate: undefined,
    apRate: undefined,
    internalNotes: '',
    hotelLink: '',
    attachmentName: '',
    attachmentData: ''
  };

  const [formData, setFormData] = useState<Partial<Hotel>>(initialFormState);

  // Load custom hotels from localStorage
  useEffect(() => {
    const saved = localStorage.getItem('et_hotels');
    if (saved) {
      setCustomHotels(JSON.parse(saved));
    }
  }, []);

  // Combine static and custom hotels
  const allHotels = useMemo(() => {
    const customIds = new Set(customHotels.map(h => h.id));
    return [...HOTELS.filter(h => !customIds.has(h.id)), ...customHotels];
  }, [customHotels]);

  const filteredHotels = useMemo(() => {
    return allHotels.filter(hotel => {
      const matchesSearch = hotel.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                           hotel.location.toLowerCase().includes(searchTerm.toLowerCase());
      const matchesCategory = categoryFilter === 'All' || hotel.category === categoryFilter;
      return matchesSearch && matchesCategory;
    });
  }, [allHotels, searchTerm, categoryFilter]);

  // Group hotels by Location (Destination)
  const groupedHotels = useMemo(() => {
    const groups: Record<string, Hotel[]> = {};

    filteredHotels.forEach(hotel => {
      if (!groups[hotel.location]) {
        groups[hotel.location] = [];
      }
      groups[hotel.location].push(hotel);
    });

    return groups;
  }, [filteredHotels]);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setFormData({
          ...formData,
          attachmentName: file.name,
          attachmentType: file.type,
          attachmentData: reader.result as string
        });
      };
      reader.readAsDataURL(file);
    }
  };

  const openAddModal = () => {
    setEditingHotelId(null);
    setFormData(initialFormState);
    setIsModalOpen(true);
  };

  const openEditModal = (hotel: Hotel) => {
    setEditingHotelId(hotel.id);
    setFormData({ ...hotel });
    setIsModalOpen(true);
  };

  const handleSaveHotel = (e: React.FormEvent) => {
    e.preventDefault();

    const hotelData: Hotel = {
      id: editingHotelId || `h-custom-${Date.now()}`,
      name: formData.name || '',
      location: formData.location || '',
      category: formData.category || HotelCategory.DELUXE,
      ratePerNight: formData.ratePerNight || 0,
      contact: formData.contact || '',
      ...formData
    } as Hotel;

    let updated: Hotel[];
    if (editingHotelId) {
      const index = customHotels.findIndex(h => h.id === editingHotelId);
      if (index > -1) {
        updated = [...customHotels];
        updated[index] = hotelData;
      } else {
        updated = [...customHotels, hotelData];
      }
    } else {
      updated = [...customHotels, hotelData];
    }

    setCustomHotels(updated);
    localStorage.setItem('et_hotels', JSON.stringify(updated));

    setFormData(initialFormState);
    setIsModalOpen(false);
  };

  const checkRateValidity = (dateStr?: string) => {
    if (!dateStr) return { status: 'none', label: '' };
    const expiry = new Date(dateStr);
    const today = new Date();
    const diffTime = expiry.getTime() - today.getTime();
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

    if (diffDays < 0) return { status: 'expired', label: 'Rate Expired' };
    if (diffDays <= 15) return { status: 'warning', label: `Expires in ${diffDays}d` };
    return { status: 'valid', label: `Valid until ${new Date(dateStr).toLocaleDateString('en-IN', { day: 'numeric', month: 'short' })}` };
  };

  const destinations = Object.keys(groupedHotels).sort();

  return (
    <div className="space-y-8 pb-20">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-slate-900">Hotel Inventory</h1>
          <p className="text-slate-500 text-sm">Manage seasonal rates and operational data across destinations.</p>
        </div>
        <button 
          onClick={openAddModal}
          className="bg-blue-600 text-white px-5 py-2.5 rounded-xl font-bold flex items-center gap-2 hover:bg-blue-700 shadow-lg shadow-blue-100 transition-all active:scale-95"
        >
          <Plus size={18} /> Add New Hotel
        </button>
      </div>

      {/* Destination Stats Quick View */}
      <div className="flex gap-4 overflow-x-auto pb-2 no-scrollbar">
        {destinations.map(dest => (
          <div key={dest} className="bg-white px-4 py-2 rounded-xl border border-slate-200 flex items-center gap-3 shrink-0 shadow-sm cursor-pointer hover:border-blue-300" onClick={() => {
            setSearchTerm(dest);
          }}>
            <div className="w-2 h-2 rounded-full bg-blue-500" />
            <span className="text-xs font-bold text-slate-700">{dest}</span>
            <span className="text-[10px] font-black bg-slate-100 text-slate-500 px-1.5 py-0.5 rounded">
              {groupedHotels[dest].length}
            </span>
          </div>
        ))}
      </div>

      {/* Filters Bar */}
      <div className="bg-white p-4 rounded-2xl border border-slate-200 shadow-sm flex flex-wrap items-center gap-4">
        <div className="flex-1 min-w-[300px] relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
          <input 
            type="text" 
            placeholder="Search hotel name or location..." 
            className="w-full pl-10 pr-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm text-slate-900 focus:ring-2 focus:ring-blue-500 outline-none transition-all"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
        <div className="flex items-center gap-2 bg-slate-50 border border-slate-200 rounded-xl px-3 py-1">
          <Layers size={16} className="text-slate-400" />
          <select 
            className="bg-transparent py-2 text-sm text-slate-900 font-bold outline-none"
            value={categoryFilter}
            onChange={(e) => setCategoryFilter(e.target.value)}
          >
            <option value="All">All Categories</option>
            {Object.values(HotelCategory).map(c => <option key={c} value={c}>{c}</option>)}
          </select>
        </div>
      </div>

      {/* Destination Grouped View */}
      <div className="space-y-12">
        {destinations.length > 0 ? (
          destinations.map((location) => (
            <section key={location} className="space-y-6">
              <div className="flex items-center gap-4">
                <div className="bg-slate-900 text-white p-2 rounded-xl">
                  <MapPin size={20} />
                </div>
                <h2 className="text-xl font-black text-slate-800 uppercase tracking-widest flex items-center gap-3">
                  {location}
                  <span className="text-slate-300 font-normal">/</span>
                  <span className="text-slate-400 text-sm font-bold">{groupedHotels[location].length} Hotels</span>
                </h2>
                <div className="flex-1 h-px bg-slate-200"></div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
                {groupedHotels[location].map(hotel => {
                  const validity = checkRateValidity(hotel.rateValidityDate);
                  return (
                    <div key={hotel.id} className="bg-white border border-slate-200 rounded-2xl overflow-hidden hover:shadow-xl hover:border-blue-200 transition-all group flex flex-col h-full shadow-sm relative">
                      <div className="relative h-32 bg-slate-100 overflow-hidden">
                        <img 
                          src={`https://picsum.photos/seed/${hotel.id}/400/200`} 
                          className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700 opacity-80" 
                          alt={hotel.name}
                        />
                        <div className="absolute top-3 left-3 flex flex-col gap-2">
                          <span className="flex items-center gap-1.5 px-2 py-1 bg-white/90 backdrop-blur border border-slate-200 rounded-lg text-[9px] font-black uppercase tracking-widest text-slate-700 shadow-sm">
                            <CategoryIcon category={hotel.category} />
                            {hotel.category}
                          </span>
                          {validity.status !== 'none' && (
                            <span className={`flex items-center gap-1 px-2 py-1 rounded-lg text-[9px] font-black uppercase tracking-widest shadow-sm ${
                              validity.status === 'expired' ? 'bg-red-500 text-white' : 
                              validity.status === 'warning' ? 'bg-amber-500 text-white' : 'bg-emerald-500 text-white'
                            }`}>
                              {validity.status === 'expired' ? <AlertTriangle size={10} /> : <Calendar size={10} />}
                              {validity.label}
                            </span>
                          )}
                        </div>
                        <div className="absolute top-3 right-3 flex flex-col gap-2 opacity-0 group-hover:opacity-100 transition-all duration-300">
                          <button 
                            onClick={() => setViewingHotel(hotel)}
                            className="p-2 bg-white/90 backdrop-blur rounded-full text-slate-400 hover:text-blue-600 hover:bg-white transition-all shadow-sm"
                          >
                            <Eye size={14} />
                          </button>
                          <button 
                            onClick={() => openEditModal(hotel)}
                            className="p-2 bg-white/90 backdrop-blur rounded-full text-slate-400 hover:text-blue-600 hover:bg-white transition-all shadow-sm"
                          >
                            <Edit2 size={14} />
                          </button>
                        </div>
                      </div>

                      <div className="p-5 flex flex-col flex-1">
                        <div className="flex justify-between items-start mb-2">
                          <h3 className="font-bold text-slate-800 text-base group-hover:text-blue-600 transition-colors leading-tight cursor-pointer" onClick={() => setViewingHotel(hotel)}>
                            {hotel.name}
                          </h3>
                        </div>

                        {/* Summary Rates */}
                        <div className="grid grid-cols-2 gap-2 mt-2">
                          {hotel.cpRate && <div className="text-[10px] bg-emerald-50 text-emerald-700 px-2 py-1 rounded font-bold uppercase">CP: ₹{hotel.cpRate.toLocaleString()}</div>}
                          {hotel.mapRate && <div className="text-[10px] bg-blue-50 text-blue-700 px-2 py-1 rounded font-bold uppercase">MAP: ₹{hotel.mapRate.toLocaleString()}</div>}
                        </div>

                        <div className="mt-auto space-y-3 pt-4 border-t border-slate-50">
                          <div className="flex items-center justify-between">
                            <span className="text-[10px] font-black uppercase text-slate-400">Base Rate</span>
                            <span className="text-lg font-black text-slate-900">₹{hotel.ratePerNight.toLocaleString()}</span>
                          </div>
                          <div className="flex items-center gap-2 text-xs font-semibold text-slate-500 bg-slate-50 p-2 rounded-lg truncate">
                            <Phone size={14} className="text-slate-400 shrink-0" />
                            {hotel.contact}
                          </div>
                        </div>
                      </div>
                    </div>
                  );
                })}
              </div>
            </section>
          ))
        ) : (
          <div className="text-center py-20 bg-white border-2 border-dashed border-slate-200 rounded-3xl">
            <HotelIcon size={48} className="mx-auto text-slate-200 mb-4" />
            <h3 className="text-lg font-bold text-slate-400">No hotels found matching filters</h3>
            <button 
              onClick={() => { setSearchTerm(''); setCategoryFilter('All'); }}
              className="mt-4 text-blue-600 font-bold hover:underline"
            >
              Reset Search
            </button>
          </div>
        )}
      </div>

      {/* View Details Modal */}
      {viewingHotel && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[60] flex items-center justify-center p-4 overflow-y-auto">
          <div className="bg-white rounded-[32px] shadow-2xl w-full max-w-3xl overflow-hidden animate-in zoom-in-95 duration-200">
            {/* Modal Header Image */}
            <div className="h-64 relative bg-slate-900">
              <img 
                src={`https://picsum.photos/seed/${viewingHotel.id}/800/400`} 
                className="w-full h-full object-cover opacity-60" 
                alt={viewingHotel.name}
              />
              <div className="absolute inset-0 bg-gradient-to-t from-slate-900 to-transparent" />
              <button 
                onClick={() => setViewingHotel(null)}
                className="absolute top-6 right-6 p-2 bg-white/10 hover:bg-white/20 backdrop-blur-md rounded-full text-white transition-all"
              >
                <X size={24} />
              </button>

              <div className="absolute bottom-8 left-8 right-8">
                <div className="flex items-center gap-3 mb-3">
                  <span className="px-3 py-1 bg-blue-600 text-white text-[10px] font-black uppercase tracking-[0.2em] rounded-full">
                    {viewingHotel.category}
                  </span>
                  <div className="flex items-center gap-1.5 text-blue-400 text-xs font-bold">
                    <MapPin size={14} />
                    {viewingHotel.location}, Kashmir
                  </div>
                </div>
                <h2 className="text-4xl font-black text-white leading-tight">{viewingHotel.name}</h2>
              </div>
            </div>

            <div className="p-8 grid grid-cols-1 md:grid-cols-3 gap-8">
              {/* Left Column: Rates */}
              <div className="md:col-span-2 space-y-8">
                <div>
                  <h4 className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-400 mb-4 flex items-center gap-2">
                    <IndianRupee size={12} className="text-blue-500" />
                    Meal Plan & Service Rates
                  </h4>
                  <div className="grid grid-cols-2 gap-3">
                    <div className="bg-slate-50 border border-slate-100 p-4 rounded-2xl flex justify-between items-center group hover:border-blue-200 transition-colors">
                      <span className="text-xs font-bold text-slate-500">Base EP Rate</span>
                      <span className="text-lg font-black text-slate-900">₹{viewingHotel.ratePerNight.toLocaleString()}</span>
                    </div>
                    {viewingHotel.cpRate && (
                      <div className="bg-emerald-50/50 border border-emerald-100 p-4 rounded-2xl flex justify-between items-center">
                        <span className="text-xs font-bold text-emerald-600">CP (Breakfast)</span>
                        <span className="text-lg font-black text-emerald-900">₹{viewingHotel.cpRate.toLocaleString()}</span>
                      </div>
                    )}
                    {viewingHotel.mapRate && (
                      <div className="bg-blue-50/50 border border-blue-100 p-4 rounded-2xl flex justify-between items-center">
                        <span className="text-xs font-bold text-blue-600">MAP (Bf+Meal)</span>
                        <span className="text-lg font-black text-blue-900">₹{viewingHotel.mapRate.toLocaleString()}</span>
                      </div>
                    )}
                    {viewingHotel.apRate && (
                      <div className="bg-indigo-50/50 border border-indigo-100 p-4 rounded-2xl flex justify-between items-center">
                        <span className="text-xs font-bold text-indigo-600">AP (Full)</span>
                        <span className="text-lg font-black text-indigo-900">₹{viewingHotel.apRate.toLocaleString()}</span>
                      </div>
                    )}
                    {viewingHotel.extraBedRate && (
                      <div className="bg-amber-50/50 border border-amber-100 p-4 rounded-2xl flex justify-between items-center col-span-2">
                        <div className="flex items-center gap-2">
                          <Plus size={14} className="text-amber-600" />
                          <span className="text-xs font-bold text-amber-600 uppercase">Extra Bed Charge</span>
                        </div>
                        <span className="text-lg font-black text-amber-900">₹{viewingHotel.extraBedRate.toLocaleString()}</span>
                      </div>
                    )}
                  </div>
                </div>

                {viewingHotel.internalNotes && (
                  <div>
                    <h4 className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-400 mb-4 flex items-center gap-2">
                      <Info size={12} className="text-blue-500" />
                      Operational Notes
                    </h4>
                    <div className="bg-blue-50/30 border border-blue-100/50 p-6 rounded-[24px] relative overflow-hidden">
                      <div className="absolute top-0 right-0 w-24 h-24 bg-blue-100/20 -mr-8 -mt-8 rounded-full blur-2xl" />
                      <p className="text-sm text-slate-700 leading-relaxed italic relative z-10">
                        "{viewingHotel.internalNotes}"
                      </p>
                    </div>
                  </div>
                )}
              </div>

              {/* Right Column: Meta Info */}
              <div className="space-y-6 bg-slate-50 p-6 rounded-[24px] border border-slate-100">
                <div className="space-y-1">
                  <p className="text-[9px] font-black uppercase tracking-widest text-slate-400">Validity</p>
                  {viewingHotel.rateValidityDate ? (
                    <div className="flex items-center gap-2 text-sm font-bold text-slate-800">
                      <Clock size={16} className="text-blue-500" />
                      Till {new Date(viewingHotel.rateValidityDate).toLocaleDateString('en-IN', { day: 'numeric', month: 'long', year: 'numeric' })}
                    </div>
                  ) : (
                    <div className="text-xs text-slate-400 italic">No validity date set</div>
                  )}
                </div>

                <div className="space-y-1">
                  <p className="text-[9px] font-black uppercase tracking-widest text-slate-400">Primary Contact</p>
                  <div className="flex items-center gap-2 text-sm font-bold text-slate-800 bg-white p-3 rounded-xl border border-slate-200">
                    <Phone size={16} className="text-blue-500" />
                    {viewingHotel.contact}
                  </div>
                </div>

                {viewingHotel.hotelLink && (
                  <div className="space-y-1">
                    <p className="text-[9px] font-black uppercase tracking-widest text-slate-400">Digital presence</p>
                    <a 
                      href={viewingHotel.hotelLink} 
                      target="_blank" 
                      rel="noopener noreferrer"
                      className="flex items-center justify-between text-xs font-bold text-blue-600 bg-white p-3 rounded-xl border border-blue-100 hover:bg-blue-50 transition-colors"
                    >
                      Official Website
                      <ExternalLink size={14} />
                    </a>
                  </div>
                )}

                {viewingHotel.attachmentName && (
                  <div className="space-y-1">
                    <p className="text-[9px] font-black uppercase tracking-widest text-slate-400">Files & sheets</p>
                    <div className="flex items-center justify-between text-xs font-bold text-slate-700 bg-white p-3 rounded-xl border border-slate-200">
                      <div className="flex items-center gap-2 overflow-hidden">
                        <Paperclip size={14} className="text-slate-400 shrink-0" />
                        <span className="truncate">{viewingHotel.attachmentName}</span>
                      </div>
                      <button className="text-blue-600 hover:bg-blue-50 p-1 rounded transition-colors">
                        <Check size={14} />
                      </button>
                    </div>
                  </div>
                )}

                <button 
                  onClick={() => { setViewingHotel(null); openEditModal(viewingHotel); }}
                  className="w-full mt-4 py-3 bg-slate-900 text-white text-xs font-black uppercase tracking-[0.2em] rounded-xl hover:bg-slate-800 transition-all flex items-center justify-center gap-2"
                >
                  <Edit2 size={14} />
                  Modify Entry
                </button>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Add/Edit Hotel Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-50 flex items-center justify-center p-4 overflow-y-auto">
          <div className="bg-white rounded-3xl shadow-2xl w-full max-w-2xl my-8 overflow-hidden animate-in zoom-in-95 duration-200">
            <div className="bg-slate-50 p-6 border-b border-slate-100 flex items-center justify-between sticky top-0 z-10">
              <div className="flex items-center gap-3">
                <div className="bg-blue-600 p-2 rounded-xl text-white">
                  {editingHotelId ? <Edit2 size={20} /> : <HotelIcon size={20} />}
                </div>
                <div>
                  <h3 className="font-bold text-slate-900">{editingHotelId ? 'Edit Hotel Details' : 'Add Detailed Hotel Entry'}</h3>
                  <p className="text-xs text-slate-500">Fill operational details and meal plan rates.</p>
                </div>
              </div>
              <button 
                onClick={() => setIsModalOpen(false)}
                className="p-2 hover:bg-slate-200 rounded-full transition-colors"
              >
                <X size={20} className="text-slate-400" />
              </button>
            </div>

            <form onSubmit={handleSaveHotel} className="p-8 space-y-8">
              {/* Basic Details */}
              <div className="space-y-4">
                <h4 className="text-xs font-black uppercase tracking-widest text-blue-600 border-b border-blue-50 pb-2">Basic Information</h4>
                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-2 col-span-2">
                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">Hotel Name</label>
                    <input 
                      required
                      type="text"
                      placeholder="e.g. Grand Palace Resort"
                      className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm focus:ring-2 focus:ring-blue-500 outline-none"
                      value={formData.name}
                      onChange={e => setFormData({...formData, name: e.target.value})}
                    />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">Location (City/Destination)</label>
                    <input 
                      required
                      type="text"
                      placeholder="e.g. Srinagar"
                      className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm focus:ring-2 focus:ring-blue-500 outline-none"
                      value={formData.location}
                      onChange={e => setFormData({...formData, location: e.target.value})}
                    />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">Inventory Category</label>
                    <select 
                      className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm focus:ring-2 focus:ring-blue-500 outline-none font-medium"
                      value={formData.category}
                      onChange={e => setFormData({...formData, category: e.target.value as HotelCategory})}
                    >
                      {Object.values(HotelCategory).map(c => <option key={c} value={c}>{c}</option>)}
                    </select>
                  </div>
                </div>
              </div>

              {/* Rates Section */}
              <div className="space-y-4">
                <h4 className="text-xs font-black uppercase tracking-widest text-blue-600 border-b border-blue-50 pb-2">Meal Plans & Extra Bed Rates</h4>
                <div className="grid grid-cols-3 gap-4">
                  <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">EP Rate (Room Only)</label>
                    <input 
                      type="number"
                      placeholder="Optional"
                      className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none"
                      value={formData.epRate || ''}
                      onChange={e => setFormData({...formData, epRate: parseInt(e.target.value) || undefined})}
                    />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">CP Rate (Room+Bf)</label>
                    <input 
                      type="number"
                      placeholder="Optional"
                      className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none"
                      value={formData.cpRate || ''}
                      onChange={e => setFormData({...formData, cpRate: parseInt(e.target.value) || undefined})}
                    />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">MAP Rate (Room+Bf+Meal)</label>
                    <input 
                      type="number"
                      placeholder="Optional"
                      className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none"
                      value={formData.mapRate || ''}
                      onChange={e => setFormData({...formData, mapRate: parseInt(e.target.value) || undefined})}
                    />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">AP Rate (All Meals)</label>
                    <input 
                      type="number"
                      placeholder="Optional"
                      className="w-full px-4 py-2 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none"
                      value={formData.apRate || ''}
                      onChange={e => setFormData({...formData, apRate: parseInt(e.target.value) || undefined})}
                    />
