                      onChange={e => setFormData({...formData, contact: e.target.value})}
                    />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">Website/Portal Link</label>
                    <div className="relative">
                      <LinkIcon className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-300" size={14} />
                      <input 
                        type="url" 
                        placeholder="https://..."
                        className="w-full pl-9 pr-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none font-semibold"
                        value={formData.hotelLink}
                        onChange={e => setFormData({...formData, hotelLink: e.target.value})}
                      />
                    </div>
                  </div>
                  <div className="space-y-2 col-span-2">
                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">Internal Operational Notes</label>
                    <textarea 
                      placeholder="e.g. Free room upgrades for Honeymooners, Check-in at 12 PM..."
                      rows={3}
                      className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl text-sm outline-none resize-none font-medium"
                      value={formData.internalNotes}
                      onChange={e => setFormData({...formData, internalNotes: e.target.value})}
                    />
                  </div>
                  <div className="space-y-2 col-span-2">
                    <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">Attachments (PDF, JPG, XLS)</label>
                    <div className="flex items-center gap-3 p-4 border-2 border-dashed border-slate-200 rounded-2xl bg-slate-50 hover:bg-slate-100 transition-colors cursor-pointer relative">
                      <input 
                        type="file" 
                        ref={fileInputRef}
                        className="absolute inset-0 opacity-0 cursor-pointer"
                        onChange={handleFileChange}
                        accept=".pdf,.jpg,.jpeg,.png,.xls,.xlsx"
                      />
                      <div className="bg-white p-2 rounded-lg shadow-sm">
                        <Paperclip size={20} className="text-blue-500" />
                      </div>
                      <div className="flex-1">
                        <p className="text-xs font-bold text-slate-700">
                          {formData.attachmentName || 'Click to upload rate sheet or contract'}
                        </p>
                        <p className="text-[10px] text-slate-400 uppercase tracking-widest font-black">Max 5MB • PDF / JPG / Excel</p>
                      </div>
                      {formData.attachmentName && (
                        <button 
                          type="button" 
                          onClick={(e) => { e.stopPropagation(); setFormData({...formData, attachmentName: '', attachmentData: ''}); }}
                          className="p-1.5 hover:bg-red-50 text-red-400 rounded-md transition-colors"
                        >
                          <X size={14} />
                        </button>
                      )}
                    </div>
                  </div>
                </div>
              </div>

              <div className="pt-6 flex gap-3 sticky bottom-0 bg-white pb-2 shadow-[0_-10px_20px_rgba(255,255,255,0.8)]">
                <button 
                  type="button"
                  onClick={() => setIsModalOpen(false)}
                  className="flex-1 py-3 text-slate-500 font-bold hover:bg-slate-50 rounded-xl transition-colors"
                >
                  Cancel
                </button>
                <button 
                  type="submit"
                  className="flex-1 py-3 bg-blue-600 text-white font-bold rounded-xl shadow-lg shadow-blue-100 hover:bg-blue-700 transition-all flex items-center justify-center gap-2"
                >
                  <Check size={18} />
                  {editingHotelId ? 'Update Inventory' : 'Save Hotel to Inventory'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default Hotels;

import React, { useState, useMemo, useEffect, useRef } from 'react';
import { 
  Search, 
  Hotel as HotelIcon, 
  MapPin, 
  Phone, 
  Plus, 
  Layers, 
  Anchor, 
  Stars, 
  Wallet, 
  X, 
  Check, 
  Link as LinkIcon, 
  FileText, 
  Info, 
  Paperclip, 
  ExternalLink,
  Edit2,
  AlertTriangle,
  Calendar,
  Eye,
  Globe,
  Tag,
  Clock,
  IndianRupee,
  ShieldCheck,
  Building2,
  CalendarCheck,
  /* Fix: Added missing Download icon import */
  Download
} from 'lucide-react';
import { HOTELS } from '../constants';
import { HotelCategory, Hotel } from '../types';

const CategoryIcon = ({ category }: { category: HotelCategory }) => {
  switch (category) {
    case HotelCategory.LUXURY: return <Stars size={14} className="text-amber-500" />;
    case HotelCategory.DELUXE: return <Layers size={14} className="text-blue-500" />;
    case HotelCategory.HOUSEBOAT: return <Anchor size={14} className="text-cyan-500" />;
    case HotelCategory.BUDGET: return <Wallet size={14} className="text-slate-500" />;
    default: return <HotelIcon size={14} />;
  }
};

const Hotels: React.FC = () => {
  const [searchTerm, setSearchTerm] = useState('');
  const [categoryFilter, setCategoryFilter] = useState('All');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [viewingHotel, setViewingHotel] = useState<Hotel | null>(null);
  const [editingHotelId, setEditingHotelId] = useState<string | null>(null);
  const [customHotels, setCustomHotels] = useState<Hotel[]>([]);
  const fileInputRef = useRef<HTMLInputElement>(null);

  // Form State
  const initialFormState: Partial<Hotel> = {
    name: '',
    location: '',
    category: HotelCategory.DELUXE,
    ratePerNight: 5000,
    contact: '',
    rateValidityDate: '',
    extraBedRate: undefined,
    epRate: undefined,
    cpRate: undefined,
    mapRate: undefined,
    apRate: undefined,
    internalNotes: '',
    hotelLink: '',
    attachmentName: '',
    attachmentType: '',
    attachmentData: ''
  };

  const [formData, setFormData] = useState<Partial<Hotel>>(initialFormState);

  // Load custom hotels from localStorage
  useEffect(() => {
    const saved = localStorage.getItem('et_hotels');
    if (saved) {
      setCustomHotels(JSON.parse(saved));
    }
  }, []);

  // Combine static and custom hotels
  const allHotels = useMemo(() => {
    const customIds = new Set(customHotels.map(h => h.id));
    return [...HOTELS.filter(h => !customIds.has(h.id)), ...customHotels];
  }, [customHotels]);

  const filteredHotels = useMemo(() => {
    return allHotels.filter(hotel => {
      const matchesSearch = hotel.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                           hotel.location.toLowerCase().includes(searchTerm.toLowerCase());
      const matchesCategory = categoryFilter === 'All' || hotel.category === categoryFilter;
      return matchesSearch && matchesCategory;
    });
  }, [allHotels, searchTerm, categoryFilter]);

  // Group hotels by Location (Destination)
  const groupedHotels = useMemo(() => {
    const groups: Record<string, Hotel[]> = {};

    filteredHotels.forEach(hotel => {
      if (!groups[hotel.location]) {
        groups[hotel.location] = [];
      }
      groups[hotel.location].push(hotel);
    });

    return groups;
  }, [filteredHotels]);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setFormData({
          ...formData,
          attachmentName: file.name,
          attachmentType: file.type,
          attachmentData: reader.result as string
        });
      };
      reader.readAsDataURL(file);
    }
  };

  const openAddModal = () => {
    setEditingHotelId(null);
    setFormData(initialFormState);
    setIsModalOpen(true);
  };

  const openEditModal = (hotel: Hotel) => {
    setEditingHotelId(hotel.id);
    setFormData({ ...hotel });
    setIsModalOpen(true);
  };

  const handleSaveHotel = (e: React.FormEvent) => {
    e.preventDefault();

    const hotelData: Hotel = {
      id: editingHotelId || `h-custom-${Date.now()}`,
      name: formData.name || '',
      location: formData.location || '',
      category: formData.category || HotelCategory.DELUXE,
      ratePerNight: formData.ratePerNight || 0,
      contact: formData.contact || '',
      ...formData
    } as Hotel;

    let updated: Hotel[];
    if (editingHotelId) {
      const index = customHotels.findIndex(h => h.id === editingHotelId);
      if (index > -1) {
        updated = [...customHotels];
        updated[index] = hotelData;
      } else {
        updated = [...customHotels, hotelData];
      }
    } else {
      updated = [...customHotels, hotelData];
    }

    setCustomHotels(updated);
    localStorage.setItem('et_hotels', JSON.stringify(updated));

    setFormData(initialFormState);
    setIsModalOpen(false);
  };

  const checkRateValidity = (dateStr?: string) => {
    if (!dateStr) return { status: 'none', label: '' };
    const expiry = new Date(dateStr);
    const today = new Date();
    const diffTime = expiry.getTime() - today.getTime();
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

    if (diffDays < 0) return { status: 'expired', label: 'Rate Expired' };
    if (diffDays <= 15) return { status: 'warning', label: `Expires in ${diffDays}d` };
    return { status: 'valid', label: `Valid until ${new Date(dateStr).toLocaleDateString('en-IN', { day: 'numeric', month: 'short' })}` };
  };

  const destinations = Object.keys(groupedHotels).sort();

  return (
    <div className="space-y-8 pb-20">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-slate-900">Hotel Inventory</h1>
          <p className="text-slate-500 text-sm">Manage seasonal rates and operational data across destinations.</p>
        </div>
        <button 
          onClick={openAddModal}
          className="bg-blue-600 text-white px-5 py-2.5 rounded-xl font-bold flex items-center gap-2 hover:bg-blue-700 shadow-lg shadow-blue-100 transition-all active:scale-95"
        >
          <Plus size={18} /> Add New Hotel
        </button>
      </div>

      {/* Destination Stats Quick View */}
      <div className="flex gap-4 overflow-x-auto pb-2 no-scrollbar">
        {destinations.map(dest => (
          <div key={dest} className="bg-white px-4 py-2 rounded-xl border border-slate-200 flex items-center gap-3 shrink-0 shadow-sm cursor-pointer hover:border-blue-300 transition-colors" onClick={() => {
            setSearchTerm(dest);
          }}>
            <div className="w-2 h-2 rounded-full bg-blue-500" />
            <span className="text-xs font-bold text-slate-700">{dest}</span>
            <span className="text-[10px] font-black bg-slate-100 text-slate-500 px-1.5 py-0.5 rounded">
              {groupedHotels[dest].length}
            </span>
          </div>
        ))}
      </div>

      {/* Filters Bar */}
      <div className="bg-white p-4 rounded-2xl border border-slate-200 shadow-sm flex flex-wrap items-center gap-4">
        <div className="flex-1 min-w-[300px] relative">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
          <input 
            type="text" 
            placeholder="Search hotel name or location..." 
            className="w-full pl-10 pr-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm text-slate-900 focus:ring-2 focus:ring-blue-500 outline-none transition-all"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
        <div className="flex items-center gap-2 bg-slate-50 border border-slate-200 rounded-xl px-3 py-1">
          <Layers size={16} className="text-slate-400" />
          <select 
            className="bg-transparent py-2 text-sm text-slate-900 font-bold outline-none cursor-pointer"
            value={categoryFilter}
            onChange={(e) => setCategoryFilter(e.target.value)}
          >
            <option value="All">All Categories</option>
            {Object.values(HotelCategory).map(c => <option key={c} value={c}>{c}</option>)}
          </select>
        </div>
      </div>

      {/* Destination Grouped View */}
      <div className="space-y-12">
        {destinations.length > 0 ? (
          destinations.map((location) => (
            <section key={location} className="space-y-6">
              <div className="flex items-center gap-4">
                <div className="bg-slate-900 text-white p-2 rounded-xl shadow-lg">
                  <MapPin size={20} />
                </div>
                <h2 className="text-xl font-black text-slate-800 uppercase tracking-widest flex items-center gap-3">
                  {location}
                  <span className="text-slate-300 font-normal">/</span>
                  <span className="text-slate-400 text-sm font-bold">{groupedHotels[location].length} Hotels</span>
                </h2>
                <div className="flex-1 h-px bg-slate-200"></div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
                {groupedHotels[location].map(hotel => {
                  const validity = checkRateValidity(hotel.rateValidityDate);
                  return (
                    <div key={hotel.id} className="bg-white border border-slate-200 rounded-2xl overflow-hidden hover:shadow-xl hover:border-blue-200 transition-all group flex flex-col h-full shadow-sm relative">
                      <div className="relative h-32 bg-slate-100 overflow-hidden">
                        <img 
                          src={`https://picsum.photos/seed/${hotel.id}/400/200`} 
                          className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700 opacity-80" 
                          alt={hotel.name}
                        />
                        <div className="absolute top-3 left-3 flex flex-col gap-2">
                          <span className="flex items-center gap-1.5 px-2 py-1 bg-white/90 backdrop-blur border border-slate-200 rounded-lg text-[9px] font-black uppercase tracking-widest text-slate-700 shadow-sm">
                            <CategoryIcon category={hotel.category} />
                            {hotel.category}
                          </span>
                          {validity.status !== 'none' && (
                            <span className={`flex items-center gap-1 px-2 py-1 rounded-lg text-[9px] font-black uppercase tracking-widest shadow-sm ${
                              validity.status === 'expired' ? 'bg-red-500 text-white' : 
                              validity.status === 'warning' ? 'bg-amber-500 text-white' : 'bg-emerald-500 text-white'
                            }`}>
                              {validity.status === 'expired' ? <AlertTriangle size={10} /> : <Calendar size={10} />}
                              {validity.label}
                            </span>
                          )}
                        </div>
                        <div className="absolute top-3 right-3 flex flex-col gap-2 opacity-0 group-hover:opacity-100 transition-all duration-300">
                          <button 
                            onClick={() => setViewingHotel(hotel)}
                            className="p-2 bg-white/90 backdrop-blur rounded-full text-slate-400 hover:text-blue-600 hover:bg-white transition-all shadow-sm"
                            title="View Full Specs"
                          >
                            <Eye size={14} />
                          </button>
                          <button 
                            onClick={() => openEditModal(hotel)}
                            className="p-2 bg-white/90 backdrop-blur rounded-full text-slate-400 hover:text-blue-600 hover:bg-white transition-all shadow-sm"
                            title="Edit Hotel"
                          >
                            <Edit2 size={14} />
                          </button>
                        </div>
                      </div>

                      <div className="p-5 flex flex-col flex-1">
                        <div className="flex justify-between items-start mb-2">
                          <h3 className="font-bold text-slate-800 text-base group-hover:text-blue-600 transition-colors leading-tight cursor-pointer" onClick={() => setViewingHotel(hotel)}>
                            {hotel.name}
                          </h3>
                        </div>

                        {/* Summary Rates Badge */}
                        <div className="flex flex-wrap gap-1.5 mt-2">
                          {hotel.cpRate && <div className="text-[10px] bg-emerald-50 text-emerald-700 px-2 py-0.5 rounded font-bold uppercase">CP: ₹{hotel.cpRate.toLocaleString()}</div>}
                          {hotel.mapRate && <div className="text-[10px] bg-blue-50 text-blue-700 px-2 py-0.5 rounded font-bold uppercase">MAP: ₹{hotel.mapRate.toLocaleString()}</div>}
                        </div>

                        <div className="mt-auto space-y-3 pt-4 border-t border-slate-50">
                          <div className="flex items-center justify-between">
                            <span className="text-[10px] font-black uppercase text-slate-400">EP / Starting Rate</span>
                            <span className="text-lg font-black text-slate-900">₹{hotel.ratePerNight.toLocaleString()}</span>
                          </div>
                          <div className="flex items-center gap-2 text-xs font-semibold text-slate-500 bg-slate-50 p-2 rounded-lg truncate">
                            <Phone size={14} className="text-slate-400 shrink-0" />
                            {hotel.contact}
                          </div>
                        </div>
                      </div>
                    </div>
                  );
                })}
              </div>
            </section>
          ))
        ) : (
          <div className="text-center py-20 bg-white border-2 border-dashed border-slate-200 rounded-3xl">
            <HotelIcon size={48} className="mx-auto text-slate-200 mb-4" />
            <h3 className="text-lg font-bold text-slate-400">No hotels found matching filters</h3>
            <button 
              onClick={() => { setSearchTerm(''); setCategoryFilter('All'); }}
              className="mt-4 text-blue-600 font-bold hover:underline"
            >
              Reset Search
            </button>
          </div>
        )}
      </div>

      {/* View Details Modal (Comprehensive Spec View) */}
      {viewingHotel && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[60] flex items-center justify-center p-4 overflow-y-auto">
          <div className="bg-white rounded-[32px] shadow-2xl w-full max-w-4xl overflow-hidden animate-in zoom-in-95 duration-200">
            {/* Modal Header Image with Gradient Overlays */}
            <div className="h-72 relative bg-slate-900 group">
              <img 
                src={`https://picsum.photos/seed/${viewingHotel.id}/1200/600`} 
                className="w-full h-full object-cover opacity-70 group-hover:scale-105 transition-transform duration-1000" 
                alt={viewingHotel.name}
              />
              <div className="absolute inset-0 bg-gradient-to-t from-slate-900 via-slate-900/20 to-transparent" />
              <div className="absolute inset-0 bg-gradient-to-r from-slate-900/60 via-transparent to-transparent" />

              <button 
                onClick={() => setViewingHotel(null)}
                className="absolute top-6 right-6 p-2 bg-white/10 hover:bg-white/20 backdrop-blur-md rounded-full text-white transition-all z-10"
              >
                <X size={24} />
              </button>

              <div className="absolute bottom-8 left-10 right-10 flex justify-between items-end">
                <div className="space-y-4">
                  <div className="flex items-center gap-3">
                    <span className="px-4 py-1 bg-blue-600 text-white text-[10px] font-black uppercase tracking-[0.2em] rounded-full shadow-lg shadow-blue-900/20 flex items-center gap-2">
                      <CategoryIcon category={viewingHotel.category} />
                      {viewingHotel.category} Class
                    </span>
                    <div className="flex items-center gap-1.5 text-blue-300 text-xs font-bold bg-slate-900/40 backdrop-blur-sm px-3 py-1 rounded-full border border-white/10">
                      <MapPin size={14} className="text-blue-400" />
                      {viewingHotel.location}, Kashmir
                    </div>
                  </div>
                  <h2 className="text-5xl font-black text-white leading-tight tracking-tight drop-shadow-md">{viewingHotel.name}</h2>
                </div>

                <div className="text-right">
                  <p className="text-[10px] font-black uppercase tracking-widest text-slate-400 mb-1">Base Price / Night</p>
                  <div className="text-4xl font-black text-white flex items-center gap-1">
                    <IndianRupee size={28} className="text-blue-400" />
                    {viewingHotel.ratePerNight.toLocaleString()}
                  </div>
                </div>
              </div>
            </div>

            <div className="p-10 grid grid-cols-1 md:grid-cols-12 gap-10">
              {/* Left Side: Rates & Notes (Cols 1-8) */}
              <div className="md:col-span-8 space-y-10">
                {/* Rate Card Section */}
                <div>
                  <div className="flex items-center justify-between mb-6">
                    <h4 className="text-[11px] font-black uppercase tracking-[0.2em] text-slate-400 flex items-center gap-3">
                      <div className="w-8 h-px bg-slate-200" />
                      Meal Plan Breakdown
                    </h4>
                  </div>
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                    {/* EP Rate */}
                    <div className="bg-slate-50 border border-slate-100 p-5 rounded-2xl flex justify-between items-center group hover:bg-white hover:shadow-md transition-all duration-300">
                      <div className="flex flex-col">
                        <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">EP Plan</span>
                        <span className="text-xs font-bold text-slate-600">Room Only</span>
