                      <div className="flex flex-col">
                        <span className="text-[10px] font-black uppercase tracking-widest text-emerald-600">CP Plan</span>
                        <span className="text-xs font-bold text-slate-500">Room + Breakfast</span>
                      </div>
                      <span className="text-xl font-black text-slate-900">{viewingHotel.cpRate ? `₹${viewingHotel.cpRate.toLocaleString()}` : '--'}</span>
                    </div>

                    {/* MAP Rate */}
                    <div className={`p-5 rounded-2xl flex justify-between items-center border transition-all duration-300 ${viewingHotel.mapRate ? 'bg-blue-50/40 border-blue-100 group hover:bg-white hover:shadow-md' : 'bg-slate-50/50 border-slate-100 opacity-40 grayscale'}`}>
                      <div className="flex flex-col">
                        <span className="text-[10px] font-black uppercase tracking-widest text-blue-600">MAP Plan</span>
                        <span className="text-xs font-bold text-slate-500">Room + BF + Lunch/Dinner</span>
                      </div>
                      <span className="text-xl font-black text-slate-900">{viewingHotel.mapRate ? `₹${viewingHotel.mapRate.toLocaleString()}` : '--'}</span>
                    </div>

                    {/* AP Rate */}
