                      <div className="flex flex-col">
                        <span className="text-[10px] font-black uppercase tracking-widest text-indigo-600">AP Plan</span>
                        <span className="text-xs font-bold text-slate-500">Room + All Meals</span>
                      </div>
                      <span className="text-xl font-black text-slate-900">{viewingHotel.apRate ? `₹${viewingHotel.apRate.toLocaleString()}` : '--'}</span>
                    </div>
