                          <CalendarCheck size={20} className="shrink-0" />
                          <div>
                            <p className="text-xs font-black uppercase tracking-widest">{checkRateValidity(viewingHotel.rateValidityDate).label}</p>
                            <p className="text-[10px] opacity-70 font-bold">{new Date(viewingHotel.rateValidityDate).toLocaleDateString('en-IN', { day: 'numeric', month: 'long', year: 'numeric' })}</p>
                          </div>
                        </div>
                      </div>
                    ) : (
                      <div className="p-4 bg-slate-100 border border-slate-200 rounded-2xl text-[10px] font-bold text-slate-400 flex items-center gap-2">
                        <AlertTriangle size={14} />
                        NO VALIDITY DATE DEFINED
                      </div>
                    )}
                  </div>

                  <div className="h-px bg-slate-200/50" />

                  {/* Public Contact */}
                  <div className="space-y-4">
                    <div>
                      <p className="text-[9px] font-black uppercase tracking-[0.2em] text-slate-400 mb-2">Front Office Contact</p>
                      <div className="flex items-center gap-3 bg-white p-4 rounded-2xl border border-slate-200 shadow-sm group hover:border-blue-300 transition-all cursor-pointer">
                        <div className="p-2 bg-blue-50 text-blue-600 rounded-lg group-hover:bg-blue-600 group-hover:text-white transition-all">
                          <Phone size={16} />
                        </div>
                        <span className="text-sm font-black text-slate-800">{viewingHotel.contact}</span>
                      </div>
                    </div>

                    {viewingHotel.hotelLink && (
                      <div>
                        <p className="text-[9px] font-black uppercase tracking-[0.2em] text-slate-400 mb-2">Property Website</p>
                        <a 
                          href={viewingHotel.hotelLink} 
                          target="_blank" 
                          rel="noopener noreferrer"
                          className="flex items-center justify-between text-xs font-black uppercase tracking-widest text-blue-600 bg-white p-4 rounded-2xl border border-blue-100 hover:bg-blue-600 hover:text-white transition-all shadow-sm group"
                        >
