                          <ExternalLink size={16} className="group-hover:translate-x-1 group-hover:-translate-y-1 transition-transform" />
                        </a>
                      </div>
                    )}

                    {viewingHotel.attachmentName && (
                      <div>
                        <p className="text-[9px] font-black uppercase tracking-[0.2em] text-slate-400 mb-2">Operational Attachments</p>
                        <div className="bg-white p-4 rounded-2xl border border-slate-200 flex items-center justify-between group cursor-help hover:border-blue-200 transition-all">
                          <div className="flex items-center gap-3 overflow-hidden">
                            <div className="bg-slate-100 p-2 rounded-lg text-slate-400">
                              <FileText size={16} />
                            </div>
