import React, { useState, useMemo, useEffect, useRef } from 'react';
import { 
  Search, 
  Car, 
  Users, 
  Plus, 
  IndianRupee, 
  X, 
  Check, 
  Edit2, 
  Eye, 
  Phone, 
  Info, 
  Calendar, 
  ShieldCheck, 
  Zap, 
  Wind, 
  Droplets,
  MoreVertical,
  Trash2,
  AlertTriangle,
  ArrowRight,
  FileText,
  Paperclip,
  Star
} from 'lucide-react';
import { VEHICLES } from '../constants';
import { Vehicle } from '../types';

const Vehicles: React.FC = () => {
  const [searchTerm, setSearchTerm] = useState('');
  const [capacityFilter, setCapacityFilter] = useState('All');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [viewingVehicle, setViewingVehicle] = useState<Vehicle | null>(null);
  const [editingVehicleId, setEditingVehicleId] = useState<string | null>(null);
  const [customVehicles, setCustomVehicles] = useState<Vehicle[]>([]);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const initialFormState: Partial<Vehicle> = {
    type: '',
    brand: '',
    model: '',
    capacity: 4,
    ratePerDay: 2500,
    isAC: true,
    fuelType: 'Diesel',
    features: [],
    providerName: '',
    providerContact: '',
    internalNotes: '',
    rateValidityDate: '',
  };

  const [formData, setFormData] = useState<Partial<Vehicle>>(initialFormState);

  // Load from localStorage
  useEffect(() => {
    const saved = localStorage.getItem('et_vehicles');
    if (saved) {
      setCustomVehicles(JSON.parse(saved));
    }
  }, []);

  const allVehicles = useMemo(() => {
    const customIds = new Set(customVehicles.map(v => v.id));
    return [...VEHICLES.filter(v => !customIds.has(v.id)), ...customVehicles];
  }, [customVehicles]);

  const filteredVehicles = useMemo(() => {
    return allVehicles.filter(v => {
      const matchesSearch = v.type.toLowerCase().includes(searchTerm.toLowerCase()) || 
                           (v.brand?.toLowerCase().includes(searchTerm.toLowerCase()));
      const matchesCapacity = capacityFilter === 'All' || v.capacity >= parseInt(capacityFilter);
      return matchesSearch && matchesCapacity;
    });
  }, [allVehicles, searchTerm, capacityFilter]);

  const openAddModal = () => {
    setEditingVehicleId(null);
    setFormData(initialFormState);
    setIsModalOpen(true);
  };

  const openEditModal = (vehicle: Vehicle) => {
    setEditingVehicleId(vehicle.id);
    setFormData({ ...vehicle });
    setIsModalOpen(true);
  };

  const handleSaveVehicle = (e: React.FormEvent) => {
    e.preventDefault();
    const vehicleData: Vehicle = {
      id: editingVehicleId || `v-custom-${Date.now()}`,
      type: formData.type || 'Standard',
      capacity: formData.capacity || 1,
      ratePerDay: formData.ratePerDay || 0,
      isAC: formData.isAC ?? true,
      ...formData
    } as Vehicle;

    let updated: Vehicle[];
    if (editingVehicleId) {
      const index = customVehicles.findIndex(v => v.id === editingVehicleId);
      if (index > -1) {
        updated = [...customVehicles];
        updated[index] = vehicleData;
      } else {
        updated = [...customVehicles, vehicleData];
      }
    } else {
      updated = [...customVehicles, vehicleData];
    }

    setCustomVehicles(updated);
    localStorage.setItem('et_vehicles', JSON.stringify(updated));
    setIsModalOpen(false);
  };

  const handleDeleteVehicle = (id: string) => {
    if (window.confirm("Delete this vehicle from your inventory?")) {
      const updated = customVehicles.filter(v => v.id !== id);
      setCustomVehicles(updated);
      localStorage.setItem('et_vehicles', JSON.stringify(updated));
    }
  };

  const checkRateValidity = (dateStr?: string) => {
    if (!dateStr) return { status: 'none', label: '' };
    const expiry = new Date(dateStr);
    const today = new Date();
    const diffTime = expiry.getTime() - today.getTime();
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

    if (diffDays < 0) return { status: 'expired', label: 'Rate Expired' };
    if (diffDays <= 15) return { status: 'warning', label: `Expires in ${diffDays}d` };
    return { status: 'valid', label: `Valid until ${new Date(dateStr).toLocaleDateString('en-IN', { day: 'numeric', month: 'short' })}` };
  };

  return (
