                      value={formData.ratePerDay}
                      onChange={e => setFormData({...formData, ratePerDay: parseInt(e.target.value)})}
                    />
                  </div>
                  <div className="space-y-1.5">
                    <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest">AC Configuration</label>
                    <select 
                      className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm font-bold text-slate-900 outline-none"
                      value={formData.isAC ? 'true' : 'false'}
                      onChange={e => setFormData({...formData, isAC: e.target.value === 'true'})}
                    >
                      <option value="true">Air Conditioned (AC)</option>
                      <option value="false">Non-AC</option>
                    </select>
                  </div>
                  <div className="space-y-1.5">
                    <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Fuel Type</label>
                    <select 
                      className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm font-bold text-slate-900 outline-none"
                      value={formData.fuelType}
                      onChange={e => setFormData({...formData, fuelType: e.target.value})}
                    >
                      <option value="Diesel">Diesel</option>
                      <option value="Petrol">Petrol</option>
                      <option value="Electric">Electric</option>
                    </select>
                  </div>
                </div>
              </div>

              <div className="space-y-4">
                <h4 className="text-xs font-black uppercase tracking-widest text-blue-600 border-b border-blue-50 pb-2">Operational Data</h4>
                <div className="grid grid-cols-2 gap-4">
                  <div className="space-y-1.5">
                    <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Provider / Owner</label>
                    <input 
                      type="text" 
                      placeholder="e.g. Valley Travels"
                      className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm font-semibold text-slate-900 outline-none"
                      value={formData.providerName}
                      onChange={e => setFormData({...formData, providerName: e.target.value})}
                    />
                  </div>
                  <div className="space-y-1.5">
                    <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Primary Contact</label>
                    <input 
                      type="text" 
                      placeholder="+91..."
                      className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm font-semibold text-slate-900 outline-none"
                      value={formData.providerContact}
                      onChange={e => setFormData({...formData, providerContact: e.target.value})}
                    />
                  </div>
                  <div className="space-y-1.5">
                    <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Rate Valid Until</label>
                    <input 
                      type="date" 
                      className="w-full px-4 py-2.5 bg-slate-50 border border-slate-200 rounded-xl text-sm font-semibold text-slate-900 outline-none"
                      value={formData.rateValidityDate}
                      onChange={e => setFormData({...formData, rateValidityDate: e.target.value})}
                    />
                  </div>
                  <div className="space-y-1.5 col-span-2">
                    <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Internal Notes</label>
                    <textarea 
                      rows={3}
                      placeholder="Notes for sales team... e.g. 24/7 airport backup available."
                      className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl text-sm font-medium text-slate-900 outline-none resize-none"
                      value={formData.internalNotes}
                      onChange={e => setFormData({...formData, internalNotes: e.target.value})}
                    />
                  </div>
                </div>
              </div>

              <div className="pt-6 flex gap-4 sticky bottom-0 bg-white shadow-[0_-10px_20px_rgba(255,255,255,0.8)] pb-2">
                <button 
                  type="button"
                  onClick={() => setIsModalOpen(false)}
                  className="flex-1 py-3.5 text-slate-500 font-bold hover:bg-slate-50 rounded-2xl transition-all"
                >
                  Cancel
                </button>
                <button 
                  type="submit"
                  className="flex-1 py-3.5 bg-blue-600 text-white font-black uppercase tracking-widest text-[11px] rounded-2xl shadow-xl shadow-blue-900/10 hover:bg-blue-700 transition-all flex items-center justify-center gap-2"
                >
                  <Check size={18} />
                  {editingVehicleId ? 'Update Specs' : 'Save to Fleet'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

