const TripBuilder: React.FC = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const [trip, setTrip] = useState<Trip | null>(null);
  const [activeDayIndex, setActiveDayIndex] = useState(0);
  const [isAiGenerating, setIsAiGenerating] = useState(false);
  const [isDownloading, setIsDownloading] = useState(false);
  const [downloadSuccess, setDownloadSuccess] = useState(false);
  const [showHistory, setShowHistory] = useState(false);

  // Load trip data and check localStorage for edits
  useEffect(() => {
    const savedTrips = localStorage.getItem('et_trips');
    let foundTrip: Trip | undefined;

    if (savedTrips) {
      const parsed = JSON.parse(savedTrips);
      foundTrip = parsed.find((t: Trip) => t.id === id);
    }

    if (!foundTrip) {
      foundTrip = MOCK_TRIPS.find(t => t.id === id);
    }

    if (foundTrip) {
      // Ensure startLocation exists for older records
      setTrip({ ...foundTrip, startLocation: foundTrip.startLocation || 'Srinagar' });
    }
  }, [id]);

  // Persist trip to localStorage whenever it changes
  useEffect(() => {
    if (trip) {
      const savedTrips = localStorage.getItem('et_trips');
      let allTrips: Trip[] = savedTrips ? JSON.parse(savedTrips) : [...MOCK_TRIPS];

      const index = allTrips.findIndex(t => t.id === trip.id);
      if (index > -1) {
        allTrips[index] = trip;
      } else {
        allTrips.push(trip);
      }
      localStorage.setItem('et_trips', JSON.stringify(allTrips));
    }
  }, [trip]);

  const costs = useMemo(() => {
    if (!trip) return { total: 0, hotel: 0, vehicle: 0, activity: 0, addOns: 0, margin: 0, sellingPrice: 0, jammuSurcharge: 0 };

    let hotelCost = 0;
    let vehicleCost = 0;
    let activityCost = 0;
    let addOnsCost = 0;
    let jammuSurcharge = 0;

    const JAMMU_DAILY_SURCHARGE = 1000;

    trip.itinerary.forEach(day => {
      if (day.hotelId) {
        const hotel = HOTELS.find(h => h.id === day.hotelId);
        if (hotel) hotelCost += hotel.ratePerNight;
      }
      if (day.vehicleId) {
        const vehicle = VEHICLES.find(v => v.id === day.vehicleId);
        if (vehicle) {
          vehicleCost += vehicle.ratePerDay;
          if (trip.startLocation === 'Jammu') {
            jammuSurcharge += JAMMU_DAILY_SURCHARGE;
          }
        }
      }
      day.activityIds.forEach(aid => {
        const act = ACTIVITIES.find(a => a.id === aid);
        if (act) activityCost += act.costPerPax * trip.pax;
      });
    });

    trip.addOnIds.forEach(aoId => {
      const ao = ADD_ONS.find(a => a.id === aoId);
      if (ao) {
        addOnsCost += ao.isPerPax ? ao.cost * trip.pax : ao.cost;
      }
    });

    const subtotal = hotelCost + vehicleCost + jammuSurcharge + activityCost + addOnsCost;
    const margin = subtotal * (trip.marginPercentage / 100);
    const sellingPrice = subtotal + margin;

    return { 
      total: subtotal, 
      hotel: hotelCost, 
      vehicle: vehicleCost + jammuSurcharge, 
      jammuSurcharge,
      activity: activityCost, 
      addOns: addOnsCost, 
      margin, 
      sellingPrice 
    };
  }, [trip]);

  if (!trip) return <div className="p-10 text-center font-bold text-slate-400">Loading Trip Details...</div>;

  const handleSaveAsTemplate = () => {
    if (!trip) return;
    const templateName = prompt("Enter a name for this template:", `${trip.tripName} (Standard)`);
    if (!templateName) return;

    const newTemplate: TripTemplate = {
      id: `temp-${Date.now()}`,
      name: templateName,
      duration: `${trip.itinerary.length} Days, ${trip.itinerary.length - 1} Nights`,
      tripType: trip.tripType,
      baseMargin: trip.marginPercentage,
      itinerary: JSON.parse(JSON.stringify(trip.itinerary))
    };

    const savedRaw = localStorage.getItem('et_templates');
    const saved = savedRaw ? JSON.parse(savedRaw) : [];
    saved.push(newTemplate);
    localStorage.setItem('et_templates', JSON.stringify(saved));
    alert("Itinerary saved to templates library!");
  };

  const handleSaveTrip = () => {
    if (!trip) return;
    const newVersion: TripVersion = {
      id: `v-${Date.now()}`,
      timestamp: new Date().toISOString(),
      itinerary: JSON.parse(JSON.stringify(trip.itinerary)),
      marginPercentage: trip.marginPercentage,
      addOnIds: [...trip.addOnIds],
      label: `Update ${new Date().toLocaleTimeString()}`
    };

    const updatedTrip = { ...trip, versions: [newVersion, ...(trip.versions || [])] };
    setTrip(updatedTrip);

    // Force immediate save for peace of mind
    const savedTrips = localStorage.getItem('et_trips');
    let allTrips: Trip[] = savedTrips ? JSON.parse(savedTrips) : [...MOCK_TRIPS];
    const index = allTrips.findIndex(t => t.id === updatedTrip.id);
    if (index > -1) allTrips[index] = updatedTrip;
    else allTrips.push(updatedTrip);
    localStorage.setItem('et_trips', JSON.stringify(allTrips));

    alert("Changes saved successfully!");
  };

  const handleRestoreVersion = (version: TripVersion) => {
    if (window.confirm(`Restore to version from ${new Date(version.timestamp).toLocaleString()}?`)) {
      setTrip({
        ...trip,
        itinerary: JSON.parse(JSON.stringify(version.itinerary)),
        marginPercentage: version.marginPercentage,
        addOnIds: [...version.addOnIds]
      });
      setShowHistory(false);
      setActiveDayIndex(0);
    }
  };

  const handleAddDay = async () => {
    if (!trip) return;
    const nextDayNum = trip.itinerary.length + 1;
    const lastDay = trip.itinerary[trip.itinerary.length - 1];

    const newDay: ItineraryDay = {
      id: `d-${Date.now()}`,
      dayNumber: nextDayNum,
      title: `Day ${nextDayNum}: Suggesting Title...`,
      hotelId: lastDay?.hotelId || '', 
      vehicleId: lastDay?.vehicleId || '', 
      activityIds: [],
      clientNotes: '',
      internalNotes: ''
    };

    const newItinerary = [...trip.itinerary, newDay];
    setTrip({ ...trip, itinerary: newItinerary });
    setActiveDayIndex(newItinerary.length - 1);

    const suggestedTitle = await suggestNextDayTitle(
      lastDay?.title || 'Start of Trip', 
      trip.tripType, 
      nextDayNum
    );

    setTrip(prev => {
      if (!prev) return null;
      const updatedItinerary = [...prev.itinerary];
      const targetDay = updatedItinerary[updatedItinerary.length - 1];
      if (targetDay && targetDay.title.includes('Suggesting Title...')) {
        updatedItinerary[updatedItinerary.length - 1] = { ...targetDay, title: suggestedTitle };
      }
      return { ...prev, itinerary: updatedItinerary };
    });
  };

  const updateDay = (index: number, updates: Partial<ItineraryDay>) => {
    const newItinerary = [...trip.itinerary];
    newItinerary[index] = { ...newItinerary[index], ...updates };
    setTrip({ ...trip, itinerary: newItinerary });
  };

  const handleAiDescription = async (index: number) => {
    const day = trip.itinerary[index];
    if (!day.title) return;

    setIsAiGenerating(true);
    const activities = day.activityIds.map(aid => ACTIVITIES.find(a => a.id === aid)?.name || '');
    const description = await generateDayDescription(day.title, activities);
    updateDay(index, { clientNotes: description });
    setIsAiGenerating(false);
  };

  const handleDownloadPdf = async () => {
    if (!trip || isDownloading) return;
    setIsDownloading(true);

    try {
      const h2p = (window as any).html2pdf;
      if (!h2p) throw new Error("PDF library (html2pdf) is not loaded correctly.");

      const renderZone = document.getElementById('pdf-render-zone');
      if (!renderZone) throw new Error("Internal render container not found.");

      renderZone.innerHTML = `
        <div style="padding: 60px; background-color: #ffffff; color: #1e293b; font-family: 'Helvetica', 'Arial', sans-serif; width: 210mm; min-height: 297mm; box-sizing: border-box;">
          <div style="display: flex; justify-content: space-between; border-bottom: 2px solid #e2e8f0; padding-bottom: 30px; margin-bottom: 40px;">
            <div>
              <h1 style="color: #2563eb; margin: 0; font-size: 32px; font-weight: bold; letter-spacing: -1px;">${BRAND_CONFIG.name}</h1>
              <p style="color: #64748b; margin: 8px 0; font-size: 14px; font-weight: 600; text-transform: uppercase; letter-spacing: 2px;">${BRAND_CONFIG.tagline}</p>
            </div>
            <div style="text-align: right; font-size: 12px; color: #64748b; line-height: 1.6;">
              <p style="margin:0; font-weight: bold; color: #1e293b;">${BRAND_CONFIG.email}</p>
              <p style="margin:0;">${BRAND_CONFIG.phone}</p>
              <p style="margin:0;">${BRAND_CONFIG.address}</p>
            </div>
          </div>

          <div style="margin-bottom: 40px; background: #f8fafc; padding: 40px; border-radius: 16px; border: 1px solid #f1f5f9;">
             <span style="font-size: 10px; font-weight: 900; color: #2563eb; text-transform: uppercase; letter-spacing: 2px; display: block; margin-bottom: 8px;">Private Itinerary</span>
             <h2 style="margin: 0; font-size: 28px; color: #0f172a; font-weight: 800;">${trip.tripName}</h2>
             <div style="margin-top: 15px; display: flex; gap: 30px;">
                <p style="margin: 0; font-size: 14px; color: #475569;">Guest: <strong style="color: #0f172a;">${trip.client.name}</strong></p>
                <p style="margin: 0; font-size: 14px; color: #475569;">Pax: <strong style="color: #0f172a;">${trip.pax}</strong></p>
                <p style="margin: 0; font-size: 14px; color: #475569;">Dates: <strong style="color: #0f172a;">${trip.startDate} to ${trip.endDate}</strong></p>
             </div>
          </div>

          <div style="display: block;">
            ${trip.itinerary.map(day => {
              const hotel = HOTELS.find(h => h.id === day.hotelId);
              return `
              <div style="margin-bottom: 35px; border-left: 3px solid #e2e8f0; padding-left: 25px; page-break-inside: avoid;">
                <h3 style="margin: 0 0 12px 0; font-size: 18px; color: #1e293b; font-weight: 700;">Day ${day.dayNumber}: ${day.title}</h3>
                <p style="font-size: 14px; line-height: 1.7; color: #475569; margin: 0 0 15px 0;">${day.clientNotes || 'Scheduled leisure and exploration.'}</p>
                ${hotel ? `
                <div style="display: inline-block; font-size: 11px; font-weight: 700; color: #2563eb; background: #eff6ff; padding: 6px 14px; border-radius: 6px; border: 1px solid #dbeafe;">
                  Accommodation: ${hotel.name}
                </div>` : ''}
              </div>
            `}).join('')}
          </div>

          <div style="margin-top: 50px; border-top: 2px solid #f1f5f9; padding-top: 30px; text-align: center;">
            <p style="font-size: 10px; color: #94a3b8; letter-spacing: 5px; text-transform: uppercase; font-weight: 700;">Escape Theory Kashmir</p>
          </div>
        </div>
      `;

      await new Promise(resolve => setTimeout(resolve, 500));

      const opt = {
        margin: 0,
        filename: `${trip.client.name.replace(/[^a-z0-9]/gi, '_')}_Itinerary.pdf`,
        image: { type: 'jpeg', quality: 0.98 },
        html2canvas: { scale: 2, useCORS: false, backgroundColor: '#ffffff', logging: false },
        jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' }
      };

      await h2p().from(renderZone.children[0]).set(opt).save();
      setDownloadSuccess(true);
      setTimeout(() => setDownloadSuccess(false), 4000);
    } catch (err) {
      console.error("PDF generation failed:", err);
      alert("Direct download failed. Use 'Print Preview' instead.");
    } finally {
      setIsDownloading(false);
    }
  };

  return (
    <div className="flex flex-col h-full space-y-6 relative">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-4">
          <button onClick={() => navigate('/trips')} className="p-2 hover:bg-white rounded-lg transition-colors border border-transparent hover:border-slate-200">
            <ArrowLeft size={20} className="text-slate-600" />
          </button>
          <div>
            <h1 className="text-2xl font-bold text-slate-900">{trip.tripName}</h1>
            <p className="text-slate-500 text-sm">Itinerary Builder • {trip.client.name}</p>
          </div>
        </div>
        <div className="flex items-center gap-3">
          <button 
            onClick={handleSaveAsTemplate}
            className="flex items-center gap-2 px-4 py-2 border border-slate-200 rounded-lg bg-white text-slate-700 font-bold hover:bg-slate-50 transition-all shadow-sm"
          >
            <Archive size={18} />
            Save as Template
          </button>

          <button 
            onClick={() => setShowHistory(!showHistory)}
            className={`flex items-center gap-2 px-4 py-2 border rounded-lg font-bold transition-all ${showHistory ? 'bg-slate-800 text-white border-slate-800' : 'bg-white border-slate-200 text-slate-700 hover:bg-slate-50'}`}
          >
            <History size={18} />
            History
          </button>

          <Link 
            to={`/trips/${trip.id}/print`}
            className="flex items-center gap-2 px-4 py-2 border border-slate-200 rounded-lg bg-white text-blue-600 font-bold hover:bg-blue-50 transition-all shadow-sm"
          >
            <ExternalLink size={18} />
            Print Preview
          </Link>

          <button 
            onClick={handleSaveTrip}
            className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg font-bold hover:bg-blue-700 transition-all shadow-md"
          >
            <Save size={18} />
            Save Changes
          </button>
        </div>
      </div>

      <div className="flex flex-1 gap-6 overflow-hidden relative">
        {/* Version History Sidebar */}
        {showHistory && (
          <div className="absolute inset-y-0 right-0 w-80 bg-white border-l border-slate-200 shadow-2xl z-20 flex flex-col animate-in slide-in-from-right duration-300">
