                    className="w-full p-3 bg-slate-50 border border-slate-200 rounded-lg text-sm font-medium text-slate-900"
                  >
                    <option value="">Select Vehicle</option>
                    {VEHICLES.map(v => <option key={v.id} value={v.id}>{v.type}</option>)}
                  </select>
                </div>
              </div>

              <div className="space-y-4">
                <div className="flex items-center justify-between">
                  <label className="text-sm font-bold text-slate-700">Client Description</label>
                  <button 
                    onClick={() => handleAiDescription(activeDayIndex)}
                    disabled={isAiGenerating}
                    className="flex items-center gap-2 text-xs font-black uppercase text-blue-600 bg-blue-50 px-3 py-1.5 rounded-full disabled:opacity-50"
                  >
                    <Sparkles size={12} />
                    {isAiGenerating ? 'AI Magic...' : 'AI Enhance'}
                  </button>
                </div>
                <textarea 
                  rows={4}
                  value={trip.itinerary[activeDayIndex].clientNotes}
                  onChange={(e) => updateDay(activeDayIndex, { clientNotes: e.target.value })}
                  className="w-full p-4 bg-slate-50 border border-slate-200 rounded-xl text-sm leading-relaxed text-slate-900 focus:ring-2 focus:ring-blue-500 outline-none"
                />
              </div>

              <div className="space-y-4">
                <label className="text-sm font-bold text-slate-500">Internal Operational Notes</label>
                <textarea 
                  rows={2}
                  value={trip.itinerary[activeDayIndex].internalNotes}
                  onChange={(e) => updateDay(activeDayIndex, { internalNotes: e.target.value })}
                  className="w-full p-4 bg-amber-50/30 border border-amber-100 rounded-xl text-sm italic text-slate-800 outline-none"
                />
              </div>
            </div>
          ) : (
            <div className="flex flex-col items-center justify-center h-64 bg-white border-2 border-dashed border-slate-200 rounded-xl text-slate-400">
              <CalendarDays size={48} className="mb-4 opacity-20" />
              <p className="font-bold">Select a day to start building the itinerary.</p>
            </div>
          )}
        </div>

        {/* Costing Engine */}
        <div className="w-80 bg-slate-900 text-white rounded-xl shadow-2xl p-6 flex flex-col h-fit sticky top-0">
          <div className="flex items-center gap-2 mb-6 border-b border-slate-800 pb-4">
            <Calculator className="text-blue-400" size={20} />
            <h3 className="font-bold text-lg">Financial Summary</h3>
          </div>

          <div className="space-y-4 flex-1">
            <div className="flex justify-between items-center text-sm">
              <span className="text-slate-400">Hotels Total</span>
              <span className="font-bold">₹ {costs.hotel.toLocaleString()}</span>
            </div>
            <div className="flex justify-between items-center text-sm">
              <span className="text-slate-400">Vehicle Base</span>
              <span className="font-bold">₹ {(costs.vehicle - costs.jammuSurcharge).toLocaleString()}</span>
            </div>
            {costs.jammuSurcharge > 0 && (
              <div className="flex justify-between items-center text-sm">
                <span className="text-blue-400 font-medium">Jammu Surcharge</span>
                <span className="font-bold text-blue-400">₹ {costs.jammuSurcharge.toLocaleString()}</span>
              </div>
            )}
            <div className="flex justify-between items-center text-sm">
              <span className="text-slate-400">Activities Total</span>
              <span className="font-bold">₹ {costs.activity.toLocaleString()}</span>
            </div>
            <div className="pt-4 border-t border-slate-800">
              <div className="flex justify-between items-center text-xs uppercase font-black text-slate-500 mb-2">
                <span>Margin %</span>
                <input 
                  type="number" 
                  value={trip.marginPercentage}
                  onChange={(e) => setTrip({ ...trip, marginPercentage: Number(e.target.value) })}
                  className="w-12 bg-transparent border-none p-0 text-right text-blue-400 font-black focus:ring-0"
                />
              </div>
              <div className="flex justify-between items-center text-emerald-400 font-bold">
                <span>Profit</span>
                <span>₹ {Math.round(costs.margin).toLocaleString()}</span>
              </div>
            </div>
          </div>

          <div className="mt-10 pt-6 border-t border-slate-800">
            <p className="text-[10px] uppercase font-black tracking-widest text-slate-500 mb-1">Total Quote</p>
            <h2 className="text-4xl font-black text-white">₹ {Math.round(costs.sellingPrice).toLocaleString()}</h2>

            <div className="mt-6 space-y-3">
              <button 
                onClick={handleDownloadPdf}
                disabled={isDownloading}
                className={`w-full py-4 rounded-xl font-black uppercase tracking-widest text-xs flex items-center justify-center gap-3 transition-all ${
                  downloadSuccess 
                    ? 'bg-emerald-600 text-white shadow-lg shadow-emerald-900/40' 
                    : 'bg-blue-600 text-white hover:bg-blue-700 shadow-lg shadow-blue-900/40'
                } disabled:opacity-50 disabled:cursor-not-allowed`}
              >
                {isDownloading ? (
                  <Clock className="animate-spin" size={16} />
                ) : downloadSuccess ? (
                  <Check size={16} />
                ) : (
                  <Download size={16} />
                )}
                {isDownloading ? 'Generating...' : downloadSuccess ? 'Success' : 'Direct PDF'}
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default TripBuilder;

import React, { useState, useEffect, useMemo } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { 
  Plus, 
  Trash2, 
  Save, 
  Sparkles,
  ArrowLeft,
  CalendarDays,
  Hotel as HotelIcon,
  Car as CarIcon,
  Clock,
  Settings,
  Briefcase,
  Layers,
  Filter
} from 'lucide-react';
import { MOCK_TEMPLATES, HOTELS, VEHICLES, ACTIVITIES, TripTemplate } from '../constants';
import { ItineraryDay, TripType, HotelCategory } from '../types';
import { generateDayDescription, suggestNextDayTitle } from '../services/geminiService';

const TemplateBuilder: React.FC = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const [template, setTemplate] = useState<TripTemplate | null>(null);
  const [activeDayIndex, setActiveDayIndex] = useState(0);
  const [isAiGenerating, setIsAiGenerating] = useState(false);
  const [hotelCategoryFilter, setHotelCategoryFilter] = useState<string>('All');

  useEffect(() => {
    // Load combined templates
    const savedTemplatesRaw = localStorage.getItem('et_templates');
    const savedTemplates = savedTemplatesRaw ? JSON.parse(savedTemplatesRaw) : [];
    const merged = [...MOCK_TEMPLATES, ...savedTemplates];

    const found = merged.find(t => t.id === id);
    if (found) {
      setTemplate(JSON.parse(JSON.stringify(found))); // Deep clone for editing
    } else {
      // Default blank template if id is "new" or not found
      setTemplate({
        id: `temp-${Date.now()}`,
        name: 'New Custom Template',
        duration: '1 Day',
        tripType: TripType.FAMILY,
        baseMargin: 15,
        itinerary: []
      });
    }
  }, [id]);

  // Sync category filter when activeDayIndex changes
  useEffect(() => {
    if (template?.itinerary[activeDayIndex]?.hotelId) {
      const currentHotel = HOTELS.find(h => h.id === template.itinerary[activeDayIndex].hotelId);
      if (currentHotel) {
        setHotelCategoryFilter(currentHotel.category);
      } else {
        setHotelCategoryFilter('All');
      }
    } else {
      setHotelCategoryFilter('All');
    }
  }, [activeDayIndex, template?.itinerary]);

  const filteredHotels = useMemo(() => {
    if (hotelCategoryFilter === 'All') return HOTELS;
    return HOTELS.filter(h => h.category === hotelCategoryFilter);
  }, [hotelCategoryFilter]);

  if (!template) return <div className="p-10 text-center text-slate-400 font-bold">Loading Template...</div>;

  const handleSave = () => {
    if (!template) return;

    const savedTemplatesRaw = localStorage.getItem('et_templates');
    let savedTemplates: TripTemplate[] = savedTemplatesRaw ? JSON.parse(savedTemplatesRaw) : [];

    const index = savedTemplates.findIndex(t => t.id === template.id);
    if (index > -1) {
      savedTemplates[index] = template;
    } else {
      savedTemplates.push(template);
    }

    localStorage.setItem('et_templates', JSON.stringify(savedTemplates));
    alert("Template updated successfully!");
    navigate('/templates');
  };

  const updateDay = (index: number, updates: Partial<ItineraryDay>) => {
    const newItinerary = [...template.itinerary];
    newItinerary[index] = { ...newItinerary[index], ...updates };
    setTemplate({ ...template, itinerary: newItinerary });
  };

  const handleAddDay = async () => {
    const nextDayNum = template.itinerary.length + 1;
    const lastDay = template.itinerary[template.itinerary.length - 1];

    const newDay: ItineraryDay = {
      id: `d-${Date.now()}`,
      dayNumber: nextDayNum,
      title: `Day ${nextDayNum}: Suggesting...`,
      hotelId: lastDay?.hotelId || '', 
      vehicleId: lastDay?.vehicleId || '', 
      activityIds: [],
      clientNotes: '',
      internalNotes: ''
    };

    const newItinerary = [...template.itinerary, newDay];
    setTemplate({ ...template, itinerary: newItinerary, duration: `${nextDayNum} Days, ${nextDayNum - 1} Nights` });
    setActiveDayIndex(newItinerary.length - 1);

    const suggestedTitle = await suggestNextDayTitle(
      lastDay?.title || 'Start of Trip', 
      template.tripType, 
      nextDayNum
    );

    updateDay(newItinerary.length - 1, { title: suggestedTitle });
  };

  const handleAiDescription = async (index: number) => {
    const day = template.itinerary[index];
    if (!day.title) return;

    setIsAiGenerating(true);
    const activities = day.activityIds.map(aid => ACTIVITIES.find(a => a.id === aid)?.name || '');
    const description = await generateDayDescription(day.title, activities);
    updateDay(index, { clientNotes: description });
    setIsAiGenerating(false);
  };

  const removeDay = (index: number) => {
    if (!window.confirm("Delete this day from template?")) return;
    const newItinerary = template.itinerary.filter((_, i) => i !== index);
    // Re-index day numbers
    const reindexed = newItinerary.map((day, i) => ({ ...day, dayNumber: i + 1 }));
    setTemplate({ ...template, itinerary: reindexed, duration: `${reindexed.length} Days` });
    setActiveDayIndex(Math.max(0, activeDayIndex - 1));
  };

  return (
    <div className="flex flex-col h-full space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-4">
          <button onClick={() => navigate('/templates')} className="p-2 hover:bg-white rounded-lg transition-colors border border-transparent hover:border-slate-200">
            <ArrowLeft size={20} className="text-slate-600" />
          </button>
          <div>
            <h1 className="text-2xl font-bold text-slate-900">Template Builder</h1>
            <p className="text-slate-500 text-sm">Design reusable itineraries for standard packages.</p>
          </div>
        </div>
        <div className="flex items-center gap-3">
          <button 
            onClick={handleSave}
            className="flex items-center gap-2 px-6 py-2.5 bg-blue-600 text-white rounded-xl font-bold hover:bg-blue-700 transition-all shadow-lg shadow-blue-100"
          >
            <Save size={18} />
            Save Template
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-6 flex-1 overflow-hidden">
        {/* Metadata Sidebar */}
        <div className="lg:col-span-1 space-y-6 flex flex-col">
          <div className="bg-white border border-slate-200 rounded-2xl p-6 space-y-4 shadow-sm">
            <h3 className="font-bold text-slate-800 flex items-center gap-2 text-sm uppercase tracking-widest">
              <Settings size={16} className="text-blue-600" />
              General Info
            </h3>

            <div className="space-y-4">
              <div className="space-y-1">
                <label className="text-[10px] font-black uppercase text-slate-400">Template Name</label>
                <input 
                  type="text" 
                  value={template.name}
                  onChange={(e) => setTemplate({ ...template, name: e.target.value })}
                  className="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-lg text-sm text-slate-900 font-bold"
                />
              </div>

              <div className="space-y-1">
                <label className="text-[10px] font-black uppercase text-slate-400">Default Margin %</label>
                <input 
                  type="number" 
                  value={template.baseMargin}
                  onChange={(e) => setTemplate({ ...template, baseMargin: parseInt(e.target.value) })}
                  className="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-lg text-sm text-slate-900 font-bold"
                />
              </div>

              <div className="space-y-1">
                <label className="text-[10px] font-black uppercase text-slate-400">Trip Type</label>
                <select 
                  value={template.tripType}
                  onChange={(e) => setTemplate({ ...template, tripType: e.target.value as TripType })}
                  className="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-lg text-sm text-slate-900 font-bold"
                >
                  {Object.values(TripType).map(t => <option key={t} value={t}>{t}</option>)}
                </select>
              </div>
            </div>
          </div>

          <div className="bg-white border border-slate-200 rounded-2xl flex-1 flex flex-col overflow-hidden shadow-sm">
            <div className="p-4 border-b border-slate-100 flex items-center justify-between">
              <h3 className="font-bold text-slate-800 flex items-center gap-2 text-sm">
                <Layers size={16} className="text-blue-600" />
                Itinerary Steps
              </h3>
            </div>
            <div className="flex-1 overflow-y-auto p-4 space-y-2">
              {template.itinerary.map((day, idx) => (
                <button
                  key={day.id}
                  onClick={() => setActiveDayIndex(idx)}
                  className={`w-full text-left p-3 rounded-xl border transition-all ${
                    activeDayIndex === idx 
                      ? 'border-blue-600 bg-blue-50 shadow-sm' 
                      : 'border-slate-100 hover:border-slate-300'
                  }`}
                >
                  <div className="flex justify-between items-center mb-1">
                    <span className="text-[10px] font-black uppercase text-blue-600">Day {day.dayNumber}</span>
                  </div>
                  <h4 className={`font-semibold text-sm truncate ${activeDayIndex === idx ? 'text-blue-900' : 'text-slate-700'}`}>
                    {day.title || 'New Step'}
                  </h4>
                </button>
              ))}
              <button 
                onClick={handleAddDay}
                className="w-full py-4 border-2 border-dashed border-slate-200 rounded-xl text-slate-400 font-bold hover:border-blue-400 hover:text-blue-500 transition-all flex items-center justify-center gap-2 text-sm"
              >
                <Plus size={18} />
                Add Step
              </button>
            </div>
          </div>
        </div>

        {/* Day Editor */}
        <div className="lg:col-span-3 overflow-y-auto pr-2 pb-10">
          {template.itinerary[activeDayIndex] ? (
            <div className="bg-white border border-slate-200 rounded-2xl shadow-sm p-8 space-y-8 animate-in fade-in slide-in-from-right-4 duration-200 text-slate-900">
              <div className="flex justify-between items-start">
                <div className="flex-1 space-y-2">
                  <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">Step Title</label>
                  <input 
                    type="text" 
                    value={template.itinerary[activeDayIndex].title}
                    onChange={(e) => updateDay(activeDayIndex, { title: e.target.value })}
                    className="text-3xl font-bold text-slate-900 border-none p-0 focus:ring-0 placeholder:text-slate-300 w-full bg-transparent"
                    placeholder="e.g. Arrival & Shikara Ride"
                  />
                </div>
                <button 
                  onClick={() => removeDay(activeDayIndex)}
                  className="p-2 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition-all"
                  title="Remove Day"
                >
                  <Trash2 size={20} />
                </button>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                <div className="space-y-4">
                  <div className="flex flex-col gap-3">
                    <label className="text-sm font-bold text-slate-700 flex items-center gap-2">
                      <HotelIcon size={16} className="text-blue-500" />
                      Standard Stay
                    </label>

                    {/* Category Selection Filter */}
                    <div className="bg-slate-50 border border-slate-100 p-3 rounded-xl flex flex-col gap-2">
                      <label className="text-[9px] font-black uppercase tracking-widest text-slate-400 flex items-center gap-1.5">
                        <Filter size={10} />
                        Filter Category First
                      </label>
                      <div className="flex flex-wrap gap-1.5">
                        {['All', ...Object.values(HotelCategory)].map((cat) => (
                          <button
                            key={cat}
                            type="button"
                            onClick={() => setHotelCategoryFilter(cat)}
                            className={`px-3 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-wider transition-all border ${
                              hotelCategoryFilter === cat 
                                ? 'bg-blue-600 text-white border-blue-600 shadow-md' 
                                : 'bg-white text-slate-500 border-slate-200 hover:border-blue-300'
                            }`}
                          >
                            {cat}
                          </button>
                        ))}
                      </div>
                    </div>

                    <select 
                      value={template.itinerary[activeDayIndex].hotelId}
                      onChange={(e) => updateDay(activeDayIndex, { hotelId: e.target.value })}
                      className="w-full p-3 bg-white border border-slate-200 rounded-xl text-sm font-black text-slate-900 shadow-sm"
                    >
                      <option value="">Select Hotel from {hotelCategoryFilter}</option>
                      {filteredHotels.map(h => (
                        <option key={h.id} value={h.id}>
                          {h.name} ({h.location})
                        </option>
                      ))}
                    </select>
                  </div>
                </div>

                <div className="space-y-4">
                  <label className="text-sm font-bold text-slate-700 flex items-center gap-2">
                    <CarIcon size={16} className="text-blue-500" />
                    Standard Vehicle
                  </label>
                  <select 
                    value={template.itinerary[activeDayIndex].vehicleId}
                    onChange={(e) => updateDay(activeDayIndex, { vehicleId: e.target.value })}
                    className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl text-sm font-medium text-slate-900"
                  >
                    <option value="">Select Suggested Vehicle</option>
                    {VEHICLES.map(v => <option key={v.id} value={v.id}>{v.type}</option>)}
                  </select>
                </div>
              </div>

              <div className="space-y-4">
                <div className="flex items-center justify-between">
                  <label className="text-sm font-bold text-slate-700">Client Description (Template)</label>
                  <button 
                    onClick={() => handleAiDescription(activeDayIndex)}
                    disabled={isAiGenerating}
                    className="flex items-center gap-2 text-xs font-black uppercase text-blue-600 bg-blue-50 px-4 py-2 rounded-full disabled:opacity-50 hover:bg-blue-100 transition-colors"
                  >
                    <Sparkles size={12} />
                    {isAiGenerating ? 'AI Processing...' : 'AI Generate Content'}
                  </button>
                </div>
                <textarea 
                  rows={6}
                  value={template.itinerary[activeDayIndex].clientNotes}
                  onChange={(e) => updateDay(activeDayIndex, { clientNotes: e.target.value })}
                  className="w-full p-4 bg-slate-50 border border-slate-200 rounded-2xl text-sm leading-relaxed text-slate-900 focus:ring-2 focus:ring-blue-500 outline-none"
                  placeholder="Describe what the guest will experience on this day..."
                />
              </div>

              <div className="space-y-4">
                <label className="text-sm font-bold text-slate-500 flex items-center gap-2">
                  <Briefcase size={14} />
                  Operational Instructions (Internal)
                </label>
                <textarea 
                  rows={2}
                  value={template.itinerary[activeDayIndex].internalNotes}
                  onChange={(e) => updateDay(activeDayIndex, { internalNotes: e.target.value })}
                  className="w-full p-4 bg-amber-50/20 border border-amber-100/50 rounded-2xl text-sm italic text-slate-800 outline-none"
                  placeholder="e.g. Ensure flower bouquet is ready for arrival..."
                />
              </div>
            </div>
          ) : (
            <div className="flex flex-col items-center justify-center h-96 bg-white border-2 border-dashed border-slate-200 rounded-2xl text-slate-400">
              <Layers size={64} className="mb-4 opacity-10" />
              <p className="font-bold">Add steps to this template to build your itinerary structure.</p>
              <button 
                onClick={handleAddDay}
                className="mt-6 px-6 py-2 bg-blue-600 text-white rounded-xl font-bold hover:bg-blue-700"
              >
                Add First Step
              </button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

