                <input type="text" value={template.itinerary[activeDayIndex].title} onChange={(e) => updateDay(activeDayIndex, { title: e.target.value })} className="text-3xl font-bold text-slate-900 border-none p-0 focus:ring-0 placeholder:text-slate-300 w-full bg-transparent" />
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                <div className="space-y-4">
                  <div className="flex flex-col gap-3">
                    <label className="text-sm font-bold text-slate-700 flex items-center gap-2"><HotelIcon size={16} className="text-blue-500" />Standard Stay</label>
                    <div className="bg-slate-50 border border-slate-100 p-3 rounded-xl flex flex-col gap-2">
                      <div className="flex flex-wrap gap-1.5">
                        {['All', ...Object.values(HotelCategory)].map((cat) => (
                          <button key={cat} type="button" onClick={() => setHotelCategoryFilter(cat)} className={`px-3 py-1.5 rounded-lg text-[10px] font-black uppercase tracking-wider border ${hotelCategoryFilter === cat ? 'bg-blue-600 text-white border-blue-600' : 'bg-white text-slate-500 border-slate-200'}`}>{cat}</button>
