                    <select value={template.itinerary[activeDayIndex].hotelId} onChange={(e) => updateDay(activeDayIndex, { hotelId: e.target.value })} className="w-full p-3 bg-white border border-slate-200 rounded-xl text-sm font-black text-slate-900 shadow-sm">
                      <option value="">Select Hotel from {hotelCategoryFilter}</option>
                      {filteredHotels.map(h => <option key={h.id} value={h.id}>{h.name} ({h.location})</option>)}
                    </select>

                    {/* Property Preview Card */}
                    {selectedHotel && (
                      <div className="mt-2 bg-white border border-slate-200 rounded-2xl overflow-hidden shadow-sm animate-in zoom-in-95 duration-200">
                        <div className="h-28 relative">
                          <img 
                            src={selectedHotel.gallery?.[0] || `https://picsum.photos/seed/${selectedHotel.id}/400/200`} 
                            className="w-full h-full object-cover" 
                            alt="Hotel thumbnail" 
                          />
                          <div className="absolute inset-0 bg-gradient-to-t from-slate-900/60 to-transparent" />
                          <div className="absolute bottom-3 left-3 flex items-center gap-2">
                            <span className="px-2 py-0.5 bg-blue-600 text-white text-[8px] font-black uppercase rounded shadow-sm">
                              {selectedHotel.category}
                            </span>
                          </div>
                        </div>
                        <div className="p-3 flex justify-between items-center">
