                        <span className="text-lg font-black text-slate-900">₹{viewingHotel.cpRate.toLocaleString()}</span>
                      </div>
                    )}
                    {viewingHotel.mapRate && (
                      <div className="bg-blue-50 border border-blue-100 p-4 rounded-2xl group hover:bg-white transition-all">
                        <div className="flex items-center gap-2 mb-2"><Utensils size={14} className="text-blue-500" /><span className="text-[9px] font-black uppercase text-blue-600">MAP (+ Dinner)</span></div>
                        <span className="text-lg font-black text-slate-900">₹{viewingHotel.mapRate.toLocaleString()}</span>
                      </div>
                    )}
                    {viewingHotel.apRate && (
                      <div className="bg-indigo-50 border border-indigo-100 p-4 rounded-2xl group hover:bg-white transition-all">
                        <div className="flex items-center gap-2 mb-2"><Utensils size={14} className="text-indigo-500" /><span className="text-[9px] font-black uppercase text-indigo-600">AP (Full Board)</span></div>
                        <span className="text-lg font-black text-slate-900">₹{viewingHotel.apRate.toLocaleString()}</span>
                      </div>
                    )}
                  </div>
                </div>

                {viewingHotel.internalNotes && (
                  <div>
                    <h4 className="text-[11px] font-black uppercase tracking-[0.2em] text-slate-400 flex items-center gap-3 mb-4">
                      <div className="w-8 h-px bg-slate-200" />
                      Internal Operational Notes
                    </h4>
                    <p className="text-sm text-slate-600 bg-amber-50/50 p-6 rounded-2xl border border-amber-100 italic leading-relaxed">
                      "{viewingHotel.internalNotes}"
                    </p>
                  </div>
                )}
              </div>

              <div className="md:col-span-4 space-y-6">
                <div className="bg-slate-50 p-6 rounded-[28px] border border-slate-100 space-y-6">
                  <div>
                    <p className="text-[9px] font-black uppercase tracking-[0.2em] text-slate-400 mb-2">Operational Contact</p>
                    <div className="flex items-center gap-3 bg-white p-4 rounded-2xl border border-slate-200 shadow-sm mb-3">
                      <Phone size={16} className="text-blue-600" />
                      <span className="text-sm font-black text-slate-800">{viewingHotel.contact}</span>
                    </div>
                    {viewingHotel.rateValidityDate && (
                      <div className="flex items-center gap-3 bg-white p-4 rounded-2xl border border-slate-200 shadow-sm">
                        <Clock size={16} className="text-amber-600" />
                        <span className="text-xs font-bold text-slate-600">Expiry: {new Date(viewingHotel.rateValidityDate).toLocaleDateString()}</span>
                      </div>
                    )}
                  </div>

                  {viewingHotel.attachmentData && (
                    <div className="pt-4 border-t border-slate-100">
                      <p className="text-[9px] font-black uppercase tracking-[0.2em] text-slate-400 mb-2">Contract / Rate Sheet</p>
                      <button 
                        onClick={() => downloadAttachment(viewingHotel)}
                        className="w-full flex items-center justify-between p-4 bg-white rounded-2xl border border-slate-200 hover:border-blue-400 transition-all group"
                      >
                        <div className="flex items-center gap-3 overflow-hidden">
                          <FileText size={18} className="text-slate-400 group-hover:text-blue-600" />
                          <span className="text-xs font-bold text-slate-700 truncate">{viewingHotel.attachmentName}</span>
                        </div>
                        <Download size={16} className="text-slate-400" />
                      </button>
                    </div>
                  )}

                  {viewingHotel.extraBedRate && (
                    <div>
                      <p className="text-[9px] font-black uppercase tracking-[0.2em] text-slate-400 mb-2">Policy</p>
                      <div className="flex items-center justify-between bg-amber-50 px-4 py-3 rounded-xl">
                        <span className="text-[10px] font-bold text-amber-800">Extra Bed Cost</span>
                        <span className="text-sm font-black text-amber-900">₹{viewingHotel.extraBedRate.toLocaleString()}</span>
                      </div>
                    </div>
                  )}
                </div>

                <div className="flex flex-col gap-3 pt-4">
                  <button 
                    onClick={() => { setViewingHotel(null); openEditModal(viewingHotel); }}
                    className="w-full py-4 bg-slate-900 text-white text-[11px] font-black uppercase tracking-[0.2em] rounded-2xl shadow-xl flex items-center justify-center gap-3"
                  >
                    <Edit2 size={16} /> Modify Entry
                  </button>
                  <button onClick={() => setViewingHotel(null)} className="w-full py-4 bg-slate-100 text-slate-500 text-[11px] font-black uppercase tracking-[0.2em] rounded-2xl">Close</button>
                </div>
              </div>
            </div>
          </div>
        </div>
      )}

      {/* Add/Edit Hotel Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[60] flex items-center justify-center p-4 overflow-y-auto">
          <div className="bg-white rounded-3xl shadow-2xl w-full max-w-3xl my-8 overflow-hidden animate-in zoom-in-95 duration-200">
            <div className="bg-slate-50 p-6 border-b border-slate-100 flex items-center justify-between sticky top-0 z-10">
              <div className="flex items-center gap-3">
                <div className="bg-blue-600 p-2.5 rounded-xl text-white shadow-lg">
                  {editingHotelId ? <Edit2 size={20} /> : <HotelIcon size={20} />}
                </div>
                <div>
                  <h3 className="font-bold text-slate-900">{editingHotelId ? `Edit Property Inventory` : 'New Hotel Registration'}</h3>
                  <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Database Record</p>
                </div>
              </div>
              <button onClick={() => setIsModalOpen(false)} className="p-2 hover:bg-slate-200 rounded-full transition-colors text-slate-400"><X size={20} /></button>
            </div>

            <form onSubmit={handleSaveHotel} className="p-8 space-y-10">
              {/* Media Section */}
              <div className="space-y-4">
                <h4 className="text-xs font-black uppercase tracking-widest text-blue-600 border-b border-blue-50 pb-2">Property Media Gallery</h4>
                <div className="grid grid-cols-5 gap-4">
                  {formData.gallery?.map((img, i) => (
                    <div key={i} className="aspect-square rounded-xl overflow-hidden relative group border border-slate-200 shadow-sm">
                      <img src={img} className="w-full h-full object-cover" alt="Gallery item" />
                      <button type="button" onClick={() => removeGalleryImage(i)} className="absolute top-1 right-1 p-1.5 bg-red-600 text-white rounded-full opacity-0 group-hover:opacity-100 transition-opacity"><Trash2 size={12} /></button>
                    </div>
                  ))}
                  <button 
                    type="button" 
                    onClick={() => galleryInputRef.current?.click()}
                    className="aspect-square rounded-xl border-2 border-dashed border-slate-200 bg-slate-50 flex flex-col items-center justify-center text-slate-400 hover:border-blue-400 hover:text-blue-500 transition-all"
                  >
                    <ImageIcon size={24} />
                    <span className="text-[9px] font-black uppercase mt-1">Upload</span>
                    <input type="file" multiple ref={galleryInputRef} className="hidden" onChange={handleGalleryUpload} accept="image/*" />
                  </button>
                </div>
              </div>

              {/* Core Info Section */}
              <div className="space-y-6">
                <h4 className="text-xs font-black uppercase tracking-widest text-blue-600 border-b border-blue-50 pb-2">Core Property Information</h4>
                <div className="grid grid-cols-2 gap-6">
                  <div className="col-span-2 space-y-1.5">
                    <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Hotel Name</label>
                    <input required type="text" className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl outline-none font-bold text-slate-900" value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} />
                  </div>
                  <div className="space-y-1.5">
                    <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Location / City</label>
                    <input required type="text" className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl outline-none font-bold text-slate-900" value={formData.location} onChange={e => setFormData({...formData, location: e.target.value})} />
                  </div>
                  <div className="space-y-1.5">
                    <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Property Category</label>
                    <select className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl outline-none font-black text-slate-900" value={formData.category} onChange={e => setFormData({...formData, category: e.target.value as HotelCategory})}>
                      {Object.values(HotelCategory).map(c => <option key={c} value={c}>{c}</option>)}
                    </select>
                  </div>
                  <div className="space-y-1.5">
                    <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Front Office / Sales Phone</label>
                    <input required type="text" className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl outline-none font-bold text-slate-900" value={formData.contact} onChange={e => setFormData({...formData, contact: e.target.value})} />
