                      <input type="url" placeholder="https://..." className="w-full pl-11 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl outline-none font-medium text-slate-900" value={formData.hotelLink} onChange={e => setFormData({...formData, hotelLink: e.target.value})} />
