          </div>
        </div>
        <div className="flex gap-4">
          <button 
            onClick={() => window.print()} 
            className="bg-white border border-slate-200 text-slate-700 px-6 py-3 rounded-2xl font-black uppercase tracking-widest text-[11px] flex items-center gap-3 transition-all hover:bg-slate-50 active:scale-95"
          >
            <Printer size={18} /> Browser Print
          </button>
          <button 
            onClick={handleDownloadPdf} 
            disabled={isGenerating}
            className="bg-slate-900 text-white px-8 py-3 rounded-2xl font-black uppercase tracking-widest text-[11px] flex items-center gap-3 shadow-2xl transition-all active:scale-95 disabled:opacity-70 disabled:cursor-not-allowed"
