import React, { useState, useMemo, useEffect } from 'react';
import { useParams, useNavigate, Link } from 'react-router-dom';
import { 
  Plus, 
  Trash2, 
  Save, 
  ChevronDown, 
  ChevronUp, 
  Copy, 
  Share2, 
  Calculator,
  Sparkles,
  ArrowLeft,
  CalendarDays,
  Hotel as HotelIcon,
  Car as CarIcon,
  Activity as ActivityIcon,
  History,
  RotateCcw,
  Clock,
  FileText,
  Download,
  ExternalLink,
  Check,
  AlertCircle,
  Archive,
  UserCheck,
  Wallet,
  MapPin,
  TrendingUp,
  Filter,
  Stars,
  Layers,
  Anchor,
  Image as ImageIcon,
  MapPinned,
  Utensils,
  Map as MapIcon
} from 'lucide-react';
import { MOCK_TRIPS, HOTELS, VEHICLES, ACTIVITIES, ADD_ONS, BRAND_CONFIG, TripTemplate } from '../constants';
import { Trip, ItineraryDay, TripVersion, HotelCategory, Hotel, MealPlan, TripStatus } from '../types';
import { generateDayDescription, suggestNextDayTitle } from '../services/geminiService';

const TripBuilder: React.FC = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const [trip, setTrip] = useState<Trip | null>(null);
  const [activeDayIndex, setActiveDayIndex] = useState(0);
  const [isAiGenerating, setIsAiGenerating] = useState(false);
  const [isDownloading, setIsDownloading] = useState(false);
  const [downloadSuccess, setDownloadSuccess] = useState(false);
  const [showHistory, setShowHistory] = useState(false);

  const [hotelCategoryFilter, setHotelCategoryFilter] = useState<string>('All');

  const masterHotels = useMemo(() => {
    const saved = localStorage.getItem('et_hotels');
    const custom = saved ? JSON.parse(saved) : [];
    const customIds = new Set(custom.map((h: Hotel) => h.id));
    return [...HOTELS.filter(h => !customIds.has(h.id)), ...custom];
  }, []);

  useEffect(() => {
    const savedTrips = localStorage.getItem('et_trips');
    let foundTrip: Trip | undefined;

    if (savedTrips) {
      const parsed = JSON.parse(savedTrips);
      foundTrip = parsed.find((t: Trip) => t.id === id);
    }

    if (!foundTrip) {
      foundTrip = MOCK_TRIPS.find(t => t.id === id);
    }

    if (foundTrip) {
      setTrip({ ...foundTrip, startLocation: foundTrip.startLocation || 'Srinagar' });
    }
  }, [id]);

  useEffect(() => {
    if (trip) {
      const savedTrips = localStorage.getItem('et_trips');
      let allTrips: Trip[] = savedTrips ? JSON.parse(savedTrips) : [...MOCK_TRIPS];
      const index = allTrips.findIndex(t => t.id === trip.id);
      if (index > -1) allTrips[index] = trip;
      else allTrips.push(trip);
      localStorage.setItem('et_trips', JSON.stringify(allTrips));
    }
  }, [trip]);

  useEffect(() => {
    if (trip?.itinerary[activeDayIndex]?.hotelId) {
      const currentHotel = masterHotels.find(h => h.id === trip.itinerary[activeDayIndex].hotelId);
      if (currentHotel) setHotelCategoryFilter(currentHotel.category);
      else setHotelCategoryFilter('All');
    } else {
      setHotelCategoryFilter('All');
    }
  }, [activeDayIndex, trip?.itinerary, masterHotels]);

  const costs = useMemo(() => {
    if (!trip) return { total: 0, hotel: 0, vehicle: 0, activity: 0, addOns: 0, margin: 0, sellingPrice: 0, jammuSurcharge: 0 };
    let hotelCost = 0, vehicleCost = 0, activityCost = 0, addOnsCost = 0, jammuSurcharge = 0;
    const JAMMU_DAILY_SURCHARGE = 1000;

    trip.itinerary.forEach(day => {
      if (day.hotelId) {
        const hotel = masterHotels.find(h => h.id === day.hotelId);
        if (hotel) {
          let nightRate = hotel.ratePerNight;
          if (day.mealPlan === MealPlan.EP && hotel.epRate) nightRate = hotel.epRate;
          else if (day.mealPlan === MealPlan.CP && hotel.cpRate) nightRate = hotel.cpRate;
          else if (day.mealPlan === MealPlan.MAP && hotel.mapRate) nightRate = hotel.mapRate;
          else if (day.mealPlan === MealPlan.AP && hotel.apRate) nightRate = hotel.apRate;

          hotelCost += nightRate;
        }
      }
      if (day.vehicleId) {
        const vehicle = VEHICLES.find(v => v.id === day.vehicleId);
        if (vehicle) {
          vehicleCost += vehicle.ratePerDay;
          if (trip.startLocation === 'Jammu') jammuSurcharge += JAMMU_DAILY_SURCHARGE;
        }
      }
      day.activityIds.forEach(aid => {
        const act = ACTIVITIES.find(a => a.id === aid);
        if (act) activityCost += act.costPerPax * trip.pax;
      });
    });

    trip.addOnIds.forEach(aoId => {
      const ao = ADD_ONS.find(a => a.id === aoId);
      if (ao) addOnsCost += ao.isPerPax ? ao.cost * trip.pax : ao.cost;
    });

    const subtotal = hotelCost + vehicleCost + jammuSurcharge + activityCost + addOnsCost;
    const margin = subtotal * (trip.marginPercentage / 100);
    const sellingPrice = subtotal + margin;
    return { total: subtotal, hotel: hotelCost, vehicle: vehicleCost, jammuSurcharge, activity: activityCost, addOns: addOnsCost, margin, sellingPrice };
  }, [trip, masterHotels]);

  const filteredHotels = useMemo(() => {
    if (hotelCategoryFilter === 'All') return masterHotels;
    return masterHotels.filter(h => h.category === hotelCategoryFilter);
  }, [hotelCategoryFilter, masterHotels]);

  const selectedHotel = useMemo(() => {
    const hotelId = trip?.itinerary[activeDayIndex]?.hotelId;
    return masterHotels.find(h => h.id === hotelId);
  }, [trip?.itinerary, activeDayIndex, masterHotels]);

  if (!trip) return <div className="p-10 text-center font-bold text-slate-400">Loading...</div>;

  const updateDay = (index: number, updates: Partial<ItineraryDay>) => {
    const newItinerary = [...trip.itinerary];
    newItinerary[index] = { ...newItinerary[index], ...updates };
    setTrip({ ...trip, itinerary: newItinerary });
  };

  const handleAddDay = async () => {
    const nextDayNum = trip.itinerary.length + 1;
    const lastDay = trip.itinerary[trip.itinerary.length - 1];

    const newDay: ItineraryDay = {
      id: `d-${Date.now()}`,
      dayNumber: nextDayNum,
      title: `Day ${nextDayNum}: Suggesting...`,
      hotelId: lastDay?.hotelId || '',
      mealPlan: lastDay?.mealPlan || MealPlan.CP,
      vehicleId: lastDay?.vehicleId || '',
      activityIds: [],
      clientNotes: '',
      internalNotes: ''
    };

    const newItinerary = [...trip.itinerary, newDay];
    setTrip({ ...trip, itinerary: newItinerary });
    setActiveDayIndex(newItinerary.length - 1);

    const suggestedTitle = await suggestNextDayTitle(lastDay?.title || 'Arrival', trip.tripName, nextDayNum);
    updateDay(newItinerary.length - 1, { title: suggestedTitle });
  };

  const handleDuplicateDay = (index: number) => {
    const dayToCopy = trip.itinerary[index];
    const newDay = {
      ...dayToCopy,
      id: `d-${Date.now()}`,
      dayNumber: trip.itinerary.length + 1
    };
    const newItinerary = [...trip.itinerary, newDay];
    setTrip({ ...trip, itinerary: newItinerary });
    setActiveDayIndex(newItinerary.length - 1);
  };

  const handleDeleteDay = (index: number) => {
    if (trip.itinerary.length <= 1) {
      alert("At least one day is required.");
      return;
    }
    const newItinerary = trip.itinerary
      .filter((_, i) => i !== index)
      .map((day, i) => ({ ...day, dayNumber: i + 1 }));

    setTrip({ ...trip, itinerary: newItinerary });
    setActiveDayIndex(Math.max(0, index - 1));
  };

  const handleAiDescription = async (index: number) => {
    const day = trip.itinerary[index];
    if (!day.title) return;
    setIsAiGenerating(true);
    const activities = day.activityIds.map(aid => ACTIVITIES.find(a => a.id === aid)?.name || '');
    const description = await generateDayDescription(day.title, activities);
    updateDay(index, { clientNotes: description });
    setIsAiGenerating(false);
  };

  const handleDownloadPdf = async () => {
    if (!trip || isDownloading) return;
    setIsDownloading(true);
    try {
      const h2p = (window as any).html2pdf;
      const renderZone = document.getElementById('pdf-render-zone');
      if (!renderZone) throw new Error("Internal render container not found.");

      renderZone.innerHTML = `
        <div style="padding: 60px; background-color: #ffffff; color: #1e293b; font-family: 'Helvetica', 'Arial', sans-serif; width: 210mm; min-height: 297mm; box-sizing: border-box;">
          <h1 style="color: #2563eb; margin: 0; font-size: 32px; font-weight: bold;">${BRAND_CONFIG.name}</h1>
          <h2 style="margin: 20px 0; font-size: 28px; color: #0f172a;">${trip.tripName}</h2>
          ${trip.itinerary.map(day => {
            const hotel = masterHotels.find(h => h.id === day.hotelId);
            return `
              <div style="margin-bottom: 30px; border-left: 3px solid #e2e8f0; padding-left: 20px;">
                <h3 style="margin-bottom: 10px;">Day ${day.dayNumber}: ${day.title}</h3>
                <p>${day.clientNotes || 'Standard exploration.'}</p>
                ${hotel ? `<div style="color: #2563eb; font-weight: bold; font-size: 12px;">Stay: ${hotel.name} (${day.mealPlan || 'EP'})</div>` : ''}
              </div>
            `}).join('')}
        </div>
      `;
      const opt = { margin: 0, filename: `${trip.client.name}_Itinerary.pdf`, image: { type: 'jpeg', quality: 0.98 }, html2canvas: { scale: 2 }, jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' } };
      await h2p().from(renderZone.children[0]).set(opt).save();
      setDownloadSuccess(true);
      setTimeout(() => setDownloadSuccess(false), 4000);
    } catch (err) { alert("Download failed."); } finally { setIsDownloading(false); }
  };

  return (
    <div className="flex flex-col h-full space-y-6 relative">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-4">
          <button onClick={() => navigate('/trips')} className="p-2 hover:bg-white rounded-lg border border-transparent hover:border-slate-200"><ArrowLeft size={20} className="text-slate-600" /></button>
          <div>
            <h1 className="text-2xl font-bold text-slate-900">{trip.tripName}</h1>
            <div className="flex items-center gap-2">
              <p className="text-slate-500 text-sm">Itinerary Builder • {trip.client.name}</p>
              <span className="text-slate-300">•</span>
              <div className="flex items-center gap-1.5 bg-slate-100 px-2 py-0.5 rounded-full">
                <MapIcon size={12} className="text-slate-500" />
                <select 
                  className="bg-transparent text-[10px] font-black uppercase text-slate-700 outline-none cursor-pointer"
                  value={trip.startLocation}
                  onChange={(e) => setTrip({ ...trip, startLocation: e.target.value as 'Srinagar' | 'Jammu' })}
                >
                  <option value="Srinagar">Srinagar Start</option>
                  <option value="Jammu">Jammu Start (+₹1k Surcharge)</option>
                </select>
              </div>
            </div>
          </div>
        </div>
        <div className="flex items-center gap-3">
          <button onClick={() => setShowHistory(!showHistory)} className={`flex items-center gap-2 px-4 py-2 border rounded-lg font-bold transition-all ${showHistory ? 'bg-slate-800 text-white border-slate-800' : 'bg-white border-slate-200 text-slate-700'}`}><History size={18} />History</button>
          <button onClick={() => setTrip({...trip})} className="flex items-center gap-2 px-4 py-2 bg-blue-600 text-white rounded-lg font-bold hover:bg-blue-700 shadow-md transition-all"><Save size={18} />Save Changes</button>
        </div>
      </div>

      <div className="flex flex-1 gap-6 overflow-hidden relative">
        <div className="w-80 bg-white border border-slate-200 rounded-xl flex flex-col overflow-hidden">
          <div className="p-4 border-b border-slate-100 flex items-center justify-between">
            <h3 className="font-bold text-slate-800 flex items-center gap-2"><CalendarDays size={18} className="text-blue-600" />Itinerary</h3>
            <span className="text-xs font-bold text-slate-400">{trip.itinerary.length} Days</span>
          </div>
          <div className="flex-1 overflow-y-auto p-4 space-y-3">
            {trip.itinerary.map((day, idx) => (
              <div key={day.id} className="relative group">
                <button 
                  onClick={() => setActiveDayIndex(idx)} 
                  className={`w-full text-left p-3 pr-10 rounded-lg border transition-all ${activeDayIndex === idx ? 'border-blue-600 bg-blue-50 shadow-sm' : 'border-slate-100 hover:border-slate-300'}`}
                >
                  <div className="flex justify-between items-center"><span className="text-[10px] font-black uppercase text-blue-600">Day {day.dayNumber}</span></div>
                  <h4 className={`font-semibold truncate ${activeDayIndex === idx ? 'text-blue-900' : 'text-slate-700'}`}>{day.title || 'Untitled Day'}</h4>
                </button>
                <div className="absolute right-2 top-1/2 -translate-y-1/2 flex flex-col gap-1 opacity-0 group-hover:opacity-100 transition-opacity">
                  <button onClick={(e) => { e.stopPropagation(); handleDuplicateDay(idx); }} className="p-1 hover:text-blue-600 text-slate-400 bg-white border border-slate-200 rounded shadow-sm"><Copy size={12} /></button>
                  <button onClick={(e) => { e.stopPropagation(); handleDeleteDay(idx); }} className="p-1 hover:text-red-600 text-slate-400 bg-white border border-slate-200 rounded shadow-sm"><Trash2 size={12} /></button>
                </div>
              </div>
            ))}
            <button 
