                          <div className="absolute inset-0 bg-gradient-to-t from-slate-900/60 to-transparent" />
                          <div className="absolute bottom-3 left-3 flex items-center gap-2">
                            <span className="px-2 py-0.5 bg-blue-600 text-white text-[8px] font-black uppercase rounded shadow-sm">
                              {selectedHotel.category}
                            </span>
                          </div>
                        </div>
                        <div className="p-3 flex justify-between items-center">
                          <div>
                            <p className="text-xs font-bold text-slate-800">{selectedHotel.name}</p>
                            <p className="text-[10px] text-slate-400 flex items-center gap-1 font-medium">
                              <MapPinned size={10} /> {selectedHotel.location}
                            </p>
                          </div>
                          <div className="text-right">
                            <p className="text-[10px] font-black text-slate-400 uppercase leading-none">Net Cost</p>
                            <p className="text-sm font-black text-blue-600">
                              ₹{(() => {
                                let rate = selectedHotel.ratePerNight;
                                const mp = trip.itinerary[activeDayIndex].mealPlan;
                                if (mp === MealPlan.EP && selectedHotel.epRate) rate = selectedHotel.epRate;
                                else if (mp === MealPlan.CP && selectedHotel.cpRate) rate = selectedHotel.cpRate;
                                else if (mp === MealPlan.MAP && selectedHotel.mapRate) rate = selectedHotel.mapRate;
                                else if (mp === MealPlan.AP && selectedHotel.apRate) rate = selectedHotel.apRate;
                                return rate.toLocaleString();
                              })()}
                            </p>
                          </div>
                        </div>
                      </div>
                    )}
                  </div>
                </div>

                <div className="space-y-4">
                  <label className="text-sm font-bold text-slate-700 flex items-center gap-2"><CarIcon size={16} className="text-blue-500" />Transport</label>
                  <select value={trip.itinerary[activeDayIndex].vehicleId} onChange={(e) => updateDay(activeDayIndex, { vehicleId: e.target.value })} className="w-full p-3 bg-slate-50 border border-slate-200 rounded-lg text-sm font-medium text-slate-900">
                    <option value="">Select Vehicle</option>
                    {VEHICLES.map(v => <option key={v.id} value={v.id}>{v.type}</option>)}
                  </select>
                </div>
              </div>

              <div className="space-y-4">
                <div className="flex items-center justify-between">
                  <label className="text-sm font-bold text-slate-700">Client Description</label>
                  <button onClick={() => handleAiDescription(activeDayIndex)} disabled={isAiGenerating} className="flex items-center gap-2 text-xs font-black uppercase text-blue-600 bg-blue-50 px-3 py-1.5 rounded-full disabled:opacity-50"><Sparkles size={12} />{isAiGenerating ? 'AI Magic...' : 'AI Enhance'}</button>
                </div>
                <textarea rows={4} value={trip.itinerary[activeDayIndex].clientNotes} onChange={(e) => updateDay(activeDayIndex, { clientNotes: e.target.value })} className="w-full p-4 bg-slate-50 border border-slate-200 rounded-xl text-sm leading-relaxed text-slate-900 focus:ring-2 focus:ring-blue-500 outline-none" />
              </div>

              <div className="space-y-4">
                <label className="text-sm font-bold text-slate-500">Internal Operational Notes</label>
                <textarea rows={2} value={trip.itinerary[activeDayIndex].internalNotes} onChange={(e) => updateDay(activeDayIndex, { internalNotes: e.target.value })} className="w-full p-4 bg-amber-50/20 border border-amber-100 rounded-xl text-sm italic text-slate-800 outline-none" />
              </div>
            </div>
          ) : (
            <div className="flex flex-col items-center justify-center h-64 bg-white border-2 border-dashed border-slate-200 rounded-xl text-slate-400">
              <CalendarDays size={48} className="mb-4 opacity-20" /><p className="font-bold">Select a day to start building.</p>
            </div>
          )}
        </div>

        <div className="w-80 bg-slate-900 text-white rounded-xl shadow-2xl p-6 flex flex-col h-fit sticky top-0">
          <div className="flex items-center gap-2 mb-6 border-b border-slate-800 pb-4"><Calculator className="text-blue-400" size={20} /><h3 className="font-bold text-lg">Financial Summary</h3></div>
          <div className="space-y-4 flex-1">
            <div className="flex justify-between items-center text-sm"><span className="text-slate-400">Hotels Total</span><span className="font-bold">₹ {costs.hotel.toLocaleString()}</span></div>
            <div className="flex justify-between items-center text-sm"><span className="text-slate-400">Vehicle Base Total</span><span className="font-bold">₹ {costs.vehicle.toLocaleString()}</span></div>
            {costs.jammuSurcharge > 0 && (
              <div className="flex justify-between items-center text-sm text-amber-400">
                <span className="flex items-center gap-1"><MapPin size={12} /> Jammu Surcharge</span>
                <span className="font-bold">₹ {costs.jammuSurcharge.toLocaleString()}</span>
              </div>
            )}
            <div className="flex justify-between items-center text-sm"><span className="text-slate-400">Activities Total</span><span className="font-bold">₹ {costs.activity.toLocaleString()}</span></div>
            <div className="pt-4 border-t border-slate-800">
              <div className="flex justify-between items-center text-xs uppercase font-black text-slate-500 mb-2"><span>Margin %</span><input type="number" value={trip.marginPercentage} onChange={(e) => setTrip({ ...trip, marginPercentage: Number(e.target.value) })} className="w-12 bg-transparent border-none p-0 text-right text-blue-400 font-black focus:ring-0" /></div>
              <div className="flex justify-between items-center text-emerald-400 font-bold"><span>Profit</span><span>₹ {Math.round(costs.margin).toLocaleString()}</span></div>
            </div>
          </div>
          <div className="mt-10 pt-6 border-t border-slate-800">
            <p className="text-[10px] uppercase font-black tracking-widest text-slate-500 mb-1">Total Quote</p>
            <h2 className="text-4xl font-black text-white">₹ {Math.round(costs.sellingPrice).toLocaleString()}</h2>

            <Link to={`/trips/${trip.id}/print`} className="mt-6 w-full py-4 bg-white text-slate-900 rounded-xl font-black uppercase tracking-widest text-xs flex items-center justify-center gap-3 transition-all hover:bg-slate-100">
              <ExternalLink size={16} /> Print Preview
            </Link>

            <button onClick={handleDownloadPdf} disabled={isDownloading} className={`mt-3 w-full py-4 rounded-xl font-black uppercase tracking-widest text-xs flex items-center justify-center gap-3 transition-all ${downloadSuccess ? 'bg-emerald-600 shadow-emerald-900/40' : 'bg-blue-600 hover:bg-blue-700 shadow-blue-900/40'} disabled:opacity-50`}>
              {isDownloading ? <Clock className="animate-spin" size={16} /> : downloadSuccess ? <Check size={16} /> : <Download size={16} />}
              {isDownloading ? 'Generating...' : downloadSuccess ? 'Success' : 'Direct PDF'}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default TripBuilder;

import React, { useState, useMemo, useEffect } from 'react';
import { useParams, useNavigate, Link } from 'react-router-dom';
import { 
  Plus, 
  Trash2, 
  Save, 
  ChevronDown, 
  ChevronUp, 
  Copy, 
  Share2, 
  Calculator,
  Sparkles,
  ArrowLeft,
  CalendarDays,
  Hotel as HotelIcon,
  Car as CarIcon,
  Activity as ActivityIcon,
  History,
  RotateCcw,
  Clock,
  FileText,
  Download,
  ExternalLink,
  Check,
  AlertCircle,
  Archive,
  UserCheck,
  Wallet,
  MapPin,
  TrendingUp,
  Filter,
  Stars,
  Layers,
  Anchor,
  Image as ImageIcon,
  MapPinned,
  Utensils,
  Map as MapIcon,
  PlusCircle,
  Printer,
  ChevronRight
} from 'lucide-react';
import { MOCK_TRIPS, HOTELS, VEHICLES, ACTIVITIES, ADD_ONS, BRAND_CONFIG } from '../constants';
import { Trip, ItineraryDay, TripVersion, HotelCategory, Hotel, MealPlan, TripStatus } from '../types';
import { generateDayDescription, suggestNextDayTitle } from '../services/geminiService';

// Main TripBuilder component for managing and designing customer itineraries
const TripBuilder: React.FC = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const [trip, setTrip] = useState<Trip | null>(null);
  const [activeDayIndex, setActiveDayIndex] = useState(0);
  const [isAiGenerating, setIsAiGenerating] = useState(false);
  const [isDownloading, setIsDownloading] = useState(false);
  const [downloadSuccess, setDownloadSuccess] = useState(false);
  const [showHistory, setShowHistory] = useState(false);

  const [hotelCategoryFilter, setHotelCategoryFilter] = useState<string>('All');

  // Memoized list of all available hotels, merging static constants with custom entries from local storage
  const masterHotels = useMemo(() => {
    const saved = localStorage.getItem('et_hotels');
    const custom = saved ? JSON.parse(saved) : [];
    const customIds = new Set(custom.map((h: Hotel) => h.id));
    return [...HOTELS.filter(h => !customIds.has(h.id)), ...custom];
  }, []);

  // Effect hook to load the specific trip data based on the route parameter 'id'
  useEffect(() => {
    const savedTrips = localStorage.getItem('et_trips');
    let foundTrip: Trip | undefined;

    if (savedTrips) {
      const parsed = JSON.parse(savedTrips);
      foundTrip = parsed.find((t: Trip) => t.id === id);
    }

    if (!foundTrip) {
      foundTrip = MOCK_TRIPS.find(t => t.id === id);
    }

    if (foundTrip) {
      setTrip({ ...foundTrip, startLocation: foundTrip.startLocation || 'Srinagar' });
    }
  }, [id]);

  // Sync component state changes back to local storage for persistence
  useEffect(() => {
    if (trip) {
      const savedTrips = localStorage.getItem('et_trips');
      let allTrips: Trip[] = savedTrips ? JSON.parse(savedTrips) : [...MOCK_TRIPS];
      const index = allTrips.findIndex(t => t.id === trip.id);
      if (index > -1) allTrips[index] = trip;
      else allTrips.push(trip);
      localStorage.setItem('et_trips', JSON.stringify(allTrips));
    }
  }, [trip]);

  // Synchronize category filter with the currently selected hotel on the active day
  useEffect(() => {
    if (trip?.itinerary[activeDayIndex]?.hotelId) {
      const currentHotel = masterHotels.find(h => h.id === trip.itinerary[activeDayIndex].hotelId);
      if (currentHotel) setHotelCategoryFilter(currentHotel.category);
      else setHotelCategoryFilter('All');
    } else {
      setHotelCategoryFilter('All');
    }
  }, [activeDayIndex, trip?.itinerary, masterHotels]);

  // Real-time cost calculator that accounts for hotels, transport (with Jammu surcharge), activities, and add-ons
  const costs = useMemo(() => {
    if (!trip) return { total: 0, hotel: 0, vehicle: 0, activity: 0, addOns: 0, margin: 0, sellingPrice: 0, jammuSurcharge: 0 };
    let hotelCost = 0, vehicleCost = 0, activityCost = 0, addOnsCost = 0, jammuSurcharge = 0;
    const JAMMU_DAILY_SURCHARGE = 1000;

    trip.itinerary.forEach(day => {
      if (day.hotelId) {
        const hotel = masterHotels.find(h => h.id === day.hotelId);
        if (hotel) {
          let nightRate = hotel.ratePerNight;
          if (day.mealPlan === MealPlan.EP && hotel.epRate) nightRate = hotel.epRate;
          else if (day.mealPlan === MealPlan.CP && hotel.cpRate) nightRate = hotel.cpRate;
          else if (day.mealPlan === MealPlan.MAP && hotel.mapRate) nightRate = hotel.mapRate;
          else if (day.mealPlan === MealPlan.AP && hotel.apRate) nightRate = hotel.apRate;

          hotelCost += nightRate;
        }
      }
      if (day.vehicleId) {
        const vehicle = VEHICLES.find(v => v.id === day.vehicleId);
        if (vehicle) {
          vehicleCost += vehicle.ratePerDay;
          if (trip.startLocation === 'Jammu') jammuSurcharge += JAMMU_DAILY_SURCHARGE;
        }
      }
      day.activityIds.forEach(aid => {
        const act = ACTIVITIES.find(a => a.id === aid);
        if (act) activityCost += act.costPerPax * trip.pax;
      });
    });

    trip.addOnIds.forEach(aoId => {
      const ao = ADD_ONS.find(a => a.id === aoId);
      if (ao) addOnsCost += ao.isPerPax ? ao.cost * trip.pax : ao.cost;
    });

    const subtotal = hotelCost + vehicleCost + jammuSurcharge + activityCost + addOnsCost;
    const margin = subtotal * (trip.marginPercentage / 100);
    const sellingPrice = subtotal + margin;
    return { total: subtotal, hotel: hotelCost, vehicle: vehicleCost, jammuSurcharge, activity: activityCost, addOns: addOnsCost, margin, sellingPrice };
  }, [trip, masterHotels]);

  const filteredHotels = useMemo(() => {
    if (hotelCategoryFilter === 'All') return masterHotels;
    return masterHotels.filter(h => h.category === hotelCategoryFilter);
  }, [hotelCategoryFilter, masterHotels]);

  const selectedHotel = useMemo(() => {
    const hotelId = trip?.itinerary[activeDayIndex]?.hotelId;
    return masterHotels.find(h => h.id === hotelId);
  }, [trip?.itinerary, activeDayIndex, masterHotels]);

  // Function to add a new itinerary day with smart default values and AI title suggestion
  const handleAddDay = async () => {
    if (!trip) return;
    const nextDayNum = trip.itinerary.length + 1;
    const lastDay = trip.itinerary[trip.itinerary.length - 1];

    const newDay: ItineraryDay = {
      id: `d-${Date.now()}`,
      dayNumber: nextDayNum,
      title: `Day ${nextDayNum}: Exploring...`,
      hotelId: lastDay?.hotelId || '',
      mealPlan: lastDay?.mealPlan || MealPlan.CP,
      vehicleId: lastDay?.vehicleId || '',
      activityIds: [],
      clientNotes: '',
      internalNotes: ''
    };

    const newItinerary = [...trip.itinerary, newDay];
    setTrip({ ...trip, itinerary: newItinerary });
    setActiveDayIndex(newItinerary.length - 1);

    try {
      const suggestedTitle = await suggestNextDayTitle(lastDay?.title || 'Arrival', trip.tripType, nextDayNum);
      updateDay(newItinerary.length - 1, { title: suggestedTitle });
    } catch (e) {
      console.warn("AI title suggestion failed");
    }
  };

  const handleDuplicateDay = (index: number) => {
    if (!trip) return;
    const dayToCopy = trip.itinerary[index];
    const newDay = {
      ...dayToCopy,
      id: `d-${Date.now()}`,
      dayNumber: trip.itinerary.length + 1
    };
    const newItinerary = [...trip.itinerary, newDay];
    setTrip({ ...trip, itinerary: newItinerary });
    setActiveDayIndex(newItinerary.length - 1);
  };

  const handleDeleteDay = (index: number) => {
    if (!trip) return;
    if (trip.itinerary.length <= 1) {
      alert("At least one day is required.");
      return;
    }
    const newItinerary = trip.itinerary
      .filter((_, i) => i !== index)
      .map((day, i) => ({ ...day, dayNumber: i + 1 }));

    setTrip({ ...trip, itinerary: newItinerary });
    setActiveDayIndex(Math.max(0, index - 1));
  };

  const updateDay = (index: number, updates: Partial<ItineraryDay>) => {
    if (!trip) return;
    const newItinerary = [...trip.itinerary];
    newItinerary[index] = { ...newItinerary[index], ...updates };
    setTrip({ ...trip, itinerary: newItinerary });
  };

  // Uses Gemini AI to generate a poetic and inviting description for the day based on planned activities
  const handleAiDescription = async (index: number) => {
    if (!trip) return;
    const day = trip.itinerary[index];
    if (!day.title) return;
    setIsAiGenerating(true);
    const activities = day.activityIds.map(aid => ACTIVITIES.find(a => a.id === aid)?.name || '');
    const description = await generateDayDescription(day.title, activities);
    updateDay(index, { clientNotes: description });
    setIsAiGenerating(false);
  };

  // Triggers navigation to the specialized printable client view
  const handleDownloadPdf = async () => {
    if (!trip || isDownloading) return;
    setIsDownloading(true);
    try {
      navigate(`/trips/${trip.id}/print`);
    } catch (err) {
      console.error("PDF generation failed:", err);
    } finally {
      setIsDownloading(false);
    }
  };

  // Saves a snapshot of the current itinerary to the version history
  const handleSaveVersion = () => {
    if (!trip) return;
    const label = prompt("Enter a label for this version:", `Version ${trip.versions.length + 1}`);
    if (!label) return;

    const newVersion: TripVersion = {
      id: `v-${Date.now()}`,
      timestamp: new Date().toISOString(),
      itinerary: JSON.parse(JSON.stringify(trip.itinerary)),
      marginPercentage: trip.marginPercentage,
      addOnIds: [...trip.addOnIds],
      label: label
    };

    setTrip({ ...trip, versions: [newVersion, ...trip.versions] });
  };

  if (!trip) return <div className="p-10 text-center font-bold text-slate-400">Loading Trip Builder...</div>;

  return (
    <div className="flex flex-col h-full space-y-6">
      {/* Header with Trip Stats and Main Actions */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
        <div className="flex items-center gap-4">
          <button onClick={() => navigate('/trips')} className="p-2 hover:bg-slate-50 rounded-lg transition-colors">
            <ArrowLeft size={20} className="text-slate-600" />
          </button>
          <div>
            <h1 className="text-2xl font-black text-slate-900 leading-tight">{trip.tripName}</h1>
            <div className="flex items-center gap-3 mt-1">
              <span className="text-xs font-bold text-slate-400 uppercase tracking-widest">{trip.client.name}</span>
              <span className="w-1 h-1 rounded-full bg-slate-200" />
              <span className={`px-2 py-0.5 rounded text-[10px] font-black uppercase tracking-widest ${
                trip.status === TripStatus.BOOKED ? 'bg-emerald-100 text-emerald-700' : 'bg-blue-100 text-blue-700'
              }`}>{trip.status}</span>
            </div>
          </div>
        </div>

        <div className="flex flex-wrap items-center gap-3">
          <div className="flex items-center gap-6 px-6 py-2 bg-slate-50 rounded-xl border border-slate-100 mr-4">
             <div className="text-right">
               <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Client Payable</p>
               <p className="text-lg font-black text-blue-600">₹{costs.sellingPrice.toLocaleString()}</p>
             </div>
             <div className="h-8 w-px bg-slate-200" />
             <div className="text-right">
               <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Net Profit ({trip.marginPercentage}%)</p>
               <p className="text-lg font-black text-emerald-600">₹{costs.margin.toLocaleString()}</p>
             </div>
          </div>

          <button 
            onClick={handleSaveVersion}
            className="p-2.5 bg-white border border-slate-200 rounded-xl text-slate-600 hover:bg-slate-50 transition-all shadow-sm"
            title="Save Version"
          >
            <History size={20} />
          </button>

          <button 
            onClick={handleDownloadPdf}
            className="flex items-center gap-2 bg-slate-900 text-white px-5 py-2.5 rounded-xl font-bold hover:bg-slate-800 transition-all shadow-lg"
          >
            <Download size={18} />
            PDF / Print
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-6 flex-1 overflow-hidden">
        {/* Left Sidebar: Day Navigation */}
        <div className="lg:col-span-2 flex flex-col gap-4 overflow-hidden">
           <div className="bg-white border border-slate-200 rounded-2xl flex-1 flex flex-col overflow-hidden shadow-sm">
             <div className="p-4 border-b border-slate-100 flex items-center justify-between">
               <h3 className="font-bold text-slate-800 flex items-center gap-2 text-sm uppercase tracking-wider">
                 <CalendarDays size={16} className="text-blue-600" /> Itinerary
               </h3>
             </div>
             <div className="flex-1 overflow-y-auto p-3 space-y-2">
               {trip.itinerary.map((day, idx) => (
                 <div key={day.id} className="relative group">
                   <button 
                     onClick={() => setActiveDayIndex(idx)}
                     className={`w-full text-left p-3 rounded-xl border transition-all ${
                       activeDayIndex === idx ? 'border-blue-600 bg-blue-50 shadow-sm' : 'border-slate-100 hover:border-slate-300'
                     }`}
                   >
                     <div className="flex justify-between items-center mb-1">
                       <span className="text-[10px] font-black uppercase text-blue-600">Day {day.dayNumber}</span>
                     </div>
                     <h4 className={`font-semibold text-xs truncate ${activeDayIndex === idx ? 'text-blue-900' : 'text-slate-700'}`}>
                       {day.title || 'Untitled Day'}
                     </h4>
                   </button>
                   <button 
                     onClick={(e) => { e.stopPropagation(); handleDeleteDay(idx); }}
                     className="absolute -top-1 -right-1 p-1 bg-white border border-slate-200 rounded-full text-slate-400 hover:text-red-500 opacity-0 group-hover:opacity-100 transition-opacity shadow-sm"
                   >
                     <Trash2 size={10} />
                   </button>
                 </div>
               ))}
               <button 
                 onClick={handleAddDay}
                 className="w-full py-4 border-2 border-dashed border-slate-200 rounded-xl text-slate-400 font-bold hover:border-blue-400 hover:text-blue-500 transition-all flex items-center justify-center gap-2 text-xs"
               >
                 <Plus size={16} /> Add Day
               </button>
             </div>
           </div>

           {/* Quick History Preview */}
           {trip.versions.length > 0 && (
             <div className="bg-white border border-slate-200 rounded-2xl p-4 shadow-sm">
                <h3 className="text-[10px] font-black uppercase text-slate-400 tracking-widest mb-3 flex items-center gap-2">
                  <RotateCcw size={12} /> Recent Versions
                </h3>
                <div className="space-y-2">
                  {trip.versions.slice(0, 3).map((v) => (
                    <div key={v.id} className="flex items-center justify-between text-[10px] font-bold text-slate-600 hover:text-blue-600 cursor-pointer p-1.5 hover:bg-blue-50 rounded">
                      <span className="truncate max-w-[80px]">{v.label}</span>
                      <span className="text-slate-300 font-medium">{new Date(v.timestamp).toLocaleDateString()}</span>
                    </div>
                  ))}
                </div>
             </div>
           )}
        </div>

        {/* Central Component: Itinerary Day Editor */}
        <div className="lg:col-span-7 flex flex-col gap-6 overflow-y-auto pr-2">
          {trip.itinerary[activeDayIndex] ? (
            <div className="bg-white border border-slate-200 rounded-2xl shadow-sm p-8 space-y-8 animate-in fade-in slide-in-from-right-4 duration-200">
               <div className="flex flex-col gap-2">
                 <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">Day Title</label>
                 <input 
                   type="text" 
                   value={trip.itinerary[activeDayIndex].title}
