                </div>
              </div>

              <div className="pt-8 flex gap-4 sticky bottom-0 bg-white shadow-[0_-15px_30px_rgba(255,255,255,1)] pb-4 z-10">
                <button type="button" onClick={() => setIsModalOpen(false)} className="flex-1 py-4 text-slate-500 font-bold rounded-2xl transition-all hover:bg-slate-50">Cancel</button>
                <button type="submit" className="flex-1 py-4 bg-blue-600 text-white font-black uppercase tracking-[0.1em] text-xs rounded-2xl shadow-xl transition-all hover:bg-blue-700 flex items-center justify-center gap-2">
                  <Check size={18} /> {editingHotelId ? 'Update Inventory Record' : 'Save Property to Database'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

