                     >
                       <Copy size={12} />
                     </button>
                     <button 
                       onClick={(e) => { e.stopPropagation(); handleDeleteDay(idx); }}
                       className="p-1 bg-white border border-slate-200 rounded text-slate-400 hover:text-red-500 shadow-sm"
                     >
                       <Trash2 size={12} />
                     </button>
                   </div>
                 </div>
               ))}
               <button 
