                     className="w-full p-4 bg-amber-50/50 border border-amber-100 rounded-2xl text-xs font-medium text-slate-700 italic outline-none"
                     placeholder="E.g. Coordinate with Shikara union head, ensure flowers are in the boat."
                   />
                 </div>
               </div>
