               <p className="text-sm mt-1">Select a day or add one to begin crafting the magic.</p>
               <button onClick={handleAddDay} className="mt-6 px-6 py-2 bg-blue-600 text-white rounded-xl font-bold hover:bg-blue-700 transition-all">Create Day 1</button>
            </div>
          )}
        </div>

        {/* Right Sidebar: Costs and Add-ons */}
        <div className="lg:col-span-3 space-y-6 overflow-y-auto pb-10">
           <div className="bg-white border border-slate-200 rounded-2xl p-6 shadow-sm space-y-6">
              <div className="flex items-center gap-2 text-sm font-black uppercase tracking-widest text-slate-800">
                <Wallet size={18} className="text-blue-600" /> Financials
              </div>

              <div className="space-y-3">
                <div className="flex justify-between items-center text-xs">
                   <span className="text-slate-500 font-bold uppercase">Subtotal Cost</span>
                   <span className="text-slate-900 font-black">₹{costs.total.toLocaleString()}</span>
                </div>
                {costs.jammuSurcharge > 0 && (
                  <div className="flex justify-between items-center text-[10px] font-black text-amber-600 uppercase tracking-widest bg-amber-50 px-2 py-1 rounded">
                     <span className="flex items-center gap-1"><MapPin size={10} /> Jammu Surcharge</span>
                     <span>₹{costs.jammuSurcharge.toLocaleString()}</span>
                  </div>
                )}
                <div className="flex justify-between items-center text-xs">
                   <div className="flex items-center gap-1.5">
                     <span className="text-slate-500 font-bold uppercase">Margin</span>
                     <input 
                       type="number" 
                       value={trip.marginPercentage}
                       onChange={(e) => setTrip({...trip, marginPercentage: parseInt(e.target.value) || 0})}
                       className="w-10 bg-slate-50 border border-slate-200 rounded px-1 py-0.5 text-[10px] font-black text-blue-600 text-center"
                     />
                     <span className="text-[10px] font-black text-slate-300">%</span>
                   </div>
                   <span className="text-emerald-600 font-black">₹{costs.margin.toLocaleString()}</span>
                </div>
                <div className="h-px bg-slate-100" />
                <div className="flex justify-between items-center pt-2">
                   <span className="text-sm font-black text-slate-900 uppercase">Total Quote</span>
                   <span className="text-xl font-black text-blue-600">₹{costs.sellingPrice.toLocaleString()}</span>
                </div>
              </div>

              {trip.startLocation === 'Jammu' && (
                <div className="bg-amber-50 border border-amber-100 p-3 rounded-xl flex items-center gap-3">
                   <AlertCircle size={16} className="text-amber-600 shrink-0" />
                   <p className="text-[10px] text-amber-800 font-bold leading-tight">Jammu start includes ₹1,000/day vehicle surcharge.</p>
                </div>
              )}
           </div>

           <div className="bg-white border border-slate-200 rounded-2xl p-6 shadow-sm space-y-6">
              <div className="flex items-center gap-2 text-sm font-black uppercase tracking-widest text-slate-800">
                <PlusCircle size={18} className="text-blue-600" /> Premium Add-ons
              </div>
              <div className="space-y-3">
                {ADD_ONS.map(addon => {
                  const isSelected = trip.addOnIds.includes(addon.id);
                  return (
                    <button
                      key={addon.id}
                      onClick={() => {
                        const newAddOns = isSelected 
                          ? trip.addOnIds.filter(id => id !== addon.id)
                          : [...trip.addOnIds, addon.id];
                        setTrip({...trip, addOnIds: newAddOns});
                      }}
                      className={`w-full text-left p-3 rounded-xl border transition-all flex items-center justify-between group ${
                        isSelected ? 'border-blue-600 bg-blue-50' : 'border-slate-100 hover:border-slate-200'
                      }`}
                    >
                      <div>
                        <p className={`text-xs font-bold ${isSelected ? 'text-blue-900' : 'text-slate-700'}`}>{addon.name}</p>
                        <p className="text-[9px] text-slate-400 font-bold">₹{addon.cost.toLocaleString()} {addon.isPerPax ? '/ pax' : 'total'}</p>
                      </div>
                      <div className={`p-1 rounded-full transition-all ${isSelected ? 'bg-blue-600 text-white' : 'bg-slate-100 text-slate-300 group-hover:bg-slate-200'}`}>
                        <Check size={12} />
                      </div>
                    </button>
                  );
                })}
              </div>
           </div>
        </div>
      </div>
    </div>
  );
};

