                    </div>
                    <div className="flex gap-4">
                      <button onClick={() => { setViewingHotel(null); openEditModal(viewingHotel); }} className="flex-1 py-3 bg-slate-900 text-white rounded-xl font-bold text-[11px] uppercase tracking-widest transition-all hover:bg-slate-800">Edit</button>
                      <button onClick={() => setViewingHotel(null)} className="flex-1 py-3 bg-slate-100 text-slate-500 rounded-xl font-bold text-[11px] uppercase tracking-widest transition-all hover:bg-slate-200">Close</button>
