                <div>
                  <h3 className="font-bold text-slate-900">{editingHotelId ? `Edit Property Inventory` : 'New Property Registration'}</h3>
                  <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Operational Database Entry</p>
                </div>
              </div>
              <button onClick={() => setIsModalOpen(false)} className="p-2 hover:bg-slate-200 rounded-full transition-colors text-slate-400"><X size={20} /></button>
