           <div className="bg-white border border-slate-200 rounded-2xl p-6 shadow-sm space-y-6">
              <div className="flex items-center gap-2 text-sm font-black uppercase tracking-widest text-slate-800">
                <PlusCircle size={18} className="text-blue-600" /> Add-ons
              </div>
              <div className="space-y-3">
                {ADD_ONS.map(addon => {
                  const isSelected = trip.addOnIds.includes(addon.id);
                  return (
                    <button
                      key={addon.id}
                      onClick={() => {
                        const newAddOns = isSelected ? trip.addOnIds.filter(id => id !== addon.id) : [...trip.addOnIds, addon.id];
                        setTrip({...trip, addOnIds: newAddOns});
                      }}
                      className={`w-full text-left p-3 rounded-xl border transition-all flex items-center justify-between ${
                        isSelected ? 'border-blue-600 bg-blue-50' : 'border-slate-100 hover:border-slate-200'
                      }`}
                    >
                      <span className="text-xs font-bold text-slate-700">{addon.name}</span>
                      {isSelected && <Check size={14} className="text-blue-600" />}
                    </button>
                  );
                })}
              </div>
           </div>
        </div>
      </div>
    </div>
  );
};

