          )}

          {/* DYNAMIC Inclusions & Exclusions */}
          <section className="bg-slate-50 rounded-[48px] p-12 grid grid-cols-2 gap-16 border border-slate-100 break-inside-avoid">
            <div className="space-y-6">
              <h4 className="text-xs font-black uppercase tracking-[0.2em] text-emerald-600 flex items-center gap-3">
                 <CheckCircle2 size={20} /> Inclusions
              </h4>
              <ul className="text-xs space-y-4 text-slate-600 font-bold">
                {trip.inclusions.map((item, i) => (
                  <li key={i} className="flex gap-2"><span>•</span> {item}</li>
                ))}
              </ul>
            </div>
            <div className="space-y-6">
              <h4 className="text-xs font-black uppercase tracking-[0.2em] text-rose-600 flex items-center gap-3">
                 <XCircle size={20} /> Exclusions
              </h4>
              <ul className="text-xs space-y-4 text-slate-600 font-bold">
                {trip.exclusions.map((item, i) => (
                  <li key={i} className="flex gap-2"><span>•</span> {item}</li>
                ))}
              </ul>
            </div>
          </section>

          <footer className="mt-32 pt-12 border-t border-slate-100 text-center pb-10">
            <p className="text-[11px] font-black text-slate-400 uppercase tracking-[0.8em] mb-4">Escape Theory Kashmir</p>
          </footer>
        </div>
      </div>
    </div>
  );
};

