import React, { useEffect, useState, useMemo, useRef } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { Mail, Phone, MapPin, Calendar, Users, CheckCircle2, XCircle, Info, X, Printer, ArrowLeft, Coffee, Utensils, Star, Mountain, Download, Loader2, Sparkles, Hotel as HotelIcon, Car as CarIcon, MapPinned } from 'lucide-react';
import { MOCK_TRIPS, BRAND_CONFIG, HOTELS, VEHICLES, ACTIVITIES, DEFAULT_INCLUSIONS, DEFAULT_EXCLUSIONS, ADD_ONS } from '../constants';
import { Trip, HotelCategory, Hotel, MealPlan, AddOn, Vehicle } from '../types';

const ClientItinerary: React.FC = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const [trip, setTrip] = useState<Trip | null>(null);
  const [isGenerating, setIsGenerating] = useState(false);
  const printableRef = useRef<HTMLDivElement>(null);

  const masterHotels = useMemo(() => {
    const saved = localStorage.getItem('et_hotels');
    const custom = saved ? JSON.parse(saved) : [];
    const customIds = new Set(custom.map((h: Hotel) => h.id));
    return [...HOTELS.filter(h => !customIds.has(h.id)), ...custom];
  }, []);

  const masterVehicles = useMemo(() => {
    const saved = localStorage.getItem('et_vehicles');
    const custom = saved ? JSON.parse(saved) : [];
    const customIds = new Set(custom.map((v: Vehicle) => v.id));
    return [...VEHICLES.filter(v => !customIds.has(v.id)), ...custom];
  }, []);

  const masterAddOns = useMemo(() => {
    const saved = localStorage.getItem('et_addons');
    const custom = saved ? JSON.parse(saved) : [];
    const customIds = new Set(custom.map((a: AddOn) => a.id));
    return [...ADD_ONS.filter(a => !customIds.has(a.id)), ...custom];
  }, []);

  useEffect(() => {
    const savedTrips = localStorage.getItem('et_trips');
    let foundTrip: Trip | undefined;

    if (savedTrips) {
      const parsed = JSON.parse(savedTrips);
      foundTrip = parsed.find((t: Trip) => t.id === id);
    }

    if (!foundTrip) {
      foundTrip = MOCK_TRIPS.find(t => t.id === id);
    }

    if (foundTrip) {
      setTrip({
        ...foundTrip,
        inclusions: foundTrip.inclusions || [...DEFAULT_INCLUSIONS],
        exclusions: foundTrip.exclusions || [...DEFAULT_EXCLUSIONS],
        addOnIds: foundTrip.addOnIds || []
      });
    }
  }, [id]);

  const selectedAddOns = useMemo(() => {
    if (!trip) return [];
    return masterAddOns.filter(ao => (trip.addOnIds || []).includes(ao.id));
  }, [trip, masterAddOns]);

  const handleDownloadPdf = async () => {
    if (!trip || !printableRef.current || isGenerating) return;

    setIsGenerating(true);
    try {
      const element = printableRef.current;
      const h2p = (window as any).html2pdf;

      const opt = {
        margin: 0,
        filename: `${trip.client.name}_Escape_Theory_Itinerary.pdf`,
        image: { type: 'jpeg', quality: 0.98 },
        html2canvas: { 
          scale: 2, 
          useCORS: true, 
          letterRendering: true,
          scrollX: 0,
          scrollY: 0
        },
        jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' },
        pagebreak: { mode: ['avoid-all', 'css', 'legacy'] }
      };

      const images = element.getElementsByTagName('img');
      const promises = Array.from(images).map(img => {
        if (img.complete) return Promise.resolve();
        return new Promise((resolve) => {
          img.onload = resolve;
          img.onerror = resolve;
        });
      });

      await Promise.all(promises);
      await h2p().from(element).set(opt).save();
    } catch (err) {
      console.error("PDF Generation Error:", err);
      alert("Failed to generate PDF. Please try the standard Print option.");
    } finally {
      setIsGenerating(false);
    }
  };

  if (!trip) return (
    <div className="p-20 text-center font-bold text-slate-400">
      <div className="animate-spin w-10 h-10 border-4 border-blue-600 border-t-transparent rounded-full mx-auto mb-6"></div>
    </div>
  );

  return (
    <div className="bg-slate-100 min-h-screen text-slate-900 print:bg-white overflow-x-hidden">
      {/* Interactive Controls */}
      <div className="no-print sticky top-0 bg-white/95 backdrop-blur-md border-b border-slate-200 z-[100] p-4 flex justify-between items-center px-10 shadow-sm">
        <button onClick={() => navigate(`/trips/${id}`)} className="text-slate-500 font-bold hover:text-slate-800 flex items-center gap-2 transition-colors py-2 px-3 hover:bg-slate-100 rounded-lg">
          <ArrowLeft size={18} /> Back to Builder
        </button>
        <div className="flex gap-4">
          <button onClick={() => window.print()} className="bg-white border border-slate-200 text-slate-700 px-6 py-3 rounded-2xl font-black uppercase tracking-widest text-[11px] flex items-center gap-3 transition-all hover:bg-slate-50">
            <Printer size={18} /> Print
          </button>
          <button onClick={handleDownloadPdf} disabled={isGenerating} className="bg-slate-900 text-white px-8 py-3 rounded-2xl font-black uppercase tracking-widest text-[11px] flex items-center gap-3 shadow-2xl transition-all disabled:opacity-70">
            {isGenerating ? <Loader2 size={18} className="animate-spin" /> : <Download size={18} />}
            {isGenerating ? 'Generating...' : 'Download PDF'}
          </button>
        </div>
      </div>

      {/* Printable Area */}
      <div className="max-w-[210mm] mx-auto bg-white shadow-2xl my-10 print:my-0 print:shadow-none" ref={printableRef}>
        <div className="p-[15mm] print:p-10">
          <header className="flex justify-between items-start border-b-2 border-slate-100 pb-10 mb-12">
            <div className="flex items-center gap-5">
              <img src={BRAND_CONFIG.logo} alt="Logo" className="w-20 h-20" />
              <div>
                <h1 className="text-4xl font-black text-slate-900 tracking-tighter leading-none">{BRAND_CONFIG.name}</h1>
                <p className="text-blue-600 font-black text-[11px] uppercase tracking-[0.3em] mt-2">{BRAND_CONFIG.tagline}</p>
              </div>
            </div>
          </header>

          <section className="bg-slate-900 rounded-[40px] p-12 mb-16 relative overflow-hidden text-white shadow-2xl">
            <div className="relative z-10 flex justify-between items-end">
              <div>
                <h2 className="text-6xl font-black tracking-tighter mb-4 leading-tight">{trip.tripName}</h2>
                <p className="text-slate-300 text-lg font-medium">Prepared for <span className="text-white font-black">{trip.client.name}</span></p>
              </div>
              <div className="text-right">
                <div className="flex items-center gap-2 justify-end mb-2">
                   <Calendar size={16} className="text-blue-400" />
                   <span className="text-sm font-bold">{new Date(trip.startDate).toLocaleDateString()} to {new Date(trip.endDate).toLocaleDateString()}</span>
                </div>
                <div className="flex items-center gap-2 justify-end">
                   <Users size={16} className="text-blue-400" />
                   <span className="text-sm font-bold">{trip.pax} Travelers</span>
                </div>
              </div>
            </div>
          </section>

          {/* Detailed Timeline */}
          <section className="space-y-32 mb-24">
            {trip.itinerary.map((day, idx) => {
              const hotel = masterHotels.find(h => h.id === day.hotelId);
              const vehicle = masterVehicles.find(v => v.id === day.vehicleId);
              return (
                <div key={day.id} className="grid grid-cols-12 gap-12 break-inside-avoid relative">
                  <div className="col-span-1 flex flex-col items-center">
                    <div className="w-14 h-14 rounded-2xl bg-slate-900 text-white flex items-center justify-center font-black text-xl shadow-lg">
                      {day.dayNumber}
                    </div>
                    <div className="w-0.5 h-full bg-slate-100 my-4" />
                  </div>
                  <div className="col-span-11 space-y-8">
                    <div>
                      <h4 className="text-4xl font-black text-slate-900 tracking-tight mb-6">{day.title}</h4>
                      <p className="text-slate-600 leading-relaxed text-xl font-medium border-l-8 border-blue-50 pl-8 whitespace-pre-line">
                        {day.clientNotes}
                      </p>
                    </div>

                    {/* Stay & Transport Visual Cards */}
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-8 pt-4">
                       {hotel && (
                         <div className="flex flex-col rounded-[32px] overflow-hidden border border-slate-100 bg-white shadow-xl hover:shadow-2xl transition-all">
                            <div className="h-48 relative">
                               <img 
                                 src={hotel.gallery?.[0] || `https://picsum.photos/seed/${hotel.id}/600/400`} 
                                 className="w-full h-full object-cover" 
                                 alt={hotel.name} 
                               />
                               <div className="absolute top-4 left-4">
                                  <span className="bg-white/90 backdrop-blur px-3 py-1.5 rounded-xl text-[10px] font-black uppercase text-blue-600 shadow-sm flex items-center gap-2">
                                     <HotelIcon size={12}/> {hotel.category}
                                  </span>
                               </div>
                            </div>
                            <div className="p-6">
                               <div className="flex justify-between items-start mb-2">
                                  <h5 className="text-lg font-black text-slate-900 leading-tight">{hotel.name}</h5>
                               </div>
                               <div className="flex items-center gap-4 text-slate-400">
                                  <span className="text-[11px] font-bold uppercase flex items-center gap-1.5">
                                     <MapPinned size={12}/> {hotel.location}
                                  </span>
                                  <span className="w-1 h-1 bg-slate-200 rounded-full" />
                                  <span className="text-[11px] font-bold uppercase flex items-center gap-1.5">
                                     <Coffee size={12}/> {day.mealPlan || 'Meal Plan Included'}
                                  </span>
                               </div>
                            </div>
                         </div>
                       )}

                       {vehicle && (
                         <div className="flex flex-col rounded-[32px] overflow-hidden border border-slate-100 bg-white shadow-xl hover:shadow-2xl transition-all">
                            <div className="h-48 relative bg-slate-50">
                               <img 
                                 src={vehicle.image || `https://picsum.photos/seed/${vehicle.id}/600/400`} 
                                 className="w-full h-full object-cover" 
                                 alt={vehicle.type} 
                               />
                               <div className="absolute top-4 left-4">
                                  <span className="bg-slate-900/90 backdrop-blur px-3 py-1.5 rounded-xl text-[10px] font-black uppercase text-white shadow-sm flex items-center gap-2">
                                     <CarIcon size={12}/> Private Transport
                                  </span>
                               </div>
                            </div>
                            <div className="p-6">
                               <h5 className="text-lg font-black text-slate-900 leading-tight mb-2">{vehicle.brand} {vehicle.type}</h5>
                               <div className="flex items-center gap-4 text-slate-400">
                                  <span className="text-[11px] font-bold uppercase flex items-center gap-1.5">
                                     <Users size={12}/> Upto {vehicle.capacity} Pax
                                  </span>
                                  <span className="w-1 h-1 bg-slate-200 rounded-full" />
                                  <span className="text-[11px] font-bold uppercase flex items-center gap-1.5">
                                     <Sparkles size={12}/> {vehicle.isAC ? 'Climate Controlled' : 'Standard'}
                                  </span>
                               </div>
                            </div>
                         </div>
                       )}
                    </div>
                  </div>
                </div>
              );
            })}
          </section>

          {/* PREMIUM ADD-ONS Section */}
          {selectedAddOns.length > 0 && (
            <section className="mb-24 break-inside-avoid">
              <h4 className="text-xs font-black uppercase tracking-[0.4em] text-slate-400 mb-8 border-b border-slate-100 pb-4 flex items-center gap-3">
                <Sparkles size={18} className="text-blue-600" /> Premium Experiences & Highlights
              </h4>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                {selectedAddOns.map(ao => (
                  <div key={ao.id} className="bg-slate-50 p-10 rounded-[48px] border border-slate-100 flex flex-col gap-4 shadow-sm">
                    <h5 className="font-black text-slate-900 text-2xl leading-tight">{ao.name}</h5>
                    <p className="text-slate-500 text-sm font-medium leading-relaxed">
                      {ao.description || 'A specially curated high-end experience designed by Escape Theory to make your journey unforgettable.'}
                    </p>
                  </div>
                ))}
              </div>
            </section>
          )}

          {/* DYNAMIC Inclusions & Exclusions */}
          <section className="bg-slate-900 rounded-[56px] p-16 grid grid-cols-2 gap-20 text-white break-inside-avoid shadow-2xl">
            <div className="space-y-8">
              <h4 className="text-xs font-black uppercase tracking-[0.3em] text-emerald-400 flex items-center gap-3">
                 <CheckCircle2 size={24} /> Standard Inclusions
              </h4>
              <ul className="text-sm space-y-5 text-slate-300 font-medium">
                {trip.inclusions.map((item, i) => (
                  <li key={i} className="flex gap-4">
                     <span className="text-emerald-500 font-black">•</span> 
                     <span className="flex-1">{item}</span>
                  </li>
                ))}
              </ul>
            </div>
            <div className="space-y-8">
              <h4 className="text-xs font-black uppercase tracking-[0.3em] text-rose-400 flex items-center gap-3">
                 <XCircle size={24} /> General Exclusions
              </h4>
              <ul className="text-sm space-y-5 text-slate-300 font-medium">
                {trip.exclusions.map((item, i) => (
                  <li key={i} className="flex gap-4">
                     <span className="text-rose-500 font-black">•</span> 
                     <span className="flex-1">{item}</span>
                  </li>
                ))}
              </ul>
            </div>
          </section>

          <footer className="mt-32 pt-16 border-t-2 border-slate-100 text-center pb-12">
            <img src={BRAND_CONFIG.logo} alt="Logo Small" className="w-12 h-12 mx-auto mb-6 grayscale opacity-20" />
            <p className="text-[12px] font-black text-slate-400 uppercase tracking-[0.6em] mb-4">Escape Theory Kashmir</p>
            <p className="text-[10px] text-slate-400 font-bold max-w-lg mx-auto leading-relaxed">
              This itinerary is a conceptual presentation of your journey. Escape Theory reserves the right to make minor adjustments for your comfort and safety.
            </p>
          </footer>
        </div>
      </div>
    </div>
  );
};

