  hotelLink?: string;
  attachmentName?: string;
  attachmentType?: string;
  attachmentData?: string; // base64 string
}

export interface Vehicle {
  id: string;
  type: string;
  brand?: string;
  model?: string;
  capacity: number;
  ratePerDay: number;
  isAC: boolean;
  image?: string;
  fuelType?: string;
  features?: string[];
  providerName?: string;
  providerContact?: string;
  internalNotes?: string;
  rateValidityDate?: string;
  attachmentName?: string;
  attachmentType?: string;
  attachmentData?: string;
}

export interface Activity {
  id: string;
  name: string;
  costPerPax: number;
  description: string;
}

export interface AddOn {
  id: string;
  name: string;
  cost: number;
