  marginPercentage: number;
  addOnIds: string[];
  versions: TripVersion[];
  startLocation: 'Srinagar' | 'Jammu';
  inclusions: string[];
  exclusions: string[];
}

export interface DashboardStats {
  activeLeads: number;
  totalRevenue: number;
  bookedTrips: number;
  conversionRate: number;
}

import React, { useState, useMemo, useEffect } from 'react';
import { useParams, useNavigate, Link } from 'react-router-dom';
import { 
  Plus, 
  Trash2, 
  Save, 
  Sparkles,
  ArrowLeft,
  CalendarDays,
  Hotel as HotelIcon,
  Car as CarIcon,
  History,
  Download,
  Check,
  MapPin,
  Utensils,
  Map as MapIcon,
  PlusCircle,
  Wallet,
  MapPinned,
  IndianRupee,
  Star,
  ListPlus,
  X,
  ChevronRight,
  ShieldCheck,
  XCircle
} from 'lucide-react';
import { MOCK_TRIPS, HOTELS, VEHICLES, ACTIVITIES, ADD_ONS, DEFAULT_INCLUSIONS, DEFAULT_EXCLUSIONS } from '../constants';
import { Trip, ItineraryDay, TripVersion, HotelCategory, Hotel, MealPlan, TripStatus, AddOn, Vehicle } from '../types';
import { generateDayDescription, suggestNextDayTitle } from '../services/geminiService';

const TripBuilder: React.FC = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const [trip, setTrip] = useState<Trip | null>(null);
  const [activeDayIndex, setActiveDayIndex] = useState(0);
  const [isAiGenerating, setIsAiGenerating] = useState(false);
  const [isDownloading, setIsDownloading] = useState(false);

  const [newHighlight, setNewHighlight] = useState('');
  const [newInclusion, setNewInclusion] = useState('');
  const [newExclusion, setNewExclusion] = useState('');

  const masterHotels = useMemo(() => {
    const saved = localStorage.getItem('et_hotels');
    const custom = saved ? JSON.parse(saved) : [];
    const customIds = new Set(custom.map((h: Hotel) => h.id));
    return [...HOTELS.filter(h => !customIds.has(h.id)), ...custom];
  }, []);

  const masterVehicles = useMemo(() => {
    const saved = localStorage.getItem('et_vehicles');
    const custom = saved ? JSON.parse(saved) : [];
    const customIds = new Set(custom.map((v: Vehicle) => v.id));
    return [...VEHICLES.filter(v => !customIds.has(v.id)), ...custom];
  }, []);

  const masterAddOns = useMemo(() => {
    const saved = localStorage.getItem('et_addons');
    const custom = saved ? JSON.parse(saved) : [];
    const customIds = new Set(custom.map((a: AddOn) => a.id));
    return [...ADD_ONS.filter(a => !customIds.has(a.id)), ...custom];
  }, []);

  useEffect(() => {
    const savedTrips = localStorage.getItem('et_trips');
    let foundTrip: Trip | undefined;

    if (savedTrips) {
      const parsed = JSON.parse(savedTrips);
      foundTrip = parsed.find((t: Trip) => t.id === id);
    }

    if (!foundTrip) {
      foundTrip = MOCK_TRIPS.find(t => t.id === id);
    }

    if (foundTrip) {
      setTrip({ 
        ...foundTrip, 
        startLocation: foundTrip.startLocation || 'Srinagar',
        inclusions: foundTrip.inclusions || [...DEFAULT_INCLUSIONS],
        exclusions: foundTrip.exclusions || [...DEFAULT_EXCLUSIONS]
      });
    }
  }, [id]);

  useEffect(() => {
    if (trip) {
      const savedTrips = localStorage.getItem('et_trips');
      let allTrips: Trip[] = savedTrips ? JSON.parse(savedTrips) : [...MOCK_TRIPS];
      const index = allTrips.findIndex(t => t.id === trip.id);
      if (index > -1) allTrips[index] = trip;
      else allTrips.push(trip);
      localStorage.setItem('et_trips', JSON.stringify(allTrips));
    }
  }, [trip]);

  const costs = useMemo(() => {
    if (!trip) return { total: 0, sellingPrice: 0, margin: 0 };
    let hotelCost = 0, vehicleCost = 0, activityCost = 0, addOnsCost = 0, jammuSurcharge = 0;
    const JAMMU_DAILY_SURCHARGE = 1000;

    trip.itinerary.forEach(day => {
      if (day.hotelId) {
        const hotel = masterHotels.find(h => h.id === day.hotelId);
        if (hotel) {
          let nightRate = hotel.ratePerNight;
          if (day.mealPlan === MealPlan.EP && hotel.epRate) nightRate = hotel.epRate;
          else if (day.mealPlan === MealPlan.CP && hotel.cpRate) nightRate = hotel.cpRate;
          else if (day.mealPlan === MealPlan.MAP && hotel.mapRate) nightRate = hotel.mapRate;
          else if (day.mealPlan === MealPlan.AP && hotel.apRate) nightRate = hotel.apRate;
          hotelCost += nightRate;
        }
      }
      if (day.vehicleId) {
        const vehicle = masterVehicles.find(v => v.id === day.vehicleId);
        if (vehicle) {
          vehicleCost += vehicle.ratePerDay;
          if (trip.startLocation === 'Jammu') jammuSurcharge += JAMMU_DAILY_SURCHARGE;
        }
      }
      (day.activityIds || []).forEach(aid => {
        const act = ACTIVITIES.find(a => a.id === aid);
        if (act) activityCost += act.costPerPax * trip.pax;
      });
    });

    trip.addOnIds.forEach(aoId => {
      const ao = masterAddOns.find(a => a.id === aoId);
      if (ao) addOnsCost += ao.isPerPax ? ao.cost * trip.pax : ao.cost;
    });

    const subtotal = hotelCost + vehicleCost + jammuSurcharge + activityCost + addOnsCost;
    const margin = subtotal * (trip.marginPercentage / 100);
    return { total: subtotal, margin, sellingPrice: subtotal + margin };
  }, [trip, masterHotels, masterVehicles, masterAddOns]);

  const selectedHotel = useMemo(() => {
    const hotelId = trip?.itinerary[activeDayIndex]?.hotelId;
    return masterHotels.find(h => h.id === hotelId);
  }, [trip?.itinerary, activeDayIndex, masterHotels]);

  const updateDay = (index: number, updates: Partial<ItineraryDay>) => {
    if (!trip) return;
    const newItinerary = [...trip.itinerary];
    newItinerary[index] = { ...newItinerary[index], ...updates };
    setTrip({ ...trip, itinerary: newItinerary });
  };

  const addHighlight = () => {
    if (!trip || !newHighlight.trim()) return;
    const day = trip.itinerary[activeDayIndex];
    const updatedHighlights = [...(day.highlights || []), newHighlight.trim()];
    updateDay(activeDayIndex, { highlights: updatedHighlights });
    setNewHighlight('');
  };

  const removeHighlight = (idx: number) => {
    if (!trip) return;
    const day = trip.itinerary[activeDayIndex];
    const updatedHighlights = (day.highlights || []).filter((_, i) => i !== idx);
    updateDay(activeDayIndex, { highlights: updatedHighlights });
  };

  const handleAiDescription = async () => {
    if (!trip) return;
    setIsAiGenerating(true);
    const day = trip.itinerary[activeDayIndex];
    const activities = (day.activityIds || []).map(aid => ACTIVITIES.find(a => a.id === aid)?.name || '');
    const description = await generateDayDescription(day.title, activities);
    updateDay(activeDayIndex, { clientNotes: description });
    setIsAiGenerating(false);
  };

  const handleAddDay = async () => {
    if (!trip) return;
    const nextDayNum = trip.itinerary.length + 1;
    const lastDay = trip.itinerary[trip.itinerary.length - 1];

    const newDay: ItineraryDay = {
      id: `d-${Date.now()}`,
      dayNumber: nextDayNum,
      title: `Day ${nextDayNum} Exploration`,
      hotelId: lastDay?.hotelId || '',
      mealPlan: lastDay?.mealPlan || MealPlan.CP,
      vehicleId: lastDay?.vehicleId || '',
      activityIds: [],
      highlights: [],
      clientNotes: '',
      internalNotes: ''
    };

    setTrip({ ...trip, itinerary: [...trip.itinerary, newDay] });
    setActiveDayIndex(trip.itinerary.length);
  };

  const handleDownloadPdf = () => {
    if (!trip) return;
    navigate(`/trips/${trip.id}/print`);
  };

  if (!trip) return <div className="p-20 text-center text-slate-400 font-black">LOADING BUILDER...</div>;

  return (
    <div className="flex flex-col h-full space-y-6 pb-20">
      {/* Header Bar */}
      <div className="bg-white p-6 rounded-3xl border border-slate-200 shadow-sm flex flex-col md:flex-row md:items-center justify-between gap-6">
        <div className="flex items-center gap-5">
          <button onClick={() => navigate('/trips')} className="p-3 hover:bg-slate-50 rounded-2xl transition-all border border-slate-100 shadow-sm">
            <ArrowLeft size={20} className="text-slate-600" />
          </button>
          <div>
            <h1 className="text-2xl font-black text-slate-900 tracking-tight">{trip.tripName}</h1>
            <div className="flex items-center gap-3 mt-1 text-slate-400">
               <span className="text-[10px] font-black uppercase tracking-widest text-blue-600">{trip.client.name}</span>
               <span className="w-1 h-1 bg-slate-200 rounded-full"/>
               <span className="text-[10px] font-bold uppercase tracking-widest">{trip.status}</span>
               <span className="w-1 h-1 bg-slate-200 rounded-full"/>
               <div className="flex items-center gap-1.5 bg-slate-50 px-2 py-0.5 rounded-full border border-slate-100">
                  <MapIcon size={12} className="text-slate-400" />
                  <select 
                    className="bg-transparent text-[10px] font-black uppercase text-slate-600 outline-none cursor-pointer"
                    value={trip.startLocation}
                    onChange={(e) => setTrip({ ...trip, startLocation: e.target.value as 'Srinagar' | 'Jammu' })}
                  >
                    <option value="Srinagar">Srinagar Start</option>
                    <option value="Jammu">Jammu (+₹1k/day)</option>
                  </select>
               </div>
            </div>
          </div>
        </div>

        <div className="flex items-center gap-4">
          <div className="flex items-center gap-6 px-6 py-3 bg-slate-50 rounded-2xl border border-slate-100">
             <div className="text-right">
               <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Client Quote</p>
               <p className="text-xl font-black text-blue-600">₹{costs.sellingPrice.toLocaleString()}</p>
             </div>
             <div className="h-8 w-px bg-slate-200" />
             <div className="text-right">
               <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Net Profit</p>
               <p className="text-xl font-black text-emerald-600">₹{costs.margin.toLocaleString()}</p>
             </div>
          </div>
          <button 
            onClick={handleDownloadPdf}
            className="bg-slate-900 text-white px-8 py-4 rounded-2xl font-black uppercase tracking-widest text-xs flex items-center gap-3 shadow-xl hover:bg-slate-800 transition-all"
          >
            <Download size={18} /> PDF / PRINT
          </button>
        </div>
      </div>

      <div className="grid grid-cols-12 gap-8 flex-1 overflow-hidden">
        {/* Left: Day List */}
        <div className="col-span-12 lg:col-span-3 space-y-4 overflow-y-auto pr-2">
           <div className="bg-white border border-slate-200 rounded-[32px] p-6 shadow-sm flex flex-col h-full">
              <div className="flex items-center justify-between mb-6">
                <h3 className="text-xs font-black uppercase tracking-widest text-slate-400 flex items-center gap-2">
                   <CalendarDays size={16} className="text-blue-600" /> Itinerary Timeline
                </h3>
              </div>
              <div className="space-y-3 flex-1">
                {trip.itinerary.map((day, idx) => (
                  <button 
                    key={day.id} 
                    onClick={() => setActiveDayIndex(idx)}
                    className={`w-full text-left p-4 rounded-2xl border transition-all flex flex-col gap-1 ${
                      activeDayIndex === idx ? 'bg-blue-600 border-blue-600 text-white shadow-lg shadow-blue-100' : 'bg-white border-slate-100 hover:border-slate-300 text-slate-700'
                    }`}
                  >
                    <span className={`text-[9px] font-black uppercase tracking-widest ${activeDayIndex === idx ? 'text-blue-100' : 'text-blue-600'}`}>Day {day.dayNumber}</span>
                    <h4 className="font-bold text-sm truncate">{day.title}</h4>
                  </button>
                ))}
                <button 
                  onClick={handleAddDay}
                  className="w-full py-5 border-2 border-dashed border-slate-200 rounded-2xl text-slate-400 font-black uppercase tracking-widest text-[10px] flex items-center justify-center gap-2 hover:border-blue-300 hover:text-blue-600 hover:bg-blue-50/30 transition-all"
                >
                  <Plus size={16} /> Add Another Day
                </button>
              </div>
           </div>
        </div>

        {/* Center: Content Editor */}
        <div className="col-span-12 lg:col-span-6 space-y-8 overflow-y-auto pr-2">
           {trip.itinerary[activeDayIndex] && (
             <div className="bg-white border border-slate-200 rounded-[40px] p-10 shadow-sm space-y-10 animate-in fade-in slide-in-from-bottom-4 duration-300">
                <div className="space-y-1">
                   <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">Heading Title</label>
                   <input 
                     type="text" 
                     value={trip.itinerary[activeDayIndex].title}
                     onChange={(e) => updateDay(activeDayIndex, { title: e.target.value })}
                     className="text-4xl font-black text-slate-900 border-none p-0 focus:ring-0 w-full placeholder:text-slate-100"
                     placeholder="Name this day..."
                   />
                </div>

                <div className="grid grid-cols-2 gap-8">
                   <div className="space-y-4">
                      <label className="text-xs font-black uppercase text-slate-700 flex items-center gap-2 tracking-widest">
                         <HotelIcon size={16} className="text-blue-500" /> Property
                      </label>
                      <select 
                        value={trip.itinerary[activeDayIndex].hotelId}
                        onChange={(e) => updateDay(activeDayIndex, { hotelId: e.target.value })}
                        className="w-full p-4 bg-slate-50 border border-slate-200 rounded-2xl font-black text-xs text-slate-900 shadow-sm outline-none"
                      >
                         <option value="">Select Accommodation...</option>
                         {masterHotels.map(h => <option key={h.id} value={h.id}>{h.name} ({h.location})</option>)}
                      </select>
                   </div>
                   <div className="space-y-4">
                      <label className="text-xs font-black uppercase text-slate-700 flex items-center gap-2 tracking-widest">
                         <CarIcon size={16} className="text-blue-500" /> Transport
                      </label>
                      <select 
                        value={trip.itinerary[activeDayIndex].vehicleId}
                        onChange={(e) => updateDay(activeDayIndex, { vehicleId: e.target.value })}
                        className="w-full p-4 bg-slate-50 border border-slate-200 rounded-2xl font-black text-xs text-slate-900 shadow-sm outline-none"
                      >
                         <option value="">Select Fleet Item...</option>
                         {masterVehicles.map(v => <option key={v.id} value={v.id}>{v.brand} {v.type}</option>)}
                      </select>
                   </div>
                </div>

                {/* Daily Highlights Editor */}
                <div className="space-y-6">
                   <div className="flex items-center justify-between border-b border-slate-50 pb-3">
                      <h4 className="text-[10px] font-black uppercase tracking-widest text-slate-400 flex items-center gap-2">
                         <Star size={14} className="text-amber-500" /> Curated Day Highlights
                      </h4>
                   </div>
                   <div className="space-y-3">
                      {(trip.itinerary[activeDayIndex].highlights || []).map((h, i) => (
                        <div key={i} className="flex items-center gap-3 group">
                           <div className="flex-1 bg-blue-50 border border-blue-100 text-blue-900 px-5 py-3 rounded-2xl text-xs font-bold">
                              {h}
                           </div>
                           <button onClick={() => removeHighlight(i)} className="p-3 text-slate-300 hover:text-rose-500 transition-colors">
                              <X size={16}/>
                           </button>
                        </div>
                      ))}
                      <div className="flex gap-2">
                        <input 
                          type="text" 
                          placeholder="e.g. Sunset Shikara Ride with Saffron Tea"
                          value={newHighlight}
                          onChange={(e) => setNewHighlight(e.target.value)}
                          onKeyDown={(e) => e.key === 'Enter' && addHighlight()}
                          className="flex-1 p-4 bg-white border-2 border-dashed border-slate-200 rounded-2xl text-xs font-bold outline-none focus:border-blue-500 transition-all"
                        />
                        <button onClick={addHighlight} className="bg-slate-900 text-white p-4 rounded-2xl">
                          <Plus size={20} />
                        </button>
                      </div>
                   </div>
                </div>

                <div className="space-y-6">
                   <div className="flex items-center justify-between border-b border-slate-50 pb-3">
                      <h4 className="text-[10px] font-black uppercase tracking-widest text-slate-400">Detailed Narrative</h4>
                      <button 
                        onClick={handleAiDescription}
                        disabled={isAiGenerating}
                        className="flex items-center gap-2 text-[10px] font-black uppercase tracking-widest text-blue-600 hover:text-blue-700 disabled:opacity-50"
                      >
                        <Sparkles size={14} /> AI Enchant Narrative
