import React, { useEffect, useState, useMemo, useRef } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { 
  Calendar, 
  Users, 
  CheckCircle2, 
  XCircle, 
  Printer, 
  ArrowLeft, 
  Coffee, 
  Star, 
  Download, 
  Loader2, 
  Sparkles, 
  Hotel as HotelIcon, 
  Car as CarIcon, 
  MapPinned, 
  ChevronRight,
  Sun,
  MapPin
} from 'lucide-react';
import { MOCK_TRIPS, BRAND_CONFIG, HOTELS, VEHICLES, ACTIVITIES, DEFAULT_INCLUSIONS, DEFAULT_EXCLUSIONS, ADD_ONS } from '../constants';
import { Trip, Hotel, AddOn, Vehicle } from '../types';

const ClientItinerary: React.FC = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const [trip, setTrip] = useState<Trip | null>(null);
  const [isGenerating, setIsGenerating] = useState(false);
  const printableRef = useRef<HTMLDivElement>(null);

  const masterHotels = useMemo(() => {
    const saved = localStorage.getItem('et_hotels');
    const custom = saved ? JSON.parse(saved) : [];
    const customIds = new Set(custom.map((h: Hotel) => h.id));
    return [...HOTELS.filter(h => !customIds.has(h.id)), ...custom];
  }, []);

  const masterVehicles = useMemo(() => {
    const saved = localStorage.getItem('et_vehicles');
    const custom = saved ? JSON.parse(saved) : [];
    const customIds = new Set(custom.map((v: Vehicle) => v.id));
    return [...VEHICLES.filter(v => !customIds.has(v.id)), ...custom];
  }, []);

  const masterAddOns = useMemo(() => {
    const saved = localStorage.getItem('et_addons');
    const custom = saved ? JSON.parse(saved) : [];
    const customIds = new Set(custom.map((a: AddOn) => a.id));
    return [...ADD_ONS.filter(a => !customIds.has(a.id)), ...custom];
  }, []);

  useEffect(() => {
    const savedTrips = localStorage.getItem('et_trips');
    let foundTrip: Trip | undefined;

    if (savedTrips) {
      const parsed = JSON.parse(savedTrips);
      foundTrip = parsed.find((t: Trip) => t.id === id);
    }

    if (!foundTrip) {
      foundTrip = MOCK_TRIPS.find(t => t.id === id);
    }

    if (foundTrip) {
      setTrip({
        ...foundTrip,
        inclusions: foundTrip.inclusions || [...DEFAULT_INCLUSIONS],
        exclusions: foundTrip.exclusions || [...DEFAULT_EXCLUSIONS],
        addOnIds: foundTrip.addOnIds || []
      });
    }
  }, [id]);

  const selectedAddOns = useMemo(() => {
    if (!trip) return [];
    return masterAddOns.filter(ao => (trip.addOnIds || []).includes(ao.id));
  }, [trip, masterAddOns]);

  const handleDownloadPdf = async () => {
    if (!trip || !printableRef.current || isGenerating) return;

    setIsGenerating(true);
    try {
      const element = printableRef.current;
      const h2p = (window as any).html2pdf;

      const opt = {
        margin: 0,
        filename: `${trip.client.name}_Escape_Theory_Proposal.pdf`,
        image: { type: 'jpeg', quality: 0.98 },
        html2canvas: { 
          scale: 2, 
          useCORS: true, 
          letterRendering: true,
          scrollX: 0,
          scrollY: 0
        },
        jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' },
        pagebreak: { mode: ['avoid-all', 'css', 'legacy'] }
      };

      const images = element.getElementsByTagName('img');
      const promises = Array.from(images).map(img => {
        if (img.complete) return Promise.resolve();
        return new Promise((resolve) => {
          img.onload = resolve;
          img.onerror = resolve;
        });
      });

      await Promise.all(promises);
      await h2p().from(element).set(opt).save();
    } catch (err) {
      console.error("PDF Generation Error:", err);
      alert("Failed to generate PDF. Use the Print option.");
    } finally {
      setIsGenerating(false);
    }
  };

  if (!trip) return (
    <div className="p-20 text-center font-black text-slate-300">
      <div className="animate-spin w-12 h-12 border-4 border-blue-600 border-t-transparent rounded-full mx-auto mb-6"></div>
      LOADING PROPOSAL...
    </div>
  );

  return (
    <div className="bg-slate-100 min-h-screen text-slate-900 print:bg-white overflow-x-hidden pb-20">
      {/* Tool Bar */}
      <div className="no-print sticky top-0 bg-white/90 backdrop-blur-xl border-b border-slate-200 z-[100] p-6 flex justify-between items-center px-10 shadow-lg">
        <button onClick={() => navigate(`/trips/${id}`)} className="text-slate-500 font-black uppercase text-[10px] tracking-widest hover:text-slate-800 flex items-center gap-3 transition-all px-4 py-2 hover:bg-slate-50 rounded-xl">
          <ArrowLeft size={16} /> Back to Builder
        </button>
        <div className="flex gap-4">
          <button onClick={() => window.print()} className="bg-white border border-slate-200 text-slate-700 px-6 py-3 rounded-2xl font-black uppercase tracking-widest text-[11px] flex items-center gap-3 hover:bg-slate-50 transition-all">
            <Printer size={18} /> Print View
          </button>
          <button onClick={handleDownloadPdf} disabled={isGenerating} className="bg-slate-900 text-white px-10 py-3 rounded-2xl font-black uppercase tracking-widest text-[11px] flex items-center gap-3 shadow-2xl transition-all disabled:opacity-70 active:scale-95">
            {isGenerating ? <Loader2 size={18} className="animate-spin" /> : <Download size={18} />}
            {isGenerating ? 'GENERATING...' : 'DOWNLOAD PROPOSAL'}
          </button>
        </div>
      </div>

      {/* Printable Area */}
      <div className="max-w-[210mm] mx-auto bg-white shadow-2xl my-10 print:my-0 print:shadow-none font-inter" ref={printableRef}>
        <div className="p-[20mm] print:p-12">

          {/* Cover Header */}
          <header className="flex justify-between items-start border-b-4 border-slate-900 pb-12 mb-16">
            <div className="flex items-center gap-6">
              <img src={BRAND_CONFIG.logo} alt="Agency Logo" className="w-24 h-24 object-contain" />
              <div>
                <h1 className="text-5xl font-black text-slate-900 tracking-tighter uppercase leading-none">{BRAND_CONFIG.name}</h1>
                <p className="text-blue-600 font-black text-[12px] uppercase tracking-[0.4em] mt-3">{BRAND_CONFIG.tagline}</p>
              </div>
            </div>
            <div className="text-right">
               <p className="text-[10px] font-black uppercase tracking-widest text-slate-400 mb-2">Exclusive Itinerary For</p>
               <h3 className="text-2xl font-black text-slate-900 tracking-tight leading-none">{trip.client.name}</h3>
            </div>
          </header>

          {/* Hero Section */}
          <section className="bg-slate-900 rounded-[64px] p-20 mb-24 relative overflow-hidden text-white shadow-2xl">
            <div className="absolute top-0 right-0 w-1/2 h-full bg-blue-600/10 skew-x-12 transform translate-x-20" />
            <div className="relative z-10">
              <span className="text-blue-400 font-black uppercase tracking-[0.5em] text-[10px] mb-6 block">Premium Travel Experience</span>
