              <div className="flex flex-wrap gap-12 pt-8 border-t border-white/10">
                 <div className="space-y-1">
                    <p className="text-slate-400 text-[9px] font-black uppercase tracking-widest flex items-center gap-2"><Calendar size={12}/> Dates</p>
                    <p className="text-lg font-black">{new Date(trip.startDate).toLocaleDateString()} — {new Date(trip.endDate).toLocaleDateString()}</p>
