          const loc = hotel.location === 'Srinagar' && hotel.category === 'Houseboat' ? 'Houseboat' : hotel.location;
          counts[loc] = (counts[loc] || 0) + 1;
        }
      }
    });
    return Object.entries(counts).map(([loc, nights]) => `${loc} | ${nights.toString().padStart(2, '0')} Nights`);
