const TripBuilder: React.FC = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const [trip, setTrip] = useState<Trip | null>(null);
  const [activeDayIndex, setActiveDayIndex] = useState(0);
  const [isAiGenerating, setIsAiGenerating] = useState(false);

  const [newHighlight, setNewHighlight] = useState('');

  const masterHotels = useMemo(() => {
    const saved = localStorage.getItem('et_hotels');
    const custom = saved ? JSON.parse(saved) : [];
    return [...HOTELS, ...custom];
  }, []);

  const masterVehicles = useMemo(() => {
    const saved = localStorage.getItem('et_vehicles');
    const custom = saved ? JSON.parse(saved) : [];
    return [...VEHICLES, ...custom];
  }, []);

  const masterAddOns = useMemo(() => {
    const saved = localStorage.getItem('et_addons');
    const custom = saved ? JSON.parse(saved) : [];
    return [...ADD_ONS, ...custom];
  }, []);

  useEffect(() => {
    const savedTrips = localStorage.getItem('et_trips');
    let foundTrip: Trip | undefined;
    if (savedTrips) {
      const parsed = JSON.parse(savedTrips);
      foundTrip = parsed.find((t: Trip) => t.id === id);
    }
    if (!foundTrip) {
      foundTrip = MOCK_TRIPS.find(t => t.id === id);
    }
    if (foundTrip) {
      setTrip(foundTrip);
    }
  }, [id]);

  const costs = useMemo(() => {
    if (!trip) return { total: 0, sellingPrice: 0, margin: 0 };
    let hotelCost = 0, vehicleCost = 0, activityCost = 0, addOnsCost = 0;
    trip.itinerary.forEach(day => {
      if (day.hotelId) {
        const hotel = masterHotels.find(h => h.id === day.hotelId);
        if (hotel) hotelCost += hotel.ratePerNight;
      }
      if (day.vehicleId) {
        const vehicle = masterVehicles.find(v => v.id === day.vehicleId);
        if (vehicle) vehicleCost += vehicle.ratePerDay;
      }
      (day.activityIds || []).forEach(aid => {
        const act = ACTIVITIES.find(a => a.id === aid);
        if (act) activityCost += act.costPerPax * trip.pax;
      });
    });
    trip.addOnIds.forEach(aoId => {
      const ao = masterAddOns.find(a => a.id === aoId);
      if (ao) addOnsCost += ao.isPerPax ? ao.cost * trip.pax : ao.cost;
    });
    const subtotal = hotelCost + vehicleCost + activityCost + addOnsCost;
    const margin = subtotal * (trip.marginPercentage / 100);
    return { total: subtotal, margin, sellingPrice: subtotal + margin };
  }, [trip, masterHotels, masterVehicles, masterAddOns]);

  const updateDay = (index: number, updates: Partial<ItineraryDay>) => {
    if (!trip) return;
    const newItinerary = [...trip.itinerary];
    newItinerary[index] = { ...newItinerary[index], ...updates };
    setTrip({ ...trip, itinerary: newItinerary });
  };

  const addHighlight = () => {
    if (!trip || !newHighlight.trim()) return;
    const day = trip.itinerary[activeDayIndex];
    const updatedHighlights = [...(day.highlights || []), newHighlight.trim()];
    updateDay(activeDayIndex, { highlights: updatedHighlights });
    setNewHighlight('');
  };

  const handleAiDescription = async () => {
    if (!trip) return;
    setIsAiGenerating(true);
    const day = trip.itinerary[activeDayIndex];
    const activities = (day.activityIds || []).map(aid => ACTIVITIES.find(a => a.id === aid)?.name || '');
    const description = await generateDayDescription(day.title, activities);
    updateDay(activeDayIndex, { clientNotes: description });
    setIsAiGenerating(false);
  };

  if (!trip) return <div className="p-20 text-center text-slate-400 font-black">LOADING BUILDER...</div>;

  return (
    <div className="flex flex-col h-full space-y-6 pb-20">
      <div className="bg-white p-6 rounded-3xl border border-slate-200 shadow-sm flex flex-col md:flex-row md:items-center justify-between gap-6">
        <div className="flex items-center gap-5">
          <button onClick={() => navigate('/trips')} className="p-3 hover:bg-slate-50 rounded-2xl transition-all border border-slate-100">
            <ArrowLeft size={20} className="text-slate-600" />
          </button>
          <div>
            <h1 className="text-2xl font-black text-slate-900 tracking-tight">{trip.tripName}</h1>
            <p className="text-[10px] font-black uppercase tracking-widest text-blue-600">{trip.client.name} • {trip.status}</p>
          </div>
        </div>

        <div className="flex items-center gap-4">
          <button 
            onClick={() => navigate(`/trips/${trip.id}/print`)}
            className="bg-blue-600 text-white px-8 py-4 rounded-2xl font-black uppercase tracking-widest text-xs flex items-center gap-3 shadow-xl hover:bg-blue-700 transition-all"
          >
            <Download size={18} /> GENERATE PROPOSAL
          </button>
        </div>
      </div>

      <div className="grid grid-cols-12 gap-8 flex-1 overflow-hidden">
        <div className="col-span-12 lg:col-span-3 space-y-4 overflow-y-auto">
           <div className="bg-white border border-slate-200 rounded-[32px] p-6 shadow-sm">
              <h3 className="text-xs font-black uppercase tracking-widest text-slate-400 mb-6 flex items-center gap-2">
                 <CalendarDays size={16} className="text-blue-600" /> Itinerary Timeline
              </h3>
              <div className="space-y-3">
                {trip.itinerary.map((day, idx) => (
                  <button 
                    key={day.id} 
                    onClick={() => setActiveDayIndex(idx)}
                    className={`w-full text-left p-4 rounded-2xl border transition-all ${
                      activeDayIndex === idx ? 'bg-blue-600 border-blue-600 text-white' : 'bg-white border-slate-100 hover:border-slate-300 text-slate-700'
                    }`}
                  >
                    <span className={`text-[9px] font-black uppercase tracking-widest ${activeDayIndex === idx ? 'text-blue-100' : 'text-blue-600'}`}>Day {day.dayNumber}</span>
                    <h4 className="font-bold text-sm truncate">{day.title}</h4>
                  </button>
                ))}
              </div>
           </div>
        </div>

        <div className="col-span-12 lg:col-span-6 space-y-8 overflow-y-auto">
           {trip.itinerary[activeDayIndex] && (
             <div className="bg-white border border-slate-200 rounded-[40px] p-10 shadow-sm space-y-10">
                <div className="space-y-1">
                   <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">Heading Title</label>
                   <input 
                     type="text" 
                     value={trip.itinerary[activeDayIndex].title}
                     onChange={(e) => updateDay(activeDayIndex, { title: e.target.value })}
                     className="text-4xl font-black text-slate-900 border-2 border-slate-50 p-3 rounded-2xl focus:ring-4 focus:ring-blue-50 focus:border-blue-200 w-full placeholder:text-slate-200"
                     placeholder="Name this day..."
                   />
                </div>

                <div className="grid grid-cols-2 gap-8">
                   <div className="space-y-4">
                      <label className="text-xs font-black uppercase text-slate-700 flex items-center gap-2 tracking-widest">
                         <HotelIcon size={16} className="text-blue-500" /> Hotel
                      </label>
                      <select 
                        value={trip.itinerary[activeDayIndex].hotelId}
                        onChange={(e) => updateDay(activeDayIndex, { hotelId: e.target.value })}
                        className="w-full p-4 bg-slate-50 border border-slate-100 rounded-2xl font-bold text-sm text-slate-900 shadow-inner outline-none"
                      >
                         <option value="">Select Accommodation...</option>
                         {masterHotels.map(h => <option key={h.id} value={h.id}>{h.name} ({h.location})</option>)}
                      </select>
                   </div>
                   <div className="space-y-4">
                      <label className="text-xs font-black uppercase text-slate-700 flex items-center gap-2 tracking-widest">
                         <CarIcon size={16} className="text-blue-500" /> Vehicle
                      </label>
                      <select 
                        value={trip.itinerary[activeDayIndex].vehicleId}
                        onChange={(e) => updateDay(activeDayIndex, { vehicleId: e.target.value })}
                        className="w-full p-4 bg-slate-50 border border-slate-100 rounded-2xl font-bold text-sm text-slate-900 shadow-inner outline-none"
                      >
                         <option value="">Select Vehicle...</option>
                         {masterVehicles.map(v => <option key={v.id} value={v.id}>{v.type}</option>)}
                      </select>
                   </div>
                </div>

                <div className="space-y-6">
                   <div className="flex items-center justify-between border-b border-slate-50 pb-3">
                      <h4 className="text-[10px] font-black uppercase tracking-widest text-slate-400 flex items-center gap-2">
                         <Star size={14} className="text-amber-500" /> Day Highlights
                      </h4>
                   </div>
                   <div className="space-y-3">
                      {(trip.itinerary[activeDayIndex].highlights || []).map((h, i) => (
                        <div key={i} className="flex items-center justify-between bg-blue-50 px-5 py-3 rounded-2xl text-xs font-bold text-blue-900">
                           {h}
                           <button onClick={() => {
                             const updated = trip.itinerary[activeDayIndex].highlights?.filter((_, idx) => idx !== i);
                             updateDay(activeDayIndex, { highlights: updated });
                           }} className="text-rose-400 hover:text-rose-600"><X size={14}/></button>
                        </div>
                      ))}
                      <div className="flex gap-2">
                        <input 
                          type="text" 
                          placeholder="Add a bullet point highlight..."
                          value={newHighlight}
                          onChange={(e) => setNewHighlight(e.target.value)}
                          onKeyDown={(e) => e.key === 'Enter' && addHighlight()}
                          className="flex-1 p-4 bg-white border border-slate-200 rounded-2xl text-xs font-bold outline-none"
                        />
                        <button onClick={addHighlight} className="bg-slate-900 text-white p-4 rounded-2xl"><Plus size={20} /></button>
                      </div>
                   </div>
                </div>

                <div className="space-y-6">
                   <div className="flex items-center justify-between border-b border-slate-50 pb-3">
                      <h4 className="text-[10px] font-black uppercase tracking-widest text-slate-400">Narrative</h4>
                      <button 
                        onClick={handleAiDescription}
                        disabled={isAiGenerating}
                        className="flex items-center gap-2 text-[10px] font-black uppercase tracking-widest text-blue-600"
                      >
                        <Sparkles size={14} /> AI ENCHANT
                      </button>
                   </div>
                   <textarea 
                     rows={6}
                     value={trip.itinerary[activeDayIndex].clientNotes}
                     onChange={(e) => updateDay(activeDayIndex, { clientNotes: e.target.value })}
                     className="w-full p-6 bg-slate-50 border border-slate-100 rounded-[32px] text-base leading-relaxed text-slate-800 outline-none"
                     placeholder="Write about the guest experience..."
                   />
                </div>
             </div>
           )}
        </div>

        <div className="col-span-12 lg:col-span-3 space-y-6">
           <div className="bg-blue-600 rounded-[32px] p-8 text-white space-y-8 shadow-2xl">
              <h3 className="text-[10px] font-black uppercase tracking-[0.2em] text-blue-200">Financial Summary</h3>
              <div className="space-y-4">
                 <div className="flex justify-between items-center text-sm">
                    <span className="font-bold opacity-70 uppercase tracking-widest text-[9px]">Margin %</span>
                    <input 
                      type="number" 
                      value={trip.marginPercentage}
                      onChange={(e) => setTrip({...trip, marginPercentage: parseInt(e.target.value)})}
                      className="bg-blue-700 border-none rounded-lg px-2 py-1 w-16 text-right font-black"
                    />
                 </div>
                 <div className="pt-4 border-t border-blue-500">
                    <p className="text-[9px] font-black uppercase tracking-widest text-blue-200 mb-1">Total Quote</p>
                    <p className="text-3xl font-black">₹{costs.sellingPrice.toLocaleString()}</p>
                 </div>
              </div>
           </div>
        </div>
      </div>
    </div>
  );
};

