        {/* Right: Master Data & Summary */}
        <div className="col-span-12 lg:col-span-3 space-y-6 overflow-y-auto pr-2">
           <div className="bg-slate-900 rounded-[32px] p-8 text-white space-y-8 shadow-2xl">
