                       />
                       <span className="font-black text-xl">{trip.marginPercentage}%</span>
                    </div>
                 </div>
                 <div className="pt-6 border-t border-slate-800 space-y-4">
                    <div className="flex justify-between items-center">
                       <span className="text-xs font-bold text-slate-400 uppercase">Operational Cost</span>
                       <span className="text-sm font-black">₹{costs.total.toLocaleString()}</span>
                    </div>
                    <div className="flex justify-between items-center text-blue-400">
                       <span className="text-xs font-black uppercase">Final Client Quote</span>
                       <span className="text-xl font-black">₹{costs.sellingPrice.toLocaleString()}</span>
                    </div>
                 </div>
              </div>
           </div>

           <div className="bg-white border border-slate-200 rounded-[32px] p-8 shadow-sm space-y-8">
              <div className="flex items-center justify-between">
                <h3 className="text-xs font-black uppercase tracking-widest text-slate-800 flex items-center gap-2">
                   <PlusCircle size={16} className="text-blue-600" /> Premium Add-ons
                </h4>
              </div>
              <div className="space-y-3">
                 {masterAddOns.map(ao => {
                   const isSelected = (trip.addOnIds || []).includes(ao.id);
                   return (
                     <button 
                       key={ao.id}
                       onClick={() => {
                         const updated = isSelected ? trip.addOnIds.filter(id => id !== ao.id) : [...trip.addOnIds, ao.id];
                         setTrip({...trip, addOnIds: updated});
                       }}
                       className={`w-full text-left p-4 rounded-2xl border transition-all flex flex-col gap-1 ${
                         isSelected ? 'bg-blue-50 border-blue-200' : 'bg-white border-slate-50 hover:bg-slate-50'
                       }`}
                     >
                        <div className="flex items-center justify-between mb-1">
                           <span className="text-xs font-black text-slate-900">{ao.name}</span>
                           {isSelected && <Check size={14} className="text-blue-600" />}
                        </div>
                        <div className="flex justify-between items-center">
                           <span className="text-[9px] font-bold text-slate-400 uppercase tracking-widest">{ao.isPerPax ? 'Per Person' : 'Fixed Unit'}</span>
                           <span className="text-[10px] font-black text-slate-900">₹{ao.cost.toLocaleString()}</span>
                        </div>
                     </button>
                   );
                 })}
              </div>
           </div>
        </div>
      </div>
    </div>
  );
};

