import { 
  Plus, 
  Trash2, 
  Save, 
  Sparkles,
  ArrowLeft,
  CalendarDays,
  Hotel as HotelIcon,
  Car as CarIcon,
  Clock,
  Settings,
  Briefcase,
  Layers,
  Filter,
  MapPinned,
  ShieldCheck,
  XCircle
} from 'lucide-react';
