                <div className="space-y-6">
                   <div className="flex items-center justify-between border-b border-slate-100 pb-3">
                      <h4 className="text-[10px] font-black uppercase tracking-widest text-slate-400">Guest Experience Story</h4>
                      <button 
                        onClick={handleAiDescription}
                        disabled={isAiGenerating}
                        className="flex items-center gap-2 text-[10px] font-black uppercase tracking-widest text-blue-600 hover:text-blue-700 disabled:opacity-50 transition-all"
                      >
                        <Sparkles size={14} /> AI Enchant Narrative
                      </button>
                   </div>
                   <textarea 
                     rows={10}
                     value={trip.itinerary[activeDayIndex].clientNotes}
                     onChange={(e) => updateDay(activeDayIndex, { clientNotes: e.target.value })}
                     className="w-full p-8 bg-slate-50 border border-slate-200 rounded-[32px] text-base leading-relaxed text-slate-800 outline-none focus:ring-4 focus:ring-blue-50 focus:bg-white transition-all shadow-inner"
                     placeholder="Describe the magical experience awaiting the guests..."
                   />
                </div>
             </div>
           )}
        </div>

        {/* Right: Master Data & Global Trip Config */}
        <div className="col-span-12 lg:col-span-3 space-y-6 overflow-y-auto pr-2 pb-20">
           {/* Financials */}
           <div className="bg-slate-900 rounded-[32px] p-8 text-white space-y-8 shadow-2xl">
              <h3 className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-500">Global Financial Summary</h3>
              <div className="space-y-6">
                 <div>
                    <p className="text-[9px] font-bold text-slate-400 uppercase mb-1">Standard Profit Margin</p>
                    <div className="flex items-center gap-4">
                       <input 
                         type="range" 
                         min="0" max="60" 
                         value={trip.marginPercentage}
                         onChange={(e) => setTrip({...trip, marginPercentage: parseInt(e.target.value)})}
                         className="flex-1 h-1.5 bg-slate-800 rounded-full appearance-none cursor-pointer accent-blue-500"
                       />
                       <span className="font-black text-xl">{trip.marginPercentage}%</span>
                    </div>
                 </div>
                 <div className="pt-6 border-t border-slate-800 space-y-4">
                    <div className="flex justify-between items-center text-blue-400 pt-2 border-t border-slate-800/50">
                       <span className="text-[10px] font-black uppercase tracking-widest">Final Client Proposal</span>
                       <span className="text-2xl font-black">₹{costs.sellingPrice.toLocaleString()}</span>
                    </div>
                 </div>
              </div>
           </div>

           {/* Inclusions Management */}
           <div className="bg-white border border-slate-200 rounded-[32px] p-8 shadow-sm space-y-6">
              <h3 className="text-xs font-black uppercase tracking-widest text-emerald-600 flex items-center gap-2">
                 <ShieldCheck size={16} /> Trip Inclusions
              </h3>
              <div className="space-y-2">
                 {(trip.inclusions || []).map((inc, i) => (
                    <div key={i} className="flex items-center gap-2 group">
                       <div className="flex-1 text-[10px] font-bold text-slate-600 bg-emerald-50 p-3 rounded-xl line-clamp-2">
                          {inc}
                       </div>
                       <button onClick={() => removeInclusion(i)} className="text-slate-300 hover:text-rose-500 transition-colors">
                          <Trash2 size={14}/>
                       </button>
                    </div>
                 ))}
                 <div className="flex gap-2 pt-2">
                    <input 
                       type="text" 
                       placeholder="Add Inclusion..."
                       value={newInclusion}
                       onChange={(e) => setNewInclusion(e.target.value)}
                       onKeyDown={(e) => e.key === 'Enter' && addInclusion()}
                       className="flex-1 p-3 bg-slate-50 border border-slate-100 rounded-xl text-[10px] font-bold outline-none focus:border-emerald-200"
                    />
                    <button onClick={addInclusion} className="bg-emerald-600 text-white p-3 rounded-xl">
                       <Plus size={14}/>
                    </button>
                 </div>
              </div>
           </div>

           {/* Exclusions Management */}
           <div className="bg-white border border-slate-200 rounded-[32px] p-8 shadow-sm space-y-6">
              <h3 className="text-xs font-black uppercase tracking-widest text-rose-500 flex items-center gap-2">
                 <XCircle size={16} /> Trip Exclusions
              </h3>
              <div className="space-y-2">
                 {(trip.exclusions || []).map((exc, i) => (
                    <div key={i} className="flex items-center gap-2 group">
                       <div className="flex-1 text-[10px] font-bold text-slate-600 bg-rose-50 p-3 rounded-xl line-clamp-2">
                          {exc}
                       </div>
                       <button onClick={() => removeExclusion(i)} className="text-slate-300 hover:text-rose-500 transition-colors">
                          <Trash2 size={14}/>
                       </button>
                    </div>
                 ))}
                 <div className="flex gap-2 pt-2">
                    <input 
                       type="text" 
                       placeholder="Add Exclusion..."
                       value={newExclusion}
                       onChange={(e) => setNewExclusion(e.target.value)}
                       onKeyDown={(e) => e.key === 'Enter' && addExclusion()}
                       className="flex-1 p-3 bg-slate-50 border border-slate-100 rounded-xl text-[10px] font-bold outline-none focus:border-rose-200"
                    />
                    <button onClick={addExclusion} className="bg-rose-500 text-white p-3 rounded-xl">
                       <Plus size={14}/>
                    </button>
                 </div>
              </div>
           </div>

           {/* Premium Add-ons */}
           <div className="bg-white border border-slate-200 rounded-[32px] p-8 shadow-sm space-y-8">
              <div className="flex items-center justify-between">
                <h3 className="text-xs font-black uppercase tracking-widest text-slate-800 flex items-center gap-2">
                   <PlusCircle size={16} className="text-blue-600" /> Premium Experiences
                </h3>
              </div>
              <div className="space-y-3">
                 {masterAddOns.map(ao => {
                   const isSelected = (trip.addOnIds || []).includes(ao.id);
                   return (
                     <button 
                       key={ao.id}
                       onClick={() => {
                         const updated = isSelected ? trip.addOnIds.filter(id => id !== ao.id) : [...trip.addOnIds, ao.id];
                         setTrip({...trip, addOnIds: updated});
                       }}
                       className={`w-full text-left p-5 rounded-3xl border transition-all flex flex-col gap-1 ${
                         isSelected ? 'bg-blue-600 border-blue-600 text-white shadow-lg' : 'bg-white border-slate-100 hover:bg-slate-50'
                       }`}
                     >
                        <div className="flex items-center justify-between mb-1">
                           <span className={`text-xs font-black ${isSelected ? 'text-white' : 'text-slate-900'}`}>{ao.name}</span>
                           {isSelected && <Check size={14} className="text-white" />}
                        </div>
                        <div className="flex justify-between items-center">
                           <span className={`text-[9px] font-bold uppercase tracking-widest ${isSelected ? 'text-blue-100' : 'text-slate-400'}`}>{ao.isPerPax ? 'Per Guest' : 'Flat Fee'}</span>
                           <span className={`text-sm font-black ${isSelected ? 'text-white' : 'text-blue-600'}`}>₹{ao.cost.toLocaleString()}</span>
                        </div>
                     </button>
                   );
                 })}
              </div>
           </div>
        </div>
      </div>
    </div>
  );
};

export default TripBuilder;

export enum UserRole {
  ADMIN = 'ADMIN',
  SALES = 'SALES',
  OPERATIONS = 'OPERATIONS'
}

export enum TripStatus {
  LEAD = 'Lead',
  QUOTED = 'Quoted',
  BOOKED = 'Booked',
  COMPLETED = 'Completed',
  CANCELLED = 'Cancelled'
}

export enum TripType {
  HONEYMOON = 'Honeymoon',
  FAMILY = 'Family',
  GROUP = 'Group',
  CORPORATE = 'Corporate'
}

export enum HotelCategory {
  BUDGET = 'Budget',
  DELUXE = 'Deluxe',
  LUXURY = 'Luxury',
  HOUSEBOAT = 'Houseboat'
}

export enum MealPlan {
  EP = 'EP (Room Only)',
  CP = 'CP (Room + Breakfast)',
  MAP = 'MAP (Room + BF + Dinner)',
  AP = 'AP (Room + All Meals)'
}

export interface Hotel {
  id: string;
  name: string;
  location: string;
  category: HotelCategory;
  ratePerNight: number;
  contact: string;
  gallery?: string[]; // Array of base64 strings or URLs
  // Rate Validity
  rateValidityDate?: string;
  // Optional detailed rates
  extraBedRate?: number;
  epRate?: number;
  cpRate?: number;
  mapRate?: number;
  apRate?: number;
