                    <th className="px-6 py-5 text-blue-900 flex items-center gap-2"><Award size={14}/> Signature</th>
                    <th className="px-6 py-5 text-blue-900 bg-blue-50/50 flex items-center gap-2"><Trophy size={14}/> Elite Tier</th>
                    <th className="px-6 py-5 text-blue-900 flex items-center gap-2"><Crown size={14}/> Prime Tier</th>
                  </tr>
                </thead>
