                  {tieredAccommodationRows.length > 0 ? tieredAccommodationRows.map((row, i) => (
                    <tr key={i} className="divide-x-2 divide-slate-900">
                      <td className="px-6 py-5 font-black text-blue-900 bg-slate-50/20 uppercase tracking-wider">{row.location}</td>
                      <td className="px-6 py-5">{row.signature}</td>
                      <td className="px-6 py-5 bg-blue-50/10 font-black">{row.elite}</td>
