             </div>
          </div>
        </div>

        {/* PAGE 2: DAY WISE SUMMARY */}
        <div className="page-break" />
        <div className="p-16 space-y-12">
           <h4 className="text-3xl font-black text-blue-900 tracking-tight flex items-center gap-5 uppercase">
