                      </tr>
                    );
                  })}
                </tbody>
              </table>
           </div>

           <div className="grid grid-cols-2 gap-12 pt-12">
             <div className="space-y-8 p-8 bg-blue-50/30 rounded-[40px] border border-blue-100">
                <h4 className="text-2xl font-black text-blue-900 uppercase tracking-widest flex items-center gap-4">
                   <ShieldCheck size={28} className="text-emerald-500" /> What's Included
                </h4>
                <ul className="space-y-5">
                  {(trip.inclusions || DEFAULT_INCLUSIONS).map((inc, i) => (
                    <li key={i} className="flex gap-4 text-sm font-bold text-slate-700 leading-tight">
                       <span className="text-blue-600 font-black text-lg">•</span> {inc}
                    </li>
                  ))}
                </ul>
             </div>

             <div className="space-y-8 p-8 bg-rose-50/20 rounded-[40px] border border-rose-100">
                <h4 className="text-2xl font-black text-rose-900 uppercase tracking-widest flex items-center gap-4">
                   <XCircle size={28} className="text-rose-500" /> What's Not Included
                </h4>
                <ul className="space-y-5">
                  {(trip.exclusions || DEFAULT_EXCLUSIONS).map((exc, i) => (
                    <li key={i} className="flex gap-4 text-sm font-bold text-slate-400 leading-tight">
                       <span className="text-rose-500 font-black text-lg">•</span> {exc}
                    </li>
                  ))}
                </ul>
             </div>
          </div>
        </div>

        {/* PAGE 3: TERMS & BRANDING */}
        <div className="page-break" />
        <div className="p-16 space-y-16">
          <div className="space-y-12">
            <div>
              <h4 className="text-2xl font-black text-blue-900 border-b-4 border-slate-900 pb-5 mb-10 uppercase tracking-[0.2em]">Operational Guidelines</h4>
              <ul className="space-y-6">
                {TERMS_AND_CONDITIONS.map((tc, i) => (
                  <li key={i} className="flex gap-4 text-sm font-bold text-slate-700 leading-relaxed bg-slate-50 p-5 rounded-2xl border border-slate-100">
                    <span className="text-blue-600 font-black text-2xl">•</span> {tc}
                  </li>
                ))}
              </ul>
            </div>
          </div>

          <footer className="mt-20 pt-16 border-t-8 border-slate-900 flex justify-between items-end">
            <div className="space-y-6">
              <h2 className="text-6xl font-black text-slate-900 tracking-tighter uppercase leading-none">{BRAND_CONFIG.name}</h2>
              <div className="space-y-2 text-xs font-black text-slate-400 uppercase tracking-[0.3em]">
                <p>{BRAND_CONFIG.phone}</p>
                <p>{BRAND_CONFIG.email}</p>
                <p>{BRAND_CONFIG.address}</p>
              </div>
            </div>
            <div className="bg-slate-900 p-12 rounded-[50px] text-white shadow-2xl">
              <MountainLogo />
            </div>
          </footer>
        </div>

      </div>
    </div>
  );
};

const MountainLogo = () => (
  <svg width="70" height="70" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round">
    <path d="m8 3 4 8 5-5 5 15H2L8 3z"/>
  </svg>
)

export default ClientItinerary;

import React, { useState, useMemo, useEffect } from 'react';
import { useParams, useNavigate, Link } from 'react-router-dom';
import { 
  Plus, 
  Trash2, 
  Save, 
  Sparkles,
  ArrowLeft,
  CalendarDays,
  Hotel as HotelIcon,
  Car as CarIcon,
  History,
  Download,
  Check,
  MapPin,
  Utensils,
  Map as MapIcon,
  PlusCircle,
  Wallet,
  MapPinned,
  IndianRupee,
  Star,
  ListPlus,
  X,
  ChevronRight,
  ShieldCheck,
  XCircle,
  Trophy,
  Award,
  Crown,
  Compass
} from 'lucide-react';
import { MOCK_TRIPS, HOTELS, VEHICLES, ACTIVITIES, ADD_ONS, DEFAULT_INCLUSIONS, DEFAULT_EXCLUSIONS } from '../constants';
import { Trip, ItineraryDay, TripVersion, HotelCategory, Hotel, MealPlan, TripStatus, AddOn, Vehicle, HotelTierSelection, TierPrices } from '../types';
import { generateDayDescription, suggestNextDayTitle } from '../services/geminiService';

const TripBuilder: React.FC = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const [trip, setTrip] = useState<Trip | null>(null);
  const [activeDayIndex, setActiveDayIndex] = useState(0);
  const [isAiGenerating, setIsAiGenerating] = useState(false);

  const [newHighlight, setNewHighlight] = useState('');
  const [newInclusion, setNewInclusion] = useState('');
  const [newExclusion, setNewExclusion] = useState('');

  const masterHotels = useMemo(() => {
    const saved = localStorage.getItem('et_hotels');
    const custom = saved ? JSON.parse(saved) : [];
    const customIds = new Set(custom.map((h: Hotel) => h.id));
    return [...HOTELS.filter(h => !customIds.has(h.id)), ...custom];
  }, []);

  const masterVehicles = useMemo(() => {
    const saved = localStorage.getItem('et_vehicles');
    const custom = saved ? JSON.parse(saved) : [];
    const customIds = new Set(custom.map((v: Vehicle) => v.id));
    return [...VEHICLES.filter(v => !customIds.has(v.id)), ...custom];
  }, []);

  const masterAddOns = useMemo(() => {
    const saved = localStorage.getItem('et_addons');
    const custom = saved ? JSON.parse(saved) : [];
    const customIds = new Set(custom.map((a: AddOn) => a.id));
    return [...ADD_ONS.filter(a => !customIds.has(a.id)), ...custom];
  }, []);

  useEffect(() => {
    const savedTrips = localStorage.getItem('et_trips');
    let foundTrip: Trip | undefined;

    if (savedTrips) {
      const parsed = JSON.parse(savedTrips);
      foundTrip = parsed.find((t: Trip) => t.id === id);
    }

    if (!foundTrip) {
      foundTrip = MOCK_TRIPS.find(t => t.id === id);
    }

    if (foundTrip) {
      setTrip({ 
        ...foundTrip, 
        startLocation: foundTrip.startLocation || 'Srinagar',
        inclusions: foundTrip.inclusions || [...DEFAULT_INCLUSIONS],
        exclusions: foundTrip.exclusions || [...DEFAULT_EXCLUSIONS],
        hotelTiers: foundTrip.hotelTiers || [],
        tierPrices: foundTrip.tierPrices || { signature: 0, elite: 0, prime: 0 }
      });
    }
  }, [id]);

  useEffect(() => {
    if (trip) {
      const savedTrips = localStorage.getItem('et_trips');
      let allTrips: Trip[] = savedTrips ? JSON.parse(savedTrips) : [...MOCK_TRIPS];
      const index = allTrips.findIndex(t => t.id === trip.id);
      if (index > -1) allTrips[index] = trip;
      else allTrips.push(trip);
      localStorage.setItem('et_trips', JSON.stringify(allTrips));
    }
  }, [trip]);

  const itineraryLocations = useMemo(() => {
    if (!trip) return [];
    return Array.from(new Set(trip.itinerary.map(day => {
      const hotel = masterHotels.find(h => h.id === day.hotelId);
      return hotel?.location || 'Srinagar';
    })));
  }, [trip, masterHotels]);

  const costs = useMemo(() => {
    if (!trip) return { total: 0, sellingPrice: 0, margin: 0 };
    let hotelCost = 0, vehicleCost = 0, activityCost = 0, addOnsCost = 0, jammuSurcharge = 0;
    const JAMMU_DAILY_SURCHARGE = 1000;

    trip.itinerary.forEach(day => {
      if (day.hotelId) {
        const hotel = masterHotels.find(h => h.id === day.hotelId);
        if (hotel) {
          hotelCost += hotel.ratePerNight;
        }
      }
      if (day.vehicleId) {
        const vehicle = masterVehicles.find(v => v.id === day.vehicleId);
        if (vehicle) {
          vehicleCost += vehicle.ratePerDay;
          if (trip.startLocation === 'Jammu') jammuSurcharge += JAMMU_DAILY_SURCHARGE;
        }
      }
      (day.activityIds || []).forEach(aid => {
        const act = ACTIVITIES.find(a => a.id === aid);
        if (act) activityCost += act.costPerPax * trip.pax;
      });
    });

    trip.addOnIds.forEach(aoId => {
      const ao = masterAddOns.find(a => a.id === aoId);
      if (ao) addOnsCost += ao.isPerPax ? ao.cost * trip.pax : ao.cost;
    });

    const subtotal = hotelCost + vehicleCost + jammuSurcharge + activityCost + addOnsCost;
    const margin = subtotal * (trip.marginPercentage / 100);
    return { total: subtotal, margin, sellingPrice: subtotal + margin };
  }, [trip, masterHotels, masterVehicles, masterAddOns]);

  const updateDay = (index: number, updates: Partial<ItineraryDay>) => {
    if (!trip) return;
    const newItinerary = [...trip.itinerary];
    newItinerary[index] = { ...newItinerary[index], ...updates };
    setTrip({ ...trip, itinerary: newItinerary });
  };

  const toggleActivity = (activityId: string) => {
    if (!trip) return;
    const currentDay = trip.itinerary[activeDayIndex];
    const currentActivityIds = currentDay.activityIds || [];
    const isSelected = currentActivityIds.includes(activityId);

    const updatedIds = isSelected 
      ? currentActivityIds.filter(id => id !== activityId)
      : [...currentActivityIds, activityId];

    updateDay(activeDayIndex, { activityIds: updatedIds });
  };

  const updateTierSelection = (location: string, tier: 'signature' | 'elite' | 'prime', hotelId: string) => {
    if (!trip) return;
    const tiers = [...(trip.hotelTiers || [])];
    const index = tiers.findIndex(t => t.location === location);

    if (index > -1) {
      tiers[index] = { ...tiers[index], [`${tier}HotelId`]: hotelId };
    } else {
      tiers.push({
        location,
        signatureHotelId: tier === 'signature' ? hotelId : '',
        eliteHotelId: tier === 'elite' ? hotelId : '',
        primeHotelId: tier === 'prime' ? hotelId : ''
      });
    }
    setTrip({ ...trip, hotelTiers: tiers });
  };

  const updateTierPrice = (tier: keyof TierPrices, value: string) => {
    if (!trip) return;
    setTrip({ 
      ...trip, 
      tierPrices: { 
        ...(trip.tierPrices || { signature: 0, elite: 0, prime: 0 }), 
        [tier]: parseInt(value) || 0 
      } 
    });
  };

  const addHighlight = () => {
    if (!trip || !newHighlight.trim()) return;
    const day = trip.itinerary[activeDayIndex];
    const updatedHighlights = [...(day.highlights || []), newHighlight.trim()];
    updateDay(activeDayIndex, { highlights: updatedHighlights });
    setNewHighlight('');
  };

  const removeHighlight = (idx: number) => {
    if (!trip) return;
    const day = trip.itinerary[activeDayIndex];
    const updatedHighlights = (day.highlights || []).filter((_, i) => i !== idx);
    updateDay(activeDayIndex, { highlights: updatedHighlights });
  };

  const addInclusion = () => {
    if (!trip || !newInclusion.trim()) return;
    setTrip({ ...trip, inclusions: [...(trip.inclusions || []), newInclusion.trim()] });
    setNewInclusion('');
  };

  const removeInclusion = (idx: number) => {
    if (!trip) return;
    setTrip({ ...trip, inclusions: (trip.inclusions || []).filter((_, i) => i !== idx) });
  };

  const addExclusion = () => {
    if (!trip || !newExclusion.trim()) return;
    setTrip({ ...trip, exclusions: [...(trip.exclusions || []), newExclusion.trim()] });
    setNewExclusion('');
  };

  const removeExclusion = (idx: number) => {
    if (!trip) return;
    setTrip({ ...trip, exclusions: (trip.exclusions || []).filter((_, i) => i !== idx) });
  };

  const handleAiDescription = async () => {
    if (!trip) return;
    setIsAiGenerating(true);
    const day = trip.itinerary[activeDayIndex];
    const activitiesNames = (day.activityIds || []).map(aid => ACTIVITIES.find(a => a.id === aid)?.name || '');
    const description = await generateDayDescription(day.title, activitiesNames);
    updateDay(activeDayIndex, { clientNotes: description });
    setIsAiGenerating(false);
  };

  const handleAddDay = async () => {
    if (!trip) return;
    const nextDayNum = trip.itinerary.length + 1;
    const lastDay = trip.itinerary[trip.itinerary.length - 1];
    const newDay: ItineraryDay = {
      id: `d-${Date.now()}`,
      dayNumber: nextDayNum,
      title: `Day ${nextDayNum}: New Adventures`,
      hotelId: lastDay?.hotelId || '',
      vehicleId: lastDay?.vehicleId || '',
      activityIds: [],
      highlights: [],
      clientNotes: '',
      internalNotes: ''
    };
    setTrip({ ...trip, itinerary: [...trip.itinerary, newDay] });
    setActiveDayIndex(trip.itinerary.length);
  };

  if (!trip) return <div className="p-20 text-center text-slate-400 font-black uppercase tracking-widest">LOADING BUILDER...</div>;

  return (
    <div className="flex flex-col h-full space-y-6 pb-20">
      {/* Header Bar */}
      <div className="bg-white p-6 rounded-3xl border border-slate-200 shadow-sm flex flex-col md:flex-row md:items-center justify-between gap-6">
        <div className="flex items-center gap-5">
          <button onClick={() => navigate('/trips')} className="p-3 hover:bg-slate-50 rounded-2xl transition-all border border-slate-100 shadow-sm">
            <ArrowLeft size={20} className="text-slate-600" />
          </button>
          <div>
            <h1 className="text-2xl font-black text-slate-900 tracking-tight">{trip.tripName}</h1>
            <div className="flex items-center gap-3 mt-1 text-slate-400">
               <span className="text-[10px] font-black uppercase tracking-widest text-blue-600">{trip.client.name}</span>
               <span className="w-1 h-1 bg-slate-200 rounded-full"/>
               <div className="flex items-center gap-1.5 bg-slate-50 px-2 py-0.5 rounded-full border border-slate-100">
                  <MapIcon size={12} className="text-slate-400" />
                  <select 
                    className="bg-transparent text-[10px] font-black uppercase text-slate-600 outline-none cursor-pointer"
                    value={trip.startLocation}
                    onChange={(e) => setTrip({ ...trip, startLocation: e.target.value as 'Srinagar' | 'Jammu' })}
                  >
                    <option value="Srinagar">Srinagar Start</option>
                    <option value="Jammu">Jammu (+₹1k/day Vehicle)</option>
                  </select>
               </div>
            </div>
          </div>
        </div>

        <div className="flex items-center gap-4">
          <div className="flex items-center gap-6 px-6 py-3 bg-slate-50 rounded-2xl border border-slate-100">
             <div className="text-right">
               <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Base Quote (Elite)</p>
               <p className="text-xl font-black text-blue-600">₹{costs.sellingPrice.toLocaleString()}</p>
             </div>
          </div>
          <button 
            onClick={() => navigate(`/trips/${trip.id}/print`)}
            className="bg-blue-600 text-white px-8 py-4 rounded-2xl font-black uppercase tracking-widest text-xs flex items-center gap-3 shadow-xl hover:bg-blue-700 transition-all active:scale-95"
          >
            <Download size={18} /> PROPOSAL / PDF
          </button>
        </div>
      </div>

      <div className="grid grid-cols-12 gap-8 flex-1 overflow-hidden">
        {/* Left: Day List */}
        <div className="col-span-12 lg:col-span-3 space-y-4 overflow-y-auto pr-2">
           <div className="bg-white border border-slate-200 rounded-[32px] p-6 shadow-sm flex flex-col h-full">
              <div className="flex items-center justify-between mb-6">
                <h3 className="text-xs font-black uppercase tracking-widest text-slate-400 flex items-center gap-2">
                   <CalendarDays size={16} className="text-blue-600" /> Itinerary Steps
                </h3>
              </div>
              <div className="space-y-3 flex-1">
                {trip.itinerary.map((day, idx) => (
                  <button 
                    key={day.id} 
                    onClick={() => setActiveDayIndex(idx)}
                    className={`w-full text-left p-4 rounded-2xl border transition-all flex flex-col gap-1 ${
                      activeDayIndex === idx ? 'bg-blue-600 border-blue-600 text-white shadow-lg' : 'bg-white border-slate-100 hover:border-slate-300 text-slate-700'
                    }`}
                  >
                    <span className={`text-[9px] font-black uppercase tracking-widest ${activeDayIndex === idx ? 'text-blue-100' : 'text-blue-600'}`}>Day {day.dayNumber}</span>
                    <h4 className="font-bold text-sm truncate">{day.title}</h4>
                  </button>
                ))}
                <button 
                  onClick={handleAddDay}
                  className="w-full py-5 border-2 border-dashed border-slate-200 rounded-2xl text-slate-400 font-black uppercase tracking-widest text-[10px] flex items-center justify-center gap-2 hover:border-blue-300 hover:text-blue-600 hover:bg-blue-50/30 transition-all"
                >
                  <Plus size={16} /> Add Next Day
                </button>
              </div>
           </div>
        </div>

        {/* Center: Content Editor */}
        <div className="col-span-12 lg:col-span-6 space-y-8 overflow-y-auto pr-2 pb-24">
           {trip.itinerary[activeDayIndex] && (
             <div className="bg-white border border-slate-200 rounded-[40px] p-10 shadow-sm space-y-10 animate-in fade-in slide-in-from-bottom-4 duration-300">
                <div className="space-y-3">
                   <label className="text-[11px] font-black uppercase tracking-[0.2em] text-slate-400 ml-1">Daily Title Headline</label>
                   <div className="relative group">
                     <input 
                       type="text" 
                       value={trip.itinerary[activeDayIndex].title}
                       onChange={(e) => updateDay(activeDayIndex, { title: e.target.value })}
                       className="w-full px-8 py-6 bg-blue-50/30 border-2 border-blue-100 rounded-3xl text-2xl font-black text-slate-900 focus:bg-white focus:ring-8 focus:ring-blue-50 transition-all outline-none shadow-sm"
                       placeholder="Enter day title..."
                     />
                   </div>
                </div>

                <div className="grid grid-cols-2 gap-8">
                   <div className="space-y-4">
                      <label className="text-xs font-black uppercase text-slate-700 flex items-center gap-2 tracking-widest">
                         <HotelIcon size={16} className="text-blue-500" /> Default Stay
                      </label>
                      <select 
                        value={trip.itinerary[activeDayIndex].hotelId}
                        onChange={(e) => updateDay(activeDayIndex, { hotelId: e.target.value })}
                        className="w-full p-4 bg-slate-50 border border-slate-200 rounded-2xl font-black text-xs text-slate-900 shadow-sm outline-none"
                      >
                         <option value="">Select Base Hotel...</option>
                         {masterHotels.map(h => <option key={h.id} value={h.id}>{h.name} ({h.location})</option>)}
                      </select>
                   </div>
                   <div className="space-y-4">
                      <label className="text-xs font-black uppercase text-slate-700 flex items-center gap-2 tracking-widest">
                         <CarIcon size={16} className="text-blue-500" /> Fleet Item
                      </label>
                      <select 
                        value={trip.itinerary[activeDayIndex].vehicleId}
                        onChange={(e) => updateDay(activeDayIndex, { vehicleId: e.target.value })}
                        className="w-full p-4 bg-slate-50 border border-slate-200 rounded-2xl font-black text-xs text-slate-900 shadow-sm outline-none"
                      >
                         <option value="">Select Transport...</option>
                         {masterVehicles.map(v => <option key={v.id} value={v.id}>{v.brand} {v.type}</option>)}
                      </select>
                   </div>
                </div>

                {/* Daily Activity Library (RESTORED) */}
                <div className="space-y-6">
                   <div className="flex items-center justify-between border-b border-slate-100 pb-3">
                      <h4 className="text-[10px] font-black uppercase tracking-widest text-slate-400 flex items-center gap-2">
                         <Compass size={14} className="text-emerald-500" /> Planned Daily Activities
                      </h4>
                   </div>
                   <div className="flex flex-wrap gap-3">
                      {ACTIVITIES.map(act => {
                         const isSelected = (trip.itinerary[activeDayIndex].activityIds || []).includes(act.id);
                         return (
                            <button 
                               key={act.id}
                               onClick={() => toggleActivity(act.id)}
                               className={`px-4 py-2.5 rounded-xl border text-[10px] font-black uppercase tracking-widest transition-all ${
                                  isSelected 
                                  ? 'bg-emerald-600 border-emerald-600 text-white shadow-lg' 
                                  : 'bg-white border-slate-200 text-slate-400 hover:border-emerald-200 hover:text-emerald-600'
                               }`}
                            >
                               {act.name}
                            </button>
                         );
                      })}
                   </div>
                </div>

                <div className="space-y-6">
                   <div className="flex items-center justify-between border-b border-slate-100 pb-3">
                      <h4 className="text-[10px] font-black uppercase tracking-widest text-slate-400 flex items-center gap-2">
                         <Star size={14} className="text-amber-500" /> Highlights List
                      </h4>
                   </div>
                   <div className="space-y-3">
                      {(trip.itinerary[activeDayIndex].highlights || []).map((h, i) => (
                        <div key={i} className="flex items-center gap-3 group">
                           <div className="flex-1 bg-blue-50 border border-blue-100 text-blue-900 px-6 py-4 rounded-2xl text-xs font-bold shadow-sm">
                              {h}
                           </div>
                           <button onClick={() => removeHighlight(i)} className="p-4 text-slate-300 hover:text-rose-500 transition-colors">
                              <X size={16}/>
                           </button>
                        </div>
                      ))}
                      <div className="flex gap-2">
                        <input 
                          type="text" 
                          placeholder="e.g. Shikara at sunset..."
                          value={newHighlight}
                          onChange={(e) => setNewHighlight(e.target.value)}
                          onKeyDown={(e) => e.key === 'Enter' && addHighlight()}
                          className="flex-1 p-5 bg-white border-2 border-dashed border-slate-200 rounded-2xl text-xs font-bold outline-none"
                        />
                        <button onClick={addHighlight} className="bg-slate-900 text-white px-6 rounded-2xl active:scale-95">
                          <Plus size={24} />
                        </button>
                      </div>
                   </div>
                </div>

                <div className="space-y-6">
                   <div className="flex items-center justify-between border-b border-slate-100 pb-3">
                      <h4 className="text-[10px] font-black uppercase tracking-widest text-slate-400">Detailed Client Story</h4>
                      <button 
                        onClick={handleAiDescription}
                        disabled={isAiGenerating}
                        className="flex items-center gap-2 text-[10px] font-black uppercase tracking-widest text-blue-600 hover:text-blue-700 disabled:opacity-50 transition-all"
                      >
                        <Sparkles size={14} /> AI Enchant Story
                      </button>
                   </div>
                   <textarea 
                     rows={8}
                     value={trip.itinerary[activeDayIndex].clientNotes}
                     onChange={(e) => updateDay(activeDayIndex, { clientNotes: e.target.value })}
                     className="w-full p-8 bg-slate-50 border border-slate-200 rounded-[32px] text-base leading-relaxed text-slate-800 outline-none focus:ring-4 focus:ring-blue-50 transition-all shadow-inner"
                     placeholder="Write the story of this day for the guest..."
                   />
                </div>
             </div>
           )}
        </div>

        {/* Right Sidebar: Master Config */}
        <div className="col-span-12 lg:col-span-3 space-y-6 overflow-y-auto pr-2 pb-20">

           {/* Tiered Package Setup */}
           <div className="bg-white border-2 border-blue-600 rounded-[32px] p-8 shadow-xl space-y-8">
              <h3 className="text-xs font-black uppercase tracking-widest text-blue-600 flex items-center gap-2">
                 <Crown size={18} /> Package Tier Configuration
              </h3>

              {itineraryLocations.map(location => {
                const selection = trip.hotelTiers?.find(t => t.location === location) || { signatureHotelId: '', eliteHotelId: '', primeHotelId: '' };
                return (
                  <div key={location} className="space-y-4 pt-4 border-t border-slate-100 first:border-0 first:pt-0">
                    <p className="text-[10px] font-black uppercase text-slate-900 tracking-widest bg-blue-50 px-3 py-1 rounded-full w-fit">In {location}</p>
                    <div className="space-y-3">
                       <div className="space-y-1">
                          <label className="text-[9px] font-black uppercase text-slate-400 flex items-center gap-1"><Award size={10}/> Signature</label>
