                    </div>
                    <div className="space-y-1">
                       <label className="text-[8px] font-black uppercase text-amber-600">Prime</label>
                       <input type="number" value={trip.tierPrices?.prime || ''} onChange={(e) => updateTierPrice('prime', e.target.value)} className="w-full p-2 bg-amber-50 border border-amber-200 rounded-lg text-[10px] font-bold outline-none" />
                    </div>
                 </div>
              </div>
           </div>

           {/* Premium Experiences (RESTORED / VERIFIED) */}
           <div className="bg-slate-900 border border-slate-800 rounded-[32px] p-8 shadow-2xl space-y-8">
