        <button onClick={() => navigate(`/trips/${id}`)} className="text-slate-500 font-bold flex items-center gap-2 hover:text-slate-900 transition-colors">
          <ArrowLeft size={18} /> BACK TO BUILDER
        </button>
        <div className="flex gap-4">
          <button onClick={() => window.print()} className="bg-white border border-slate-200 px-6 py-2.5 rounded-xl font-bold flex items-center gap-2 shadow-sm hover:bg-slate-50">
            <Printer size={18} /> PRINT
          </button>
          <button onClick={handleDownloadPdf} disabled={isGenerating} className="bg-blue-600 text-white px-8 py-2.5 rounded-xl font-bold flex items-center gap-2 shadow-xl hover:bg-blue-700 transition-all">
            {isGenerating ? <Loader2 size={18} className="animate-spin" /> : <Download size={18} />}
            {isGenerating ? 'GENERATING...' : 'DOWNLOAD PDF'}
          </button>
        </div>
      </div>

      {/* Proposal Document */}
      <div className="max-w-[210mm] mx-auto bg-white shadow-2xl my-10 print:my-0 print:shadow-none" ref={printableRef}>

