import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { LeadStage, Lead, LeadScore } from '../types';
import { MOCK_LEADS } from '../constants';
import { 
  MoreVertical, 
  Plus, 
  Calendar, 
  MessageSquare, 
  Phone, 
  TrendingUp, 
  Flame, 
  Snowflake,
  Search
} from 'lucide-react';

const Pipeline: React.FC = () => {
  const navigate = useNavigate();
  const [leads, setLeads] = useState<Lead[]>([]);
  const stages = Object.values(LeadStage);

  useEffect(() => {
    const saved = localStorage.getItem('et_leads');
    setLeads(saved ? JSON.parse(saved) : MOCK_LEADS);
  }, []);

  const getLeadsByStage = (stage: LeadStage) => leads.filter(l => l.stage === stage);

  const ScoreBadge = ({ score }: { score: LeadScore }) => {
    if (score === LeadScore.HOT) return <div className="p-1 bg-rose-100 text-rose-600 rounded-md"><Flame size={14} /></div>;
    if (score === LeadScore.WARM) return <div className="p-1 bg-orange-100 text-orange-600 rounded-md"><TrendingUp size={14} /></div>;
    return <div className="p-1 bg-blue-100 text-blue-600 rounded-md"><Snowflake size={14} /></div>;
  };

  return (
    <div className="h-full flex flex-col gap-6">
      <div className="flex items-center justify-between">
        <div className="relative w-96">
           <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-300" size={18} />
           <input 
             type="text" 
             placeholder="Search leads by name or phone..." 
             className="w-full pl-10 pr-4 py-3 bg-white border border-slate-200 rounded-2xl text-sm outline-none focus:ring-4 focus:ring-blue-50 transition-all shadow-sm"
           />
        </div>
        <button 
          onClick={() => navigate('/leads/new')}
          className="bg-slate-900 text-white px-6 py-3 rounded-2xl font-black uppercase tracking-widest text-[11px] flex items-center gap-2 hover:bg-slate-800 transition-all shadow-xl active:scale-95"
        >
          <Plus size={18} /> Add New Lead
        </button>
      </div>

      <div className="flex-1 overflow-x-auto pb-6">
        <div className="flex gap-6 h-full min-w-max">
          {stages.map(stage => (
            <div key={stage} className="w-80 flex flex-col gap-4">
              <div className="flex items-center justify-between px-2">
                <div className="flex items-center gap-2">
                  <h3 className="text-xs font-black uppercase tracking-[0.2em] text-slate-500">{stage}</h3>
                  <span className="bg-slate-100 text-slate-500 text-[10px] font-bold px-2 py-0.5 rounded-full">
                    {getLeadsByStage(stage).length}
                  </span>
                </div>
                <button className="text-slate-400 hover:text-slate-900"><Plus size={16}/></button>
              </div>

              <div className="flex-1 bg-slate-100/50 rounded-[32px] p-4 space-y-4 border-2 border-dashed border-slate-200 overflow-y-auto">
                {getLeadsByStage(stage).map(lead => (
                  <div 
                    key={lead.id}
                    onClick={() => navigate(`/leads/${lead.id}`)}
                    className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm hover:shadow-xl hover:border-blue-200 transition-all cursor-pointer group"
                  >
                    <div className="flex items-start justify-between mb-3">
                      <ScoreBadge score={lead.score} />
                      <button className="text-slate-300 group-hover:text-slate-600 transition-colors"><MoreVertical size={16}/></button>
                    </div>
                    <h4 className="font-black text-slate-900 mb-1">{lead.name}</h4>
                    <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{lead.interest} • {lead.pax} PAX</p>

                    <div className="mt-4 flex items-center gap-4 text-slate-400">
                      <div className="flex items-center gap-1.5"><Calendar size={12}/> <span className="text-[10px] font-bold uppercase">{lead.travelMonth}</span></div>
                      <div className="flex items-center gap-1.5"><TrendingUp size={12}/> <span className="text-[10px] font-bold uppercase">{lead.budgetRange}</span></div>
                    </div>

                    <div className="mt-6 flex items-center justify-between pt-4 border-t border-slate-50">
                       <div className="flex -space-x-2">
                          <img src={`https://picsum.photos/seed/${lead.assignedTo}/32/32`} className="w-6 h-6 rounded-full border-2 border-white" title={lead.assignedTo} alt="Sales" />
                       </div>
                       <div className="flex gap-2">
                          <button className="p-2 text-slate-300 hover:text-blue-600 bg-slate-50 rounded-lg"><Phone size={14}/></button>
                          <button className="p-2 text-slate-300 hover:text-emerald-500 bg-slate-50 rounded-lg"><MessageSquare size={14}/></button>
                       </div>
                    </div>
                  </div>
                ))}
                {getLeadsByStage(stage).length === 0 && (
                  <div className="h-24 flex items-center justify-center text-[10px] font-black uppercase text-slate-300 tracking-widest">Empty Stage</div>
                )}
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default Pipeline;

import React from 'react';
import { HashRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import Layout from './components/Layout';
import Dashboard from './pages/Dashboard';
import Pipeline from './pages/Pipeline';
import LeadProfile from './pages/LeadProfile';
import TripBuilder from './pages/TripBuilder';
import Hotels from './pages/Hotels';
import Vehicles from './pages/Vehicles';
import Activities from './pages/Activities';
import AddOns from './pages/AddOns';
import Templates from './pages/Templates';
import TemplateBuilder from './pages/TemplateBuilder';
import Settings from './pages/Settings';
import NewTrip from './pages/NewTrip';
import ClientItinerary from './pages/ClientItinerary';

const App: React.FC = () => {
  return (
    <Router>
      <Routes>
        {/* Specific Route for Print View - Must be outside Layout */}
        <Route path="/trips/:id/print" element={<ClientItinerary />} />

        {/* Main Application Routes */}
        <Route path="/" element={<Layout><Dashboard /></Layout>} />
        <Route path="/pipeline" element={<Layout><Pipeline /></Layout>} />
        <Route path="/leads/:id" element={<Layout><LeadProfile /></Layout>} />
        <Route path="/trips" element={<Layout><Pipeline /></Layout>} /> {/* Trips default to Pipeline for MVP */}
        <Route path="/trips/new" element={<Layout><NewTrip /></Layout>} />
        <Route path="/trips/:id" element={<Layout><TripBuilder /></Layout>} />
        <Route path="/hotels" element={<Layout><Hotels /></Layout>} />
        <Route path="/vehicles" element={<Layout><Vehicles /></Layout>} />
        <Route path="/activities" element={<Layout><Activities /></Layout>} />
        <Route path="/add-ons" element={<Layout><AddOns /></Layout>} />
        <Route path="/templates" element={<Layout><Templates /></Layout>} />
        <Route path="/templates/:id/edit" element={<Layout><TemplateBuilder /></Layout>} />
        <Route path="/settings" element={<Layout><Settings /></Layout>} />

        {/* Catch-all redirect to Dashboard */}
        <Route path="*" element={<Navigate to="/" replace />} />
      </Routes>
    </Router>
  );
};

export default App;

