               <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Base Quote (Elite)</p>
               <p className="text-xl font-black text-blue-600">₹{costs.sellingPrice.toLocaleString()}</p>
             </div>
          </div>
          <button 
            onClick={() => navigate(`/trips/${trip.id}/print`)}
            className="bg-blue-600 text-white px-8 py-4 rounded-2xl font-black uppercase tracking-widest text-xs flex items-center gap-3 shadow-xl hover:bg-blue-700 transition-all active:scale-95"
          >
            <Download size={18} /> PROPOSAL / PDF
          </button>
        </div>
      </div>

      <div className="grid grid-cols-12 gap-8 flex-1 overflow-hidden">
        {/* Left: Day List & Stay Summary */}
