           {/* Premium Add-ons Section */}
           <div className="bg-slate-900 border border-slate-800 rounded-[32px] p-8 shadow-2xl space-y-8">
              <div className="flex items-center justify-between">
                <h3 className="text-xs font-black uppercase tracking-widest text-slate-400 flex items-center gap-2">
                   <Sparkles size={16} className="text-blue-400" /> Premium Experiences
                </h3>
              </div>
              <div className="space-y-3">
                 {masterAddOns.map(ao => {
                   const isSelected = (trip.addOnIds || []).includes(ao.id);
                   return (
                     <button 
                       key={ao.id}
                       onClick={() => {
                         const updated = isSelected ? trip.addOnIds.filter(id => id !== ao.id) : [...trip.addOnIds, ao.id];
                         setTrip({...trip, addOnIds: updated});
                       }}
                       className={`w-full text-left p-5 rounded-3xl border transition-all flex flex-col gap-1 ${
                         isSelected ? 'bg-blue-600 border-blue-600 text-white shadow-lg' : 'bg-slate-800 border-slate-700 text-slate-400 hover:bg-slate-700'
                       }`}
                     >
                        <div className="flex items-center justify-between mb-1">
                           <span className={`text-xs font-black ${isSelected ? 'text-white' : 'text-slate-200'}`}>{ao.name}</span>
                           {isSelected && <Check size={14} className="text-white" />}
                        </div>
                        <div className="flex justify-between items-center">
                           <span className={`text-[9px] font-bold uppercase tracking-widest ${isSelected ? 'text-blue-100' : 'text-slate-500'}`}>{ao.isPerPax ? 'Per Guest' : 'Flat'}</span>
                           <span className={`text-sm font-black ${isSelected ? 'text-white' : 'text-blue-400'}`}>₹{ao.cost.toLocaleString()}</span>
                        </div>
                     </button>
                   );
                 })}
              </div>
           </div>

           {/* Terms Sidebar */}
           <div className="space-y-6 pb-10">
              <div className="bg-white border border-slate-200 rounded-[32px] p-8 shadow-sm space-y-6">
                 <h3 className="text-xs font-black uppercase tracking-widest text-emerald-600 flex items-center gap-2"><ShieldCheck size={16} /> Trip Inclusions</h3>
                 <div className="space-y-2">
                    {(trip.inclusions || []).map((inc, i) => (
                       <div key={i} className="flex items-center gap-2 group">
                          <div className="flex-1 text-[10px] font-bold text-slate-600 bg-emerald-50 p-3 rounded-xl line-clamp-2">{inc}</div>
                          <button onClick={() => removeInclusion(i)} className="text-slate-300 hover:text-rose-500"><Trash2 size={14}/></button>
                       </div>
                    ))}
                    <div className="flex gap-2 pt-2">
                       <input type="text" placeholder="Add..." value={newInclusion} onChange={(e) => setNewInclusion(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && addInclusion()} className="flex-1 p-2 bg-slate-50 border border-slate-100 rounded-lg text-[10px] font-bold outline-none" />
                       <button onClick={addInclusion} className="bg-emerald-600 text-white p-2 rounded-lg transition-all active:scale-90"><Plus size={14}/></button>
                    </div>
                 </div>
              </div>

              <div className="bg-white border border-slate-200 rounded-[32px] p-8 shadow-sm space-y-6">
                 <h3 className="text-xs font-black uppercase tracking-widest text-rose-500 flex items-center gap-2"><XCircle size={16} /> Trip Exclusions</h3>
                 <div className="space-y-2">
                    {(trip.exclusions || []).map((exc, i) => (
                       <div key={i} className="flex items-center gap-2 group">
                          <div className="flex-1 text-[10px] font-bold text-slate-600 bg-rose-50 p-3 rounded-xl line-clamp-2">{exc}</div>
                          <button onClick={() => removeExclusion(i)} className="text-slate-300 hover:text-rose-500"><Trash2 size={14}/></button>
                       </div>
                    ))}
                    <div className="flex gap-2 pt-2">
                       <input type="text" placeholder="Add..." value={newExclusion} onChange={(e) => setNewExclusion(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && addExclusion()} className="flex-1 p-2 bg-slate-50 border border-slate-100 rounded-lg text-[10px] font-bold outline-none" />
                       <button onClick={addExclusion} className="bg-rose-500 text-white p-2 rounded-lg transition-all active:scale-90"><Plus size={14}/></button>
                    </div>
                 </div>
              </div>
           </div>
        </div>
      </div>
    </div>
  );
};

export default TripBuilder;

