                      </label>
                      <select 
                        value={trip.itinerary[activeDayIndex].hotelId}
                        onChange={(e) => updateDay(activeDayIndex, { hotelId: e.target.value })}
                        className="w-full p-4 bg-blue-50 border border-blue-100 rounded-2xl font-black text-xs text-blue-900 shadow-sm outline-none"
                      >
                         <option value="">Select Property...</option>
                         {masterHotels
                           .filter(h => {
                             const loc = trip.itinerary[activeDayIndex].location || 'All';
                             if (loc === 'All') return true;
                             if (loc === 'Houseboat') return h.location === 'Srinagar' && h.category === HotelCategory.HOUSEBOAT;
                             return h.location === loc;
                           })
                           .map(h => (
                             <option key={h.id} value={h.id}>{h.name}</option>
