                <h3 className="text-xs font-black uppercase tracking-widest text-blue-600 flex items-center gap-2">
                   <Crown size={18} /> Tier Management
                </h3>
              </div>

              {itineraryLocations.map(location => {
                const selection = trip.hotelTiers?.find(t => t.location === location) || { signatureHotelId: '', eliteHotelId: '', primeHotelId: '' };
                const isActive = location === activeLocation || (activeLocation === 'Houseboat' && location === 'Srinagar');

                return (
                  <div key={location} className={`space-y-4 pt-4 border-t border-slate-100 first:border-0 first:pt-0 transition-all ${isActive ? 'bg-blue-50/50 -mx-4 px-4 py-4 rounded-xl' : ''}`}>
                    <p className="text-[10px] font-black uppercase text-slate-900 tracking-widest bg-blue-50 px-3 py-1 rounded-full w-fit">{location}</p>
                    <div className="space-y-3">
                       <div className="space-y-1">
                          <label className="text-[9px] font-black uppercase text-slate-400 flex items-center gap-1"><Award size={10}/> Signature</label>
                          <select 
                            value={selection.signatureHotelId} 
                            onChange={(e) => updateTierSelection(location, 'signature', e.target.value)} 
                            className="w-full p-2.5 bg-slate-50 border border-slate-200 rounded-xl text-[10px] font-bold outline-none"
                          >
                            <option value="">Select Signature...</option>
                            {masterHotels
                              .filter(h => h.location === location || (location === 'Srinagar' && h.location === 'Srinagar'))
                              .map(h => <option key={h.id} value={h.id}>{h.name}</option>)
                            }
                          </select>
                       </div>
                       <div className="space-y-1">
                          <label className="text-[9px] font-black uppercase text-blue-600 flex items-center gap-1"><Trophy size={10}/> Elite</label>
                          <select 
                            value={selection.eliteHotelId} 
                            onChange={(e) => updateTierSelection(location, 'elite', e.target.value)} 
                            className="w-full p-2.5 bg-blue-50 border border-blue-200 rounded-xl text-[10px] font-black outline-none"
                          >
                            <option value="">Select Elite...</option>
                            {masterHotels
                              .filter(h => h.location === location || (location === 'Srinagar' && h.location === 'Srinagar'))
                              .map(h => <option key={h.id} value={h.id}>{h.name}</option>)
                            }
                          </select>
                       </div>
                       <div className="space-y-1">
                          <label className="text-[9px] font-black uppercase text-amber-600 flex items-center gap-1"><Crown size={10}/> Prime</label>
                          <select 
                            value={selection.primeHotelId} 
                            onChange={(e) => updateTierSelection(location, 'prime', e.target.value)} 
                            className="w-full p-2.5 bg-amber-50 border border-amber-200 rounded-xl text-[10px] font-bold outline-none"
                          >
                            <option value="">Select Prime...</option>
                            {masterHotels
                              .filter(h => h.location === location || (location === 'Srinagar' && h.location === 'Srinagar'))
                              .map(h => <option key={h.id} value={h.id}>{h.name}</option>)
                            }
                          </select>
                       </div>
                    </div>
                  </div>
                );
              })}

              <div className="pt-6 border-t border-slate-100 space-y-6">
                 <div className="flex items-center justify-between">
                    <p className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Pricing Control</p>
                    <button 
                      onClick={autoCalculatePricing}
                      className="text-[9px] font-black uppercase text-blue-600 flex items-center gap-1 hover:underline"
                    >
                       <RefreshCcw size={10}/> Auto-Calculate All
                    </button>
                 </div>

                 <div className="space-y-4">
                    <div className="space-y-2">
                       <div className="flex justify-between items-center px-1">
                          <label className="text-[9px] font-black uppercase text-slate-400">Signature</label>
                          <span className="text-[8px] font-bold text-slate-300">Sug: ₹{tieredCosts.suggested.signature.toLocaleString()}</span>
                       </div>
                       <input 
                         type="number" 
                         placeholder={`Sug: ₹${tieredCosts.suggested.signature}`}
                         value={trip.tierPrices?.signature || ''} 
                         onChange={(e) => updateTierPrice('signature', e.target.value)} 
                         className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl text-xs font-bold outline-none focus:ring-2 focus:ring-blue-100" 
                       />
                    </div>

                    <div className="space-y-2">
                       <div className="flex justify-between items-center px-1">
                          <label className="text-[9px] font-black uppercase text-blue-600">Elite (Recommended)</label>
                          <span className="text-[8px] font-black text-blue-300">Sug: ₹{tieredCosts.suggested.elite.toLocaleString()}</span>
                       </div>
                       <input 
                         type="number" 
                         placeholder={`Sug: ₹${tieredCosts.suggested.elite}`}
                         value={trip.tierPrices?.elite || ''} 
                         onChange={(e) => updateTierPrice('elite', e.target.value)} 
                         className="w-full p-3 bg-blue-50 border border-blue-200 rounded-xl text-xs font-black outline-none focus:ring-2 focus:ring-blue-300" 
                       />
                    </div>

                    <div className="space-y-2">
                       <div className="flex justify-between items-center px-1">
                          <label className="text-[9px] font-black uppercase text-amber-600">Prime</label>
                          <span className="text-[8px] font-bold text-amber-300">Sug: ₹{tieredCosts.suggested.prime.toLocaleString()}</span>
                       </div>
                       <input 
                         type="number" 
                         placeholder={`Sug: ₹${tieredCosts.suggested.prime}`}
                         value={trip.tierPrices?.prime || ''} 
                         onChange={(e) => updateTierPrice('prime', e.target.value)} 
                         className="w-full p-3 bg-amber-50 border border-amber-200 rounded-xl text-xs font-bold outline-none focus:ring-2 focus:ring-amber-200" 
                       />
                    </div>
                 </div>

                 <div className="flex items-center gap-2 p-3 bg-slate-50 rounded-xl border border-slate-100">
                    <Percent size={14} className="text-slate-400" />
                    <span className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Global Margin</span>
                    <input 
                      type="number" 
                      value={trip.marginPercentage}
                      onChange={(e) => setTrip({...trip, marginPercentage: parseInt(e.target.value) || 0})}
                      className="w-12 bg-transparent text-right font-black text-blue-600 outline-none"
                    />
                    <span className="text-[10px] font-black text-slate-400">%</span>
                 </div>
              </div>
           </div>

           {/* Premium Add-ons Section */}
           <div className="bg-slate-900 border border-slate-800 rounded-[32px] p-8 shadow-2xl space-y-8">
              <div className="flex items-center justify-between">
                <h3 className="text-xs font-black uppercase tracking-widest text-slate-400 flex items-center gap-2">
                   <Sparkles size={16} className="text-blue-400" /> Premium Experiences
                </h3>
              </div>
              <div className="space-y-3">
                 {masterAddOns.map(ao => {
                   const isSelected = (trip.addOnIds || []).includes(ao.id);
                   return (
                     <button 
                       key={ao.id}
                       onClick={() => {
                         const updated = isSelected ? trip.addOnIds.filter(id => id !== ao.id) : [...trip.addOnIds, ao.id];
                         setTrip({...trip, addOnIds: updated});
                       }}
                       className={`w-full text-left p-5 rounded-3xl border transition-all flex flex-col gap-1 ${
                         isSelected ? 'bg-blue-600 border-blue-600 text-white shadow-lg' : 'bg-slate-800 border-slate-700 text-slate-400 hover:bg-slate-700'
                       }`}
                     >
                        <div className="flex items-center justify-between mb-1">
                           <span className={`text-xs font-black ${isSelected ? 'text-white' : 'text-slate-200'}`}>{ao.name}</span>
                           {isSelected && <Check size={14} className="text-white" />}
                        </div>
                        <div className="flex justify-between items-center">
                           <span className={`text-[9px] font-bold uppercase tracking-widest ${isSelected ? 'text-blue-100' : 'text-slate-500'}`}>{ao.isPerPax ? 'Per Guest' : 'Flat'}</span>
                           <span className={`text-sm font-black ${isSelected ? 'text-white' : 'text-blue-400'}`}>₹{ao.cost.toLocaleString()}</span>
                        </div>
                     </button>
                   );
                 })}
              </div>
           </div>

           {/* Terms Sidebar */}
           <div className="space-y-6 pb-10">
              <div className="bg-white border border-slate-200 rounded-[32px] p-8 shadow-sm space-y-6">
                 <h3 className="text-xs font-black uppercase tracking-widest text-emerald-600 flex items-center gap-2"><ShieldCheck size={16} /> Trip Inclusions</h3>
                 <div className="space-y-2">
                    {(trip.inclusions || []).map((inc, i) => (
                       <div key={i} className="flex items-center gap-2 group">
                          <div className="flex-1 text-[10px] font-bold text-slate-600 bg-emerald-50 p-3 rounded-xl line-clamp-2">{inc}</div>
                          <button onClick={() => removeInclusion(i)} className="text-slate-300 hover:text-rose-500"><Trash2 size={14}/></button>
                       </div>
                    ))}
                    <div className="flex gap-2 pt-2">
                       <input type="text" placeholder="Add..." value={newInclusion} onChange={(e) => setNewInclusion(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && addInclusion()} className="flex-1 p-2 bg-slate-50 border border-slate-100 rounded-lg text-[10px] font-bold outline-none" />
                       <button onClick={addInclusion} className="bg-emerald-600 text-white p-2 rounded-lg transition-all active:scale-90"><Plus size={14}/></button>
                    </div>
                 </div>
              </div>

              <div className="bg-white border border-slate-200 rounded-[32px] p-8 shadow-sm space-y-6">
                 <h3 className="text-xs font-black uppercase tracking-widest text-rose-500 flex items-center gap-2"><XCircle size={16} /> Trip Exclusions</h3>
                 <div className="space-y-2">
                    {(trip.exclusions || []).map((exc, i) => (
                       <div key={i} className="flex items-center gap-2 group">
                          <div className="flex-1 text-[10px] font-bold text-slate-600 bg-rose-50 p-3 rounded-xl line-clamp-2">{exc}</div>
                          <button onClick={() => removeExclusion(i)} className="text-slate-300 hover:text-rose-500"><Trash2 size={14}/></button>
                       </div>
                    ))}
                    <div className="flex gap-2 pt-2">
                       <input type="text" placeholder="Add..." value={newExclusion} onChange={(e) => setNewExclusion(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && addExclusion()} className="flex-1 p-2 bg-slate-50 border border-slate-100 rounded-lg text-[10px] font-bold outline-none" />
                       <button onClick={addExclusion} className="bg-rose-500 text-white p-2 rounded-lg transition-all active:scale-90"><Plus size={14}/></button>
                    </div>
                 </div>
              </div>
           </div>
        </div>
      </div>
    </div>
  );
};

export default TripBuilder;

