                            className="p-1.5 bg-emerald-500 text-white rounded-lg shadow-lg hover:bg-emerald-600 active:scale-90 transition-all border-2 border-white"
                          >
                           <PlusCircle size={14} />
                         </button>
                         <button 
                            onClick={(e) => cloneDay(idx, e)}
