                   <div className="relative group">
                     <input 
                       type="text" 
                       value={trip.itinerary[activeDayIndex].title}
                       onChange={(e) => updateDay(activeDayIndex, { title: e.target.value })}
                       className="w-full px-8 py-6 bg-blue-50/30 border-2 border-blue-100 rounded-3xl text-2xl font-black text-slate-900 focus:bg-white focus:ring-8 focus:ring-blue-50 transition-all outline-none shadow-sm"
                       placeholder="Enter day title..."
                     />
