  Send
} from 'lucide-react';
import { Lead, LeadStage, LeadScore, CommunicationLog, FollowUp, Trip } from '../types';
import { MOCK_LEADS, MOCK_TRIPS } from '../constants';
import { suggestFollowUp, draftWhatsAppMessage } from '../services/geminiService';

const LeadProfile: React.FC = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const [lead, setLead] = useState<Lead | null>(null);
  const [activeTab, setActiveTab] = useState<'overview' | 'trips' | 'history' | 'followups'>('overview');
  const [newLog, setNewLog] = useState('');
  const [isAiScheduling, setIsAiScheduling] = useState(false);

  // WhatsApp Draft State
  const [isDraftingWs, setIsDraftingWs] = useState(false);
  const [wsDraft, setWsDraft] = useState('');
  const [showWsModal, setShowWsModal] = useState(false);

  useEffect(() => {
    const savedLeads = localStorage.getItem('et_leads');
    const allLeads = savedLeads ? JSON.parse(savedLeads) : MOCK_LEADS;
    const found = allLeads.find((l: Lead) => l.id === id);
    if (found) setLead(found);
  }, [id]);

  const updateLeadInStorage = (updatedLead: Lead) => {
    setLead(updatedLead);
    const savedLeads = localStorage.getItem('et_leads');
    const allLeads = savedLeads ? JSON.parse(savedLeads) : [...MOCK_LEADS];
    const index = allLeads.findIndex((l: Lead) => l.id === updatedLead.id);
    if (index > -1) {
      allLeads[index] = updatedLead;
    } else {
      allLeads.push(updatedLead);
    }
    localStorage.setItem('et_leads', JSON.stringify(allLeads));
  };

  const addCommunicationLog = (type: CommunicationLog['type'] = 'Note', content: string = newLog) => {
    if (!lead || !content.trim()) return;
    const log: CommunicationLog = {
      id: `c-${Date.now()}`,
      type,
      timestamp: new Date().toISOString(),
      content,
      author: 'Adil Bakshi'
    };
    const updatedLead = { ...lead, communicationLogs: [log, ...lead.communicationLogs] };
    updateLeadInStorage(updatedLead);
    if (type === 'Note') setNewLog('');
  };

  const handleAutoSchedule = async () => {
    if (!lead || isAiScheduling) return;
    setIsAiScheduling(true);

    try {
      const suggestion = await suggestFollowUp(lead.name, lead.stage, lead.notes, lead.interest);

      const futureDate = new Date();
      futureDate.setDate(futureDate.getDate() + suggestion.daysFromNow);

      const newFollowUp: FollowUp = {
        id: `f-${Date.now()}`,
        date: futureDate.toISOString().split('T')[0],
        status: 'Pending',
        note: suggestion.task
      };

      const updatedLead = {
        ...lead,
        followUps: [...lead.followUps, newFollowUp]
      };

      updateLeadInStorage(updatedLead);
    } catch (error) {
      console.error("Failed to auto-schedule:", error);
    } finally {
      setIsAiScheduling(false);
    }
  };

  const handleDraftWhatsApp = async () => {
    if (!lead || isDraftingWs) return;
    setIsDraftingWs(true);
    try {
      const draft = await draftWhatsAppMessage(
        lead.name, 
        lead.interest, 
        lead.communicationLogs[0]?.content || lead.notes
      );
      setWsDraft(draft);
      setShowWsModal(true);
    } catch (error) {
      console.error("Drafting failed:", error);
    } finally {
      setIsDraftingWs(false);
    }
  };

  const sendWhatsApp = () => {
    if (!lead || !wsDraft) return;
    const cleanPhone = lead.phone.replace(/\D/g, '');
    const encodedText = encodeURIComponent(wsDraft);
    window.open(`https://wa.me/${cleanPhone}?text=${encodedText}`, '_blank');
    addCommunicationLog('WhatsApp', `AI Sent: ${wsDraft}`);
    setShowWsModal(false);
  };

  const completeFollowUp = (fuId: string) => {
    if (!lead) return;
    const updatedFollowUps = lead.followUps.map(fu => 
      fu.id === fuId ? { ...fu, status: 'Completed' as const } : fu
    );
    updateLeadInStorage({ ...lead, followUps: updatedFollowUps });
  };

  if (!lead) return <div className="p-20 text-center font-black text-slate-300 uppercase tracking-widest">LOADING LEAD...</div>;

  const leadTrips = MOCK_TRIPS.filter(t => t.leadId === lead.id);
  const pendingFollowUps = lead.followUps.filter(f => f.status === 'Pending');

  return (
    <div className="space-y-8 pb-20">
      {/* Header Profile Info */}
      <div className="bg-white p-10 rounded-[48px] border border-slate-100 shadow-sm flex flex-col md:flex-row gap-10">
         <div className="flex-1 space-y-6">
            <div className="flex items-center gap-5">
               <button onClick={() => navigate('/pipeline')} className="p-3 bg-slate-50 hover:bg-slate-100 rounded-2xl text-slate-400"><ArrowLeft size={20}/></button>
               <div>
                  <h1 className="text-4xl font-black text-slate-900 tracking-tighter">{lead.name}</h1>
                  <div className="flex items-center gap-4 mt-1">
                     <span className={`text-[10px] font-black uppercase tracking-widest px-3 py-1 rounded-full ${lead.score === LeadScore.HOT ? 'bg-rose-100 text-rose-600' : 'bg-blue-100 text-blue-600'}`}>
                        {lead.score} Priority
                     </span>
                     <span className="w-1 h-1 bg-slate-200 rounded-full" />
                     <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">Captured via {lead.source}</span>
                  </div>
               </div>
            </div>

            <div className="grid grid-cols-2 md:grid-cols-4 gap-6 pt-4">
