  Hotel as HotelIcon, 
  Car, 
  Sparkles,
  Settings,
  LogOut,
  Mountain,
  FileText,
  Compass,
  Bell,
  X,
  AlertTriangle,
  Clock,
  ChevronRight
} from 'lucide-react';
import { Lead, LeadStage } from '../types';
import { MOCK_LEADS } from '../constants';

const SidebarItem = ({ icon: Icon, label, path, active }: { icon: any, label: string, path: string, active: boolean }) => (
  <Link 
    to={path} 
    className={`flex items-center gap-3 px-4 py-3 rounded-2xl transition-all ${
      active ? 'bg-blue-600 text-white shadow-lg shadow-blue-900/20' : 'text-slate-400 hover:bg-slate-800 hover:text-white'
    }`}
  >
    <Icon size={18} />
    <span className="font-bold text-[13px]">{label}</span>
  </Link>
);

const SidebarHeader = ({ label }: { label: string }) => (
  <p className="text-slate-600 text-[10px] font-black uppercase tracking-[0.2em] mb-3 mt-6 ml-4">{label}</p>
);

const Layout: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const location = useLocation();
  const [showNotifications, setShowNotifications] = useState(false);
  const [alerts, setAlerts] = useState<{ id: string, title: string, desc: string, type: 'danger' | 'warning' | 'info', leadId: string }[]>([]);

  useEffect(() => {
    // Lead Rules Engine Simulation
    const savedLeads = localStorage.getItem('et_leads');
    const leads: Lead[] = savedLeads ? JSON.parse(savedLeads) : MOCK_LEADS;
    const now = new Date();
    const newAlerts: any[] = [];

    leads.forEach(lead => {
      const createdAt = new Date(lead.createdAt);
      const lastUpdate = lead.updatedAt ? new Date(lead.updatedAt) : createdAt;
      const hoursSinceInactivity = (now.getTime() - lastUpdate.getTime()) / (1000 * 60 * 60);

      // Rule: New Lead + 24hrs Inactivity
      if (lead.stage === LeadStage.NEW && hoursSinceInactivity > 24) {
        newAlerts.push({
          id: `alert-new-${lead.id}`,
          title: 'Cold Lead Alert',
          desc: `${lead.name} has been in "New" for 24h+ without action.`,
          type: 'danger',
          leadId: lead.id
        });
      }

      // Rule: Proposal Sent + 48hrs No reply
      if (lead.stage === LeadStage.PROPOSAL_SENT && hoursSinceInactivity > 48) {
        newAlerts.push({
          id: `alert-prop-${lead.id}`,
          title: 'Proposal Follow-up',
          desc: `48h since proposal sent to ${lead.name}. Needs follow-up.`,
          type: 'warning',
          leadId: lead.id
        });
      }

      // Pending Follow-ups for Today
      const todayStr = now.toISOString().split('T')[0];
      lead.followUps.filter(f => f.status === 'Pending' && f.date <= todayStr).forEach(f => {
        newAlerts.push({
          id: `alert-fu-${f.id}`,
          title: 'Due Follow-up',
          desc: `${f.note} for ${lead.name}`,
          type: 'info',
          leadId: lead.id
        });
      });
    });

    setAlerts(newAlerts);
  }, [location.pathname]);

  return (
    <div className="flex h-screen overflow-hidden bg-[#f8fafc]">
      {/* Sidebar */}
      <aside className="w-64 bg-slate-950 flex flex-col p-6 border-r border-slate-900">
        <div className="flex items-center gap-3 mb-4">
          <div className="bg-blue-600 p-2.5 rounded-xl shadow-xl shadow-blue-900/40">
            <Mountain className="text-white" size={24} />
          </div>
          <div>
            <h1 className="text-white font-black text-lg tracking-tighter leading-none">ESCAPE</h1>
            <p className="text-blue-500 text-[9px] font-black uppercase tracking-[0.2em]">THEORY KASHMIR</p>
          </div>
        </div>

        <nav className="flex-1 space-y-1 overflow-y-auto custom-scrollbar pr-2">
          <SidebarHeader label="Revenue & Sales" />
          <SidebarItem icon={LayoutDashboard} label="Dashboard" path="/" active={location.pathname === '/'} />
          <SidebarItem icon={Trello} label="Sales Pipeline" path="/pipeline" active={location.pathname === '/pipeline'} />
          <SidebarItem icon={Users} label="Lead Manager" path="/leads" active={location.pathname.startsWith('/leads') && location.pathname !== '/leads/new'} />

          <SidebarHeader label="Operations" />
          <SidebarItem icon={Map} label="All Itineraries" path="/trips" active={location.pathname === '/trips' || (location.pathname.startsWith('/trips/') && !location.pathname.includes('print'))} />
          <SidebarItem icon={FileText} label="Templates" path="/templates" active={location.pathname.startsWith('/templates')} />

          <SidebarHeader label="Master Database" />
          <SidebarItem icon={HotelIcon} label="Hotels" path="/hotels" active={location.pathname === '/hotels'} />
          <SidebarItem icon={Car} label="Vehicle Fleet" path="/vehicles" active={location.pathname === '/vehicles'} />
          <SidebarItem icon={Compass} label="Activities" path="/activities" active={location.pathname === '/activities'} />
          <SidebarItem icon={Sparkles} label="Add-ons" path="/add-ons" active={location.pathname === '/add-ons'} />

          <SidebarHeader label="System" />
          <SidebarItem icon={Settings} label="Settings" path="/settings" active={location.pathname === '/settings'} />
        </nav>

        <div className="mt-auto border-t border-slate-900 pt-6">
          <button className="flex items-center gap-3 px-4 py-3 text-slate-500 hover:text-red-400 transition-colors w-full group">
            <LogOut size={20} className="group-hover:translate-x-1 transition-transform" />
            <span className="font-bold text-sm">Sign Out</span>
          </button>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 flex flex-col overflow-hidden relative">
        <header className="h-20 bg-white border-b border-slate-100 flex items-center justify-between px-10">
          <div className="flex items-center gap-4">
            <h2 className="text-slate-900 font-black text-xl tracking-tight uppercase">
              {location.pathname === '/' ? 'Business Intelligence' : 
               location.pathname.startsWith('/pipeline') ? 'Sales Pipeline' :
               location.pathname.startsWith('/leads') ? 'Client Relationship' :
               location.pathname.startsWith('/trips') ? 'Itinerary Control' :
               'Operational Control'}
            </h2>
          </div>
          <div className="flex items-center gap-6">
            <button 
              onClick={() => setShowNotifications(!showNotifications)}
              className="relative p-3 bg-slate-50 hover:bg-slate-100 rounded-2xl transition-all group"
            >
              <Bell size={20} className="text-slate-400 group-hover:text-blue-600" />
              {alerts.length > 0 && (
                <span className="absolute top-2 right-2 w-4 h-4 bg-rose-600 border-2 border-white rounded-full flex items-center justify-center text-[8px] text-white font-black">
                  {alerts.length}
                </span>
              )}
            </button>

            <div className="text-right">
              <p className="text-sm font-black text-slate-900 leading-none">Adil Bakshi</p>
              <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-1">Super Admin</p>
            </div>
            <div className="w-12 h-12 rounded-2xl bg-slate-100 border-4 border-white shadow-sm overflow-hidden">
               <img src="https://picsum.photos/seed/adil/100/100" alt="Admin" />
            </div>
          </div>
        </header>

        {/* Notifications Sidebar Panel */}
        {showNotifications && (
          <div className="absolute top-24 right-10 w-96 bg-white rounded-[40px] shadow-2xl border border-slate-100 z-[110] flex flex-col overflow-hidden animate-in slide-in-from-top-4 duration-300">
             <div className="p-8 border-b border-slate-50 flex items-center justify-between">
                <h3 className="font-black text-slate-900 uppercase tracking-widest text-xs flex items-center gap-2">
                   <Bell size={16} className="text-blue-600" /> Agency Action Center
                </h3>
                <button onClick={() => setShowNotifications(false)} className="text-slate-300 hover:text-slate-900"><X size={20}/></button>
             </div>
             <div className="flex-1 overflow-y-auto p-6 space-y-4 max-h-[60vh]">
                {alerts.length > 0 ? alerts.map(alert => (
                  <Link 
                    key={alert.id}
                    to={`/leads/${alert.leadId}`}
                    onClick={() => setShowNotifications(false)}
                    className="flex items-start gap-4 p-5 bg-slate-50 border border-slate-100 rounded-3xl group hover:bg-white hover:border-blue-200 transition-all shadow-sm"
                  >
                     <div className={`p-2 rounded-xl shrink-0 ${
                       alert.type === 'danger' ? 'bg-rose-100 text-rose-600' :
                       alert.type === 'warning' ? 'bg-amber-100 text-amber-600' :
                       'bg-blue-100 text-blue-600'
                     }`}>
                        <AlertTriangle size={18} />
                     </div>
                     <div className="space-y-1">
                        <p className="text-[10px] font-black uppercase text-slate-400 tracking-widest">{alert.title}</p>
                        <p className="text-xs font-bold text-slate-700 leading-snug">{alert.desc}</p>
                     </div>
                     <ChevronRight size={16} className="text-slate-200 group-hover:text-blue-600 mt-1" />
                  </Link>
                )) : (
                  <div className="py-20 text-center space-y-4 opacity-30">
                    <Clock size={48} className="mx-auto" />
                    <p className="text-[10px] font-black uppercase tracking-widest">No Alerts Pending</p>
                  </div>
                )}
             </div>
             <div className="p-6 bg-slate-50 border-t border-slate-100">
                <button onClick={() => setAlerts([])} className="w-full py-3 text-[10px] font-black uppercase tracking-widest text-slate-400 hover:text-slate-900">Clear All Alerts</button>
             </div>
          </div>
        )}

        <div className="flex-1 overflow-y-auto p-10 bg-[#f8fafc]">
          {children}
        </div>
      </main>
    </div>
  );
};

export default Layout;

import React, { useState, useEffect, useMemo } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { 
  ArrowLeft, 
  Phone, 
  Mail, 
  MessageSquare, 
  Calendar, 
  Plus, 
  Clock, 
  User, 
  TrendingUp, 
  Target,
  FileText,
  Map,
  ChevronRight,
  MoreVertical,
  CheckCircle2,
  AlertCircle,
  Zap,
  Tag,
  Sparkles,
  Loader2,
  X,
  Send,
  History,
  Activity as ActivityIcon
} from 'lucide-react';
import { Lead, LeadStage, LeadScore, CommunicationLog, FollowUp, Trip, LeadActivity } from '../types';
import { MOCK_LEADS, MOCK_TRIPS } from '../constants';
import { suggestFollowUp, draftWhatsAppMessage } from '../services/geminiService';

const LeadProfile: React.FC = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const [lead, setLead] = useState<Lead | null>(null);
  const [activeTab, setActiveTab] = useState<'overview' | 'trips' | 'timeline' | 'followups'>('overview');
  const [newLog, setNewLog] = useState('');
  const [isAiScheduling, setIsAiScheduling] = useState(false);

  // WhatsApp Draft State
  const [isDraftingWs, setIsDraftingWs] = useState(false);
  const [wsDraft, setWsDraft] = useState('');
  const [showWsModal, setShowWsModal] = useState(false);

  useEffect(() => {
    const savedLeads = localStorage.getItem('et_leads');
    const allLeads = savedLeads ? JSON.parse(savedLeads) : MOCK_LEADS;
    const found = allLeads.find((l: Lead) => l.id === id);
    if (found) {
      if (!found.activities) found.activities = [];
      setLead(found);
    }
  }, [id]);

  const recordActivity = (updatedLead: Lead, type: LeadActivity['type'], description: string, meta?: any) => {
    const activity: LeadActivity = {
      id: `act-${Date.now()}`,
      leadId: updatedLead.id,
      type,
      timestamp: new Date().toISOString(),
      description,
      meta
    };
    updatedLead.activities = [activity, ...(updatedLead.activities || [])];
    updatedLead.updatedAt = new Date().toISOString();
    return updatedLead;
  };

  const updateLeadInStorage = (updatedLead: Lead) => {
    setLead(updatedLead);
    const savedLeads = localStorage.getItem('et_leads');
    const allLeads = savedLeads ? JSON.parse(savedLeads) : [...MOCK_LEADS];
    const index = allLeads.findIndex((l: Lead) => l.id === updatedLead.id);
    if (index > -1) {
      allLeads[index] = updatedLead;
    } else {
      allLeads.push(updatedLead);
    }
    localStorage.setItem('et_leads', JSON.stringify(allLeads));
  };

  const handleStageChange = (newStage: LeadStage) => {
    if (!lead) return;
    let updatedLead = { ...lead, stage: newStage };
    updatedLead = recordActivity(updatedLead, 'StatusChange', `Stage changed from ${lead.stage} to ${newStage}`);
    updateLeadInStorage(updatedLead);
  };

  const addCommunicationLog = (type: CommunicationLog['type'] = 'Note', content: string = newLog) => {
    if (!lead || !content.trim()) return;
    const log: CommunicationLog = {
      id: `c-${Date.now()}`,
      type,
      timestamp: new Date().toISOString(),
      content,
      author: 'Adil Bakshi'
    };
    let updatedLead = { ...lead, communicationLogs: [log, ...lead.communicationLogs] };
    updatedLead = recordActivity(updatedLead, 'NoteAdded', `Communication logged: ${type}`, { logId: log.id });
    updateLeadInStorage(updatedLead);
    if (type === 'Note') setNewLog('');
  };

  const handleAutoSchedule = async () => {
    if (!lead || isAiScheduling) return;
    setIsAiScheduling(true);

    try {
      const suggestion = await suggestFollowUp(lead.name, lead.stage, lead.notes, lead.interest);
      const futureDate = new Date();
      futureDate.setDate(futureDate.getDate() + suggestion.daysFromNow);

      const newFollowUp: FollowUp = {
        id: `f-${Date.now()}`,
        date: futureDate.toISOString().split('T')[0],
        status: 'Pending',
        note: suggestion.task
      };

      let updatedLead = {
        ...lead,
        followUps: [...lead.followUps, newFollowUp]
      };
      updatedLead = recordActivity(updatedLead, 'FollowUpCreated', `Scheduled follow-up: ${suggestion.task} for ${newFollowUp.date}`);
      updateLeadInStorage(updatedLead);
    } catch (error) {
      console.error("Failed to auto-schedule:", error);
    } finally {
      setIsAiScheduling(false);
    }
  };

  const handleDraftWhatsApp = async () => {
    if (!lead || isDraftingWs) return;
    setIsDraftingWs(true);
    try {
      const draft = await draftWhatsAppMessage(
        lead.name, 
        lead.interest, 
        lead.communicationLogs[0]?.content || lead.notes
      );
      setWsDraft(draft);
      setShowWsModal(true);
    } catch (error) {
      console.error("Drafting failed:", error);
    } finally {
      setIsDraftingWs(false);
    }
  };

  const sendWhatsApp = () => {
    if (!lead || !wsDraft) return;
    const cleanPhone = lead.phone.replace(/\D/g, '');
    const encodedText = encodeURIComponent(wsDraft);
    window.open(`https://wa.me/${cleanPhone}?text=${encodedText}`, '_blank');
    addCommunicationLog('WhatsApp', `AI Sent: ${wsDraft}`);
    setShowWsModal(false);
  };

  const completeFollowUp = (fuId: string) => {
    if (!lead) return;
    const completedTask = lead.followUps.find(f => f.id === fuId)?.note;
    const updatedFollowUps = lead.followUps.map(fu => 
      fu.id === fuId ? { ...fu, status: 'Completed' as const } : fu
    );
    let updatedLead = { ...lead, followUps: updatedFollowUps };
    updatedLead = recordActivity(updatedLead, 'FollowUpCompleted', `Task completed: ${completedTask}`);
    updateLeadInStorage(updatedLead);
  };

  if (!lead) return <div className="p-20 text-center font-black text-slate-300 uppercase tracking-widest">LOADING LEAD...</div>;

  const leadTrips = MOCK_TRIPS.filter(t => t.leadId === lead.id);
  const pendingFollowUps = lead.followUps.filter(f => f.status === 'Pending');

  return (
    <div className="space-y-8 pb-20">
      {/* Header Profile Info */}
      <div className="bg-white p-10 rounded-[48px] border border-slate-100 shadow-sm flex flex-col md:flex-row gap-10">
         <div className="flex-1 space-y-6">
            <div className="flex items-center gap-5">
               <button onClick={() => navigate('/pipeline')} className="p-3 bg-slate-50 hover:bg-slate-100 rounded-2xl text-slate-400 transition-all active:scale-95"><ArrowLeft size={20}/></button>
               <div>
                  <h1 className="text-4xl font-black text-slate-900 tracking-tighter">{lead.name}</h1>
                  <div className="flex items-center gap-4 mt-1">
                     <span className={`text-[10px] font-black uppercase tracking-widest px-3 py-1 rounded-full ${lead.score === LeadScore.HOT ? 'bg-rose-100 text-rose-600' : 'bg-blue-100 text-blue-600'}`}>
                        {lead.score} Priority
                     </span>
                     <span className="w-1 h-1 bg-slate-200 rounded-full" />
                     <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">Captured via {lead.source}</span>
                  </div>
               </div>
            </div>

            <div className="grid grid-cols-2 md:grid-cols-4 gap-6 pt-4">
               <div className="space-y-1">
                  <p className="text-[9px] font-black uppercase text-slate-400 tracking-widest">Phone</p>
                  <p className="font-bold text-slate-900 flex items-center gap-2 transition-all hover:text-blue-600 cursor-pointer"><Phone size={14} className="text-blue-500"/> {lead.phone}</p>
               </div>
               <div className="space-y-1">
                  <p className="text-[9px] font-black uppercase text-slate-400 tracking-widest">Email</p>
                  <p className="font-bold text-slate-900 flex items-center gap-2 truncate" title={lead.email}><Mail size={14} className="text-blue-500"/> {lead.email}</p>
               </div>
               <div className="space-y-1">
                  <p className="text-[9px] font-black uppercase text-slate-400 tracking-widest">Travel Month</p>
                  <p className="font-bold text-slate-900 flex items-center gap-2"><Calendar size={14} className="text-amber-500"/> {lead.travelMonth}</p>
               </div>
               <div className="space-y-1">
                  <p className="text-[9px] font-black uppercase text-slate-400 tracking-widest">Budget</p>
                  <p className="font-bold text-slate-900 flex items-center gap-2">₹ {lead.budgetRange}</p>
               </div>
            </div>
         </div>

         <div className="w-full md:w-80 bg-slate-950 p-8 rounded-[40px] text-white space-y-6">
            <p className="text-[10px] font-black uppercase tracking-widest text-slate-500">Pipeline Stage</p>
            <div className="flex flex-col gap-4">
               <select 
                 value={lead.stage}
                 onChange={(e) => handleStageChange(e.target.value as LeadStage)}
                 className="w-full bg-slate-900 border border-slate-800 p-4 rounded-2xl font-black text-xs uppercase tracking-widest outline-none appearance-none cursor-pointer hover:border-blue-500/50 transition-all"
               >
                  {Object.values(LeadStage).map(s => <option key={s} value={s}>{s}</option>)}
               </select>
               <div className="p-4 bg-white/5 rounded-2xl border border-white/5 space-y-1">
                  <p className="text-[8px] font-black uppercase text-slate-500 tracking-[0.2em]">Last Action</p>
                  <p className="text-[10px] font-bold text-slate-300">
                    {lead.updatedAt ? new Date(lead.updatedAt).toLocaleString() : 'New Capture'}
                  </p>
               </div>
            </div>
         </div>
      </div>

      <div className="grid grid-cols-12 gap-8">
         {/* Left: Feed and Management */}
         <div className="col-span-12 lg:col-span-8 space-y-8">
            <div className="flex gap-4 p-1.5 bg-white border border-slate-100 rounded-3xl w-fit">
               {['overview', 'trips', 'timeline', 'followups'].map((tab) => (
                  <button 
                    key={tab}
                    onClick={() => setActiveTab(tab as any)}
                    className={`px-6 py-3 rounded-2xl font-black text-[10px] uppercase tracking-widest transition-all ${
                      activeTab === tab ? 'bg-slate-900 text-white shadow-xl' : 'text-slate-400 hover:text-slate-900'
                    }`}
                  >
                    {tab}
                  </button>
               ))}
            </div>

            {activeTab === 'overview' && (
              <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-300">
                 <div className="bg-white p-8 rounded-[40px] border border-slate-100 shadow-sm space-y-6">
                    <div className="flex items-center justify-between">
                       <h3 className="text-xs font-black uppercase tracking-widest text-slate-900">Add Communication Log</h3>
                       <button 
                         onClick={handleDraftWhatsApp}
                         disabled={isDraftingWs}
                         className="flex items-center gap-2 text-[10px] font-black uppercase tracking-widest text-emerald-600 hover:text-emerald-700 disabled:opacity-50 transition-all"
                       >
                          {isDraftingWs ? <Loader2 size={14} className="animate-spin" /> : <Sparkles size={14} />}
                          AI WhatsApp Draft
                       </button>
                    </div>
                    <div className="relative">
                       <textarea 
                         rows={4}
                         placeholder="Add a call summary, WhatsApp update, or internal note..."
                         className="w-full p-6 bg-slate-50 border border-slate-100 rounded-[32px] outline-none font-bold text-slate-900 focus:bg-white focus:ring-4 focus:ring-blue-50 transition-all shadow-inner resize-none"
                         value={newLog}
                         onChange={(e) => setNewLog(e.target.value)}
                       />
                       <button 
                         onClick={() => addCommunicationLog('Note')}
                         className="absolute bottom-4 right-4 bg-slate-900 text-white p-4 rounded-2xl shadow-xl hover:bg-blue-600 transition-all active:scale-90"
                       >
                          <Plus size={20}/>
                       </button>
                    </div>
                 </div>

                 <div className="space-y-6">
                    <h3 className="text-xs font-black uppercase tracking-widest text-slate-400 ml-4">Recent Interactions</h3>
                    {lead.communicationLogs.map((log) => (
                       <div key={log.id} className="bg-white p-8 rounded-[40px] border border-slate-100 shadow-sm flex gap-6 group relative animate-in fade-in slide-in-from-left-2 transition-all">
                          <div className={`p-4 rounded-2xl shrink-0 h-fit ${
                            log.type === 'WhatsApp' ? 'bg-emerald-50 text-emerald-600' : 
                            log.type === 'Call' ? 'bg-blue-50 text-blue-600' : 'bg-slate-50 text-slate-500'
                          }`}>
                             {log.type === 'WhatsApp' ? <MessageSquare size={20}/> : <Clock size={20}/>}
                          </div>
                          <div className="flex-1 space-y-2">
                             <div className="flex items-center justify-between">
                                <div className="flex items-center gap-2">
                                   <span className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Logged by {log.author}</span>
                                   <span className="px-2 py-0.5 bg-slate-100 rounded-full text-[8px] font-black uppercase text-slate-400 tracking-tighter">{log.type}</span>
                                </div>
                                <span className="text-[10px] font-bold text-slate-300">{new Date(log.timestamp).toLocaleDateString()}</span>
                             </div>
                             <p className="text-slate-800 font-bold leading-relaxed">{log.content}</p>
                          </div>
                       </div>
                    ))}
                 </div>
              </div>
            )}

            {activeTab === 'timeline' && (
              <div className="space-y-12 py-10 animate-in fade-in slide-in-from-bottom-4 duration-300">
                <div className="relative border-l-2 border-slate-100 ml-10 space-y-10 pb-10">
                  {(lead.activities || []).length > 0 ? (lead.activities || []).map((act, i) => (
                    <div key={act.id} className="relative pl-12 group">
                      {/* Timeline Dot */}
                      <div className={`absolute -left-[11px] top-0 w-5 h-5 rounded-full border-4 border-white shadow-sm transition-all group-hover:scale-125 ${
                        act.type === 'StatusChange' ? 'bg-blue-600' :
                        act.type === 'BookingConfirmed' ? 'bg-emerald-600' :
                        act.type === 'ProposalSent' ? 'bg-indigo-600' :
                        'bg-slate-300'
                      }`} />

                      <div className="bg-white p-6 rounded-[32px] border border-slate-50 shadow-sm transition-all group-hover:shadow-lg group-hover:border-blue-100">
                        <div className="flex items-center justify-between mb-2">
                          <div className="flex items-center gap-3">
                            <span className="text-[9px] font-black uppercase tracking-widest px-2 py-0.5 bg-slate-50 rounded text-slate-400">
                              {act.type.replace(/([A-Z])/g, ' $1').trim()}
                            </span>
                            <span className="text-[10px] font-bold text-slate-300">
                              {new Date(act.timestamp).toLocaleString([], { dateStyle: 'short', timeStyle: 'short' })}
                            </span>
                          </div>
                        </div>
                        <p className="text-slate-800 font-bold">{act.description}</p>
                        {act.meta?.logId && <p className="text-[10px] text-slate-400 mt-2 italic font-medium">Ref: Log #{act.meta.logId.slice(-6)}</p>}
                      </div>
                    </div>
                  )) : (
                    <div className="pl-12 space-y-4 opacity-30">
                       <History size={48} />
                       <p className="text-[10px] font-black uppercase tracking-widest">Timeline Start: Registration Captured</p>
                    </div>
                  )}
                  {/* Initial Capture Event */}
                  <div className="relative pl-12">
                      <div className="absolute -left-[11px] top-0 w-5 h-5 rounded-full border-4 border-white shadow-sm bg-slate-200" />
                      <div className="text-[10px] font-black uppercase text-slate-300 tracking-widest pt-1">
                        Lead Created • {new Date(lead.createdAt).toLocaleDateString()}
                      </div>
                  </div>
                </div>
              </div>
            )}

            {activeTab === 'trips' && (
               <div className="space-y-6 animate-in fade-in duration-300">
                  <div className="flex items-center justify-between">
                     <h3 className="text-xs font-black uppercase tracking-widest text-slate-400">Linked Proposal & Trips</h3>
                     <button onClick={() => navigate(`/trips/new?leadId=${lead.id}`)} className="text-[10px] font-black uppercase tracking-widest text-blue-600 hover:text-blue-700 transition-all flex items-center gap-2 group">
                        <Plus size={16} className="group-hover:rotate-90 transition-transform" /> Build New Proposal
                     </button>
                  </div>
                  {leadTrips.map(trip => (
                     <div key={trip.id} onClick={() => navigate(`/trips/${trip.id}`)} className="bg-white p-8 rounded-[40px] border border-slate-100 shadow-sm flex items-center justify-between group hover:border-blue-200 transition-all cursor-pointer">
                        <div className="flex items-center gap-6">
                           <div className="bg-blue-50 p-4 rounded-2xl text-blue-600 group-hover:bg-blue-600 group-hover:text-white transition-all">
                              <Map size={24}/>
                           </div>
                           <div>
                              <h4 className="text-lg font-black text-slate-900">{trip.tripName}</h4>
                              <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{trip.tripType} • {trip.startDate} Start</p>
                           </div>
                        </div>
                        <div className="flex items-center gap-8">
                           <div className="text-right">
                              <p className="text-[9px] font-black uppercase text-slate-300">Status</p>
                              <p className="text-[10px] font-black uppercase text-emerald-600">{trip.status}</p>
                           </div>
                           <ChevronRight size={20} className="text-slate-200 group-hover:text-blue-600 group-hover:translate-x-1 transition-all" />
                        </div>
                     </div>
                  ))}
                  {leadTrips.length === 0 && (
                     <div className="bg-white p-20 rounded-[48px] border-2 border-dashed border-slate-100 flex flex-col items-center justify-center text-slate-300 text-center gap-4">
                        <FileText size={64} className="opacity-10"/>
                        <p className="text-sm font-black uppercase tracking-widest">No Active Itineraries</p>
                        <button onClick={() => navigate(`/trips/new?leadId=${lead.id}`)} className="bg-slate-900 text-white px-8 py-3 rounded-2xl text-[10px] font-black uppercase tracking-widest shadow-xl active:scale-95 transition-all">Start Your First Build</button>
                     </div>
                  )}
               </div>
            )}

            {activeTab === 'followups' && (
              <div className="animate-in fade-in slide-in-from-bottom-4 duration-300 space-y-6">
                 <div className="bg-white p-8 rounded-[40px] border border-slate-100 shadow-sm space-y-6">
                    <h3 className="text-xs font-black uppercase tracking-widest text-slate-900">Manage Follow-ups</h3>
                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                       {lead.followUps.map(fu => (
                         <div key={fu.id} className={`p-6 rounded-[32px] border transition-all ${
                            fu.status === 'Completed' ? 'bg-slate-50 border-slate-100 grayscale opacity-60' : 'bg-white border-slate-100 shadow-sm'
                         }`}>
                            <div className="flex items-center justify-between mb-3">
                               <span className={`text-[9px] font-black uppercase tracking-widest px-3 py-1 rounded-full ${
                                  fu.status === 'Completed' ? 'bg-slate-200 text-slate-500' : 'bg-rose-100 text-rose-600'
                               }`}>
                                  {fu.status}
                               </span>
                               {fu.status === 'Pending' && (
                                  <button onClick={() => completeFollowUp(fu.id)} className="p-2 hover:bg-emerald-50 text-slate-200 hover:text-emerald-500 transition-all rounded-xl">
                                     <CheckCircle2 size={20}/>
                                  </button>
                               )}
