} from 'lucide-react';

const Pipeline: React.FC = () => {
  const navigate = useNavigate();
  const [leads, setLeads] = useState<Lead[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const stages = Object.values(LeadStage);

  useEffect(() => {
    const saved = localStorage.getItem('et_leads');
    setLeads(saved ? JSON.parse(saved) : MOCK_LEADS);
  }, []);

  const filteredLeads = useMemo(() => {
    return leads.filter(l => 
      l.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
      l.phone.includes(searchTerm)
    );
  }, [leads, searchTerm]);

  const getLeadsByStage = (stage: LeadStage) => filteredLeads.filter(l => l.stage === stage);

  const ScoreBadge = ({ score }: { score: LeadScore }) => {
    if (score === LeadScore.HOT) return <div className="p-2 bg-rose-100 text-rose-600 rounded-xl shadow-sm"><Flame size={14} /></div>;
    if (score === LeadScore.WARM) return <div className="p-2 bg-orange-100 text-orange-600 rounded-xl shadow-sm"><TrendingUp size={14} /></div>;
    return <div className="p-2 bg-blue-100 text-blue-600 rounded-xl shadow-sm"><Snowflake size={14} /></div>;
  };

  const PipelineCard = ({ lead }: { lead: Lead }) => {
    const now = new Date();
    const lastUpdate = lead.updatedAt ? new Date(lead.updatedAt) : new Date(lead.createdAt);
    const hoursInactivity = (now.getTime() - lastUpdate.getTime()) / (1000 * 60 * 60);

    // Rules Engine Integration in UI
    const isSLAAlert = (lead.stage === LeadStage.NEW && hoursInactivity > 24) || 
                      (lead.stage === LeadStage.PROPOSAL_SENT && hoursInactivity > 48);

    return (
      <div 
        onClick={() => navigate(`/leads/${lead.id}`)}
        className={`bg-white p-6 rounded-3xl border group transition-all cursor-pointer relative overflow-hidden ${
          isSLAAlert ? 'border-rose-300 shadow-rose-100 shadow-xl ring-2 ring-rose-50' : 'border-slate-100 hover:border-blue-300 hover:shadow-2xl shadow-sm'
        }`}
      >
        {isSLAAlert && (
           <div className="absolute top-0 right-0 bg-rose-600 text-white text-[8px] font-black uppercase px-3 py-1 rounded-bl-xl tracking-[0.2em] animate-pulse flex items-center gap-1">
              <AlertTriangle size={8} /> SLA VIOLATION
