        <div className="flex items-start justify-between mb-4">
          <ScoreBadge score={lead.score} />
          <div className="text-[9px] font-black uppercase tracking-widest text-slate-300 group-hover:text-blue-600 transition-colors">
            #{lead.id.slice(-4)}
