  const [showNotifications, setShowNotifications] = useState(false);
  const [alerts, setAlerts] = useState<{ id: string, title: string, desc: string, type: 'danger' | 'warning' | 'info' | 'success', leadId: string }[]>([]);

  // Simulation: Background Automation Job (Every 30 seconds for demo, real would be 15m)
  useEffect(() => {
    const runAutomationJob = async () => {
      const savedLeads = localStorage.getItem('et_leads');
      const leads: Lead[] = savedLeads ? JSON.parse(savedLeads) : MOCK_LEADS;
      const now = new Date();

      const savedLogs = localStorage.getItem('et_message_logs');
      const allLogs = savedLogs ? JSON.parse(savedLogs) : [];

      for (const lead of leads) {
        const lastUpdate = lead.updatedAt ? new Date(lead.updatedAt) : new Date(lead.createdAt);
        const hoursInactivity = (now.getTime() - lastUpdate.getTime()) / (1000 * 60 * 60);

        // Automation Rule: New Lead + 24h Inactivity -> Send Welcome WhatsApp
        if (lead.stage === LeadStage.NEW && hoursInactivity > 24) {
          const hasAlreadySentWelcome = allLogs.some((l: any) => l.leadId === lead.id && l.templateId === 'welcome-wa');
          if (!hasAlreadySentWelcome && lead.whatsappOptIn) {
            const template = DEFAULT_TEMPLATES.find(t => t.id === 'welcome-wa');
            if (template) {
              const log = await sendSimulatedMessage(lead, template);
              saveMessageLog(log);
              setAlerts(prev => [{
                id: `auto-${log.id}`,
                title: 'Auto-Message Sent',
                desc: `Welcome WhatsApp sent to ${lead.name}`,
                type: 'success',
                leadId: lead.id
              }, ...prev]);
            }
          }
        }

        // Rule: Proposal Sent + 48h Inactivity -> Send WhatsApp Follow-up
        if (lead.stage === LeadStage.PROPOSAL_SENT && hoursInactivity > 48) {
          const hasAlreadySentFollowup = allLogs.some((l: any) => l.leadId === lead.id && l.templateId === 'proposal-wa');
          if (!hasAlreadySentFollowup && lead.whatsappOptIn) {
            const template = DEFAULT_TEMPLATES.find(t => t.id === 'proposal-wa');
            if (template) {
              const log = await sendSimulatedMessage(lead, template);
              saveMessageLog(log);
            }
          }
        }
      }
    };

    const interval = setInterval(runAutomationJob, 30000);
    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
    // Regular UI Alerts (Manual Reminders)
    const savedLeads = localStorage.getItem('et_leads');
    const leads: Lead[] = savedLeads ? JSON.parse(savedLeads) : MOCK_LEADS;
    const now = new Date();
    const newAlerts: any[] = [];

    leads.forEach(lead => {
      const createdAt = new Date(lead.createdAt);
      const lastUpdate = lead.updatedAt ? new Date(lead.updatedAt) : createdAt;
      const hoursSinceInactivity = (now.getTime() - lastUpdate.getTime()) / (1000 * 60 * 60);

      if (lead.stage === LeadStage.NEW && hoursSinceInactivity > 24) {
        newAlerts.push({ id: `alert-new-${lead.id}`, title: 'Cold Lead Alert', desc: `${lead.name} has been in "New" for 24h+.`, type: 'danger', leadId: lead.id });
      }

      if (lead.stage === LeadStage.PROPOSAL_SENT && hoursSinceInactivity > 48) {
        newAlerts.push({ id: `alert-prop-${lead.id}`, title: 'Proposal Follow-up', desc: `48h since proposal sent to ${lead.name}.`, type: 'warning', leadId: lead.id });
      }

      const todayStr = now.toISOString().split('T')[0];
      lead.followUps.filter(f => f.status === 'Pending' && f.date <= todayStr).forEach(f => {
        newAlerts.push({ id: `alert-fu-${f.id}`, title: 'Due Follow-up', desc: `${f.note} for ${lead.name}`, type: 'info', leadId: lead.id });
      });
    });

    setAlerts(prev => [...newAlerts, ...prev.filter(a => a.id.startsWith('auto-'))]);
  }, [location.pathname]);

  return (
    <div className="flex h-screen overflow-hidden bg-[#f8fafc]">
      {/* Sidebar */}
      <aside className="w-64 bg-slate-950 flex flex-col p-6 border-r border-slate-900">
        <div className="flex items-center gap-3 mb-4">
          <div className="bg-blue-600 p-2.5 rounded-xl shadow-xl shadow-blue-900/40">
            <Mountain className="text-white" size={24} />
          </div>
          <div>
            <h1 className="text-white font-black text-lg tracking-tighter leading-none">ESCAPE</h1>
            <p className="text-blue-500 text-[9px] font-black uppercase tracking-[0.2em]">THEORY KASHMIR</p>
          </div>
        </div>

        <nav className="flex-1 space-y-1 overflow-y-auto custom-scrollbar pr-2">
          <SidebarHeader label="Revenue & Sales" />
          <SidebarItem icon={LayoutDashboard} label="Dashboard" path="/" active={location.pathname === '/'} />
          <SidebarItem icon={Trello} label="Sales Pipeline" path="/pipeline" active={location.pathname === '/pipeline'} />
          <SidebarItem icon={Users} label="Lead Manager" path="/leads" active={location.pathname.startsWith('/leads') && location.pathname !== '/leads/new'} />

          <SidebarHeader label="Operations" />
          <SidebarItem icon={Map} label="All Itineraries" path="/trips" active={location.pathname === '/trips' || (location.pathname.startsWith('/trips/') && !location.pathname.includes('print'))} />
          <SidebarItem icon={FileText} label="Templates" path="/templates" active={location.pathname.startsWith('/templates')} />

          <SidebarHeader label="Master Database" />
          <SidebarItem icon={HotelIcon} label="Hotels" path="/hotels" active={location.pathname === '/hotels'} />
          <SidebarItem icon={Car} label="Vehicle Fleet" path="/vehicles" active={location.pathname === '/vehicles'} />
          <SidebarItem icon={Compass} label="Activities" path="/activities" active={location.pathname === '/activities'} />
          <SidebarItem icon={Sparkles} label="Add-ons" path="/add-ons" active={location.pathname === '/add-ons'} />

          <SidebarHeader label="System" />
          <SidebarItem icon={Settings} label="Settings" path="/settings" active={location.pathname === '/settings'} />
        </nav>

        <div className="mt-auto border-t border-slate-900 pt-6">
          <button className="flex items-center gap-3 px-4 py-3 text-slate-500 hover:text-red-400 transition-colors w-full group">
            <LogOut size={20} className="group-hover:translate-x-1 transition-transform" />
            <span className="font-bold text-sm">Sign Out</span>
          </button>
        </div>
      </aside>

      {/* Main Content */}
      <main className="flex-1 flex flex-col overflow-hidden relative">
        <header className="h-20 bg-white border-b border-slate-100 flex items-center justify-between px-10">
          <div className="flex items-center gap-4">
            <h2 className="text-slate-900 font-black text-xl tracking-tight uppercase">
              {location.pathname === '/' ? 'Business Intelligence' : 
               location.pathname.startsWith('/pipeline') ? 'Sales Pipeline' :
               location.pathname.startsWith('/leads') ? 'Client Relationship' :
               location.pathname.startsWith('/trips') ? 'Itinerary Control' :
               'Operational Control'}
            </h2>
          </div>
          <div className="flex items-center gap-6">
            <button 
              onClick={() => setShowNotifications(!showNotifications)}
              className="relative p-3 bg-slate-50 hover:bg-slate-100 rounded-2xl transition-all group"
            >
              <Bell size={20} className="text-slate-400 group-hover:text-blue-600" />
              {alerts.length > 0 && (
                <span className="absolute top-2 right-2 w-4 h-4 bg-rose-600 border-2 border-white rounded-full flex items-center justify-center text-[8px] text-white font-black">
                  {alerts.length}
                </span>
              )}
            </button>

            <div className="text-right">
              <p className="text-sm font-black text-slate-900 leading-none">Adil Bakshi</p>
              <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-1">Super Admin</p>
            </div>
            <div className="w-12 h-12 rounded-2xl bg-slate-100 border-4 border-white shadow-sm overflow-hidden">
               <img src="https://picsum.photos/seed/adil/100/100" alt="Admin" />
            </div>
          </div>
        </header>

        {/* Notifications Sidebar Panel */}
        {showNotifications && (
          <div className="absolute top-24 right-10 w-96 bg-white rounded-[40px] shadow-2xl border border-slate-100 z-[110] flex flex-col overflow-hidden animate-in slide-in-from-top-4 duration-300">
             <div className="p-8 border-b border-slate-50 flex items-center justify-between">
                <h3 className="font-black text-slate-900 uppercase tracking-widest text-xs flex items-center gap-2">
                   <Bell size={16} className="text-blue-600" /> Agency Action Center
                </h3>
                <button onClick={() => setShowNotifications(false)} className="text-slate-300 hover:text-slate-900"><X size={20}/></button>
             </div>
             <div className="flex-1 overflow-y-auto p-6 space-y-4 max-h-[60vh]">
                {alerts.length > 0 ? alerts.map(alert => (
                  <Link 
                    key={alert.id}
                    to={`/leads/${alert.leadId}`}
                    onClick={() => setShowNotifications(false)}
                    className="flex items-start gap-4 p-5 bg-slate-50 border border-slate-100 rounded-3xl group hover:bg-white hover:border-blue-200 transition-all shadow-sm"
                  >
                     <div className={`p-2 rounded-xl shrink-0 ${
                       alert.type === 'danger' ? 'bg-rose-100 text-rose-600' :
                       alert.type === 'warning' ? 'bg-amber-100 text-amber-600' :
                       alert.type === 'success' ? 'bg-emerald-100 text-emerald-600' :
                       'bg-blue-100 text-blue-600'
                     }`}>
                        {alert.type === 'success' ? <MessageSquare size={18}/> : <AlertTriangle size={18} />}
                     </div>
                     <div className="space-y-1">
                        <p className="text-[10px] font-black uppercase text-slate-400 tracking-widest">{alert.title}</p>
                        <p className="text-xs font-bold text-slate-700 leading-snug">{alert.desc}</p>
                     </div>
                     <ChevronRight size={16} className="text-slate-200 group-hover:text-blue-600 mt-1" />
                  </Link>
                )) : (
                  <div className="py-20 text-center space-y-4 opacity-30">
                    <Clock size={48} className="mx-auto" />
                    <p className="text-[10px] font-black uppercase tracking-widest">No Alerts Pending</p>
                  </div>
                )}
             </div>
             <div className="p-6 bg-slate-50 border-t border-slate-100">
                <button onClick={() => setAlerts([])} className="w-full py-3 text-[10px] font-black uppercase tracking-widest text-slate-400 hover:text-slate-900">Clear All Alerts</button>
             </div>
          </div>
        )}

        <div className="flex-1 overflow-y-auto p-10 bg-[#f8fafc]">
          {children}
        </div>
      </main>
    </div>
  );
};

export default Layout;

import React, { useState, useEffect, useMemo } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { 
  ArrowLeft, 
  Phone, 
  Mail, 
  MessageSquare, 
  Calendar, 
  Plus, 
  Clock, 
  User, 
  TrendingUp, 
  Target,
  FileText,
  Map,
  ChevronRight,
  MoreVertical,
  CheckCircle2,
  AlertCircle,
  Zap,
  Tag,
  Sparkles,
  Loader2,
  X,
  Send,
  History,
  Activity as ActivityIcon,
  ShieldCheck,
  Smartphone,
  Eye,
  RefreshCcw,
  Check
} from 'lucide-react';
import { Lead, LeadStage, LeadScore, CommunicationLog, FollowUp, Trip, LeadActivity, MessageLog } from '../types';
import { MOCK_LEADS, MOCK_TRIPS } from '../constants';
import { suggestFollowUp, draftWhatsAppMessage } from '../services/geminiService';
import { sendSimulatedMessage, DEFAULT_TEMPLATES, saveMessageLog, getMessageLogsForLead } from '../services/messagingService';

const LeadProfile: React.FC = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const [lead, setLead] = useState<Lead | null>(null);
  const [activeTab, setActiveTab] = useState<'overview' | 'trips' | 'timeline' | 'messaging' | 'followups'>('overview');
  const [newLog, setNewLog] = useState('');
  const [isAiScheduling, setIsAiScheduling] = useState(false);

  // Messaging States
  const [isSending, setIsSending] = useState(false);
  const [messageLogs, setMessageLogs] = useState<MessageLog[]>([]);

  useEffect(() => {
    const savedLeads = localStorage.getItem('et_leads');
    const allLeads = savedLeads ? JSON.parse(savedLeads) : MOCK_LEADS;
    const found = allLeads.find((l: Lead) => l.id === id);
    if (found) {
      if (!found.activities) found.activities = [];
      if (found.whatsappOptIn === undefined) found.whatsappOptIn = true;
      setLead(found);
      setMessageLogs(getMessageLogsForLead(found.id));
    }
  }, [id]);

  const recordActivity = (updatedLead: Lead, type: LeadActivity['type'], description: string, meta?: any) => {
    const activity: LeadActivity = {
      id: `act-${Date.now()}`,
      leadId: updatedLead.id,
      type,
      timestamp: new Date().toISOString(),
      description,
      meta
    };
    updatedLead.activities = [activity, ...(updatedLead.activities || [])];
    updatedLead.updatedAt = new Date().toISOString();
    return updatedLead;
  };

  const updateLeadInStorage = (updatedLead: Lead) => {
    setLead(updatedLead);
    const savedLeads = localStorage.getItem('et_leads');
    const allLeads = savedLeads ? JSON.parse(savedLeads) : [...MOCK_LEADS];
    const index = allLeads.findIndex((l: Lead) => l.id === updatedLead.id);
    if (index > -1) {
      allLeads[index] = updatedLead;
    } else {
      allLeads.push(updatedLead);
    }
    localStorage.setItem('et_leads', JSON.stringify(allLeads));
  };

  const handleManualMessage = async (templateId: string) => {
    if (!lead || isSending) return;
    const template = DEFAULT_TEMPLATES.find(t => t.id === templateId);
    if (!template) return;

    setIsSending(true);
    try {
      const log = await sendSimulatedMessage(lead, template);
      saveMessageLog(log);
      setMessageLogs(prev => [log, ...prev]);

      let updatedLead = { ...lead };
      updatedLead = recordActivity(updatedLead, 'MessageSent', `Manual ${template.type} sent: ${template.name}`, { msgId: log.id });
      updateLeadInStorage(updatedLead);
    } finally {
      setIsSending(false);
    }
  };

  const handleStageChange = (newStage: LeadStage) => {
    if (!lead) return;
    let updatedLead = { ...lead, stage: newStage };
    updatedLead = recordActivity(updatedLead, 'StatusChange', `Stage changed from ${lead.stage} to ${newStage}`);
    updateLeadInStorage(updatedLead);
  };

  const addCommunicationLog = (type: CommunicationLog['type'] = 'Note', content: string = newLog) => {
    if (!lead || !content.trim()) return;
    const log: CommunicationLog = {
      id: `c-${Date.now()}`,
      type,
      timestamp: new Date().toISOString(),
      content,
      author: 'Adil Bakshi'
    };
    let updatedLead = { ...lead, communicationLogs: [log, ...lead.communicationLogs] };
    updatedLead = recordActivity(updatedLead, 'NoteAdded', `Communication logged: ${type}`, { logId: log.id });
    updateLeadInStorage(updatedLead);
    if (type === 'Note') setNewLog('');
  };

  if (!lead) return <div className="p-20 text-center font-black text-slate-300 uppercase tracking-widest">LOADING LEAD...</div>;

  const leadTrips = MOCK_TRIPS.filter(t => t.leadId === lead.id);
  const pendingFollowUps = lead.followUps.filter(f => f.status === 'Pending');

  return (
    <div className="space-y-8 pb-20">
      {/* Header Profile Info */}
      <div className="bg-white p-10 rounded-[48px] border border-slate-100 shadow-sm flex flex-col md:flex-row gap-10">
         <div className="flex-1 space-y-6">
            <div className="flex items-center gap-5">
               <button onClick={() => navigate('/pipeline')} className="p-3 bg-slate-50 hover:bg-slate-100 rounded-2xl text-slate-400 transition-all active:scale-95"><ArrowLeft size={20}/></button>
               <div>
                  <h1 className="text-4xl font-black text-slate-900 tracking-tighter">{lead.name}</h1>
                  <div className="flex items-center gap-4 mt-1">
                     <span className={`text-[10px] font-black uppercase tracking-widest px-3 py-1 rounded-full ${lead.score === LeadScore.HOT ? 'bg-rose-100 text-rose-600' : 'bg-blue-100 text-blue-600'}`}>
                        {lead.score} Priority
                     </span>
                     <div className="flex items-center gap-1.5 px-3 py-1 bg-emerald-50 rounded-full">
                        <Smartphone size={10} className="text-emerald-600" />
                        <span className="text-[9px] font-black uppercase tracking-widest text-emerald-600">WhatsApp {lead.whatsappOptIn ? 'Opted-In' : 'Opted-Out'}</span>
                     </div>
                  </div>
               </div>
            </div>

            <div className="grid grid-cols-2 md:grid-cols-4 gap-6 pt-4">
               <div className="space-y-1">
                  <p className="text-[9px] font-black uppercase text-slate-400 tracking-widest">Phone</p>
                  <p className="font-bold text-slate-900 flex items-center gap-2"><Phone size={14} className="text-blue-500"/> {lead.phone}</p>
               </div>
               <div className="space-y-1">
                  <p className="text-[9px] font-black uppercase text-slate-400 tracking-widest">Email</p>
                  <p className="font-bold text-slate-900 flex items-center gap-2 truncate"><Mail size={14} className="text-blue-500"/> {lead.email}</p>
               </div>
               <div className="space-y-1">
                  <p className="text-[9px] font-black uppercase text-slate-400 tracking-widest">Travel Month</p>
                  <p className="font-bold text-slate-900 flex items-center gap-2"><Calendar size={14} className="text-amber-500"/> {lead.travelMonth}</p>
               </div>
               <div className="space-y-1">
                  <p className="text-[9px] font-black uppercase text-slate-400 tracking-widest">Budget</p>
                  <p className="font-bold text-slate-900 flex items-center gap-2">₹ {lead.budgetRange}</p>
               </div>
            </div>
         </div>

         <div className="w-full md:w-80 bg-slate-950 p-8 rounded-[40px] text-white space-y-6">
            <p className="text-[10px] font-black uppercase tracking-widest text-slate-500">Pipeline Stage</p>
            <div className="flex flex-col gap-4">
               <select 
                 value={lead.stage}
                 onChange={(e) => handleStageChange(e.target.value as LeadStage)}
                 className="w-full bg-slate-900 border border-slate-800 p-4 rounded-2xl font-black text-xs uppercase tracking-widest outline-none"
               >
                  {Object.values(LeadStage).map(s => <option key={s} value={s}>{s}</option>)}
               </select>
               <button className="w-full py-4 bg-blue-600 text-white rounded-2xl font-black uppercase tracking-widest text-[10px] shadow-xl shadow-blue-900/40">
                  Quick Log Follow-up
               </button>
            </div>
         </div>
      </div>

      <div className="grid grid-cols-12 gap-8">
         <div className="col-span-12 lg:col-span-8 space-y-8">
            <div className="flex gap-4 p-1.5 bg-white border border-slate-100 rounded-3xl w-fit">
               {['overview', 'trips', 'timeline', 'messaging', 'followups'].map((tab) => (
                  <button 
                    key={tab}
                    onClick={() => setActiveTab(tab as any)}
                    className={`px-6 py-3 rounded-2xl font-black text-[10px] uppercase tracking-widest transition-all ${
                      activeTab === tab ? 'bg-slate-900 text-white shadow-xl' : 'text-slate-400 hover:text-slate-900'
                    }`}
                  >
                    {tab}
                  </button>
               ))}
            </div>

            {activeTab === 'messaging' && (
               <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-300">
                  <div className="bg-white p-8 rounded-[40px] border border-slate-100 shadow-sm space-y-8">
                     <div className="flex items-center justify-between">
                        <h3 className="text-xs font-black uppercase tracking-widest text-slate-900 flex items-center gap-2">
                           <MessageSquare size={16} className="text-blue-600" /> Messaging Action Center
                        </h3>
                     </div>

                     <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                        {DEFAULT_TEMPLATES.map(tmp => (
                           <button 
                             key={tmp.id}
                             onClick={() => handleManualMessage(tmp.id)}
                             disabled={isSending}
                             className="p-6 border border-slate-100 rounded-[32px] text-left hover:bg-slate-50 hover:border-blue-200 transition-all group flex flex-col gap-3"
                           >
                              <div className={`p-3 rounded-2xl w-fit ${tmp.type === 'WhatsApp' ? 'bg-emerald-50 text-emerald-600' : 'bg-blue-50 text-blue-600'}`}>
                                 {tmp.type === 'WhatsApp' ? <Smartphone size={18}/> : <Mail size={18}/>}
                              </div>
                              <div>
                                 <p className="font-black text-slate-900 text-sm">{tmp.name}</p>
                                 <p className="text-[10px] font-bold text-slate-400 uppercase mt-1">Template: {tmp.id}</p>
                              </div>
                              <div className="mt-4 flex items-center justify-between">
                                 <span className="text-[10px] font-black text-blue-600 group-hover:underline">Trigger Now</span>
                                 <ChevronRight size={14} className="text-slate-200 group-hover:text-blue-600" />
                              </div>
                           </button>
                        ))}
                     </div>
                  </div>

                  <div className="space-y-6">
                     <h3 className="text-xs font-black uppercase tracking-widest text-slate-400 ml-4">Communication Delivery Log</h3>
                     {messageLogs.map(log => (
                        <div key={log.id} className="bg-white p-6 rounded-[32px] border border-slate-50 shadow-sm flex items-center gap-6">
                           <div className={`p-4 rounded-2xl ${log.status === 'Delivered' ? 'bg-emerald-50 text-emerald-600' : 'bg-rose-50 text-rose-600'}`}>
                              {log.status === 'Delivered' ? <Check size={20}/> : <AlertCircle size={20}/>}
                           </div>
                           <div className="flex-1 space-y-1">
                              <div className="flex items-center justify-between">
                                 <div className="flex items-center gap-3">
                                    <span className={`text-[10px] font-black uppercase tracking-widest ${log.type === 'WhatsApp' ? 'text-emerald-600' : 'text-blue-600'}`}>{log.type} Delivery</span>
                                    <span className="w-1 h-1 bg-slate-200 rounded-full" />
                                    <span className="text-[10px] font-bold text-slate-300">{new Date(log.timestamp).toLocaleString()}</span>
                                 </div>
                                 <span className={`text-[9px] font-black uppercase px-2 py-0.5 rounded-full ${log.status === 'Delivered' ? 'bg-emerald-100 text-emerald-700' : 'bg-rose-100 text-rose-700'}`}>{log.status}</span>
                              </div>
                              <p className="text-sm text-slate-600 font-medium italic line-clamp-2">"{log.content}"</p>
                              {log.errorMessage && <p className="text-[10px] font-black text-rose-500 uppercase tracking-tighter">Error: {log.errorMessage}</p>}
                           </div>
                           <button className="p-3 text-slate-300 hover:text-slate-900 transition-colors"><Eye size={18}/></button>
                        </div>
                     ))}
                     {messageLogs.length === 0 && (
                        <div className="py-20 text-center border-2 border-dashed border-slate-100 rounded-[40px]">
                           <MessageSquare size={48} className="mx-auto mb-4 opacity-10" />
                           <p className="text-[10px] font-black uppercase tracking-widest text-slate-300">No Automated Messages Sent Yet</p>
                        </div>
                     )}
                  </div>
               </div>
            )}

            {activeTab === 'overview' && (
              <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4 duration-300">
                 <div className="bg-white p-8 rounded-[40px] border border-slate-100 shadow-sm space-y-6">
                    <div className="flex items-center justify-between">
                       <h3 className="text-xs font-black uppercase tracking-widest text-slate-900">Add Communication Log</h3>
                    </div>
                    <div className="relative">
                       <textarea 
                         rows={4}
                         placeholder="Add a call summary, WhatsApp update, or internal note..."
                         className="w-full p-6 bg-slate-50 border border-slate-100 rounded-[32px] outline-none font-bold text-slate-900 focus:bg-white focus:ring-4 focus:ring-blue-50 transition-all shadow-inner resize-none"
                         value={newLog}
                         onChange={(e) => setNewLog(e.target.value)}
                       />
                       <button 
