  ChevronRight, 
  MessageSquare, 
  Phone, 
  Mail, 
  MoreVertical,
  Flame,
  TrendingUp,
  Snowflake,
  Clock,
  Calendar,
  Zap,
  CheckCircle2,
  X,
  Trash2,
