                   </div>
                   <div className="space-y-1">
                      <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">Pax</label>
                      <input type="number" className="w-full p-4 bg-slate-50 border border-slate-200 rounded-2xl font-bold outline-none" value={editingLead.pax} onChange={e => setEditingLead({...editingLead, pax: parseInt(e.target.value)})} />
