                                {tmp.type === 'WhatsApp' ? <Smartphone size={18}/> : <Mail size={18}/>}
                             </div>
                             <div>
                                <h4 className="font-black text-slate-900">{tmp.name}</h4>
                                <div className="flex items-center gap-2 mt-1">
                                  {/* Fixed: Added Clock to lucide-react imports */}
                                  <Clock size={10} className="text-slate-400" />
                                  <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">Trigger: After {tmp.delayHours}h inactivity</p>
                                </div>
                             </div>
                          </div>
                          <div className="flex items-center gap-4">
                             <div className="w-10 h-5 bg-blue-600 rounded-full relative shadow-inner cursor-pointer">
                               <div className="absolute right-1 top-1 w-3 h-3 bg-white rounded-full shadow-sm"/>
                             </div>
                             <button className="text-slate-300 hover:text-rose-500 transition-colors"><X size={20}/></button>
                          </div>
                       </div>
                       <textarea 
                         className="w-full p-6 bg-slate-50 border border-slate-200 rounded-[32px] outline-none font-bold text-slate-700 focus:bg-white focus:ring-4 focus:ring-blue-50 transition-all text-sm leading-relaxed"
                         rows={4}
                         value={tmp.body}
                         onChange={(e) => {
                           const newTemplates = [...templates];
                           newTemplates[idx].body = e.target.value;
                           setTemplates(newTemplates);
                         }}
                       />
                    </div>
                  ))}
                  <button className="w-full py-8 border-2 border-dashed border-slate-200 rounded-[40px] text-slate-300 font-black uppercase tracking-widest text-[10px] hover:text-blue-600 hover:border-blue-200 transition-all flex flex-col items-center justify-center gap-2">
                     <Plus size={24} className="opacity-40" /> Add Custom Workflow Template
                  </button>
               </div>
            </div>
          </Section>
        </div>
      )}
    </div>
  );
};

