               </div>
            </div>

            <div className="bg-blue-600 p-10 rounded-[48px] text-white space-y-8 shadow-2xl">
               <h3 className="text-[10px] font-black uppercase tracking-[0.2em] text-blue-200">Channel Activity</h3>
