import { 
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, AreaChart, Area, PieChart, Pie, Cell
} from 'recharts';
import { 
  TrendingUp, Users, Target, MessageSquare, Zap, Clock, AlertCircle, ChevronRight, IndianRupee, 
  MapPin, CheckCircle, Activity, Star, Calendar, ArrowUpRight, Wallet
} from 'lucide-react';
import { MOCK_LEADS, MOCK_TRIPS } from '../constants';
import { LeadStage, LeadScore, Lead, Trip } from '../types';

const Dashboard: React.FC = () => {
  const [leads, setLeads] = useState<Lead[]>([]);
  const [trips, setTrips] = useState<Trip[]>([]);

  useEffect(() => {
    const savedLeads = localStorage.getItem('et_leads');
    setLeads(savedLeads ? JSON.parse(savedLeads) : MOCK_LEADS);
    const savedTrips = localStorage.getItem('et_trips');
    setTrips(savedTrips ? JSON.parse(savedTrips) : MOCK_TRIPS);
  }, []);

  const stats = useMemo(() => {
    const quotedLeads = leads.filter(l => l.stage === LeadStage.PROPOSAL_SENT || l.stage === LeadStage.NEGOTIATION);
    const pipelineValue = trips.reduce((acc, t) => acc + (t.tierPrices?.elite || 0), 0);
    const conversionRate = leads.length > 0 ? (leads.filter(l => l.stage === LeadStage.BOOKED).length / leads.length) * 100 : 0;
    const activeFollows = leads.reduce((acc, l) => acc + l.followUps.filter(f => f.status === 'Pending').length, 0);

    return {
      totalLeads: leads.length,
      pipelineValue: pipelineValue.toLocaleString(),
      conversionRate: conversionRate.toFixed(1),
      activeFollows
    };
  }, [leads, trips]);

  const agentStats = useMemo(() => {
    const agents = Array.from(new Set(leads.map(l => l.assignedTo)));
    return agents.map(agent => {
      const agentLeads = leads.filter(l => l.assignedTo === agent);
      const bookings = agentLeads.filter(l => l.stage === LeadStage.BOOKED).length;
      return { 
        name: agent, 
        leads: agentLeads.length, 
        bookings,
        conversion: agentLeads.length > 0 ? (bookings / agentLeads.length * 100).toFixed(1) : '0'
      };
    }).sort((a, b) => parseFloat(b.conversion) - parseFloat(a.conversion));
  }, [leads]);

  const chartData = [
    { name: 'Mon', leads: 4 }, { name: 'Tue', leads: 7 }, { name: 'Wed', leads: 5 },
    { name: 'Thu', leads: 8 }, { name: 'Fri', leads: 12 }, { name: 'Sat', leads: 15 },
    { name: 'Sun', leads: 9 }
  ];

  const StatCard = ({ label, value, icon: Icon, color, trend }: any) => (
    <div className="bg-slate-900/60 backdrop-blur-xl border border-white/10 p-6 rounded-[32px] group transition-all hover:bg-slate-900/80 hover:border-blue-500/30">
      <div className="flex justify-between items-start mb-4">
        <div className={`p-3 rounded-2xl ${color} bg-opacity-20`}>
          <Icon size={24} className={color.replace('bg-', 'text-')} />
        </div>
        <div className="flex items-center gap-1 text-emerald-400 text-xs font-bold">
          <ArrowUpRight size={14} />
          {trend}
        </div>
      </div>
      <div>
        <p className="text-slate-400 text-[10px] font-black uppercase tracking-[0.2em] mb-1">{label}</p>
        <h3 className="text-3xl font-black text-white tracking-tighter">{value}</h3>
      </div>
    </div>
  );

  return (
    <div className="space-y-8 animate-in fade-in duration-500">
      {/* Header Summary */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard label="Total Acquisitions" value={stats.totalLeads} icon={Users} color="bg-blue-500" trend="+14%" />
        <StatCard label="Live Pipeline" value={`₹${stats.pipelineValue}`} icon={Wallet} color="bg-emerald-500" trend="+8%" />
        <StatCard label="Conversion Efficiency" value={`${stats.conversionRate}%`} icon={Target} color="bg-indigo-500" trend="+12%" />
        <StatCard label="Due Engagements" value={stats.activeFollows} icon={Clock} color="bg-rose-500" trend="+5%" />
      </div>

      <div className="grid grid-cols-1 xl:grid-cols-3 gap-8">
        {/* Main Chart */}
        <div className="xl:col-span-2 space-y-8">
          <div className="bg-slate-900/60 backdrop-blur-xl border border-white/10 p-8 rounded-[40px]">
            <div className="flex items-center justify-between mb-8">
              <h3 className="text-white font-black text-lg uppercase tracking-widest flex items-center gap-3">
                <Activity size={20} className="text-blue-500" /> Lead Trajectory
              </h3>
              <select className="bg-white/5 border border-white/10 rounded-xl px-4 py-2 text-xs font-bold text-white outline-none">
                <option>Last 7 Days</option>
                <option>Last 30 Days</option>
              </select>
            </div>
            <div className="h-72">
              <ResponsiveContainer width="100%" height="100%">
                <AreaChart data={chartData}>
                  <defs>
                    <linearGradient id="chartGradient" x1="0" y1="0" x2="0" y2="1">
                      <stop offset="5%" stopColor="#3b82f6" stopOpacity={0.3}/>
                      <stop offset="95%" stopColor="#3b82f6" stopOpacity={0}/>
                    </linearGradient>
                  </defs>
                  <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#ffffff05" />
                  <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{fill: '#64748b', fontSize: 10, fontWeight: 700}} />
                  {/* Fixed: Completed missing YAxis and Chart components */}
                  <YAxis axisLine={false} tickLine={false} tick={{fill: '#64748b', fontSize: 10, fontWeight: 700}} />
                  <Tooltip 
                    contentStyle={{backgroundColor: '#0f172a', border: '1px solid #1e293b', borderRadius: '16px', color: '#fff'}} 
                    itemStyle={{color: '#3b82f6'}}
                  />
                  <Area type="monotone" dataKey="leads" stroke="#3b82f6" strokeWidth={4} fillOpacity={1} fill="url(#chartGradient)" />
                </AreaChart>
              </ResponsiveContainer>
            </div>
          </div>
        </div>

        {/* Agent Performance */}
        <div className="space-y-6">
          <div className="bg-slate-900/60 backdrop-blur-xl border border-white/10 p-8 rounded-[40px] h-full">
            <h3 className="text-white font-black text-lg uppercase tracking-widest flex items-center gap-3 mb-8">
              <Star size={20} className="text-amber-400" /> Sales Elite
            </h3>
            <div className="space-y-6">
              {agentStats.map((agent, i) => (
                <div key={agent.name} className="flex items-center justify-between group">
                  <div className="flex items-center gap-4">
                    <div className="w-10 h-10 rounded-2xl bg-slate-800 flex items-center justify-center text-xs font-black text-slate-400 border border-white/5">
                      {i + 1}
                    </div>
                    <div>
                      <p className="text-white font-black text-sm">{agent.name}</p>
                      <p className="text-[10px] text-slate-500 font-bold uppercase tracking-widest">{agent.leads} Leads Acquired</p>
                    </div>
                  </div>
                  <div className="text-right">
                    <p className="text-white font-black text-sm">{agent.conversion}%</p>
                    <p className="text-[9px] text-emerald-400 font-bold uppercase tracking-widest">Efficiency</p>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

