      foundTrip = parsed.find((t: Trip) => t.id === id);
    }
    if (!foundTrip) {
      foundTrip = MOCK_TRIPS.find(t => t.id === id);
    }
    if (foundTrip) {
      setTrip(foundTrip);
    }
  }, [id]);

  const masterHotels = useMemo(() => {
    const saved = localStorage.getItem('et_hotels');
    const custom = saved ? JSON.parse(saved) : [];
    return [...HOTELS, ...custom];
  }, []);

  const tieredAccommodationRows = useMemo(() => {
    if (!trip || !trip.hotelTiers) return [];
    return trip.hotelTiers.map(tier => {
      const sigHotel = masterHotels.find(h => h.id === tier.signatureHotelId);
      const eltHotel = masterHotels.find(h => h.id === tier.eliteHotelId);
      const prmHotel = masterHotels.find(h => h.id === tier.primeHotelId);

      return {
        location: tier.location,
        signature: sigHotel?.name || 'Standard Deluxe',
        elite: eltHotel?.name || 'Premium Deluxe',
        prime: prmHotel?.name || 'Super Luxury'
      };
    });
  }, [trip, masterHotels]);

  const stayDistribution = useMemo(() => {
    if (!trip || trip.itinerary.length < 2) return [];
    const dist: { location: string; nights: number }[] = [];
    let currentLocation: string | undefined = undefined;
    let currentCount = 0;

    const stayDays = trip.itinerary.slice(0, -1);

    stayDays.forEach((day, idx) => {
      const dayLoc = day.location || masterHotels.find(h => h.id === day.hotelId)?.location || 'Srinagar';

      if (dayLoc === currentLocation) {
        currentCount++;
      } else {
        if (currentLocation) {
          dist.push({ location: currentLocation, nights: currentCount });
        }
        currentLocation = dayLoc;
        currentCount = 1;
      }

      if (idx === stayDays.length - 1 && currentLocation) {
        dist.push({ location: currentLocation, nights: currentCount });
      }
    });
    return dist;
  }, [trip, masterHotels]);

  const handleDownloadPdf = async () => {
    if (!trip || !printableRef.current || isGenerating) return;
    setIsGenerating(true);
    try {
      const h2p = (window as any).html2pdf;
      const element = printableRef.current;
      const opt = {
        margin: [0, 0, 0, 0],
        filename: `${trip.client.name}_EscapeTheory_Kashmir.pdf`,
        image: { type: 'jpeg', quality: 0.98 },
        html2canvas: { scale: 2, useCORS: true },
        jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' },
        pagebreak: { mode: ['avoid-all', 'css', 'legacy'] }
      };
      await h2p().from(element).set(opt).save();
    } catch (err) {
      console.error(err);
      alert("PDF Error. Try browser print.");
    } finally {
      setIsGenerating(false);
    }
  };

  if (!trip) return <div className="p-20 text-center font-black text-slate-400">LOADING PROPOSAL...</div>;

  const durationNights = Math.max(0, trip.itinerary.length - 1);
  const durationDays = trip.itinerary.length;

  return (
    <div className="bg-slate-50 min-h-screen text-slate-900 print:bg-white overflow-x-hidden pb-20">
      {/* Tool Bar */}
      <div className="no-print sticky top-0 bg-white/95 backdrop-blur-md border-b border-slate-200 z-[100] p-4 flex justify-between items-center px-10 shadow-lg">
        <button onClick={() => navigate(`/trips/${id}`)} className="text-slate-500 font-bold flex items-center gap-2 hover:text-slate-900 transition-colors">
          <ArrowLeft size={18} /> BACK TO BUILDER
        </button>
        <div className="flex gap-4">
          <button onClick={() => window.print()} className="bg-white border border-slate-200 px-6 py-2.5 rounded-xl font-bold flex items-center gap-2 shadow-sm hover:bg-slate-50">
            <Printer size={18} /> PRINT
          </button>
          <button onClick={handleDownloadPdf} disabled={isGenerating} className="bg-blue-600 text-white px-8 py-2.5 rounded-xl font-bold flex items-center gap-2 shadow-xl hover:bg-blue-700 transition-all">
            {isGenerating ? <Loader2 size={18} className="animate-spin" /> : <Download size={18} />}
            {isGenerating ? 'GENERATING...' : 'DOWNLOAD PDF'}
          </button>
        </div>
      </div>

      {/* Proposal Document */}
      <div className="max-w-[210mm] mx-auto bg-white shadow-2xl my-10 print:my-0 print:shadow-none" ref={printableRef}>

        {/* PAGE 1: COVER & DYNAMIC TIERED TABLE */}
        <div className="p-16 space-y-12">
          {/* Cover Section */}
          <div className="w-full h-[120mm] rounded-[40px] overflow-hidden relative shadow-2xl">
            <img src="https://images.unsplash.com/photo-1590490360182-c33d57733427?auto=format&fit=crop&q=80&w=1600" className="w-full h-full object-cover" alt="Kashmir" />
            <div className="absolute inset-0 bg-gradient-to-t from-black/70 to-transparent" />
            <div className="absolute bottom-10 left-10 text-white">
              <h1 className="text-6xl font-black tracking-tighter uppercase leading-none">{BRAND_CONFIG.name}</h1>
              <p className="text-blue-300 font-bold uppercase tracking-[0.4em] mt-4">{BRAND_CONFIG.tagline}</p>
            </div>
          </div>

          <div className="space-y-4">
            <h2 className="text-4xl font-serif text-slate-800 italic leading-tight">Dear {trip.client.name},</h2>
            <p className="text-xl font-medium text-slate-600">Greetings from <span className="text-blue-900 font-black">Escape Theory Kashmir</span>. We are delighted to present your curated travel plan.</p>
          </div>

          <div className="space-y-4">
            <h3 className="text-3xl font-black text-slate-900 border-l-8 border-blue-600 pl-6 uppercase tracking-tight">
              Tour {durationNights.toString().padStart(2, '0')} Nights/{durationDays.toString().padStart(2, '0')} Days
            </h3>

            <div className="flex flex-wrap gap-4 pt-2">
              <div className="bg-blue-950 text-white px-6 py-3 rounded-2xl shadow-lg flex items-center gap-3">
                 <Moon size={18} className="text-blue-400" />
                 <div className="flex items-center gap-2 text-xs font-black uppercase tracking-widest divide-x divide-white/20">
                   {stayDistribution.map((dist, i) => (
                     <span key={i} className={i > 0 ? 'pl-2' : ''}>
                       {dist.nights.toString().padStart(2, '0')} {dist.location}
                     </span>
                   ))}
                 </div>
              </div>
            </div>

            <p className="text-lg font-bold text-slate-700 pt-4">
              <span className="text-blue-600 uppercase tracking-widest text-xs font-black mr-4">Itinerary Overview</span>
              {trip.itinerary.map(d => d.title.split(':')[0]).join(' • ')}
            </p>
          </div>

          {/* DYNAMIC TIERED ACCOMMODATION TABLE */}
          <div className="space-y-6 pt-6">
            <h4 className="text-2xl font-black text-slate-900 flex items-center gap-4 uppercase tracking-tight">
              <Bed className="text-blue-600" /> Accommodation Selection & Pricing
            </h4>
            <div className="overflow-hidden border-2 border-slate-900 rounded-lg shadow-sm">
              <table className="w-full text-left border-collapse">
                <thead className="bg-slate-50 border-b-2 border-slate-900 text-[11px] font-black uppercase">
                  <tr className="divide-x-2 divide-slate-900">
                    <th className="px-6 py-5 text-slate-400">Destination</th>
                    <th className="px-6 py-5 text-blue-900"><div className="flex items-center gap-2"><Award size={14}/> Signature</div></th>
                    <th className="px-6 py-5 text-blue-900 bg-blue-50/50"><div className="flex items-center gap-2"><Trophy size={14}/> Elite Tier</div></th>
                    <th className="px-6 py-5 text-blue-900"><div className="flex items-center gap-2"><Crown size={14}/> Prime Tier</div></th>
                  </tr>
                </thead>
                <tbody className="divide-y-2 divide-slate-900 text-sm font-bold text-slate-800">
                  {tieredAccommodationRows.length > 0 ? tieredAccommodationRows.map((row, i) => (
                    <tr key={i} className="divide-x-2 divide-slate-900">
                      <td className="px-6 py-5 font-black text-blue-900 bg-slate-50/20 uppercase tracking-wider">{row.location}</td>
                      <td className="px-6 py-5">{row.signature}</td>
                      <td className="px-6 py-5 bg-blue-50/10 font-black">{row.elite}</td>
                      <td className="px-6 py-5">{row.prime}</td>
                    </tr>
                  )) : (
                    <tr className="divide-x-2 divide-slate-900 italic text-slate-400">
                      <td className="px-6 py-5" colSpan={4}>Hotel configurations pending.</td>
                    </tr>
                  )}
                  <tr className="divide-x-2 divide-slate-900 font-black text-2xl bg-yellow-400">
                    <td className="px-6 py-6 bg-white border-white"></td>
                    <td className="px-6 py-6 text-center">₹{(trip.tierPrices?.signature || 0).toLocaleString()}*</td>
                    <td className="px-6 py-6 text-center border-x-4 border-blue-600">₹{(trip.tierPrices?.elite || 0).toLocaleString()}*</td>
                    <td className="px-6 py-6 text-center">₹{(trip.tierPrices?.prime || 0).toLocaleString()}*</td>
                  </tr>
                </tbody>
              </table>
            </div>
            <p className="text-[10px] text-slate-400 font-black italic uppercase tracking-[0.2em] text-center">
              *All inclusive pricing for {(trip.pax || 2)} persons. Subject to availability at booking.
            </p>
          </div>

          <div className="flex gap-12 items-center justify-center bg-slate-50 p-8 rounded-3xl border border-slate-100 shadow-inner">
             <div className="flex items-center gap-4">
               <span className="text-xl font-black text-slate-400 uppercase tracking-widest">Guests</span>
               <span className="bg-blue-900 text-white text-3xl font-black px-8 py-4 rounded-3xl shadow-xl">{(trip.pax || 2).toString().padStart(2, '0')}</span>
             </div>
             <div className="w-px h-16 bg-slate-200" />
             <div className="flex items-center gap-4">
               <span className="text-xl font-black text-slate-400 uppercase tracking-widest">Rooms</span>
               <span className="bg-blue-900 text-white text-3xl font-black px-8 py-4 rounded-3xl shadow-xl">{Math.ceil((trip.pax || 2) / 2).toString().padStart(2, '0')}</span>
             </div>
          </div>
        </div>

        {/* PAGE 2: DAY WISE SUMMARY */}
        <div className="page-break" />
        <div className="p-16 space-y-12">
           <h4 className="text-3xl font-black text-blue-900 tracking-tight flex items-center gap-5 uppercase">
              <Compass size={36} className="text-blue-600" /> Planned Itinerary Summary
           </h4>
           <div className="overflow-hidden border-2 border-slate-900 rounded-lg shadow-sm">
              <table className="w-full text-left border-collapse">
                <thead className="bg-slate-100 border-b-2 border-slate-900 text-[11px] font-black uppercase text-blue-900">
                  <tr>
                    <th className="px-6 py-5 border-r-2 border-slate-900 w-28">Day</th>
                    <th className="px-6 py-5 border-r-2 border-slate-900">Program & Experience</th>
                    <th className="px-6 py-5">Night Stay At</th>
                  </tr>
                </thead>
                <tbody className="divide-y-2 divide-slate-900 font-bold text-slate-800 text-[13px]">
                  {trip.itinerary.map((day, idx) => {
                    const hotel = masterHotels.find(h => h.id === day.hotelId);
                    const dayActivities = (day.activityIds || []).map(aid => ACTIVITIES.find(a => a.id === aid)?.name);
                    const isDepartureDay = idx === trip.itinerary.length - 1;

                    return (
                      <tr key={idx} className="divide-x-2 divide-slate-900">
                        <td className="px-6 py-6 text-blue-700 font-black uppercase bg-slate-50/50">Day {day.dayNumber}</td>
                        <td className="px-6 py-6 space-y-3">
                           <div>
                              <span className="block font-black text-slate-900 mb-2 uppercase text-base">{day.title}</span>
                              <p className="text-[12px] text-slate-500 font-medium leading-relaxed italic">"{day.clientNotes}"</p>
                           </div>
                           {dayActivities.length > 0 && (
                              <div className="flex flex-wrap gap-2 pt-2">
                                 {dayActivities.map((act, i) => (
                                    <span key={i} className="px-2 py-1 bg-emerald-50 border border-emerald-100 text-emerald-700 rounded-md text-[9px] font-black uppercase tracking-wider">
                                       ✓ {act}
                                    </span>
                                 ))}
                              </div>
                           )}
                        </td>
                        <td className="px-6 py-6 text-blue-900 font-black uppercase tracking-wider">
                          {isDepartureDay ? (
                            <div className="flex flex-col items-center gap-1 text-rose-600">
                              <PlaneTakeoff size={18} />
                              <span className="text-[10px]">CHECKOUT</span>
                            </div>
                          ) : (
                            day.location || hotel?.location || 'Srinagar'
                          )}
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
              </table>
           </div>

           <div className="grid grid-cols-2 gap-12 pt-12">
             <div className="space-y-8 p-10 bg-blue-50/30 rounded-[48px] border border-blue-100 shadow-sm">
                <h4 className="text-2xl font-black text-blue-900 uppercase tracking-widest flex items-center gap-4">
                   <ShieldCheck size={28} className="text-emerald-500" /> Package Inclusions
                </h4>
                <ul className="space-y-4">
                  {(trip.inclusions || DEFAULT_INCLUSIONS).map((inc, i) => (
                    <li key={i} className="flex gap-4 text-[13px] font-bold text-slate-700 leading-snug">
                       <span className="text-blue-600 font-black text-lg">•</span> {inc}
                    </li>
                  ))}
                </ul>
             </div>

             <div className="space-y-8 p-10 bg-rose-50/20 rounded-[48px] border border-rose-100 shadow-sm">
                <h4 className="text-2xl font-black text-rose-900 uppercase tracking-widest flex items-center gap-4">
                   <XCircle size={28} className="text-rose-500" /> Package Exclusions
                </h4>
                <ul className="space-y-4">
                  {(trip.exclusions || DEFAULT_EXCLUSIONS).map((exc, i) => (
                    <li key={i} className="flex gap-4 text-[13px] font-bold text-slate-400 leading-snug">
                       <span className="text-rose-500 font-black text-lg">•</span> {exc}
                    </li>
                  ))}
                </ul>
             </div>
          </div>
        </div>

        {/* PAGE 3: TERMS & POLICIES */}
        <div className="page-break" />
        <div className="p-16 space-y-10">

          {/* TERMS AND CONDITIONS */}
          <div className="space-y-6">
            <h4 className="text-2xl font-black text-slate-900 border-l-8 border-slate-900 pl-4 uppercase tracking-widest flex items-center gap-3">
               <ShieldCheck size={24}/> Terms & Conditions
            </h4>
            <ul className="space-y-2">
              {TERMS_AND_CONDITIONS.map((tc, i) => (
                <li key={i} className="flex gap-3 text-[12px] font-bold text-slate-700 leading-relaxed bg-slate-50 p-3 rounded-xl border border-slate-100">
                  <span className="text-blue-600 font-black">•</span> {tc}
                </li>
              ))}
            </ul>
          </div>

          <div className="grid grid-cols-1 gap-10">
            {/* PAYMENT TERMS */}
            <div className="space-y-6">
              <h4 className="text-2xl font-black text-slate-900 border-l-8 border-blue-600 pl-4 uppercase tracking-widest flex items-center gap-3">
                 <Wallet size={24} className="text-blue-600"/> Payment Terms
              </h4>
              <ul className="space-y-2">
                {PAYMENT_TERMS.map((pt, i) => (
                  <li key={i} className="flex gap-3 text-[12px] font-bold text-slate-700 leading-relaxed bg-blue-50/50 p-3 rounded-xl border border-blue-100">
                    <span className="text-blue-600 font-black">•</span> {pt}
                  </li>
                ))}
              </ul>
            </div>

            {/* CANCELLATION POLICY */}
            <div className="space-y-6">
              <h4 className="text-2xl font-black text-slate-900 border-l-8 border-rose-600 pl-4 uppercase tracking-widest flex items-center gap-3">
                 <AlertTriangle size={24} className="text-rose-600"/> Cancellation Policy
              </h4>
              <div className="p-6 bg-rose-50 border border-rose-100 rounded-2xl">
                 <p className="text-[12px] font-black text-rose-900 uppercase tracking-wide leading-relaxed">
                    {CANCELLATION_POLICY[0]}
                 </p>
              </div>
            </div>

            {/* REFUND POLICY */}
            <div className="space-y-6">
              <h4 className="text-2xl font-black text-slate-900 border-l-8 border-emerald-600 pl-4 uppercase tracking-widest flex items-center gap-3">
                 <RotateCcw size={24} className="text-emerald-600"/> Refund Policy
              </h4>
              <div className="p-6 bg-emerald-50 border border-emerald-100 rounded-2xl">
                 <p className="text-[12px] font-bold text-emerald-900 leading-relaxed italic">
                    {REFUND_POLICY[0]}
                 </p>
              </div>
            </div>
          </div>

          {/* FINAL BRANDING FOOTER */}
          <div className="pt-10 border-t-2 border-slate-100">
            <footer className="flex justify-between items-end">
              <div className="space-y-4">
                <h2 className="text-5xl font-black text-slate-900 tracking-tighter uppercase leading-none">{BRAND_CONFIG.name}</h2>
                <div className="space-y-1 text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">
                  <p>{BRAND_CONFIG.phone} • {BRAND_CONFIG.email}</p>
                  <p>{BRAND_CONFIG.address}</p>
                </div>
              </div>
              <div className="bg-slate-900 p-8 rounded-[40px] text-white shadow-xl">
                 <svg width="40" height="40" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round">
                  <path d="m8 3 4 8 5-5 5 15H2L8 3z"/>
                </svg>
              </div>
            </footer>
          </div>
        </div>

      </div>
    </div>
  );
};

