const ClientItinerary: React.FC = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const [trip, setTrip] = useState<Trip | null>(null);
  const [isGenerating, setIsGenerating] = useState(false);
  const printableRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const savedTrips = localStorage.getItem('et_trips');
    let foundTrip: Trip | undefined;
    if (savedTrips) {
      const parsed = JSON.parse(savedTrips);
      foundTrip = parsed.find((t: Trip) => t.id === id);
    }
    if (!foundTrip) {
      foundTrip = MOCK_TRIPS.find(t => t.id === id);
    }
    if (foundTrip) {
      setTrip(foundTrip);
    }
  }, [id]);

  const masterHotels = useMemo(() => {
    const saved = localStorage.getItem('et_hotels');
    const custom = saved ? JSON.parse(saved) : [];
    return [...HOTELS, ...custom];
  }, []);

  const tieredAccommodationRows = useMemo(() => {
    if (!trip || !trip.hotelTiers) return [];
    return trip.hotelTiers.map(tier => {
      const sigHotel = masterHotels.find(h => h.id === tier.signatureHotelId);
      const eltHotel = masterHotels.find(h => h.id === tier.eliteHotelId);
      const prmHotel = masterHotels.find(h => h.id === tier.primeHotelId);

      return {
        location: tier.location,
        signature: sigHotel?.name || 'Standard Deluxe',
        elite: eltHotel?.name || 'Premium Deluxe',
        prime: prmHotel?.name || 'Super Luxury'
      };
    });
  }, [trip, masterHotels]);

  const stayDistribution = useMemo(() => {
    if (!trip || trip.itinerary.length < 2) return [];
    const dist: { location: string; nights: number }[] = [];
    let currentLocation: string | undefined = undefined;
    let currentCount = 0;

    const stayDays = trip.itinerary.slice(0, -1);

    stayDays.forEach((day, idx) => {
      const dayLoc = day.location || masterHotels.find(h => h.id === day.hotelId)?.location || 'Srinagar';

      if (dayLoc === currentLocation) {
        currentCount++;
      } else {
        if (currentLocation) {
          dist.push({ location: currentLocation, nights: currentCount });
        }
        currentLocation = dayLoc;
        currentCount = 1;
      }

      if (idx === stayDays.length - 1 && currentLocation) {
        dist.push({ location: currentLocation, nights: currentCount });
      }
    });
    return dist;
  }, [trip, masterHotels]);

  const handleDownloadPdf = async () => {
    if (!trip || !printableRef.current || isGenerating) return;
    setIsGenerating(true);
    try {
      const h2p = (window as any).html2pdf;
      const element = printableRef.current;
      const opt = {
        margin: [0, 0, 0, 0],
        filename: `${trip.client.name}_EscapeTheory_Kashmir.pdf`,
        image: { type: 'jpeg', quality: 0.98 },
        html2canvas: { scale: 2, useCORS: true },
        jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' },
        pagebreak: { mode: ['avoid-all', 'css', 'legacy'] }
      };
      await h2p().from(element).set(opt).save();
    } catch (err) {
      console.error(err);
      alert("PDF Error. Try browser print.");
    } finally {
      setIsGenerating(false);
    }
  };

  if (!trip) return <div className="p-20 text-center font-black text-slate-400">LOADING PROPOSAL...</div>;

  const durationNights = Math.max(0, trip.itinerary.length - 1);
  const durationDays = trip.itinerary.length;

  // Luxury Accents
  const goldHex = "#94724d";
  const midnightHex = "#0f172a";

  return (
    <div className="bg-slate-900 min-h-screen text-slate-900 print:bg-white overflow-x-hidden pb-20">
      {/* Tool Bar */}
      <div className="no-print sticky top-0 bg-white/95 backdrop-blur-md border-b border-slate-200 z-[100] p-4 flex justify-between items-center px-10 shadow-lg">
        <button onClick={() => navigate(`/trips/${id}`)} className="text-slate-500 font-bold flex items-center gap-2 hover:text-slate-900 transition-colors">
          <ArrowLeft size={18} /> BACK TO BUILDER
        </button>
        <div className="flex gap-4">
          <button onClick={() => window.print()} className="bg-white border border-slate-200 px-6 py-2.5 rounded-xl font-bold flex items-center gap-2 shadow-sm hover:bg-slate-50">
            <Printer size={18} /> PRINT
          </button>
          <button onClick={handleDownloadPdf} disabled={isGenerating} className="bg-slate-900 text-white px-8 py-2.5 rounded-xl font-bold flex items-center gap-2 shadow-xl hover:bg-black transition-all">
            {isGenerating ? <Loader2 size={18} className="animate-spin" /> : <Download size={18} />}
            {isGenerating ? 'GENERATING...' : 'EXPORT LUXURY PDF'}
          </button>
        </div>
      </div>

      {/* Proposal Document */}
      <div className="max-w-[210mm] mx-auto bg-[#fdfcfb] shadow-2xl my-10 print:my-0 print:shadow-none" ref={printableRef}>

        {/* PAGE 1: COVER & DYNAMIC TIERED TABLE */}
        <div className="p-16 space-y-12">
          {/* Cover Section */}
          <div className="w-full h-[130mm] rounded-[20px] overflow-hidden relative shadow-2xl border-4 border-white">
            <img src="https://images.unsplash.com/photo-1590490360182-c33d57733427?auto=format&fit=crop&q=80&w=1600" className="w-full h-full object-cover" alt="Kashmir" />
            <div className="absolute inset-0 bg-gradient-to-t from-black/80 via-black/20 to-transparent" />

            <div className="absolute top-10 left-10 flex items-center gap-3">
              <div className="p-2 bg-white/20 backdrop-blur-md rounded-lg">
                <Mountain className="text-white" size={32} />
              </div>
              <h1 className="text-white font-serif-luxury text-2xl tracking-widest uppercase">Escape Theory</h1>
            </div>

            <div className="absolute bottom-12 left-12 right-12 text-white">
              <p className="text-[#c5a059] font-black uppercase tracking-[0.4em] mb-4 text-xs">Curated Travel Experience</p>
              <h2 className="text-7xl font-serif-luxury tracking-tighter leading-none mb-6 italic">The Kashmiri Legacy</h2>
              <div className="h-0.5 w-24 bg-[#c5a059] mb-8" />
              <div className="flex justify-between items-end">
                <div className="space-y-1">
                  <p className="text-slate-300 font-bold uppercase tracking-widest text-[10px]">Prepared exclusively for</p>
                  <p className="text-3xl font-serif-luxury">{trip.client.name}</p>
                </div>
                <div className="text-right">
                  <p className="text-slate-300 font-bold uppercase tracking-widest text-[10px]">Expedition Period</p>
                  <p className="text-lg font-serif-luxury">{new Date(trip.startDate).toLocaleDateString('en-GB', { month: 'long', year: 'numeric' })}</p>
                </div>
              </div>
            </div>
          </div>

          <div className="space-y-4 pt-4 border-t border-slate-200">
            <h2 className="text-4xl font-serif-luxury text-[#0f172a] italic leading-tight">Dear {trip.client.name},</h2>
            <p className="text-lg font-garamond italic text-slate-600 leading-relaxed">
              It is our privilege to invite you on a journey through the "Paradise on Earth." At <span className="text-[#94724d] font-bold">Escape Theory Kashmir</span>, we don't just book trips; we craft legacies of Himalayan memories.
            </p>
          </div>

          <div className="space-y-6">
            <div className="flex items-center gap-4">
              <h3 className="text-2xl font-serif-luxury text-slate-900 uppercase tracking-tighter">
                Tour {durationNights}/{durationDays} Days
              </h3>
              <div className="flex-1 h-px bg-[#c5a059]/30" />
            </div>

            <div className="flex flex-wrap gap-4">
              <div className="bg-slate-900 text-white px-6 py-3 rounded-full shadow-lg flex items-center gap-3">
                 <Moon size={16} className="text-[#c5a059]" />
                 <div className="flex items-center gap-2 text-[10px] font-bold uppercase tracking-widest divide-x divide-white/20">
                   {stayDistribution.map((dist, i) => (
                     <span key={i} className={i > 0 ? 'pl-2' : ''}>
                       {dist.nights} {dist.location}
                     </span>
                   ))}
                 </div>
              </div>
            </div>

            <p className="text-sm font-garamond text-slate-700 italic border-l-2 border-[#c5a059] pl-4">
              {trip.itinerary.map(d => d.title.split(':')[0]).join(' • ')}
            </p>
          </div>

          {/* DYNAMIC TIERED ACCOMMODATION TABLE */}
          <div className="space-y-6 pt-6">
            <h4 className="text-xl font-serif-luxury text-slate-900 flex items-center gap-4 uppercase tracking-tighter">
               Curated Residences
            </h4>
            <div className="overflow-hidden border border-slate-200 rounded-lg shadow-sm">
              <table className="w-full text-left border-collapse bg-white">
                <thead className="bg-slate-50 border-b border-slate-200 text-[10px] font-black uppercase text-slate-500">
                  <tr>
                    <th className="px-6 py-5">Destination</th>
                    <th className="px-6 py-5 text-[#0f172a]">Signature</th>
                    <th className="px-6 py-5 text-[#94724d] bg-[#fdfcfb]">Elite Tier</th>
                    <th className="px-6 py-5 text-[#0f172a]">Prime Tier</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-slate-100 text-[13px] font-medium text-slate-700 font-garamond">
                  {tieredAccommodationRows.length > 0 ? tieredAccommodationRows.map((row, i) => (
                    <tr key={i} className="hover:bg-slate-50/50 transition-colors">
                      <td className="px-6 py-5 font-bold text-slate-900 uppercase tracking-wider text-[11px] font-serif-luxury">{row.location}</td>
                      <td className="px-6 py-5 italic">{row.signature}</td>
                      <td className="px-6 py-5 bg-[#fdfcfb] font-bold text-[#94724d] italic">{row.elite}</td>
                      <td className="px-6 py-5 italic">{row.prime}</td>
                    </tr>
                  )) : (
                    <tr className="italic text-slate-400">
                      <td className="px-6 py-5" colSpan={4}>Hotel configurations pending.</td>
                    </tr>
                  )}
                  <tr className="font-serif-luxury text-xl bg-[#0f172a] text-white">
                    <td className="px-6 py-6 italic text-[14px]">Total Proposal Value</td>
                    <td className="px-6 py-6 text-center">₹{(trip.tierPrices?.signature || 0).toLocaleString()}*</td>
                    <td className="px-6 py-6 text-center border-x border-white/10 text-[#c5a059] bg-slate-800">₹{(trip.tierPrices?.elite || 0).toLocaleString()}*</td>
                    <td className="px-6 py-6 text-center">₹{(trip.tierPrices?.prime || 0).toLocaleString()}*</td>
                  </tr>
                </tbody>
              </table>
            </div>
            <p className="text-[9px] text-slate-400 font-bold italic uppercase tracking-[0.2em] text-center">
              *All inclusive pricing for {(trip.pax || 2)} persons. Subject to availability at the time of final booking.
            </p>
          </div>
        </div>

        {/* PAGE 2: DAY WISE SUMMARY */}
        <div className="page-break" />
        <div className="p-16 space-y-12">
           <div className="flex items-center justify-between border-b-2 border-[#c5a059]/20 pb-6">
              <h4 className="text-3xl font-serif-luxury text-slate-900 tracking-tighter uppercase italic">
                Daily Expeditions
              </h4>
              <Compass size={28} className="text-[#c5a059]" />
           </div>

           <div className="space-y-10">
              {trip.itinerary.map((day, idx) => {
                const hotel = masterHotels.find(h => h.id === day.hotelId);
                const dayActivities = (day.activityIds || []).map(aid => ACTIVITIES.find(a => a.id === aid)?.name);
                const isDepartureDay = idx === trip.itinerary.length - 1;

                return (
                  <div key={idx} className="grid grid-cols-12 gap-8 items-start group">
                    <div className="col-span-2 text-right pt-1">
