    const saved = localStorage.getItem('et_leads');
    return saved ? JSON.parse(saved) : MOCK_LEADS;
  }, []);

  const pendingFollowups = useMemo(() => {
    const list: any[] = [];
    leads.forEach(l => {
      l.followUps.filter(f => f.status === 'Pending' && !tasksDone.has(f.id)).forEach(f => {
        list.push({ ...f, leadName: l.name, leadId: l.id });
      });
    });
    return list.sort((a, b) => a.date.localeCompare(b.date)).slice(0, 4);
  }, [leads, tasksDone]);

  const filteredLeads = useMemo(() => {
    let result = leads;
    if (filterSource) {
      result = result.filter(l => l.source === filterSource);
    }
    if (activeStat === 'leads') {
      // Just show all (default)
    } else if (activeStat === 'priority') {
      result = result.filter(l => l.score === 'Hot');
    } else if (activeStat === 'conversion') {
      result = result.filter(l => l.stage === LeadStage.BOOKED);
    }
    return result.slice(0, 6);
  }, [leads, filterSource, activeStat]);

  const attentionLeads = useMemo(() => {
    const now = new Date();
    return leads.filter(l => {
      const lastUpdate = l.updatedAt ? new Date(l.updatedAt) : new Date(l.createdAt);
      const hours = (now.getTime() - lastUpdate.getTime()) / (1000 * 60 * 60);
      return (l.stage === LeadStage.NEW && hours > 24) || (l.stage === LeadStage.PROPOSAL_SENT && hours > 48);
    }).slice(0, 3);
  }, [leads]);

  const toggleTask = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    e.preventDefault();
    setTasksDone(prev => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
  };

  const handleWhatsApp = (phone: string, e: React.MouseEvent) => {
    e.stopPropagation();
    const cleanPhone = phone.replace(/\D/g, '');
    window.open(`https://wa.me/${cleanPhone}`, '_blank');
  };

  const handleCall = (phone: string, e: React.MouseEvent) => {
    e.stopPropagation();
    window.location.href = `tel:${phone}`;
  };

  const resetFilters = () => {
    setFilterSource(null);
    setActiveStat(null);
  };

  return (
