      {/* Interactive Stat Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard 
          label="Lead Acquisition" 
          value={leads.length} 
          icon={Users} 
          color="bg-[#CFCAC2]" 
          trend="+12%" 
          isActive={activeStat === 'leads'}
          onClick={() => setActiveStat(activeStat === 'leads' ? null : 'leads')}
        />
        <StatCard 
          label="Market Value" 
