const Dashboard: React.FC = () => {
  const navigate = useNavigate();
  const [filterSource, setFilterSource] = useState<string | null>(null);
  const [activeStat, setActiveStat] = useState<string | null>(null);
  const [filterMonth, setFilterMonth] = useState<string | null>(null);
  const [dashboardSearch, setDashboardSearch] = useState('');
  const [tasksDone, setTasksDone] = useState<Set<string>>(new Set());
  const [snoozedTasks, setSnoozedTasks] = useState<Set<string>>(new Set());

  const leads: Lead[] = useMemo(() => {
    const saved = localStorage.getItem('et_leads');
    return saved ? JSON.parse(saved) : MOCK_LEADS;
  }, []);

  const pendingFollowups = useMemo(() => {
    const list: any[] = [];
    leads.forEach(l => {
      l.followUps.filter(f => f.status === 'Pending' && !tasksDone.has(f.id)).forEach(f => {
        list.push({ ...f, leadName: l.name, leadId: l.id });
      });
    });
    return list.sort((a, b) => a.date.localeCompare(b.date)).slice(0, 4);
  }, [leads, tasksDone]);

  const filteredLeads = useMemo(() => {
    let result = leads;

    // Global Dashboard Search
    if (dashboardSearch) {
      const s = dashboardSearch.toLowerCase();
      result = result.filter(l => l.name.toLowerCase().includes(s) || l.email.toLowerCase().includes(s));
    }

    // Source Filter from Pie Chart
    if (filterSource) {
      result = result.filter(l => l.source === filterSource);
    }

    // Month Filter from Area Chart
    if (filterMonth) {
      // Mapping Jan, Feb etc to full months
      const monthMap: any = { 'Jan': 'January', 'Feb': 'February', 'Mar': 'March', 'Apr': 'April', 'May': 'May', 'Jun': 'June' };
      const targetMonth = monthMap[filterMonth];
      result = result.filter(l => l.travelMonth === targetMonth);
    }

    // Stat Card Filters
    if (activeStat === 'leads') {
      // Just show all
    } else if (activeStat === 'priority') {
      result = result.filter(l => l.score === 'Hot');
    } else if (activeStat === 'conversion') {
      result = result.filter(l => l.stage === LeadStage.BOOKED);
    } else if (activeStat === 'tasks') {
      const leadIdsWithTasks = new Set(pendingFollowups.map(f => f.leadId));
      result = result.filter(l => leadIdsWithTasks.has(l.id));
    }

    return result.slice(0, 8);
  }, [leads, filterSource, activeStat, filterMonth, dashboardSearch, pendingFollowups]);

  const attentionLeads = useMemo(() => {
    const now = new Date();
    return leads.filter(l => {
      const lastUpdate = l.updatedAt ? new Date(l.updatedAt) : new Date(l.createdAt);
      const hours = (now.getTime() - lastUpdate.getTime()) / (1000 * 60 * 60);
      return (l.stage === LeadStage.NEW && hours > 24) || (l.stage === LeadStage.PROPOSAL_SENT && hours > 48);
    }).slice(0, 3);
  }, [leads]);

  const toggleTask = (id: string, e: React.MouseEvent) => {
    e.stopPropagation();
    e.preventDefault();
    setTasksDone(prev => {
      const next = new Set(prev);
      if (next.has(id)) next.delete(id);
      else next.add(id);
      return next;
    });
