    } else if (activeStat === 'conversion') {
      result = result.filter(l => l.stage === LeadStage.BOOKED);
    } else if (activeStat === 'tasks') {
      const idsWithTasks = new Set(pendingFollowups.map(f => f.leadId));
      result = result.filter(l => idsWithTasks.has(l.id));
