                      <Edit2 size={16} />
                    </button>
                    <button 
                      onClick={() => handleWhatsApp(lead.phone)}
                      className="p-2.5 bg-white border border-slate-200 text-slate-400 hover:text-emerald-500 rounded-xl shadow-sm transition-all active:scale-90" 
                      title="WhatsApp Client"
                    >
                      <MessageSquare size={16} />
                    </button>
                    <button 
                      onClick={() => updateLeadField(lead.id, 'stage', LeadStage.LOST)}
                      className="p-2.5 bg-white border border-slate-200 text-slate-400 hover:text-rose-500 rounded-xl shadow-sm transition-all active:scale-90" 
                      title="Mark as Lost"
                    >
                      <Trash2 size={16} />
                    </button>
                    <Link to={`/leads/${lead.id}`} className="p-2.5 bg-slate-900 text-white rounded-xl shadow-xl shadow-slate-900/10 hover:bg-blue-600 transition-all active:scale-90">
                      <ChevronRight size={18} />
                    </Link>
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
        {filteredLeads.length === 0 && (
          <div className="py-32 text-center flex flex-col items-center gap-4 opacity-30">
            <Search size={64} />
            <div>
              <p className="text-sm font-black uppercase tracking-widest text-slate-900">No matching leads found</p>
              <p className="text-xs font-bold mt-1">Try adjusting your filters or search terms.</p>
            </div>
          </div>
        )}
      </div>

      {/* Edit Lead Modal */}
      {isEditModalOpen && editingLead && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[110] flex items-center justify-center p-4">
          <div className="bg-white rounded-[48px] shadow-2xl w-full max-w-2xl overflow-hidden animate-in zoom-in-95 duration-200">
             <div className="bg-slate-950 p-8 text-white flex justify-between items-center">
                <div className="flex items-center gap-4">
                   <div className="bg-blue-600 p-3 rounded-2xl">
                      <Edit2 size={24}/>
                   </div>
                   <div>
                      <h2 className="text-xl font-black tracking-tight">Edit Lead: {editingLead.name}</h2>
                      <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Update Client Portfolio</p>
                   </div>
                </div>
                <button onClick={() => setIsEditModalOpen(false)} className="text-slate-500 hover:text-white transition-colors"><X size={24}/></button>
             </div>

             <form onSubmit={handleEditSubmit} className="p-10 space-y-8 max-h-[70vh] overflow-y-auto custom-scrollbar">
                <div className="grid grid-cols-2 gap-6">
                   <div className="space-y-1">
                      <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">Full Name</label>
                      <input required type="text" className="w-full p-4 bg-slate-50 border border-slate-200 rounded-2xl font-bold outline-none text-slate-900" value={editingLead.name} onChange={e => setEditingLead({...editingLead, name: e.target.value})} />
                   </div>
                   <div className="space-y-1">
                      <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">Phone</label>
                      <input required type="text" className="w-full p-4 bg-slate-50 border border-slate-200 rounded-2xl font-bold outline-none text-slate-900" value={editingLead.phone} onChange={e => setEditingLead({...editingLead, phone: e.target.value})} />
                   </div>
                </div>

                <div className="grid grid-cols-2 gap-6">
                   <div className="space-y-1">
                      <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">Email</label>
                      <input type="email" className="w-full p-4 bg-slate-50 border border-slate-200 rounded-2xl font-bold outline-none text-slate-900" value={editingLead.email} onChange={e => setEditingLead({...editingLead, email: e.target.value})} />
                   </div>
                   <div className="space-y-1">
                      <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">Priority Score</label>
                      <select className="w-full p-4 bg-slate-50 border border-slate-200 rounded-2xl font-bold outline-none text-slate-900" value={editingLead.score} onChange={e => setEditingLead({...editingLead, score: e.target.value as LeadScore})}>
                         {Object.values(LeadScore).map(s => <option key={s} value={s}>{s}</option>)}
                      </select>
                   </div>
                </div>

                <div className="grid grid-cols-3 gap-4">
                   <div className="space-y-1">
                      <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">Travel Month</label>
                      <input type="text" className="w-full p-4 bg-slate-50 border border-slate-200 rounded-2xl font-bold outline-none text-slate-900" value={editingLead.travelMonth} onChange={e => setEditingLead({...editingLead, travelMonth: e.target.value})} />
                   </div>
                   <div className="space-y-1">
                      <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">Budget</label>
                      <input type="text" className="w-full p-4 bg-slate-50 border border-slate-200 rounded-2xl font-bold outline-none text-slate-900" value={editingLead.budgetRange} onChange={e => setEditingLead({...editingLead, budgetRange: e.target.value})} />
                   </div>
                   <div className="space-y-1">
                      <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">Pax</label>
                      <input type="number" className="w-full p-4 bg-slate-50 border border-slate-200 rounded-2xl font-bold outline-none text-slate-900" value={editingLead.pax} onChange={e => setEditingLead({...editingLead, pax: parseInt(e.target.value)})} />
                   </div>
                </div>

                <div className="space-y-1">
                   <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">Sales Notes</label>
                   <textarea rows={4} className="w-full p-4 bg-slate-50 border border-slate-200 rounded-2xl font-medium outline-none text-slate-900" value={editingLead.notes} onChange={e => setEditingLead({...editingLead, notes: e.target.value})} />
                </div>

                <div className="pt-4 flex gap-4">
                   <button type="button" onClick={() => setIsEditModalOpen(false)} className="flex-1 py-4 text-slate-400 font-black uppercase tracking-widest text-[10px] hover:bg-slate-50 rounded-2xl transition-all">Discard</button>
                   <button type="submit" className="flex-[2] py-4 bg-blue-600 text-white font-black uppercase tracking-widest text-[10px] rounded-2xl shadow-xl hover:bg-blue-700 transition-all flex items-center justify-center gap-2">
                      <Check size={18}/> Update Portfolio
                   </button>
                </div>
             </form>
          </div>
        </div>
      )}

      {/* AI Suggestion Display Modal */}
      {currentSuggestion && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[110] flex items-center justify-center p-4">
           <div className="bg-white rounded-[48px] shadow-2xl w-full max-w-md overflow-hidden animate-in zoom-in-95 duration-300">
              <div className="bg-blue-600 p-8 text-white text-center space-y-2">
                 <div className="w-16 h-16 bg-white/20 rounded-3xl mx-auto flex items-center justify-center mb-2">
                    <Sparkles size={32} />
                 </div>
                 <h3 className="text-xl font-black tracking-tight uppercase">AI Sales Suggestion</h3>
                 <p className="text-blue-100 text-[10px] font-bold uppercase tracking-widest">Optimized Conversion Path</p>
              </div>

              <div className="p-10 space-y-8">
                 <div className="bg-slate-50 p-6 rounded-3xl border border-slate-100 space-y-4 shadow-inner text-center">
                    <p className="text-slate-900 font-bold text-lg leading-snug">"{currentSuggestion.task}"</p>
                    <div className="flex items-center justify-center gap-2 text-[10px] font-black uppercase text-blue-600 tracking-widest">
                       <Clock size={14}/> Schedule for {currentSuggestion.daysFromNow} days from now
                    </div>
                 </div>

                 <div className="flex flex-col gap-3">
                    <button 
                      onClick={acceptSuggestion}
                      className="w-full py-4 bg-slate-900 text-white font-black uppercase tracking-[0.2em] text-[10px] rounded-2xl shadow-xl hover:bg-blue-600 transition-all active:scale-95 flex items-center justify-center gap-2"
                    >
                       <CheckCircle2 size={18}/> Accept & Schedule
                    </button>
                    <button 
                      onClick={() => setCurrentSuggestion(null)}
                      className="w-full py-4 text-slate-400 font-black uppercase tracking-widest text-[10px] hover:text-rose-500 transition-colors"
                    >
                       Ignore
                    </button>
                 </div>
              </div>
           </div>
        </div>
      )}

      {/* Bulk Message Modal */}
      {isBulkMessageModalOpen && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[110] flex items-center justify-center p-4">
           <div className="bg-white rounded-[48px] shadow-2xl w-full max-w-lg overflow-hidden animate-in zoom-in-95 duration-300">
              <div className="bg-emerald-600 p-8 text-white flex justify-between items-center">
                 <div className="flex items-center gap-4">
                    <div className="bg-white/20 p-3 rounded-2xl">
                       <Smartphone size={24}/>
                    </div>
                    <div>
                       <h2 className="text-xl font-black tracking-tight uppercase">Bulk Transmission</h2>
                       <p className="text-emerald-100 text-[10px] font-bold uppercase tracking-widest">{selectedLeads.length} Recipients Selected</p>
                    </div>
                 </div>
                 <button onClick={() => setIsBulkMessageModalOpen(false)} className="text-emerald-200 hover:text-white transition-colors"><X size={24}/></button>
              </div>

              <div className="p-10 space-y-8">
                 <div className="space-y-4">
                    <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">Select Message Template</label>
                    <div className="space-y-3">
                       {DEFAULT_TEMPLATES.map(tmp => (
                          <button 
                            key={tmp.id}
                            onClick={() => setSelectedTemplateId(tmp.id)}
                            className={`w-full p-5 rounded-[32px] text-left transition-all border flex items-center gap-4 ${
                              selectedTemplateId === tmp.id 
                              ? 'bg-emerald-50 border-emerald-200 shadow-sm' 
                              : 'bg-white border-slate-100 hover:bg-slate-50'
                            }`}
                          >
                             <div className={`p-2.5 rounded-xl ${tmp.type === 'WhatsApp' ? 'bg-emerald-100 text-emerald-600' : 'bg-blue-100 text-blue-600'}`}>
                                {tmp.type === 'WhatsApp' ? <Smartphone size={18}/> : <Mail size={18}/>}
                             </div>
                             <div className="flex-1">
                                <p className="font-black text-slate-900 text-sm">{tmp.name}</p>
                                <p className="text-[9px] font-bold text-slate-400 uppercase mt-0.5">{tmp.type} Channel</p>
                             </div>
                             {selectedTemplateId === tmp.id && <CheckCircle2 size={20} className="text-emerald-600" />}
                          </button>
                       ))}
                    </div>
                 </div>

                 <div className="p-6 bg-slate-900 rounded-[32px] text-slate-400 space-y-3">
                    <p className="text-[10px] font-black uppercase tracking-widest flex items-center gap-2">
                       <ShieldCheck size={14} className="text-emerald-500" /> Compliance Check
                    </p>
                    <p className="text-xs leading-relaxed">
                       Messages will be personalized using AI-injected variables. Only leads with verified WhatsApp opt-in status will receive the transmission.
                    </p>
                 </div>

                 <div className="flex flex-col gap-3 pt-4">
                    <button 
                      onClick={handleBulkWhatsAppSend}
                      disabled={isBulkSending}
                      className="w-full py-5 bg-emerald-600 text-white font-black uppercase tracking-[0.2em] text-[11px] rounded-3xl shadow-xl shadow-emerald-900/20 hover:bg-emerald-700 transition-all flex items-center justify-center gap-3 active:scale-95 disabled:opacity-50"
                    >
                       {isBulkSending ? <Loader2 size={18} className="animate-spin" /> : <Send size={18}/>}
                       {isBulkSending ? 'Transmitting Data...' : `Dispatch to ${selectedLeads.length} Leads`}
                    </button>
                    <button 
                      onClick={() => setIsBulkMessageModalOpen(false)}
                      className="w-full py-4 text-slate-400 font-black uppercase tracking-widest text-[10px] hover:text-slate-900 transition-colors"
                    >
                       Cancel Batch
                    </button>
                 </div>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default LeadList;

import React, { useState, useEffect, useMemo } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { 
  Search, 
  Filter, 
  Plus, 
  ChevronRight, 
  MessageSquare, 
  Phone, 
  Mail, 
  MoreVertical,
  Flame,
  TrendingUp,
  Snowflake,
  Clock,
  Calendar,
  Zap,
  CheckCircle2,
  X,
  Trash2,
  UserPlus,
  ArrowRightLeft,
  Check,
  Edit2,
  Sparkles,
  Loader2,
  Globe,
  User,
  Activity as ActivityIcon,
  Smartphone,
  Send,
  // Added ShieldCheck to resolve 'Cannot find name' error
  ShieldCheck
} from 'lucide-react';
import { Lead, LeadStage, LeadScore, TripType, FollowUp, LeadActivity } from '../types';
import { MOCK_LEADS } from '../constants';
import { suggestFollowUp } from '../services/geminiService';
import { DEFAULT_TEMPLATES, sendSimulatedMessage, saveMessageLog } from '../services/messagingService';

const SALES_TEAM = ['Adil Bakshi', 'Sajad Ahmad', 'Ishfaq Lone', 'Zaid Bhat'];

const LeadList: React.FC = () => {
  const navigate = useNavigate();
  const [leads, setLeads] = useState<Lead[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [stageFilter, setStageFilter] = useState('All');
  const [scoreFilter, setScoreFilter] = useState('All');
  const [selectedLeads, setSelectedLeads] = useState<string[]>([]);

  // Edit State
  const [editingLead, setEditingLead] = useState<Lead | null>(null);
  const [isEditModalOpen, setIsEditModalOpen] = useState(false);

  // AI Suggestion State
  const [suggestingForId, setSuggestingForId] = useState<string | null>(null);
  const [currentSuggestion, setCurrentSuggestion] = useState<{ task: string, daysFromNow: number } | null>(null);
  const [isSuggesting, setIsSuggesting] = useState(false);

  // Bulk Messaging State
  const [isBulkMessageModalOpen, setIsBulkMessageModalOpen] = useState(false);
  const [selectedTemplateId, setSelectedTemplateId] = useState(DEFAULT_TEMPLATES[0].id);
  const [isBulkSending, setIsBulkSending] = useState(false);

  useEffect(() => {
    const saved = localStorage.getItem('et_leads');
    setLeads(saved ? JSON.parse(saved) : MOCK_LEADS);
  }, []);

  const saveLeads = (updatedLeads: Lead[]) => {
    setLeads(updatedLeads);
    localStorage.setItem('et_leads', JSON.stringify(updatedLeads));
  };

  const filteredLeads = useMemo(() => {
    return leads.filter(l => {
      const matchesSearch = l.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                           l.phone.includes(searchTerm) ||
                           l.email.toLowerCase().includes(searchTerm.toLowerCase());
      const matchesStage = stageFilter === 'All' || l.stage === stageFilter;
      const matchesScore = scoreFilter === 'All' || l.score === scoreFilter;
      return matchesSearch && matchesStage && matchesScore;
    });
  }, [leads, searchTerm, stageFilter, scoreFilter]);

  const toggleSelectAll = () => {
    if (selectedLeads.length === filteredLeads.length) {
      setSelectedLeads([]);
    } else {
      setSelectedLeads(filteredLeads.map(l => l.id));
    }
  };

  const toggleSelectLead = (id: string) => {
    setSelectedLeads(prev => prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]);
  };

  const handleWhatsApp = (phone: string) => {
    const cleanPhone = phone.replace(/\D/g, '');
    window.open(`https://wa.me/${cleanPhone}`, '_blank');
  };

  const handleCall = (phone: string) => {
    window.location.href = `tel:${phone}`;
  };

  const updateLeadField = (id: string, field: keyof Lead, value: any) => {
    const updated = leads.map(l => l.id === id ? { ...l, [field]: value, updatedAt: new Date().toISOString() } : l);
    saveLeads(updated);
  };

  const handleBulkStatusUpdate = (newStage: LeadStage) => {
    const updated = leads.map(l => selectedLeads.includes(l.id) ? { ...l, stage: newStage, updatedAt: new Date().toISOString() } : l);
    saveLeads(updated);
    setSelectedLeads([]);
  };

  const handleBulkDelete = () => {
    if (window.confirm(`Are you sure you want to delete ${selectedLeads.length} leads?`)) {
      const updated = leads.filter(l => !selectedLeads.includes(l.id));
      saveLeads(updated);
      setSelectedLeads([]);
    }
  };

  const handleBulkWhatsAppSend = async () => {
    setIsBulkSending(true);
    const template = DEFAULT_TEMPLATES.find(t => t.id === selectedTemplateId);
    if (!template) return;

    const selectedLeadsData = leads.filter(l => selectedLeads.includes(l.id));

    // Process messages in parallel (simulated)
    const promises = selectedLeadsData.map(async (lead) => {
      if (!lead.whatsappOptIn && template.type === 'WhatsApp') return null;
      const log = await sendSimulatedMessage(lead, template);
      saveMessageLog(log);

      // Update individual lead activities
      const activity: LeadActivity = {
        id: `act-${Date.now()}-${lead.id}`,
        leadId: lead.id,
        type: 'MessageSent',
        timestamp: new Date().toISOString(),
        description: `Bulk ${template.type} sent: ${template.name}`
      };

      return { leadId: lead.id, activity };
    });

    const results = await Promise.all(promises);

    // Update master leads state with new activities
    const updatedLeads = leads.map(l => {
      const result = results.find(r => r?.leadId === l.id);
      if (result) {
        return {
          ...l,
          activities: [result.activity, ...(l.activities || [])],
          updatedAt: new Date().toISOString()
        };
      }
      return l;
    });

    saveLeads(updatedLeads);
    setIsBulkSending(false);
    setIsBulkMessageModalOpen(false);
    setSelectedLeads([]);
    alert(`Bulk transmission complete for ${selectedLeads.length} leads.`);
  };

  // Edit Logic
  const openEditModal = (lead: Lead) => {
    setEditingLead({ ...lead });
    setIsEditModalOpen(true);
  };

  const handleEditSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingLead) return;
    const updated = leads.map(l => l.id === editingLead.id ? { ...editingLead, updatedAt: new Date().toISOString() } : l);
    saveLeads(updated);
    setIsEditModalOpen(false);
    setEditingLead(null);
  };

  // AI Suggestion Logic
  const handleGetSuggestion = async (lead: Lead) => {
    if (isSuggesting) return;
    setSuggestingForId(lead.id);
    setIsSuggesting(true);
    setCurrentSuggestion(null);

    try {
      const suggestion = await suggestFollowUp(lead.name, lead.stage, lead.notes, lead.interest);
      setCurrentSuggestion(suggestion);
    } catch (error) {
      console.error("AI Error:", error);
      alert("AI failed to provide a suggestion. Please try again.");
      setSuggestingForId(null);
    } finally {
      setIsSuggesting(false);
    }
  };

  const acceptSuggestion = () => {
    if (!suggestingForId || !currentSuggestion) return;

    const lead = leads.find(l => l.id === suggestingForId);
    if (!lead) return;

    const futureDate = new Date();
    futureDate.setDate(futureDate.getDate() + currentSuggestion.daysFromNow);

    const newFollowUp: FollowUp = {
      id: `f-${Date.now()}`,
      date: futureDate.toISOString().split('T')[0],
      status: 'Pending',
      note: currentSuggestion.task
    };

    const activity: LeadActivity = {
      id: `act-${Date.now()}`,
      leadId: lead.id,
      type: 'FollowUpCreated',
      timestamp: new Date().toISOString(),
      description: `AI Suggested Task: ${currentSuggestion.task} for ${newFollowUp.date}`
    };

    const updatedLead = {
      ...lead,
      followUps: [...lead.followUps, newFollowUp],
      activities: [activity, ...(lead.activities || [])],
      updatedAt: new Date().toISOString()
    };

    const updatedLeads = leads.map(l => l.id === lead.id ? updatedLead : l);
    saveLeads(updatedLeads);
    setSuggestingForId(null);
    setCurrentSuggestion(null);
  };

  const ScoreBadge = ({ score }: { score: LeadScore }) => {
    switch (score) {
      case LeadScore.HOT:
        return <span className="flex items-center gap-1 text-[10px] font-black uppercase text-rose-600 bg-rose-50 px-2.5 py-1 rounded-full border border-rose-100"><Flame size={12}/> Hot</span>;
      case LeadScore.WARM:
        return <span className="flex items-center gap-1 text-[10px] font-black uppercase text-amber-600 bg-amber-50 px-2.5 py-1 rounded-full border border-amber-100"><TrendingUp size={12}/> Warm</span>;
      case LeadScore.COLD:
        return <span className="flex items-center gap-1 text-[10px] font-black uppercase text-blue-600 bg-blue-50 px-2.5 py-1 rounded-full border border-blue-100"><Snowflake size={12}/> Cold</span>;
    }
  };

  return (
    <div className="space-y-8 pb-20 relative">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-slate-900">Lead Manager</h1>
          <p className="text-slate-500 text-sm">Manage client acquisitions and team assignments.</p>
        </div>
        <button 
          onClick={() => navigate('/leads/new')}
          className="bg-blue-600 text-white px-6 py-3 rounded-2xl font-black uppercase tracking-widest text-[11px] flex items-center gap-2 hover:bg-blue-700 shadow-xl shadow-blue-100 transition-all active:scale-95"
        >
          <Plus size={18} /> New Capture
        </button>
      </div>

      <div className="bg-white p-5 rounded-[32px] border border-slate-200 shadow-sm flex flex-wrap items-center gap-6">
        <div className="flex-1 min-w-[300px] relative">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
          <input 
            type="text" 
            placeholder="Search leads by name, phone, or email..." 
            className="w-full pl-12 pr-4 py-3.5 bg-slate-50 border border-slate-200 rounded-2xl text-sm font-bold outline-none focus:ring-4 focus:ring-blue-50/50 transition-all text-slate-900"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>

        <div className="flex items-center gap-4">
          <div className="flex items-center gap-2 px-4 py-2 bg-slate-50 border border-slate-200 rounded-2xl">
            <Clock size={16} className="text-slate-400" />
            <select 
              className="bg-transparent text-[10px] font-black uppercase text-slate-700 outline-none cursor-pointer"
              value={stageFilter}
              onChange={(e) => setStageFilter(e.target.value)}
            >
              <option value="All">All Stages</option>
              {Object.values(LeadStage).map(s => <option key={s} value={s}>{s}</option>)}
            </select>
          </div>

          <div className="flex items-center gap-2 px-4 py-2 bg-slate-50 border border-slate-200 rounded-2xl">
            <Zap size={16} className="text-slate-400" />
            <select 
              className="bg-transparent text-[10px] font-black uppercase text-slate-700 outline-none cursor-pointer"
              value={scoreFilter}
              onChange={(e) => setScoreFilter(e.target.value)}
            >
              <option value="All">All Priority</option>
              {Object.values(LeadScore).map(s => <option key={s} value={s}>{s}</option>)}
            </select>
          </div>

          {(searchTerm || stageFilter !== 'All' || scoreFilter !== 'All') && (
            <button 
              onClick={() => { setSearchTerm(''); setStageFilter('All'); setScoreFilter('All'); }}
              className="p-2 text-slate-400 hover:text-rose-500 transition-colors"
            >
              <X size={20} />
            </button>
          )}
        </div>
      </div>

      {/* Bulk Action Bar */}
      {selectedLeads.length > 0 && (
        <div className="fixed bottom-10 left-1/2 -translate-x-1/2 bg-slate-900 text-white px-8 py-4 rounded-3xl shadow-2xl z-[100] flex items-center gap-8 animate-in slide-in-from-bottom-4 duration-300 border border-slate-800">
          <div className="flex items-center gap-3 pr-8 border-r border-slate-800">
             <span className="bg-blue-600 text-[10px] font-black px-2.5 py-1 rounded-full uppercase tracking-widest">{selectedLeads.length} Selected</span>
          </div>
          <div className="flex items-center gap-6">
            <button 
              onClick={() => setIsBulkMessageModalOpen(true)}
              className="flex items-center gap-2 text-[10px] font-black uppercase text-emerald-400 hover:text-emerald-300 transition-colors"
            >
              <MessageSquare size={16} /> Send WhatsApp
            </button>
            <div className="flex items-center gap-3">
              <span className="text-[10px] font-black uppercase text-slate-500 tracking-widest">Update Stage</span>
              <select 
                className="bg-slate-800 border border-slate-700 rounded-xl px-3 py-1.5 text-[10px] font-bold outline-none cursor-pointer text-white"
                onChange={(e) => handleBulkStatusUpdate(e.target.value as LeadStage)}
                value=""
              >
                <option value="" disabled>Move to...</option>
                {Object.values(LeadStage).map(s => <option key={s} value={s}>{s}</option>)}
              </select>
            </div>
            <button 
              onClick={handleBulkDelete}
              className="flex items-center gap-2 text-[10px] font-black uppercase text-rose-400 hover:text-rose-300 transition-colors"
            >
              <Trash2 size={16} /> Delete
            </button>
            <button onClick={() => setSelectedLeads([])} className="p-1 hover:bg-slate-800 rounded-lg text-slate-500">
              <X size={20}/>
            </button>
          </div>
        </div>
      )}

      <div className="bg-white rounded-[40px] border border-slate-200 shadow-sm overflow-hidden">
        <table className="w-full text-left border-collapse">
          <thead>
            <tr className="bg-slate-50 text-[10px] font-black uppercase text-slate-400 tracking-[0.2em] border-b border-slate-100">
              <th className="px-8 py-5 w-10">
                <input 
                  type="checkbox" 
                  className="w-4 h-4 rounded border-slate-300 text-blue-600 focus:ring-blue-500"
                  checked={selectedLeads.length === filteredLeads.length && filteredLeads.length > 0}
                  onChange={toggleSelectAll}
                />
              </th>
              <th className="px-8 py-5">Lead Profile</th>
              <th className="px-8 py-5">Pipeline Progress</th>
              <th className="px-8 py-5">Trip Context</th>
              <th className="px-8 py-5">Assigned Agent</th>
              <th className="px-8 py-5 text-right">Actions</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-50">
            {filteredLeads.map(lead => (
              <tr key={lead.id} className={`group hover:bg-slate-50/50 transition-colors ${selectedLeads.includes(lead.id) ? 'bg-blue-50/30' : ''}`}>
                <td className="px-8 py-6">
                  <input 
                    type="checkbox" 
                    className="w-4 h-4 rounded border-slate-300 text-blue-600 focus:ring-blue-500"
                    checked={selectedLeads.includes(lead.id)}
                    onChange={() => toggleSelectLead(lead.id)}
                  />
                </td>
                <td className="px-8 py-6">
                  <div className="flex items-center gap-4">
                    <div 
                      onClick={() => navigate(`/leads/${lead.id}`)}
                      className="w-12 h-12 rounded-2xl bg-blue-50 border-2 border-white shadow-sm flex items-center justify-center font-black text-blue-600 cursor-pointer hover:bg-blue-600 hover:text-white transition-all"
                    >
                      {lead.name.split(' ').map(n => n[0]).join('')}
                    </div>
                    <div>
                      <p onClick={() => navigate(`/leads/${lead.id}`)} className="font-black text-slate-900 group-hover:text-blue-600 transition-colors cursor-pointer">{lead.name}</p>
                      <div className="flex items-center gap-2 mt-0.5">
                        <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">{lead.source}</span>
                        <span className="w-1 h-1 bg-slate-200 rounded-full" />
                        <span className="text-[10px] font-bold text-slate-300">{new Date(lead.createdAt).toLocaleDateString()}</span>
                      </div>
                    </div>
                  </div>
                </td>
                <td className="px-8 py-6">
                  <div className="flex flex-col gap-2">
                    <div className="flex gap-2 items-center">
                      <select 
                        className={`text-[9px] font-black uppercase tracking-widest px-3 py-1 rounded-lg border shadow-sm outline-none cursor-pointer appearance-none transition-all
                          ${lead.stage === LeadStage.BOOKED ? 'bg-blue-600 text-white border-blue-700' : 
                            lead.stage === LeadStage.PROPOSAL_SENT ? 'bg-emerald-50 text-emerald-600 border-emerald-100' :
                            'bg-slate-100 text-slate-600 border-slate-200 hover:bg-slate-200'}
                        `}
                        value={lead.stage}
                        onChange={(e) => updateLeadField(lead.id, 'stage', e.target.value)}
                      >
                        {Object.values(LeadStage).map(s => <option key={s} value={s}>{s}</option>)}
                      </select>
                      <ScoreBadge score={lead.score} />
                    </div>
                    <div className="flex items-center gap-3 text-slate-400">
                      <button onClick={() => handleCall(lead.phone)} className="flex items-center gap-1 text-[10px] font-bold uppercase hover:text-blue-600 transition-colors">
                        <Phone size={10}/> {lead.phone}
                      </button>
                    </div>
                  </div>
                </td>
                <td className="px-8 py-6">
                  <div className="space-y-1">
                    <p className="text-[10px] font-black text-slate-900 uppercase tracking-widest">{lead.interest} Trip</p>
                    <div className="flex items-center gap-2">
                      <span className="text-[10px] font-bold text-slate-400 uppercase flex items-center gap-1"><Calendar size={10}/> {lead.travelMonth}</span>
                      <span className="w-1 h-1 bg-slate-200 rounded-full" />
                      <span className="text-[10px] font-bold text-slate-400 uppercase flex items-center gap-1"><Zap size={10}/> ₹{lead.budgetRange}</span>
                    </div>
                  </div>
                </td>
                <td className="px-8 py-6">
                  <div className="flex items-center gap-3">
                    <img src={`https://picsum.photos/seed/${lead.assignedTo}/32/32`} className="w-8 h-8 rounded-full border-2 border-white shadow-sm" alt="Staff" />
                    <select 
                      className="bg-transparent text-[11px] font-black text-slate-700 uppercase tracking-widest outline-none cursor-pointer hover:bg-slate-100 px-2 py-1 rounded-lg transition-all"
                      value={lead.assignedTo}
                      onChange={(e) => updateLeadField(lead.id, 'assignedTo', e.target.value)}
                    >
                      {SALES_TEAM.map(member => <option key={member} value={member}>{member}</option>)}
                    </select>
                  </div>
                </td>
                <td className="px-8 py-6 text-right">
                  <div className="flex items-center justify-end gap-2 opacity-0 group-hover:opacity-100 transition-all">
                    <button 
                      onClick={() => handleGetSuggestion(lead)}
                      disabled={suggestingForId === lead.id && isSuggesting}
                      className="p-2.5 bg-white border border-slate-200 text-slate-400 hover:text-blue-600 rounded-xl shadow-sm transition-all active:scale-90" 
                      title="AI Suggest Next Action"
                    >
                      {suggestingForId === lead.id && isSuggesting ? <Loader2 size={16} className="animate-spin" /> : <Sparkles size={16} />}
                    </button>
                    <button 
                      onClick={() => openEditModal(lead)}
                      className="p-2.5 bg-white border border-slate-200 text-slate-400 hover:text-blue-500 rounded-xl shadow-sm transition-all active:scale-90" 
                      title="Edit Lead"
                    >
                      <Edit2 size={16} />
                    </button>
                    <button 
                      onClick={() => handleWhatsApp(lead.phone)}
                      className="p-2.5 bg-white border border-slate-200 text-slate-400 hover:text-emerald-500 rounded-xl shadow-sm transition-all active:scale-90" 
                      title="WhatsApp Client"
                    >
                      <MessageSquare size={16} />
                    </button>
                    <button 
                      onClick={() => updateLeadField(lead.id, 'stage', LeadStage.LOST)}
                      className="p-2.5 bg-white border border-slate-200 text-slate-400 hover:text-rose-500 rounded-xl shadow-sm transition-all active:scale-90" 
                      title="Mark as Lost"
                    >
                      <Trash2 size={16} />
                    </button>
                    <Link to={`/leads/${lead.id}`} className="p-2.5 bg-slate-900 text-white rounded-xl shadow-xl shadow-slate-900/10 hover:bg-blue-600 transition-all active:scale-90">
                      <ChevronRight size={18} />
                    </Link>
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
        {filteredLeads.length === 0 && (
          <div className="py-32 text-center flex flex-col items-center gap-4 opacity-30">
            <Search size={64} />
            <div>
              <p className="text-sm font-black uppercase tracking-widest text-slate-900">No matching leads found</p>
              <p className="text-xs font-bold mt-1">Try adjusting your filters or search terms.</p>
            </div>
          </div>
        )}
      </div>

      {/* Edit Lead Modal */}
      {isEditModalOpen && editingLead && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[110] flex items-center justify-center p-4">
          <div className="bg-white rounded-[48px] shadow-2xl w-full max-w-2xl overflow-hidden animate-in zoom-in-95 duration-200">
             <div className="bg-slate-950 p-8 text-white flex justify-between items-center">
                <div className="flex items-center gap-4">
                   <div className="bg-blue-600 p-3 rounded-2xl">
                      <Edit2 size={24}/>
                   </div>
                   <div>
                      <h2 className="text-xl font-black tracking-tight">Edit Lead: {editingLead.name}</h2>
                      <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Update Client Portfolio</p>
                   </div>
                </div>
                <button onClick={() => setIsEditModalOpen(false)} className="text-slate-500 hover:text-white transition-colors"><X size={24}/></button>
             </div>

             <form onSubmit={handleEditSubmit} className="p-10 space-y-8 max-h-[70vh] overflow-y-auto custom-scrollbar">
                <div className="grid grid-cols-2 gap-6">
                   <div className="space-y-1">
                      <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">Full Name</label>
                      <input required type="text" className="w-full p-4 bg-slate-50 border border-slate-200 rounded-2xl font-bold outline-none text-slate-900" value={editingLead.name} onChange={e => setEditingLead({...editingLead, name: e.target.value})} />
                   </div>
                   <div className="space-y-1">
                      <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">Phone</label>
                      <input required type="text" className="w-full p-4 bg-slate-50 border border-slate-200 rounded-2xl font-bold outline-none text-slate-900" value={editingLead.phone} onChange={e => setEditingLead({...editingLead, phone: e.target.value})} />
                   </div>
                </div>

                <div className="grid grid-cols-2 gap-6">
                   <div className="space-y-1">
                      <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">Email</label>
                      <input type="email" className="w-full p-4 bg-slate-50 border border-slate-200 rounded-2xl font-bold outline-none text-slate-900" value={editingLead.email} onChange={e => setEditingLead({...editingLead, email: e.target.value})} />
                   </div>
                   <div className="space-y-1">
                      <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">Priority Score</label>
                      <select className="w-full p-4 bg-slate-50 border border-slate-200 rounded-2xl font-bold outline-none text-slate-900" value={editingLead.score} onChange={e => setEditingLead({...editingLead, score: e.target.value as LeadScore})}>
                         {Object.values(LeadScore).map(s => <option key={s} value={s}>{s}</option>)}
                      </select>
                   </div>
                </div>

                <div className="grid grid-cols-3 gap-4">
                   <div className="space-y-1">
                      <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">Travel Month</label>
                      <input type="text" className="w-full p-4 bg-slate-50 border border-slate-200 rounded-2xl font-bold outline-none text-slate-900" value={editingLead.travelMonth} onChange={e => setEditingLead({...editingLead, travelMonth: e.target.value})} />
                   </div>
                   <div className="space-y-1">
                      <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">Budget</label>
                      <input type="text" className="w-full p-4 bg-slate-50 border border-slate-200 rounded-2xl font-bold outline-none text-slate-900" value={editingLead.budgetRange} onChange={e => setEditingLead({...editingLead, budgetRange: e.target.value})} />
                   </div>
                   <div className="space-y-1">
                      <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">Pax</label>
                      <input type="number" className="w-full p-4 bg-slate-50 border border-slate-200 rounded-2xl font-bold outline-none text-slate-900" value={editingLead.pax} onChange={e => setEditingLead({...editingLead, pax: parseInt(e.target.value)})} />
                   </div>
                </div>

                <div className="space-y-1">
                   <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">Sales Notes</label>
                   <textarea rows={4} className="w-full p-4 bg-slate-50 border border-slate-200 rounded-2xl font-medium outline-none text-slate-900" value={editingLead.notes} onChange={e => setEditingLead({...editingLead, notes: e.target.value})} />
                </div>

                <div className="pt-4 flex gap-4">
                   <button type="button" onClick={() => setIsEditModalOpen(false)} className="flex-1 py-4 text-slate-400 font-black uppercase tracking-widest text-[10px] hover:bg-slate-50 rounded-2xl transition-all">Discard</button>
                   <button type="submit" className="flex-[2] py-4 bg-blue-600 text-white font-black uppercase tracking-widest text-[10px] rounded-2xl shadow-xl hover:bg-blue-700 transition-all flex items-center justify-center gap-2">
                      <Check size={18}/> Update Portfolio
                   </button>
                </div>
             </form>
          </div>
        </div>
      )}

      {/* AI Suggestion Display Modal */}
      {currentSuggestion && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[110] flex items-center justify-center p-4">
           <div className="bg-white rounded-[48px] shadow-2xl w-full max-w-md overflow-hidden animate-in zoom-in-95 duration-300">
              <div className="bg-blue-600 p-8 text-white text-center space-y-2">
                 <div className="w-16 h-16 bg-white/20 rounded-3xl mx-auto flex items-center justify-center mb-2">
                    <Sparkles size={32} />
                 </div>
                 <h3 className="text-xl font-black tracking-tight uppercase">AI Sales Suggestion</h3>
                 <p className="text-blue-100 text-[10px] font-bold uppercase tracking-widest">Optimized Conversion Path</p>
              </div>

              <div className="p-10 space-y-8">
                 <div className="bg-slate-50 p-6 rounded-3xl border border-slate-100 space-y-4 shadow-inner text-center">
                    <p className="text-slate-900 font-bold text-lg leading-snug">"{currentSuggestion.task}"</p>
                    <div className="flex items-center justify-center gap-2 text-[10px] font-black uppercase text-blue-600 tracking-widest">
                       <Clock size={14}/> Schedule for {currentSuggestion.daysFromNow} days from now
                    </div>
                 </div>

                 <div className="flex flex-col gap-3">
                    <button 
                      onClick={acceptSuggestion}
                      className="w-full py-4 bg-slate-900 text-white font-black uppercase tracking-[0.2em] text-[10px] rounded-2xl shadow-xl hover:bg-blue-600 transition-all active:scale-95 flex items-center justify-center gap-2"
                    >
                       <CheckCircle2 size={18}/> Accept & Schedule
                    </button>
                    <button 
                      onClick={() => setCurrentSuggestion(null)}
                      className="w-full py-4 text-slate-400 font-black uppercase tracking-widest text-[10px] hover:text-rose-500 transition-colors"
                    >
                       Ignore
                    </button>
                 </div>
              </div>
           </div>
        </div>
      )}

      {/* Bulk Message Modal */}
      {isBulkMessageModalOpen && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[110] flex items-center justify-center p-4">
           <div className="bg-white rounded-[48px] shadow-2xl w-full max-w-lg overflow-hidden animate-in zoom-in-95 duration-300">
              <div className="bg-emerald-600 p-8 text-white flex justify-between items-center">
                 <div className="flex items-center gap-4">
                    <div className="bg-white/20 p-3 rounded-2xl">
                       <Smartphone size={24}/>
                    </div>
                    <div>
                       <h2 className="text-xl font-black tracking-tight uppercase">Bulk Transmission</h2>
                       <p className="text-emerald-100 text-[10px] font-bold uppercase tracking-widest">{selectedLeads.length} Recipients Selected</p>
                    </div>
                 </div>
                 <button onClick={() => setIsBulkMessageModalOpen(false)} className="text-emerald-200 hover:text-white transition-colors"><X size={24}/></button>
              </div>

              <div className="p-10 space-y-8">
                 <div className="space-y-4">
                    <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">Select Message Template</label>
                    <div className="space-y-3">
                       {DEFAULT_TEMPLATES.map(tmp => (
                          <button 
                            key={tmp.id}
                            onClick={() => setSelectedTemplateId(tmp.id)}
                            className={`w-full p-5 rounded-[32px] text-left transition-all border flex items-center gap-4 ${
                              selectedTemplateId === tmp.id 
                              ? 'bg-emerald-50 border-emerald-200 shadow-sm' 
                              : 'bg-white border-slate-100 hover:bg-slate-50'
                            }`}
                          >
                             <div className={`p-2.5 rounded-xl ${tmp.type === 'WhatsApp' ? 'bg-emerald-100 text-emerald-600' : 'bg-blue-100 text-blue-600'}`}>
                                {tmp.type === 'WhatsApp' ? <Smartphone size={18}/> : <Mail size={18}/>}
                             </div>
                             <div className="flex-1">
                                <p className="font-black text-slate-900 text-sm">{tmp.name}</p>
                                <p className="text-[9px] font-bold text-slate-400 uppercase mt-0.5">{tmp.type} Channel</p>
                             </div>
                             {selectedTemplateId === tmp.id && <CheckCircle2 size={20} className="text-emerald-600" />}
                          </button>
                       ))}
                    </div>
                 </div>

                 <div className="p-6 bg-slate-900 rounded-[32px] text-slate-400 space-y-3">
                    <p className="text-[10px] font-black uppercase tracking-widest flex items-center gap-2">
                       <ShieldCheck size={14} className="text-emerald-500" /> Compliance Check
                    </p>
                    <p className="text-xs leading-relaxed">
                       Messages will be personalized using AI-injected variables. Only leads with verified WhatsApp opt-in status will receive the transmission.
                    </p>
                 </div>

                 <div className="flex flex-col gap-3 pt-4">
                    <button 
                      onClick={handleBulkWhatsAppSend}
                      disabled={isBulkSending}
                      className="w-full py-5 bg-emerald-600 text-white font-black uppercase tracking-[0.2em] text-[11px] rounded-3xl shadow-xl shadow-emerald-900/20 hover:bg-emerald-700 transition-all flex items-center justify-center gap-3 active:scale-95 disabled:opacity-50"
                    >
                       {isBulkSending ? <Loader2 size={18} className="animate-spin" /> : <Send size={18}/>}
                       {isBulkSending ? 'Transmitting Data...' : `Dispatch to ${selectedLeads.length} Leads`}
                    </button>
                    <button 
                      onClick={() => setIsBulkMessageModalOpen(false)}
                      className="w-full py-4 text-slate-400 font-black uppercase tracking-widest text-[10px] hover:text-slate-900 transition-colors"
                    >
                       Cancel Batch
                    </button>
                 </div>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default LeadList;

export enum UserRole {
  ADMIN = 'ADMIN',
  SALES = 'SALES',
  OPERATIONS = 'OPERATIONS'
}

export enum LeadStage {
  NEW = 'New',
  CONTACTED = 'Contacted',
  QUALIFIED = 'Qualified',
  PROPOSAL_SENT = 'Proposal Sent',
  NEGOTIATION = 'Negotiation',
  BOOKED = 'Booked',
  LOST = 'Lost',
  CANCELLED = 'Cancelled'
}

export enum LeadScore {
  HOT = 'Hot',
  WARM = 'Warm',
  COLD = 'Cold'
}

export enum TripStatus {
  LEAD = 'Lead',
  QUOTED = 'Quoted',
  BOOKED = 'Booked',
  COMPLETED = 'Completed',
  CANCELLED = 'Cancelled'
}

export enum TripType {
  HONEYMOON = 'Honeymoon',
  FAMILY = 'Family',
  GROUP = 'Group',
  CORPORATE = 'Corporate'
}

export enum HotelCategory {
  BUDGET = 'Budget',
  DELUXE = 'Deluxe',
  LUXURY = 'Luxury',
  HOUSEBOAT = 'Houseboat'
}

export enum MealPlan {
  EP = 'EP (Room Only)',
  CP = 'CP (Room + Breakfast)',
  MAP = 'MAP (Room + BF + Dinner)',
  AP = 'AP (Room + All Meals)'
}

export interface Hotel {
  id: string;
  name: string;
  location: string;
  category: HotelCategory;
  ratePerNight: number;
  contact: string;
  gallery?: string[];
  rateValidityDate?: string;
  extraBedRate?: number;
  epRate?: number;
  cpRate?: number;
  mapRate?: number;
  apRate?: number;
  internalNotes?: string;
  hotelLink?: string;
  attachmentData?: string;
  attachmentName?: string;
  attachmentType?: string;
}

export interface Vehicle {
  id: string;
  type: string;
  brand?: string;
  capacity: number;
  ratePerDay: number;
  isAC: boolean;
  image?: string;
  fuelType?: string;
  model?: string;
  internalNotes?: string;
  providerName?: string;
  providerContact?: string;
  rateValidityDate?: string;
  features?: string[];
}

export interface Activity {
  id: string;
  name: string;
  costPerPax: number;
  description: string;
  location?: string;
  category?: string;
  duration?: string;
  internalNotes?: string;
  image?: string;
}

export interface AddOn {
  id: string;
  name: string;
  cost: number;
  isPerPax: boolean;
  description?: string;
}

export interface ItineraryDay {
  id: string;
  dayNumber: number;
  title: string;
  location?: string;
  hotelId?: string;
  mealPlan?: MealPlan;
  vehicleId?: string;
  activityIds: string[];
  highlights?: string[]; 
  clientNotes: string;
  internalNotes: string;
}

export interface MessageTemplate {
  id: string;
  name: string;
  type: 'WhatsApp' | 'Email';
  body: string;
  isActive: boolean;
  triggerStage?: LeadStage;
  delayHours?: number;
}

export interface MessageLog {
  id: string;
  leadId: string;
  type: 'WhatsApp' | 'Email';
  content: string;
  timestamp: string;
  status: 'Sent' | 'Failed' | 'Delivered';
  templateId?: string;
  errorMessage?: string;
  retryCount: number;
}

export interface ChannelSettings {
  whatsappEnabled: boolean;
  emailEnabled: boolean;
  whatsappApiKey?: string;
  sendgridApiKey?: string;
  fromEmail?: string;
}

export interface CommunicationLog {
  id: string;
  type: 'Call' | 'WhatsApp' | 'Email' | 'Note';
  timestamp: string;
  content: string;
  author: string;
}

export interface FollowUp {
  id: string;
  date: string;
  status: 'Pending' | 'Completed' | 'Snoozed';
  note: string;
  type?: 'Call' | 'WhatsApp' | 'Email';
}

export interface LeadActivity {
  id: string;
  leadId: string;
  type: 'StatusChange' | 'FollowUpCreated' | 'FollowUpCompleted' | 'ProposalSent' | 'BookingConfirmed' | 'NoteAdded' | 'MessageSent';
  timestamp: string;
  description: string;
  meta?: any;
}

export interface Lead {
  id: string;
  name: string;
  phone: string;
  email: string;
  source: string;
  interest: TripType;
  budgetRange: string;
  travelMonth: string;
  pax: number;
  assignedTo: string;
  stage: LeadStage;
  score: LeadScore;
  notes: string;
  communicationLogs: CommunicationLog[];
  followUps: FollowUp[];
  activities?: LeadActivity[];
  messageLogs?: MessageLog[];
  tripIds: string[]; 
  createdAt: string;
  updatedAt?: string;
  whatsappOptIn: boolean;
}

// Fixed missing interface: TierPrices
export interface TierPrices {
  signature: number;
  elite: number;
  prime: number;
}

// Fixed missing interface: HotelTierSelection
export interface HotelTierSelection {
  location: string;
  signatureHotelId: string;
  eliteHotelId: string;
  primeHotelId: string;
}

// Fixed missing interface: TripVersion
export interface TripVersion {
  id: string;
  timestamp: string;
  label: string;
  itinerary: ItineraryDay[];
  tierPrices: TierPrices;
}

export interface Trip {
  id: string;
  leadId: string;
  client: {
    name: string;
    phone: string;
    email: string;
    source: string;
  };
  assignedSalesperson: string;
  budgetRange: string;
  tripName: string;
  tripType: TripType;
  startDate: string;
  endDate: string;
  pax: number;
  status: TripStatus;
  itinerary: ItineraryDay[];
  marginPercentage: number; 
  tierMargins?: TierPrices; 
  addOnIds: string[];
  startLocation: 'Srinagar' | 'Jammu';
  inclusions: string[];
  exclusions: string[];
  hotelTiers?: HotelTierSelection[];
  tierPrices?: TierPrices;
  versions?: TripVersion[];
}

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { 
  Search, 
  MapPin, 
  IndianRupee, 
  Plus, 
  Activity as ActivityIcon, 
  X, 
  Check, 
  Edit2, 
  Eye, 
  Trash2, 
  Clock, 
  Layers, 
  Info,
  Camera,
  Image as ImageIcon,
  Compass,
  ArrowRight,
  ChevronRight
} from 'lucide-react';
import { ACTIVITIES } from '../constants';
import { Activity } from '../types';

const ACTIVITY_CATEGORIES = ['Sightseeing', 'Adventure', 'Cultural', 'Nature', 'Leisure'];

const Activities: React.FC = () => {
  const [searchTerm, setSearchTerm] = useState('');
  const [maxCost, setMaxCost] = useState('10000');
  const [categoryFilter, setCategoryFilter] = useState('All');
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingActivityId, setEditingActivityId] = useState<string | null>(null);
  const [viewingActivity, setViewingActivity] = useState<Activity | null>(null);
  const [customActivities, setCustomActivities] = useState<Activity[]>([]);
  const imageInputRef = useRef<HTMLInputElement>(null);

  const initialFormState: Partial<Activity> = {
    name: '',
    costPerPax: 0,
    description: '',
    location: '',
    category: 'Sightseeing',
    duration: '1 Hour',
    internalNotes: '',
    image: ''
  };

  const [formData, setFormData] = useState<Partial<Activity>>(initialFormState);

  // Persistence
  useEffect(() => {
    const saved = localStorage.getItem('et_activities');
    if (saved) setCustomActivities(JSON.parse(saved));
  }, []);

  const allActivities = useMemo(() => {
    const customIds = new Set(customActivities.map(a => a.id));
    return [...ACTIVITIES.filter(a => !customIds.has(a.id)), ...customActivities];
  }, [customActivities]);

  const filteredActivities = useMemo(() => {
    return allActivities.filter(a => {
      const matchesSearch = a.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                           (a.location?.toLowerCase().includes(searchTerm.toLowerCase()));
      const matchesCost = a.costPerPax <= parseInt(maxCost);
      const matchesCategory = categoryFilter === 'All' || a.category === categoryFilter;
      return matchesSearch && matchesCost && matchesCategory;
    });
  }, [allActivities, searchTerm, maxCost, categoryFilter]);

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setFormData(prev => ({ ...prev, image: reader.result as string }));
      };
      reader.readAsDataURL(file);
    }
  };

  const openAddModal = () => {
    setEditingActivityId(null);
    setFormData(initialFormState);
    setIsModalOpen(true);
  };

  const openEditModal = (e: React.MouseEvent, activity: Activity) => {
    e.stopPropagation();
    setEditingActivityId(activity.id);
    setFormData({ ...activity });
    setIsModalOpen(true);
    setViewingActivity(null);
  };

  const handleSaveActivity = (e: React.FormEvent) => {
    e.preventDefault();
    const activityData: Activity = {
      ...formData,
      id: editingActivityId || `a-custom-${Date.now()}`,
      name: formData.name || 'New Activity',
      costPerPax: formData.costPerPax || 0,
      description: formData.description || '',
    } as Activity;

    let updated: Activity[];
    if (editingActivityId) {
      const index = customActivities.findIndex(a => a.id === editingActivityId);
      if (index > -1) {
        updated = [...customActivities];
        updated[index] = activityData;
      } else updated = [...customActivities, activityData];
    } else updated = [...customActivities, activityData];

    setCustomActivities(updated);
    localStorage.setItem('et_activities', JSON.stringify(updated));
    setIsModalOpen(false);
  };

  const handleDelete = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (window.confirm("Permanently remove this activity from inventory?")) {
      const updated = customActivities.filter(a => a.id !== id);
      setCustomActivities(updated);
      localStorage.setItem('et_activities', JSON.stringify(updated));
      setViewingActivity(null);
    }
  };

  return (
    <div className="space-y-8 pb-20 animate-in fade-in duration-700">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-black text-slate-900 tracking-tight">Activity Catalog</h1>
          <p className="text-slate-500 text-sm">Curated experiences, excursions, and local highlights for Kashmir trips.</p>
        </div>
        <button 
          onClick={openAddModal}
          className="bg-blue-600 text-white px-6 py-3 rounded-2xl font-black uppercase tracking-widest text-[11px] flex items-center gap-2 hover:bg-blue-700 shadow-xl shadow-blue-100 transition-all active:scale-95"
        >
          <Plus size={18} /> New Activity
        </button>
      </div>

      <div className="bg-white p-6 rounded-[32px] border border-slate-200 shadow-sm flex flex-col md:flex-row gap-8 items-center">
        <div className="flex-1 relative w-full">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
          <input 
            type="text" 
            placeholder="Search activities by name or location..." 
            className="w-full pl-12 pr-4 py-3.5 bg-slate-50 border border-slate-200 rounded-2xl text-sm font-bold outline-none focus:ring-4 focus:ring-blue-50/50 transition-all text-slate-900"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>

        <div className="flex flex-wrap items-center gap-6 w-full md:w-auto">
          <div className="flex items-center gap-3">
             <div className="bg-slate-100 p-2.5 rounded-xl text-slate-500"><ActivityIcon size={16}/></div>
             <select 
               className="bg-transparent text-xs font-black uppercase tracking-widest text-slate-700 outline-none cursor-pointer"
               value={categoryFilter}
               onChange={(e) => setCategoryFilter(e.target.value)}
             >
               <option value="All">All Types</option>
               {ACTIVITY_CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
             </select>
          </div>

          <div className="flex-1 min-w-[200px] space-y-2">
            <div className="flex justify-between items-center px-1">
              <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Max Budget / PAX</label>
              <span className="text-[11px] font-black text-blue-600">₹{parseInt(maxCost).toLocaleString()}</span>
            </div>
            <input 
              type="range" 
              min="500" 
              max="20000" 
              step="500" 
              value={maxCost}
              onChange={(e) => setMaxCost(e.target.value)}
              className="w-full h-1.5 bg-slate-100 rounded-lg appearance-none cursor-pointer accent-blue-600"
            />
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-8">
        {filteredActivities.map(act => (
          <div 
            key={act.id} 
            onClick={() => setViewingActivity(act)}
            className="bg-white border border-slate-200 rounded-[36px] overflow-hidden hover:shadow-2xl hover:border-blue-100 transition-all group flex flex-col shadow-sm cursor-pointer relative"
          >
            <div className="relative h-48 bg-slate-100 overflow-hidden">
              <img 
                src={act.image || `https://picsum.photos/seed/${act.id}/600/400`} 
                className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-700 opacity-90" 
                alt={act.name} 
              />
              <div className="absolute inset-0 bg-gradient-to-t from-slate-900/40 to-transparent" />
              <div className="absolute top-4 left-4">
                <span className="px-3 py-1 bg-white/90 backdrop-blur border border-slate-200 rounded-xl text-[9px] font-black uppercase tracking-widest text-slate-700 shadow-sm">
                  {act.category || 'Sightseeing'}
                </span>
              </div>
              <div className="absolute top-4 right-4 flex flex-col gap-2 opacity-0 group-hover:opacity-100 transition-all duration-300">
                <button onClick={(e) => openEditModal(e, act)} className="p-2.5 bg-white/90 backdrop-blur rounded-2xl text-slate-400 hover:text-blue-600 hover:bg-white shadow-sm transition-all"><Edit2 size={16} /></button>
              </div>
            </div>

            <div className="p-6 flex-1 flex flex-col">
              <div className="mb-6">
                <h3 className="font-black text-slate-900 text-lg group-hover:text-blue-600 transition-colors leading-tight mb-2 truncate" title={act.name}>
                  {act.name}
                </h3>
                <div className="flex items-center gap-3">
                  <span className="flex items-center gap-1.5 text-[10px] font-black text-slate-400 uppercase tracking-widest">
                    <MapPin size={12} className="text-blue-500" />
                    {act.location || 'Kashmir'}
                  </span>
                  <span className="w-1 h-1 rounded-full bg-slate-200" />
                  <span className="flex items-center gap-1.5 text-[10px] font-black text-slate-400 uppercase tracking-widest">
                    <Clock size={12} className="text-amber-500" />
                    {act.duration || 'Flexible'}
                  </span>
                </div>
              </div>

              <p className="text-slate-500 text-xs line-clamp-2 leading-relaxed mb-6 italic font-medium">
                "{act.description}"
              </p>

              <div className="mt-auto pt-5 border-t border-slate-50 flex items-center justify-between">
                <div>
                  <span className="text-[10px] font-black uppercase text-slate-300 tracking-[0.2em] mb-1">Cost Per Guest</span>
                  <div className="text-2xl font-black text-slate-900 flex items-center gap-1">
                    <IndianRupee size={20} className="text-blue-600" />
                    {act.costPerPax.toLocaleString()}
                  </div>
                </div>
                <div className="p-3 bg-slate-50 rounded-2xl text-slate-300 group-hover:bg-blue-600 group-hover:text-white transition-all shadow-sm">
                  <ArrowRight size={20} />
                </div>
              </div>
            </div>
          </div>
        ))}
      </div>

      {filteredActivities.length === 0 && (
        <div className="bg-white p-32 rounded-[48px] border-2 border-dashed border-slate-200 text-center flex flex-col items-center gap-6">
          <div className="p-6 bg-slate-50 rounded-full text-slate-300">
             <Search size={64} />
          </div>
          <div>
             <p className="text-xl font-black text-slate-900 uppercase tracking-tight">No Experiences Found</p>
             <p className="text-slate-400 font-bold mt-1">Try adjusting your filters or search criteria.</p>
          </div>
        </div>
      )}

      {/* View Detail Modal */}
      {viewingActivity && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[110] flex items-center justify-center p-4">
          <div className="bg-white rounded-[48px] shadow-2xl w-full max-w-4xl overflow-hidden animate-in zoom-in-95 duration-200">
            <div className="h-80 relative bg-slate-900">
              <img 
                src={viewingActivity.image || `https://picsum.photos/seed/${viewingActivity.id}/1200/600`} 
                className="w-full h-full object-cover opacity-60" 
                alt={viewingActivity.name} 
              />
              <div className="absolute inset-0 bg-gradient-to-t from-slate-900 via-transparent to-transparent" />
              <button onClick={() => setViewingActivity(null)} className="absolute top-8 right-8 p-3 bg-white/10 hover:bg-white/20 backdrop-blur-md rounded-full text-white transition-all z-10"><X size={24} /></button>
              <div className="absolute bottom-10 left-10">
                <div className="flex items-center gap-3 mb-3">
                   <span className="px-4 py-1.5 bg-blue-600 text-white text-[10px] font-black uppercase tracking-[0.2em] rounded-full shadow-xl">{viewingActivity.category}</span>
                   <span className="text-blue-300 text-xs font-black uppercase tracking-widest">{viewingActivity.location}</span>
                </div>
                <h2 className="text-5xl font-black text-white leading-none tracking-tighter drop-shadow-lg">{viewingActivity.name}</h2>
              </div>
            </div>

            <div className="p-12 grid grid-cols-1 md:grid-cols-12 gap-12">
               <div className="md:col-span-7 space-y-10">
                  <div className="space-y-4">
                     <h4 className="text-[11px] font-black uppercase tracking-[0.3em] text-slate-400 flex items-center gap-3">
                        <div className="w-8 h-px bg-slate-200" /> Experience Narrative
                     </h4>
                     <p className="text-lg text-slate-700 leading-relaxed font-medium italic">
                       "{viewingActivity.description}"
                     </p>
                  </div>

                  {viewingActivity.internalNotes && (
                    <div className="bg-slate-900 p-8 rounded-[40px] text-white shadow-2xl relative overflow-hidden group">
                       <div className="absolute top-0 right-0 p-6 opacity-10 group-hover:opacity-20 transition-opacity">
                          <Info size={120} />
                       </div>
                       <h4 className="text-[10px] font-black uppercase tracking-[0.3em] text-blue-400 mb-4 flex items-center gap-2">
                          <Info size={14} /> Operations Context
                       </h4>
                       <p className="text-base text-slate-300 leading-relaxed font-bold relative z-10">
                         {viewingActivity.internalNotes}
                       </p>
                    </div>
                  )}
               </div>

               <div className="md:col-span-5 space-y-6">
                  <div className="bg-slate-50 p-8 rounded-[48px] border border-slate-100 space-y-8 shadow-sm">
                     <div className="space-y-2">
                        <p className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">Standard Net Rate</p>
                        <div className="text-4xl font-black text-slate-900 flex items-center gap-1.5">
                           <IndianRupee size={32} className="text-blue-600" />
                           {viewingActivity.costPerPax.toLocaleString()}
                           <span className="text-[10px] text-slate-300 font-black uppercase ml-2 tracking-widest">/ Guest</span>
                        </div>
                     </div>

                     <div className="space-y-4 pt-4 border-t border-slate-200">
                        <div className="flex items-center justify-between p-4 bg-white rounded-2xl shadow-sm">
                           <span className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Time Required</span>
                           <span className="text-sm font-black text-slate-900 flex items-center gap-2"><Clock size={16} className="text-amber-500" /> {viewingActivity.duration}</span>
                        </div>
                        <div className="flex items-center justify-between p-4 bg-white rounded-2xl shadow-sm">
                           <span className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Primary Hub</span>
                           <span className="text-sm font-black text-slate-900 flex items-center gap-2"><MapPin size={16} className="text-blue-500" /> {viewingActivity.location}</span>
                        </div>
                     </div>

                     <div className="pt-6 flex flex-col gap-3">
                        <button 
                          onClick={(e) => openEditModal(e, viewingActivity)}
                          className="w-full py-4 bg-slate-950 text-white rounded-2xl font-black uppercase tracking-[0.2em] text-[10px] shadow-xl hover:bg-blue-600 transition-all flex items-center justify-center gap-2 active:scale-95"
                        >
                           <Edit2 size={16}/> Modify Experience
                        </button>
                        <button 
                          onClick={(e) => handleDelete(e, viewingActivity.id)}
                          className="w-full py-4 text-rose-600 font-black uppercase tracking-[0.2em] text-[10px] hover:bg-rose-50 rounded-2xl transition-all"
                        >
                           Remove from Hub
                        </button>
                     </div>
                  </div>
               </div>
            </div>
          </div>
        </div>
      )}

      {/* Add/Edit Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[110] flex items-center justify-center p-4 overflow-y-auto">
          <div className="bg-white rounded-[48px] shadow-2xl w-full max-w-3xl my-8 overflow-hidden animate-in zoom-in-95 duration-200">
            <div className="bg-white p-8 border-b border-slate-50 flex items-center justify-between sticky top-0 z-10">
              <div className="flex items-center gap-4">
                <div className="bg-blue-600 p-3 rounded-2xl text-white shadow-xl shadow-blue-100">
                  {editingActivityId ? <Edit2 size={24} /> : <Compass size={24} />}
                </div>
                <div>
                  <h3 className="text-xl font-black text-slate-900 tracking-tight">{editingActivityId ? 'Modify Experience Hub' : 'Register New Experience'}</h3>
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.3em]">Curatorial Database Entry</p>
                </div>
              </div>
              <button 
                onClick={() => setIsModalOpen(false)}
                className="p-3 hover:bg-slate-50 rounded-full transition-colors text-slate-300 hover:text-slate-900"
              >
                <X size={24} />
              </button>
            </div>

            <form onSubmit={handleSaveActivity} className="p-10 space-y-12">
               {/* Image Picker */}
               <div className="space-y-6">
                  <h4 className="text-[11px] font-black uppercase tracking-[0.2em] text-blue-600 border-b border-blue-50 pb-3 flex items-center gap-2">
                    <Camera size={14} /> Catalog Visualization
                  </h4>
                  <div className="w-full h-64 rounded-[40px] bg-slate-50 border-2 border-dashed border-slate-200 overflow-hidden relative group transition-all hover:border-blue-400 hover:bg-blue-50/30">
                    {formData.image ? (
                      <>
                        <img src={formData.image} className="w-full h-full object-cover" alt="Preview" />
                        <div className="absolute inset-0 bg-black/40 opacity-0 group-hover:opacity-100 transition-opacity flex items-center justify-center">
                          <button 
                            type="button"
                            onClick={() => setFormData({ ...formData, image: '' })}
                            className="bg-white text-rose-600 p-4 rounded-full shadow-2xl hover:scale-110 transition-transform"
                          >
                            <Trash2 size={24} />
                          </button>
                        </div>
                      </>
                    ) : (
                      <button 
                        type="button"
                        onClick={() => imageInputRef.current?.click()}
                        className="w-full h-full flex flex-col items-center justify-center text-slate-300 gap-4"
                      >
                        <div className="bg-white p-5 rounded-3xl shadow-lg border border-slate-100 text-blue-600">
                          <ImageIcon size={48} />
                        </div>
                        <div className="text-center">
                          <p className="text-sm font-black text-slate-600 uppercase tracking-widest">Select Catalog Image</p>
                          <p className="text-[10px] font-bold text-slate-400 mt-1 uppercase tracking-widest">High-quality Landscape Shots Preferred</p>
                        </div>
                      </button>
                    )}
                  </div>
                  <input type="file" ref={imageInputRef} className="hidden" accept="image/*" onChange={handleImageUpload} />
               </div>

               <div className="space-y-8">
                  <h4 className="text-[11px] font-black uppercase tracking-[0.2em] text-blue-600 border-b border-blue-50 pb-3">Core Particulars</h4>
                  <div className="grid grid-cols-2 gap-8">
                     <div className="col-span-2 space-y-2">
                        <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">Activity Name</label>
                        <input required type="text" className="w-full px-5 py-4 bg-slate-50 border border-slate-200 rounded-2xl text-base font-black text-slate-900 outline-none focus:ring-4 focus:ring-blue-50/50 transition-all shadow-inner" placeholder="e.g. Shikara Ride on Dal Lake" value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} />
                     </div>
                     <div className="space-y-2">
                        <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">Primary Hub (Location)</label>
                        <input required type="text" className="w-full px-5 py-3.5 bg-slate-50 border border-slate-200 rounded-2xl text-sm font-bold text-slate-900 outline-none" placeholder="e.g. Srinagar" value={formData.location} onChange={e => setFormData({...formData, location: e.target.value})} />
                     </div>
                     <div className="space-y-2">
                        <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">Category</label>
                        <select className="w-full px-5 py-3.5 bg-slate-50 border border-slate-200 rounded-2xl text-sm font-black uppercase tracking-widest text-slate-700 outline-none cursor-pointer shadow-sm" value={formData.category} onChange={e => setFormData({...formData, category: e.target.value})}>
                           {ACTIVITY_CATEGORIES.map(c => <option key={c} value={c}>{c}</option>)}
                        </select>
                     </div>
                  </div>
               </div>

               <div className="space-y-8">
                  <h4 className="text-[11px] font-black uppercase tracking-[0.2em] text-blue-600 border-b border-blue-50 pb-3">Operational Logistics</h4>
                  <div className="grid grid-cols-2 gap-8">
                     <div className="space-y-2">
                        <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">Standard Duration</label>
                        <input type="text" className="w-full px-5 py-3.5 bg-slate-50 border border-slate-200 rounded-2xl text-sm font-bold text-slate-900 outline-none" placeholder="e.g. 1.5 Hours" value={formData.duration} onChange={e => setFormData({...formData, duration: e.target.value})} />
                     </div>
                     <div className="space-y-2">
                        <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">Net Cost / PAX</label>
                        <div className="relative">
                           <div className="absolute left-4 top-1/2 -translate-y-1/2 text-blue-600 font-black">₹</div>
                           <input required type="number" className="w-full pl-10 pr-4 py-3.5 bg-blue-50 border border-blue-100 rounded-2xl text-base font-black text-blue-900 outline-none" value={formData.costPerPax || ''} onChange={e => setFormData({...formData, costPerPax: parseInt(e.target.value) || 0})} />
                        </div>
                     </div>
                  </div>
               </div>

               <div className="space-y-8">
                  <h4 className="text-[11px] font-black uppercase tracking-[0.2em] text-blue-600 border-b border-blue-50 pb-3">Descriptive Metadata</h4>
                  <div className="space-y-6">
                     <div className="space-y-2">
                        <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">Client Narrative (Public)</label>
                        <textarea rows={4} className="w-full p-6 bg-slate-50 border border-slate-200 rounded-[32px] text-sm font-medium leading-relaxed text-slate-700 outline-none shadow-inner" placeholder="Briefly describe the guest experience..." value={formData.description} onChange={e => setFormData({...formData, description: e.target.value})} />
                     </div>
                     <div className="space-y-2">
                        <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">Internal Logistical Notes (Hidden)</label>
                        <textarea rows={3} className="w-full p-6 bg-slate-50 border border-slate-200 rounded-[32px] text-sm font-bold leading-relaxed text-slate-600 outline-none shadow-inner italic" placeholder="Add provider details, seasonal restrictions, or booking tips..." value={formData.internalNotes} onChange={e => setFormData({...formData, internalNotes: e.target.value})} />
                     </div>
                  </div>
               </div>

               <div className="pt-8 flex gap-6 border-t border-slate-50">
                  <button type="button" onClick={() => setIsModalOpen(false)} className="flex-1 py-5 text-slate-400 font-black uppercase tracking-widest text-[11px] hover:bg-slate-50 rounded-2xl transition-all">Discard</button>
                  <button type="submit" className="flex-[2] py-5 bg-blue-600 text-white font-black uppercase tracking-[0.2em] text-[11px] rounded-2xl shadow-2xl shadow-blue-900/10 hover:bg-blue-700 transition-all flex items-center justify-center gap-3 active:scale-95">
                     <Check size={20}/> {editingActivityId ? 'Update Inventory Entry' : 'Commit New Experience'}
                  </button>
               </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
};

