import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Link, useLocation, useNavigate } from 'react-router-dom';
import { 
  LayoutDashboard, 
  Trello, 
  Users, 
  Map, 
  Hotel as HotelIcon, 
  Car, 
  Sparkles,
  Settings,
  LogOut,
  Mountain,
  FileText,
  Compass,
  Bell,
  X,
  AlertTriangle,
  Clock,
  ChevronRight,
  MessageSquare,
  ChevronDown,
  User as UserIcon,
  ShieldCheck,
  Zap,
  Briefcase
} from 'lucide-react';
import { Lead, LeadStage, UserRole } from '../types';
import { MOCK_LEADS } from '../constants';
import { sendSimulatedMessage, DEFAULT_TEMPLATES, saveMessageLog } from '../services/messagingService';

interface UserPersona {
  name: string;
  role: UserRole;
  avatar: string;
  title: string;
  color: string;
}

const PERSONAS: UserPersona[] = [
  { name: 'Adil Bakshi', role: UserRole.ADMIN, avatar: 'https://picsum.photos/seed/adil/100/100', title: 'Super Admin', color: 'bg-blue-600' },
  { name: 'Sajad Ahmad', role: UserRole.SALES, avatar: 'https://picsum.photos/seed/sajad/100/100', title: 'Senior Sales Executive', color: 'bg-emerald-600' },
  { name: 'Ishfaq Lone', role: UserRole.OPERATIONS, avatar: 'https://picsum.photos/seed/ishfaq/100/100', title: 'Operations Manager', color: 'bg-amber-600' }
];

const SidebarItem = ({ icon: Icon, label, path, active, roleColor }: { icon: any, label: string, path: string, active: boolean, roleColor: string }) => (
  <Link 
    to={path} 
    className={`flex items-center gap-3 px-4 py-3 rounded-2xl transition-all ${
      active ? `${roleColor} text-white shadow-lg` : 'text-slate-400 hover:bg-slate-800 hover:text-white'
    }`}
  >
    <Icon size={18} />
