                {isSaving ? <Loader2 size={20} className="animate-spin" /> : <Check size={20}/>}
                {isSaving ? 'Synchronizing Profile...' : 'Save Workspace Updates'}
              </button>
            </div>
          </div>
        </div>
      </form>
    </div>
  );
};

