    loadRoleData(currentRole);

    // Listen for external role switches from Layout
    const handleExternalUpdate = () => {
      const updatedChoice = localStorage.getItem('et_current_user');
      const role = updatedChoice ? JSON.parse(updatedChoice).role : UserRole.ADMIN;
      setSelectedRole(role);
      loadRoleData(role);
    };

    window.addEventListener('user-profile-updated', handleExternalUpdate);
    return () => window.removeEventListener('user-profile-updated', handleExternalUpdate);
  }, []);

  // When user manually switches tab in this page
  const handleRoleTabChange = (role: UserRole) => {
    setSelectedRole(role);
    loadRoleData(role);
  };

