    e.preventDefault();
    setIsSaving(true);

    await new Promise(resolve => setTimeout(resolve, 800));

    const customProfiles = JSON.parse(localStorage.getItem('et_user_profiles') || '{}');
    customProfiles[selectedRole] = {
      name: formData.name,
      title: formData.title,
      avatar: formData.avatar,
      email: formData.email,
      phone: formData.phone
