    localStorage.setItem('et_user_profiles', JSON.stringify(customProfiles));

    // If we updated the currently active session role, notify the Layout
    const savedChoice = localStorage.getItem('et_current_user');
    const activeSessionRole = savedChoice ? JSON.parse(savedChoice).role : UserRole.ADMIN;

    if (selectedRole === activeSessionRole) {
      window.dispatchEvent(new Event('user-profile-updated'));
    }

    setIsSaving(false);
    setShowSuccess(true);
    setTimeout(() => setShowSuccess(false), 3000);
  };

