            <div className={`absolute top-0 inset-x-0 h-24 transition-colors duration-500 ${
              selectedRole === UserRole.ADMIN ? 'bg-blue-600' : 
              selectedRole === UserRole.SALES ? 'bg-emerald-600' : 'bg-amber-500'
            }`} />

            <div className="relative pt-4">
              <div className="relative w-36 h-36 mx-auto">
                <div className="w-full h-full rounded-[48px] overflow-hidden border-8 border-white shadow-2xl bg-slate-50">
                  <img src={formData.avatar} alt="Profile" className="w-full h-full object-cover" />
                </div>
                <label className="absolute -bottom-2 -right-2 bg-slate-900 text-white p-3.5 rounded-2xl shadow-2xl cursor-pointer hover:bg-blue-600 hover:scale-110 transition-all border-4 border-white active:scale-95 group/cam">
                  <Camera size={20} />
