              </div>
            </div>

            <div className="space-y-1">
              <h2 className="text-2xl font-black text-slate-900 leading-tight">{formData.name || 'Set Name'}</h2>
              <p className={`text-[11px] font-black uppercase tracking-[0.2em] ${
