                  <div className="text-left">
                    <p className="text-[9px] font-black text-slate-300 uppercase tracking-widest leading-none mb-1">Primary Base</p>
                    <span className="text-xs font-black uppercase tracking-widest text-slate-700">{formData.location}</span>
