             <div className="space-y-4 relative z-10">
                <h3 className="text-xs font-black uppercase tracking-[0.3em] text-blue-400">Persona Architecture</h3>
                <p className="text-sm text-slate-400 leading-relaxed font-bold">
                  Editing this profile updates the <span className="text-white">"{selectedRole}"</span> persona. This data is persistent and synced across the agency's internal reporting and itinerary outputs.
                </p>
             </div>
             <button 
               type="button"
               onClick={() => {
                 if (window.confirm("Restore this specific persona to system defaults?")) {
                   const customProfiles = JSON.parse(localStorage.getItem('et_user_profiles') || '{}');
                   delete customProfiles[selectedRole];
                   localStorage.setItem('et_user_profiles', JSON.stringify(customProfiles));
                   loadRoleData(selectedRole);
