const Layout: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const location = useLocation();
  const navigate = useNavigate();
  const [showNotifications, setShowNotifications] = useState(false);
  const [showProfileMenu, setShowProfileMenu] = useState(false);
  const [currentUser, setCurrentUser] = useState<TeamMember>(DEFAULT_PERSONAS[0]);
  const [teamMembers, setTeamMembers] = useState<TeamMember[]>(DEFAULT_PERSONAS);
  const [alerts, setAlerts] = useState<{ id: string, title: string, desc: string, type: 'danger' | 'warning' | 'info' | 'success', leadId: string }[]>([]);
  const profileRef = useRef<HTMLDivElement>(null);

  // Initialize and persist persona
  useEffect(() => {
    const refreshUser = () => {
      const savedMembers = localStorage.getItem('et_team_members');
      const members: TeamMember[] = savedMembers ? JSON.parse(savedMembers) : DEFAULT_PERSONAS;
      setTeamMembers(members);

      const activeMemberId = localStorage.getItem('et_active_member_id');
      const found = members.find(m => m.id === activeMemberId);

      if (found) {
        setCurrentUser(found);
      } else {
        const firstAvailable = members.length > 0 ? members[0] : DEFAULT_PERSONAS[0];
        setCurrentUser(firstAvailable);
        localStorage.setItem('et_active_member_id', firstAvailable.id);
      }
    };

    refreshUser();

    window.addEventListener('storage', refreshUser);
    window.addEventListener('user-profile-updated', refreshUser);

    const handleClickOutside = (event: MouseEvent) => {
      if (profileRef.current && !profileRef.current.contains(event.target as Node)) {
        setShowProfileMenu(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => {
      window.removeEventListener('storage', refreshUser);
      window.removeEventListener('user-profile-updated', refreshUser);
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, []);

  const switchPersona = (member: TeamMember) => {
    localStorage.setItem('et_active_member_id', member.id);
    window.dispatchEvent(new Event('user-profile-updated'));
    setShowProfileMenu(false);
  };

  const isAllowed = (path: string) => {
    if (currentUser.role === UserRole.ADMIN) return true;
    const salesPaths = ['/', '/pipeline', '/leads', '/trips', '/templates'];
    const opsPaths = ['/trips', '/hotels', '/vehicles', '/activities', '/add-ons'];
    if (currentUser.role === UserRole.SALES) return salesPaths.includes(path) || path.startsWith('/leads') || path.startsWith('/trips');
    if (currentUser.role === UserRole.OPERATIONS) return opsPaths.includes(path) || path.startsWith('/trips');
    return false;
  };

  // Automation logic
  useEffect(() => {
    const runAutomationJob = async () => {
      const savedLeads = localStorage.getItem('et_leads');
      const leads: Lead[] = savedLeads ? JSON.parse(savedLeads) : MOCK_LEADS;
      const now = new Date();
      const savedLogs = localStorage.getItem('et_message_logs');
      const allLogs = savedLogs ? JSON.parse(savedLogs) : [];

      for (const lead of leads) {
        const lastUpdate = lead.updatedAt ? new Date(lead.updatedAt) : new Date(lead.createdAt);
        const hoursInactivity = (now.getTime() - lastUpdate.getTime()) / (1000 * 60 * 60);

        if (lead.stage === LeadStage.NEW && hoursInactivity > 24) {
          const hasAlreadySentWelcome = allLogs.some((l: any) => l.leadId === lead.id && l.templateId === 'welcome-wa');
          if (!hasAlreadySentWelcome && lead.whatsappOptIn) {
            const template = DEFAULT_TEMPLATES.find(t => t.id === 'welcome-wa');
            if (template) {
              const log = await sendSimulatedMessage(lead, template);
              saveMessageLog(log);
              setAlerts(prev => [{
                id: `auto-${log.id}`,
                title: 'Auto-Message Sent',
                desc: `Welcome WhatsApp sent to ${lead.name}`,
                type: 'success',
                leadId: lead.id
              }, ...prev]);
            }
          }
        }
      }
    };
    const interval = setInterval(runAutomationJob, 30000);
    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
    const savedLeads = localStorage.getItem('et_leads');
    const leads: Lead[] = savedLeads ? JSON.parse(savedLeads) : MOCK_LEADS;
    const now = new Date();
    const newAlerts: any[] = [];

    leads.forEach(lead => {
      const createdAt = new Date(lead.createdAt);
      const lastUpdate = lead.updatedAt ? new Date(lead.updatedAt) : createdAt;
      const hoursSinceInactivity = (now.getTime() - lastUpdate.getTime()) / (1000 * 60 * 60);

      if (lead.stage === LeadStage.NEW && hoursSinceInactivity > 24) {
        newAlerts.push({ id: `alert-new-${lead.id}`, title: 'Cold Lead Alert', desc: `${lead.name} has been in "New" for 24h+.`, type: 'danger', leadId: lead.id });
      }

      const todayStr = now.toISOString().split('T')[0];
      lead.followUps.filter(f => f.status === 'Pending' && f.date <= todayStr).forEach(f => {
        newAlerts.push({ id: `alert-fu-${f.id}`, title: 'Due Follow-up', desc: `${f.note} for ${lead.name}`, type: 'info', leadId: lead.id });
      });
    });

    setAlerts(prev => [...newAlerts, ...prev.filter(a => a.id.startsWith('auto-'))]);
  }, [location.pathname]);

  return (
    <div className="flex h-screen overflow-hidden bg-[#f8fafc]">
      <aside className="w-64 bg-slate-950 flex flex-col p-6 border-r border-slate-900 transition-all duration-300">
        <div className="flex items-center gap-3 mb-4">
          <div className={`${currentUser.color} p-2.5 rounded-xl shadow-xl transition-colors duration-500`}>
            <Mountain className="text-white" size={24} />
          </div>
          <div>
            <h1 className="text-white font-black text-lg tracking-tighter leading-none">ESCAPE</h1>
            <p className="text-blue-500 text-[9px] font-black uppercase tracking-[0.2em]">THEORY KASHMIR</p>
          </div>
        </div>

        <nav className="flex-1 space-y-1 overflow-y-auto custom-scrollbar pr-2">
          {(currentUser.role === UserRole.ADMIN || currentUser.role === UserRole.SALES) && (
            <>
              <SidebarHeader label="Revenue & Sales" />
              <SidebarItem icon={LayoutDashboard} label="Dashboard" path="/" active={location.pathname === '/'} roleColor={currentUser.color} />
              <SidebarItem icon={Trello} label="Sales Pipeline" path="/pipeline" active={location.pathname === '/pipeline'} roleColor={currentUser.color} />
              <SidebarItem icon={Users} label="Lead Manager" path="/leads" active={location.pathname.startsWith('/leads') && location.pathname !== '/leads/new'} roleColor={currentUser.color} />
            </>
          )}

          <SidebarHeader label="Operations" />
          <SidebarItem icon={Map} label="All Itineraries" path="/trips" active={location.pathname === '/trips' || (location.pathname.startsWith('/trips/') && !location.pathname.includes('print'))} roleColor={currentUser.color} />
          {isAllowed('/templates') && <SidebarItem icon={FileText} label="Templates" path="/templates" active={location.pathname.startsWith('/templates')} roleColor={currentUser.color} />}

          {isAllowed('/hotels') && (
            <>
              <SidebarHeader label="Master Database" />
              <SidebarItem icon={HotelIcon} label="Hotels" path="/hotels" active={location.pathname === '/hotels'} roleColor={currentUser.color} />
              <SidebarItem icon={Car} label="Vehicle Fleet" path="/vehicles" active={location.pathname === '/vehicles'} roleColor={currentUser.color} />
              <SidebarItem icon={Compass} label="Activities" path="/activities" active={location.pathname === '/activities'} roleColor={currentUser.color} />
              <SidebarItem icon={Sparkles} label="Add-ons" path="/add-ons" active={location.pathname === '/add-ons'} roleColor={currentUser.color} />
            </>
          )}

          {currentUser.role === UserRole.ADMIN && (
            <>
              <SidebarHeader label="System" />
              <SidebarItem icon={Settings} label="Settings" path="/settings" active={location.pathname === '/settings'} roleColor={currentUser.color} />
            </>
          )}
        </nav>

        <div className="mt-auto border-t border-slate-900 pt-6">
          <button className="flex items-center gap-3 px-4 py-3 text-slate-500 hover:text-red-400 transition-colors w-full group">
            <LogOut size={20} className="group-hover:translate-x-1 transition-transform" />
            <span className="font-bold text-sm">Sign Out</span>
          </button>
        </div>
      </aside>

      <main className="flex-1 flex flex-col overflow-hidden relative">
        <header className="h-20 bg-white border-b border-slate-100 flex items-center justify-between px-10">
          <div className="flex items-center gap-4">
            <h2 className="text-slate-900 font-black text-xl tracking-tight uppercase">
              {location.pathname === '/' ? 'Business Intelligence' : 
               location.pathname.startsWith('/pipeline') ? 'Sales Pipeline' :
               location.pathname.startsWith('/leads') ? 'Client Relationship' :
               location.pathname.startsWith('/trips') ? 'Itinerary Control' :
               location.pathname.startsWith('/profile') ? 'My Workspace' :
               'Operational Control'}
            </h2>
          </div>
          <div className="flex items-center gap-6">
            <button 
              onClick={() => setShowNotifications(!showNotifications)}
              className="relative p-3 bg-slate-50 hover:bg-slate-100 rounded-2xl transition-all group"
            >
              <Bell size={20} className="text-slate-400 group-hover:text-blue-600" />
              {alerts.length > 0 && (
                <span className="absolute top-2 right-2 w-4 h-4 bg-rose-600 border-2 border-white rounded-full flex items-center justify-center text-[8px] text-white font-black">
                  {alerts.length}
                </span>
              )}
            </button>

            <div className="relative" ref={profileRef}>
              <button 
                onClick={() => setShowProfileMenu(!showProfileMenu)}
                className="flex items-center gap-4 p-1 pr-3 hover:bg-slate-50 rounded-2xl transition-all group border border-transparent hover:border-slate-200"
              >
                <div className="w-11 h-11 rounded-xl bg-slate-100 border-2 border-white shadow-sm overflow-hidden transition-transform group-active:scale-90">
                  <img src={currentUser.avatar} alt={currentUser.name} className="w-full h-full object-cover" />
                </div>
                <div className="text-left hidden md:block">
                  <p className="text-xs font-black text-slate-900 leading-none flex items-center gap-1">
                    {currentUser.name}
                    <ChevronDown size={14} className={`text-slate-400 transition-transform ${showProfileMenu ? 'rotate-180' : ''}`} />
                  </p>
                  <p className="text-[9px] text-slate-400 font-bold uppercase tracking-widest mt-1">{currentUser.title}</p>
                </div>
              </button>

              {showProfileMenu && (
                <div className="absolute top-14 right-0 w-64 bg-white rounded-3xl shadow-2xl border border-slate-100 z-[120] overflow-hidden animate-in zoom-in-95 duration-200">
                  <div className="p-5 border-b border-slate-50 bg-slate-50/50">
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3">Switch Work Persona</p>
                    <div className="space-y-2 max-h-60 overflow-y-auto custom-scrollbar">
                      {teamMembers.map(m => (
                        <button 
                          key={m.id}
                          onClick={() => switchPersona(m)}
                          className={`w-full flex items-center gap-3 p-3 rounded-2xl transition-all ${
                            currentUser.id === m.id 
                            ? 'bg-white border border-slate-200 shadow-sm' 
                            : 'hover:bg-white/60'
                          }`}
                        >
                          <div className={`w-8 h-8 rounded-lg overflow-hidden shrink-0 ${currentUser.id === m.id ? 'ring-2 ring-blue-500 ring-offset-2' : ''}`}>
                            <img src={m.avatar} alt={m.name} className="w-full h-full object-cover" />
                          </div>
                          <div className="text-left">
                            <p className={`text-xs font-black ${currentUser.id === m.id ? 'text-blue-600' : 'text-slate-700'}`}>{m.name}</p>
                            <p className="text-[9px] font-bold text-slate-400 uppercase tracking-tighter">{m.role}</p>
                          </div>
                          {currentUser.id === m.id && <ShieldCheck size={14} className="ml-auto text-blue-600" />}
                        </button>
                      ))}
                    </div>
                  </div>
                  <div className="p-3">
                     <button 
                       onClick={() => { navigate('/profile'); setShowProfileMenu(false); }}
                       className="w-full flex items-center gap-3 p-3 text-slate-500 hover:text-slate-900 hover:bg-slate-50 rounded-2xl transition-all"
                     >
                        <UserIcon size={16}/>
                        <span className="text-xs font-bold">Manage Profiles</span>
                     </button>
                     <button className="w-full flex items-center gap-3 p-3 text-rose-500 hover:bg-rose-50 rounded-2xl transition-all">
                        <LogOut size={16}/>
                        <span className="text-xs font-bold">Log Out</span>
                     </button>
                  </div>
                </div>
              )}
            </div>
          </div>
        </header>

        {showNotifications && (
          <div className="absolute top-24 right-10 w-96 bg-white rounded-[40px] shadow-2xl border border-slate-100 z-[110] flex flex-col overflow-hidden animate-in slide-in-from-top-4 duration-300">
             <div className="p-8 border-b border-slate-50 flex items-center justify-between">
                <h3 className="font-black text-slate-900 uppercase tracking-widest text-xs flex items-center gap-2">
                   <Bell size={16} className="text-blue-600" /> Agency Action Center
                </h3>
                <button onClick={() => setShowNotifications(false)} className="text-slate-300 hover:text-slate-900"><X size={20}/></button>
             </div>
             <div className="flex-1 overflow-y-auto p-6 space-y-4 max-h-[60vh]">
                {alerts.length > 0 ? alerts.map(alert => (
                  <Link 
                    key={alert.id}
                    to={`/leads/${alert.leadId}`}
                    onClick={() => setShowNotifications(false)}
                    className="flex items-start gap-4 p-5 bg-slate-50 border border-slate-100 rounded-3xl group hover:bg-white hover:border-blue-200 transition-all shadow-sm"
                  >
                     <div className={`p-2 rounded-xl shrink-0 ${
                       alert.type === 'danger' ? 'bg-rose-100 text-rose-600' :
                       alert.type === 'warning' ? 'bg-amber-100 text-amber-600' :
                       alert.type === 'success' ? 'bg-emerald-100 text-emerald-600' :
                       'bg-blue-100 text-blue-600'
                     }`}>
                        {alert.type === 'success' ? <MessageSquare size={18}/> : <AlertTriangle size={18} />}
                     </div>
                     <div className="space-y-1">
                        <p className="text-[10px] font-black uppercase text-slate-400 tracking-widest">{alert.title}</p>
                        <p className="text-xs font-bold text-slate-700 leading-snug">{alert.desc}</p>
                     </div>
                     <ChevronRight size={16} className="text-slate-200 group-hover:text-blue-600 mt-1" />
                  </Link>
                )) : (
                  <div className="py-20 text-center space-y-4 opacity-30">
                    <Clock size={48} className="mx-auto" />
                    <p className="text-[10px] font-black uppercase tracking-widest">No Alerts Pending</p>
                  </div>
                )}
             </div>
             <div className="p-6 bg-slate-50 border-t border-slate-100">
                <button onClick={() => setAlerts([])} className="w-full py-3 text-[10px] font-black uppercase tracking-widest text-slate-400 hover:text-slate-900">Clear All Alerts</button>
             </div>
          </div>
        )}

        <div className="flex-1 overflow-y-auto p-10 bg-[#f8fafc]">
          {children}
        </div>
      </main>
    </div>
  );
};

export default Layout;

import React, { useState, useEffect, useMemo } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { 
  Search, 
  Filter, 
  Plus, 
  ChevronRight, 
  MessageSquare, 
  Phone, 
  Mail, 
  MoreVertical,
  Flame,
  TrendingUp,
  Snowflake,
  Clock,
  Calendar,
  Zap,
  CheckCircle2,
  X,
  Trash2,
  UserPlus,
  ArrowRightLeft,
  Check,
  Edit2,
  Sparkles,
  Loader2,
  Globe,
  User,
  Activity as ActivityIcon,
  Smartphone,
  Send,
  ShieldCheck
} from 'lucide-react';
import { Lead, LeadStage, LeadScore, TripType, FollowUp, LeadActivity, TeamMember } from '../types';
import { MOCK_LEADS, DEFAULT_PERSONAS } from '../constants';
import { suggestFollowUp } from '../services/geminiService';
import { DEFAULT_TEMPLATES, sendSimulatedMessage, saveMessageLog } from '../services/messagingService';

const LeadList: React.FC = () => {
  const navigate = useNavigate();
  const [leads, setLeads] = useState<Lead[]>([]);
  const [teamMembers, setTeamMembers] = useState<TeamMember[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [stageFilter, setStageFilter] = useState('All');
  const [scoreFilter, setScoreFilter] = useState('All');
  const [selectedLeads, setSelectedLeads] = useState<string[]>([]);

  // Edit State
  const [editingLead, setEditingLead] = useState<Lead | null>(null);
  const [isEditModalOpen, setIsEditModalOpen] = useState(false);

  // AI Suggestion State
  const [suggestingForId, setSuggestingForId] = useState<string | null>(null);
  const [currentSuggestion, setCurrentSuggestion] = useState<{ task: string, daysFromNow: number } | null>(null);
  const [isSuggesting, setIsSuggesting] = useState(false);

  // Bulk Messaging State
  const [isBulkMessageModalOpen, setIsBulkMessageModalOpen] = useState(false);
  const [selectedTemplateId, setSelectedTemplateId] = useState(DEFAULT_TEMPLATES[0].id);
  const [isBulkSending, setIsBulkSending] = useState(false);

  useEffect(() => {
    const savedLeads = localStorage.getItem('et_leads');
    setLeads(savedLeads ? JSON.parse(savedLeads) : MOCK_LEADS);

    const savedMembers = localStorage.getItem('et_team_members');
    setTeamMembers(savedMembers ? JSON.parse(savedMembers) : DEFAULT_PERSONAS);
  }, []);

  const saveLeads = (updatedLeads: Lead[]) => {
    setLeads(updatedLeads);
    localStorage.setItem('et_leads', JSON.stringify(updatedLeads));
  };

  const filteredLeads = useMemo(() => {
    return leads.filter(l => {
      const matchesSearch = l.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                           l.phone.includes(searchTerm) ||
                           l.email.toLowerCase().includes(searchTerm.toLowerCase());
      const matchesStage = stageFilter === 'All' || l.stage === stageFilter;
      const matchesScore = scoreFilter === 'All' || l.score === scoreFilter;
      return matchesSearch && matchesStage && matchesScore;
    });
  }, [leads, searchTerm, stageFilter, scoreFilter]);

  const toggleSelectAll = () => {
    if (selectedLeads.length === filteredLeads.length) {
      setSelectedLeads([]);
    } else {
      setSelectedLeads(filteredLeads.map(l => l.id));
    }
  };

  const toggleSelectLead = (id: string) => {
    setSelectedLeads(prev => prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]);
  };

  const handleWhatsApp = (phone: string) => {
    const cleanPhone = phone.replace(/\D/g, '');
    window.open(`https://wa.me/${cleanPhone}`, '_blank');
  };

  const handleCall = (phone: string) => {
    window.location.href = `tel:${phone}`;
  };

  const updateLeadField = (id: string, field: keyof Lead, value: any) => {
    const updated = leads.map(l => l.id === id ? { ...l, [field]: value, updatedAt: new Date().toISOString() } : l);
    saveLeads(updated);
  };

  const handleBulkStatusUpdate = (newStage: LeadStage) => {
    const updated = leads.map(l => selectedLeads.includes(l.id) ? { ...l, stage: newStage, updatedAt: new Date().toISOString() } : l);
    saveLeads(updated);
    setSelectedLeads([]);
  };

  const handleBulkDelete = () => {
    if (window.confirm(`Are you sure you want to delete ${selectedLeads.length} leads?`)) {
      const updated = leads.filter(l => !selectedLeads.includes(l.id));
      saveLeads(updated);
      setSelectedLeads([]);
    }
  };

  const handleBulkWhatsAppSend = async () => {
    setIsBulkSending(true);
    const template = DEFAULT_TEMPLATES.find(t => t.id === selectedTemplateId);
    if (!template) return;

    const selectedLeadsData = leads.filter(l => selectedLeads.includes(l.id));

    // Process messages in parallel (simulated)
    const promises = selectedLeadsData.map(async (lead) => {
      if (!lead.whatsappOptIn && template.type === 'WhatsApp') return null;
      const log = await sendSimulatedMessage(lead, template);
      saveMessageLog(log);

      // Update individual lead activities
      const activity: LeadActivity = {
        id: `act-${Date.now()}-${lead.id}`,
        leadId: lead.id,
        type: 'MessageSent',
        timestamp: new Date().toISOString(),
        description: `Bulk ${template.type} sent: ${template.name}`
      };

      return { leadId: lead.id, activity };
    });

    const results = await Promise.all(promises);

    // Update master leads state with new activities
    const updatedLeads = leads.map(l => {
      const result = results.find(r => r?.leadId === l.id);
      if (result) {
        return {
          ...l,
          activities: [result.activity, ...(l.activities || [])],
          updatedAt: new Date().toISOString()
        };
      }
      return l;
    });

    saveLeads(updatedLeads);
    setIsBulkSending(false);
    setIsBulkMessageModalOpen(false);
    setSelectedLeads([]);
    alert(`Bulk transmission complete for ${selectedLeads.length} leads.`);
  };

  // Edit Logic
  const openEditModal = (lead: Lead) => {
    setEditingLead({ ...lead });
    setIsEditModalOpen(true);
  };

  const handleEditSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingLead) return;
    const updated = leads.map(l => l.id === editingLead.id ? { ...editingLead, updatedAt: new Date().toISOString() } : l);
    saveLeads(updated);
    setIsEditModalOpen(false);
    setEditingLead(null);
  };

  // AI Suggestion Logic
  const handleGetSuggestion = async (lead: Lead) => {
    if (isSuggesting) return;
    setSuggestingForId(lead.id);
    setIsSuggesting(true);
    setCurrentSuggestion(null);

    try {
      const suggestion = await suggestFollowUp(lead.name, lead.stage, lead.notes, lead.interest);
      setCurrentSuggestion(suggestion);
    } catch (error) {
      console.error("AI Error:", error);
      alert("AI failed to provide a suggestion. Please try again.");
      setSuggestingForId(null);
    } finally {
      setIsSuggesting(false);
    }
  };

  const acceptSuggestion = () => {
    if (!suggestingForId || !currentSuggestion) return;

    const lead = leads.find(l => l.id === suggestingForId);
    if (!lead) return;

    const futureDate = new Date();
    futureDate.setDate(futureDate.getDate() + currentSuggestion.daysFromNow);

    const newFollowUp: FollowUp = {
      id: `f-${Date.now()}`,
      date: futureDate.toISOString().split('T')[0],
      status: 'Pending',
      note: currentSuggestion.task
    };

    const activity: LeadActivity = {
      id: `act-${Date.now()}`,
      leadId: lead.id,
      type: 'FollowUpCreated',
      timestamp: new Date().toISOString(),
      description: `AI Suggested Task: ${currentSuggestion.task} for ${newFollowUp.date}`
    };

    const updatedLead = {
      ...lead,
      followUps: [...lead.followUps, newFollowUp],
      activities: [activity, ...(lead.activities || [])],
      updatedAt: new Date().toISOString()
    };

    const updatedLeads = leads.map(l => l.id === lead.id ? updatedLead : l);
    saveLeads(updatedLeads);
    setSuggestingForId(null);
    setCurrentSuggestion(null);
  };

  const ScoreBadge = ({ score }: { score: LeadScore }) => {
    switch (score) {
      case LeadScore.HOT:
        return <span className="flex items-center gap-1 text-[10px] font-black uppercase text-rose-600 bg-rose-50 px-2.5 py-1 rounded-full border border-rose-100"><Flame size={12}/> Hot</span>;
      case LeadScore.WARM:
        return <span className="flex items-center gap-1 text-[10px] font-black uppercase text-amber-600 bg-amber-50 px-2.5 py-1 rounded-full border border-amber-100"><TrendingUp size={12}/> Warm</span>;
      case LeadScore.COLD:
        return <span className="flex items-center gap-1 text-[10px] font-black uppercase text-blue-600 bg-blue-50 px-2.5 py-1 rounded-full border border-blue-100"><Snowflake size={12}/> Cold</span>;
    }
  };

  return (
    <div className="space-y-8 pb-20 relative">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-slate-900">Lead Manager</h1>
          <p className="text-slate-500 text-sm">Manage client acquisitions and team assignments.</p>
        </div>
        <button 
          onClick={() => navigate('/leads/new')}
