import React, { useState, useEffect, useRef } from 'react';
import { 
  User, 
  Camera, 
  Check, 
  Shield, 
  Mail, 
  Briefcase, 
  Loader2, 
  CheckCircle2,
  Trash2,
  Smartphone,
  MapPin,
  Mountain,
  Plus,
  X,
  Edit2,
  Search,
  Users
} from 'lucide-react';
import { UserRole, TeamMember } from '../types';
import { DEFAULT_PERSONAS } from '../constants';

const ProfileSettings: React.FC = () => {
  const [members, setMembers] = useState<TeamMember[]>([]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingMember, setEditingMember] = useState<TeamMember | null>(null);
  const [isSaving, setIsSaving] = useState(false);
  const [showSuccess, setShowSuccess] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const [formData, setFormData] = useState<Partial<TeamMember>>({
    name: '',
    title: '',
    role: UserRole.SALES,
    avatar: 'https://picsum.photos/seed/' + Math.random() + '/100/100',
    email: '',
    phone: '',
    location: 'Srinagar Office',
    color: 'bg-emerald-600'
  });

  useEffect(() => {
    const saved = localStorage.getItem('et_team_members');
    if (saved) {
      setMembers(JSON.parse(saved));
    } else {
      setMembers(DEFAULT_PERSONAS);
    }
  }, []);

  const saveMembers = (updated: TeamMember[]) => {
    setMembers(updated);
    localStorage.setItem('et_team_members', JSON.stringify(updated));
    window.dispatchEvent(new Event('user-profile-updated'));
  };

  const handleOpenAdd = () => {
    setEditingMember(null);
