  };

  const handleDelete = (id: string) => {
    if (members.length <= 1) {
      alert("At least one member must remain in the system.");
      return;
    }
    if (window.confirm("Permanently delete this member profile?")) {
      const updated = members.filter(m => m.id !== id);
      saveMembers(updated);
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSaving(true);
    await new Promise(r => setTimeout(r, 600));

    const roleColors: Record<UserRole, string> = {
      [UserRole.ADMIN]: 'bg-blue-600',
      [UserRole.SALES]: 'bg-emerald-600',
      [UserRole.OPERATIONS]: 'bg-amber-600'
    };

    const memberData: TeamMember = {
      ...formData,
      id: editingMember?.id || `tm-${Date.now()}`,
      color: roleColors[formData.role as UserRole] || 'bg-slate-600'
    } as TeamMember;

    let updated: TeamMember[];
    if (editingMember) {
      updated = members.map(m => m.id === editingMember.id ? memberData : m);
    } else {
      updated = [...members, memberData];
    }

    saveMembers(updated);
    setIsSaving(false);
    setShowSuccess(true);
    setTimeout(() => {
      setShowSuccess(false);
      setIsModalOpen(false);
    }, 1000);
