                               <span className="flex-1 truncate mr-2">{item}</span>
                               <Plus size={10} className="text-slate-600 group-hover:text-blue-400" />
                            </button>
                          ))}
                        </div>
                      </div>
                    )}

                    <div className="space-y-3">
                        {(trip.inclusions || []).map((inc, i) => (
                          <div key={i} className="flex items-start gap-2 group">
                              <textarea 
                                value={inc}
                                onChange={(e) => updateInclusionInline(i, e.target.value)}
                                className="flex-1 text-[10px] font-bold text-slate-600 bg-emerald-50 p-3 rounded-xl outline-none focus:ring-2 focus:ring-emerald-200 resize-none overflow-hidden"
                                rows={2}
                              />
                              <button onClick={() => removeInclusion(i)} className="p-2 text-slate-300 hover:text-rose-500 transition-all mt-1"><Trash2 size={14}/></button>
                          </div>
                        ))}
                        <div className="flex gap-2 pt-2">
                          <input type="text" placeholder="Add custom inclusion..." value={newInclusion} onChange={(e) => setNewInclusion(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && addInclusion()} className="flex-1 p-2 bg-slate-50 border border-slate-100 rounded-lg text-[10px] font-bold outline-none text-slate-900" />
                          <button onClick={addInclusion} className="bg-emerald-600 text-white p-2 rounded-lg transition-all active:scale-90"><Plus size={14}/></button>
                        </div>
                    </div>
                  </div>

                  {/* Terms Sidebar - Exclusions */}
                  <div className="bg-white border border-slate-200 rounded-[32px] p-8 shadow-sm space-y-6">
                    <div className="flex items-center justify-between">
                      <h3 className="text-xs font-black uppercase tracking-widest text-rose-500 flex items-center gap-2"><XCircle size={16} /> Trip Exclusions</h3>
                      <div className="flex items-center gap-2">
                         <button onClick={() => setShowExclusionLibrary(!showExclusionLibrary)} className="p-2 bg-slate-50 rounded-xl text-slate-400 hover:text-blue-600 transition-all" title="Master Library">
                           <Library size={14} />
                         </button>
                         <button onClick={() => syncWithMaster('exclusions')} className="p-2 bg-slate-50 rounded-xl text-slate-400 hover:text-rose-500 transition-all" title="Reset to Master">
                           <RotateCcw size={14} />
                         </button>
                      </div>
                    </div>

                    {showExclusionLibrary && (
                      <div className="bg-slate-900 p-4 rounded-2xl space-y-3 animate-in slide-in-from-top-2">
                        <p className="text-[8px] font-black uppercase text-slate-500 tracking-widest px-1">Master Database Exclusions</p>
                        <div className="max-h-40 overflow-y-auto space-y-2 custom-scrollbar pr-2">
                          {masterExclusions.map((item, idx) => (
                            <button 
                              key={idx} 
                              onClick={() => { setTrip({...trip, exclusions: [...trip.exclusions, item]}); setShowExclusionLibrary(false); }}
                              className="w-full text-left p-2.5 bg-white/5 hover:bg-white/10 rounded-xl text-[10px] font-bold text-slate-300 transition-all flex items-center justify-between group"
                            >
                               <span className="flex-1 truncate mr-2">{item}</span>
                               <Plus size={10} className="text-slate-600 group-hover:text-rose-400" />
                            </button>
                          ))}
                        </div>
                      </div>
                    )}

                    <div className="space-y-3">
                        {(trip.exclusions || []).map((exc, i) => (
                          <div key={i} className="flex items-start gap-2 group">
                              <textarea 
                                value={exc}
                                onChange={(e) => updateExclusionInline(i, e.target.value)}
                                className="flex-1 text-[10px] font-bold text-slate-600 bg-rose-50 p-3 rounded-xl outline-none focus:ring-2 focus:ring-rose-200 resize-none overflow-hidden"
                                rows={2}
                              />
                              <button onClick={() => removeExclusion(i)} className="p-2 text-slate-300 hover:text-rose-500 transition-all mt-1"><Trash2 size={14}/></button>
                          </div>
                        ))}
                        <div className="flex gap-2 pt-2">
                          <input type="text" placeholder="Add custom exclusion..." value={newExclusion} onChange={(e) => setNewExclusion(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && addExclusion()} className="flex-1 p-2 bg-slate-50 border border-slate-100 rounded-lg text-[10px] font-bold outline-none text-slate-900" />
                          <button onClick={addExclusion} className="bg-rose-500 text-white p-2 rounded-lg transition-all active:scale-90"><Plus size={14}/></button>
                        </div>
                    </div>
                  </div>
                </div>
                <div className="pb-20" />
             </div>
           )}

           {activeRightTab === 'history' && (
             <div className="space-y-6 animate-in fade-in slide-in-from-right-4 duration-300">
                <div className="bg-slate-900 p-8 rounded-[40px] text-white space-y-8 shadow-2xl">
                   <div className="flex items-center justify-between">
                      <h3 className="text-xs font-black uppercase tracking-widest text-blue-400 flex items-center gap-2">
                         <History size={16} /> Iteration History
                      </h3>
                   </div>

                   <div className="space-y-4">
                      {trip.versions?.map(v => (
                         <div key={v.id} className="p-5 bg-white/5 border border-white/10 rounded-[32px] group hover:bg-white/10 transition-all">
                            <div className="flex justify-between items-start mb-2">
                               <div>
                                  <p className="text-xs font-black text-white">{v.label}</p>
                                  <p className="text-[9px] font-bold text-slate-500 uppercase tracking-widest mt-0.5">
                                     {new Date(v.timestamp).toLocaleString('en-IN', { dateStyle: 'medium', timeStyle: 'short' })}
                                  </p>
                               </div>
                               <button onClick={() => deleteVersion(v.id)} className="p-1.5 text-slate-600 hover:text-rose-400 transition-colors">
                                  <Trash2 size={14} />
                                </button>
                            </div>
                            <div className="flex gap-2 mt-4">
                               <button 
                                 onClick={() => restoreVersion(v)}
                                 className="flex-1 py-2.5 bg-blue-600 text-white text-[10px] font-black uppercase tracking-widest rounded-xl hover:bg-blue-500 transition-all flex items-center justify-center gap-2"
                               >
                                  <RotateCcw size={12} /> Restore
                               </button>
                            </div>
                         </div>
                      ))}

                      {(trip.versions || []).length === 0 && (
                         <div className="py-12 text-center space-y-4 opacity-20">
                            <Clock size={40} className="mx-auto" />
                            <p className="text-[10px] font-black uppercase tracking-widest">No versions saved yet</p>
                         </div>
                      )}
                   </div>

                   <button 
                      onClick={() => setIsVersionModalOpen(true)}
                      className="w-full py-4 bg-white/10 text-white border border-white/20 rounded-2xl font-black uppercase tracking-widest text-[10px] hover:bg-white/20 transition-all flex items-center justify-center gap-2"
                   >
                      <Plus size={14} /> Save Current Draft
                   </button>
                </div>
             </div>
           )}
        </div>
      </div>

      {/* Version Modal */}
      {isVersionModalOpen && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[120] flex items-center justify-center p-4">
           <div className="bg-white rounded-[40px] shadow-2xl w-full max-w-md overflow-hidden animate-in zoom-in-95 duration-200">
              <div className="bg-slate-950 p-8 text-white flex items-center justify-between">
                 <div className="flex items-center gap-3">
                    <div className="bg-blue-600 p-2.5 rounded-xl">
                       <FileClock size={20} />
                    </div>
                    <div>
                       <h3 className="font-black uppercase text-sm">Save Version</h3>
                       <p className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">Freeze current progress</p>
                    </div>
                 </div>
                 <button onClick={() => setIsVersionModalOpen(false)} className="text-slate-500 hover:text-white transition-colors"><X size={24}/></button>
              </div>

              <form onSubmit={handleSaveVersion} className="p-10 space-y-6">
                 <div className="space-y-2">
                    <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Version Label</label>
                    <input 
                      autoFocus
                      required
                      type="text" 
                      placeholder="e.g. Initial Draft, Added Houseboat, Post-Discount..."
                      className="w-full p-4 bg-slate-50 border border-slate-200 rounded-2xl font-bold outline-none text-slate-900 focus:bg-white focus:ring-4 focus:ring-blue-50 transition-all"
                      value={versionLabel}
                      onChange={(e) => setVersionLabel(e.target.value)}
                    />
                 </div>

                 <div className="pt-4 flex gap-4">
                    <button type="button" onClick={() => setIsVersionModalOpen(false)} className="flex-1 py-4 text-slate-400 font-black uppercase tracking-widest text-[10px] hover:bg-slate-50 rounded-2xl transition-all">Discard</button>
                    <button type="submit" className="flex-[2] py-4 bg-slate-900 text-white font-black uppercase tracking-widest text-[10px] rounded-2xl shadow-xl hover:bg-blue-600 transition-all">
                       Commit Version
                    </button>
                 </div>
              </form>
           </div>
        </div>
      )}
    </div>
  );
};

export default TripBuilder;

import React, { useState, useEffect } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { ArrowLeft, User, Phone, Mail, Globe, Calendar, Users, Briefcase, ChevronRight, Check, MapPin } from 'lucide-react';
import { TripType, TripStatus, Trip } from '../types';
import { MOCK_TEMPLATES, MOCK_TRIPS, BRAND_CONFIG, TripTemplate, DEFAULT_INCLUSIONS, DEFAULT_EXCLUSIONS, MOCK_LEADS } from '../constants';

const NewTrip: React.FC = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const [step, setStep] = useState(1);
  const [allTemplates, setAllTemplates] = useState<TripTemplate[]>([]);
  const [formData, setFormData] = useState({
    clientName: '',
    phone: '',
    email: '',
    source: 'Website',
    tripName: '',
    tripType: TripType.FAMILY,
    pax: 2,
    startDate: '',
    endDate: '',
    templateId: 'blank',
    startLocation: 'Srinagar' as 'Srinagar' | 'Jammu',
    leadId: ''
  });

  useEffect(() => {
    // Load combined templates
    const savedTemplatesRaw = localStorage.getItem('et_templates');
    const savedTemplates = savedTemplatesRaw ? JSON.parse(savedTemplatesRaw) : [];
    const merged = [...MOCK_TEMPLATES, ...savedTemplates];
    setAllTemplates(merged);

    // Check for pre-selected template and lead from URL
    const queryParams = new URLSearchParams(location.search);
    const templateId = queryParams.get('templateId');
    const leadId = queryParams.get('leadId');

    if (templateId) {
      const template = merged.find(t => t.id === templateId);
      if (template) {
        setFormData(prev => ({ 
          ...prev, 
          templateId, 
          tripType: template.tripType 
        }));
      }
    }

    // Pre-fill lead data if leadId is provided in URL
    if (leadId) {
      const savedLeadsRaw = localStorage.getItem('et_leads');
      const allLeads = savedLeadsRaw ? JSON.parse(savedLeadsRaw) : MOCK_LEADS;
      const foundLead = allLeads.find((l: any) => l.id === leadId);
      if (foundLead) {
        setFormData(prev => ({
          ...prev,
          leadId,
          clientName: foundLead.name,
          phone: foundLead.phone,
          email: foundLead.email,
          source: foundLead.source,
          pax: foundLead.pax,
          tripType: foundLead.interest
        }));
      } else {
        setFormData(prev => ({ ...prev, leadId }));
      }
    }
  }, [location.search]);

  const handleNext = () => setStep(step + 1);
  const handleBack = () => setStep(step - 1);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    // Fetch current Master Terms from Database
    const masterInc = localStorage.getItem('et_master_inclusions');
    const masterExc = localStorage.getItem('et_master_exclusions');
    const currentMasterInclusions = masterInc ? JSON.parse(masterInc) : [...DEFAULT_INCLUSIONS];
    const currentMasterExclusions = masterExc ? JSON.parse(masterExc) : [...DEFAULT_EXCLUSIONS];

    const newId = `trip-${Date.now()}`;
    const selectedTemplate = allTemplates.find(t => t.id === formData.templateId);

    const newTrip: Trip = {
      id: newId,
      leadId: formData.leadId,
      client: {
        name: formData.clientName,
        phone: formData.phone,
        email: formData.email,
        source: formData.source,
      },
      tripName: formData.tripName || `${formData.clientName}'s Kashmir Trip`,
      tripType: formData.tripType,
      startDate: formData.startDate,
      endDate: formData.endDate,
      pax: formData.pax,
      budgetRange: 'TBD',
      assignedSalesperson: 'Adil Bakshi',
      status: TripStatus.LEAD,
      marginPercentage: selectedTemplate?.baseMargin || BRAND_CONFIG.defaultMargin,
      addOnIds: [],
      itinerary: selectedTemplate ? JSON.parse(JSON.stringify(selectedTemplate.itinerary)) : [],
      versions: [],
      startLocation: formData.startLocation,
      // Priority: 1. Template-specific terms, 2. Global Master Terms
      inclusions: selectedTemplate?.inclusions && selectedTemplate.inclusions.length > 0 
        ? [...selectedTemplate.inclusions] 
        : currentMasterInclusions,
      exclusions: selectedTemplate?.exclusions && selectedTemplate.exclusions.length > 0 
        ? [...selectedTemplate.exclusions] 
        : currentMasterExclusions
    };

    const savedTripsRaw = localStorage.getItem('et_trips');
    const allTrips: Trip[] = savedTripsRaw ? JSON.parse(savedTripsRaw) : [...MOCK_TRIPS];
    allTrips.push(newTrip);
    localStorage.setItem('et_trips', JSON.stringify(allTrips));

    navigate(`/trips/${newId}`); 
  };

  return (
    <div className="max-w-4xl mx-auto py-8">
      <button onClick={() => navigate('/trips')} className="mb-6 flex items-center gap-2 text-slate-500 hover:text-slate-800 transition-colors font-medium">
        <ArrowLeft size={18} />
        Back to Trips
      </button>

      <div className="bg-white rounded-2xl border border-slate-200 shadow-xl overflow-hidden text-slate-900">
        <div className="bg-slate-50 border-b border-slate-100 flex p-6 gap-8">
          <div className={`flex items-center gap-3 ${step >= 1 ? 'text-blue-600' : 'text-slate-400'}`}>
            <div className={`w-8 h-8 rounded-full flex items-center justify-center font-bold text-sm ${step >= 1 ? 'bg-blue-600 text-white' : 'bg-slate-200 text-slate-500'}`}>
              {step > 1 ? <Check size={16} /> : '1'}
            </div>
            <span className="font-bold text-sm uppercase tracking-wider">Client Details</span>
          </div>
          <div className={`flex items-center gap-3 ${step >= 2 ? 'text-blue-600' : 'text-slate-400'}`}>
            <div className={`w-8 h-8 rounded-full flex items-center justify-center font-bold text-sm ${step >= 2 ? 'bg-blue-600 text-white' : 'bg-slate-200 text-slate-500'}`}>
              {step > 2 ? <Check size={16} /> : '2'}
            </div>
            <span className="font-bold text-sm uppercase tracking-wider">Trip Logistics</span>
          </div>
          <div className={`flex items-center gap-3 ${step >= 3 ? 'text-blue-600' : 'text-slate-400'}`}>
            <div className={`w-8 h-8 rounded-full flex items-center justify-center font-bold text-sm ${step >= 3 ? 'bg-blue-600 text-white' : 'bg-slate-200 text-slate-500'}`}>
              3
            </div>
            <span className="font-bold text-sm uppercase tracking-wider">Template</span>
          </div>
        </div>

        <form onSubmit={handleSubmit} className="p-10">
          {step === 1 && (
            <div className="space-y-6 animate-in fade-in slide-in-from-right-4">
              <div className="grid grid-cols-2 gap-6">
                <div className="space-y-2">
                  <label className="text-xs font-black uppercase text-slate-400 tracking-widest">Client Name</label>
                  <div className="relative">
                    <User className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-300" size={18} />
                    <input 
                      required
                      type="text" 
                      className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none text-slate-900 placeholder:text-slate-300"
                      placeholder="e.g. Adnan Ahmad"
                      value={formData.clientName}
                      onChange={(e) => setFormData({...formData, clientName: e.target.value})}
                    />
                  </div>
                </div>
                <div className="space-y-2">
                  <label className="text-xs font-black uppercase text-slate-400 tracking-widest">WhatsApp / Phone</label>
                  <div className="relative">
                    <Phone className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-300" size={18} />
                    <input 
                      required
                      type="tel" 
                      className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none text-slate-900 placeholder:text-slate-300"
                      placeholder="+91 0000 000000"
                      value={formData.phone}
                      onChange={(e) => setFormData({...formData, phone: e.target.value})}
                    />
                  </div>
                </div>
              </div>
              <div className="grid grid-cols-2 gap-6">
                <div className="space-y-2">
                  <label className="text-xs font-black uppercase text-slate-400 tracking-widest">Email Address</label>
                  <div className="relative">
                    <Mail className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-300" size={18} />
                    <input 
                      type="email" 
                      className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none text-slate-900 placeholder:text-slate-300"
                      placeholder="client@example.com"
                      value={formData.email}
                      onChange={(e) => setFormData({...formData, email: e.target.value})}
                    />
                  </div>
                </div>
                <div className="space-y-2">
                  <label className="text-xs font-black uppercase text-slate-400 tracking-widest">Lead Source</label>
                  <div className="relative">
                    <Globe className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-300" size={18} />
                    <select 
                      className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none text-slate-900"
                      value={formData.source}
                      onChange={(e) => setFormData({...formData, source: e.target.value})}
                    >
                      <option>Website</option>
                      <option>Instagram</option>
                      <option>Referral</option>
                      <option>Walk-in</option>
                    </select>
                  </div>
                </div>
              </div>
            </div>
          )}

          {step === 2 && (
            <div className="space-y-6 animate-in fade-in slide-in-from-right-4">
              <div className="grid grid-cols-2 gap-6">
                <div className="space-y-2">
                  <label className="text-xs font-black uppercase text-slate-400 tracking-widest">Trip Name</label>
                  <div className="relative">
                    <Briefcase className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-300" size={18} />
                    <input 
                      required
                      type="text" 
                      className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none text-slate-900 placeholder:text-slate-300"
                      placeholder="e.g. Kashmir Family Getaway"
                      value={formData.tripName}
                      onChange={(e) => setFormData({...formData, tripName: e.target.value})}
                    />
                  </div>
                </div>
                <div className="space-y-2">
                  <label className="text-xs font-black uppercase text-slate-400 tracking-widest">Start Location</label>
                  <div className="relative">
                    <MapPin className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-300" size={18} />
                    <select 
                      className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none text-slate-900"
                      value={formData.startLocation}
                      onChange={(e) => setFormData({...formData, startLocation: e.target.value as 'Srinagar' | 'Jammu'})}
                    >
                      <option value="Srinagar">Srinagar (Base)</option>
                      <option value="Jammu">Jammu (+₹1k/day Vehicle)</option>
                    </select>
                  </div>
                </div>
              </div>
              <div className="grid grid-cols-2 gap-6">
                <div className="space-y-2">
                  <label className="text-xs font-black uppercase text-slate-400 tracking-widest">Trip Type</label>
                  <select 
                    className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none text-slate-900"
                    value={formData.tripType}
                    onChange={(e) => setFormData({...formData, tripType: e.target.value as TripType})}
                  >
                    {Object.values(TripType).map(t => <option key={t} value={t}>{t}</option>)}
                  </select>
                </div>
                <div className="space-y-2">
                  <label className="text-xs font-black uppercase text-slate-400 tracking-widest">Number of Pax</label>
                  <div className="relative">
                    <Users className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-300" size={18} />
                    <input 
                      required
                      type="number" 
                      className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none text-slate-900"
                      value={formData.pax}
                      onChange={(e) => setFormData({...formData, pax: parseInt(e.target.value)})}
                    />
                  </div>
                </div>
              </div>
              <div className="grid grid-cols-2 gap-6">
                <div className="space-y-2">
                  <label className="text-xs font-black uppercase text-slate-400 tracking-widest">Start Date</label>
                  <input 
                    required
                    type="date" 
                    className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none text-slate-900"
                    value={formData.startDate}
                    onChange={(e) => setFormData({...formData, startDate: e.target.value})}
                  />
                </div>
                <div className="space-y-2">
                  <label className="text-xs font-black uppercase text-slate-400 tracking-widest">End Date</label>
                  <input 
                    required
                    type="date" 
                    className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none text-slate-900"
                    value={formData.endDate}
                    onChange={(e) => setFormData({...formData, endDate: e.target.value})}
                  />
                </div>
              </div>
            </div>
          )}

          {step === 3 && (
            <div className="space-y-6 animate-in fade-in slide-in-from-right-4">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <button 
                  type="button"
                  onClick={() => setFormData({...formData, templateId: 'blank'})}
                  className={`p-6 border-2 rounded-2xl text-left transition-all ${formData.templateId === 'blank' ? 'border-blue-600 bg-blue-50' : 'border-slate-100 bg-white hover:border-slate-200'}`}
                >
                  <h4 className="font-bold text-slate-800">Start from Scratch</h4>
                  <p className="text-sm text-slate-500 mt-1">Empty itinerary, pre-filled with global Master Terms.</p>
                </button>
                {allTemplates.map(temp => (
                  <button 
                    key={temp.id}
                    type="button"
                    onClick={() => setFormData({...formData, templateId: temp.id})}
                    className={`p-6 border-2 rounded-2xl text-left transition-all ${formData.templateId === temp.id ? 'border-blue-600 bg-blue-50' : 'border-slate-100 bg-white hover:border-slate-200'}`}
                  >
                    <h4 className="font-bold text-slate-800">{temp.name}</h4>
                    <p className="text-sm text-slate-500 mt-1">{temp.duration} • {temp.tripType}</p>
                    <div className="mt-3 flex gap-1">
                      {temp.itinerary.slice(0, 3).map((_, i) => <div key={i} className="w-4 h-1 bg-slate-200 rounded-full" />)}
                    </div>
                  </button>
                ))}
              </div>
            </div>
          )}

          <div className="mt-12 pt-8 border-t border-slate-100 flex items-center justify-between">
            {step > 1 ? (
              <button type="button" onClick={handleBack} className="px-6 py-2 text-slate-500 font-bold hover:text-slate-800">Back</button>
            ) : <div></div>}

            {step < 3 ? (
              <button type="button" onClick={handleNext} className="bg-blue-600 text-white px-8 py-3 rounded-xl font-bold flex items-center gap-2 hover:bg-blue-700 shadow-lg shadow-blue-100 transition-all">Continue <ChevronRight size={18} /></button>
            ) : (
              <button type="submit" className="bg-emerald-600 text-white px-10 py-3 rounded-xl font-bold flex items-center gap-2 hover:bg-emerald-700 shadow-lg shadow-emerald-100 transition-all">Create Trip & Open Builder</button>
            )}
          </div>
        </form>
      </div>
    </div>
  );
};

export default NewTrip;

import React, { useState, useMemo, useEffect } from 'react';
import { useParams, useNavigate, Link } from 'react-router-dom';
import { 
  Plus, 
  Trash2, 
  Save, 
  Sparkles,
  ArrowLeft,
  CalendarDays,
  Hotel as HotelIcon,
  Car as CarIcon,
  History,
  Download,
  Check,
  MapPin,
  Utensils,
  Map as MapIcon,
  PlusCircle,
  Wallet,
  MapPinned,
  IndianRupee,
  Star,
  ListPlus,
  X,
  ChevronRight,
  ShieldCheck,
  XCircle,
  Trophy,
  Award,
  Crown,
  Compass,
  ArrowRightLeft,
  Bed,
  Moon,
  Clock,
  RefreshCcw,
  Percent,
  Calculator,
