  const handleEditSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingLead) return;
    let updatedLead: Lead = { ...editingLead, updatedAt: new Date().toISOString() };
    updatedLead = recordActivity(updatedLead, 'NoteAdded', 'Client profile updated');
