                <div className="space-y-2"><label className="text-[10px] font-black uppercase text-slate-400">Task</label><input required type="text" className="w-full p-3 bg-slate-50 border rounded-xl font-bold text-sm" value={fuFormData.note} onChange={e => setFuFormData({...fuFormData, note: e.target.value})} /></div>
