                      </div>
                    </div>
                  );
                })}
                <button onClick={handleAddDay} className="w-full py-5 border-2 border-dashed border-slate-200 rounded-2xl text-slate-400 font-black uppercase tracking-widest text-[10px] flex items-center justify-center gap-2 hover:border-blue-300 hover:text-blue-600 transition-all"><Plus size={16} /> Append Final Day</button>
              </div>
           </div>
        </div>

        {/* Center: Editor */}
        <div className="col-span-12 lg:col-span-6 space-y-8 overflow-y-auto pr-2 pb-24">
           {trip.itinerary[activeDayIndex] && (
             <div className="bg-white border border-slate-200 rounded-[40px] p-10 shadow-sm space-y-10">
                <div className="space-y-3">
                   <label className="text-[11px] font-black uppercase tracking-[0.2em] text-slate-400 ml-1">Daily Title Headline</label>
                   <input type="text" value={trip.itinerary[activeDayIndex].title} onChange={(e) => updateDay(activeDayIndex, { title: e.target.value })} className="w-full px-8 py-6 bg-blue-50/30 border-2 border-blue-100 rounded-3xl text-2xl font-black text-slate-900 focus:bg-white transition-all outline-none" />
                </div>
                <div className="grid grid-cols-2 gap-8">
                   <div className="space-y-4">
                      <label className="text-xs font-black uppercase text-slate-700 flex items-center gap-2 tracking-widest"><MapPin size={16} className="text-blue-500" /> Destination City</label>
                      <select value={trip.itinerary[activeDayIndex].location || 'Srinagar'} onChange={(e) => updateDay(activeDayIndex, { location: e.target.value })} className="w-full p-4 bg-slate-50 border border-slate-200 rounded-2xl font-black text-xs text-slate-900 outline-none uppercase tracking-widest">
                         <option value="Srinagar">Srinagar</option><option value="Gulmarg">Gulmarg</option><option value="Pahalgam">Pahalgam</option><option value="Sonamarg">Sonamarg</option>
                         {hotelLocations.filter(l => !['Srinagar', 'Gulmarg', 'Pahalgam', 'Sonamarg'].includes(l)).map(loc => <option key={loc} value={loc}>{loc}</option>)}
                      </select>
                   </div>
                   <div className="space-y-4">
                      <label className="text-xs font-black uppercase text-slate-700 flex items-center gap-2 tracking-widest"><CarIcon size={16} className="text-blue-500" /> Primary Transport</label>
                      <select value={trip.itinerary[activeDayIndex].vehicleId} onChange={(e) => updateDay(activeDayIndex, { vehicleId: e.target.value })} className="w-full p-4 bg-slate-50 border border-slate-200 rounded-2xl font-black text-xs text-slate-900 outline-none">
                         <option value="">Select Transport...</option>
                         {masterVehicles.map(v => <option key={v.id} value={v.id}>{v.brand} {v.type}</option>)}
                      </select>
                   </div>
                </div>
                <div className="space-y-6">
                   <div className="flex items-center justify-between border-b border-slate-100 pb-3">
                      <h4 className="text-[10px] font-black uppercase tracking-widest text-slate-400 flex items-center gap-2">Client Narrative</h4>
                      <button onClick={handleAiDescription} disabled={isAiGenerating} className="flex items-center gap-2 text-[10px] font-black uppercase tracking-widest text-blue-600 hover:text-blue-700 disabled:opacity-50 transition-all"><Sparkles size={14} /> AI Context Suggest</button>
                   </div>
                   <textarea rows={8} value={trip.itinerary[activeDayIndex].clientNotes} onChange={(e) => updateDay(activeDayIndex, { clientNotes: e.target.value })} className="w-full p-8 bg-slate-50 border border-slate-200 rounded-[32px] text-base leading-relaxed text-slate-800 outline-none focus:bg-white transition-all shadow-inner" placeholder="Paint a picture of the day..." />
                </div>
             </div>
           )}
        </div>

        {/* Right Sidebar: Inclusions/Exclusions & Versions */}
        <div className="col-span-12 lg:col-span-3 space-y-6 overflow-y-auto pr-2 pb-20">
           <div className="flex gap-2 p-1 bg-slate-100 rounded-2xl">
              <button onClick={() => setActiveRightTab('config')} className={`flex-1 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${activeRightTab === 'config' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-400'}`}>Package</button>
              <button onClick={() => setActiveRightTab('history')} className={`flex-1 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${activeRightTab === 'history' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-400'}`}>Versions</button>
           </div>

           {activeRightTab === 'config' && (
             <div className="space-y-6 animate-in fade-in slide-in-from-right-4 duration-300">
                {/* Tiers UI - Minimal version for space */}
                <div className="bg-white border-2 border-blue-600 rounded-[32px] p-8 shadow-xl space-y-8">
                   <h3 className="text-xs font-black uppercase tracking-widest text-blue-600 flex items-center gap-2"><Crown size={18} /> Tier Management</h3>
                   {itineraryLocations.map(location => {
                    const selection = trip.hotelTiers?.find(t => t.location === location) || { signatureHotelId: '', eliteHotelId: '', primeHotelId: '' };
                    return (
                      <div key={location} className="space-y-3 pt-4 border-t border-slate-100 first:border-0 first:pt-0">
                        <p className="text-[10px] font-black uppercase text-slate-900 tracking-widest bg-blue-50 px-3 py-1 rounded-full w-fit">{location}</p>
                        <select value={selection.eliteHotelId} onChange={(e) => updateTierSelection(location, 'elite', e.target.value)} className="w-full p-2.5 bg-blue-50 border border-blue-200 rounded-xl text-[10px] font-black outline-none text-slate-900 shadow-sm">
                           <option value="">Select Elite Property...</option>
                           {masterHotels.filter(h => h.location === location).map(h => <option key={h.id} value={h.id}>{h.name}</option>)}
                        </select>
                      </div>
                    );
                   })}
                   <div className="pt-6 border-t border-slate-100 space-y-4">
                      <div className="flex items-center justify-between"><p className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Pricing Control</p><button onClick={autoCalculatePricing} className="text-[9px] font-black uppercase text-blue-600 hover:underline flex items-center gap-1"><RefreshCcw size={10}/> Auto-Calc</button></div>
                      <div className="space-y-4">
                         <div className="space-y-1"><label className="text-[9px] font-black uppercase text-blue-600 ml-1">Elite Quote (INR)</label><input type="number" value={trip.tierPrices?.elite || ''} onChange={(e) => updateTierPrice('elite', e.target.value)} className="w-full p-3 bg-blue-50 border border-blue-200 rounded-xl text-xs font-black outline-none" /></div>
                      </div>
                   </div>
                </div>

                {/* DYNAMIC TERMS SECTION: Edit/Delete/Swap */}
                <div className="space-y-6">
                  {/* INCLUSIONS BLOCK */}
                  <div className="bg-white border border-slate-200 rounded-[32px] p-8 shadow-sm space-y-6">
                    <div className="flex items-center justify-between">
                      <h3 className="text-xs font-black uppercase tracking-widest text-emerald-600 flex items-center gap-2"><ShieldCheck size={16} /> Trip Inclusions</h3>
                      <div className="flex items-center gap-2">
                        <button onClick={() => setShowInclusionLibrary(!showInclusionLibrary)} className="p-2 bg-slate-50 rounded-xl text-slate-400 hover:text-blue-600 transition-all" title="Master Library"><Library size={14} /></button>
                        <button onClick={() => syncWithMaster('inclusions')} className="p-2 bg-slate-50 rounded-xl text-slate-400 hover:text-rose-500 transition-all" title="Reset to Master"><RotateCcw size={14} /></button>
                      </div>
                    </div>
                    {showInclusionLibrary && (
                      <div className="bg-slate-900 p-4 rounded-2xl space-y-3 animate-in slide-in-from-top-2">
                        <p className="text-[8px] font-black uppercase text-slate-500 tracking-widest">Swap/Add from Master Library</p>
                        <div className="max-h-40 overflow-y-auto space-y-2 custom-scrollbar pr-1">
                          {masterInclusions.map((item, idx) => (
                            <button key={idx} onClick={() => { setTrip({...trip, inclusions: [...trip.inclusions, item]}); setShowInclusionLibrary(false); }} className="w-full text-left p-2.5 bg-white/5 hover:bg-white/10 rounded-xl text-[10px] font-bold text-slate-300 transition-all flex items-center justify-between group"><span className="truncate mr-2">{item}</span><Plus size={10} className="text-slate-600 group-hover:text-emerald-400" /></button>
                          ))}
                        </div>
                      </div>
                    )}
                    <div className="space-y-3">
                        {trip.inclusions.map((inc, i) => (
                          <div key={i} className="flex items-start gap-2 group relative">
                              <textarea 
                                value={inc}
                                onChange={(e) => updateInclusionInline(i, e.target.value)}
                                className="flex-1 text-[10px] font-bold text-slate-600 bg-emerald-50 p-3 rounded-xl outline-none focus:ring-2 focus:ring-emerald-200 resize-none overflow-hidden"
                                rows={2}
                              />
                              <div className="flex flex-col gap-1 mt-1">
                                <button onClick={() => swapToExclusion(i)} className="p-2 text-slate-300 hover:text-amber-500 transition-all" title="Move to Exclusions"><ArrowDownUp size={14}/></button>
                                <button onClick={() => removeInclusion(i)} className="p-2 text-slate-300 hover:text-rose-500 transition-all" title="Remove"><Trash2 size={14}/></button>
                              </div>
                          </div>
                        ))}
                        <div className="flex gap-2 pt-2">
                          <input type="text" placeholder="Add custom inclusion..." value={newInclusion} onChange={(e) => setNewInclusion(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && addInclusion()} className="flex-1 p-2 bg-slate-50 border border-slate-100 rounded-lg text-[10px] font-bold outline-none text-slate-900" />
                          <button onClick={addInclusion} className="bg-emerald-600 text-white p-2 rounded-lg transition-all active:scale-90"><Plus size={14}/></button>
                        </div>
                    </div>
                  </div>

                  {/* EXCLUSIONS BLOCK */}
                  <div className="bg-white border border-slate-200 rounded-[32px] p-8 shadow-sm space-y-6">
                    <div className="flex items-center justify-between">
                      <h3 className="text-xs font-black uppercase tracking-widest text-rose-500 flex items-center gap-2"><XCircle size={16} /> Trip Exclusions</h3>
                      <div className="flex items-center gap-2">
                        <button onClick={() => setShowExclusionLibrary(!showExclusionLibrary)} className="p-2 bg-slate-50 rounded-xl text-slate-400 hover:text-blue-600 transition-all" title="Master Library"><Library size={14} /></button>
                        <button onClick={() => syncWithMaster('exclusions')} className="p-2 bg-slate-50 rounded-xl text-slate-400 hover:text-rose-500 transition-all" title="Reset to Master"><RotateCcw size={14} /></button>
                      </div>
                    </div>
                    {showExclusionLibrary && (
                      <div className="bg-slate-900 p-4 rounded-2xl space-y-3 animate-in slide-in-from-top-2">
                        <p className="text-[8px] font-black uppercase text-slate-500 tracking-widest">Swap/Add from Master Library</p>
                        <div className="max-h-40 overflow-y-auto space-y-2 custom-scrollbar pr-1">
                          {masterExclusions.map((item, idx) => (
                            <button key={idx} onClick={() => { setTrip({...trip, exclusions: [...trip.exclusions, item]}); setShowExclusionLibrary(false); }} className="w-full text-left p-2.5 bg-white/5 hover:bg-white/10 rounded-xl text-[10px] font-bold text-slate-300 transition-all flex items-center justify-between group"><span className="truncate mr-2">{item}</span><Plus size={10} className="text-slate-600 group-hover:text-rose-400" /></button>
                          ))}
                        </div>
                      </div>
                    )}
                    <div className="space-y-3">
                        {trip.exclusions.map((exc, i) => (
                          <div key={i} className="flex items-start gap-2 group relative">
                              <textarea 
                                value={exc}
                                onChange={(e) => updateExclusionInline(i, e.target.value)}
                                className="flex-1 text-[10px] font-bold text-slate-600 bg-rose-50 p-3 rounded-xl outline-none focus:ring-2 focus:ring-rose-200 resize-none overflow-hidden"
                                rows={2}
                              />
                              <div className="flex flex-col gap-1 mt-1">
                                <button onClick={() => swapToInclusion(i)} className="p-2 text-slate-300 hover:text-emerald-500 transition-all" title="Move to Inclusions"><ArrowDownUp size={14}/></button>
                                <button onClick={() => removeExclusion(i)} className="p-2 text-slate-300 hover:text-rose-500 transition-all" title="Remove"><Trash2 size={14}/></button>
                              </div>
                          </div>
                        ))}
                        <div className="flex gap-2 pt-2">
                          <input type="text" placeholder="Add custom exclusion..." value={newExclusion} onChange={(e) => setNewExclusion(e.target.value)} onKeyDown={(e) => e.key === 'Enter' && addExclusion()} className="flex-1 p-2 bg-slate-50 border border-slate-100 rounded-lg text-[10px] font-bold outline-none text-slate-900" />
                          <button onClick={addExclusion} className="bg-rose-500 text-white p-2 rounded-lg transition-all active:scale-90"><Plus size={14}/></button>
                        </div>
                    </div>
                  </div>
                </div>
                <div className="pb-20" />
             </div>
           )}

           {activeRightTab === 'history' && (
             <div className="space-y-4">
                {trip.versions?.map(v => (
                  <div key={v.id} className="p-4 bg-slate-900 rounded-2xl text-white space-y-3">
                    <p className="text-xs font-black">{v.label}</p>
                    <button onClick={() => restoreVersion(v)} className="w-full py-2 bg-blue-600 rounded-xl text-[10px] font-black uppercase">Restore</button>
                  </div>
                ))}
             </div>
           )}
        </div>
      </div>

      {/* Version Modal */}
      {isVersionModalOpen && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[120] flex items-center justify-center p-4">
           <div className="bg-white rounded-[40px] shadow-2xl w-full max-w-md overflow-hidden animate-in zoom-in-95 duration-200">
              <div className="bg-slate-950 p-8 text-white flex items-center justify-between">
                 <h3 className="font-black uppercase text-sm">Save Snapshot</h3>
                 <button onClick={() => setIsVersionModalOpen(false)} className="text-slate-500 hover:text-white"><X size={24}/></button>
              </div>
              <form onSubmit={handleSaveVersion} className="p-10 space-y-6">
                 <input autoFocus required type="text" placeholder="Version label..." className="w-full p-4 bg-slate-50 border border-slate-200 rounded-2xl font-bold outline-none" value={versionLabel} onChange={(e) => setVersionLabel(e.target.value)} />
                 <button type="submit" className="w-full py-4 bg-slate-900 text-white font-black uppercase tracking-widest text-[10px] rounded-2xl shadow-xl hover:bg-blue-600 transition-all">Commit Version</button>
              </form>
           </div>
        </div>
      )}
    </div>
  );
};

