const TripBuilder: React.FC = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const [trip, setTrip] = useState<Trip | null>(null);
  const [activeDayIndex, setActiveDayIndex] = useState(0);
  const [isAiGenerating, setIsAiGenerating] = useState(false);
  const [activeRightTab, setActiveRightTab] = useState<'config' | 'history'>('config');

  const [newInclusion, setNewInclusion] = useState('');
  const [newExclusion, setNewExclusion] = useState('');

  // Master Library States
  const [masterInclusions, setMasterInclusions] = useState<string[]>([]);
  const [masterExclusions, setMasterExclusions] = useState<string[]>([]);
  const [showInclusionLibrary, setShowInclusionLibrary] = useState(false);
  const [showExclusionLibrary, setShowExclusionLibrary] = useState(false);

  // Regional Config constants
  const UNION_CAB_COST = 2500;
  const JAMMU_DAILY_SURCHARGE = 1000;

  // Versioning state
  const [isVersionModalOpen, setIsVersionModalOpen] = useState(false);
  const [versionLabel, setVersionLabel] = useState('');

  const masterHotels = useMemo(() => {
    const saved = localStorage.getItem('et_hotels');
    const custom = saved ? JSON.parse(saved) : [];
    const customIds = new Set(custom.map((h: Hotel) => h.id));
    return [...HOTELS.filter(h => !customIds.has(h.id)), ...custom];
  }, []);

  const masterVehicles = useMemo(() => {
    const saved = localStorage.getItem('et_vehicles');
    const custom = saved ? JSON.parse(saved) : [];
    const customIds = new Set(custom.map((v: Vehicle) => v.id));
    return [...VEHICLES.filter(v => !customIds.has(v.id)), ...custom];
  }, []);

  const masterAddOns = useMemo(() => {
    const saved = localStorage.getItem('et_addons');
    const custom = saved ? JSON.parse(saved) : [];
    const customIds = new Set(custom.map((a: AddOn) => a.id));
    return [...ADD_ONS.filter(a => !customIds.has(a.id)), ...custom];
  }, []);

  const hotelLocations = useMemo(() => {
    const locs = Array.from(new Set(masterHotels.map(h => h.location)));
    return locs.sort();
  }, [masterHotels]);

  useEffect(() => {
    const savedTrips = localStorage.getItem('et_trips');
    let foundTrip: Trip | undefined;

    if (savedTrips) {
      const parsed = JSON.parse(savedTrips);
      foundTrip = parsed.find((t: Trip) => t.id === id);
    }

    if (!foundTrip) {
      foundTrip = MOCK_TRIPS.find(t => t.id === id);
    }

    if (foundTrip) {
      setTrip({ 
        ...foundTrip, 
        startLocation: foundTrip.startLocation || 'Srinagar',
        numRooms: foundTrip.numRooms || 1,
        extraBeds: foundTrip.extraBeds || 0,
        childNoBed: foundTrip.childNoBed || 0,
        compChild: foundTrip.compChild || 0,
        inclusions: foundTrip.inclusions || [],
        exclusions: foundTrip.exclusions || [],
        hotelTiers: foundTrip.hotelTiers || [],
        tierPrices: foundTrip.tierPrices || { signature: 0, elite: 0, prime: 0 },
        tierMargins: foundTrip.tierMargins || { signature: 15, elite: 15, prime: 15 },
        versions: foundTrip.versions || []
      });
    }

    // Load Master Terms
    const mInc = localStorage.getItem('et_master_inclusions');
    const mExc = localStorage.getItem('et_master_exclusions');
    setMasterInclusions(mInc ? JSON.parse(mInc) : [...DEFAULT_INCLUSIONS]);
    setMasterExclusions(mExc ? JSON.parse(mExc) : [...DEFAULT_EXCLUSIONS]);
  }, [id]);

  useEffect(() => {
    if (trip) {
      const savedTrips = localStorage.getItem('et_trips');
      let allTrips: Trip[] = savedTrips ? JSON.parse(savedTrips) : [...MOCK_TRIPS];
      const index = allTrips.findIndex(t => t.id === trip.id);
      if (index > -1) allTrips[index] = trip;
      else allTrips.push(trip);
      localStorage.setItem('et_trips', JSON.stringify(allTrips));
    }
  }, [trip]);

  const itineraryLocations = useMemo(() => {
    if (!trip) return [];
    return Array.from(new Set(trip.itinerary.slice(0, -1).map(day => {
      if (day.location) return day.location;
      const hotel = masterHotels.find(h => h.id === day.hotelId);
      return hotel?.location || 'Srinagar';
    })));
  }, [trip, masterHotels]);

  const stayTracking = useMemo(() => {
    if (!trip || trip.itinerary.length < 2) return { summaries: [], dayStayInfo: {} };

    const summaries: { location: string; nights: number; startDay: number }[] = [];
    const dayStayInfo: Record<number, { nightNum: number; totalNightsInLocation: number }> = {};

    let currentLocation: string | undefined = undefined;
    let currentCount = 0;
    let currentStart = 1;
    let currentDayIndices: number[] = [];

    const stayDays = trip.itinerary.slice(0, -1);

    stayDays.forEach((day, idx) => {
      const dayLoc = day.location || masterHotels.find(h => h.id === day.hotelId)?.location || 'Srinagar';

      if (dayLoc === currentLocation) {
        currentCount++;
        currentDayIndices.push(day.dayNumber);
      } else {
        if (currentLocation) {
          summaries.push({
            location: currentLocation,
            nights: currentCount,
            startDay: currentStart
          });
          currentDayIndices.forEach((dNum, i) => {
            dayStayInfo[dNum] = { nightNum: i + 1, totalNightsInLocation: currentCount };
          });
        }
        currentLocation = dayLoc;
        currentCount = 1;
        currentStart = day.dayNumber;
        currentDayIndices = [day.dayNumber];
      }

      if (idx === stayDays.length - 1 && currentLocation) {
        summaries.push({
          location: currentLocation,
          nights: currentCount,
          startDay: currentStart
        });
        currentDayIndices.forEach((dNum, i) => {
          dayStayInfo[dNum] = { nightNum: i + 1, totalNightsInLocation: currentCount };
        });
      }
    });

    return { summaries, dayStayInfo };
  }, [trip, masterHotels]);

  const tieredCosts = useMemo(() => {
    if (!trip) return { 
      signature: { subtotal: 0, margin: 0, suggested: 0 }, 
      elite: { subtotal: 0, margin: 0, suggested: 0 }, 
      prime: { subtotal: 0, margin: 0, suggested: 0 } 
    };

    const calculateForTier = (tier: 'signature' | 'elite' | 'prime') => {
      let hotelCost = 0;
      let vehicleCost = 0;
      let activityCost = 0;
      let addOnsCost = 0;
      let jammuSurcharge = 0;
      let regionalCabCost = 0;

      trip.itinerary.forEach((day, idx) => {
        const dayLoc = day.location || masterHotels.find(h => h.id === day.hotelId)?.location || 'Srinagar';
        const tierMap = trip.hotelTiers?.find(t => t.location === dayLoc);
        const tierHotelId = tierMap?.[`${tier}HotelId` as keyof HotelTierSelection] as string;
        const hotel = masterHotels.find(h => h.id === tierHotelId);

        if (hotel && idx < trip.itinerary.length - 1) {
          // Complex Costing Formula
          const baseRoomCost = hotel.ratePerNight * (trip.numRooms || 1);
          const extraBedCost = (hotel.extraBedRate || 0) * (trip.extraBeds || 0);
          const cwbCost = (hotel.childNoBedRate || 0) * (trip.childNoBed || 0);

          hotelCost += (baseRoomCost + extraBedCost + cwbCost);
        }

        if (day.vehicleId) {
          const vehicle = masterVehicles.find(v => v.id === day.vehicleId);
          if (vehicle) {
            vehicleCost += vehicle.ratePerDay;
            if (trip.startLocation === 'Jammu') jammuSurcharge += JAMMU_DAILY_SURCHARGE;
          }
        }

        if (day.unionCabSelected) {
          regionalCabCost += UNION_CAB_COST;
        }

        (day.activityIds || []).forEach(aid => {
          const act = ACTIVITIES.find(a => a.id === aid);
          if (act) activityCost += act.costPerPax * trip.pax;
        });
      });

      trip.addOnIds.forEach(aoId => {
        const ao = masterAddOns.find(a => a.id === aoId);
        if (ao) {
          addOnsCost += ao.isPerPax ? ao.cost * trip.pax : ao.cost;
        }
      });

      const subtotal = hotelCost + vehicleCost + jammuSurcharge + activityCost + addOnsCost + regionalCabCost;
      const marginPct = trip.tierMargins?.[tier] || trip.marginPercentage || 15;
      const margin = subtotal * (marginPct / 100);

      return { 
        subtotal, 
        margin, 
        suggested: Math.ceil(subtotal + margin) 
      };
    };

    return {
      signature: calculateForTier('signature'),
      elite: calculateForTier('elite'),
      prime: calculateForTier('prime')
    };
  }, [trip, masterHotels, masterVehicles, masterAddOns]);

  // UTILS
  const generateUniqueId = () => `d-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;

  const remapItinerary = (itinerary: ItineraryDay[]) => {
    return itinerary.map((day, i) => ({
      ...day,
      dayNumber: i + 1
    }));
  };

  const updateDay = (index: number, updates: Partial<ItineraryDay>) => {
    if (!trip) return;
    const newItinerary = [...trip.itinerary];
    newItinerary[index] = { ...newItinerary[index], ...updates };
    setTrip({ ...trip, itinerary: newItinerary });
  };

  const removeDay = (index: number, e: React.MouseEvent) => {
    e.stopPropagation();
    if (!trip || trip.itinerary.length <= 1) return;
    if (!window.confirm("Are you sure you want to delete this day?")) return;
    const filtered = trip.itinerary.filter((_, i) => i !== index);
    const remapped = remapItinerary(filtered);
    if (index === activeDayIndex) {
      setActiveDayIndex(Math.min(index, remapped.length - 1));
    } else if (index < activeDayIndex) {
      setActiveDayIndex(prev => prev - 1);
    }
    setTrip({ ...trip, itinerary: remapped });
  };

  const cloneDay = (index: number, e: React.MouseEvent) => {
    e.stopPropagation();
    if (!trip) return;
    const dayToClone = trip.itinerary[index];
    const newDay: ItineraryDay = {
      ...JSON.parse(JSON.stringify(dayToClone)),
      id: generateUniqueId(),
      title: `${dayToClone.title} (Copy)`
    };
    const newItinerary = [...trip.itinerary];
    newItinerary.splice(index + 1, 0, newDay);
    setTrip({ ...trip, itinerary: remapItinerary(newItinerary) });
    setActiveDayIndex(index + 1);
  };

  const insertDay = (index: number, e: React.MouseEvent) => {
    e.stopPropagation();
    if (!trip) return;
    const prevDay = trip.itinerary[index];
    const newDay: ItineraryDay = {
      id: generateUniqueId(),
      dayNumber: index + 2,
      title: `Day ${index + 2}: New Exploration`,
      location: prevDay?.location || 'Srinagar',
      hotelId: '',
      vehicleId: prevDay?.vehicleId || '',
      activityIds: [],
      highlights: [],
      clientNotes: '',
      internalNotes: '',
      unionCabSelected: false
    };
    const newItinerary = [...trip.itinerary];
    newItinerary.splice(index + 1, 0, newDay);
    setTrip({ ...trip, itinerary: remapItinerary(newItinerary) });
    setActiveDayIndex(index + 1);
  };

  const handleAddDay = () => {
    if (!trip) return;
    const nextDayNum = trip.itinerary.length + 1;
    const lastDay = trip.itinerary[trip.itinerary.length - 1];
    const newDay: ItineraryDay = {
      id: generateUniqueId(),
      dayNumber: nextDayNum,
      title: `Day ${nextDayNum}: Exploring Kashmir`,
      location: lastDay?.location || 'Srinagar',
      hotelId: '',
      vehicleId: lastDay?.vehicleId || '',
      activityIds: [],
      highlights: [],
      clientNotes: '',
      internalNotes: '',
      unionCabSelected: false
    };
    setTrip({ ...trip, itinerary: [...trip.itinerary, newDay] });
    setActiveDayIndex(trip.itinerary.length);
  };

  const toggleActivity = (activityId: string) => {
    if (!trip) return;
    const currentDay = trip.itinerary[activeDayIndex];
    const currentActivityIds = currentDay.activityIds || [];
    const isSelected = currentActivityIds.includes(activityId);
    const updatedIds = isSelected 
      ? currentActivityIds.filter(id => id !== activityId)
      : [...currentActivityIds, activityId];
    updateDay(activeDayIndex, { activityIds: updatedIds });
  };

  const updateTierSelection = (location: string, tier: 'signature' | 'elite' | 'prime', hotelId: string) => {
    if (!trip) return;
    const tiers = [...(trip.hotelTiers || [])];
    const index = tiers.findIndex(t => t.location === location);
    if (index > -1) {
      tiers[index] = { ...tiers[index], [`${tier}HotelId`]: hotelId };
    } else {
      tiers.push({
        location,
        signatureHotelId: tier === 'signature' ? hotelId : '',
        eliteHotelId: tier === 'elite' ? hotelId : '',
        primeHotelId: tier === 'prime' ? hotelId : ''
      });
    }
    setTrip({ ...trip, hotelTiers: tiers });
  };

  const updateTierPrice = (tier: keyof TierPrices, value: string) => {
    if (!trip) return;
    setTrip({ 
      ...trip, 
      tierPrices: { 
        ...(trip.tierPrices || { signature: 0, elite: 0, prime: 0 }), 
        [tier]: parseInt(value) || 0 
      } 
    });
  };

  const updateTierMargin = (tier: keyof TierPrices, value: string) => {
    if (!trip) return;
    setTrip({
      ...trip,
      tierMargins: {
        ...(trip.tierMargins || { signature: 15, elite: 15, prime: 15 }),
        [tier]: parseInt(value) || 0
      }
    });
  };

  const autoCalculatePricing = () => {
    if (!trip) return;
    setTrip({
      ...trip,
      tierPrices: {
        signature: tieredCosts.signature.suggested,
        elite: tieredCosts.elite.suggested,
        prime: tieredCosts.prime.suggested
      }
    });
  };

  const addInclusion = () => {
    if (!trip || !newInclusion.trim()) return;
    setTrip({ ...trip, inclusions: [...(trip.inclusions || []), newInclusion.trim()] });
    setNewInclusion('');
  };

  const updateInclusionInline = (index: number, value: string) => {
    if (!trip) return;
    const updated = [...trip.inclusions];
    updated[index] = value;
    setTrip({ ...trip, inclusions: updated });
  };

  const removeInclusion = (idx: number) => {
    if (!trip) return;
    setTrip({ ...trip, inclusions: (trip.inclusions || []).filter((_, i) => i !== idx) });
  };

  const swapToExclusion = (idx: number) => {
    if (!trip) return;
    const item = trip.inclusions[idx];
    setTrip({
      ...trip,
      inclusions: trip.inclusions.filter((_, i) => i !== idx),
      exclusions: [...trip.exclusions, item]
    });
  };

  const addExclusion = () => {
    if (!trip || !newExclusion.trim()) return;
    setTrip({ ...trip, exclusions: [...(trip.exclusions || []), newExclusion.trim()] });
    setNewExclusion('');
  };

  const updateExclusionInline = (index: number, value: string) => {
    if (!trip) return;
    const updated = [...trip.exclusions];
    updated[index] = value;
    setTrip({ ...trip, exclusions: updated });
  };

  const removeExclusion = (idx: number) => {
    if (!trip) return;
    setTrip({ ...trip, exclusions: (trip.exclusions || []).filter((_, i) => i !== idx) });
  };

  const swapToInclusion = (idx: number) => {
    if (!trip) return;
    const item = trip.exclusions[idx];
    setTrip({
      ...trip,
      exclusions: trip.exclusions.filter((_, i) => i !== idx),
      inclusions: [...trip.inclusions, item]
    });
  };

  const syncWithMaster = (type: 'inclusions' | 'exclusions') => {
    if (!trip) return;
    if (window.confirm(`Are you sure you want to reset all trip ${type} to the Master Database values? Current custom edits will be lost.`)) {
      setTrip({ ...trip, [type]: type === 'inclusions' ? [...masterInclusions] : [...masterExclusions] });
    }
  };

  const handleAiDescription = async () => {
    if (!trip) return;
    setIsAiGenerating(true);
    const day = trip.itinerary[activeDayIndex];
    const activitiesNames = (day.activityIds || []).map(aid => ACTIVITIES.find(a => a.id === aid)?.name || '');
    const description = await generateDayDescription(day.title, activitiesNames);
    updateDay(activeDayIndex, { clientNotes: description });
    setIsAiGenerating(false);
  };

  const handleSaveVersion = (e: React.FormEvent) => {
    e.preventDefault();
    if (!trip || !versionLabel.trim()) return;
    const newVersion: TripVersion = {
      id: `v-${Date.now()}`,
      timestamp: new Date().toISOString(),
      label: versionLabel,
      itinerary: JSON.parse(JSON.stringify(trip.itinerary)),
      tierPrices: { ...(trip.tierPrices || { signature: 0, elite: 0, prime: 0 }) }
    };
    setTrip({ ...trip, versions: [newVersion, ...(trip.versions || [])] });
    setIsVersionModalOpen(false);
    setVersionLabel('');
    setActiveRightTab('history');
  };

  const restoreVersion = (version: TripVersion) => {
    if (!trip) return;
    if (!window.confirm(`Restore "${version.label}"?`)) return;
    setTrip({ ...trip, itinerary: JSON.parse(JSON.stringify(version.itinerary)), tierPrices: { ...version.tierPrices } });
    setActiveDayIndex(0);
  };

  const deleteVersion = (vId: string) => {
    if (!trip) return;
    setTrip({ ...trip, versions: (trip.versions || []).filter(v => v.id !== vId) });
  };

  if (!trip) return <div className="p-20 text-center text-slate-400 font-black uppercase tracking-widest">LOADING BUILDER...</div>;

  const currentDay = trip.itinerary[activeDayIndex];
  const isLastDay = activeDayIndex === trip.itinerary.length - 1;
  const activeLocation = currentDay?.location || masterHotels.find(h => h.id === currentDay?.hotelId)?.location || 'All';

  return (
    <div className="flex flex-col h-full space-y-6 pb-20">
      {/* Header Bar */}
      <div className="bg-white p-6 rounded-3xl border border-slate-200 shadow-sm flex flex-col md:flex-row md:items-center justify-between gap-6">
        <div className="flex items-center gap-5">
          <button onClick={() => navigate('/trips')} className="p-3 hover:bg-slate-50 rounded-2xl transition-all border border-slate-100 shadow-sm"><ArrowLeft size={20} className="text-slate-600" /></button>
          <div>
            <h1 className="text-2xl font-black text-slate-900 tracking-tight">{trip.tripName}</h1>
            <div className="flex items-center gap-3 mt-1 text-slate-400">
               <span className="text-[10px] font-black uppercase tracking-widest text-blue-600">{trip.client.name}</span>
               <span className="w-1 h-1 bg-slate-200 rounded-full"/>
               <div className="flex items-center gap-1.5 bg-slate-50 px-2 py-0.5 rounded-full border border-slate-100">
                  <MapIcon size={12} className="text-slate-400" />
                  <select 
                    className="bg-transparent text-[10px] font-black uppercase text-slate-600 outline-none cursor-pointer"
                    value={trip.startLocation}
                    onChange={(e) => setTrip({ ...trip, startLocation: e.target.value as 'Srinagar' | 'Jammu' })}
                  >
                    <option value="Srinagar">Srinagar Start</option>
                    <option value="Jammu">Jammu Start (+₹1k/Day)</option>
                  </select>
               </div>
            </div>
          </div>
        </div>
        <div className="flex items-center gap-4">
          <div className="flex items-center gap-6 px-6 py-3 bg-blue-600 rounded-2xl shadow-xl shadow-blue-900/20">
             <div className="text-right">
               <p className="text-[9px] font-black text-blue-100 uppercase tracking-widest">Selected Elite Quote</p>
               <p className="text-xl font-black text-white">₹{(trip.tierPrices?.elite || tieredCosts.elite.suggested).toLocaleString()}</p>
             </div>
          </div>
          <button onClick={() => setIsVersionModalOpen(true)} className="p-4 bg-slate-100 text-slate-600 rounded-2xl hover:bg-blue-50 transition-all shadow-sm" title="Save Version"><FileClock size={20} /></button>
          <button onClick={() => navigate(`/trips/${trip.id}/print`)} className="bg-slate-900 text-white px-8 py-4 rounded-2xl font-black uppercase tracking-widest text-xs flex items-center gap-3 shadow-xl hover:bg-black transition-all active:scale-95"><Download size={18} /> PROPOSAL / PDF</button>
        </div>
      </div>

      <div className="grid grid-cols-12 gap-8 flex-1 overflow-hidden">
        {/* Left: Day List */}
        <div className="col-span-12 lg:col-span-3 space-y-6 overflow-y-auto pr-2">
           <div className="bg-white border border-slate-200 rounded-[32px] p-6 shadow-sm flex flex-col h-fit">
              <h3 className="text-xs font-black uppercase tracking-widest text-slate-400 flex items-center gap-2 mb-6"><CalendarDays size={16} className="text-blue-600" /> Trip Steps</h3>
              <div className="space-y-4">
                {trip.itinerary.map((day, idx) => {
                  const hotel = masterHotels.find(h => h.id === day.hotelId);
                  const isSelected = activeDayIndex === idx;
                  return (
                    <div key={day.id} className="relative group">
                      <button onClick={() => setActiveDayIndex(idx)} className={`w-full text-left p-4 rounded-2xl border transition-all flex flex-col gap-1 ${isSelected ? 'bg-blue-600 border-blue-600 text-white shadow-lg' : 'bg-white border-slate-100 hover:border-slate-300 text-slate-700'}`}>
                        <div className="flex justify-between items-center"><span className={`text-[9px] font-black uppercase tracking-widest ${isSelected ? 'text-blue-100' : 'text-blue-600'}`}>Day {day.dayNumber}</span></div>
                        <h4 className="font-bold text-sm truncate pr-10">{day.title}</h4>
                      </button>
                      <div className={`absolute -right-2 top-1/2 -translate-y-1/2 flex flex-col gap-1 transition-all duration-200 z-20 ${isSelected ? 'opacity-100 scale-100' : 'opacity-0 scale-95 group-hover:opacity-100'}`}>
                         <button onClick={(e) => insertDay(idx, e)} title="Add Day After" className="p-1.5 bg-emerald-500 text-white rounded-lg shadow-lg hover:bg-emerald-600 active:scale-90 transition-all border-2 border-white"><PlusCircle size={14} /></button>
                         <button onClick={(e) => cloneDay(idx, e)} title="Clone Day" className="p-1.5 bg-blue-500 text-white rounded-lg shadow-lg hover:bg-blue-600 active:scale-90 transition-all border-2 border-white"><Copy size={14} /></button>
                         {trip.itinerary.length > 1 && <button onClick={(e) => removeDay(idx, e)} title="Delete Day" className="p-1.5 bg-rose-500 text-white rounded-lg shadow-lg hover:bg-rose-600 active:scale-90 transition-all border-2 border-white"><Trash2 size={14} /></button>}
                      </div>
                    </div>
                  );
                })}
                <button onClick={handleAddDay} className="w-full py-5 border-2 border-dashed border-slate-200 rounded-2xl text-slate-400 font-black uppercase tracking-widest text-[10px] flex items-center justify-center gap-2 hover:border-blue-300 hover:text-blue-600 transition-all"><Plus size={16} /> Append Final Day</button>
              </div>
           </div>
        </div>

        {/* Center: Editor */}
        <div className="col-span-12 lg:col-span-6 space-y-8 overflow-y-auto pr-2 pb-24">
           {trip.itinerary[activeDayIndex] && (
             <div className="bg-white border border-slate-200 rounded-[40px] p-10 shadow-sm space-y-10">
                <div className="space-y-3">
                   <label className="text-[11px] font-black uppercase tracking-[0.2em] text-slate-400 ml-1">Daily Title Headline</label>
                   <input type="text" value={trip.itinerary[activeDayIndex].title} onChange={(e) => updateDay(activeDayIndex, { title: e.target.value })} className="w-full px-8 py-6 bg-blue-50/30 border-2 border-blue-100 rounded-3xl text-2xl font-black text-slate-900 focus:bg-white transition-all outline-none" />
                </div>
                <div className="grid grid-cols-2 gap-8">
                   <div className="space-y-4">
                      <label className="text-xs font-black uppercase text-slate-700 flex items-center gap-2 tracking-widest"><MapPin size={16} className="text-blue-500" /> Destination City</label>
                      <select value={trip.itinerary[activeDayIndex].location || 'Srinagar'} onChange={(e) => updateDay(activeDayIndex, { location: e.target.value })} className="w-full p-4 bg-slate-50 border border-slate-200 rounded-2xl font-black text-xs text-slate-900 outline-none uppercase tracking-widest">
                         <option value="Srinagar">Srinagar</option><option value="Gulmarg">Gulmarg</option><option value="Pahalgam">Pahalgam</option><option value="Sonamarg">Sonamarg</option>
                         {hotelLocations.filter(l => !['Srinagar', 'Gulmarg', 'Pahalgam', 'Sonamarg'].includes(l)).map(loc => <option key={loc} value={loc}>{loc}</option>)}
                      </select>
                   </div>
                   <div className="space-y-4">
                      <label className="text-xs font-black uppercase text-slate-700 flex items-center gap-2 tracking-widest"><CarIcon size={16} className="text-blue-500" /> Primary Transport</label>
                      <select value={trip.itinerary[activeDayIndex].vehicleId} onChange={(e) => updateDay(activeDayIndex, { vehicleId: e.target.value })} className="w-full p-4 bg-slate-50 border border-slate-200 rounded-2xl font-black text-xs text-slate-900 outline-none">
                         <option value="">Select Transport...</option>
                         {masterVehicles.map(v => <option key={v.id} value={v.id}>{v.brand} {v.type}</option>)}
                      </select>
                   </div>
                </div>
                <div className="space-y-6">
                   <div className="flex items-center justify-between border-b border-slate-100 pb-3">
                      <h4 className="text-[10px] font-black uppercase tracking-widest text-slate-400 flex items-center gap-2">Client Narrative</h4>
                      <button onClick={handleAiDescription} disabled={isAiGenerating} className="flex items-center gap-2 text-[10px] font-black uppercase tracking-widest text-blue-600 hover:text-blue-700 disabled:opacity-50 transition-all"><Sparkles size={14} /> AI Context Suggest</button>
                   </div>
                   <textarea rows={8} value={trip.itinerary[activeDayIndex].clientNotes} onChange={(e) => updateDay(activeDayIndex, { clientNotes: e.target.value })} className="w-full p-8 bg-slate-50 border border-slate-200 rounded-[32px] text-base leading-relaxed text-slate-800 outline-none focus:bg-white transition-all shadow-inner" placeholder="Paint a picture of the day..." />
                </div>
             </div>
           )}
        </div>

        {/* Right Sidebar: Inclusions/Exclusions & Versions */}
        <div className="col-span-12 lg:col-span-3 space-y-6 overflow-y-auto pr-2 pb-20">
           <div className="flex gap-2 p-1 bg-slate-100 rounded-2xl">
              <button onClick={() => setActiveRightTab('config')} className={`flex-1 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${activeRightTab === 'config' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-400'}`}>Package</button>
              <button onClick={() => setActiveRightTab('history')} className={`flex-1 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${activeRightTab === 'history' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-400'}`}>History</button>
           </div>

           {activeRightTab === 'config' && (
             <div className="space-y-6 animate-in fade-in slide-in-from-right-4 duration-300">
                {/* ADVANCED OCCUPANCY BLOCK */}
                <div className="bg-white border-2 border-slate-900 rounded-[32px] p-6 shadow-sm space-y-6">
                   <h3 className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-400 flex items-center gap-2">
                     <Users size={16} className="text-blue-600" /> Rooming Logistics
                   </h3>
                   <div className="grid grid-cols-2 gap-4">
                      <div className="space-y-1">
                         <label className="text-[9px] font-black uppercase text-slate-500">Rooms</label>
                         <input type="number" value={trip.numRooms} onChange={e => setTrip({...trip, numRooms: parseInt(e.target.value) || 0})} className="w-full p-2 bg-slate-50 border rounded-xl font-bold text-xs" />
                      </div>
                      <div className="space-y-1">
                         <label className="text-[9px] font-black uppercase text-slate-500">Extra Beds</label>
                         <input type="number" value={trip.extraBeds} onChange={e => setTrip({...trip, extraBeds: parseInt(e.target.value) || 0})} className="w-full p-2 bg-slate-50 border rounded-xl font-bold text-xs" />
                      </div>
                      <div className="space-y-1">
                         <label className="text-[9px] font-black uppercase text-slate-500">Child (No Bed)</label>
                         <input type="number" value={trip.childNoBed} onChange={e => setTrip({...trip, childNoBed: parseInt(e.target.value) || 0})} className="w-full p-2 bg-slate-50 border rounded-xl font-bold text-xs" />
                      </div>
                      <div className="space-y-1">
