                      value={formData.childNoBed} 
                      onChange={e => setFormData({...formData, childNoBed: parseInt(e.target.value) || 0})} 
                    />
                  </div>
                  <div className="space-y-1.5">
                    <label className="text-[9px] font-black uppercase text-slate-400">Comp. Child</label>
                    <input 
                      type="number" 
                      className="w-full px-3 py-2 bg-white border border-slate-200 rounded-xl font-bold text-sm text-slate-900 outline-none focus:ring-2 focus:ring-blue-500" 
                      value={formData.compChild} 
                      onChange={e => setFormData({...formData, compChild: parseInt(e.target.value) || 0})} 
                    />
                  </div>
                </div>
              </div>

              <div className="grid grid-cols-2 gap-6">
                <div className="space-y-2">
                  <label className="text-xs font-black uppercase text-slate-400 tracking-widest">Start Date</label>
                  <input 
                    required
                    type="date" 
                    className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl focus:ring-2 focus:ring-blue-500 outline-none text-slate-900"
