                  <div className="flex items-center">
                    <button onClick={() => swapToExclusion(idx)} className="text-slate-300 hover:text-amber-500 p-1" title="Move to Exclusions"><ArrowDownUp size={12}/></button>
                    <button onClick={() => removeInclusion(idx)} className="text-slate-300 hover:text-rose-500 p-1"><Trash2 size={12}/></button>
                  </div>
                </div>
              ))}
              <div className="flex gap-1 mt-2">
                <input 
                  type="text" 
                  placeholder="New..." 
                  value={newInclusion}
                  onChange={(e) => setNewInclusion(e.target.value)}
                  className="flex-1 text-[10px] p-2 border border-slate-200 rounded-lg outline-none"
