                  </tr>
                </tbody>
              </table>
            </div>
            <p className="text-[10px] text-slate-400 font-black italic uppercase tracking-[0.2em] text-center">
              *All inclusive pricing for {(trip.pax || 2)} persons. Subject to availability at booking.
            </p>
          </div>
        </div>

        {/* PAGE 2: DAY WISE SUMMARY */}
        <div className="page-break" />
        <div className="p-16 space-y-12">
           <h4 className="text-3xl font-black text-blue-900 tracking-tight flex items-center gap-5 uppercase">
              <Compass size={36} className="text-blue-600" /> Planned Itinerary Summary
           </h4>
           <div className="overflow-hidden border-2 border-slate-900 rounded-lg shadow-sm">
              <table className="w-full text-left border-collapse">
                <thead className="bg-slate-100 border-b-2 border-slate-900 text-[11px] font-black uppercase text-blue-900">
                  <tr>
                    <th className="px-6 py-5 border-r-2 border-slate-900 w-28">Day</th>
                    <th className="px-6 py-5 border-r-2 border-slate-900">Program & Experience</th>
