                                 )}
                                 {dayActivities.map((act, i) => (
                                    <span key={i} className="px-2 py-1 bg-emerald-50 border border-emerald-100 text-emerald-700 rounded-md text-[9px] font-black uppercase tracking-wider">
                                       ✓ {act}
