                        <td className="px-6 py-6 text-blue-900 font-black uppercase tracking-wider">
                          {isDepartureDay ? (
                            <div className="flex flex-col items-center gap-1 text-rose-600">
                              <PlaneTakeoff size={18} />
                              <span className="text-[10px]">CHECKOUT</span>
                            </div>
                          ) : (
                            day.location || hotel?.location || 'Srinagar'
                          )}
                        </td>
                      </tr>
                    );
                  })}
                </tbody>
