                       <span className="text-rose-500 font-black text-lg">•</span> {exc}
                    </li>
                  ))}
                </ul>
             </div>
          </div>
        </div>

        {/* PAGE 3: TERMS & POLICIES */}
        <div className="page-break" />
        <div className="p-16 space-y-10">

          {/* TERMS AND CONDITIONS */}
          <div className="space-y-6">
            <h4 className="text-2xl font-black text-slate-900 border-l-8 border-slate-900 pl-4 uppercase tracking-widest flex items-center gap-3">
