  const [newInclusion, setNewInclusion] = useState('');
  const [newExclusion, setNewExclusion] = useState('');

  // Combined master hotels (mock + local)
  const masterHotels = useMemo(() => {
    const saved = localStorage.getItem('et_hotels');
    const custom = saved ? JSON.parse(saved) : [];
    const customIds = new Set(custom.map((h: Hotel) => h.id));
    return [...HOTELS.filter(h => !customIds.has(h.id)), ...custom];
  }, []);

  useEffect(() => {
    const savedTemplatesRaw = localStorage.getItem('et_templates');
    const savedTemplates = savedTemplatesRaw ? JSON.parse(savedTemplatesRaw) : [];
    const merged = [...MOCK_TEMPLATES, ...savedTemplates];
    const found = merged.find(t => t.id === id);
    if (found) setTemplate(JSON.parse(JSON.stringify(found)));
    else setTemplate({ 
      id: `temp-${Date.now()}`, 
      name: 'New Custom Template', 
      duration: '1 Day', 
      tripType: TripType.FAMILY, 
      baseMargin: 15, 
      pax: 2,
      numRooms: 1,
      extraBeds: 0,
      childNoBed: 0,
      compChild: 0,
      itinerary: [],
      inclusions: [...DEFAULT_INCLUSIONS],
      exclusions: [...DEFAULT_EXCLUSIONS]
    });
  }, [id]);

  useEffect(() => {
    if (template?.itinerary[activeDayIndex]?.hotelId) {
      const currentHotel = masterHotels.find(h => h.id === template.itinerary[activeDayIndex].hotelId);
      if (currentHotel) setHotelCategoryFilter(currentHotel.category);
      else setHotelCategoryFilter('All');
    } else setHotelCategoryFilter('All');
  }, [activeDayIndex, template?.itinerary, masterHotels]);

  const filteredHotels = useMemo(() => {
    if (hotelCategoryFilter === 'All') return masterHotels;
    return masterHotels.filter(h => h.category === hotelCategoryFilter);
  }, [hotelCategoryFilter, masterHotels]);

  if (!template) return <div className="p-10 text-center text-slate-400 font-bold">Loading Template...</div>;

  const handleSave = () => {
    if (!template) return;
    const savedTemplatesRaw = localStorage.getItem('et_templates');
    let savedTemplates: TripTemplate[] = savedTemplatesRaw ? JSON.parse(savedTemplatesRaw) : [];
    const index = savedTemplates.findIndex(t => t.id === template.id);
    if (index > -1) savedTemplates[index] = template;
    else savedTemplates.push(template);
    localStorage.setItem('et_templates', JSON.stringify(savedTemplates));
    alert("Template updated successfully!");
    navigate('/templates');
  };

  const updateDay = (index: number, updates: Partial<ItineraryDay>) => {
    const newItinerary = [...template.itinerary];
    newItinerary[index] = { ...newItinerary[index], ...updates };
    setTemplate({ ...template, itinerary: newItinerary });
  };

  const remapItinerary = (itinerary: ItineraryDay[]) => {
    return itinerary.map((day, i) => ({
      ...day,
      dayNumber: i + 1
    }));
  };

  const updateDurationString = (dayCount: number) => {
    if (dayCount <= 0) return '0 Days';
    if (dayCount === 1) return '1 Day';
    return `${dayCount} Days, ${dayCount - 1} Nights`;
  };

  const removeDay = (index: number, e: React.MouseEvent) => {
    e.stopPropagation();
    if (!template || template.itinerary.length <= 1) return;

    if (!window.confirm("Delete this step from the template?")) return;

    const filtered = template.itinerary.filter((_, i) => i !== index);
    const remapped = remapItinerary(filtered);

    if (index === activeDayIndex) {
      setActiveDayIndex(Math.min(index, remapped.length - 1));
    } else if (index < activeDayIndex) {
      setActiveDayIndex(prev => prev - 1);
    }

    setTemplate({
      ...template,
      itinerary: remapped,
      duration: updateDurationString(remapped.length)
    });
  };

  const handleAddDay = async () => {
    const nextDayNum = template.itinerary.length + 1;
    const lastDay = template.itinerary[template.itinerary.length - 1];
    const newDay: ItineraryDay = { id: `d-${Date.now()}`, dayNumber: nextDayNum, title: `Day ${nextDayNum}: Suggesting...`, hotelId: lastDay?.hotelId || '', vehicleId: lastDay?.vehicleId || '', activityIds: [], clientNotes: '', internalNotes: '' };
    const newItinerary = [...template.itinerary, newDay];
    setTemplate({ ...template, itinerary: newItinerary, duration: updateDurationString(newItinerary.length) });
    setActiveDayIndex(newItinerary.length - 1);
    const suggestedTitle = await suggestNextDayTitle(lastDay?.title || 'Start of Trip', template.tripType, nextDayNum);
    updateDay(newItinerary.length - 1, { title: suggestedTitle });
  };

  const addInclusion = () => {
    if (!template || !newInclusion.trim()) return;
    setTemplate({ ...template, inclusions: [...(template.inclusions || []), newInclusion.trim()] });
    setNewInclusion('');
  };

  const removeInclusion = (index: number) => {
    const updated = [...template.inclusions];
    updated.splice(index, 1);
    setTemplate({ ...template, inclusions: updated });
  };

  const swapToExclusion = (idx: number) => {
    if (!template) return;
    const item = template.inclusions[idx];
    setTemplate({
      ...template,
      inclusions: template.inclusions.filter((_, i) => i !== idx),
      exclusions: [...template.exclusions, item]
    });
  };

  const addExclusion = () => {
    if (!template || !newExclusion.trim()) return;
    setTemplate({ ...template, exclusions: [...(template.exclusions || []), newExclusion.trim()] });
    setNewExclusion('');
  };

  const removeExclusion = (index: number) => {
    const updated = [...template.exclusions];
    updated.splice(index, 1);
    setTemplate({ ...template, exclusions: updated });
  };

  const swapToInclusion = (idx: number) => {
    if (!template) return;
    const item = template.exclusions[idx];
    setTemplate({
      ...template,
      exclusions: template.exclusions.filter((_, i) => i !== idx),
      inclusions: [...template.inclusions, item]
    });
  };

  return (
    <div className="flex flex-col h-full space-y-6 pb-20">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-4">
          <button onClick={() => navigate('/templates')} className="p-2 hover:bg-white rounded-lg border border-transparent hover:border-slate-200"><ArrowLeft size={20} className="text-slate-600" /></button>
          <div><h1 className="text-2xl font-bold text-slate-900">Template Builder</h1><p className="text-slate-500 text-sm">Design reusable itineraries.</p></div>
        </div>
        <button onClick={handleSave} className="flex items-center gap-2 px-6 py-2.5 bg-blue-600 text-white rounded-xl font-bold hover:bg-blue-700 shadow-lg shadow-blue-100 transition-all"><Save size={18} />Save Template</button>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-6 flex-1 overflow-hidden">
        <div className="lg:col-span-1 space-y-6 flex flex-col overflow-y-auto">
          <div className="bg-white border border-slate-200 rounded-2xl p-6 space-y-4 shadow-sm text-slate-900">
            <h3 className="font-bold text-slate-800 flex items-center gap-2 text-sm uppercase tracking-widest"><Settings size={16} className="text-blue-600" />General Info</h3>
            <div className="space-y-4">
              <div className="space-y-1"><label className="text-[10px] font-black uppercase text-slate-400">Template Name</label><input type="text" value={template.name} onChange={(e) => setTemplate({ ...template, name: e.target.value })} className="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-lg text-sm font-bold" /></div>
              <div className="space-y-1"><label className="text-[10px] font-black uppercase text-slate-400">Trip Type</label><select value={template.tripType} onChange={(e) => setTemplate({ ...template, tripType: e.target.value as TripType })} className="w-full px-3 py-2 bg-slate-50 border border-slate-200 rounded-lg text-sm font-bold">{Object.values(TripType).map(t => <option key={t} value={t}>{t}</option>)}</select></div>
            </div>
          </div>

          <div className="bg-white border border-slate-200 rounded-2xl p-6 space-y-4 shadow-sm text-slate-900">
            <h3 className="font-bold text-slate-800 flex items-center gap-2 text-sm uppercase tracking-widest"><Users size={16} className="text-blue-600" />Default Rooming</h3>
            <div className="grid grid-cols-2 gap-3">
              <div className="space-y-1"><label className="text-[9px] font-black uppercase text-slate-400">PAX</label><input type="number" value={template.pax} onChange={e => setTemplate({...template, pax: parseInt(e.target.value) || 0})} className="w-full px-2 py-1.5 bg-slate-50 border rounded-lg text-xs font-bold" /></div>
              <div className="space-y-1"><label className="text-[9px] font-black uppercase text-slate-400">Rooms</label><input type="number" value={template.numRooms} onChange={e => setTemplate({...template, numRooms: parseInt(e.target.value) || 0})} className="w-full px-2 py-1.5 bg-slate-50 border rounded-lg text-xs font-bold" /></div>
              <div className="space-y-1"><label className="text-[9px] font-black uppercase text-slate-400">Ex. Beds</label><input type="number" value={template.extraBeds} onChange={e => setTemplate({...template, extraBeds: parseInt(e.target.value) || 0})} className="w-full px-2 py-1.5 bg-slate-50 border rounded-lg text-xs font-bold" /></div>
              <div className="space-y-1"><label className="text-[9px] font-black uppercase text-slate-400">CWB</label><input type="number" value={template.childNoBed} onChange={e => setTemplate({...template, childNoBed: parseInt(e.target.value) || 0})} className="w-full px-2 py-1.5 bg-slate-50 border rounded-lg text-xs font-bold" /></div>
            </div>
          </div>

          <div className="bg-white border border-slate-200 rounded-2xl p-6 space-y-4 shadow-sm text-slate-900">
            <h3 className="font-bold text-slate-800 flex items-center gap-2 text-sm uppercase tracking-widest"><ShieldCheck size={16} className="text-emerald-600" />Inclusions</h3>
            <div className="space-y-2">
              {template.inclusions.map((item, idx) => (
                <div key={idx} className="flex items-center gap-2 group">
                  <div className="flex-1 text-[10px] font-bold text-slate-600 bg-emerald-50 p-2 rounded-lg line-clamp-2">{item}</div>
                  <div className="flex items-center">
                    <button onClick={() => swapToExclusion(idx)} className="text-slate-300 hover:text-amber-500 p-1" title="Move to Exclusions"><ArrowDownUp size={12}/></button>
                    <button onClick={() => removeInclusion(idx)} className="text-slate-300 hover:text-rose-500 p-1"><Trash2 size={12}/></button>
                  </div>
                </div>
              ))}
              <div className="flex gap-1 mt-2">
                <input 
                  type="text" 
                  placeholder="New..." 
                  value={newInclusion}
                  onChange={(e) => setNewInclusion(e.target.value)}
                  className="flex-1 text-[10px] p-2 border border-slate-200 rounded-lg outline-none"
                />
                <button onClick={addInclusion} className="p-2 bg-blue-600 text-white rounded-lg"><Plus size={14}/></button>
              </div>
            </div>
          </div>

          <div className="bg-white border border-slate-200 rounded-2xl p-6 space-y-4 shadow-sm text-slate-900">
            <h3 className="font-bold text-slate-800 flex items-center gap-2 text-sm uppercase tracking-widest"><XCircle size={16} className="text-rose-600" />Exclusions</h3>
            <div className="space-y-2">
              {template.exclusions.map((item, idx) => (
                <div key={idx} className="flex items-center gap-2 group">
                  <div className="flex-1 text-[10px] font-bold text-slate-600 bg-rose-50 p-2 rounded-lg line-clamp-2">{item}</div>
                  <div className="flex items-center">
                    <button onClick={() => swapToInclusion(idx)} className="text-slate-300 hover:text-emerald-500 p-1" title="Move to Inclusions"><ArrowDownUp size={12}/></button>
                    <button onClick={() => removeExclusion(idx)} className="text-slate-300 hover:text-rose-500 p-1"><Trash2 size={12}/></button>
                  </div>
                </div>
              ))}
              <div className="flex gap-1 mt-2">
                <input 
                  type="text" 
                  placeholder="New..." 
                  value={newExclusion}
                  onChange={(e) => setNewExclusion(e.target.value)}
                  className="flex-1 text-[10px] p-2 border border-slate-200 rounded-lg outline-none"
                />
                <button onClick={addExclusion} className="p-2 bg-blue-600 text-white rounded-lg"><Plus size={14}/></button>
              </div>
            </div>
          </div>

          <div className="bg-white border border-slate-200 rounded-2xl flex-1 flex flex-col overflow-hidden shadow-sm min-h-[200px]">
            <div className="p-4 border-b border-slate-100 flex items-center justify-between"><h3 className="font-bold text-slate-800 flex items-center gap-2 text-sm"><Layers size={16} className="text-blue-600" />Itinerary Steps</h3></div>
            <div className="flex-1 overflow-y-auto p-4 space-y-2">
              {template.itinerary.map((day, idx) => (
                <div key={day.id} className="relative group">
                  <button onClick={() => setActiveDayIndex(idx)} className={`w-full text-left p-3 rounded-xl border transition-all pr-12 ${activeDayIndex === idx ? 'border-blue-600 bg-blue-50 shadow-sm' : 'border-slate-100 hover:border-slate-300'}`}>
                    <div className="flex justify-between items-center mb-1"><span className="text-[10px] font-black uppercase text-blue-600">Day {day.dayNumber}</span></div>
                    <h4 className={`font-semibold text-sm truncate ${activeDayIndex === idx ? 'text-blue-900' : 'text-slate-700'}`}>{day.title || 'New Step'}</h4>
                  </button>
                  {template.itinerary.length > 1 && (
                    <button 
                      onClick={(e) => removeDay(idx, e)}
                      className="absolute right-3 top-1/2 -translate-y-1/2 p-2 text-slate-300 hover:text-rose-500 opacity-0 group-hover:opacity-100 transition-all"
                      title="Remove Step"
                    >
                      <Trash2 size={14} />
                    </button>
                  )}
                </div>
              ))}
              <button onClick={handleAddDay} className="w-full py-4 border-2 border-dashed border-slate-200 rounded-xl text-slate-400 font-bold hover:border-blue-400 hover:text-blue-500 transition-all flex items-center justify-center gap-2 text-sm"><Plus size={18} />Add Step</button>
            </div>
          </div>
        </div>

        <div className="lg:col-span-3 overflow-y-auto pr-2 pb-10">
          {template.itinerary[activeDayIndex] ? (
            <div className="bg-white border border-slate-200 rounded-2xl shadow-sm p-8 space-y-8 animate-in fade-in slide-in-from-right-4 duration-200 text-slate-900">
              <div className="flex flex-col gap-2">
                <label className="text-[10px] font-black uppercase tracking-widest text-slate-400">Step Title</label>
                <input 
                  type="text" 
                  value={template.itinerary[activeDayIndex].title} 
                  onChange={(e) => updateDay(activeDayIndex, { title: e.target.value })} 
                  className="w-full px-5 py-4 bg-slate-50 border border-slate-200 rounded-2xl text-2xl font-black text-slate-900 focus:bg-white focus:ring-4 focus:ring-blue-100 transition-all outline-none placeholder:text-slate-300 shadow-inner"
                  placeholder="Step title..." 
                />
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                <div className="space-y-4">
                  <div className="flex flex-col gap-3">
                    <label className="text-sm font-bold text-slate-700 flex items-center gap-2"><HotelIcon size={16} className="text-blue-500" />Standard Stay</label>
                    <select value={template.itinerary[activeDayIndex].hotelId} onChange={(e) => updateDay(activeDayIndex, { hotelId: e.target.value })} className="w-full p-3 bg-white border border-slate-200 rounded-xl text-sm font-black text-slate-900 shadow-sm">
                      <option value="">Select Hotel</option>
                      {masterHotels.map(h => <option key={h.id} value={h.id}>{h.name} ({h.location})</option>)}
                    </select>
                  </div>
                </div>
                <div className="space-y-4">
                  <label className="text-sm font-bold text-slate-700 flex items-center gap-2"><CarIcon size={16} className="text-blue-500" />Standard Vehicle</label>
                  <select value={template.itinerary[activeDayIndex].vehicleId} onChange={(e) => updateDay(activeDayIndex, { vehicleId: e.target.value })} className="w-full p-3 bg-slate-50 border border-slate-200 rounded-xl text-sm font-medium text-slate-900">
                    <option value="">Select Suggested Vehicle</option>
                    {VEHICLES.map(v => <option key={v.id} value={v.id}>{v.type}</option>)}
                  </select>
                </div>
              </div>
              <textarea rows={6} value={template.itinerary[activeDayIndex].clientNotes} onChange={(e) => updateDay(activeDayIndex, { clientNotes: e.target.value })} className="w-full p-4 bg-slate-50 border border-slate-200 rounded-2xl text-sm leading-relaxed text-slate-900 focus:ring-2 focus:ring-blue-500 outline-none" placeholder="Describe what the guest will experience..." />
            </div>
          ) : (
            <div className="flex flex-col items-center justify-center h-96 bg-white border-2 border-dashed border-slate-200 rounded-2xl text-slate-400"><Layers size={64} className="mb-4 opacity-10" /><p className="font-bold">Add steps to this template.</p></div>
          )}
        </div>
      </div>
    </div>
  );
};

export default TemplateBuilder;

import React, { useState, useEffect, useMemo } from 'react';
// Fixed: Using namespace import for react-router-dom to resolve "no exported member" errors
import * as ReactRouterDOM from 'react-router-dom';
const { useNavigate } = ReactRouterDOM;
import { LeadStage, Lead, LeadScore, TripType } from '../types';
import { MOCK_LEADS } from '../constants';
import { 
  MoreVertical, 
  Plus, 
  Calendar, 
  MessageSquare, 
  Phone, 
  TrendingUp, 
  Flame, 
  Snowflake,
  Search,
  Clock,
  Zap,
  Filter,
  AlertTriangle,
  Edit2,
  X,
  Check,
  Timer
} from 'lucide-react';

const Pipeline: React.FC = () => {
  const navigate = useNavigate();
  const [leads, setLeads] = useState<Lead[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [editingLead, setEditingLead] = useState<Lead | null>(null);
  const [isEditModalOpen, setIsEditModalOpen] = useState(false);

  // Define 'now' for SLA calculations in the component scope
  const now = new Date();
  const stages = Object.values(LeadStage);

  useEffect(() => {
    const saved = localStorage.getItem('et_leads');
    setLeads(saved ? JSON.parse(saved) : MOCK_LEADS);
  }, []);

  const saveLeads = (updatedLeads: Lead[]) => {
    setLeads(updatedLeads);
    localStorage.setItem('et_leads', JSON.stringify(updatedLeads));
  };

  const filteredLeads = useMemo(() => {
    return leads.filter(l => 
      l.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
      l.phone.includes(searchTerm)
    );
  }, [leads, searchTerm]);

  const getLeadsByStage = (stage: LeadStage) => filteredLeads.filter(l => l.stage === stage);

  const openEditModal = (e: React.MouseEvent, lead: Lead) => {
    e.stopPropagation();
    setEditingLead({ ...lead });
    setIsEditModalOpen(true);
  };

  const handleEditSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingLead) return;
    const updated = leads.map(l => l.id === editingLead.id ? { ...editingLead, updatedAt: new Date().toISOString() } : l);
    saveLeads(updated);
    setIsEditModalOpen(false);
    setEditingLead(null);
  };

  const ScoreBadge = ({ score }: { score: LeadScore }) => {
    if (score === LeadScore.HOT) return <div className="p-2 bg-rose-100 text-rose-600 rounded-xl shadow-sm"><Flame size={14} /></div>;
    if (score === LeadScore.WARM) return <div className="p-2 bg-orange-100 text-orange-600 rounded-xl shadow-sm"><TrendingUp size={14} /></div>;
    return <div className="p-2 bg-blue-100 text-blue-600 rounded-xl shadow-sm"><Snowflake size={14} /></div>;
  };

  // Fixed: Wrapped PipelineCard in React.FC type to handle 'key' prop correctly in map callback
  const PipelineCard: React.FC<{ lead: Lead }> = ({ lead }) => {
    const now = new Date();
    const todayStr = now.toISOString().split('T')[0];
    const lastUpdate = lead.updatedAt ? new Date(lead.updatedAt) : new Date(lead.createdAt);
    const hoursInactivity = Math.floor((now.getTime() - lastUpdate.getTime()) / (1000 * 60 * 60));

    // SLA Rule 1: Stage Inactivity
    const isStageOverdue = (lead.stage === LeadStage.NEW && hoursInactivity > 24) || 
                          (lead.stage === LeadStage.PROPOSAL_SENT && hoursInactivity > 48);

    // SLA Rule 2: Overdue Tasks
    const overdueTask = lead.followUps.find(f => f.status === 'Pending' && f.date < todayStr);

    const isSLAAlert = isStageOverdue || !!overdueTask;

    return (
      <div 
        onClick={() => navigate(`/leads/${lead.id}`)}
        className={`bg-white p-6 rounded-3xl border group transition-all cursor-pointer relative overflow-hidden ${
          isSLAAlert ? 'border-rose-400 shadow-rose-100 shadow-2xl ring-4 ring-rose-50/50' : 'border-slate-100 hover:border-blue-300 hover:shadow-2xl shadow-sm'
        }`}
      >
        {isSLAAlert && (
           <div className={`absolute top-0 right-0 bg-rose-600 text-white text-[8px] font-black uppercase px-3 py-1.5 rounded-bl-xl tracking-[0.15em] flex items-center gap-1.5 shadow-lg ${isStageOverdue ? 'animate-pulse' : ''}`}>
              {overdueTask ? <Clock size={10} /> : <Timer size={10} />}
              {overdueTask ? 'TASK OVERDUE' : `INACTIVE ${hoursInactivity}H`}
           </div>
        )}

        <div className="flex items-start justify-between mb-4">
          <ScoreBadge score={lead.score} />
          <button 
            onClick={(e) => openEditModal(e, lead)}
            className="p-2 text-slate-300 hover:text-blue-600 hover:bg-blue-50 rounded-xl transition-all"
          >
            <Edit2 size={14} />
          </button>
        </div>

        <h4 className="font-black text-slate-900 mb-1 text-base tracking-tight leading-tight">{lead.name}</h4>

        <div className="flex flex-wrap items-center gap-2 mb-4">
           <span className="text-[9px] font-black text-slate-400 uppercase tracking-widest bg-slate-50 px-2 py-0.5 rounded-full">{lead.interest}</span>
           <span className="text-[9px] font-black text-blue-600 uppercase tracking-widest bg-blue-50 px-2 py-0.5 rounded-full">{lead.pax} PAX</span>
        </div>

        {overdueTask && (
          <div className="mb-4 p-3 bg-rose-50 border border-rose-100 rounded-2xl animate-in fade-in duration-300">
            <p className="text-[9px] font-black text-rose-600 uppercase tracking-wider mb-1 flex items-center gap-1">
              <AlertTriangle size={10} /> Missed Task
            </p>
            <p className="text-[11px] font-bold text-rose-800 line-clamp-1 italic">"{overdueTask.note}"</p>
          </div>
        )}

        <div className="grid grid-cols-2 gap-3 mt-4 text-slate-400 border-t border-slate-50 pt-4">
          <div className="flex items-center gap-1.5">
            <Calendar size={12} className={overdueTask ? 'text-rose-500' : 'text-slate-300'}/> 
            <span className={`text-[9px] font-bold uppercase ${overdueTask ? 'text-rose-600 font-black' : ''}`}>
              {lead.travelMonth}
            </span>
          </div>
          <div className="flex items-center gap-1.5">
            <Zap size={12} className="text-amber-400"/> 
            <span className="text-[9px] font-bold uppercase">{lead.budgetRange}</span>
          </div>
        </div>

        <div className="mt-6 flex items-center justify-between">
           <div className="flex items-center gap-2">
              <img src={`https://picsum.photos/seed/${lead.assignedTo}/32/32`} className="w-7 h-7 rounded-full border-2 border-white shadow-sm" title={lead.assignedTo} alt="Sales" />
              <span className="text-[8px] font-black uppercase text-slate-300 tracking-widest group-hover:text-slate-500 transition-colors">{lead.assignedTo.split(' ')[0]}</span>
           </div>
           <div className="flex gap-1.5">
              <button 
                onClick={(e) => { e.stopPropagation(); window.location.href = `tel:${lead.phone}`; }}
                className="p-2.5 text-slate-300 hover:text-blue-600 bg-slate-50 hover:bg-white rounded-xl transition-all active:scale-90"
              >
                <Phone size={14}/>
              </button>
              <button 
                onClick={(e) => { e.stopPropagation(); const cleanPhone = lead.phone.replace(/\D/g, ''); window.open(`https://wa.me/${cleanPhone}`, '_blank'); }}
                className="p-2.5 text-slate-300 hover:text-emerald-500 bg-slate-50 hover:bg-white rounded-xl transition-all active:scale-90"
              >
                <MessageSquare size={14}/>
              </button>
           </div>
        </div>
      </div>
    );
  };

  return (
    <div className="h-full flex flex-col gap-6 relative">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div className="flex items-center gap-4">
          <div className="relative w-96">
             <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300" size={18} />
             <input 
               type="text" 
               placeholder="Search pipeline..." 
               className="w-full pl-12 pr-4 py-4 bg-white border border-slate-200 rounded-3xl text-sm font-bold outline-none focus:ring-8 focus:ring-blue-50/50 transition-all shadow-sm text-slate-900"
               value={searchTerm}
               onChange={(e) => setSearchTerm(e.target.value)}
             />
          </div>
          <button className="p-4 bg-white border border-slate-200 rounded-3xl text-slate-400 hover:text-slate-900 transition-all active:scale-95">
             <Filter size={20} />
          </button>
        </div>
        <div className="flex items-center gap-4">
          <div className="hidden lg:flex items-center gap-2 px-4 py-2 bg-rose-50 border border-rose-100 rounded-2xl">
            <AlertTriangle size={14} className="text-rose-500 animate-pulse" />
            <span className="text-[10px] font-black text-rose-600 uppercase tracking-widest">Breached: {leads.filter(l => (l.stage === LeadStage.NEW && Math.floor((now.getTime() - (l.updatedAt ? new Date(l.updatedAt) : new Date(l.createdAt)).getTime()) / 3600000) > 24)).length}</span>
          </div>
          <button 
            onClick={() => navigate('/leads/new')}
            className="bg-blue-600 text-white px-10 py-5 rounded-3xl font-black uppercase tracking-[0.2em] text-[11px] flex items-center gap-3 hover:bg-blue-700 transition-all shadow-2xl shadow-blue-900/30 active:scale-95"
          >
            <Plus size={20} /> New Sales Lead
          </button>
        </div>
      </div>

      <div className="flex-1 overflow-x-auto pb-6 -mx-4 px-4">
        <div className="flex gap-8 h-full min-w-max">
          {stages.map(stage => {
            const stageLeads = getLeadsByStage(stage);
            return (
              <div key={stage} className="w-80 flex flex-col gap-6">
                <div className="flex items-center justify-between px-3">
                  <div className="flex items-center gap-3">
                    <h3 className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-400">{stage}</h3>
                    <span className="bg-slate-200 text-slate-600 text-[10px] font-black px-3 py-0.5 rounded-full">
                      {stageLeads.length}
                    </span>
                  </div>
                  <button className="text-slate-300 hover:text-blue-600 transition-colors"><MoreVertical size={16}/></button>
                </div>

                <div className="flex-1 bg-slate-100/40 rounded-[48px] p-5 space-y-6 border-2 border-dashed border-slate-200/50 overflow-y-auto custom-scrollbar">
                  {stageLeads.map(lead => <PipelineCard key={lead.id} lead={lead} />)}
                  {stageLeads.length === 0 && (
                    <div className="h-32 flex flex-col items-center justify-center text-slate-300 gap-3">
                       <Clock size={32} className="opacity-10" />
                       <span className="text-[9px] font-black uppercase tracking-[0.3em] opacity-30">No Active Leads</span>
                    </div>
                  )}
                  <button onClick={() => navigate('/leads/new')} className="w-full py-4 border-2 border-dashed border-slate-200 rounded-3xl text-slate-300 hover:text-blue-400 hover:border-blue-200 transition-all flex items-center justify-center gap-2 text-[10px] font-black uppercase tracking-widest">
                    <Plus size={14}/> Add to {stage}
                  </button>
                </div>
              </div>
            );
          })}
        </div>
      </div>

      {/* Edit Lead Modal */}
      {isEditModalOpen && editingLead && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[110] flex items-center justify-center p-4">
          <div className="bg-white rounded-[48px] shadow-2xl w-full max-w-2xl overflow-hidden animate-in zoom-in-95 duration-200">
             <div className="bg-slate-950 p-8 text-white flex justify-between items-center">
                <div className="flex items-center gap-4">
                   <div className="bg-blue-600 p-3 rounded-2xl">
                      <Edit2 size={24}/>
                   </div>
                   <div>
                      <h2 className="text-xl font-black tracking-tight">Edit Lead: {editingLead.name}</h2>
                      <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Pipeline Data Update</p>
                   </div>
                </div>
                <button onClick={() => setIsEditModalOpen(false)} className="text-slate-500 hover:text-white transition-colors"><X size={24}/></button>
             </div>

             <form onSubmit={handleEditSubmit} className="p-10 space-y-8 max-h-[70vh] overflow-y-auto custom-scrollbar">
                <div className="grid grid-cols-2 gap-6">
                   <div className="space-y-1">
                      <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">Full Name</label>
                      <input required type="text" className="w-full p-4 bg-slate-50 border border-slate-200 rounded-2xl font-bold outline-none text-slate-900" value={editingLead.name} onChange={e => setEditingLead({...editingLead, name: e.target.value})} />
                   </div>
                   <div className="space-y-1">
                      <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">Phone</label>
                      <input required type="text" className="w-full p-4 bg-slate-50 border border-slate-200 rounded-2xl font-bold outline-none text-slate-900" value={editingLead.phone} onChange={e => setEditingLead({...editingLead, phone: e.target.value})} />
                   </div>
                </div>

                <div className="grid grid-cols-2 gap-6">
                   <div className="space-y-1">
                      <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">Email</label>
                      <input type="email" className="w-full p-4 bg-slate-50 border border-slate-200 rounded-2xl font-bold outline-none text-slate-900" value={editingLead.email} onChange={e => setEditingLead({...editingLead, email: e.target.value})} />
                   </div>
                   <div className="space-y-1">
                      <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">Priority Score</label>
                      <select className="w-full p-4 bg-slate-50 border border-slate-200 rounded-2xl font-bold outline-none text-slate-900" value={editingLead.score} onChange={e => setEditingLead({...editingLead, score: e.target.value as LeadScore})}>
                         {Object.values(LeadScore).map(s => <option key={s} value={s}>{s}</option>)}
                      </select>
                   </div>
                </div>

                <div className="grid grid-cols-3 gap-4">
                   <div className="space-y-1">
                      <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">Travel Month</label>
                      <input type="text" className="w-full p-4 bg-slate-50 border border-slate-200 rounded-2xl font-bold outline-none text-slate-900" value={editingLead.travelMonth} onChange={e => setEditingLead({...editingLead, travelMonth: e.target.value})} />
                   </div>
                   <div className="space-y-1">
                      <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">Budget</label>
                      <input type="text" className="w-full p-4 bg-slate-50 border border-slate-200 rounded-2xl font-bold outline-none text-slate-900" value={editingLead.budgetRange} onChange={e => setEditingLead({...editingLead, budgetRange: e.target.value})} />
                   </div>
                   <div className="space-y-1">
                      <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">Pax</label>
                      <input type="number" className="w-full p-4 bg-slate-50 border border-slate-200 rounded-2xl font-bold outline-none text-slate-900" value={editingLead.pax} onChange={e => setEditingLead({...editingLead, pax: parseInt(e.target.value)})} />
                   </div>
                </div>

                <div className="space-y-1">
                   <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest ml-1">Sales Notes</label>
                   <textarea rows={4} className="w-full p-4 bg-slate-50 border border-slate-200 rounded-2xl font-medium outline-none text-slate-900" value={editingLead.notes} onChange={e => setEditingLead({...editingLead, notes: e.target.value})} />
                </div>

                <div className="pt-4 flex gap-4">
                   <button type="button" onClick={() => setIsEditModalOpen(false)} className="flex-1 py-4 text-slate-400 font-black uppercase tracking-widest text-[10px] hover:bg-slate-50 rounded-2xl transition-all">Discard</button>
                   <button type="submit" className="flex-[2] py-4 bg-blue-600 text-white font-black uppercase tracking-widest text-[10px] rounded-2xl shadow-xl hover:bg-blue-700 transition-all flex items-center justify-center gap-2">
                      <Check size={18}/> Update Lead
                   </button>
                </div>
             </form>
          </div>
        </div>
      )}
    </div>
  );
};

export default Pipeline;

import React, { useState, useEffect, useRef } from 'react';
import { Link, useLocation, useNavigate } from 'react-router-dom';
import { 
  LayoutDashboard, 
  Trello, 
  Users, 
  Map, 
  Hotel as HotelIcon, 
  Car, 
  Sparkles,
  Settings,
  LogOut,
  Mountain,
  FileText,
  Compass,
  Bell,
  X,
  AlertTriangle,
  Clock,
  ChevronRight,
  MessageSquare,
  ChevronDown,
  User as UserIcon,
  ShieldCheck,
  Zap,
  Briefcase,
  ListChecks
} from 'lucide-react';
import { Lead, LeadStage, UserRole, TeamMember } from '../types';
import { MOCK_LEADS, DEFAULT_PERSONAS } from '../constants';
import { sendSimulatedMessage, DEFAULT_TEMPLATES, saveMessageLog } from '../services/messagingService';

const SidebarItem = ({ icon: Icon, label, path, active, roleColor }: { icon: any, label: string, path: string, active: boolean, roleColor: string }) => (
  <Link 
    to={path} 
    className={`flex items-center gap-3 px-4 py-3 rounded-2xl transition-all ${
      active ? `${roleColor} text-white shadow-lg` : 'text-slate-400 hover:bg-slate-800 hover:text-white'
    }`}
  >
    <Icon size={18} />
    <span className="font-bold text-[13px]">{label}</span>
  </Link>
);

const SidebarHeader = ({ label }: { label: string }) => (
  <p className="text-slate-600 text-[10px] font-black uppercase tracking-[0.2em] mb-3 mt-6 ml-4">{label}</p>
);

const Layout: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const location = useLocation();
  const navigate = useNavigate();
  const [showNotifications, setShowNotifications] = useState(false);
  const [showProfileMenu, setShowProfileMenu] = useState(false);
  const [currentUser, setCurrentUser] = useState<TeamMember>(DEFAULT_PERSONAS[0]);
  const [teamMembers, setTeamMembers] = useState<TeamMember[]>(DEFAULT_PERSONAS);
  const [alerts, setAlerts] = useState<{ id: string, title: string, desc: string, type: 'danger' | 'warning' | 'info' | 'success', leadId: string }[]>([]);
  const profileRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const refreshUser = () => {
      const savedMembers = localStorage.getItem('et_team_members');
      const members: TeamMember[] = savedMembers ? JSON.parse(savedMembers) : DEFAULT_PERSONAS;
      setTeamMembers(members);

      const activeMemberId = localStorage.getItem('et_active_member_id');
      const found = members.find(m => m.id === activeMemberId);

      if (found) {
        setCurrentUser(found);
      } else {
        const firstAvailable = members.length > 0 ? members[0] : DEFAULT_PERSONAS[0];
        setCurrentUser(firstAvailable);
        localStorage.setItem('et_active_member_id', firstAvailable.id);
      }
    };

    refreshUser();

    window.addEventListener('storage', refreshUser);
    window.addEventListener('user-profile-updated', refreshUser);

    const handleClickOutside = (event: MouseEvent) => {
      if (profileRef.current && !profileRef.current.contains(event.target as Node)) {
        setShowProfileMenu(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => {
      window.removeEventListener('storage', refreshUser);
      window.removeEventListener('user-profile-updated', refreshUser);
      document.removeEventListener('mousedown', handleClickOutside);
    };
  }, []);

  const switchPersona = (member: TeamMember) => {
    localStorage.setItem('et_active_member_id', member.id);
    window.dispatchEvent(new Event('user-profile-updated'));
    setShowProfileMenu(false);
  };

  const isAllowed = (path: string) => {
    if (currentUser.role === UserRole.ADMIN) return true;
    const salesPaths = ['/', '/pipeline', '/leads', '/trips', '/templates'];
    const opsPaths = ['/trips', '/hotels', '/vehicles', '/activities', '/add-ons', '/master-terms'];
    if (currentUser.role === UserRole.SALES) return salesPaths.includes(path) || path.startsWith('/leads') || path.startsWith('/trips');
    if (currentUser.role === UserRole.OPERATIONS) return opsPaths.includes(path) || path.startsWith('/trips');
    return false;
  };

  useEffect(() => {
    const runAutomationJob = async () => {
      const savedLeads = localStorage.getItem('et_leads');
      const leads: Lead[] = savedLeads ? JSON.parse(savedLeads) : MOCK_LEADS;
      const now = new Date();
      const savedLogs = localStorage.getItem('et_message_logs');
      const allLogs = savedLogs ? JSON.parse(savedLogs) : [];

      for (const lead of leads) {
        const lastUpdate = lead.updatedAt ? new Date(lead.updatedAt) : new Date(lead.createdAt);
        const hoursInactivity = (now.getTime() - lastUpdate.getTime()) / (1000 * 60 * 60);

        if (lead.stage === LeadStage.NEW && hoursInactivity > 24) {
          const hasAlreadySentWelcome = allLogs.some((l: any) => l.leadId === lead.id && l.templateId === 'welcome-wa');
          if (!hasAlreadySentWelcome && lead.whatsappOptIn) {
            const template = DEFAULT_TEMPLATES.find(t => t.id === 'welcome-wa');
            if (template) {
              const log = await sendSimulatedMessage(lead, template);
              saveMessageLog(log);
              setAlerts(prev => [{
                id: `auto-${log.id}`,
                title: 'Auto-Message Sent',
                desc: `Welcome WhatsApp sent to ${lead.name}`,
                type: 'success',
                leadId: lead.id
              }, ...prev]);
            }
          }
        }
      }
    };
    const interval = setInterval(runAutomationJob, 30000);
    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
    const savedLeads = localStorage.getItem('et_leads');
    const leads: Lead[] = savedLeads ? JSON.parse(savedLeads) : MOCK_LEADS;
    const now = new Date();
    const newAlerts: any[] = [];

    leads.forEach(lead => {
      const createdAt = new Date(lead.createdAt);
      const lastUpdate = lead.updatedAt ? new Date(lead.updatedAt) : createdAt;
      const hoursSinceInactivity = (now.getTime() - lastUpdate.getTime()) / (1000 * 60 * 60);

      if (lead.stage === LeadStage.NEW && hoursSinceInactivity > 24) {
        newAlerts.push({ id: `alert-new-${lead.id}`, title: 'Cold Lead Alert', desc: `${lead.name} has been in "New" for 24h+.`, type: 'danger', leadId: lead.id });
      }

      const todayStr = now.toISOString().split('T')[0];
      lead.followUps.filter(f => f.status === 'Pending' && f.date <= todayStr).forEach(f => {
        newAlerts.push({ id: `alert-fu-${f.id}`, title: 'Due Follow-up', desc: `${f.note} for ${lead.name}`, type: 'info', leadId: lead.id });
      });
    });

    setAlerts(prev => [...newAlerts, ...prev.filter(a => a.id.startsWith('auto-'))]);
  }, [location.pathname]);

  return (
    <div className="flex h-screen overflow-hidden bg-[#f8fafc]">
      <aside className="w-64 bg-slate-950 flex flex-col p-6 border-r border-slate-900 transition-all duration-300">
        <div className="flex items-center gap-3 mb-4">
          <div className={`${currentUser.color} p-2.5 rounded-xl shadow-xl transition-colors duration-500`}>
            <Mountain className="text-white" size={24} />
          </div>
          <div>
            <h1 className="text-white font-black text-lg tracking-tighter leading-none">ESCAPE</h1>
            <p className="text-blue-500 text-[9px] font-black uppercase tracking-[0.2em]">THEORY KASHMIR</p>
          </div>
        </div>

        <nav className="flex-1 space-y-1 overflow-y-auto custom-scrollbar pr-2">
          {(currentUser.role === UserRole.ADMIN || currentUser.role === UserRole.SALES) && (
            <>
              <SidebarHeader label="Revenue & Sales" />
              <SidebarItem icon={LayoutDashboard} label="Dashboard" path="/" active={location.pathname === '/'} roleColor={currentUser.color} />
              <SidebarItem icon={Trello} label="Sales Pipeline" path="/pipeline" active={location.pathname === '/pipeline'} roleColor={currentUser.color} />
              <SidebarItem icon={Users} label="Lead Manager" path="/leads" active={location.pathname.startsWith('/leads') && location.pathname !== '/leads/new'} roleColor={currentUser.color} />
            </>
          )}

          <SidebarHeader label="Operations" />
          <SidebarItem icon={Map} label="All Itineraries" path="/trips" active={location.pathname === '/trips' || (location.pathname.startsWith('/trips/') && !location.pathname.includes('print'))} roleColor={currentUser.color} />
          {isAllowed('/templates') && <SidebarItem icon={FileText} label="Templates" path="/templates" active={location.pathname.startsWith('/templates')} roleColor={currentUser.color} />}

          {isAllowed('/hotels') && (
            <>
              <SidebarHeader label="Master Database" />
              <SidebarItem icon={HotelIcon} label="Hotels" path="/hotels" active={location.pathname === '/hotels'} roleColor={currentUser.color} />
              <SidebarItem icon={Car} label="Vehicle Fleet" path="/vehicles" active={location.pathname === '/vehicles'} roleColor={currentUser.color} />
              <SidebarItem icon={Compass} label="Activities" path="/activities" active={location.pathname === '/activities'} roleColor={currentUser.color} />
              <SidebarItem icon={Sparkles} label="Add-ons" path="/add-ons" active={location.pathname === '/add-ons'} roleColor={currentUser.color} />
              <SidebarItem icon={ListChecks} label="Master Terms" path="/master-terms" active={location.pathname === '/master-terms'} roleColor={currentUser.color} />
            </>
          )}

          {currentUser.role === UserRole.ADMIN && (
            <>
              <SidebarHeader label="System" />
              <SidebarItem icon={Settings} label="Settings" path="/settings" active={location.pathname === '/settings'} roleColor={currentUser.color} />
            </>
          )}
        </nav>

        <div className="mt-auto border-t border-slate-900 pt-6">
          <button className="flex items-center gap-3 px-4 py-3 text-slate-500 hover:text-red-400 transition-colors w-full group">
            <LogOut size={20} className="group-hover:translate-x-1 transition-transform" />
            <span className="font-bold text-sm">Sign Out</span>
          </button>
        </div>
      </aside>

      <main className="flex-1 flex flex-col overflow-hidden relative">
        <header className="h-20 bg-white border-b border-slate-100 flex items-center justify-between px-10">
          <div className="flex items-center gap-4">
            <h2 className="text-slate-900 font-black text-xl tracking-tight uppercase">
              {location.pathname === '/' ? 'Business Intelligence' : 
               location.pathname.startsWith('/pipeline') ? 'Sales Pipeline' :
               location.pathname.startsWith('/leads') ? 'Client Relationship' :
               location.pathname.startsWith('/trips') ? 'Itinerary Control' :
               location.pathname.startsWith('/profile') ? 'My Workspace' :
               'Operational Control'}
            </h2>
          </div>
          <div className="flex items-center gap-6">
            <button 
              onClick={() => setShowNotifications(!showNotifications)}
              className="relative p-3 bg-slate-50 hover:bg-slate-100 rounded-2xl transition-all group"
            >
              <Bell size={20} className="text-slate-400 group-hover:text-blue-600" />
              {alerts.length > 0 && (
                <span className="absolute top-2 right-2 w-4 h-4 bg-rose-600 border-2 border-white rounded-full flex items-center justify-center text-[8px] text-white font-black">
                  {alerts.length}
                </span>
              )}
            </button>

            <div className="relative" ref={profileRef}>
              <button 
                onClick={() => setShowProfileMenu(!showProfileMenu)}
                className="flex items-center gap-4 p-1 pr-3 hover:bg-slate-50 rounded-2xl transition-all group border border-transparent hover:border-slate-200"
              >
                <div className="w-11 h-11 rounded-xl bg-slate-100 border-2 border-white shadow-sm overflow-hidden transition-transform group-active:scale-90">
                  <img src={currentUser.avatar} alt={currentUser.name} className="w-full h-full object-cover" />
                </div>
                <div className="text-left hidden md:block">
                  <p className="text-xs font-black text-slate-900 leading-none flex items-center gap-1">
                    {currentUser.name}
                    <ChevronDown size={14} className={`text-slate-400 transition-transform ${showProfileMenu ? 'rotate-180' : ''}`} />
                  </p>
                  <p className="text-[9px] text-slate-400 font-bold uppercase tracking-widest mt-1">{currentUser.title}</p>
                </div>
              </button>

              {showProfileMenu && (
                <div className="absolute top-14 right-0 w-64 bg-white rounded-3xl shadow-2xl border border-slate-100 z-[120] overflow-hidden animate-in zoom-in-95 duration-200">
                  <div className="p-5 border-b border-slate-50 bg-slate-50/50">
                    <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3">Switch Work Persona</p>
                    <div className="space-y-2 max-h-60 overflow-y-auto custom-scrollbar">
                      {teamMembers.map(m => (
                        <button 
                          key={m.id}
                          onClick={() => switchPersona(m)}
                          className={`w-full flex items-center gap-3 p-3 rounded-2xl transition-all ${
                            currentUser.id === m.id 
                            ? 'bg-white border border-slate-200 shadow-sm' 
                            : 'hover:bg-white/60'
                          }`}
                        >
                          <div className={`w-8 h-8 rounded-lg overflow-hidden shrink-0 ${currentUser.id === m.id ? 'ring-2 ring-blue-500 ring-offset-2' : ''}`}>
                            <img src={m.avatar} alt={m.name} className="w-full h-full object-cover" />
                          </div>
                          <div className="text-left">
                            <p className={`text-xs font-black ${currentUser.id === m.id ? 'text-blue-600' : 'text-slate-700'}`}>{m.name}</p>
                            <p className="text-[9px] font-bold text-slate-400 uppercase tracking-tighter">{m.role}</p>
                          </div>
                          {currentUser.id === m.id && <ShieldCheck size={14} className="ml-auto text-blue-600" />}
                        </button>
                      ))}
                    </div>
                  </div>
                  <div className="p-3">
                     <button 
                       onClick={() => { navigate('/profile'); setShowProfileMenu(false); }}
                       className="w-full flex items-center gap-3 p-3 text-slate-500 hover:text-slate-900 hover:bg-slate-50 rounded-2xl transition-all"
                     >
                        <UserIcon size={16}/>
                        <span className="text-xs font-bold">Manage Profiles</span>
                     </button>
                     <button className="w-full flex items-center gap-3 p-3 text-rose-500 hover:bg-rose-50 rounded-2xl transition-all">
                        <LogOut size={16}/>
                        <span className="text-xs font-bold">Log Out</span>
                     </button>
                  </div>
                </div>
              )}
            </div>
          </div>
        </header>

        {showNotifications && (
          <div className="absolute top-24 right-10 w-96 bg-white rounded-[40px] shadow-2xl border border-slate-100 z-[110] flex flex-col overflow-hidden animate-in slide-in-from-top-4 duration-300">
             <div className="p-8 border-b border-slate-50 flex items-center justify-between">
                <h3 className="font-black text-slate-900 uppercase tracking-widest text-xs flex items-center gap-2">
                   <Bell size={16} className="text-blue-600" /> Agency Action Center
                </h3>
                <button onClick={() => setShowNotifications(false)} className="text-slate-300 hover:text-slate-900"><X size={20}/></button>
             </div>
             <div className="flex-1 overflow-y-auto p-6 space-y-4 max-h-[60vh]">
                {alerts.length > 0 ? alerts.map(alert => (
                  <Link 
                    key={alert.id}
                    to={`/leads/${alert.leadId}`}
                    onClick={() => setShowNotifications(false)}
                    className="flex items-start gap-4 p-5 bg-slate-50 border border-slate-100 rounded-3xl group hover:bg-white hover:border-blue-200 transition-all shadow-sm"
                  >
                     <div className={`p-2 rounded-xl shrink-0 ${
                       alert.type === 'danger' ? 'bg-rose-100 text-rose-600' :
                       alert.type === 'warning' ? 'bg-amber-100 text-amber-600' :
                       alert.type === 'success' ? 'bg-emerald-100 text-emerald-600' :
                       'bg-blue-100 text-blue-600'
                     }`}>
                        {alert.type === 'success' ? <MessageSquare size={18}/> : <AlertTriangle size={18} />}
                     </div>
                     <div className="space-y-1">
                        <p className="text-[10px] font-black uppercase text-slate-400 tracking-widest">{alert.title}</p>
                        <p className="text-xs font-bold text-slate-700 leading-snug">{alert.desc}</p>
                     </div>
                     <ChevronRight size={16} className="text-slate-200 group-hover:text-blue-600 mt-1" />
                  </Link>
                )) : (
                  <div className="py-20 text-center space-y-4 opacity-30">
                    <Clock size={48} className="mx-auto" />
                    <p className="text-[10px] font-black uppercase tracking-widest">No Alerts Pending</p>
                  </div>
                )}
             </div>
             <div className="p-6 bg-slate-50 border-t border-slate-100">
                <button onClick={() => setAlerts([])} className="w-full py-3 text-[10px] font-black uppercase tracking-widest text-slate-400 hover:text-slate-900">Clear All Alerts</button>
             </div>
          </div>
        )}

        <div className="flex-1 overflow-y-auto p-10 bg-[#f8fafc]">
          {children}
        </div>
      </main>
    </div>
  );
};

