const LeadProfile: React.FC = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const [lead, setLead] = useState<Lead | null>(null);
  const [activeTab, setActiveTab] = useState<'overview' | 'trips' | 'timeline' | 'messaging' | 'followups'>('overview');
  const [newLog, setNewLog] = useState('');

  const [isEditModalOpen, setIsEditModalOpen] = useState(false);
  const [editingLead, setEditingLead] = useState<Lead | null>(null);

  const [isAiScheduling, setIsAiScheduling] = useState(false);
  const [isFUModalOpen, setIsFUModalOpen] = useState(false);
  const [fuFormData, setFuFormData] = useState({
    date: new Date().toISOString().split('T')[0],
    type: 'Call' as 'Call' | 'WhatsApp' | 'Email',
    note: ''
  });

  const [isSending, setIsSending] = useState(false);
  const [messageLogs, setMessageLogs] = useState<MessageLog[]>([]);

  useEffect(() => {
    const savedLeads = localStorage.getItem('et_leads');
    const allLeads = savedLeads ? JSON.parse(savedLeads) : MOCK_LEADS;
    const found = allLeads.find((l: Lead) => l.id === id);
    if (found) {
      if (!found.activities) found.activities = [];
      if (found.whatsappOptIn === undefined) found.whatsappOptIn = true;
      setLead(found);
      setMessageLogs(getMessageLogsForLead(found.id));
    }
  }, [id]);

  const recordActivity = (updatedLead: Lead, type: LeadActivity['type'], description: string, meta?: any) => {
    const activity: LeadActivity = {
      id: `act-${Date.now()}`,
      leadId: updatedLead.id,
      type,
      timestamp: new Date().toISOString(),
      description,
      meta
    };
    updatedLead.activities = [activity, ...(updatedLead.activities || [])];
    updatedLead.updatedAt = new Date().toISOString();
    return updatedLead;
  };

  const updateLeadInStorage = (updatedLead: Lead) => {
    setLead(updatedLead);
    const savedLeads = localStorage.getItem('et_leads');
    const allLeads = savedLeads ? JSON.parse(savedLeads) : [...MOCK_LEADS];
    const index = allLeads.findIndex((l: Lead) => l.id === updatedLead.id);
    if (index > -1) {
      allLeads[index] = updatedLead;
    } else {
      allLeads.push(updatedLead);
    }
    localStorage.setItem('et_leads', JSON.stringify(allLeads));
  };

  const handleManualMessage = async (templateId: string) => {
    if (!lead || isSending) return;
    const template = DEFAULT_TEMPLATES.find(t => t.id === templateId);
    if (!template) return;

    setIsSending(true);
    try {
      const log = await sendSimulatedMessage(lead, template);
      saveMessageLog(log);
      setMessageLogs(prev => [log, ...prev]);

      let updatedLead: Lead = { ...lead };
      updatedLead = recordActivity(updatedLead, 'MessageSent', `Manual ${template.type} sent: ${template.name}`, { msgId: log.id });
      updateLeadInStorage(updatedLead);
    } finally {
      setIsSending(false);
    }
  };

  const handleStageChange = (newStage: LeadStage) => {
    if (!lead) return;
    let updatedLead: Lead = { ...lead, stage: newStage };
    updatedLead = recordActivity(updatedLead, 'StatusChange', `Stage changed from ${lead.stage} to ${newStage}`);
    updateLeadInStorage(updatedLead);
  };

  const addCommunicationLog = (type: CommunicationLog['type'] = 'Note', content: string = newLog) => {
    if (!lead || !content.trim()) return;
    const log: CommunicationLog = {
      id: `c-${Date.now()}`,
      type,
      timestamp: new Date().toISOString(),
      content,
      author: 'Adil Bakshi'
    };
    let updatedLead: Lead = { ...lead, communicationLogs: [log, ...lead.communicationLogs] };
    updatedLead = recordActivity(updatedLead, 'NoteAdded', `Communication logged: ${type}`, { logId: log.id });
    updateLeadInStorage(updatedLead);
    if (type === 'Note') setNewLog('');
  };

  const handleCustomFollowUpSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!lead || !fuFormData.note.trim()) return;

    const newFollowUp: FollowUp = {
      id: `f-${Date.now()}`,
      date: fuFormData.date,
      status: 'Pending',
      type: fuFormData.type,
      note: fuFormData.note
    };

    let updatedLead: Lead = {
      ...lead,
      followUps: [...lead.followUps, newFollowUp]
    };
    updatedLead = recordActivity(updatedLead, 'FollowUpCreated', `Scheduled ${fuFormData.type}: ${fuFormData.note} for ${fuFormData.date}`);
    updateLeadInStorage(updatedLead);

    setIsFUModalOpen(false);
    setFuFormData({
      date: new Date().toISOString().split('T')[0],
      type: 'Call',
      note: ''
    });
  };

  const completeFollowUp = (fuId: string) => {
    if (!lead) return;
    const completedTask = lead.followUps.find(f => f.id === fuId)?.note;
    const updatedFollowUps = lead.followUps.map(fu => 
      fu.id === fuId ? { ...fu, status: 'Completed' as const } : fu
    );
    let updatedLead: Lead = { ...lead, followUps: updatedFollowUps };
    updatedLead = recordActivity(updatedLead, 'FollowUpCompleted', `Task completed: ${completedTask}`);
    updateLeadInStorage(updatedLead);
  };

  const openEditModal = () => {
    if (!lead) return;
    setEditingLead({ ...lead });
    setIsEditModalOpen(true);
  };

  const handleEditSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingLead) return;
    let updatedLead: Lead = { ...editingLead, updatedAt: new Date().toISOString() };
    updatedLead = recordActivity(updatedLead, 'NoteAdded', 'Client profile updated');
    updateLeadInStorage(updatedLead);
    setIsEditModalOpen(false);
    setEditingLead(null);
  };

  if (!lead) return <div className="p-20 text-center font-black text-slate-300 uppercase tracking-widest">LOADING LEAD...</div>;

  const leadTrips = MOCK_TRIPS.filter(t => t.leadId === lead.id);

  return (
    <div className="space-y-8 pb-20">
      <div className="bg-white p-10 rounded-[48px] border border-slate-100 shadow-sm flex flex-col md:flex-row gap-10">
         <div className="flex-1 space-y-6">
            <div className="flex items-center justify-between">
               <div className="flex items-center gap-5">
                  <button onClick={() => navigate('/leads')} className="p-3 bg-slate-50 hover:bg-slate-100 rounded-2xl text-slate-400 transition-all active:scale-95"><ArrowLeft size={20}/></button>
                  <div>
                     <h1 className="text-4xl font-black text-slate-900 tracking-tighter">{lead.name}</h1>
                     <div className="flex items-center gap-4 mt-1">
                        <span className={`text-[10px] font-black uppercase tracking-widest px-3 py-1 rounded-full ${lead.score === LeadScore.HOT ? 'bg-rose-100 text-rose-600' : 'bg-blue-100 text-blue-600'}`}>
                           {lead.score} Priority
                        </span>
                        <div className="flex items-center gap-1.5 px-3 py-1 bg-emerald-50 rounded-full">
                           <Smartphone size={10} className="text-emerald-600" />
                           <span className="text-[9px] font-black uppercase tracking-widest text-emerald-600">WhatsApp {lead.whatsappOptIn ? 'Opted-In' : 'Opted-Out'}</span>
                        </div>
                     </div>
                  </div>
               </div>
               <button onClick={openEditModal} className="p-4 bg-slate-100 text-slate-600 rounded-2xl hover:bg-blue-600 hover:text-white transition-all shadow-sm flex items-center gap-2 group">
                 <Edit3 size={18} />
                 <span className="text-[10px] font-black uppercase tracking-widest hidden group-hover:block animate-in slide-in-from-right-2">Edit Profile</span>
               </button>
            </div>

            <div className="grid grid-cols-2 md:grid-cols-4 gap-6 pt-4">
               <div className="space-y-1">
                  <p className="text-[9px] font-black uppercase text-slate-400 tracking-widest">Phone</p>
                  <p className="font-bold text-slate-900 flex items-center gap-2">{lead.phone}</p>
               </div>
               <div className="space-y-1">
                  <p className="text-[9px] font-black uppercase text-slate-400 tracking-widest">Email</p>
                  <p className="font-bold text-slate-900 flex items-center gap-2 truncate">{lead.email}</p>
               </div>
               <div className="space-y-1">
                  <p className="text-[9px] font-black uppercase text-slate-400 tracking-widest">Travel Month</p>
                  <p className="font-bold text-slate-900 flex items-center gap-2">{lead.travelMonth}</p>
               </div>
               <div className="space-y-1">
                  <p className="text-[9px] font-black uppercase text-slate-400 tracking-widest">Budget</p>
                  <p className="font-bold text-slate-900">₹ {lead.budgetRange}</p>
               </div>
            </div>
         </div>

         <div className="w-full md:w-80 bg-slate-950 p-8 rounded-[40px] text-white space-y-6">
            <p className="text-[10px] font-black uppercase tracking-widest text-slate-500">Pipeline Stage</p>
            <div className="flex flex-col gap-4">
               <select value={lead.stage} onChange={(e) => handleStageChange(e.target.value as LeadStage)} className="w-full bg-slate-900 border border-slate-800 p-4 rounded-2xl font-black text-xs uppercase tracking-widest outline-none">
                  {Object.values(LeadStage).map(s => <option key={s} value={s}>{s}</option>)}
               </select>
               <button onClick={() => { setActiveTab('followups'); setIsFUModalOpen(true); }} className="w-full py-4 bg-blue-600 text-white rounded-2xl font-black uppercase tracking-widest text-[10px] shadow-xl hover:bg-blue-700 transition-all">Quick Log Task</button>
            </div>
         </div>
      </div>

      <div className="grid grid-cols-12 gap-8">
         <div className="col-span-12 lg:col-span-8 space-y-8">
            <div className="flex gap-4 p-1.5 bg-white border border-slate-100 rounded-3xl w-fit">
               {['overview', 'trips', 'timeline', 'messaging', 'followups'].map((tab) => (
                  <button key={tab} onClick={() => setActiveTab(tab as any)} className={`px-6 py-3 rounded-2xl font-black text-[10px] uppercase tracking-widest transition-all ${activeTab === tab ? 'bg-slate-900 text-white shadow-xl' : 'text-slate-400 hover:text-slate-900'}`}>{tab}</button>
               ))}
            </div>

            {activeTab === 'overview' && (
              <div className="space-y-8 animate-in fade-in duration-300">
                 <div className="bg-white p-8 rounded-[40px] border border-slate-100 shadow-sm space-y-6">
                    <textarea rows={4} placeholder="Add call summary..." className="w-full p-6 bg-slate-50 border border-slate-100 rounded-[32px] outline-none font-bold text-slate-900 focus:bg-white transition-all shadow-inner resize-none" value={newLog} onChange={(e) => setNewLog(e.target.value)} />
                    <button onClick={() => addCommunicationLog('Note')} className="bg-slate-900 text-white px-8 py-3 rounded-2xl font-bold">Log Interaction</button>
                 </div>
                 <div className="space-y-6">
                    {lead.communicationLogs.map((log) => (
                       <div key={log.id} className="bg-white p-8 rounded-[40px] border border-slate-100 shadow-sm flex gap-6">
                          <div className="p-4 bg-slate-50 rounded-2xl"><MessageSquare size={20}/></div>
                          <div className="flex-1 space-y-2">
                             <div className="flex items-center justify-between"><span className="text-[10px] font-black uppercase text-slate-400">{log.type} by {log.author}</span><span className="text-[10px] font-bold text-slate-300">{new Date(log.timestamp).toLocaleDateString()}</span></div>
                             <p className="text-slate-800 font-bold">{log.content}</p>
                          </div>
                       </div>
                    ))}
                 </div>
              </div>
            )}

            {activeTab === 'followups' && (
              <div className="space-y-6 animate-in fade-in duration-300">
                <div className="flex justify-between items-center"><h3 className="text-xs font-black uppercase tracking-widest text-slate-400 ml-4">Tasks</h3><button onClick={() => setIsFUModalOpen(true)} className="bg-blue-600 text-white px-4 py-2 rounded-xl text-[10px] font-black uppercase">Add Task</button></div>
                {lead.followUps.map(fu => (
                  <div key={fu.id} className={`p-6 rounded-[32px] border ${fu.status === 'Completed' ? 'bg-slate-50 opacity-60' : 'bg-white shadow-sm'}`}>
                    <div className="flex justify-between items-start">
                      <div><p className="text-[10px] font-black text-slate-400 uppercase">{fu.date}</p><p className="font-bold text-slate-800">{fu.note}</p></div>
                      {fu.status === 'Pending' && <button onClick={() => completeFollowUp(fu.id)} className="text-slate-300 hover:text-emerald-500"><CheckCircle2 size={24}/></button>}
                    </div>
                  </div>
                ))}
              </div>
            )}

            {activeTab === 'messaging' && (
              <div className="space-y-8 animate-in fade-in duration-300">
                <div className="bg-white p-8 rounded-[40px] border border-slate-100 shadow-sm grid grid-cols-1 md:grid-cols-3 gap-4">
                  {DEFAULT_TEMPLATES.map(tmp => (
                    <button key={tmp.id} onClick={() => handleManualMessage(tmp.id)} disabled={isSending} className="p-6 border rounded-[32px] text-left hover:bg-slate-50">
                      <div className="p-3 rounded-2xl bg-blue-50 w-fit mb-3"><Smartphone size={18}/></div>
                      <p className="font-black text-slate-900 text-sm">{tmp.name}</p>
                    </button>
                  ))}
                </div>
              </div>
            )}

            {activeTab === 'trips' && (
               <div className="space-y-6 animate-in fade-in duration-300">
                  {leadTrips.map(trip => (
                     <div key={trip.id} onClick={() => navigate(`/trips/${trip.id}`)} className="bg-white p-8 rounded-[40px] border border-slate-100 shadow-sm flex items-center justify-between cursor-pointer hover:border-blue-200 transition-all">
                        <div className="flex items-center gap-6">
                           <div className="bg-blue-50 p-4 rounded-2xl text-blue-600"><Map size={24}/></div>
                           <div><h4 className="text-lg font-black text-slate-900">{trip.tripName}</h4><p className="text-[10px] font-bold text-slate-400 uppercase">{trip.tripType} • {trip.status}</p></div>
                        </div>
                        <ChevronRight size={20} className="text-slate-200" />
                     </div>
                  ))}
               </div>
            )}

            {activeTab === 'timeline' && (
              <div className="space-y-12 py-10 animate-in fade-in duration-300">
                <div className="relative border-l-2 border-slate-100 ml-10 space-y-10 pb-10">
                  {(lead.activities || []).map((act) => (
                    <div key={act.id} className="relative pl-12 group">
                      <div className="absolute -left-[11px] top-0 w-5 h-5 rounded-full border-4 border-white bg-blue-600 shadow-sm" />
                      <div className="bg-white p-6 rounded-[32px] border shadow-sm">
                        <span className="text-[10px] font-bold text-slate-300">{new Date(act.timestamp).toLocaleString()}</span>
                        <p className="text-slate-800 font-bold">{act.description}</p>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            )}
         </div>

         <div className="col-span-12 lg:col-span-4 space-y-8">
            <div className="bg-white p-8 rounded-[40px] border border-slate-100 shadow-sm space-y-8">
               <h3 className="text-xs font-black uppercase tracking-widest text-slate-900 flex items-center gap-2"><ShieldCheck size={16} className="text-blue-600" /> Compliance</h3>
               <div className="flex items-center justify-between p-4 bg-slate-50 rounded-2xl">
                  <span className="text-xs font-bold text-slate-700">WhatsApp Opt-in</span>
                  <button onClick={() => updateLeadInStorage({ ...lead, whatsappOptIn: !lead.whatsappOptIn })} className={`w-12 h-6 rounded-full transition-all relative ${lead.whatsappOptIn ? 'bg-emerald-500' : 'bg-slate-300'}`}>
                     <div className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-all ${lead.whatsappOptIn ? 'left-7' : 'left-1'}`} />
                  </button>
               </div>
            </div>
         </div>
      </div>

      {isFUModalOpen && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[110] flex items-center justify-center p-4">
          <div className="bg-white rounded-[48px] shadow-2xl w-full max-w-lg overflow-hidden animate-in zoom-in-95 duration-200">
             <div className="bg-slate-950 p-8 text-white flex justify-between items-center">
                <h2 className="text-xl font-black uppercase">Schedule Task</h2>
                <button onClick={() => setIsFUModalOpen(false)} className="text-slate-500 hover:text-white transition-colors"><X size={24}/></button>
             </div>
             <form onSubmit={handleCustomFollowUpSubmit} className="p-10 space-y-8">
                <div className="grid grid-cols-2 gap-6">
                   <div className="space-y-2"><label className="text-[10px] font-black uppercase text-slate-400">Date</label><input required type="date" className="w-full p-3 bg-slate-50 border rounded-xl font-bold text-xs" value={fuFormData.date} onChange={e => setFuFormData({...fuFormData, date: e.target.value})} /></div>
                   <div className="space-y-2"><label className="text-[10px] font-black uppercase text-slate-400">Type</label><select className="w-full p-3 bg-slate-50 border rounded-xl font-bold text-xs" value={fuFormData.type} onChange={e => setFuFormData({...fuFormData, type: e.target.value as any})}><option>Call</option><option>WhatsApp</option><option>Email</option></select></div>
                </div>
                <div className="space-y-2"><label className="text-[10px] font-black uppercase text-slate-400">Task</label><input required type="text" className="w-full p-3 bg-slate-50 border rounded-xl font-bold text-sm" value={fuFormData.note} onChange={e => setFuFormData({...fuFormData, note: e.target.value})} /></div>
                <button type="submit" className="w-full py-4 bg-blue-600 text-white rounded-2xl font-black uppercase">Save Task</button>
             </form>
          </div>
        </div>
      )}

      {isEditModalOpen && editingLead && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[110] flex items-center justify-center p-4">
          <div className="bg-white rounded-[48px] shadow-2xl w-full max-w-2xl overflow-hidden animate-in zoom-in-95 duration-200">
             <div className="bg-slate-950 p-8 text-white flex justify-between items-center">
                <h2 className="text-xl font-black uppercase">Edit Client Profile</h2>
                <button onClick={() => setIsEditModalOpen(false)} className="text-slate-500 hover:text-white transition-colors"><X size={24}/></button>
             </div>
             <form onSubmit={handleEditSubmit} className="p-10 space-y-8">
                <div className="grid grid-cols-2 gap-6">
                   <div className="space-y-1"><label className="text-[10px] font-black uppercase text-slate-400">Full Name</label><input required type="text" className="w-full p-4 bg-slate-50 border rounded-2xl font-bold" value={editingLead.name} onChange={e => setEditingLead({...editingLead, name: e.target.value})} /></div>
                   <div className="space-y-1"><label className="text-[10px] font-black uppercase text-slate-400">Phone</label><input required type="text" className="w-full p-4 bg-slate-50 border rounded-2xl font-bold" value={editingLead.phone} onChange={e => setEditingLead({...editingLead, phone: e.target.value})} /></div>
                </div>
                <div className="grid grid-cols-2 gap-6">
                   <div className="space-y-1"><label className="text-[10px] font-black uppercase text-slate-400">Email</label><input type="email" className="w-full p-4 bg-slate-50 border border-rounded-2xl font-bold" value={editingLead.email} onChange={e => setEditingLead({...editingLead, email: e.target.value})} /></div>
                   <div className="space-y-1"><label className="text-[10px] font-black uppercase text-slate-400">Score</label><select className="w-full p-4 bg-slate-50 border rounded-2xl font-bold" value={editingLead.score} onChange={e => setEditingLead({...editingLead, score: e.target.value as LeadScore})}>{Object.values(LeadScore).map(s => <option key={s} value={s}>{s}</option>)}</select></div>
                </div>
                <button type="submit" className="w-full py-4 bg-blue-600 text-white font-black uppercase shadow-xl hover:bg-blue-700 transition-all flex items-center justify-center gap-2"><Check size={18}/> Commit Updates</button>
             </form>
          </div>
        </div>
      )}
    </div>
  );
};

