            </div>

            <div className="p-6 flex-1 space-y-4">
              <div className="flex items-center gap-4">
                <div className="flex items-center gap-1.5 text-slate-500 text-sm font-medium">
                  <Clock size={16} />
                  {template.duration}
                </div>
                <div className="flex items-center gap-1.5 text-slate-500 text-sm font-medium">
