                    <th className="px-6 py-5 text-slate-400">Destination</th>
                    <th className="px-6 py-5 text-blue-900"><div className="flex items-center gap-2"><Award size={14}/> Signature</div></th>
                    <th className="px-6 py-5 text-blue-900 bg-blue-50/50"><div className="flex items-center gap-2"><Trophy size={14}/> Elite Tier</div></th>
                    <th className="px-6 py-5 text-blue-900"><div className="flex items-center gap-2"><Crown size={14}/> Prime Tier</div></th>
