  PlusCircle,
  Wallet,
  IndianRupee,
  Star,
  ListPlus,
  X,
  ChevronRight,
  ShieldCheck,
  XCircle,
  Trophy,
  Award,
  Crown,
  Compass,
  ArrowRightLeft,
  Bed,
  Moon,
  Clock,
  RefreshCcw,
  Percent,
  Calculator,
  Info,
  PlaneTakeoff,
  Copy,
  Split,
