                  <tr className="divide-x-2 divide-slate-900 font-black text-2xl bg-yellow-400">
                    <td className="px-6 py-6 bg-white border-white"></td>
                    <td className="px-6 py-6 text-center">₹{(trip.tierPrices?.signature || 0).toLocaleString()}*</td>
                    <td className="px-6 py-6 text-center border-x-4 border-blue-600">₹{(trip.tierPrices?.elite || 0).toLocaleString()}*</td>
                    <td className="px-6 py-6 text-center">₹{(trip.tierPrices?.prime || 0).toLocaleString()}*</td>
                  </tr>
                </tbody>
              </table>
            </div>
            <p className="text-[10px] text-slate-400 font-black italic uppercase tracking-[0.2em] text-center">
              *Full inclusive pricing for {(trip.pax || 2)} persons. Subject to availability at booking.
            </p>
          </div>
        </div>
      </div>
    </div>
  );
};

