export const ClientItinerary: React.FC = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const [trip, setTrip] = useState<Trip | null>(null);
  const [isGenerating, setIsGenerating] = useState(false);
  const printableRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const savedTrips = localStorage.getItem('et_trips');
    let foundTrip: Trip | undefined;
    if (savedTrips) {
      const parsed = JSON.parse(savedTrips);
      foundTrip = parsed.find((t: Trip) => t.id === id);
    }
    if (!foundTrip) {
      foundTrip = MOCK_TRIPS.find(t => t.id === id);
    }
    if (foundTrip) {
      setTrip(foundTrip);
    }
  }, [id]);

  const masterHotels = useMemo(() => {
    const saved = localStorage.getItem('et_hotels');
    const custom = saved ? JSON.parse(saved) : [];
    return [...HOTELS, ...custom];
  }, []);

  const tieredAccommodationRows = useMemo(() => {
    if (!trip || !trip.hotelTiers) return [];
    return trip.hotelTiers.map(tier => {
      const sigHotel = masterHotels.find(h => h.id === tier.signatureHotelId);
      const eltHotel = masterHotels.find(h => h.id === tier.eliteHotelId);
      const prmHotel = masterHotels.find(h => h.id === tier.primeHotelId);

      return {
        location: tier.location,
        signature: sigHotel?.name || 'Standard Deluxe',
        elite: eltHotel?.name || 'Premium Deluxe',
        prime: prmHotel?.name || 'Super Luxury'
      };
    });
  }, [trip, masterHotels]);

  const handleDownloadPdf = async () => {
    if (!trip || !printableRef.current || isGenerating) return;
    setIsGenerating(true);
    try {
      const h2p = (window as any).html2pdf;
      const element = printableRef.current;
      const opt = {
        margin: [0, 0, 0, 0],
        filename: `${trip.client.name}_EscapeTheory_Kashmir.pdf`,
        image: { type: 'jpeg', quality: 0.98 },
        html2canvas: { scale: 2, useCORS: true },
        jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' },
        pagebreak: { mode: ['avoid-all', 'css', 'legacy'] }
      };
      await h2p().from(element).set(opt).save();
    } catch (err) {
      console.error(err);
      alert("PDF Error. Try browser print.");
    } finally {
      setIsGenerating(false);
    }
  };

  if (!trip) return <div className="p-20 text-center font-black text-slate-400">LOADING PROPOSAL...</div>;

  const durationNights = Math.max(0, trip.itinerary.length - 1);
  const durationDays = trip.itinerary.length;

  return (
    <div className="bg-slate-50 min-h-screen text-slate-900 print:bg-white overflow-x-hidden pb-20">
      <div className="no-print sticky top-0 bg-white/95 backdrop-blur-md border-b border-slate-200 z-[100] p-4 flex justify-between items-center px-10 shadow-lg">
        <button onClick={() => navigate(`/trips/${id}`)} className="text-slate-500 font-bold flex items-center gap-2 hover:text-slate-900 transition-colors">
          <ArrowLeft size={18} /> BACK TO BUILDER
        </button>
        <div className="flex gap-4">
          <button onClick={() => window.print()} className="bg-white border border-slate-200 px-6 py-2.5 rounded-xl font-bold flex items-center gap-2 shadow-sm hover:bg-slate-50">
            <Printer size={18} /> PRINT
          </button>
          <button onClick={handleDownloadPdf} disabled={isGenerating} className="bg-blue-600 text-white px-8 py-2.5 rounded-xl font-bold flex items-center gap-2 shadow-xl hover:bg-blue-700 transition-all">
            {isGenerating ? <Loader2 size={18} className="animate-spin" /> : <Download size={18} />}
            {isGenerating ? 'GENERATING...' : 'DOWNLOAD PDF'}
          </button>
        </div>
      </div>

      <div className="max-w-[210mm] mx-auto bg-white shadow-2xl my-10 print:my-0 print:shadow-none" ref={printableRef}>
        <div className="p-16 space-y-12">
          <div className="w-full h-[120mm] rounded-[40px] overflow-hidden relative shadow-2xl">
            <img src="https://images.unsplash.com/photo-1590490360182-c33d57733427?auto=format&fit=crop&q=80&w=1600" className="w-full h-full object-cover" alt="Kashmir" />
            <div className="absolute inset-0 bg-gradient-to-t from-black/70 to-transparent" />
            <div className="absolute bottom-10 left-10 text-white">
              <h1 className="text-6xl font-black tracking-tighter uppercase leading-none">{BRAND_CONFIG.name}</h1>
              <p className="text-blue-300 font-bold uppercase tracking-[0.4em] mt-4">{BRAND_CONFIG.tagline}</p>
            </div>
          </div>

          <div className="space-y-4">
            <h2 className="text-4xl font-serif text-slate-800 italic leading-tight">Dear {trip.client.name},</h2>
            <p className="text-xl font-medium text-slate-600">Greetings from <span className="text-blue-900 font-black">Escape Theory Kashmir</span>. We are delighted to present your curated travel plan.</p>
          </div>

