import React, { useState, useEffect, useMemo } from 'react';
// @ts-ignore
import { useNavigate, Link } from 'react-router-dom';
import { 
  Search, 
  Filter, 
  Plus, 
  ChevronRight, 
  MessageSquare, 
  Phone, 
  Mail, 
  MoreVertical,
  Flame,
  TrendingUp,
  Snowflake,
  Clock,
  Calendar,
  Zap,
  CheckCircle2,
  X,
  Trash2,
  UserPlus,
  ArrowRightLeft,
  Check,
  Edit2,
  Sparkles,
  Loader2,
  Globe,
  User,
  Activity as ActivityIcon,
  Smartphone,
  Send,
  ShieldCheck
} from 'lucide-react';
import { Lead, LeadStage, LeadScore, TripType, FollowUp, LeadActivity, TeamMember } from '../types';
import { MOCK_LEADS, DEFAULT_PERSONAS } from '../constants';
import { suggestFollowUp } from '../services/geminiService';
import { DEFAULT_TEMPLATES, sendSimulatedMessage, saveMessageLog } from '../services/messagingService';

const LeadList: React.FC = () => {
  const navigate = useNavigate();
  const [leads, setLeads] = useState<Lead[]>([]);
  const [teamMembers, setTeamMembers] = useState<TeamMember[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [stageFilter, setStageFilter] = useState('All');
  const [scoreFilter, setScoreFilter] = useState('All');
  const [selectedLeads, setSelectedLeads] = useState<string[]>([]);

  // Edit State
  const [editingLead, setEditingLead] = useState<Lead | null>(null);
  const [isEditModalOpen, setIsEditModalOpen] = useState(false);

  // AI Suggestion State
  const [suggestingForId, setSuggestingForId] = useState<string | null>(null);
  const [currentSuggestion, setCurrentSuggestion] = useState<{ task: string, daysFromNow: number } | null>(null);
  const [isSuggesting, setIsSuggesting] = useState(false);

  // Bulk Messaging State
  const [isBulkMessageModalOpen, setIsBulkMessageModalOpen] = useState(false);
  const [selectedTemplateId, setSelectedTemplateId] = useState(DEFAULT_TEMPLATES[0].id);
  const [isBulkSending, setIsBulkSending] = useState(false);

  useEffect(() => {
    const savedLeads = localStorage.getItem('et_leads');
    setLeads(savedLeads ? JSON.parse(savedLeads) : MOCK_LEADS);

    const savedMembers = localStorage.getItem('et_team_members');
    setTeamMembers(savedMembers ? JSON.parse(savedMembers) : DEFAULT_PERSONAS);
  }, []);

  const saveLeads = (updatedLeads: Lead[]) => {
    setLeads(updatedLeads);
    localStorage.setItem('et_leads', JSON.stringify(updatedLeads));
  };

  const filteredLeads = useMemo(() => {
    return leads.filter(l => {
      const matchesSearch = l.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
                           l.phone.includes(searchTerm) ||
                           l.email.toLowerCase().includes(searchTerm.toLowerCase());
      const matchesStage = stageFilter === 'All' || l.stage === stageFilter;
      const matchesScore = scoreFilter === 'All' || l.score === scoreFilter;
      return matchesSearch && matchesStage && matchesScore;
    });
  }, [leads, searchTerm, stageFilter, scoreFilter]);

  const toggleSelectAll = () => {
    if (selectedLeads.length === filteredLeads.length) {
      setSelectedLeads([]);
    } else {
      setSelectedLeads(filteredLeads.map(l => l.id));
    }
  };

  const toggleSelectLead = (id: string) => {
    setSelectedLeads(prev => prev.includes(id) ? prev.filter(i => i !== id) : [...prev, id]);
  };

  const handleWhatsApp = (phone: string) => {
    const cleanPhone = phone.replace(/\D/g, '');
    window.open(`https://wa.me/${cleanPhone}`, '_blank');
  };

  const handleCall = (phone: string) => {
    window.location.href = `tel:${phone}`;
  };

  const updateLeadField = (id: string, field: keyof Lead, value: any) => {
    const updated = leads.map(l => l.id === id ? { ...l, [field]: value, updatedAt: new Date().toISOString() } : l);
    saveLeads(updated);
  };

  const handleBulkStatusUpdate = (newStage: LeadStage) => {
    const updated = leads.map(l => selectedLeads.includes(l.id) ? { ...l, stage: newStage, updatedAt: new Date().toISOString() } : l);
    saveLeads(updated);
    setSelectedLeads([]);
  };

  const handleBulkDelete = () => {
    if (window.confirm(`Are you sure you want to delete ${selectedLeads.length} leads?`)) {
      const updated = leads.filter(l => !selectedLeads.includes(l.id));
      saveLeads(updated);
      setSelectedLeads([]);
    }
  };

  const handleBulkWhatsAppSend = async () => {
    setIsBulkSending(true);
    const template = DEFAULT_TEMPLATES.find(t => t.id === selectedTemplateId);
    if (!template) return;

    const selectedLeadsData = leads.filter(l => selectedLeads.includes(l.id));

    // Process messages in parallel (simulated)
    const promises = selectedLeadsData.map(async (lead) => {
      if (!lead.whatsappOptIn && template.type === 'WhatsApp') return null;
      const log = await sendSimulatedMessage(lead, template);
      saveMessageLog(log);

      // Update individual lead activities
      const activity: LeadActivity = {
        id: `act-${Date.now()}-${lead.id}`,
        leadId: lead.id,
        type: 'MessageSent',
        timestamp: new Date().toISOString(),
        description: `Bulk ${template.type} sent: ${template.name}`
      };

      return { leadId: lead.id, activity };
    });

    const results = await Promise.all(promises);

    // Update master leads state with new activities
    const updatedLeads = leads.map(l => {
      const result = results.find(r => r?.leadId === l.id);
      if (result) {
        return {
          ...l,
          activities: [result.activity, ...(l.activities || [])],
          updatedAt: new Date().toISOString()
        };
      }
      return l;
    });

    saveLeads(updatedLeads);
    setIsBulkSending(false);
    setIsBulkMessageModalOpen(false);
    setSelectedLeads([]);
    alert(`Bulk transmission complete for ${selectedLeads.length} leads.`);
  };

  // Edit Logic
  const openEditModal = (lead: Lead) => {
    setEditingLead({ ...lead });
    setIsEditModalOpen(true);
  };

  const handleEditSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingLead) return;
    const updated = leads.map(l => l.id === editingLead.id ? { ...editingLead, updatedAt: new Date().toISOString() } : l);
    saveLeads(updated);
    setIsEditModalOpen(false);
    setEditingLead(null);
  };

  // AI Suggestion Logic
  const handleGetSuggestion = async (lead: Lead) => {
    if (isSuggesting) return;
    setSuggestingForId(lead.id);
    setIsSuggesting(true);
    setCurrentSuggestion(null);

    try {
      // Fixed: Passing correct string parameters to suggestFollowUp instead of lead object
      const suggestion = await suggestFollowUp(lead.name, lead.stage, lead.notes, lead.interest);
      setCurrentSuggestion(suggestion);
    } catch (error) {
      console.error(error);
    } finally {
      setIsSuggesting(false);
    }
  };

  const applySuggestion = (leadId: string) => {
    if (!currentSuggestion) return;
    const date = new Date();
    date.setDate(date.getDate() + currentSuggestion.daysFromNow);

    const newFollowUp: FollowUp = {
      id: `f-ai-${Date.now()}`,
      date: date.toISOString().split('T')[0],
      status: 'Pending',
      type: 'Call',
      note: currentSuggestion.task
    };

    const updated = leads.map(l => l.id === leadId ? { 
      ...l, 
      followUps: [...l.followUps, newFollowUp],
      activities: [{
        id: `act-ai-${Date.now()}`,
        leadId: l.id,
        type: 'FollowUpCreated',
        timestamp: new Date().toISOString(),
        description: `AI Suggested Task: ${currentSuggestion.task}`
      } as LeadActivity, ...(l.activities || [])],
      updatedAt: new Date().toISOString()
    } : l);

    saveLeads(updated);
    setSuggestingForId(null);
    setCurrentSuggestion(null);
    alert("AI Task scheduled successfully!");
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-black text-slate-900 tracking-tight">Lead Hub</h1>
          <p className="text-slate-500 text-sm">Manage client relationships and sales activities.</p>
        </div>
        <button 
          onClick={() => navigate('/leads/new')}
          className="bg-blue-600 text-white px-6 py-3 rounded-2xl font-black uppercase tracking-widest text-[11px] flex items-center gap-2 hover:bg-blue-700 shadow-xl shadow-blue-100 transition-all active:scale-95"
        >
          <Plus size={18} /> New Entry
        </button>
      </div>

      <div className="bg-white p-6 rounded-[32px] border border-slate-200 shadow-sm space-y-4">
        <div className="flex flex-col md:flex-row gap-4">
          <div className="flex-1 relative">
            <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
            <input 
              type="text" 
              placeholder="Search by name, phone or email..." 
              className="w-full pl-12 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl outline-none focus:ring-4 focus:ring-blue-50/50 transition-all text-sm"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
          <div className="flex gap-3">
             <select 
               className="px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-xs font-black uppercase tracking-widest outline-none"
               value={stageFilter}
               onChange={(e) => setStageFilter(e.target.value)}
             >
                <option value="All">All Stages</option>
                {Object.values(LeadStage).map(s => <option key={s} value={s}>{s}</option>)}
             </select>
             <select 
               className="px-4 py-3 bg-slate-50 border border-slate-200 rounded-2xl text-xs font-black uppercase tracking-widest outline-none"
               value={scoreFilter}
               onChange={(e) => setScoreFilter(e.target.value)}
             >
                <option value="All">All Scores</option>
                {Object.values(LeadScore).map(s => <option key={s} value={s}>{s}</option>)}
             </select>
          </div>
        </div>

        {selectedLeads.length > 0 && (
          <div className="flex items-center justify-between p-4 bg-blue-50 border border-blue-100 rounded-2xl animate-in slide-in-from-top-2">
            <span className="text-xs font-black text-blue-600 uppercase tracking-widest">{selectedLeads.length} Selected</span>
            <div className="flex items-center gap-3">
               <button onClick={() => setIsBulkMessageModalOpen(true)} className="px-4 py-2 bg-white text-blue-600 border border-blue-200 rounded-xl text-[10px] font-black uppercase flex items-center gap-2"><Send size={14}/> Bulk Message</button>
               <button onClick={handleBulkDelete} className="px-4 py-2 bg-white text-rose-600 border border-rose-200 rounded-xl text-[10px] font-black uppercase flex items-center gap-2"><Trash2 size={14}/> Bulk Delete</button>
               <button onClick={() => setSelectedLeads([])} className="text-slate-400 hover:text-slate-600"><X size={18}/></button>
            </div>
          </div>
        )}
      </div>

      <div className="bg-white rounded-[32px] border border-slate-200 shadow-sm overflow-hidden overflow-x-auto">
        <table className="w-full text-left">
           <thead className="bg-slate-50 border-b border-slate-100">
              <tr>
                 <th className="p-6 w-10">
                   <input type="checkbox" checked={selectedLeads.length === filteredLeads.length && filteredLeads.length > 0} onChange={toggleSelectAll} className="rounded border-slate-300 text-blue-600 focus:ring-blue-500" />
                 </th>
                 <th className="p-6 text-[10px] font-black uppercase text-slate-400 tracking-widest">Client</th>
                 <th className="p-6 text-[10px] font-black uppercase text-slate-400 tracking-widest">Stage</th>
                 <th className="p-6 text-[10px] font-black uppercase text-slate-400 tracking-widest">Details</th>
                 <th className="p-6 text-[10px] font-black uppercase text-slate-400 tracking-widest text-right">Actions</th>
              </tr>
           </thead>
           <tbody className="divide-y divide-slate-100">
              {filteredLeads.map(lead => (
                <tr key={lead.id} className="hover:bg-slate-50/50 transition-colors group">
                   <td className="p-6">
                      <input type="checkbox" checked={selectedLeads.includes(lead.id)} onChange={() => toggleSelectLead(lead.id)} className="rounded border-slate-300 text-blue-600 focus:ring-blue-500" />
                   </td>
                   <td className="p-6">
                      <div className="flex items-center gap-4">
                         <div className="p-3 bg-blue-50 rounded-2xl text-blue-600">
                            <User size={20}/>
                         </div>
                         <div>
                            <Link to={`/leads/${lead.id}`} className="font-black text-slate-900 hover:text-blue-600 transition-colors block">{lead.name}</Link>
                            <p className="text-[10px] font-bold text-slate-400 uppercase">{lead.phone}</p>
                         </div>
                      </div>
                   </td>
                   <td className="p-6">
                      <span className={`px-3 py-1 rounded-full text-[9px] font-black uppercase tracking-widest ${
                        lead.stage === LeadStage.BOOKED ? 'bg-emerald-100 text-emerald-700' :
                        lead.stage === LeadStage.NEW ? 'bg-blue-100 text-blue-700' : 'bg-slate-100 text-slate-600'
                      }`}>{lead.stage}</span>
                   </td>
                   <td className="p-6">
                      <div className="flex items-center gap-4 text-slate-500">
                         <div className="flex items-center gap-1.5"><Calendar size={14}/> <span className="text-[10px] font-black uppercase tracking-tighter">{lead.travelMonth}</span></div>
                         <div className="flex items-center gap-1.5"><Users size={14}/> <span className="text-[10px] font-black uppercase tracking-tighter">{lead.pax} PAX</span></div>
                      </div>
                   </td>
                   <td className="p-6 text-right">
                      <div className="flex items-center justify-end gap-2">
                         <button onClick={() => handleGetSuggestion(lead)} className="p-2 text-blue-600 hover:bg-blue-50 rounded-xl transition-all" title="AI Sales Suggestion"><Sparkles size={16}/></button>
                         <button onClick={() => openEditModal(lead)} className="p-2 text-slate-400 hover:text-blue-600 rounded-xl transition-all"><Edit2 size={16}/></button>
                         <button onClick={() => handleWhatsApp(lead.phone)} className="p-2 text-slate-400 hover:text-emerald-500 rounded-xl transition-all"><Smartphone size={16}/></button>
                      </div>
                   </td>
                </tr>
              ))}
           </tbody>
        </table>
      </div>

      {/* AI Suggestion Modal */}
      {suggestingForId && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[110] flex items-center justify-center p-4">
          <div className="bg-white rounded-[40px] shadow-2xl w-full max-w-lg overflow-hidden animate-in zoom-in-95">
             <div className="bg-blue-600 p-8 text-white flex justify-between items-center">
                <div className="flex items-center gap-3"><Sparkles size={24}/><h3 className="font-black uppercase tracking-widest text-sm">AI Sales Pilot</h3></div>
                <button onClick={() => setSuggestingForId(null)}><X size={24}/></button>
             </div>
             <div className="p-10 space-y-6">
                {isSuggesting ? (
                  <div className="py-20 flex flex-col items-center gap-4">
                     <Loader2 size={48} className="text-blue-600 animate-spin" />
                     <p className="text-xs font-black uppercase text-slate-400 tracking-widest">Analyzing lead history...</p>
                  </div>
                ) : currentSuggestion ? (
                  <div className="space-y-8 animate-in fade-in slide-in-from-bottom-4">
                     <div className="bg-blue-50 p-6 rounded-3xl border border-blue-100">
                        <p className="text-[10px] font-black uppercase text-blue-600 tracking-widest mb-2">Recommended Strategy</p>
                        <p className="text-lg font-black text-slate-900 leading-tight">{currentSuggestion.task}</p>
                     </div>
                     <div className="flex items-center justify-between">
                        <div>
                           <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Target Date</p>
                           <p className="font-black text-slate-900">In {currentSuggestion.daysFromNow} days</p>
                        </div>
                        <button onClick={() => applySuggestion(suggestingForId)} className="bg-blue-600 text-white px-8 py-3 rounded-2xl font-black uppercase text-[10px] tracking-widest shadow-xl shadow-blue-100">Apply & Schedule</button>
                     </div>
                  </div>
                ) : <p className="text-center text-slate-400 font-bold">Failed to get suggestion.</p>}
             </div>
          </div>
        </div>
      )}

      {/* Edit Modal */}
      {isEditModalOpen && editingLead && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[110] flex items-center justify-center p-4">
          <div className="bg-white rounded-[48px] shadow-2xl w-full max-w-2xl overflow-hidden animate-in zoom-in-95 duration-200">
             <div className="bg-slate-950 p-8 text-white flex justify-between items-center">
                <h2 className="text-xl font-black uppercase">Quick Edit</h2>
                <button onClick={() => setIsEditModalOpen(false)}><X size={24}/></button>
             </div>
             <form onSubmit={handleEditSubmit} className="p-10 space-y-8">
                <div className="grid grid-cols-2 gap-6">
                   <div className="space-y-1"><label className="text-[10px] font-black uppercase text-slate-400">Name</label><input required type="text" className="w-full p-4 bg-slate-50 border rounded-2xl font-bold" value={editingLead.name} onChange={e => setEditingLead({...editingLead, name: e.target.value})} /></div>
                   <div className="space-y-1"><label className="text-[10px] font-black uppercase text-slate-400">Phone</label><input required type="text" className="w-full p-4 bg-slate-50 border rounded-2xl font-bold" value={editingLead.phone} onChange={e => setEditingLead({...editingLead, phone: e.target.value})} /></div>
                </div>
                <div className="grid grid-cols-2 gap-6">
                   <div className="space-y-1"><label className="text-[10px] font-black uppercase text-slate-400">Email</label><input required type="email" className="w-full p-4 bg-slate-50 border rounded-2xl font-bold" value={editingLead.email} onChange={e => setEditingLead({...editingLead, email: e.target.value})} /></div>
                   <div className="space-y-1"><label className="text-[10px] font-black uppercase text-slate-400">Score</label><select className="w-full p-4 bg-slate-50 border rounded-2xl font-bold" value={editingLead.score} onChange={e => setEditingLead({...editingLead, score: e.target.value as LeadScore})}>{Object.values(LeadScore).map(s => <option key={s} value={s}>{s}</option>)}</select></div>
                </div>
                <button type="submit" className="w-full py-4 bg-blue-600 text-white rounded-2xl font-black uppercase shadow-xl hover:bg-blue-700 transition-all flex items-center justify-center gap-2"><Check size={18}/> Commit Updates</button>
             </form>
          </div>
        </div>
      )}

      {/* Bulk Message Modal */}
      {isBulkMessageModalOpen && (
        <div className="fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-[110] flex items-center justify-center p-4">
          <div className="bg-white rounded-[48px] shadow-2xl w-full max-w-lg overflow-hidden animate-in zoom-in-95">
             <div className="bg-emerald-600 p-8 text-white flex justify-between items-center">
                <h3 className="font-black uppercase tracking-widest text-sm">Bulk Transmission</h3>
                <button onClick={() => setIsBulkMessageModalOpen(false)}><X size={24}/></button>
             </div>
             <div className="p-10 space-y-6">
                <div className="space-y-2">
                   <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Select Communication Template</label>
                   <select 
                     className="w-full p-4 bg-slate-50 border border-slate-200 rounded-2xl font-bold text-sm outline-none"
                     value={selectedTemplateId}
                     onChange={(e) => setSelectedTemplateId(e.target.value)}
                   >
                      {DEFAULT_TEMPLATES.map(t => <option key={t.id} value={t.id}>{t.name} ({t.type})</option>)}
                   </select>
                </div>
                <div className="p-6 bg-slate-50 rounded-3xl border border-slate-100 italic text-slate-400 text-sm">
                   "Each message will be personalized with the lead's name and details automatically."
                </div>
                <button 
                  onClick={handleBulkWhatsAppSend}
                  disabled={isBulkSending}
                  className="w-full py-5 bg-emerald-600 text-white rounded-2xl font-black uppercase tracking-widest text-xs flex items-center justify-center gap-2"
                >
                   {isBulkSending ? <Loader2 className="animate-spin" size={20}/> : <Send size={20}/>}
                   {isBulkSending ? 'Transmitting...' : `Transmit to ${selectedLeads.length} Leads`}
                </button>
             </div>
          </div>
        </div>
      )}
    </div>
  );
};

