              <div className="space-y-4">
                {trip.itinerary.map((day, idx) => {
                  const isSelected = activeDayIndex === idx;
                  return (
                    <div key={day.id} className="relative group">
                      <button onClick={() => setActiveDayIndex(idx)} className={`w-full text-left p-4 rounded-2xl border transition-all flex flex-col gap-1 ${isSelected ? 'bg-blue-600 border-blue-600 text-white shadow-lg' : 'bg-white border-slate-100 hover:border-slate-300 text-slate-700'}`}>
                        <div className="flex justify-between items-center"><span className={`text-[9px] font-black uppercase tracking-widest ${isSelected ? 'text-blue-100' : 'text-blue-600'}`}>Day {day.dayNumber}</span></div>
