export const TripBuilder: React.FC = () => {
  const { id } = useParams();
  const navigate = useNavigate();
  const [trip, setTrip] = useState<Trip | null>(null);
  const [activeDayIndex, setActiveDayIndex] = useState(0);
  const [isAiGenerating, setIsAiGenerating] = useState(false);
  const [activeRightTab, setActiveRightTab] = useState<'config' | 'history'>('config');

  const [isVersionModalOpen, setIsVersionModalOpen] = useState(false);
  const [versionLabel, setVersionLabel] = useState('');

  const masterHotels = useMemo(() => {
    const saved = localStorage.getItem('et_hotels');
    const custom = saved ? JSON.parse(saved) : [];
    return [...HOTELS, ...custom];
  }, []);

  const masterVehicles = useMemo(() => {
    const saved = localStorage.getItem('et_vehicles');
    const custom = saved ? JSON.parse(saved) : [];
    return [...VEHICLES, ...custom];
  }, []);

  const masterAddOns = useMemo(() => {
    const saved = localStorage.getItem('et_addons');
    const custom = saved ? JSON.parse(saved) : [];
    return [...ADD_ONS, ...custom];
  }, []);

  useEffect(() => {
    const savedTrips = localStorage.getItem('et_trips');
    let foundTrip: Trip | undefined;

    if (savedTrips) {
      foundTrip = JSON.parse(savedTrips).find((t: Trip) => t.id === id);
    }

    if (!foundTrip) {
      foundTrip = MOCK_TRIPS.find(t => t.id === id);
    }

    if (foundTrip) {
      setTrip({ 
        ...foundTrip, 
        startLocation: foundTrip.startLocation || 'Srinagar',
        numRooms: foundTrip.numRooms || 1,
        extraBeds: foundTrip.extraBeds || 0,
        childNoBed: foundTrip.childNoBed || 0,
        compChild: foundTrip.compChild || 0,
        hotelTiers: foundTrip.hotelTiers || [],
        tierPrices: foundTrip.tierPrices || { signature: 0, elite: 0, prime: 0 },
        tierMargins: foundTrip.tierMargins || { signature: 15, elite: 15, prime: 15 },
        versions: foundTrip.versions || []
      });
    }
  }, [id]);

  useEffect(() => {
    if (trip) {
      const savedTrips = localStorage.getItem('et_trips');
      let allTrips: Trip[] = savedTrips ? JSON.parse(savedTrips) : [...MOCK_TRIPS];
      const index = allTrips.findIndex(t => t.id === trip.id);
      if (index > -1) allTrips[index] = trip;
      localStorage.setItem('et_trips', JSON.stringify(allTrips));
    }
  }, [trip]);

  // Extract unique locations from the itinerary to manage tier selections
  const itineraryLocations = useMemo(() => {
    if (!trip) return [];
    const locs = trip.itinerary.slice(0, -1).map(day => {
      if (day.location) return day.location;
      const hotel = masterHotels.find(h => h.id === day.hotelId);
      return hotel?.location || 'Srinagar';
    });
    return Array.from(new Set(locs));
  }, [trip, masterHotels]);

  // Tiered Costing Engine
  const tieredCosts = useMemo(() => {
    if (!trip) return { signature: 0, elite: 0, prime: 0 };

    const calculateForTier = (tier: keyof HotelTierSelection) => {
      let hotelTotal = 0;
      let transportTotal = 0;
      let activitiesTotal = 0;
      let addOnsTotal = 0;

      trip.itinerary.forEach((day, idx) => {
        const dayLoc = day.location || masterHotels.find(h => h.id === day.hotelId)?.location || 'Srinagar';
        const tierMap = trip.hotelTiers?.find(t => t.location === dayLoc);
        const tierHotelId = tierMap?.[tier] as string;
        const hotel = masterHotels.find(h => h.id === tierHotelId);

        // Hotels (Nights calculation)
        if (hotel && idx < trip.itinerary.length - 1) {
          const nightlyBase = hotel.ratePerNight * trip.numRooms;
          const nightlyEB = (hotel.extraBedRate || 0) * trip.extraBeds;
          const nightlyChild = (hotel.childNoBedRate || 0) * trip.childNoBed;
          hotelTotal += (nightlyBase + nightlyEB + nightlyChild);
        }

        // Vehicles
        if (day.vehicleId) {
          const vehicle = masterVehicles.find(v => v.id === day.vehicleId);
          if (vehicle) transportTotal += vehicle.ratePerDay;
        }

        // Activities
        (day.activityIds || []).forEach(aid => {
          const act = ACTIVITIES.find(a => a.id === aid);
          if (act) activitiesTotal += (act.costPerPax * trip.pax);
        });
      });

      // Add-ons
      trip.addOnIds.forEach(aoId => {
        const ao = masterAddOns.find(a => a.id === aoId);
        if (ao) addOnsTotal += (ao.isPerPax ? ao.cost * trip.pax : ao.cost);
      });

      const subtotal = hotelTotal + transportTotal + activitiesTotal + addOnsTotal;
      const marginKey = tier.replace('HotelId', '') as keyof TierPrices;
      const marginPct = trip.tierMargins?.[marginKey] || 15;

      return Math.ceil(subtotal * (1 + marginPct / 100));
    };

    return {
      signature: calculateForTier('signatureHotelId'),
      elite: calculateForTier('eliteHotelId'),
      prime: calculateForTier('primeHotelId')
    };
  }, [trip, masterHotels, masterVehicles, masterAddOns]);

  const updateDay = (index: number, updates: Partial<ItineraryDay>) => {
    if (!trip) return;
    const newItinerary = [...trip.itinerary];
    newItinerary[index] = { ...newItinerary[index], ...updates };
    setTrip({ ...trip, itinerary: newItinerary });
  };

  const updateTierSelection = (location: string, tier: keyof HotelTierSelection, hotelId: string) => {
    if (!trip) return;
    const tiers = [...(trip.hotelTiers || [])];
    const index = tiers.findIndex(t => t.location === location);
    if (index > -1) {
      tiers[index] = { ...tiers[index], [tier]: hotelId };
    } else {
      tiers.push({
        location,
        signatureHotelId: tier === 'signatureHotelId' ? hotelId : '',
        eliteHotelId: tier === 'eliteHotelId' ? hotelId : '',
        primeHotelId: tier === 'primeHotelId' ? hotelId : ''
      });
    }
    setTrip({ ...trip, hotelTiers: tiers });
  };

  const autoApplyPricing = () => {
    if (!trip) return;
    setTrip({
      ...trip,
      tierPrices: {
        signature: tieredCosts.signature,
        elite: tieredCosts.elite,
        prime: tieredCosts.prime
      }
    });
  };

  const handleAiDescription = async () => {
    if (!trip) return;
    setIsAiGenerating(true);
    const day = trip.itinerary[activeDayIndex];
    const desc = await generateDayDescription(day.title, []);
    updateDay(activeDayIndex, { clientNotes: desc });
    setIsAiGenerating(false);
  };

  if (!trip) return <div className="p-20 text-center text-slate-300 font-black uppercase">INITIALIZING...</div>;

  return (
    <div className="flex flex-col h-full space-y-6 pb-20">
      <div className="bg-white p-6 rounded-[32px] border border-slate-200 shadow-sm flex items-center justify-between">
        <div className="flex items-center gap-5">
          <button onClick={() => navigate('/trips')} className="p-3 hover:bg-slate-50 rounded-2xl transition-all border border-slate-100 shadow-sm"><ArrowLeft size={20} className="text-slate-600" /></button>
          <div>
            <h1 className="text-2xl font-black text-slate-900 tracking-tight">{trip.tripName}</h1>
            <p className="text-[10px] font-black uppercase text-blue-600 tracking-widest">{trip.client.name} • {trip.startDate}</p>
          </div>
        </div>
        <div className="flex items-center gap-4">
          <div className="flex items-center gap-6 px-6 py-3 bg-slate-950 rounded-2xl">
             <div className="text-right">
                <p className="text-[8px] font-black text-slate-500 uppercase">Current Elite Quote</p>
                <p className="text-lg font-black text-white">₹{(trip.tierPrices?.elite || tieredCosts.elite).toLocaleString()}</p>
             </div>
          </div>
          <button onClick={() => navigate(`/trips/${trip.id}/print`)} className="bg-blue-600 text-white px-8 py-4 rounded-2xl font-black uppercase tracking-widest text-[11px] shadow-xl hover:bg-blue-700 transition-all active:scale-95 flex items-center gap-2">
            <Download size={16}/> PROPOSAL PDF
          </button>
        </div>
      </div>

      <div className="grid grid-cols-12 gap-8 flex-1 overflow-hidden">
        {/* Step Navigation */}
        <div className="col-span-3 space-y-6 overflow-y-auto pr-2">
           <div className="bg-white border border-slate-200 rounded-[32px] p-6 shadow-sm">
              <h3 className="text-[10px] font-black uppercase tracking-widest text-slate-400 flex items-center gap-2 mb-6"><CalendarDays size={16} className="text-blue-600" /> Itinerary Steps</h3>
              <div className="space-y-3">
                {trip.itinerary.map((day, idx) => (
                  <button 
                    key={day.id} 
                    onClick={() => setActiveDayIndex(idx)}
                    className={`w-full text-left p-4 rounded-2xl border transition-all flex flex-col gap-1 ${activeDayIndex === idx ? 'bg-blue-600 border-blue-600 text-white shadow-lg' : 'bg-white border-slate-100 hover:border-slate-300 text-slate-700'}`}
                  >
                    <span className={`text-[8px] font-black uppercase ${activeDayIndex === idx ? 'text-blue-100' : 'text-blue-600'}`}>Day {day.dayNumber}</span>
                    <h4 className="font-bold text-xs truncate">{day.title}</h4>
                  </button>
                ))}
              </div>
           </div>
        </div>

        {/* Content Editor */}
        <div className="col-span-6 space-y-8 overflow-y-auto pr-2">
           {trip.itinerary[activeDayIndex] && (
             <div className="bg-white border border-slate-200 rounded-[40px] p-10 shadow-sm space-y-8">
                <div className="space-y-3">
                   <label className="text-[10px] font-black uppercase tracking-widest text-slate-400 ml-1">Daily Title Headline</label>
                   <input 
                     type="text" 
                     value={trip.itinerary[activeDayIndex].title} 
                     onChange={(e) => updateDay(activeDayIndex, { title: e.target.value })} 
                     className="w-full px-8 py-6 bg-blue-50/30 border-2 border-blue-100 rounded-3xl text-2xl font-black text-slate-900 focus:bg-white transition-all outline-none" 
                   />
                </div>
                <div className="space-y-6">
                   <div className="flex items-center justify-between border-b border-slate-100 pb-3">
                      <h4 className="text-[10px] font-black uppercase tracking-widest text-slate-400 flex items-center gap-2">Client Narrative</h4>
                      <button onClick={handleAiDescription} disabled={isAiGenerating} className="flex items-center gap-2 text-[10px] font-black uppercase text-blue-600 hover:underline disabled:opacity-50"><Sparkles size={14} /> AI Suggest</button>
                   </div>
                   <textarea 
                     rows={10} 
                     value={trip.itinerary[activeDayIndex].clientNotes} 
                     onChange={(e) => updateDay(activeDayIndex, { clientNotes: e.target.value })} 
                     className="w-full p-8 bg-slate-50 border border-slate-200 rounded-[32px] text-base leading-relaxed text-slate-800 outline-none focus:bg-white transition-all shadow-inner" 
                     placeholder="Paint a picture for the guest..." 
                   />
                </div>
             </div>
           )}
        </div>

        {/* Configuration Sidebar */}
        <div className="col-span-3 space-y-6 overflow-y-auto pr-2 pb-20">
           <div className="flex gap-2 p-1.5 bg-slate-100 rounded-2xl">
              <button onClick={() => setActiveRightTab('config')} className={`flex-1 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${activeRightTab === 'config' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-400'}`}>Logistics</button>
              <button onClick={() => setActiveRightTab('history')} className={`flex-1 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${activeRightTab === 'history' ? 'bg-white text-blue-600 shadow-sm' : 'text-slate-400'}`}>Tiers</button>
           </div>

           {activeRightTab === 'config' && (
             <div className="space-y-6 animate-in fade-in slide-in-from-right-2">
                <div className="bg-white border-2 border-slate-900 rounded-[32px] p-6 shadow-sm space-y-6">
                   <h3 className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-400 flex items-center gap-2"><Users size={16} className="text-blue-600" /> Rooming Hub</h3>
                   <div className="grid grid-cols-2 gap-4">
                      <div className="space-y-1">
                         <label className="text-[9px] font-black uppercase text-slate-400">Total PAX</label>
                         <input type="number" value={trip.pax} onChange={e => setTrip({...trip, pax: parseInt(e.target.value) || 0})} className="w-full p-2 bg-slate-50 border rounded-xl font-black text-xs text-slate-900 outline-none" />
                      </div>
                      <div className="space-y-1">
                         <label className="text-[9px] font-black uppercase text-slate-400">Rooms</label>
                         <input type="number" value={trip.numRooms} onChange={e => setTrip({...trip, numRooms: parseInt(e.target.value) || 0})} className="w-full p-2 bg-slate-50 border rounded-xl font-black text-xs text-slate-900 outline-none" />
                      </div>
                      <div className="space-y-1">
                         <label className="text-[9px] font-black uppercase text-slate-400">Extra Beds</label>
                         <input type="number" value={trip.extraBeds} onChange={e => setTrip({...trip, extraBeds: parseInt(e.target.value) || 0})} className="w-full p-2 bg-slate-50 border rounded-xl font-black text-xs text-slate-900 outline-none" />
                      </div>
                      <div className="space-y-1">
                         <label className="text-[9px] font-black uppercase text-slate-400">Child (No Bed)</label>
