import * as React from 'react';
import { useState, useEffect } from 'react';
// @ts-ignore
import { useNavigate, useLocation } from 'react-router-dom';
import { ArrowLeft, User, Phone, Mail, Globe, Calendar, Users, Briefcase, ChevronRight, Check } from 'lucide-react';
import { TripType, TripStatus, Trip } from '../types';
import { MOCK_TEMPLATES, MOCK_TRIPS, BRAND_CONFIG, TripTemplate, DEFAULT_INCLUSIONS, DEFAULT_EXCLUSIONS, MOCK_LEADS } from '../constants';

const NewTrip: React.FC = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const [step, setStep] = useState(1);
  const [allTemplates, setAllTemplates] = useState<TripTemplate[]>([]);
  const [formData, setFormData] = useState({
    clientName: '',
    phone: '',
    email: '',
    source: 'Website',
    tripName: '',
    tripType: TripType.FAMILY,
    pax: 2,
    numRooms: 1,
    extraBeds: 0,
    childNoBed: 0,
    compChild: 0,
    startDate: '',
    endDate: '',
    templateId: 'blank',
    startLocation: 'Srinagar' as 'Srinagar' | 'Jammu',
    leadId: ''
  });

  useEffect(() => {
    const savedTemplatesRaw = localStorage.getItem('et_templates');
    const savedTemplates = savedTemplatesRaw ? JSON.parse(savedTemplatesRaw) : [];
    const merged = [...MOCK_TEMPLATES, ...savedTemplates];
    setAllTemplates(merged);

    const queryParams = new URLSearchParams(location.search);
    const templateId = queryParams.get('templateId');
    const leadId = queryParams.get('leadId');

    if (templateId) {
      const template = merged.find(t => t.id === templateId);
      if (template) {
        setFormData(prev => ({ 
          ...prev, 
          templateId, 
          tripType: template.tripType,
          pax: template.pax || 2,
          numRooms: template.numRooms || 1,
          extraBeds: template.extraBeds || 0,
          childNoBed: template.childNoBed || 0,
          compChild: template.compChild || 0
        }));
      }
    }

    if (leadId) {
      const savedLeadsRaw = localStorage.getItem('et_leads');
      const allLeads = savedLeadsRaw ? JSON.parse(savedLeadsRaw) : MOCK_LEADS;
      const foundLead = allLeads.find((l: any) => l.id === leadId);
      if (foundLead) {
        setFormData(prev => ({
          ...prev,
          leadId,
          clientName: foundLead.name,
          phone: foundLead.phone,
          email: foundLead.email,
          source: foundLead.source,
          pax: foundLead.pax,
          tripType: foundLead.interest
        }));
      } else {
        setFormData(prev => ({ ...prev, leadId }));
      }
    }
  }, [location.search]);

  const handleNext = () => setStep(step + 1);
  const handleBack = () => setStep(step - 1);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    const masterInc = localStorage.getItem('et_master_inclusions');
    const masterExc = localStorage.getItem('et_master_exclusions');
    const currentMasterInclusions = masterInc ? JSON.parse(masterInc) : [...DEFAULT_INCLUSIONS];
    const currentMasterExclusions = masterExc ? JSON.parse(masterExc) : [...DEFAULT_EXCLUSIONS];

    const newId = `trip-${Date.now()}`;
    const selectedTemplate = allTemplates.find(t => t.id === formData.templateId);

    const newTrip: Trip = {
      id: newId,
      leadId: formData.leadId,
      client: {
        name: formData.clientName,
        phone: formData.phone,
        email: formData.email,
        source: formData.source,
      },
      tripName: formData.tripName || `${formData.clientName}'s Kashmir Trip`,
      tripType: formData.tripType,
      startDate: formData.startDate,
      endDate: formData.endDate,
      pax: formData.pax,
      numRooms: formData.numRooms,
      extraBeds: formData.extraBeds,
      childNoBed: formData.childNoBed,
      compChild: formData.compChild,
      budgetRange: 'TBD',
      assignedSalesperson: 'Adil Bakshi',
      status: TripStatus.LEAD,
      marginPercentage: selectedTemplate?.baseMargin || BRAND_CONFIG.defaultMargin,
      addOnIds: [],
      itinerary: selectedTemplate ? JSON.parse(JSON.stringify(selectedTemplate.itinerary)) : [],
      versions: [],
      startLocation: formData.startLocation,
      inclusions: selectedTemplate ? [...selectedTemplate.inclusions] : currentMasterInclusions,
      exclusions: selectedTemplate ? [...selectedTemplate.exclusions] : currentMasterExclusions,
      hotelTiers: [],
      tierPrices: { signature: 0, elite: 0, prime: 0 }
    };

    const savedTripsRaw = localStorage.getItem('et_trips');
    const allTrips: Trip[] = savedTripsRaw ? JSON.parse(savedTripsRaw) : [...MOCK_TRIPS];
    allTrips.push(newTrip);
    localStorage.setItem('et_trips', JSON.stringify(allTrips));

    navigate(`/trips/${newId}`); 
  };

  return (
    <div className="max-w-4xl mx-auto py-8">
      <button onClick={() => navigate('/trips')} className="mb-6 flex items-center gap-2 text-slate-500 hover:text-slate-800 transition-colors font-medium">
        <ArrowLeft size={18} />
        Back to Trips
      </button>

      <div className="bg-white rounded-2xl border border-slate-200 shadow-xl overflow-hidden text-slate-900">
        <div className="bg-slate-50 border-b border-slate-100 flex p-6 gap-8">
          <div className={`flex items-center gap-3 ${step >= 1 ? 'text-blue-600' : 'text-slate-400'}`}>
            <div className={`w-8 h-8 rounded-full flex items-center justify-center font-bold text-sm ${step >= 1 ? 'bg-blue-600 text-white' : 'bg-slate-200 text-slate-500'}`}>
              {step > 1 ? <Check size={16} /> : '1'}
            </div>
            <span className="font-bold text-xs uppercase tracking-wider">Client Details</span>
          </div>
          <div className={`flex items-center gap-3 ${step >= 2 ? 'text-blue-600' : 'text-slate-400'}`}>
            <div className={`w-8 h-8 rounded-full flex items-center justify-center font-bold text-sm ${step >= 2 ? 'bg-blue-600 text-white' : 'bg-slate-200 text-slate-500'}`}>
              {step > 2 ? <Check size={16} /> : '2'}
            </div>
            <span className="font-bold text-xs uppercase tracking-wider">Occupancy</span>
          </div>
          <div className={`flex items-center gap-3 ${step >= 3 ? 'text-blue-600' : 'text-slate-400'}`}>
            <div className={`w-8 h-8 rounded-full flex items-center justify-center font-bold text-sm ${step >= 3 ? 'bg-blue-600 text-white' : 'bg-slate-200 text-slate-500'}`}>
              3
            </div>
            <span className="font-bold text-xs uppercase tracking-wider">Route</span>
          </div>
        </div>

        <form onSubmit={handleSubmit} className="p-10">
          {step === 1 && (
            <div className="space-y-6 animate-in fade-in slide-in-from-right-4">
              <div className="grid grid-cols-2 gap-6">
                <div className="space-y-2">
                  <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Client Name</label>
                  <div className="relative">
                    <User className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-300" size={18} />
                    <input 
                      required
                      type="text" 
                      className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl outline-none font-bold text-slate-900"
                      value={formData.clientName}
                      onChange={(e) => setFormData({...formData, clientName: e.target.value})}
                    />
                  </div>
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Phone</label>
                  <div className="relative">
                    <Phone className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-300" size={18} />
                    <input 
                      required
                      type="tel" 
                      className="w-full pl-10 pr-4 py-3 bg-slate-50 border border-slate-200 rounded-xl outline-none font-bold text-slate-900"
                      value={formData.phone}
                      onChange={(e) => setFormData({...formData, phone: e.target.value})}
                    />
                  </div>
                </div>
              </div>
            </div>
          )}

          {step === 2 && (
            <div className="space-y-8 animate-in fade-in slide-in-from-right-4">
              <div className="bg-blue-50/50 p-8 rounded-[40px] border border-blue-100 space-y-8">
                <div className="flex items-center gap-3 border-b border-blue-100 pb-4">
                   <div className="bg-blue-600 p-2 rounded-xl text-white shadow-lg"><Users size={20}/></div>
                   <h4 className="text-sm font-black uppercase tracking-widest text-blue-900">Guest & Rooming Logistics</h4>
                </div>
                <div className="grid grid-cols-2 md:grid-cols-5 gap-6">
                   <div className="space-y-1.5 text-center md:text-left">
                      <label className="text-[9px] font-black uppercase text-slate-400 tracking-widest">Total PAX</label>
                      <input type="number" className="w-full px-4 py-3 bg-white border border-slate-200 rounded-xl font-black text-slate-900 text-center" value={formData.pax} onChange={e => setFormData({...formData, pax: parseInt(e.target.value) || 0})} />
                   </div>
                   <div className="space-y-1.5 text-center md:text-left">
                      <label className="text-[9px] font-black uppercase text-slate-400 tracking-widest">Rooms</label>
                      <input type="number" className="w-full px-4 py-3 bg-white border border-slate-200 rounded-xl font-black text-slate-900 text-center" value={formData.numRooms} onChange={e => setFormData({...formData, numRooms: parseInt(e.target.value) || 0})} />
                   </div>
                   <div className="space-y-1.5 text-center md:text-left">
                      <label className="text-[9px] font-black uppercase text-slate-400 tracking-widest">Extra Beds</label>
                      <input type="number" className="w-full px-4 py-3 bg-white border border-slate-200 rounded-xl font-black text-slate-900 text-center" value={formData.extraBeds} onChange={e => setFormData({...formData, extraBeds: parseInt(e.target.value) || 0})} />
                   </div>
                   <div className="space-y-1.5 text-center md:text-left">
                      <label className="text-[9px] font-black uppercase text-slate-400 tracking-widest">Child (No Bed)</label>
                      <input type="number" className="w-full px-4 py-3 bg-white border border-slate-200 rounded-xl font-black text-slate-900 text-center" value={formData.childNoBed} onChange={e => setFormData({...formData, childNoBed: parseInt(e.target.value) || 0})} />
                   </div>
                </div>
              </div>

              <div className="grid grid-cols-2 gap-6">
                <div className="space-y-2">
                  <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest">Start Date</label>
                  <input required type="date" className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl font-bold" value={formData.startDate} onChange={(e) => setFormData({...formData, startDate: e.target.value})} />
                </div>
                <div className="space-y-2">
                  <label className="text-[10px] font-black uppercase text-slate-400 tracking-widest">End Date</label>
                  <input required type="date" className="w-full px-4 py-3 bg-slate-50 border border-slate-200 rounded-xl font-bold" value={formData.endDate} onChange={(e) => setFormData({...formData, endDate: e.target.value})} />
                </div>
              </div>
            </div>
          )}

          {step === 3 && (
            <div className="space-y-6 animate-in fade-in slide-in-from-right-4">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <button 
                  type="button"
                  onClick={() => setFormData({...formData, templateId: 'blank'})}
                  className={`p-8 border-2 rounded-[32px] text-left transition-all ${formData.templateId === 'blank' ? 'border-blue-600 bg-blue-50 shadow-xl' : 'border-slate-100 bg-white hover:border-slate-300'}`}
                >
                  <h4 className="font-black text-slate-900 text-lg uppercase tracking-tight">Blank Canvas</h4>
                  <p className="text-xs text-slate-400 mt-2 font-bold uppercase tracking-widest leading-relaxed">Start from scratch. Use the builder to select hotels and route.</p>
                </button>
                {allTemplates.map(temp => (
                  <button 
                    key={temp.id}
                    type="button"
                    onClick={() => setFormData({...formData, templateId: temp.id})}
                    className={`p-8 border-2 rounded-[32px] text-left transition-all ${formData.templateId === temp.id ? 'border-blue-600 bg-blue-50 shadow-xl' : 'border-slate-100 bg-white hover:border-slate-300'}`}
                  >
                    <h4 className="font-black text-slate-900 text-lg uppercase tracking-tight">{temp.name}</h4>
                    <p className="text-[10px] text-blue-600 mt-2 font-black uppercase tracking-widest">{temp.duration} • {temp.tripType}</p>
                  </button>
                ))}
              </div>
            </div>
          )}

          <div className="mt-12 pt-8 border-t border-slate-100 flex items-center justify-between">
            {step > 1 ? (
              <button type="button" onClick={handleBack} className="px-6 py-2 text-slate-400 font-black uppercase tracking-widest text-xs hover:text-slate-900 transition-colors">Back</button>
            ) : <div/>}

            {step < 3 ? (
              <button type="button" onClick={handleNext} className="bg-blue-600 text-white px-10 py-4 rounded-2xl font-black uppercase tracking-widest text-xs shadow-xl hover:bg-blue-700 transition-all flex items-center gap-2">Next Step <ChevronRight size={16}/></button>
            ) : (
              <button type="submit" className="bg-emerald-600 text-white px-12 py-5 rounded-2xl font-black uppercase tracking-[0.2em] text-xs shadow-2xl shadow-emerald-100 hover:bg-emerald-700 transition-all">Generate & Build Proposal</button>
            )}
          </div>
        </form>
      </div>
    </div>
  );
};

