  Wallet,
  AlertTriangle,
  RotateCcw,
  Zap,
  BedDouble,
  Baby
} from 'lucide-react';
import { 
  MOCK_TRIPS, 
  BRAND_CONFIG, 
  HOTELS, 
  VEHICLES, 
  TERMS_AND_CONDITIONS,
  PAYMENT_TERMS,
  CANCELLATION_POLICY,
  REFUND_POLICY,
