// New Types for Operations Tracking
export type OpsAlertType = 'ARRIVAL' | 'DEPARTURE' | 'HOTEL_CHANGE' | 'PLAN_REMINDER';

export interface OpsAlert {
  id: string;
  tripId: string;
  clientName: string;
  type: OpsAlertType;
  message: string;
  severity: 'CRITICAL' | 'WARNING' | 'INFO';
  timestamp: string;
}

import React, { useState, useMemo, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { 
  MapPin, 
  Car, 
  Hotel, 
  Users, 
  AlertCircle, 
  CheckCircle2, 
  Clock, 
  Phone, 
  MessageSquare,
  ChevronRight,
  PlaneLanding,
  PlaneTakeoff,
  RefreshCcw,
  Zap,
  Info,
  Calendar,
  Compass
} from 'lucide-react';
import { MOCK_TRIPS, HOTELS, VEHICLES } from '../constants';
import { Trip, TripStatus, ItineraryDay, OpsAlert } from '../types';

const OngoingTrips: React.FC = () => {
  const navigate = useNavigate();
  const [trips, setTrips] = useState<Trip[]>([]);
  const todayStr = new Date().toISOString().split('T')[0];

  useEffect(() => {
    const savedTrips = localStorage.getItem('et_trips');
    setTrips(savedTrips ? JSON.parse(savedTrips) : MOCK_TRIPS);
  }, []);

  const ongoingTrips = useMemo(() => {
    return trips.filter(trip => {
      if (trip.status !== TripStatus.BOOKED) return false;
      return trip.startDate <= todayStr && trip.endDate >= todayStr;
    });
  }, [trips, todayStr]);

  const getDayInfo = (trip: Trip) => {
    const start = new Date(trip.startDate);
    const today = new Date(todayStr);
    const diffTime = Math.abs(today.getTime() - start.getTime());
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24)) + 1;

    const todayItinerary = trip.itinerary.find(d => d.dayNumber === diffDays);
    const yesterdayItinerary = trip.itinerary.find(d => d.dayNumber === diffDays - 1);

    return {
      currentDay: diffDays,
      totalDays: trip.itinerary.length,
      todayPlan: todayItinerary,
      yesterdayPlan: yesterdayItinerary
    };
  };

  const opsAlerts = useMemo(() => {
    const alerts: OpsAlert[] = [];
    ongoingTrips.forEach(trip => {
      const { currentDay, totalDays, todayPlan, yesterdayPlan } = getDayInfo(trip);

      if (currentDay === 1) {
        alerts.push({
          id: `arr-${trip.id}`,
          tripId: trip.id,
          clientName: trip.client.name,
          type: 'ARRIVAL',
          message: `Arrival today in ${trip.startLocation}. Coordinate pickup.`,
          severity: 'CRITICAL',
          timestamp: new Date().toISOString()
        });
      }

      if (currentDay === totalDays) {
        alerts.push({
          id: `dep-${trip.id}`,
          tripId: trip.id,
          clientName: trip.client.name,
          type: 'DEPARTURE',
          message: `Departure today. Drop-off at ${trip.startLocation} Airport/Station.`,
          severity: 'CRITICAL',
          timestamp: new Date().toISOString()
        });
      }

      if (todayPlan && yesterdayPlan && todayPlan.hotelId !== yesterdayPlan.hotelId && todayPlan.hotelId) {
        alerts.push({
          id: `move-${trip.id}`,
          tripId: trip.id,
          clientName: trip.client.name,
          type: 'HOTEL_CHANGE',
          message: `Moving from ${yesterdayPlan.location} to ${todayPlan.location} today.`,
          severity: 'WARNING',
          timestamp: new Date().toISOString()
        });
      }
    });
    return alerts;
  }, [ongoingTrips]);

  const StatCard = ({ label, value, icon: Icon, color }: any) => (
    <div className="bg-white p-6 rounded-[32px] border border-slate-100 shadow-sm flex items-center gap-5">
      <div className={`${color} p-4 rounded-2xl text-white`}>
        <Icon size={24} />
      </div>
      <div>
        <p className="text-slate-400 text-[10px] font-black uppercase tracking-widest">{label}</p>
        <p className="text-2xl font-black text-slate-900">{value}</p>
      </div>
    </div>
  );

  return (
    <div className="space-y-8 pb-20">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-black text-slate-900 tracking-tight flex items-center gap-3">
             <div className="w-3 h-3 bg-emerald-500 rounded-full animate-pulse" /> Live Operations Hub
          </h1>
          <p className="text-slate-500 text-sm">Real-time tracking of clients currently in the valley.</p>
        </div>
        <div className="flex items-center gap-3">
          <div className="px-4 py-2 bg-slate-900 text-white rounded-xl text-[10px] font-black uppercase tracking-widest flex items-center gap-2">
            <Calendar size={14} className="text-blue-400" /> {new Date().toLocaleDateString('en-IN', { day: 'numeric', month: 'long', year: 'numeric' })}
          </div>
          <button className="p-3 bg-white border border-slate-200 rounded-xl text-slate-400 hover:text-blue-600 transition-all">
            <RefreshCcw size={18} />
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
        <StatCard label="Ongoing Groups" value={ongoingTrips.length} icon={Users} color="bg-blue-600" />
        <StatCard label="Arrivals Today" value={opsAlerts.filter(a => a.type === 'ARRIVAL').length} icon={PlaneLanding} color="bg-emerald-600" />
        <StatCard label="Departures Today" value={opsAlerts.filter(a => a.type === 'DEPARTURE').length} icon={PlaneTakeoff} color="bg-rose-600" />
        <StatCard label="Live Movements" value={opsAlerts.filter(a => a.type === 'HOTEL_CHANGE').length} icon={RefreshCcw} color="bg-amber-600" />
      </div>

      <div className="grid grid-cols-12 gap-8">
        {/* Left Column: Active Trips Board */}
        <div className="col-span-12 xl:col-span-8 space-y-6">
           <div className="flex items-center justify-between px-2">
              <h3 className="text-xs font-black uppercase tracking-[0.2em] text-slate-400">Valley Operations Board</h3>
           </div>

           <div className="space-y-6">
             {ongoingTrips.length > 0 ? ongoingTrips.map(trip => {
               const { currentDay, totalDays, todayPlan } = getDayInfo(trip);
               const hotel = HOTELS.find(h => h.id === todayPlan?.hotelId);
               const vehicle = VEHICLES.find(v => v.id === todayPlan?.vehicleId);

               return (
                 <div key={trip.id} className="bg-white border border-slate-100 rounded-[40px] shadow-sm hover:shadow-xl transition-all overflow-hidden group">
                    <div className="p-8 flex flex-col md:flex-row gap-8">
                       <div className="flex-1 space-y-4">
                          <div className="flex items-center justify-between">
                             <div className="flex items-center gap-3">
                                <span className="bg-blue-50 text-blue-600 text-[10px] font-black px-3 py-1 rounded-full uppercase">Day {currentDay} / {totalDays}</span>
                                <h3 className="text-xl font-black text-slate-900">{trip.client.name}</h3>
                             </div>
                             <div className="flex items-center gap-1.5">
                                <button className="p-2 bg-slate-50 text-slate-400 hover:text-emerald-500 rounded-xl transition-all"><MessageSquare size={16}/></button>
                                <button className="p-2 bg-slate-50 text-slate-400 hover:text-blue-600 rounded-xl transition-all"><Phone size={16}/></button>
                             </div>
                          </div>

                          <div className="grid grid-cols-2 gap-6">
                             <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100 space-y-2">
                                <div className="flex items-center gap-2 text-[10px] font-black uppercase text-slate-400">
                                   <MapPin size={12} className="text-blue-500"/> Current Location
                                </div>
                                <p className="font-bold text-slate-900">{todayPlan?.location || 'Transfer In Progress'}</p>
                             </div>
                             <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100 space-y-2">
                                <div className="flex items-center gap-2 text-[10px] font-black uppercase text-slate-400">
                                   <Hotel size={12} className="text-amber-500"/> Today's Stay
                                </div>
                                <p className="font-bold text-slate-900 truncate">{hotel?.name || 'N/A'}</p>
                             </div>
                          </div>

                          <div className="flex items-center justify-between pt-4 border-t border-slate-50">
                             <div className="flex items-center gap-4">
                                <div className="flex items-center gap-2 text-[11px] font-bold text-slate-500">
                                   <Car size={16} className="text-slate-300" /> {vehicle?.type || 'Not Assigned'}
                                </div>
                                <div className="w-1 h-1 bg-slate-200 rounded-full" />
                                <div className="flex items-center gap-2 text-[11px] font-bold text-slate-500">
                                   <Users size={16} className="text-slate-300" /> {trip.pax} Guests
                                </div>
                             </div>
                             <button onClick={() => navigate(`/trips/${trip.id}`)} className="text-[10px] font-black uppercase tracking-widest text-blue-600 flex items-center gap-1 hover:underline">
                                Full Detail <ChevronRight size={14}/>
                             </button>
                          </div>
                       </div>

                       <div className="w-full md:w-64 bg-slate-950 p-6 rounded-[32px] text-white space-y-4">
                          <p className="text-[9px] font-black uppercase tracking-[0.2em] text-slate-500">Scheduled Today</p>
                          <div className="space-y-3">
                             {todayPlan?.activityIds.length ? todayPlan.activityIds.slice(0, 3).map(id => (
                               <div key={id} className="flex items-center gap-2 text-xs font-bold">
                                  <Zap size={14} className="text-amber-400" /> {id === 'a1' ? 'Shikara Ride' : id === 'a2' ? 'Gondola Ride' : 'Sightseeing'}
                               </div>
                             )) : (
                               <div className="text-slate-600 text-[10px] font-black uppercase tracking-widest py-4">No Special Activities</div>
                             )}
                          </div>
                          {trip.numRooms && (
                             <div className="pt-4 border-t border-white/10 flex items-center justify-between">
                                <span className="text-[10px] font-black text-slate-500 uppercase">Rooms</span>
                                <span className="text-sm font-black">{trip.numRooms} Unit(s)</span>
                             </div>
                          )}
                       </div>
                    </div>
                 </div>
               );
             }) : (
               <div className="bg-white p-32 rounded-[48px] border-2 border-dashed border-slate-200 text-center flex flex-col items-center gap-6">
                 <div className="p-8 bg-slate-50 rounded-full text-slate-200">
                    <Compass size={64} />
                 </div>
                 <div>
                    <h4 className="text-xl font-black text-slate-900 uppercase">No Active Trips Today</h4>
                    <p className="text-slate-400 font-bold">Check upcoming departures in the All Itineraries tab.</p>
                 </div>
               </div>
             )}
           </div>
        </div>

        {/* Right Column: Live Notifications */}
        <div className="col-span-12 xl:col-span-4 space-y-8">
           <div className="bg-rose-50 p-8 rounded-[48px] border border-rose-100 shadow-sm space-y-6">
              <div className="flex items-center justify-between">
                 <h3 className="text-xs font-black uppercase tracking-widest text-rose-600 flex items-center gap-2">
                    <AlertCircle size={16} /> Movement Alerts
                 </h3>
                 <span className="bg-rose-600 text-white text-[8px] font-black px-2 py-0.5 rounded-full">{opsAlerts.length} Active</span>
              </div>

              <div className="space-y-4">
                 {opsAlerts.map(alert => (
                    <div key={alert.id} className="bg-white p-5 rounded-[32px] border border-rose-100 shadow-sm space-y-3 relative overflow-hidden group">
                       <div className={`absolute top-0 left-0 w-1 h-full ${alert.severity === 'CRITICAL' ? 'bg-rose-500' : 'bg-amber-500'}`} />
                       <div className="flex items-center justify-between">
                          <span className={`text-[9px] font-black uppercase px-2 py-0.5 rounded ${alert.type === 'ARRIVAL' ? 'bg-emerald-50 text-emerald-600' : alert.type === 'DEPARTURE' ? 'bg-rose-50 text-rose-600' : 'bg-amber-50 text-amber-600'}`}>
                             {alert.type}
                          </span>
                          <span className="text-[10px] font-bold text-slate-300 flex items-center gap-1"><Clock size={10}/> Now</span>
                       </div>
                       <div>
                          <p className="text-[10px] font-black uppercase text-slate-400 tracking-widest">{alert.clientName}</p>
                          <p className="text-xs font-bold text-slate-800 leading-snug">{alert.message}</p>
                       </div>
                    </div>
                 ))}
                 {opsAlerts.length === 0 && (
                   <div className="py-20 text-center space-y-4 opacity-30">
                      <CheckCircle2 size={48} className="mx-auto text-emerald-500" />
                      <p className="text-[10px] font-black uppercase tracking-widest">No Critical Alerts</p>
                   </div>
                 )}
              </div>
           </div>

           <div className="bg-blue-600 p-8 rounded-[48px] text-white shadow-2xl space-y-8">
              <h3 className="text-xs font-black uppercase tracking-widest text-blue-200">System Logs</h3>
              <div className="space-y-6">
                 <div className="flex gap-4">
                    <div className="w-10 h-10 bg-white/20 rounded-xl flex items-center justify-center shrink-0"><Info size={20}/></div>
                    <div className="space-y-1">
                       <p className="text-[11px] font-bold leading-snug">Operations dashboard syncs every 30 minutes with local driver updates.</p>
                       <p className="text-[9px] text-blue-200 uppercase font-black">Admin Notice</p>
                    </div>
                 </div>
                 <button className="w-full py-4 bg-white text-blue-600 rounded-2xl font-black uppercase tracking-widest text-[10px] active:scale-95 transition-all">
                    Generate Ops Report
                 </button>
              </div>
           </div>
        </div>
      </div>
    </div>
  );
};

