// New Types for Operations Tracking
export type OpsAlertType = 'ARRIVAL' | 'DEPARTURE' | 'HOTEL_CHANGE' | 'PLAN_REMINDER';

export interface OpsAlert {
  id: string;
  tripId: string;
  clientName: string;
  type: OpsAlertType;
  message: string;
  severity: 'CRITICAL' | 'WARNING' | 'INFO';
  timestamp: string;
}

import React, { useState, useMemo, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { 
  MapPin, 
  Car, 
  Hotel, 
  Users, 
  AlertCircle, 
  CheckCircle2, 
  Clock, 
  Phone, 
  MessageSquare,
  ChevronRight,
  PlaneLanding,
  PlaneTakeoff,
  RefreshCcw,
  Zap,
  Info,
  Calendar,
  Compass,
  X,
  User,
  ShieldCheck,
  Map as MapIcon,
  IndianRupee,
  Utensils,
  Moon,
  ExternalLink
} from 'lucide-react';
import { MOCK_TRIPS, HOTELS, VEHICLES, ACTIVITIES } from '../constants';
import { Trip, TripStatus, ItineraryDay, OpsAlert } from '../types';

const OngoingTrips: React.FC = () => {
  const navigate = useNavigate();
  const [trips, setTrips] = useState<Trip[]>([]);
  const [selectedDate, setSelectedDate] = useState(new Date().toISOString().split('T')[0]);
  const [viewingTrip, setViewingTrip] = useState<Trip | null>(null);

  useEffect(() => {
    const savedTrips = localStorage.getItem('et_trips');
    setTrips(savedTrips ? JSON.parse(savedTrips) : MOCK_TRIPS);
  }, []);

  const ongoingTrips = useMemo(() => {
    return trips.filter(trip => {
      if (trip.status !== TripStatus.BOOKED) return false;
      return trip.startDate <= selectedDate && trip.endDate >= selectedDate;
    });
  }, [trips, selectedDate]);

  const getDayInfo = (trip: Trip, dateStr: string) => {
    const start = new Date(trip.startDate);
    const targetDate = new Date(dateStr);
    const diffTime = targetDate.getTime() - start.getTime();
    const diffDays = Math.floor(diffTime / (1000 * 60 * 60 * 24)) + 1;

    const todayItinerary = trip.itinerary.find(d => d.dayNumber === diffDays);
    const yesterdayItinerary = trip.itinerary.find(d => d.dayNumber === diffDays - 1);

    return {
      currentDay: diffDays,
      totalDays: trip.itinerary.length,
      todayPlan: todayItinerary,
      yesterdayPlan: yesterdayItinerary
    };
  };

  const opsAlerts = useMemo(() => {
    const alerts: OpsAlert[] = [];
    ongoingTrips.forEach(trip => {
      const { currentDay, totalDays, todayPlan, yesterdayPlan } = getDayInfo(trip, selectedDate);

      if (currentDay === 1) {
        alerts.push({
          id: `arr-${trip.id}`,
          tripId: trip.id,
          clientName: trip.client.name,
          type: 'ARRIVAL',
          message: `Arrival today in ${trip.startLocation}. Coordinate pickup.`,
          severity: 'CRITICAL',
          timestamp: new Date().toISOString()
        });
      }

      if (currentDay === totalDays) {
        alerts.push({
          id: `dep-${trip.id}`,
          tripId: trip.id,
          clientName: trip.client.name,
          type: 'DEPARTURE',
          message: `Departure today. Drop-off at ${trip.startLocation} Airport/Station.`,
          severity: 'CRITICAL',
          timestamp: new Date().toISOString()
        });
      }

      if (todayPlan && yesterdayPlan && todayPlan.hotelId !== yesterdayPlan.hotelId && todayPlan.hotelId) {
        alerts.push({
          id: `move-${trip.id}`,
          tripId: trip.id,
          clientName: trip.client.name,
          type: 'HOTEL_CHANGE',
          message: `Moving from ${yesterdayPlan.location || 'Previous'} to ${todayPlan.location || 'Current'} today.`,
          severity: 'WARNING',
          timestamp: new Date().toISOString()
        });
      }
    });
    return alerts;
  }, [ongoingTrips, selectedDate]);

  const StatCard = ({ label, value, icon: Icon, color }: any) => (
    <div className="bg-white p-6 rounded-[32px] border border-slate-100 shadow-sm flex items-center gap-5">
      <div className={`${color} p-4 rounded-2xl text-white`}>
        <Icon size={24} />
      </div>
      <div>
        <p className="text-slate-400 text-[10px] font-black uppercase tracking-widest">{label}</p>
        <p className="text-2xl font-black text-slate-900">{value}</p>
      </div>
    </div>
  );

  const displayDate = new Date(selectedDate).toLocaleDateString('en-IN', { day: 'numeric', month: 'long', year: 'numeric' });

  return (
    <div className="space-y-8 pb-20">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-black text-slate-900 tracking-tight flex items-center gap-3">
             <div className="w-3 h-3 bg-emerald-500 rounded-full animate-pulse" /> Live Operations Hub
          </h1>
          <p className="text-slate-500 text-sm">Operational tracking for <span className="font-bold text-slate-800">{displayDate}</span>.</p>
        </div>
        <div className="flex items-center gap-3">
          <div className="px-4 py-2 bg-slate-900 text-white rounded-xl text-[10px] font-black uppercase tracking-widest flex items-center gap-2 relative overflow-hidden group">
            <Calendar size={14} className="text-blue-400" />
            <input 
              type="date" 
              className="bg-transparent border-none outline-none cursor-pointer uppercase font-black"
              value={selectedDate}
              onChange={(e) => setSelectedDate(e.target.value)}
            />
          </div>
          <button 
            onClick={() => setSelectedDate(new Date().toISOString().split('T')[0])}
            className="p-3 bg-white border border-slate-200 rounded-xl text-slate-400 hover:text-blue-600 transition-all flex items-center gap-2 text-xs font-bold"
          >
            <RefreshCcw size={18} /> Today
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
        <StatCard label="Trips on Date" value={ongoingTrips.length} icon={Users} color="bg-blue-600" />
        <StatCard label="Arrivals" value={opsAlerts.filter(a => a.type === 'ARRIVAL').length} icon={PlaneLanding} color="bg-emerald-600" />
        <StatCard label="Departures" value={opsAlerts.filter(a => a.type === 'DEPARTURE').length} icon={PlaneTakeoff} color="bg-rose-600" />
        <StatCard label="Movements" value={opsAlerts.filter(a => a.type === 'HOTEL_CHANGE').length} icon={RefreshCcw} color="bg-amber-600" />
      </div>

      <div className="grid grid-cols-12 gap-8">
        <div className="col-span-12 xl:col-span-8 space-y-6">
           <div className="flex items-center justify-between px-2">
              <h3 className="text-xs font-black uppercase tracking-[0.2em] text-slate-400">Operations Board for {displayDate}</h3>
           </div>

           <div className="space-y-6">
             {ongoingTrips.length > 0 ? ongoingTrips.map(trip => {
               const { currentDay, totalDays, todayPlan } = getDayInfo(trip, selectedDate);
               const hotel = HOTELS.find(h => h.id === todayPlan?.hotelId);
               const vehicle = VEHICLES.find(v => v.id === todayPlan?.vehicleId);

               return (
                 <div key={trip.id} className="bg-white border border-slate-100 rounded-[40px] shadow-sm hover:shadow-xl transition-all overflow-hidden group">
                    <div className="p-8 flex flex-col md:flex-row gap-8">
                       <div className="flex-1 space-y-4">
                          <div className="flex items-center justify-between">
                             <div className="flex items-center gap-3">
                                <span className={`text-[10px] font-black px-3 py-1 rounded-full uppercase ${currentDay === 1 ? 'bg-emerald-100 text-emerald-700' : currentDay === totalDays ? 'bg-rose-100 text-rose-700' : 'bg-blue-50 text-blue-600'}`}>
                                  Day {currentDay} / {totalDays}
                                </span>
                                <h3 className="text-xl font-black text-slate-900">{trip.client.name}</h3>
                             </div>
                             <div className="flex items-center gap-1.5">
                                <button className="p-2 bg-slate-50 text-slate-400 hover:text-emerald-500 rounded-xl transition-all"><MessageSquare size={16}/></button>
                                <button className="p-2 bg-slate-50 text-slate-400 hover:text-blue-600 rounded-xl transition-all"><Phone size={16}/></button>
                             </div>
                          </div>

                          <div className="grid grid-cols-2 gap-6">
                             <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100 space-y-2">
                                <div className="flex items-center gap-2 text-[10px] font-black uppercase text-slate-400">
                                   <MapPin size={12} className="text-blue-500"/> Plan Location
                                </div>
                                <p className="font-bold text-slate-900">{todayPlan?.location || 'Transfer / Srinagar'}</p>
                             </div>
                             <div className="p-4 bg-slate-50 rounded-2xl border border-slate-100 space-y-2">
                                <div className="flex items-center gap-2 text-[10px] font-black uppercase text-slate-400">
                                   <Hotel size={12} className="text-amber-500"/> Scheduled Stay
                                </div>
                                <p className="font-bold text-slate-900 truncate">{hotel?.name || 'In-Transit'}</p>
                             </div>
                          </div>

                          <div className="flex items-center justify-between pt-4 border-t border-slate-50">
                             <div className="flex items-center gap-4">
                                <div className="flex items-center gap-2 text-[11px] font-bold text-slate-500">
                                   <Car size={16} className="text-slate-300" /> {vehicle?.type || 'Not Assigned'}
                                </div>
                                <div className="w-1 h-1 bg-slate-200 rounded-full" />
                                <div className="flex items-center gap-2 text-[11px] font-bold text-slate-500">
                                   <Users size={16} className="text-slate-300" /> {trip.pax} Guests
                                </div>
                             </div>
                             <button 
                               onClick={() => setViewingTrip(trip)}
                               className="text-[10px] font-black uppercase tracking-widest text-blue-600 flex items-center gap-1 hover:underline"
                             >
                               Full Detail <ChevronRight size={14}/>
                             </button>
                          </div>
                       </div>

                       <div className="w-full md:w-64 bg-slate-950 p-6 rounded-[32px] text-white space-y-4">
                          <p className="text-[9px] font-black uppercase tracking-[0.2em] text-slate-500">Day {currentDay} Program</p>
                          <div className="space-y-3">
                             <div className="text-xs font-bold leading-tight">
                                {todayPlan?.title || 'Relax / Optional Tours'}
                             </div>
                             {todayPlan?.activityIds.length ? todayPlan.activityIds.slice(0, 2).map(id => {
                               const act = ACTIVITIES.find(a => a.id === id);
                               return (
                                 <div key={id} className="flex items-center gap-2 text-[10px] font-bold text-slate-400">
                                    <Zap size={12} className="text-amber-400" /> {act?.name || 'Activity'}
                                 </div>
                               );
                             }) : (
                               <div className="text-slate-600 text-[10px] font-black uppercase tracking-widest py-4">No Scheduled Excursions</div>
                             )}
                          </div>
                          {trip.numRooms && (
                             <div className="pt-4 border-t border-white/10 flex items-center justify-between">
                                <span className="text-[10px] font-black text-slate-500 uppercase">Rooms</span>
                                <span className="text-sm font-black">{trip.numRooms} Units</span>
                             </div>
                          )}
                       </div>
                    </div>
                 </div>
               );
             }) : (
               <div className="bg-white p-32 rounded-[48px] border-2 border-dashed border-slate-200 text-center flex flex-col items-center gap-6">
                 <div className="p-8 bg-slate-50 rounded-full text-slate-200">
                    <Compass size={64} />
                 </div>
                 <div>
                    <h4 className="text-xl font-black text-slate-900 uppercase">No Active Trips on this Date</h4>
                    <p className="text-slate-400 font-bold">Select another date from the calendar to view future/past operations.</p>
                 </div>
               </div>
             )}
           </div>
        </div>

        <div className="col-span-12 xl:col-span-4 space-y-8">
           <div className="bg-rose-50 p-8 rounded-[48px] border border-rose-100 shadow-sm space-y-6">
              <div className="flex items-center justify-between">
                 <h3 className="text-xs font-black uppercase tracking-widest text-rose-600 flex items-center gap-2">
                    <AlertCircle size={16} /> Day Movement Log
                 </h3>
                 <span className="bg-rose-600 text-white text-[8px] font-black px-2 py-0.5 rounded-full">{opsAlerts.length} Criticals</span>
              </div>

              <div className="space-y-4">
                 {opsAlerts.map(alert => (
                    <div key={alert.id} className="bg-white p-5 rounded-[32px] border border-rose-100 shadow-sm space-y-3 relative overflow-hidden group">
                       <div className={`absolute top-0 left-0 w-1 h-full ${alert.severity === 'CRITICAL' ? 'bg-rose-500' : 'bg-amber-500'}`} />
                       <div className="flex items-center justify-between">
                          <span className={`text-[9px] font-black uppercase px-2 py-0.5 rounded ${alert.type === 'ARRIVAL' ? 'bg-emerald-50 text-emerald-600' : alert.type === 'DEPARTURE' ? 'bg-rose-50 text-rose-600' : 'bg-amber-50 text-amber-600'}`}>
                             {alert.type}
                          </span>
                       </div>
                       <div>
                          <p className="text-[10px] font-black uppercase text-slate-400 tracking-widest">{alert.clientName}</p>
                          <p className="text-xs font-bold text-slate-800 leading-snug">{alert.message}</p>
                       </div>
                    </div>
                 ))}
                 {opsAlerts.length === 0 && (
                   <div className="py-20 text-center space-y-4 opacity-30">
                      <CheckCircle2 size={48} className="mx-auto text-emerald-500" />
                      <p className="text-[10px] font-black uppercase tracking-widest">Board Clear for Today</p>
                   </div>
                 )}
              </div>
           </div>

           <div className="bg-blue-600 p-8 rounded-[48px] text-white shadow-2xl space-y-8">
              <h3 className="text-xs font-black uppercase tracking-widest text-blue-200">System Logs</h3>
              <div className="space-y-6">
                 <div className="flex gap-4">
                    <div className="w-10 h-10 bg-white/20 rounded-xl flex items-center justify-center shrink-0"><Info size={20}/></div>
                    <div className="space-y-1">
                       <p className="text-[11px] font-bold leading-snug">Operations data matches current bookings and itineraries as of this moment.</p>
                       <p className="text-[9px] text-blue-200 uppercase font-black">Live Data Notice</p>
                    </div>
                 </div>
                 <button 
                   onClick={() => window.print()}
                   className="w-full py-4 bg-white text-blue-600 rounded-2xl font-black uppercase tracking-widest text-[10px] active:scale-95 transition-all flex items-center justify-center gap-2"
                 >
                    Print Manifest for {selectedDate}
                 </button>
              </div>
           </div>
        </div>
      </div>

      {/* Trip Detail Modal (Full Detail View) */}
      {viewingTrip && (
        <div className="fixed inset-0 bg-slate-950/80 backdrop-blur-xl z-[150] flex items-center justify-center p-6 animate-in fade-in duration-300">
           <div className="bg-white rounded-[48px] shadow-2xl w-full max-w-6xl max-h-[90vh] overflow-hidden flex flex-col animate-in zoom-in-95 duration-300">
              <div className="bg-slate-900 p-8 flex items-center justify-between text-white shrink-0">
                 <div className="flex items-center gap-6">
                    <div className="bg-blue-600 p-4 rounded-3xl shadow-xl">
                       <User size={32} />
                    </div>
                    <div>
                       <h2 className="text-3xl font-black tracking-tight">{viewingTrip.client.name}</h2>
                       <div className="flex items-center gap-4 mt-1">
                          <span className="text-[10px] font-black uppercase tracking-widest text-blue-400">{viewingTrip.tripName}</span>
                          <span className="w-1 h-1 bg-slate-700 rounded-full" />
                          <span className="text-[10px] font-black uppercase tracking-widest text-slate-500">{viewingTrip.startDate} — {viewingTrip.endDate}</span>
                       </div>
                    </div>
                 </div>
                 <div className="flex items-center gap-4">
                    <button 
                      onClick={() => navigate(`/trips/${viewingTrip.id}/print`)}
                      className="flex items-center gap-2 px-6 py-3 bg-white/10 hover:bg-white/20 rounded-2xl text-xs font-black uppercase tracking-widest transition-all"
                    >
                       <ExternalLink size={16}/> Proposal View
                    </button>
                    <button 
                      onClick={() => setViewingTrip(null)}
                      className="p-3 hover:bg-white/10 rounded-full text-slate-500 hover:text-white transition-all"
                    >
                       <X size={32} />
                    </button>
                 </div>
              </div>

              <div className="flex-1 overflow-y-auto p-10 space-y-12 bg-slate-50/50">
                 <div className="grid grid-cols-1 md:grid-cols-4 gap-8">
                    <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm space-y-2">
                       <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Client Contact</p>
                       <p className="font-bold text-slate-900 flex items-center gap-2"><Phone size={14} className="text-blue-500"/> {viewingTrip.client.phone}</p>
                       <p className="text-xs text-slate-500 truncate">{viewingTrip.client.email}</p>
                    </div>
                    <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm space-y-2">
                       <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Group Config</p>
                       <p className="font-bold text-slate-900 flex items-center gap-2"><Users size={14} className="text-emerald-500"/> {viewingTrip.pax} Guests</p>
                       <p className="text-xs text-slate-500">{viewingTrip.numRooms || 1} Rooms / {viewingTrip.extraBeds || 0} Extra Beds</p>
                    </div>
                    <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm space-y-2">
                       <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Package Tier</p>
                       <p className="font-bold text-slate-900 flex items-center gap-2"><ShieldCheck size={14} className="text-blue-500"/> {viewingTrip.tripType}</p>
                       <p className="text-xs text-emerald-600 font-bold uppercase">{viewingTrip.status}</p>
                    </div>
                    <div className="bg-white p-6 rounded-3xl border border-slate-100 shadow-sm space-y-2">
                       <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Operations Hub</p>
                       <p className="font-bold text-slate-900 flex items-center gap-2"><MapIcon size={14} className="text-amber-500"/> {viewingTrip.startLocation} Office</p>
                       <p className="text-xs text-slate-500">Agent: {viewingTrip.assignedSalesperson}</p>
                    </div>
                 </div>

                 <div className="space-y-6">
                    <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.3em] flex items-center gap-2">
                       <Compass size={14} className="text-blue-600" /> Complete Trip Manifest
                    </h4>
                    <div className="space-y-4">
                       {viewingTrip.itinerary.map((day, idx) => {
                          const hotel = HOTELS.find(h => h.id === day.hotelId);
                          const vehicle = VEHICLES.find(v => v.id === day.vehicleId);
                          const isTargetDay = getDayInfo(viewingTrip, selectedDate).currentDay === day.dayNumber;

                          return (
                            <div key={day.id} className={`p-8 rounded-[40px] border transition-all flex flex-col md:flex-row gap-8 ${isTargetDay ? 'bg-blue-600 border-blue-500 text-white shadow-2xl scale-[1.02]' : 'bg-white border-slate-100 shadow-sm'}`}>
                               <div className="w-32 shrink-0 space-y-1">
                                  <p className={`text-[10px] font-black uppercase tracking-widest ${isTargetDay ? 'text-blue-200' : 'text-blue-600'}`}>Day {day.dayNumber}</p>
                                  <p className="text-xl font-black tracking-tight">{new Date(new Date(viewingTrip.startDate).getTime() + (idx * 24 * 60 * 60 * 1000)).toLocaleDateString('en-IN', { day: 'numeric', month: 'short' })}</p>
                                  {isTargetDay && <span className="inline-block px-2 py-0.5 bg-white/20 rounded-full text-[8px] font-black uppercase tracking-widest">Selected Date</span>}
                               </div>

                               <div className="flex-1 space-y-4">
                                  <h5 className="text-lg font-black tracking-tight uppercase">{day.title}</h5>
                                  <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                                     <div className={`p-4 rounded-2xl flex items-center gap-4 ${isTargetDay ? 'bg-white/10 border border-white/20' : 'bg-slate-50 border border-slate-100'}`}>
                                        <Hotel size={20} className={isTargetDay ? 'text-white' : 'text-amber-500'} />
                                        <div>
                                           <p className={`text-[9px] font-black uppercase ${isTargetDay ? 'text-blue-200' : 'text-slate-400'}`}>Accommodation</p>
                                           <p className="text-sm font-bold truncate max-w-[150px]">{hotel?.name || 'Check-out / Transit'}</p>
                                        </div>
                                     </div>
                                     <div className={`p-4 rounded-2xl flex items-center gap-4 ${isTargetDay ? 'bg-white/10 border border-white/20' : 'bg-slate-50 border border-slate-100'}`}>
                                        <Car size={20} className={isTargetDay ? 'text-white' : 'text-blue-500'} />
                                        <div>
                                           <p className={`text-[9px] font-black uppercase ${isTargetDay ? 'text-blue-200' : 'text-slate-400'}`}>Transport</p>
                                           <p className="text-sm font-bold">{vehicle?.type || 'Standard Sedan'}</p>
                                        </div>
                                     </div>
                                     <div className={`p-4 rounded-2xl flex items-center gap-4 ${isTargetDay ? 'bg-white/10 border border-white/20' : 'bg-slate-50 border border-slate-100'}`}>
                                        <Utensils size={20} className={isTargetDay ? 'text-white' : 'text-emerald-500'} />
                                        <div>
                                           <p className={`text-[9px] font-black uppercase ${isTargetDay ? 'text-blue-200' : 'text-slate-400'}`}>Meal Plan</p>
                                           <p className="text-sm font-bold">{day.mealPlan || 'Plan Variable'}</p>
                                        </div>
                                     </div>
                                  </div>
                                  {day.activityIds.length > 0 && (
                                     <div className="flex flex-wrap gap-2 pt-2">
                                        {day.activityIds.map(aid => (
                                          <span key={aid} className={`px-3 py-1 rounded-lg text-[9px] font-black uppercase tracking-widest border ${isTargetDay ? 'bg-white/20 border-white/30 text-white' : 'bg-blue-50 border-blue-100 text-blue-700'}`}>
                                             ✓ {ACTIVITIES.find(a => a.id === aid)?.name}
                                          </span>
                                        ))}
                                     </div>
                                  )}
                               </div>
                            </div>
                          );
                       })}
                    </div>
                 </div>
              </div>

              <div className="p-8 bg-slate-50 border-t border-slate-100 flex justify-end gap-4 shrink-0">
                 <button 
                   onClick={() => setViewingTrip(null)}
                   className="px-8 py-4 text-slate-500 font-black uppercase tracking-widest text-[10px] hover:text-slate-900 transition-all"
                 >
                    Close Manifest
                 </button>
                 <button 
                    onClick={() => navigate(`/trips/${viewingTrip.id}`)}
                    className="px-10 py-4 bg-slate-900 text-white rounded-2xl font-black uppercase tracking-widest text-[10px] shadow-xl hover:bg-blue-600 transition-all active:scale-95 flex items-center gap-2"
                 >
                    Open in Itinerary Builder
                 </button>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default OngoingTrips;

import React, { useState, useMemo, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { 
  MapPin, 
  Car, 
  Hotel, 
  Users, 
  AlertCircle, 
  CheckCircle2, 
  Clock, 
  Phone, 
  MessageSquare,
  ChevronRight,
  PlaneLanding,
  PlaneTakeoff,
  RefreshCcw,
  Zap,
  Info,
  Calendar,
  Compass,
  X,
  User,
  ShieldCheck,
  Map as MapIcon,
  IndianRupee,
  Utensils,
  Moon,
  ExternalLink
} from 'lucide-react';
import { MOCK_TRIPS, HOTELS, VEHICLES, ACTIVITIES } from '../constants';
import { Trip, TripStatus, ItineraryDay, OpsAlert } from '../types';

const OngoingTrips: React.FC = () => {
  const navigate = useNavigate();
  const [trips, setTrips] = useState<Trip[]>([]);
  const [selectedDate, setSelectedDate] = useState(new Date().toISOString().split('T')[0]);
  const [viewingTrip, setViewingTrip] = useState<Trip | null>(null);

  useEffect(() => {
    const savedTrips = localStorage.getItem('et_trips');
    setTrips(savedTrips ? JSON.parse(savedTrips) : MOCK_TRIPS);
  }, []);

  const ongoingTrips = useMemo(() => {
    return trips.filter(trip => {
      if (trip.status !== TripStatus.BOOKED) return false;
      return trip.startDate <= selectedDate && trip.endDate >= selectedDate;
    });
  }, [trips, selectedDate]);

  const getDayInfo = (trip: Trip, dateStr: string) => {
    const start = new Date(trip.startDate);
    const targetDate = new Date(dateStr);
    const diffTime = targetDate.getTime() - start.getTime();
    const diffDays = Math.floor(diffTime / (1000 * 60 * 60 * 24)) + 1;

    const todayItinerary = trip.itinerary.find(d => d.dayNumber === diffDays);
    const yesterdayItinerary = trip.itinerary.find(d => d.dayNumber === diffDays - 1);

    return {
      currentDay: diffDays,
      totalDays: trip.itinerary.length,
      todayPlan: todayItinerary,
      yesterdayPlan: yesterdayItinerary
    };
  };

  const opsAlerts = useMemo(() => {
    const alerts: OpsAlert[] = [];
    ongoingTrips.forEach(trip => {
      const { currentDay, totalDays, todayPlan, yesterdayPlan } = getDayInfo(trip, selectedDate);

      if (currentDay === 1) {
        alerts.push({
          id: `arr-${trip.id}`,
          tripId: trip.id,
          clientName: trip.client.name,
          type: 'ARRIVAL',
          message: `Arrival today in ${trip.startLocation}. Coordinate pickup.`,
          severity: 'CRITICAL',
          timestamp: new Date().toISOString()
        });
      }

      if (currentDay === totalDays) {
        alerts.push({
          id: `dep-${trip.id}`,
          tripId: trip.id,
          clientName: trip.client.name,
          type: 'DEPARTURE',
          message: `Departure today. Drop-off at ${trip.startLocation} Airport/Station.`,
          severity: 'CRITICAL',
          timestamp: new Date().toISOString()
        });
      }

      if (todayPlan && yesterdayPlan && todayPlan.hotelId !== yesterdayPlan.hotelId && todayPlan.hotelId) {
        alerts.push({
          id: `move-${trip.id}`,
          tripId: trip.id,
          clientName: trip.client.name,
          type: 'HOTEL_CHANGE',
          message: `Moving from ${yesterdayPlan.location || 'Previous'} to ${todayPlan.location || 'Current'} today.`,
          severity: 'WARNING',
          timestamp: new Date().toISOString()
        });
      }
    });
    return alerts;
  }, [ongoingTrips, selectedDate]);

  const StatCard = ({ label, value, icon: Icon, color }: any) => (
    <div className="bg-white p-6 rounded-[32px] border border-slate-200 shadow-sm flex items-center gap-5">
      <div className={`${color} p-4 rounded-2xl text-white shadow-lg`}>
        <Icon size={24} />
      </div>
      <div>
        <p className="text-slate-500 text-[10px] font-black uppercase tracking-widest">{label}</p>
        <p className="text-2xl font-black text-slate-900">{value}</p>
      </div>
    </div>
  );

  const displayDate = new Date(selectedDate).toLocaleDateString('en-IN', { day: 'numeric', month: 'long', year: 'numeric' });

  return (
    <div className="space-y-8 pb-20">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-black text-slate-900 tracking-tight flex items-center gap-3">
             <div className="w-3 h-3 bg-emerald-500 rounded-full animate-pulse" /> Live Operations Hub
          </h1>
          <p className="text-slate-600 text-sm">Operational tracking for <span className="font-bold text-slate-800">{displayDate}</span>.</p>
        </div>
        <div className="flex items-center gap-3">
          <div className="px-4 py-2 bg-slate-900 text-white rounded-xl text-[10px] font-black uppercase tracking-widest flex items-center gap-2 relative overflow-hidden group border border-slate-800">
            <Calendar size={14} className="text-blue-400" />
            <input 
              type="date" 
              className="bg-transparent border-none outline-none cursor-pointer uppercase font-black"
              value={selectedDate}
              onChange={(e) => setSelectedDate(e.target.value)}
            />
          </div>
          <button 
            onClick={() => setSelectedDate(new Date().toISOString().split('T')[0])}
