import React, { useState, useMemo, useEffect, useRef } from 'react';
import { 
  Plus, 
  Search, 
  Calendar, 
  ArrowUpRight, 
  ArrowDownRight, 
  Filter, 
  IndianRupee, 
  Clock, 
  User, 
  Tag, 
  X, 
  Check, 
  ChevronRight,
  Printer,
  Download,
  MoreVertical,
  Trash2,
  Wallet,
  Briefcase,
  History,
  AlertCircle,
  FileText,
  Paperclip,
  ImageIcon,
  Eye,
  Building2,
  Hash,
  Map as MapIcon
} from 'lucide-react';
import { Transaction, TransactionType, Trip } from '../types';
import { MOCK_TRIPS } from '../constants';

const TRANSACTION_CATEGORIES = {
  INCOME: ['Client Advance', 'Final Payment', 'Misc Revenue', 'Incentive', 'Refund Recieved'],
  EXPENSE: ['Hotel Payout', 'Driver Payment', 'Activity Booking', 'Office Rent', 'Electricity', 'Internet', 'Marketing', 'Salary', 'Stationery', 'Tea/Meals', 'Fuel Cost', 'Misc Expense']
};

const DayBook: React.FC = () => {
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [allTrips, setAllTrips] = useState<Trip[]>([]);
  const [selectedDate, setSelectedDate] = useState(new Date().toISOString().split('T')[0]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const receiptInputRef = useRef<HTMLInputElement>(null);

  const [formData, setFormData] = useState<Partial<Transaction>>({
    type: 'INCOME',
    category: 'Client Advance',
    amount: 0,
    description: '',
    paymentMode: 'Bank Transfer',
    vendorName: '',
    billNumber: '',
    taxAmount: 0,
    tripReference: '',
    receiptData: '',
    receiptName: ''
  });

  useEffect(() => {
    const saved = localStorage.getItem('et_daybook');
    if (saved) setTransactions(JSON.parse(saved));

    const savedTrips = localStorage.getItem('et_trips');
    setAllTrips(savedTrips ? JSON.parse(savedTrips) : MOCK_TRIPS);
  }, []);

  const saveTransactions = (updated: Transaction[]) => {
    setTransactions(updated);
    localStorage.setItem('et_daybook', JSON.stringify(updated));
  };

  const filteredTransactions = useMemo(() => {
    return transactions.filter(t => {
      const isSameDate = t.date === selectedDate;
      const searchLower = searchTerm.toLowerCase();
      const matchesSearch = t.description.toLowerCase().includes(searchLower) || 
                           t.category.toLowerCase().includes(searchLower) ||
                           t.vendorName?.toLowerCase().includes(searchLower) ||
                           t.billNumber?.toLowerCase().includes(searchLower) ||
                           t.tripReference?.toLowerCase().includes(searchLower) ||
                           t.author.toLowerCase().includes(searchLower);
      return isSameDate && matchesSearch;
    }).sort((a, b) => b.id.localeCompare(a.id));
  }, [transactions, selectedDate, searchTerm]);

  const summary = useMemo(() => {
    const daily = transactions.filter(t => t.date === selectedDate);
    const income = daily.filter(t => t.type === 'INCOME').reduce((acc, t) => acc + t.amount, 0);
    const expense = daily.filter(t => t.type === 'EXPENSE').reduce((acc, t) => acc + t.amount, 0);
    return { income, expense, balance: income - expense };
  }, [transactions, selectedDate]);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setFormData(prev => ({
          ...prev,
          receiptData: reader.result as string,
          receiptName: file.name
        }));
      };
      reader.readAsDataURL(file);
    }
  };

  const handleAddTransaction = (e: React.FormEvent) => {
    e.preventDefault();
    const newTx: Transaction = {
      id: `tx-${Date.now()}`,
      date: selectedDate,
      author: 'Adil Bakshi',
      type: formData.type as TransactionType,
      category: formData.category || 'Misc',
      amount: formData.amount || 0,
      description: formData.description || '',
      paymentMode: formData.paymentMode as any || 'Cash',
      vendorName: formData.vendorName,
      billNumber: formData.billNumber,
      taxAmount: formData.taxAmount,
      tripReference: formData.tripReference,
      receiptData: formData.receiptData,
      receiptName: formData.receiptName
    };

    saveTransactions([...transactions, newTx]);
    setIsModalOpen(false);
    resetForm();
  };

  const resetForm = () => {
    setFormData({
      type: 'INCOME',
      category: 'Client Advance',
      amount: 0,
      description: '',
      paymentMode: 'Bank Transfer',
      vendorName: '',
      billNumber: '',
      taxAmount: 0,
      tripReference: '',
      receiptData: '',
      receiptName: ''
    });
  };

  const deleteTransaction = (id: string) => {
    if (window.confirm("Permanently remove this ledger entry?")) {
      saveTransactions(transactions.filter(t => t.id !== id));
    }
  };

  const viewReceipt = (tx: Transaction) => {
    if (!tx.receiptData) return;
    const win = window.open();
    if (win) {
      win.document.write(`<iframe src="${tx.receiptData}" frameborder="0" style="border:0; top:0px; left:0px; bottom:0px; right:0px; width:100%; height:100%;" allowfullscreen></iframe>`);
    }
  };

  const displayDate = new Date(selectedDate).toLocaleDateString('en-IN', { day: 'numeric', month: 'long', year: 'numeric' });

  return (
    <div className="space-y-8 pb-20 animate-in fade-in duration-500">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
        <div>
          <h1 className="text-3xl font-black text-slate-900 tracking-tight flex items-center gap-3">
             <div className="w-3 h-8 bg-blue-600 rounded-full" /> Finance Day Book
          </h1>
          <p className="text-slate-500 text-sm mt-1">Internal accounting for daily cash movement, vendor bills, and receipt management.</p>
        </div>
        <div className="flex items-center gap-4">
          <div className="bg-white border border-slate-200 rounded-2xl p-2 flex items-center gap-3 shadow-sm">
            <Calendar size={18} className="text-blue-600 ml-2" />
            <input 
              type="date" 
              className="bg-transparent font-black text-xs uppercase tracking-widest outline-none border-none cursor-pointer"
              value={selectedDate}
              onChange={(e) => setSelectedDate(e.target.value)}
            />
          </div>
          <button 
            onClick={() => setIsModalOpen(true)}
            className="bg-slate-950 text-white px-8 py-3.5 rounded-2xl font-black uppercase tracking-[0.2em] text-[10px] flex items-center gap-3 hover:bg-blue-600 shadow-2xl transition-all active:scale-95"
          >
            <Plus size={18} /> New Ledger Entry
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-emerald-600 p-8 rounded-[40px] text-white shadow-xl shadow-emerald-500/10 relative overflow-hidden group">
           <div className="absolute top-0 right-0 p-8 opacity-10 group-hover:scale-110 transition-transform">
              <ArrowUpRight size={80} />
           </div>
           <p className="text-[10px] font-black uppercase tracking-[0.2em] text-emerald-100">Today's Total Incoming</p>
           <h3 className="text-4xl font-black mt-2">₹{summary.income.toLocaleString()}</h3>
           <div className="mt-4 flex items-center gap-2">
              <div className="w-1.5 h-1.5 bg-white rounded-full animate-pulse" />
              <span className="text-[9px] font-black uppercase tracking-widest">Revenue Hub</span>
           </div>
        </div>

        <div className="bg-rose-600 p-8 rounded-[40px] text-white shadow-xl shadow-rose-500/10 relative overflow-hidden group">
           <div className="absolute top-0 right-0 p-8 opacity-10 group-hover:scale-110 transition-transform">
              <ArrowDownRight size={80} />
           </div>
           <p className="text-[10px] font-black uppercase tracking-[0.2em] text-rose-100">Today's Operational Outgo</p>
           <h3 className="text-4xl font-black mt-2">₹{summary.expense.toLocaleString()}</h3>
           <div className="mt-4 flex items-center gap-2">
              <div className="w-1.5 h-1.5 bg-white rounded-full" />
              <span className="text-[9px] font-black uppercase tracking-widest">Liability Control</span>
           </div>
        </div>

        <div className="bg-slate-950 p-8 rounded-[40px] text-white shadow-xl shadow-slate-950/20 relative overflow-hidden group border border-slate-800">
           <div className="absolute top-0 right-0 p-8 opacity-10 group-hover:scale-110 transition-transform">
              <IndianRupee size={80} />
           </div>
           <p className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-500">Daily Reconciliation</p>
           <h3 className={`text-4xl font-black mt-2 ${summary.balance < 0 ? 'text-rose-400' : 'text-emerald-400'}`}>
              ₹{summary.balance.toLocaleString()}
           </h3>
           <div className="mt-4 flex items-center gap-2">
              <div className={`w-1.5 h-1.5 rounded-full ${summary.balance < 0 ? 'bg-rose-400' : 'bg-emerald-400'}`} />
              <span className="text-[9px] font-black uppercase tracking-widest">{summary.balance < 0 ? 'Net Cash Deficit' : 'Net Cash Surplus'}</span>
           </div>
        </div>
      </div>

      <div className="grid grid-cols-12 gap-8">
        <div className="col-span-12 xl:col-span-8 space-y-6">
           <div className="bg-white p-5 rounded-[32px] border border-slate-200 shadow-sm flex items-center gap-6">
              <div className="flex-1 relative">
                 <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300" size={18} />
                 <input 
                   type="text" 
                   placeholder="Search by Bill #, Vendor, Trip, Category or Description..." 
                   className="w-full pl-12 pr-4 py-3.5 bg-slate-50 border border-slate-100 rounded-2xl text-sm font-bold outline-none focus:ring-4 focus:ring-blue-50/50 transition-all text-slate-900"
                   value={searchTerm}
                   onChange={(e) => setSearchTerm(e.target.value)}
                 />
              </div>
              <button className="p-4 bg-slate-50 text-slate-400 rounded-2xl hover:bg-slate-100 transition-all"><Filter size={20}/></button>
           </div>

           <div className="bg-white rounded-[40px] border border-slate-200 shadow-sm overflow-hidden">
              <div className="p-8 border-b border-slate-50 flex items-center justify-between bg-slate-50/30">
                 <h3 className="text-xs font-black uppercase tracking-[0.3em] text-slate-400">Day Manifest: {displayDate}</h3>
                 <div className="flex items-center gap-3">
                    <button onClick={() => window.print()} className="p-2 text-slate-400 hover:text-blue-600 transition-colors"><Printer size={18}/></button>
                    <button className="p-2 text-slate-400 hover:text-blue-600 transition-colors"><Download size={18}/></button>
                 </div>
              </div>

              <div className="overflow-x-auto">
                 <table className="w-full text-left border-collapse">
                    <thead>
                       <tr className="text-[10px] font-black uppercase text-slate-400 tracking-[0.2em] border-b border-slate-50">
                          <th className="px-8 py-5">Context/Ref</th>
                          <th className="px-8 py-5">Allocation</th>
                          <th className="px-8 py-5">Bill Details</th>
                          <th className="px-8 py-5 text-right">Amount (Gross)</th>
                          <th className="px-8 py-5 w-10"></th>
                       </tr>
                    </thead>
                    <tbody className="divide-y divide-slate-50">
                       {filteredTransactions.map(tx => (
                          <tr key={tx.id} className="group hover:bg-slate-50/50 transition-all">
                             <td className="px-8 py-6">
                                <div className="space-y-1.5">
                                   <div className="flex items-center gap-2 text-[10px] font-black text-slate-400 uppercase">
                                      <Clock size={12} /> {new Date(parseInt(tx.id.split('-')[1])).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                                   </div>
                                   {tx.tripReference && (
                                     <div className="flex items-center gap-1.5 text-[9px] font-black text-blue-600 bg-blue-50 px-2 py-0.5 rounded-full w-fit uppercase tracking-tighter">
                                        <MapIcon size={10} /> {tx.tripReference}
                                     </div>
                                   )}
                                   <div className="text-[8px] font-bold text-slate-300 uppercase tracking-tighter">Entry ID: {tx.id.slice(-6)}</div>
                                </div>
                             </td>
                             <td className="px-8 py-6">
                                <div className="flex items-center gap-3">
                                   <div className={`p-2.5 rounded-xl ${tx.type === 'INCOME' ? 'bg-emerald-50 text-emerald-600' : 'bg-rose-50 text-rose-600'}`}>
                                      {tx.type === 'INCOME' ? <ArrowUpRight size={16}/> : <ArrowDownRight size={16}/>}
                                   </div>
                                   <div>
                                      <p className="font-black text-slate-900 text-sm tracking-tight">{tx.category}</p>
                                      <p className="text-[9px] font-black text-slate-400 uppercase tracking-widest">{tx.paymentMode}</p>
                                   </div>
                                </div>
                             </td>
                             <td className="px-8 py-6">
                                <div className="space-y-1">
                                  {tx.vendorName && <p className="text-xs font-black text-slate-900 flex items-center gap-1.5"><Building2 size={12} className="text-slate-400"/> {tx.vendorName}</p>}
                                  {tx.billNumber && <p className="text-[10px] font-bold text-slate-500 uppercase tracking-widest flex items-center gap-1.5"><Hash size={10}/> Bill: {tx.billNumber}</p>}
                                  <p className="text-[11px] font-bold text-slate-400 leading-snug line-clamp-1 italic">"{tx.description || 'N/A'}"</p>
                                  {tx.receiptData && (
                                    <button 
                                      onClick={() => viewReceipt(tx)}
                                      className="mt-2 flex items-center gap-1.5 text-[9px] font-black text-blue-600 uppercase tracking-widest hover:underline"
                                    >
                                      <Paperclip size={10}/> View Receipt Attached
                                    </button>
                                  )}
                                </div>
                             </td>
                             <td className="px-8 py-6 text-right">
                                <div className={`text-xl font-black tracking-tighter ${tx.type === 'INCOME' ? 'text-emerald-600' : 'text-rose-600'}`}>
                                   {tx.type === 'INCOME' ? '+' : '-'} ₹{tx.amount.toLocaleString()}
                                </div>
                                {tx.taxAmount && tx.taxAmount > 0 && (
                                  <p className="text-[9px] font-bold text-slate-400 uppercase tracking-widest">Incl. ₹{tx.taxAmount.toLocaleString()} Tax</p>
                                )}
                             </td>
                             <td className="px-8 py-6">
                                <div className="flex items-center gap-1">
                                  <button 
                                    onClick={() => deleteTransaction(tx.id)}
