import React, { useState, useMemo, useEffect, useRef } from 'react';
import { 
  Plus, 
  Search, 
  Calendar, 
  ArrowUpRight, 
  ArrowDownRight, 
  Filter, 
  IndianRupee, 
  Clock, 
  User, 
  Tag, 
  X, 
  Check, 
  ChevronRight,
  Printer,
  Download,
  MoreVertical,
  Trash2,
  Wallet,
  Briefcase,
  History,
  AlertCircle,
  FileText,
  Paperclip,
  ImageIcon,
  Eye,
  Building2,
  Hash,
  Map as MapIcon,
  Edit3,
  Loader2,
  ExternalLink,
  ShieldCheck
} from 'lucide-react';
import { Transaction, TransactionType, Trip } from '../types';
import { MOCK_TRIPS, BRAND_CONFIG } from '../constants';

const TRANSACTION_CATEGORIES = {
  INCOME: ['Client Advance', 'Final Payment', 'Misc Revenue', 'Incentive', 'Refund Recieved'],
  EXPENSE: ['Hotel Payout', 'Driver Payment', 'Activity Booking', 'Office Rent', 'Electricity', 'Internet', 'Marketing', 'Salary', 'Stationery', 'Tea/Meals', 'Fuel Cost', 'Misc Expense']
};

const DayBook: React.FC = () => {
  const [transactions, setTransactions] = useState<Transaction[]>([]);
  const [allTrips, setAllTrips] = useState<Trip[]>([]);
  const [selectedDate, setSelectedDate] = useState(new Date().toISOString().split('T')[0]);
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);
  const [viewingTx, setViewingTx] = useState<Transaction | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const receiptInputRef = useRef<HTMLInputElement>(null);
  const manifestRef = useRef<HTMLDivElement>(null);

  const [formData, setFormData] = useState<Partial<Transaction>>({
    type: 'INCOME',
    category: 'Client Advance',
    amount: 0,
    description: '',
    paymentMode: 'Bank Transfer',
    vendorName: '',
    billNumber: '',
    taxAmount: 0,
    tripReference: '',
    receiptData: '',
    receiptName: ''
  });

  useEffect(() => {
    const saved = localStorage.getItem('et_daybook');
    if (saved) setTransactions(JSON.parse(saved));

    const savedTrips = localStorage.getItem('et_trips');
    setAllTrips(savedTrips ? JSON.parse(savedTrips) : MOCK_TRIPS);
  }, []);

  const saveTransactions = (updated: Transaction[]) => {
    setTransactions(updated);
    localStorage.setItem('et_daybook', JSON.stringify(updated));
  };

  const filteredTransactions = useMemo(() => {
    return transactions.filter(t => {
      const isSameDate = t.date === selectedDate;
      const searchLower = searchTerm.toLowerCase();
      const matchesSearch = t.description.toLowerCase().includes(searchLower) || 
                           t.category.toLowerCase().includes(searchLower) ||
                           t.vendorName?.toLowerCase().includes(searchLower) ||
                           t.billNumber?.toLowerCase().includes(searchLower) ||
                           t.tripReference?.toLowerCase().includes(searchLower) ||
                           t.author.toLowerCase().includes(searchLower);
      return isSameDate && matchesSearch;
    }).sort((a, b) => b.id.localeCompare(a.id));
  }, [transactions, selectedDate, searchTerm]);

  const summary = useMemo(() => {
    const daily = transactions.filter(t => t.date === selectedDate);
    const income = daily.filter(t => t.type === 'INCOME').reduce((acc, t) => acc + t.amount, 0);
    const expense = daily.filter(t => t.type === 'EXPENSE').reduce((acc, t) => acc + t.amount, 0);
    return { income, expense, balance: income - expense };
  }, [transactions, selectedDate]);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setFormData(prev => ({
          ...prev,
          receiptData: reader.result as string,
          receiptName: file.name
        }));
      };
      reader.readAsDataURL(file);
    }
  };

  const openAddModal = () => {
    setEditingId(null);
    resetForm();
    setIsModalOpen(true);
  };

  const openEditModal = (tx: Transaction) => {
    setEditingId(tx.id);
    setFormData({ ...tx });
    setIsModalOpen(true);
  };

  const handleSaveTransaction = (e: React.FormEvent) => {
    e.preventDefault();
    const txData: Transaction = {
      ...formData,
      id: editingId || `tx-${Date.now()}`,
      date: selectedDate,
      author: formData.author || 'Adil Bakshi',
      type: formData.type as TransactionType,
      category: formData.category || 'Misc',
      amount: formData.amount || 0,
      description: formData.description || '',
      paymentMode: formData.paymentMode as any || 'Cash',
    } as Transaction;

    let updated: Transaction[];
    if (editingId) {
      updated = transactions.map(t => t.id === editingId ? txData : t);
    } else {
      updated = [...transactions, txData];
    }

    saveTransactions(updated);
    setIsModalOpen(false);
    setEditingId(null);
    resetForm();
  };

  const resetForm = () => {
    setFormData({
      type: 'INCOME',
      category: 'Client Advance',
      amount: 0,
      description: '',
      paymentMode: 'Bank Transfer',
      vendorName: '',
      billNumber: '',
      taxAmount: 0,
      tripReference: '',
      receiptData: '',
      receiptName: ''
    });
  };

  const deleteTransaction = (id: string) => {
    if (window.confirm("Permanently remove this ledger entry?")) {
      saveTransactions(transactions.filter(t => t.id !== id));
    }
  };

  const downloadManifestPDF = async () => {
    if (filteredTransactions.length === 0) return;
    setIsProcessing(true);
    try {
      const element = manifestRef.current;
      const opt = {
        margin: 10,
        filename: `EscapeTheory_DayBook_${selectedDate}.pdf`,
        image: { type: 'jpeg', quality: 0.98 },
        html2canvas: { scale: 2 },
        jsPDF: { unit: 'mm', format: 'a4', orientation: 'landscape' }
      };
      await (window as any).html2pdf().from(element).set(opt).save();
    } catch (err) {
      console.error(err);
    } finally {
      setIsProcessing(false);
    }
  };

  const printManifest = () => {
    window.print();
  };

  const displayDate = new Date(selectedDate).toLocaleDateString('en-IN', { day: 'numeric', month: 'long', year: 'numeric' });

  return (
    <div className="space-y-8 pb-20 animate-in fade-in duration-500">
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-6 no-print">
        <div>
          <h1 className="text-3xl font-black text-slate-900 tracking-tight flex items-center gap-3">
             <div className="w-3 h-8 bg-blue-600 rounded-full" /> Finance Day Book
          </h1>
          <p className="text-slate-500 text-sm mt-1">Internal accounting for daily cash movement, vendor bills, and receipt management.</p>
        </div>
        <div className="flex items-center gap-4">
          {/* High Contrast Calendar Container */}
          <div className="bg-slate-950 border border-slate-800 rounded-2xl p-3 flex items-center gap-3 shadow-2xl transition-all hover:bg-black group">
            <Calendar size={18} className="text-blue-400 group-hover:scale-110 transition-transform" />
            <input 
              type="date" 
              className="bg-transparent font-black text-xs uppercase tracking-[0.15em] outline-none border-none cursor-pointer text-white appearance-none"
              style={{ colorScheme: 'dark' }}
              value={selectedDate}
              onChange={(e) => setSelectedDate(e.target.value)}
            />
          </div>
          <button 
            onClick={openAddModal}
            className="bg-blue-600 text-white px-8 py-3.5 rounded-2xl font-black uppercase tracking-[0.2em] text-[10px] flex items-center gap-3 hover:bg-blue-700 shadow-2xl transition-all active:scale-95"
          >
            <Plus size={18} /> New Ledger Entry
          </button>
        </div>
      </div>

