                      title="Download PDF"
                    >
                      {isProcessing ? <Loader2 size={18} className="animate-spin" /> : <Download size={18}/>} PDF
                    </button>
                 </div>
              </div>

              <div className="overflow-x-auto">
                 <table className="w-full text-left border-collapse">
