                             <p className="text-[13px] font-bold text-slate-400 leading-snug">{item}</p>
                          </div>
                       ))}
                    </div>
                 </div>
              </div>

              <div className="space-y-12 pt-16 border-t border-slate-100">
                 <h3 className="text-3xl font-black tracking-tight text-slate-900 uppercase">Terms <span className="text-blue-600">&</span> Policies</h3>

                 <div className="grid grid-cols-2 gap-12">
                    <div className="space-y-6">
                       <h4 className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-400">Payment Schedule</h4>
                       <ul className="space-y-5">
                          {PAYMENT_TERMS.slice(0, 3).map((term, i) => (
                            <li key={i} className="text-xs font-bold text-slate-600 leading-relaxed flex gap-3">
                               <div className="w-1.5 h-1.5 rounded-full bg-blue-600 mt-1 shrink-0" />
                               {term}
                            </li>
                          ))}
                       </ul>
                    </div>
                    <div className="space-y-6">
                       <h4 className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-400">Cancellation Policy</h4>
                       <div className="p-8 bg-slate-950 text-white rounded-[48px] shadow-2xl relative overflow-hidden">
                          <AlertTriangle className="absolute -top-4 -right-4 opacity-10" size={100} />
                          <p className="text-[11px] font-bold leading-relaxed relative z-10">{CANCELLATION_POLICY[0]}</p>
                       </div>
                    </div>
                 </div>
              </div>
           </div>

           <div className="pt-20 border-t-2 border-slate-100">
              <div className="flex items-end justify-between">
                 <div className="flex flex-col gap-8">
                    <div className="flex items-center gap-5">
                       <div className="bg-slate-900 p-5 rounded-[32px] text-white shadow-2xl">
                          <Mountain size={40} />
                       </div>
                       <div className="flex flex-col">
                          <h4 className="text-4xl font-black tracking-tighter text-slate-900 uppercase leading-none">Escape Theory</h4>
                          <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.4em] mt-2">Crafting Himalayan Memories</p>
                       </div>
                    </div>
                    <div className="flex gap-12">
                       <div className="space-y-1">
                          <p className="text-[9px] font-black text-slate-300 uppercase tracking-widest">Email Assistance</p>
                          <p className="text-sm font-black text-slate-900">{agencyConfig.email}</p>
                       </div>
                       <div className="space-y-1">
                          <p className="text-[9px] font-black text-slate-300 uppercase tracking-widest">Support Line</p>
                          <p className="text-sm font-black text-slate-900">{agencyConfig.phone}</p>
                       </div>
                    </div>
                 </div>
                 <div className="text-right">
                    <span className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-200 block mb-2">Authenticated Proposal</span>
                    <span className="text-2xl font-black text-blue-600 uppercase tracking-widest italic">Kashmir</span>
                 </div>
              </div>
           </div>
        </div>

      </div>
    </div>
  );
};

export default ClientItinerary;
